//! One line per request, on the way out.
//!
//! Loco installs a `TraceLayer` that opens an `http-request` **span** carrying
//! the method, URI and request id. A span is not an event: it decorates the
//! events emitted inside it and records nothing by itself, and `tower-http`'s
//! own completion event is `DEBUG`, which `config/production.yaml` filters out
//! at `info`. So a production deployment logged no record of a request having
//! been served at all — four requests produced seven lines, every one of them
//! either a SQL statement or an error, and none of them saying that a request
//! finished or how long it took.
//!
//! This is the missing line. It is a layer around the whole router rather than
//! anything per-handler, and that placement is the point: a 401 from the JWT
//! extractor, a 403 from `authz`, a 404 for a route that does not exist and a
//! panic caught upstream are all produced *below* this layer, so all of them
//! are seen. The NestJS sibling learned the same thing the hard way — its
//! equivalent is a Fastify `onResponse` hook and never a Nest interceptor,
//! because an interceptor runs after the guards and therefore sees no refusal
//! at all.
//!
//! A 404 for a route the router does not know carries no request id, and that
//! is correct rather than a gap: Loco's id middleware is layered onto the
//! routes, and an unmatched request never reaches them. The line says `none`
//! instead of inventing one, because an id that correlates with nothing is
//! worse than an honest absence.
//!
//! **The query string is deliberately not logged.** `?email=…&status=…` is
//! business data, and the log specification's rule is that a field's value
//! never reaches a log line. The path alone answers what was served; the
//! filters that were applied are the caller's business.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

use std::time::Instant;

use axum::{extract::Request, middleware::Next, response::Response};
use loco_rs::controller::middleware::request_id::LocoRequestId;

/// What a request id is called when the id middleware did not run.
const NO_REQUEST_ID: &str = "none";

/// The header Loco's request-id middleware writes onto the response.
const X_REQUEST_ID: &str = "x-request-id";

/// Emit one catalogued event per request, chosen by the status class.
///
/// Three events rather than one carrying a status field, because they are three
/// different things to whoever reads them: a completion is traffic, a refusal
/// is a client being told no, and a failure is this application breaking. They
/// carry the same fields, so one query can still read all three together.
pub async fn log_request(request: Request, next: Next) -> Response {
    let method = request.method().to_string();
    // `uri().path()`, never `uri()` — see the note above on the query string.
    let path = request.uri().path().to_string();
    // Read on the way in *and* on the way out, because which one carries the id
    // depends on layer order and this layer is deliberately outermost. Loco
    // applies its own middlewares beneath `after_routes`, so its request-id
    // layer inserts the extension below this one — invisible here — and the id
    // only becomes reachable as the `x-request-id` header it puts on the
    // response. Reading the extension first keeps this correct if that order
    // ever reverses, which is exactly when a silently empty id would be hardest
    // to notice.
    let extension_id = request
        .extensions()
        .get::<LocoRequestId>()
        .map(|id| id.get().to_string());

    let started = Instant::now();
    let response = next.run(request).await;

    let request_id = extension_id.unwrap_or_else(|| {
        response
            .headers()
            .get(X_REQUEST_ID)
            .and_then(|value| value.to_str().ok())
            .map_or_else(|| NO_REQUEST_ID.to_string(), ToString::to_string)
    });

    let status = response.status();
    // Converted rather than cast: a request held open for longer than a u64 of
    // milliseconds is not a number anyone needs exactly, and a wrapped one
    // reads as a suspiciously fast request rather than a stuck one.
    let duration_ms = u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX);
    let code = status.as_u16();

    if status.is_server_error() {
        crate::log_event!(
            request_failed,
            method = method,
            path = path,
            status = code,
            durationMs = duration_ms,
            requestId = request_id
        );
    } else if status.is_client_error() {
        crate::log_event!(
            request_refused,
            method = method,
            path = path,
            status = code,
            durationMs = duration_ms,
            requestId = request_id
        );
    } else {
        crate::log_event!(
            request_completed,
            method = method,
            path = path,
            status = code,
            durationMs = duration_ms,
            requestId = request_id
        );
    }

    response
}

//! Rate limiting, keyed by the caller rather than by the address they arrive at.
//!
//! This application had none. A generated backend accepted an unbounded number
//! of password guesses against `/api/auth/login`, and an unbounded number of
//! anything else, from anyone who could reach it.
//!
//! Two decisions here are the whole design, and both are the ones the NestJS
//! sibling got wrong first and had to measure its way out of.
//!
//! **The key is the caller, not the address.** A budget per IP is right for a
//! public service and wrong for this one: its users arrive through a reverse
//! proxy — the compose one, a corporate gateway, an ingress — and to the server
//! every one of them has the same peer address. A per-IP limit stops meaning
//! "how fast may a person go" and starts meaning "how many people may there
//! be", and a department of thirty sharing one gateway hits it while the server
//! is idle. So an authenticated request is counted against the subject of its
//! own token, and only an anonymous one falls back to the address — which is
//! the right key for the routes an anonymous caller can reach, because there is
//! nothing else to count.
//!
//! **The token is read here, not taken from an extractor.** This is a layer
//! around the whole router, so it runs *before* the JWT extractor that
//! populates a handler's `auth::JWT`. Asking for that here would find nothing
//! on every request and silently revert to counting addresses — the limit would
//! look installed and behave as though it were not. The token is therefore
//! pulled from the `Authorization` header or the session cookie and
//! **verified**, not merely parsed: an unverified subject is a bucket a caller
//! can pick, which is not a limit at all.
//!
//! Two budgets, because the two failures are different sizes. The general one
//! bounds a runaway client; a single screen of this application costs several
//! requests, so it is generous. The credential routes get a much tighter one,
//! because the thing being bounded there is guessing, and a rate that is
//! comfortable for a person is already slow for an attacker.
//!
//! The sign-in budget is a floor and not a substitute for per-account lockout,
//! which this application does not have. Counting is per address for an
//! anonymous caller, so without a trusted proxy everyone behind one gateway
//! shares it: a limit tuned for one person locks out a shift change.
//!
//! `/api/me/health` is exempt. It is the readiness probe, it is open by design,
//! and an orchestrator polling it every second must not consume the budget of
//! whoever shares its address.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

use std::{
    collections::HashMap,
    net::SocketAddr,
    sync::{Arc, Mutex},
    time::{Duration, Instant},
};

use axum::{
    extract::{ConnectInfo, Request, State},
    http::{header, HeaderValue, StatusCode},
    middleware::Next,
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::app::AppContext;

use crate::errors::ErrorBody;

/// The window every budget is measured over.
const WINDOW: Duration = Duration::from_secs(60);

/// Requests per window for everything that is not a credential route.
///
/// A single screen costs several requests — the dictionary lists, the rows, the
/// record — so this is deliberately well above what a person produces and still
/// far below what a runaway client does.
const DEFAULT_MAX_PER_MINUTE: u32 = 300;

/// Requests per window for the routes that verify or create a credential.
const DEFAULT_AUTH_MAX_PER_MINUTE: u32 = 30;

/// Buckets held before a sweep is worth the cost.
///
/// An anonymous caller's key is their address, so the map is bounded only by
/// how many addresses reach the server — which is to say, not bounded. The
/// sweep happens under the lock already held, and only when the map has grown
/// past a size no real deployment reaches by legitimate means.
const SWEEP_THRESHOLD: usize = 10_000;

/// What a caller has spent in the current window.
#[derive(Clone, Copy)]
struct Bucket {
    started: Instant,
    count: u32,
}

/// How many requests a key may make per window. `max == 0` disables the limit.
#[derive(Clone, Copy)]
pub struct Budget {
    pub max: u32,
}

impl Budget {
    fn disabled(self) -> bool {
        self.max == 0
    }
}

/// The answer for one request: whether to serve it, and what to tell the caller
/// about their remaining budget either way.
pub struct Decision {
    pub allowed: bool,
    pub limit: u32,
    pub remaining: u32,
    /// Seconds until the current window ends.
    pub reset: u64,
}

/// The two budgets, the buckets, and what is needed to name a caller.
pub struct Limiter {
    buckets: Mutex<HashMap<String, Bucket>>,
    general: Budget,
    auth: Budget,
    /// Whether `X-Forwarded-For` may be believed.
    trust_proxy: bool,
    /// The secret a session token is verified against. Absent means no token
    /// can be verified, so every caller is counted by address.
    jwt_secret: Option<String>,
}

impl Limiter {
    /// Build from the application's configuration.
    ///
    /// The budgets come from the `settings` block, which is where a deployment
    /// can change them without a rebuild, and both fall back to the constants
    /// above. `config/test.yaml` sets them to 0: the generated suites drive
    /// volumes in seconds that no human session produces in an hour, so a
    /// budget there would be testing the limiter rather than the application.
    /// What covers the limiter is `tests/requests/rate_limit.rs`, which layers
    /// this middleware over a router of its own with a budget it sets itself.
    #[must_use]
    pub fn from_context(ctx: &AppContext) -> Self {
        let settings = ctx.config.settings.as_ref();
        let number = |key: &str, fallback: u32| -> u32 {
            settings
                .and_then(|block| block.get(key))
                .and_then(|value| {
                    value
                        .as_u64()
                        .or_else(|| value.as_str().and_then(|text| text.trim().parse().ok()))
                })
                .and_then(|value| u32::try_from(value).ok())
                .unwrap_or(fallback)
        };

        let trust_proxy = settings
            .and_then(|block| block.get("trust_proxy"))
            .is_some_and(|value| match value {
                serde_json::Value::Bool(flag) => *flag,
                serde_json::Value::String(text) => {
                    matches!(text.trim(), "1" | "true" | "yes" | "on")
                }
                serde_json::Value::Number(number) => number.as_u64().is_some_and(|n| n > 0),
                _ => false,
            });

        Self {
            buckets: Mutex::new(HashMap::new()),
            general: Budget {
                max: number("rate_limit_max_per_minute", DEFAULT_MAX_PER_MINUTE),
            },
            auth: Budget {
                max: number("rate_limit_auth_max_per_minute", DEFAULT_AUTH_MAX_PER_MINUTE),
            },
            trust_proxy,
            jwt_secret: ctx
                .config
                .auth
                .as_ref()
                .and_then(|auth| auth.jwt.as_ref())
                .map(|jwt| jwt.secret.clone()),
        }
    }

    /// The budgets and the proxy switch, stated directly. For tests, which need
    /// a budget small enough to cross inside one.
    #[must_use]
    pub fn with_budgets(general: u32, auth: u32) -> Self {
        Self {
            buckets: Mutex::new(HashMap::new()),
            general: Budget { max: general },
            auth: Budget { max: auth },
            trust_proxy: false,
            jwt_secret: None,
        }
    }

    /// Count one request against `key` and say whether it may proceed.
    ///
    /// Pure apart from the map it owns: `now` is a parameter so a test can roll
    /// the window over without sleeping through it.
    fn spend(&self, key: String, budget: Budget, now: Instant) -> Decision {
        if budget.disabled() {
            return Decision {
                allowed: true,
                limit: 0,
                remaining: 0,
                reset: 0,
            };
        }

        let Ok(mut buckets) = self.buckets.lock() else {
            // A poisoned lock means a previous holder panicked while counting.
            // Refusing every request afterwards would turn one panic into an
            // outage; the limit is a bound on abuse, not a correctness
            // guarantee, so the request is served and the bound is lost until
            // the process restarts.
            return Decision {
                allowed: true,
                limit: budget.max,
                remaining: budget.max,
                reset: 0,
            };
        };

        if buckets.len() > SWEEP_THRESHOLD {
            buckets.retain(|_, bucket| now.duration_since(bucket.started) < WINDOW);
        }

        let bucket = buckets.entry(key).or_insert(Bucket {
            started: now,
            count: 0,
        });
        if now.duration_since(bucket.started) >= WINDOW {
            *bucket = Bucket {
                started: now,
                count: 0,
            };
        }

        let elapsed = now.duration_since(bucket.started);
        let reset = WINDOW.saturating_sub(elapsed).as_secs().max(1);

        if bucket.count >= budget.max {
            return Decision {
                allowed: false,
                limit: budget.max,
                remaining: 0,
                reset,
            };
        }

        bucket.count += 1;
        Decision {
            allowed: true,
            limit: budget.max,
            remaining: budget.max - bucket.count,
            reset,
        }
    }

    /// The key this request is counted against.
    ///
    /// A verified token's subject when there is one, the caller's address
    /// otherwise, prefixed apart so a subject that happens to read like an
    /// address cannot land in an address's bucket — and prefixed by the scope,
    /// because two budgets sharing one counter is one budget: exhausting the
    /// credential allowance would close the rest of the application to the same
    /// caller, and thirty ordinary requests would use up the sign-in allowance.
    fn caller(&self, request: &Request, scope: Scope) -> String {
        let prefix = match scope {
            Scope::General => "api",
            Scope::Auth => "auth",
        };
        if let Some(pid) = self.verified_subject(request) {
            return format!("{prefix}:user:{pid}");
        }
        format!("{prefix}:addr:{}", self.address(request))
    }

    /// The subject of the request's session token, if it carries one that this
    /// application signed.
    fn verified_subject(&self, request: &Request) -> Option<String> {
        let secret = self.jwt_secret.as_ref()?;
        let token = bearer_token(request).or_else(|| cookie_token(request))?;
        loco_rs::auth::jwt::JWT::new(secret)
            .validate(&token)
            .ok()
            .map(|data| data.claims.pid)
    }

    /// Where the request came from.
    ///
    /// `X-Forwarded-For` is read only when the deployment has said it sits
    /// behind a proxy it controls. Believing it unconditionally would let a
    /// client hand itself a fresh bucket per request by setting the header,
    /// which turns a sign-in limit into decoration. The **rightmost** value is
    /// taken, because a well-behaved proxy appends the address it saw: anything
    /// to the left of that was supplied by the client.
    fn address(&self, request: &Request) -> String {
        if self.trust_proxy {
            if let Some(forwarded) = request
                .headers()
                .get("x-forwarded-for")
                .and_then(|value| value.to_str().ok())
                .and_then(|value| value.rsplit(',').next())
                .map(str::trim)
                .filter(|value| !value.is_empty())
            {
                return forwarded.to_string();
            }
        }

        request
            .extensions()
            .get::<ConnectInfo<SocketAddr>>()
            .map_or_else(
                || "unknown".to_string(),
                |ConnectInfo(addr)| addr.ip().to_string(),
            )
    }
}

/// Which budget a path is counted against, or none when it is exempt.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Scope {
    General,
    /// The routes that verify or create a credential.
    Auth,
}

/// The readiness probe, which no budget applies to.
const EXEMPT_PATH: &str = "/api/me/health";

/// Paths whose budget is the tight one.
const AUTH_PATHS: [&str; 3] = [
    "/api/auth/login",
    "/api/auth/register",
    "/api/auth/change-password",
];

fn scope_for(path: &str) -> Option<Scope> {
    if path == EXEMPT_PATH {
        return None;
    }
    if AUTH_PATHS.contains(&path) {
        return Some(Scope::Auth);
    }
    Some(Scope::General)
}

fn bearer_token(request: &Request) -> Option<String> {
    request
        .headers()
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "))
        .map(str::trim)
        .filter(|token| !token.is_empty())
        .map(ToString::to_string)
}

fn cookie_token(request: &Request) -> Option<String> {
    request
        .headers()
        .get(header::COOKIE)
        .and_then(|value| value.to_str().ok())?
        .split(';')
        .filter_map(|pair| pair.trim().split_once('='))
        .find(|(name, _)| *name == "token")
        .map(|(_, value)| value.trim().to_string())
        .filter(|token| !token.is_empty())
}

/// Count this request, and either serve it or refuse it with a 429.
///
/// The budget headers go on **both** answers. A client that can see how much it
/// has left can slow down before it is refused; one that only learns at the
/// wall has to discover the limit by hitting it.
pub async fn enforce(
    State(limiter): State<Arc<Limiter>>,
    request: Request,
    next: Next,
) -> Response {
    let Some(scope) = scope_for(request.uri().path()) else {
        return next.run(request).await;
    };

    let budget = match scope {
        Scope::General => limiter.general,
        Scope::Auth => limiter.auth,
    };
    if budget.disabled() {
        return next.run(request).await;
    }

    let decision = limiter.spend(limiter.caller(&request, scope), budget, Instant::now());

    if decision.allowed {
        let mut response = next.run(request).await;
        write_budget_headers(&mut response, &decision, false);
        return response;
    }

    let body = ErrorBody {
        status_code: StatusCode::TOO_MANY_REQUESTS.as_u16(),
        message: "Too many requests. Slow down and try again shortly.".to_string(),
        errors: None,
        error: "Too Many Requests".to_string(),
        conflict: None,
    };
    let mut response = (StatusCode::TOO_MANY_REQUESTS, Json(body)).into_response();
    write_budget_headers(&mut response, &decision, true);
    response
}

/// `RateLimit-*` on every limited response, `Retry-After` only on a refusal —
/// the header means "you were refused, wait this long", and putting it on a
/// served response says the opposite of what happened.
fn write_budget_headers(response: &mut Response, decision: &Decision, refused: bool) {
    let headers = response.headers_mut();
    insert_number(headers, "ratelimit-limit", u64::from(decision.limit));
    insert_number(headers, "ratelimit-remaining", u64::from(decision.remaining));
    insert_number(headers, "ratelimit-reset", decision.reset);
    if refused {
        insert_number(headers, "retry-after", decision.reset);
    }
}

fn insert_number(headers: &mut axum::http::HeaderMap, name: &'static str, value: u64) {
    if let Ok(header_value) = HeaderValue::from_str(&value.to_string()) {
        headers.insert(name, header_value);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn at(base: Instant, seconds: u64) -> Instant {
        base + Duration::from_secs(seconds)
    }

    #[test]
    fn a_caller_is_served_up_to_its_budget_and_refused_after_it() {
        let limiter = Limiter::with_budgets(3, 3);
        let budget = Budget { max: 3 };
        let now = Instant::now();

        for expected_remaining in [2, 1, 0] {
            let decision = limiter.spend("user:a".to_string(), budget, now);
            assert!(decision.allowed);
            assert_eq!(decision.remaining, expected_remaining);
        }

        let refused = limiter.spend("user:a".to_string(), budget, now);
        assert!(!refused.allowed);
        assert_eq!(refused.remaining, 0);
        assert_eq!(refused.limit, 3);
        assert!(refused.reset >= 1);
    }

    #[test]
    fn two_callers_do_not_share_a_bucket() {
        let limiter = Limiter::with_budgets(1, 1);
        let budget = Budget { max: 1 };
        let now = Instant::now();

        assert!(limiter.spend("user:a".to_string(), budget, now).allowed);
        assert!(!limiter.spend("user:a".to_string(), budget, now).allowed);
        // The whole point of keying on the caller: b arrives through the same
        // proxy as a and is unaffected by a's spending.
        assert!(limiter.spend("user:b".to_string(), budget, now).allowed);
    }

    #[test]
    fn the_window_rolls_over() {
        let limiter = Limiter::with_budgets(1, 1);
        let budget = Budget { max: 1 };
        let now = Instant::now();

        assert!(limiter.spend("addr:10.0.0.1".to_string(), budget, now).allowed);
        assert!(!limiter
            .spend("addr:10.0.0.1".to_string(), budget, at(now, 59))
            .allowed);
        assert!(limiter
            .spend("addr:10.0.0.1".to_string(), budget, at(now, 60))
            .allowed);
    }

    #[test]
    fn a_budget_of_zero_is_off_rather_than_refusing_everything() {
        let limiter = Limiter::with_budgets(0, 0);
        let budget = Budget { max: 0 };
        let now = Instant::now();

        for _ in 0..1_000 {
            assert!(limiter.spend("user:a".to_string(), budget, now).allowed);
        }
    }

    #[test]
    fn the_credential_routes_are_scoped_apart_from_everything_else() {
        assert_eq!(scope_for("/api/auth/login"), Some(Scope::Auth));
        assert_eq!(scope_for("/api/auth/register"), Some(Scope::Auth));
        assert_eq!(scope_for("/api/auth/change-password"), Some(Scope::Auth));
        // `/api/auth/me` verifies no credential — it reads the session that a
        // verified one already produced — so it belongs to the general budget.
        assert_eq!(scope_for("/api/auth/me"), Some(Scope::General));
        assert_eq!(scope_for("/api/bus/compound"), Some(Scope::General));
        // The readiness probe is exempt, so an orchestrator polling it cannot
        // exhaust the budget of whoever shares its address.
        assert_eq!(scope_for("/api/me/health"), None);
    }

    #[test]
    fn a_general_and_an_auth_budget_are_counted_separately() {
        let limiter = Limiter::with_budgets(10, 1);
        let now = Instant::now();

        assert!(limiter
            .spend("auth:user:a".to_string(), limiter.auth, now)
            .allowed);
        assert!(!limiter
            .spend("auth:user:a".to_string(), limiter.auth, now)
            .allowed);
        // Exhausting the credential budget must not close the rest of the
        // application to the same caller — which is what the scope prefix in
        // `caller` is for.
        assert!(limiter
            .spend("api:user:a".to_string(), limiter.general, now)
            .allowed);
    }
}

//! Natural-language querying — `POST /api/ai/query` (decision D5).
//!
//! Thin by design: the pipeline lives in `services::nl_query`, and everything
//! interesting about it — that the model returns a validated plan rather than
//! SQL, and that `authz::require_read` gates execution — is documented there.
//!
//! The route is always mounted. Whether it *works* depends on `ai_base_url` and
//! `ai_model` — a `sys_system` row first, the app's `settings` block after it, so
//! the add-on can be turned on from the admin screen without a restart. Without
//! either it answers 503, the
//! same way the Electric proxy does when its upstream is unconfigured. That is
//! deliberate: a conditionally emitted module is the `include_str!` trap in
//! another costume, and the parity gate cannot see a file that both generators
//! agree to omit.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

use axum::{
    extract::State,
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::prelude::*;
use serde::Deserialize;

use crate::errors::{AppError, AppResult};
use crate::models::_entities::users;
use crate::services::authz;
use crate::services::dictionary::DictionaryCache;
use crate::services::dynamic_repo::DynamicRepo;
use crate::services::nl_query::{self, AiSettings};
use crate::services::system_config::SystemConfig;

#[derive(Debug, Deserialize)]
pub struct QueryRequest {
    /// The question, in the user's own words.
    pub query: String,
}

#[utoipa::path(
    post, path = "/api/ai/query", tag = "ai",
    security(("bearer" = [])),
    request_body = inline(Object),
    responses(
        (status = 200, description = "`{ success, data, count, entity, displayHint, summary, plan, executionTimeMs }`. `plan` is the validated query the question was translated into, echoed so the answer can be audited."),
        (status = 400, description = "Empty or over-long question, or a plan naming an unknown entity, column or operator"),
        (status = 401, description = "No or invalid token"),
        (status = 403, description = "The account may not read any entity"),
        (status = 503, description = "The AI add-on is not configured, or the endpoint is unreachable"),
    ),
)]
pub async fn query(
    auth: auth::JWTWithUser<users::Model>,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
    SharedStore(repo): SharedStore<DynamicRepo>,
    SharedStore(config): SharedStore<SystemConfig>,
    Json(body): Json<QueryRequest>,
) -> AppResult<Response> {
    // Before the settings, deliberately. An empty or over-long question is a
    // bad request on any app, and checking configuration first made it a 503 on
    // an unconfigured one — so the same request meant two different things
    // depending on a server setting the caller cannot see. `tests/requests/ai`
    // asserts the ordering.
    let question = nl_query::validate_question(&body.query)?;

    let settings = AiSettings::resolve(&config, ctx.config.settings.as_ref())
        .await
        .ok_or_else(|| {
            AppError::ServiceUnavailable(
                "AI add-on not configured (set ai_base_url and ai_model on the System \
                 Configuration screen, in settings, or as LOCAL_AI_BASE_URL and \
                 LOCAL_AI_MODEL in the environment)"
                    .to_string(),
            )
        })?;

    let pool = ctx.db.get_postgres_connection_pool();
    let principal = authz::principal(pool, &auth.user).await?;

    let answer = nl_query::answer(
        pool,
        &principal,
        &dictionary,
        &repo,
        &settings,
        question,
    )
    .await?;

    Ok(Json(answer).into_response())
}

pub fn routes() -> Routes {
    Routes::new().prefix("ai").add("/query", post(query))
}

//! Audit trail queries and chain verification.

use axum::{
    extract::{Path, Query, State},
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::prelude::*;
use serde_json::json;
use sqlx::AssertSqlSafe;
use std::collections::HashMap;
use uuid::Uuid;

use crate::errors::{AppError, AppResult};
use crate::services::audit::AuditService;

/// `GET /api/audit` — most recent entries first, which is what /admin/audit renders.
///
/// Every filter the audit screen offers is bound as a parameter, and the
/// response is the `{ data, meta }` envelope that screen's pagination reads —
/// it computes its page count from `meta.total` and `meta.limit`, so a bare
/// array leaves it stuck on one page.
#[utoipa::path(
    get, path = "/api/audit", tag = "audit",
    security(("bearer" = [])),
    params(
        ("limit" = Option<i64>, Query, description = "Page size, clamped to 1..=1000 (default 100)"),
        ("page" = Option<i64>, Query, description = "1-based page number"),
        ("offset" = Option<i64>, Query, description = "Row offset; overrides `page` when given"),
        ("entity_type" = Option<String>, Query, description = "Filter to one table, e.g. `bus_compound`"),
        ("entity_id" = Option<String>, Query, description = "Filter to one record"),
        ("action" = Option<String>, Query, description = "`create`, `update` or `delete`"),
        ("user_email" = Option<String>, Query, description = "Filter to one actor"),
        ("source" = Option<String>, Query, description = "Originating subsystem"),
        ("success" = Option<bool>, Query, description = "Only successful or only failed writes"),
        ("search" = Option<String>, Query, description = "Case-insensitive match across entity, actor and action"),
        ("from" = Option<String>, Query, description = "Inclusive lower bound; RFC 3339 or `YYYY-MM-DD`"),
        ("to" = Option<String>, Query, description = "Inclusive upper bound; RFC 3339 or `YYYY-MM-DD`"),
    ),
    responses((status = 200, description = "`{ data, meta }` — entries newest first")),
)]
pub async fn list(
    _auth: auth::JWT,
    Query(params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let limit: i64 = params
        .get("limit")
        .and_then(|v| v.parse().ok())
        .unwrap_or(100)
        .clamp(1, 1000);
    let page: i64 = params
        .get("page")
        .and_then(|v| v.parse().ok())
        .unwrap_or(1)
        .max(1);
    let offset: i64 = params
        .get("offset")
        .and_then(|v| v.parse().ok())
        .unwrap_or((page - 1) * limit)
        .max(0);

    let pool = ctx.db.get_postgres_connection_pool();

    let entity_type = params
        .get("entity_type")
        .or_else(|| params.get("entityType"))
        .filter(|v| !v.is_empty());
    let entity_id = params.get("entity_id").filter(|v| !v.is_empty());
    let action = params.get("action").filter(|v| !v.is_empty());
    let user_email = params.get("user_email").filter(|v| !v.is_empty());
    let source = params.get("source").filter(|v| !v.is_empty());
    let success = params
        .get("success")
        .filter(|v| !v.is_empty())
        .and_then(|v| v.parse::<bool>().ok());
    let search = params
        .get("search")
        .filter(|v| !v.is_empty())
        .map(|v| format!("%{v}%"));
    let from = timestamp(params.get("from"));
    let to = timestamp(params.get("to"));

    // One predicate list, applied to both the page and the count, so the
    // footer's "N of M" cannot disagree with the rows above it.
    const PREDICATES: &str = r"
           WHERE ($1::text        IS NULL OR entity_type = $1)
             AND ($2::text        IS NULL OR entity_id   = $2)
             AND ($3::text        IS NULL OR action      = $3)
             AND ($4::text        IS NULL OR user_email  = $4)
             AND ($5::text        IS NULL OR source      = $5)
             AND ($6::bool        IS NULL OR success     = $6)
             AND ($7::timestamptz IS NULL OR timestamp  >= $7)
             AND ($8::timestamptz IS NULL OR timestamp  <= $8)
             AND ($9::text        IS NULL OR entity_type ILIKE $9
                                          OR entity_id   ILIKE $9
                                          OR user_email  ILIKE $9
                                          OR user_name   ILIKE $9
                                          OR action      ILIKE $9)";

    let total: i64 = sqlx::query_scalar(AssertSqlSafe(format!(
        "SELECT COUNT(*) FROM audit_log{PREDICATES}"
    )))
        .bind(entity_type)
        .bind(entity_id)
        .bind(action)
        .bind(user_email)
        .bind(source)
        .bind(success)
        .bind(from)
        .bind(to)
        .bind(search.as_deref())
        .fetch_one(pool)
        .await?;

    let rows = sqlx::query(AssertSqlSafe(format!(
        "SELECT * FROM audit_log{PREDICATES} ORDER BY timestamp DESC LIMIT $10 OFFSET $11"
    )))
    .bind(entity_type)
    .bind(entity_id)
    .bind(action)
    .bind(user_email)
    .bind(source)
    .bind(success)
    .bind(from)
    .bind(to)
    .bind(search.as_deref())
    .bind(limit)
    .bind(offset)
    .fetch_all(pool)
    .await?;

    Ok(Json(json!({
        "data": crate::services::row_json::rows_to_json(&rows),
        "meta": {
            "total": total,
            "page": page,
            "limit": limit,
            "totalPages": if limit == 0 { 0 } else { (total + limit - 1) / limit },
        }
    }))
    .into_response())
}

/// `GET /api/audit/entity-types` — the distinct values, for the filter dropdown.
///
/// Read from the log rather than from `sys_table` on purpose: the useful list is
/// what has actually been written, not what could be.
#[utoipa::path(
    get, path = "/api/audit/entity-types", tag = "audit",
    security(("bearer" = [])),
    responses((status = 200, description = "The entity types present in the log, sorted")),
)]
pub async fn entity_types(_auth: auth::JWT, State(ctx): State<AppContext>) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let rows: Vec<(String,)> = sqlx::query_as(
        r"SELECT DISTINCT entity_type FROM audit_log
           WHERE entity_type IS NOT NULL AND entity_type <> ''
           ORDER BY entity_type",
    )
    .fetch_all(pool)
    .await?;

    let types: Vec<String> = rows.into_iter().map(|(t,)| t).collect();
    Ok(Json(types).into_response())
}

/// `GET /api/audit/{id}/verify` — recompute one entry's hash in place.
///
/// The chain-wide verify answers "has anything been tampered with"; this one
/// answers "is *this* row still what it was", which is the question the detail
/// dialog asks when an operator is looking at a single suspicious change.
#[utoipa::path(
    get, path = "/api/audit/{id}/verify", tag = "audit",
    security(("bearer" = [])),
    params(("id" = String, Path, description = "The audit entry's UUID")),
    responses(
        (status = 200, description = "Whether this entry still hashes to its stored value"),
        (status = 404, description = "No such entry"),
    ),
)]
pub async fn verify_entry(
    _auth: auth::JWT,
    Path(id): Path<Uuid>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let audit = ctx
        .shared_store
        .get::<AuditService>()
        .ok_or_else(|| AppError::Internal(anyhow::anyhow!("audit service not initialised")))?;
    Ok(Json(audit.verify_entry(id).await?).into_response())
}

/// Parse a filter date, accepting both a full RFC3339 timestamp and the bare
/// `YYYY-MM-DD` a date input produces.
fn timestamp(raw: Option<&String>) -> Option<chrono::DateTime<chrono::Utc>> {
    let raw = raw.map(String::as_str).filter(|v| !v.is_empty())?;
    if let Ok(parsed) = chrono::DateTime::parse_from_rfc3339(raw) {
        return Some(parsed.with_timezone(&chrono::Utc));
    }
    chrono::NaiveDate::parse_from_str(raw, "%Y-%m-%d")
        .ok()
        .and_then(|date| date.and_hms_opt(0, 0, 0))
        .map(|naive| chrono::DateTime::from_naive_utc_and_offset(naive, chrono::Utc))
}

/// `GET /api/audit/verify` — recompute the hash chain end to end.
///
/// This is the replacement for the immudb consistency proof (decision D4).
#[utoipa::path(
    get, path = "/api/audit/verify", tag = "audit",
    security(("bearer" = [])),
    responses((status = 200, description = "Chain verification result, and the first break if there is one")),
)]
pub async fn verify(_auth: auth::JWT, State(ctx): State<AppContext>) -> AppResult<Response> {
    let audit = ctx
        .shared_store
        .get::<AuditService>()
        .ok_or_else(|| AppError::Internal(anyhow::anyhow!("audit service not initialised")))?;
    Ok(Json(audit.verify_chain().await?).into_response())
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("audit")
        .add("/", get(list))
        .add("/verify", get(verify))
        .add("/entity-types", get(entity_types))
        .add("/{id}/verify", get(verify_entry))
}

//! Authentication routes.
//!
//! The one place the API contract deliberately changes (§9, decision D1).
//! Better Auth's `/api/auth/*` catch-all is replaced by explicit handlers over
//! Loco's native JWT.
//!
//! The token is issued **both** as a `Bearer` value in the response body and as
//! an HTTP-only cookie, because the frontend's existing flow is "the session
//! cookie is set, now call `/api/auth/me`". Keeping the cookie means that flow
//! survives with minimal change; the bearer token is there for API clients.

use axum::{
    extract::State,
    http::{header::SET_COOKIE, HeaderValue, StatusCode},
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::prelude::*;
use serde::Serialize;
use serde_json::json;

use crate::errors::{AppError, AppResult};
use crate::models::_entities::users;
use crate::models::users::{LoginParams, RegisterParams, UserResponse};

#[derive(Debug, Serialize)]
struct LoginResponse {
    token: String,
    user: UserResponse,
}

#[utoipa::path(
    post, path = "/api/auth/register", tag = "auth",
    request_body(content = serde_json::Value, description = "`{ email, password, name }`"),
    responses(
        (status = 200, description = "`{ user }`"),
        (status = 400, description = "Invalid payload"),
        (status = 409, description = "That email is already registered"),
    ),
)]
pub async fn register(
    State(ctx): State<AppContext>,
    Json(params): Json<RegisterParams>,
) -> AppResult<Response> {
    validate_registration(&params)?;

    let user = users::Model::create_with_password(&ctx.db, &params)
        .await
        .map_err(|err| match err {
            ModelError::EntityAlreadyExists => {
                // Same message and status the TypeScript stack returned.
                AppError::Conflict("A user with that email already exists".to_string())
            }
            other => AppError::Internal(anyhow::anyhow!(other)),
        })?;

    let role = user.role_name(&ctx.db).await;
    Ok((
        StatusCode::CREATED,
        Json(json!({ "user": UserResponse::new(&user, role) })),
    )
        .into_response())
}

#[utoipa::path(
    post, path = "/api/auth/login", tag = "auth",
    request_body(content = serde_json::Value, description = "`{ email, password }`"),
    responses(
        (status = 200, description = "`{ token, user }`; the token is also set as an httpOnly cookie"),
        (status = 401, description = "Wrong email or password"),
    ),
)]
pub async fn login(
    State(ctx): State<AppContext>,
    Json(params): Json<LoginParams>,
) -> AppResult<Response> {
    let user = users::Model::find_by_email(&ctx.db, &params.email)
        .await
        .map_err(|_| invalid_credentials())?;

    if !user.verify_password(&params.password) {
        return Err(invalid_credentials());
    }

    let token = issue_token(&ctx, &user.pid.to_string())?;
    let role = user.role_name(&ctx.db).await;

    let body = LoginResponse {
        token: token.clone(),
        user: UserResponse::new(&user, role),
    };

    let mut response = Json(body).into_response();
    response
        .headers_mut()
        .insert(SET_COOKIE, session_cookie(&ctx, &token)?);
    Ok(response)
}

/// `GET /api/auth/me` — the endpoint the frontend polls after login.
#[utoipa::path(
    get, path = "/api/auth/me", tag = "auth",
    security(("bearer" = [])),
    responses(
        (status = 200, description = "`{ user }`"),
        (status = 401, description = "No or invalid token"),
    ),
)]
pub async fn current(
    auth: auth::JWTWithUser<users::Model>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let role = auth.user.role_name(&ctx.db).await;
    Ok(Json(json!({ "user": UserResponse::new(&auth.user, role) })).into_response())
}

/// Clearing the cookie is the whole of logout: JWTs are stateless, so there is
/// no server-side session to destroy. An expired-in-the-past cookie is what
/// makes the browser drop it immediately.
#[utoipa::path(
    post, path = "/api/auth/logout", tag = "auth",
    responses((status = 200, description = "Session cookie cleared")),
)]
pub async fn logout() -> AppResult<Response> {
    let mut response = Json(json!({ "success": true })).into_response();
    let cookie = "token=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0";
    response.headers_mut().insert(
        SET_COOKIE,
        HeaderValue::from_str(cookie).map_err(|err| AppError::Internal(err.into()))?,
    );
    Ok(response)
}

/// `POST /api/auth/change-password` — rotate your own password.
///
/// The current password is required even though the caller is already
/// authenticated: a token left behind on a shared machine must not be enough to
/// lock its owner out.
#[utoipa::path(
    post, path = "/api/auth/change-password", tag = "auth",
    security(("bearer" = [])),
    request_body(content = serde_json::Value, description = "`{ currentPassword, newPassword }` — the current one is required even though you are already authenticated, so a token left on a shared machine cannot lock its owner out"),
    responses(
        (status = 200, description = "Password changed"),
        (status = 400, description = "The current password did not match"),
        (status = 401, description = "No token"),
    ),
)]
pub async fn change_password(
    auth: auth::JWTWithUser<users::Model>,
    State(ctx): State<AppContext>,
    Json(payload): Json<ChangePasswordParams>,
) -> AppResult<Response> {
    if !auth.user.verify_password(&payload.current_password) {
        return Err(AppError::Validation {
            message: "Validation failed".to_string(),
            errors: vec!["Current password is incorrect".to_string()],
        });
    }
    if payload.new_password.len() < 8 {
        return Err(AppError::Validation {
            message: "Validation failed".to_string(),
            errors: vec!["New password must be at least 8 characters".to_string()],
        });
    }

    auth.user
        .set_password(&ctx.db, &payload.new_password)
        .await
        .map_err(|err| AppError::Internal(anyhow::anyhow!(err)))?;

    Ok(Json(json!({ "success": true })).into_response())
}

#[derive(Debug, serde::Deserialize)]
pub struct ChangePasswordParams {
    #[serde(alias = "currentPassword")]
    pub current_password: String,
    #[serde(alias = "newPassword")]
    pub new_password: String,
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("auth")
        .add("/register", post(register))
        .add("/login", post(login))
        .add("/me", get(current))
        .add("/logout", post(logout))
        .add("/change-password", post(change_password))
}

// ---------------------------------------------------------------------------

/// Login failures are deliberately indistinguishable: revealing "no such user"
/// versus "wrong password" turns the endpoint into an account enumerator.
fn invalid_credentials() -> AppError {
    AppError::Unauthorized
}

fn validate_registration(params: &RegisterParams) -> AppResult<()> {
    let mut errors = Vec::new();
    if !params.email.contains('@') {
        errors.push("email must be a valid address".to_string());
    }
    if params.password.len() < 8 {
        errors.push("password must be at least 8 characters".to_string());
    }
    if params.name.trim().is_empty() {
        errors.push("name is required".to_string());
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(AppError::Validation {
            message: "Validation failed".to_string(),
            errors,
        })
    }
}

fn jwt_config(ctx: &AppContext) -> AppResult<&loco_rs::config::JWT> {
    ctx.config
        .auth
        .as_ref()
        .and_then(|auth| auth.jwt.as_ref())
        .ok_or_else(|| {
            AppError::Internal(anyhow::anyhow!(
                "auth.jwt is not configured — set JWT_SECRET and the auth block in config/*.yaml"
            ))
        })
}

fn issue_token(ctx: &AppContext, pid: &str) -> AppResult<String> {
    let jwt = jwt_config(ctx)?;
    // NOTE: `auth` from the prelude is the *extractor* module
    // (`controller::extractor::auth`); the JWT type lives at the crate root.
    loco_rs::auth::jwt::JWT::new(&jwt.secret)
        .generate_token(jwt.expiration, pid.to_string(), serde_json::Map::<String, serde_json::Value>::new())
        .map_err(|err| AppError::Internal(err.into()))
}

/// HTTP-only so script cannot read it; `SameSite=Lax` so ordinary top-level
/// navigations still carry it while cross-site POSTs do not.
fn session_cookie(ctx: &AppContext, token: &str) -> AppResult<HeaderValue> {
    let max_age = jwt_config(ctx)?.expiration;
    let secure = if ctx.environment == loco_rs::environment::Environment::Production {
        "; Secure"
    } else {
        ""
    };
    let cookie = format!("token={token}; HttpOnly; SameSite=Lax; Path=/; Max-Age={max_age}{secure}");
    HeaderValue::from_str(&cookie).map_err(|err| AppError::Internal(err.into()))
}

/// Unused today, but the shape every future guarded handler needs: pull the
/// role out of the dictionary and compare. Kept next to the auth code so the
/// RBAC story stays in one place.
#[allow(dead_code)]
pub async fn require_role(
    ctx: &AppContext,
    user: &users::Model,
    allowed: &[&str],
) -> AppResult<()> {
    match user.role_name(&ctx.db).await {
        Some(role) if allowed.contains(&role.as_str()) => Ok(()),
        _ => Err(AppError::Forbidden("forbidden".to_string())),
    }
}

//! Generic CRUD over every `bus_*` table.
//!
//! One controller serves every business entity, resolving columns, validation
//! and ordering from the Application Dictionary on each request. The routes and
//! payload shapes here are the frozen API contract (§9) — the frontend and the
//! stack-agnostic `tests/` suites both depend on them, and they must not drift
//! from the NestJS stack.

use std::collections::HashMap;

use axum::{
    extract::{Path, Query, State},
    http::{HeaderMap, StatusCode},
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::prelude::*;
use serde_json::{json, Map, Value};
use uuid::Uuid;

use crate::errors::{AppError, AppResult};
use crate::models::_entities::users;
use crate::hooks;
use crate::services::audit::{AuditEntry, AuditOperation, AuditService};
use crate::services::authz;
use crate::services::concurrency::{self, Refusal};
use crate::services::dictionary::{ConcurrencyMode, DictionaryCache};
use crate::services::field_meta::{self, FieldLayout};
use crate::services::dynamic_repo::{
    DynamicRepo, Filter, FilterOp, OrderDir, PaginationOptions, RawVersion, UpdateResult,
    WriteGuard,
};
use crate::services::promotion::{
    PromotionOutcome, PromotionService, STATUS_DRAFT, STATUS_REJECTED,
};
use crate::services::rules_engine::RuleOperation;

/// Default page size, matching the TypeScript stack.
const DEFAULT_LIMIT: u64 = 25;
/// Upper bound so a caller cannot ask for the whole table in one request.
const MAX_LIMIT: u64 = 500;

#[utoipa::path(
    get, path = "/api/bus/{entity}", tag = "bus",
    security(("bearer" = [])),
    params(
        ("entity" = String, Path, description = "Dictionary table or entity name, e.g. `bus_compound` or `compound`"),
        ("page" = Option<u64>, Query, description = "1-based page number"),
        ("limit" = Option<u64>, Query, description = "Rows per page"),
        ("search" = Option<String>, Query, description = "Substring match across the entity's text columns"),
        ("sort" = Option<String>, Query, description = "Column to order by"),
        ("order" = Option<String>, Query, description = "`asc` or `desc`"),
    ),
    responses(
        (status = 200, description = "`{ data: [...], meta: { total, page, limit, totalPages } }`. Column filters are `filter.COLUMN=OP:VALUE`, where OP is one of equals/eq, gt, gte, lt, lte, contains, startsWith, endsWith."),
        (status = 401, description = "No or invalid token"),
        (status = 404, description = "No such entity in the dictionary"),
    ),
)]
pub async fn list(
    auth: auth::JWTWithUser<users::Model>,
    Path(entity): Path<String>,
    Query(mut params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
    SharedStore(repo): SharedStore<DynamicRepo>,
) -> AppResult<Response> {
    let meta = dictionary.meta(&entity).await?;
    let principal = authz::principal(ctx.db.get_postgres_connection_pool(), &auth.user).await?;
    authz::require_operation(
        ctx.db.get_postgres_connection_pool(),
        &principal,
        &meta.table_name,
        authz::Operation::Read,
    )
    .await?;
    // The model's `hooks`. `beforeQuery` may rewrite the query
    // parameters — tenant scoping is the motivating case — so it runs before
    // they are read into `opts` and `filters`; `beforeList` only observes them.
    hooks::before_query(&meta.table_name, &mut params).await?;
    hooks::before_list(&meta.table_name, &params).await?;

    let opts = pagination_from(&params, &dictionary, &entity).await?;
    let filters = filters_from(&params, &dictionary, &entity).await?;

    let mut result = repo
        .find_all(&meta, &opts, &filters, params.get("search").map(String::as_str))
        .await?;

    // `total` is the count the query reported and is deliberately not
    // recomputed from `data`: these hooks shape the page being returned, and
    // a hook that drops a row from one page must not make the collection look
    // smaller than it is.
    hooks::after_query(&meta.table_name, &mut result.data).await?;
    hooks::after_list(&meta.table_name, &mut result.data).await?;

    let total_pages = if opts.limit == 0 {
        0
    } else {
        result.total.div_ceil(opts.limit)
    };

    Ok(Json(json!({
        "data": result.data,
        "meta": {
            "total": result.total,
            "page": opts.page,
            "limit": opts.limit,
            "totalPages": total_pages,
        }
    }))
    .into_response())
}

#[utoipa::path(
    get, path = "/api/bus/{entity}/{id}", tag = "bus",
    security(("bearer" = [])),
    params(("entity" = String, Path, description = "Dictionary table or entity name, e.g. `bus_compound` or `compound`"), ("id" = String, Path, description = "Record id (UUID)")),
    responses(
        (status = 200, description = "The record"),
        (status = 400, description = "Malformed id"),
        (status = 404, description = "No such record, or it is soft-deleted"),
    ),
)]
pub async fn get_one(
    auth: auth::JWTWithUser<users::Model>,
    Path((entity, id)): Path<(String, Uuid)>,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
    SharedStore(repo): SharedStore<DynamicRepo>,
) -> AppResult<Response> {
    let table = dictionary.resolve(&entity).await?;
    let principal = authz::principal(ctx.db.get_postgres_connection_pool(), &auth.user).await?;
    authz::require_operation(
        ctx.db.get_postgres_connection_pool(),
        &principal,
        table.as_str(),
        authz::Operation::Read,
    )
    .await?;
    hooks::before_read(table.as_str(), id).await?;

    let mut row = repo
        .find_by_id(&table, id)
        .await?
        .ok_or_else(|| AppError::NotFound(format!("Record {id} not found")))?;

    // Runs on the row that is about to be returned, so the ETag is computed
    // from what the caller actually receives.
    hooks::after_read(table.as_str(), &mut row).await?;

    // Where the record's transaction stands, so a screen can say a record in a
    // final state is closed before anyone tries to edit it.
    let meta = dictionary.meta(&entity).await?;
    let status =
        concurrency::transaction_status(ctx.db.get_postgres_connection_pool(), &meta, &row).await;
    attach_transaction_status(&mut row, status);

    Ok(with_etag(&row, Json(row.clone()).into_response()))
}

#[utoipa::path(
    post, path = "/api/bus/{entity}", tag = "bus",
    security(("bearer" = [])),
    params(("entity" = String, Path, description = "Dictionary table or entity name, e.g. `bus_compound` or `compound`")),
    request_body(content = serde_json::Value, description = "The entity's writable columns. Ask `/api/bus/{entity}/meta` for the shape."),
    responses(
        (status = 201, description = "The created record, carrying `docStatus` and the rules verdict under `promotion`"),
        (status = 400, description = "Missing a mandatory column, or a value of the wrong type"),
        (status = 409, description = "A unique column already holds that value"),
        (status = 422, description = "A business rule prevented the write"),
    ),
)]
pub async fn create(
    auth: auth::JWTWithUser<users::Model>,
    Path(entity): Path<String>,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
    SharedStore(repo): SharedStore<DynamicRepo>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    let meta = dictionary.meta(&entity).await?;
    let principal = authz::principal(ctx.db.get_postgres_connection_pool(), &auth.user).await?;
    authz::require_operation(
        ctx.db.get_postgres_connection_pool(),
        &principal,
        &meta.table_name,
        authz::Operation::Create,
    )
    .await?;
    let mut body = as_object(payload)?;

    // The model's `hooks`. Validation sees exactly what the caller
    // sent and `beforeCreate` may then rewrite it: validating after the
    // transform would be validating something nobody submitted.
    hooks::custom_validate(&meta.table_name, &body).await?;
    hooks::before_create(&meta.table_name, &mut body).await?;
    verify_narrowing(ctx.db.get_postgres_connection_pool(), &meta, &body).await?;

    // The row lands as a draft; promotion decides whether it becomes final.
    let mut row = repo.create(&meta, &body).await?;
    let outcome = run_promotion(&ctx, &meta, &row, RuleOperation::Create, None).await;

    // A rule that prevented this create means the request failed. Discard the
    // draft and return before the audit entry, which would otherwise record a
    // creation that did not survive the request.
    let table = dictionary.resolve(&entity).await?;
    reject_if_prevented(&ctx, &repo, &table, &row, &outcome, true).await?;

    apply_promotion(&mut row, &outcome);

    record_audit(
        &ctx,
        &meta,
        AuditOperation::Create,
        row_id(&row),
        None,
        Some(row.clone()),
        &auth.user,
    )
    .await;

    settle_row(&repo, &table, &mut row, &outcome).await?;

    // After the audit entry, so the trail records the write whatever the hook
    // does. An `after*` hook cannot undo the write — an error here surfaces to
    // the caller with the row already committed.
    hooks::after_create(&meta.table_name, &row).await?;

    // The ETag, so the first save of the new record can send `If-Match`
    // without reading it back, and where its transaction stands.
    let status =
        concurrency::transaction_status(ctx.db.get_postgres_connection_pool(), &meta, &row).await;
    attach_transaction_status(&mut row, status);
    Ok(with_etag(&row, (StatusCode::CREATED, Json(row.clone())).into_response()))
}

/// `PUT`/`PATCH /api/bus/{entity}/{id}` — change a record.
///
/// Both verbs reach this handler and behave identically — only the columns
/// present in the body are written. The document declares the `PUT`, which is
/// what the generated frontend sends.
#[utoipa::path(
    put, path = "/api/bus/{entity}/{id}", tag = "bus",
    security(("bearer" = [])),
    params(("entity" = String, Path, description = "Dictionary table or entity name, e.g. `bus_compound` or `compound`"), ("id" = String, Path, description = "Record id (UUID)")),
    request_body(content = serde_json::Value, description = "Only the columns to change; `PATCH` is accepted at the same path and does the same thing"),
    responses(
        (status = 200, description = "The updated record, with `version` advanced and its `transactionStatus`"),
        (status = 400, description = "Unknown column, or a value of the wrong type"),
        (status = 404, description = "No such record"),
        (status = 409, description = "`VERSION_CONFLICT`: the record changed since the `If-Match` version — `conflict` carries it as it now stands, who changed it, when, which columns, and its status. `RECORD_FINAL`: the record is in a final state and closed. Also a unique violation"),
        (status = 428, description = "No `If-Match` on an entity whose `concurrency` is optimistic"),
    ),
)]
pub async fn update(
    auth: auth::JWTWithUser<users::Model>,
    Path((entity, id)): Path<(String, Uuid)>,
    headers: HeaderMap,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
    SharedStore(repo): SharedStore<DynamicRepo>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    let meta = dictionary.meta(&entity).await?;
    let principal = authz::principal(ctx.db.get_postgres_connection_pool(), &auth.user).await?;
    authz::require_operation(
        ctx.db.get_postgres_connection_pool(),
        &principal,
        &meta.table_name,
        authz::Operation::Update,
    )
    .await?;
    let mut body = as_object(payload)?;
    let expected_version = match parse_if_match(&headers)? {
        Precondition::Version(version) => Some(version),
        // `*` is a deliberate overwrite of whatever is there.
        Precondition::Any => None,
        Precondition::Absent if meta.concurrency == ConcurrencyMode::Optimistic => {
            return Err(AppError::PreconditionRequired(format!(
                "An update to {} must name the version it was read at: send If-Match: \"v<version>\" from the record's ETag.",
                meta.name
            )));
        }
        Precondition::Absent => None,
    };

    // Same order as `create`: validate what the caller sent, then let
    // `beforeUpdate` rewrite it.
    hooks::custom_validate(&meta.table_name, &body).await?;
    hooks::before_update(&meta.table_name, id, &mut body).await?;

    // A status column is not an ordinary column. Before the write, check that
    // the move the body asks for is one the model's state machine draws, and
    // that this caller may make it. Both are no-ops for a table with no
    // machine, which is every table until a state machine
    // section names one.
    let moves = authz::require_transition(
        ctx.db.get_postgres_connection_pool(),
        &principal,
        &meta.table_name,
        id,
        &body,
    )
    .await?;

    // Read the row before writing so the audit entry has a real `before`.
    // Losing the read is not a reason to fail the write, so a miss simply
    // leaves `before` null rather than aborting.
    let table = dictionary.resolve(&entity).await?;
    let before = repo.find_by_id(&table, id).await.ok().flatten();

    // A record in a final state is a completed transaction: closed to every
    // caller. Said here so the refusal comes before any rule work; the write
    // below repeats the condition, so a record that becomes final in between
    // is refused just the same.
    if let Some(current) = before.as_ref() {
        if meta.lifecycle.as_ref().is_some_and(|lifecycle| lifecycle.is_final(current)) {
            return Err(concurrency::refusal(
                ctx.db.get_postgres_connection_pool(),
                &meta,
                current,
                expected_version,
                &body,
                Refusal::RecordFinal,
            )
            .await);
        }
    }

    // A choice another column narrows is checked against the record as it will
    // be: what is stored, with this request's columns laid over it.
    let mut candidate: Map<String, Value> = match &before {
        Some(Value::Object(stored)) => stored.clone(),
        _ => Map::new(),
    };
    candidate.extend(body.iter().map(|(k, v)| (k.clone(), v.clone())));
    verify_narrowing(ctx.db.get_postgres_connection_pool(), &meta, &candidate).await?;

    let guard = WriteGuard {
        expected_version,
        status_from: &moves,
        closed_by: meta.lifecycle.as_ref(),
    };
    let mut row = match repo.update(&meta, id, &body, &guard).await? {
        UpdateResult::Updated(row) => row,
        UpdateResult::Refused { current } => {
            return Err(concurrency::refusal(
                ctx.db.get_postgres_connection_pool(),
                &meta,
                &current,
                expected_version,
                &body,
                Refusal::of(&meta, &current),
            )
            .await);
        }
    };
    let outcome = run_promotion(&ctx, &meta, &row, RuleOperation::Update, before.as_ref()).await;
    if let Err(refusal) = reject_if_prevented(&ctx, &repo, &table, &row, &outcome, false).await {
        // A rule that refuses a write has to leave nothing of it behind. The
        // update has already landed, so put back what it replaced — its
        // version included, so the caller's `If-Match` still holds for the
        // corrected save; otherwise the refused value stays in the record and
        // every later edit, a status move included, is judged against it.
        restore_columns(&repo, &meta.table_name, id, before.as_ref(), &row, &body).await;
        return Err(refusal);
    }
    apply_promotion(&mut row, &outcome);

    record_audit(
        &ctx,
        &meta,
        AuditOperation::Update,
        Some(id.to_string()),
        before,
        Some(row.clone()),
        &auth.user,
    )
    .await;

    settle_row(&repo, &table, &mut row, &outcome).await?;

    // After the audit entry, and unable to undo the write — see `create`.
    hooks::after_update(&meta.table_name, &row).await?;

    let status =
        concurrency::transaction_status(ctx.db.get_postgres_connection_pool(), &meta, &row).await;
    attach_transaction_status(&mut row, status);
    Ok(with_etag(&row, Json(row.clone()).into_response()))
}

#[utoipa::path(
    delete, path = "/api/bus/{entity}/{id}", tag = "bus",
    security(("bearer" = [])),
    params(("entity" = String, Path, description = "Dictionary table or entity name, e.g. `bus_compound` or `compound`"), ("id" = String, Path, description = "Record id (UUID)")),
    responses(
        (status = 204, description = "Soft-deleted — the row stays auditable and drops out of every read"),
        (status = 404, description = "No such record"),
    ),
)]
pub async fn remove(
    auth: auth::JWTWithUser<users::Model>,
    Path((entity, id)): Path<(String, Uuid)>,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
    SharedStore(repo): SharedStore<DynamicRepo>,
) -> AppResult<Response> {
    let meta = dictionary.meta(&entity).await?;
    let principal = authz::principal(ctx.db.get_postgres_connection_pool(), &auth.user).await?;
    authz::require_operation(
        ctx.db.get_postgres_connection_pool(),
        &principal,
        &meta.table_name,
        authz::Operation::Delete,
    )
    .await?;
    let table = dictionary.resolve(&entity).await?;
    let before = repo.find_by_id(&table, id).await.ok().flatten();

    // A `beforeDelete` hook is a guard: returning `Ok(false)` refuses the
    // request rather than raising, which is how a model says "this record is
    // referenced" without inventing an error type.
    if !hooks::before_delete(table.as_str(), id).await? {
        return Err(AppError::BadRequest(format!(
            "Record {id} cannot be deleted: a beforeDelete hook refused it"
        )));
    }

    // `before` is moved into the audit entry below, so the row `afterDelete`
    // is handed has to be cloned out first.
    let deleted = before.clone();

    if repo.soft_delete(&table, id).await? {
        record_audit(
            &ctx,
            &meta,
            AuditOperation::Delete,
            Some(id.to_string()),
            before,
            None,
            &auth.user,
        )
        .await;

        // Handed the row as it was. Skipped when the pre-read missed, because
        // there is nothing truthful to pass.
        if let Some(row) = deleted {
            hooks::after_delete(table.as_str(), &row).await?;
        }

        Ok(StatusCode::NO_CONTENT.into_response())
    } else {
        Err(AppError::NotFound(format!("Record {id} not found")))
    }
}

