/// Upper bound on one lookup: a dropdown is not paged, so it asks for all of
/// its choices at once — and a list longer than this has outgrown a dropdown.
const MAX_LOOKUP: u64 = 2000;

/// `GET /api/bus/{entity}/lookup/{column}` — the choices for one lookup column.
///
/// The rows of the table the column points at, narrowed by the dictionary's
/// `narrowed_by` rule for the column: pass the record's values for the columns
/// that narrow it (`?country_id=…`) and only the rows that belong to them come
/// back. A state is offered only from the country chosen; a city only from its
/// state, or from its country when no state is chosen yet. The filter is applied
/// here, where the data is supplied, and not in the screen that asks.
///
/// The caller needs the same read access as for the target's own list.
#[utoipa::path(
    get, path = "/api/bus/{entity}/lookup/{column}", tag = "bus",
    security(("bearer" = [])),
    params(
        ("entity" = String, Path, description = "The entity holding the lookup column"),
        ("column" = String, Path, description = "The lookup column, e.g. `state_province_id`"),
        ("search" = Option<String>, Query, description = "Substring match across the target's text columns"),
        ("limit" = Option<u64>, Query, description = "At most this many choices (default and maximum 2000)"),
    ),
    responses(
        (status = 200, description = "`{ data: [...], meta: { total } }` — the target's rows that the record's other values allow"),
        (status = 400, description = "The column is not a lookup"),
        (status = 404, description = "No such entity or column"),
    ),
)]
pub async fn lookup(
    auth: auth::JWTWithUser<users::Model>,
    Path((entity, column)): Path<(String, String)>,
    Query(params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
    SharedStore(repo): SharedStore<DynamicRepo>,
) -> AppResult<Response> {
    let meta = dictionary.meta(&entity).await?;
    let source = meta
        .column(&column)
        .ok_or_else(|| AppError::NotFound(format!("No column '{column}' on this entity")))?;
    let Some(target) = source.ref_table_name.clone() else {
        return Err(AppError::BadRequest(format!(
            "'{column}' is not a lookup"
        )));
    };
    let target_meta = dictionary.meta(&target).await?;
    let principal = authz::principal(ctx.db.get_postgres_connection_pool(), &auth.user).await?;
    authz::require_operation(
        ctx.db.get_postgres_connection_pool(),
        &principal,
        &target_meta.table_name,
        authz::Operation::Read,
    )
    .await?;

    // Only what the dictionary says narrows this column counts; a parameter
    // naming any other column is ignored rather than turned into a filter.
    let filters: Vec<Filter> = source
        .narrowed_by
        .iter()
        .filter_map(|rule| {
            params
                .get(&rule.by)
                .filter(|value| !value.is_empty())
                .map(|value| Filter {
                    column: rule.on.clone(),
                    op: FilterOp::Equals,
                    value: value.clone(),
                })
        })
        .collect();

    let order_by = ["name", "code"]
        .into_iter()
        .find(|candidate| target_meta.column(candidate).is_some())
        .map(str::to_string);
    let opts = PaginationOptions {
        page: 1,
        limit: params
            .get("limit")
            .and_then(|v| v.parse::<u64>().ok())
            .unwrap_or(MAX_LOOKUP)
            .clamp(1, MAX_LOOKUP),
        order_by,
        order_dir: OrderDir::Asc,
    };
    let result = repo
        .find_all(
            &target_meta,
            &opts,
            &filters,
            params.get("search").map(String::as_str),
        )
        .await?;
    Ok(Json(json!({ "data": result.data, "meta": { "total": result.total } })).into_response())
}

/// A choice that another column of the record narrows has to be one of the rows
/// that column allows: a state of the country chosen, a city of the state.
///
/// `record` is the row as it will be — on an update, what is stored with the
/// request's columns laid over it — so changing only the country is checked
/// against the state already there. A null on either side is not a mismatch; the
/// column's own mandatory rule decides whether it may be empty.
async fn verify_narrowing(
    pool: &sqlx::PgPool,
    meta: &crate::services::dictionary::TableMeta,
    record: &Map<String, Value>,
) -> AppResult<()> {
    for column in &meta.columns {
        let Some(target) = column.ref_table_name.as_deref() else {
            continue;
        };
        let Some(chosen) = record.get(&column.column_name).and_then(Value::as_str) else {
            continue;
        };
        for rule in &column.narrowed_by {
            let Some(control) = record.get(&rule.by).and_then(Value::as_str) else {
                continue;
            };
            if !is_plain_identifier(target) || !is_plain_identifier(&rule.on) {
                return Err(AppError::BadRequest(format!(
                    "The dictionary names an unusable column for '{}'",
                    column.name
                )));
            }
            let (Ok(chosen_id), Ok(control_id)) =
                (Uuid::parse_str(chosen), Uuid::parse_str(control))
            else {
                continue;
            };
            let sql = format!(
                "SELECT EXISTS (SELECT 1 FROM {target} WHERE id = $1 AND {on} = $2 AND deleted_at IS NULL)",
                on = rule.on
            );
            let belongs: bool = sqlx::query_scalar(sqlx::AssertSqlSafe(sql))
                .bind(chosen_id)
                .bind(control_id)
                .fetch_one(pool)
                .await?;
            if !belongs {
                let controlling = meta
                    .column(&rule.by)
                    .map_or(rule.by.as_str(), |c| c.name.as_str());
                return Err(AppError::Validation {
                    message: format!("{} does not belong to the chosen {controlling}", column.name),
                    errors: vec![format!(
                        "{} does not belong to the chosen {controlling}",
                        column.name
                    )],
                });
            }
        }
    }
    Ok(())
}

/// A table or column name that may be written into SQL: lower-case words and
/// underscores. The names come from the dictionary, which an administrator can
/// write, so they are checked rather than trusted.
fn is_plain_identifier(name: &str) -> bool {
    !name.is_empty()
        && name.starts_with(|c: char| c.is_ascii_lowercase())
        && name
            .chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
}

pub fn routes() -> Routes {
    // Axum 0.8 brace syntax. Static segments outrank dynamic ones in the
    // router, so `/{entity}/meta` is matched before `/{entity}/{id}`.
    Routes::new()
        .prefix("bus")
        .add("/{entity}", get(list))
        .add("/{entity}", post(create))
        .add("/{entity}/meta", get(meta))
        .add("/{entity}/fields/form", get(fields_form))
        .add("/{entity}/fields/grid", get(fields_grid))
        .add("/{entity}/lookup/{column}", get(lookup))
        .add("/{entity}/{id}", get(get_one))
        .add("/{entity}/{id}", put(update))
        .add("/{entity}/{id}", patch(update))
        .add("/{entity}/{id}", delete(remove))
}

// ---------------------------------------------------------------------------
// Request helpers
// ---------------------------------------------------------------------------

fn as_object(payload: Value) -> AppResult<Map<String, Value>> {
    match payload {
        Value::Object(map) => Ok(map),
        _ => Err(AppError::BadRequest(
            "Request body must be a JSON object".to_string(),
        )),
    }
}

/// What an update's `If-Match` asks for.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Precondition {
    /// No header.
    Absent,
    /// `*`: whatever version is there — a deliberate overwrite.
    Any,
    /// `"v{n}"`: only if the row is still at that version.
    Version(i32),
}

/// Parse `If-Match: "v{n}"` into a row version.
///
/// The quoted `v`-prefixed form is what the frontend sends; anything else is a
/// malformed precondition rather than a silent full-overwrite.
fn parse_if_match(headers: &HeaderMap) -> AppResult<Precondition> {
    let Some(raw) = headers.get(axum::http::header::IF_MATCH) else {
        return Ok(Precondition::Absent);
    };
    let raw = raw
        .to_str()
        .map_err(|_| AppError::BadRequest("Malformed If-Match header".to_string()))?;

    // `*` means "any current version" — a valid precondition that imposes no
    // version constraint.
    if raw.trim() == "*" {
        return Ok(Precondition::Any);
    }

    let version = raw
        .trim()
        .trim_matches('"')
        .trim_start_matches('v')
        .parse::<i32>()
        .map_err(|_| {
            AppError::BadRequest(format!("Malformed If-Match header: expected \"v\{{n}}\", got {raw}"))
        })?;
    Ok(Precondition::Version(version))
}

/// Put where the record's transaction stands into the response body, when its
/// table has a state machine. A response-only key: `collect_assignments`
/// ignores it, so a client that saves the record it was given back does not
/// trip over it.
fn attach_transaction_status(row: &mut Value, status: Value) {
    if let (Value::Object(map), false) = (row, status.is_null()) {
        map.insert("transactionStatus".to_string(), status);
    }
}

/// Echo the row's version back as an ETag so the next write can send `If-Match`.
fn with_etag(row: &Value, mut response: Response) -> Response {
    if let Some(version) = row.get("version").and_then(Value::as_i64) {
        if let Ok(value) = format!("\"v{version}\"").parse() {
            response.headers_mut().insert(axum::http::header::ETAG, value);
        }
    }
    response
}

/// The row's primary key, as the audit log stores it (`entity_id` is VARCHAR).
/// Bring the response up to date with what a rule's side effects wrote.
///
/// A `trigger-workflow` or `cascade-update` action runs inside this request
/// and can write the row that fired it — a saga moving a quote to `in_review`
/// is the common case. The response used to describe the row as it stood
/// before they ran: crm's create answered `draft` for a quote the database
/// already held as `in_review`, a caller acting on that status asked for a
/// move out of a state the record had left, and the `version` — so the ETag
/// a conditional update sends back — was one behind. A transform's columns are
/// known and merged by `apply_promotion`; a workflow's are not, so the row is
/// read back whole. It runs after the audit entry, which records the write
/// the caller made.
async fn settle_row(
    repo: &DynamicRepo,
    table: &crate::services::dictionary::TableName,
    row: &mut Value,
    outcome: &PromotionOutcome,
) -> AppResult<()> {
    if !outcome.side_effects_ran {
        return Ok(());
    }
    let Some(id) = row
        .get("id")
        .and_then(Value::as_str)
        .and_then(|id| Uuid::parse_str(id).ok())
    else {
        return Ok(());
    };
    if let (Some(Value::Object(settled)), Value::Object(map)) =
        (repo.find_by_id(table, id).await?, row)
    {
        map.extend(settled);
    }
    Ok(())
}

fn row_id(row: &Value) -> Option<String> {
    row.get("id").map(|id| match id {
        // Already a string for UUID keys; anything else is rendered rather
        // than dropped, so an integer key still lands in the log.
        Value::String(value) => value.clone(),
        other => other.to_string(),
    })
}

/// Append an audit entry for a write.
///
/// Gated on `sys_table.is_changelog`, which is the dictionary's own switch for
/// "keep a history of this table" — a table an administrator has turned logging
/// off for must not accumulate entries behind their back.
///
/// Never returns an error: `AuditService::record` already swallows and logs its
/// own failures, because a write that succeeded but could not be logged is
/// still a write and must not be rolled back over bookkeeping.
async fn record_audit(
    ctx: &AppContext,
    meta: &crate::services::dictionary::TableMeta,
    operation: AuditOperation,
    entity_id: Option<String>,
    before: Option<Value>,
    after: Option<Value>,
    user: &users::Model,
) {
    if !meta.is_changelog {
        return;
    }
    let Some(audit) = ctx.shared_store.get::<AuditService>() else {
        crate::log_event!(entity_audit_unavailable);
        return;
    };

    audit
        .record(&AuditEntry {
            entity_type: meta.table_name.clone(),
            entity_id,
            operation,
            before,
            after,
            // The dictionary identity, not the credential row: `/admin/audit`
            // joins against `sys_user`, and it is the identity that survives a
            // change of credential store.
            user_id: user.sys_user_id.map(|id| id.to_string()),
            user_email: Some(user.email.clone()),
        })
        .await;
}

/// Run the draft → final pipeline for a freshly written row.
///
/// Promotion runs inline (§6.7 option A) precisely so its verdict can travel in
/// this response. A pipeline *failure* must not fail the write — the row exists
/// either way — so it degrades to leaving the row a draft and logs.
async fn run_promotion(
    ctx: &AppContext,
    meta: &crate::services::dictionary::TableMeta,
    row: &Value,
    operation: RuleOperation,
    previous: Option<&Value>,
) -> PromotionOutcome {
    let Some(promotion) = ctx.shared_store.get::<PromotionService>() else {
        crate::log_event!(entity_promotion_unavailable);
        return PromotionOutcome {
            doc_status: STATUS_DRAFT.to_string(),
            ..PromotionOutcome::default()
        };
    };

    // JDM lookup for the entity comes from sys_rule_definitions; a table with
    // no rules promotes unconditionally.
    let jdms = load_entity_jdms(ctx, &meta.table_name).await;

    match promotion.promote(meta, row, operation, &jdms, previous).await {
        Ok(outcome) => outcome,
        Err(err) => {
            crate::log_event!(entity_promotion_failed, error = ?err, table = meta.table_name);
            PromotionOutcome {
                doc_status: STATUS_DRAFT.to_string(),
                ..PromotionOutcome::default()
            }
        }
    }
}

/// Every active rule document for an entity, newest first.
///
/// All of them, deliberately. An entity routinely carries more than one rule —
/// a validation that rejects bad input and an automation that fires on the good
/// input are two separate documents — and evaluating only one means whichever
/// rule loses the sort silently never runs. Rule authors get no feedback from
/// that: the rule is listed, active, and dead.
async fn load_entity_jdms(ctx: &AppContext, table_name: &str) -> Vec<String> {
    let pool = ctx.db.get_postgres_connection_pool();
    let rows: Vec<(String,)> = sqlx::query_as(
        r"SELECT jdm_content FROM sys_rule_definitions
           WHERE entity_name = $1 AND is_active = true
           ORDER BY updated_at DESC NULLS LAST",
    )
    .bind(table_name)
    .fetch_all(pool)
    .await
    .unwrap_or_default();
    rows.into_iter().map(|(jdm,)| jdm).collect()
}

/// Attach the promotion verdict to the response body, and reflect the settled
/// status back onto the row's own `doc_status` so the two never disagree.
fn apply_promotion(row: &mut Value, outcome: &PromotionOutcome) {
    if let Value::Object(map) = row {
        // A `transform` action rewrote these columns in the database. The body
        // is built from the row as it was *sent*, so without this the response
        // contradicts the record that was just written.
        for (column, value) in &outcome.transformed {
            map.insert(column.clone(), value.clone());
        }
        map.insert(
            "doc_status".to_string(),
            Value::String(outcome.doc_status.clone()),
        );
        map.insert("promotion".to_string(), outcome.to_json());
    }
}

/// Write back the values `body` replaced, from the row as it was before the write.
///
/// Best effort, like discarding a refused create: a failure here must not
/// replace the rule's message with a storage error, and is logged.
async fn restore_columns(
    repo: &DynamicRepo,
    table: &str,
    id: Uuid,
    before: Option<&Value>,
    written: &Value,
    body: &Map<String, Value>,
) {
    let Some(Value::Object(previous)) = before else {
        return;
    };
    let version_of = |row: Option<&Value>| {
        row.and_then(Value::as_i64)
            .and_then(|version| i32::try_from(version).ok())
    };
    let (Some(written_version), Some(previous_version)) =
        (version_of(written.get("version")), version_of(previous.get("version")))
    else {
        return;
    };
    let restored: Map<String, Value> = body
        .keys()
        .filter_map(|column| previous.get(column).map(|value| (column.clone(), value.clone())))
        .collect();
    if restored.is_empty() {
        return;
    }
    let version = RawVersion::Restore {
        written: written_version,
        previous: previous_version,
    };
    if let Err(err) = repo.update_raw(table, id, &restored, version).await {
        crate::log_event!(entity_update_restore_failed, error = ?err, %id);
    }
}

/// Turn a `prevent` verdict into a rejected request.
///
/// A rule that says "prevent" has to *prevent* something. Returning 201 with
/// `doc_status: "rejected"` in the body meant every client that checks the
/// status code — including the parity suites — saw the write succeed, and a
/// form would happily navigate to a record the rules had refused.
///
/// The draft row is deleted first, so a refused create leaves nothing behind.
/// An update keeps its row: the previous version is still valid data, and the
/// rejected status on it is the record of what happened.
async fn reject_if_prevented(
    ctx: &AppContext,
    repo: &DynamicRepo,
    table: &crate::services::dictionary::TableName,
    row: &Value,
    outcome: &PromotionOutcome,
    discard_row: bool,
) -> AppResult<()> {
    if outcome.doc_status != STATUS_REJECTED {
        return Ok(());
    }

    if discard_row {
        if let Some(id) = row_id(row).and_then(|id| Uuid::parse_str(&id).ok()) {
            // Best effort: failing to clean up must not replace the rule's
            // message with a storage error the caller can do nothing about.
            if let Err(err) = repo.hard_delete(table, id).await {
                crate::log_event!(entity_draft_discard_failed, error = ?err, %id);
            }
        }
    }
    let _ = ctx;

    Err(AppError::Validation {
        message: "Rejected by a business rule".to_string(),
        errors: vec![outcome
            .message
            .clone()
            .unwrap_or_else(|| "Rejected by a business rule".to_string())],
    })
}

async fn pagination_from(
    params: &HashMap<String, String>,
    dictionary: &DictionaryCache,
    entity: &str,
) -> AppResult<PaginationOptions> {
    let page = params
        .get("page")
        .and_then(|v| v.parse::<u64>().ok())
        .filter(|p| *p > 0)
        .unwrap_or(1);

    let limit = params
        .get("limit")
        .and_then(|v| v.parse::<u64>().ok())
        .filter(|l| *l > 0)
        .unwrap_or(DEFAULT_LIMIT)
        .min(MAX_LIMIT);

    // An `orderBy` naming a column that is not in the dictionary is a 400 —
    // it must never reach the query builder as an identifier.
    let order_by = match params.get("orderBy") {
        Some(column) => Some(dictionary.resolve_column(entity, column).await?),
        None => None,
    };

    // Left alone, a list is the most recently modified first. Asking for a
    // column to sort by without a direction still means ascending — that is
    // what a column header click has always sent.
    let order_dir = match (params.get("orderDir"), &order_by) {
        (None, None) => OrderDir::Desc,
        (direction, _) => OrderDir::parse(direction.map(String::as_str)),
    };

    Ok(PaginationOptions {
        page,
        limit,
        order_by,
        order_dir,
    })
}

/// Parse `?filter.{field}={operator}:{value}` into verified filters.
async fn filters_from(
    params: &HashMap<String, String>,
    dictionary: &DictionaryCache,
    entity: &str,
) -> AppResult<Vec<Filter>> {
    let mut filters = Vec::new();
    for (key, raw) in params {
        let Some(field) = key.strip_prefix("filter.") else {
            continue;
        };
        let column = dictionary.resolve_column(entity, field).await?;
        let (op, value) = match raw.split_once(':') {
            Some((op, value)) => (FilterOp::parse(op)?, value.to_string()),
            // A bare value is an equality match, as in the TypeScript stack.
            None => (FilterOp::Equals, raw.clone()),
        };
        filters.push(Filter { column, op, value });
    }
    Ok(filters)
}

//! Role-scoped reverse proxy to an ElectricSQL server.
//!
//! Clients call `GET /v1/shape?table=sys_table&role=admin&…`; this forwards to
//! `ELECTRIC_URL/v1/shape` with the caller-supplied `role` **removed** and a
//! server-generated `where` clause put in its place, so a client cannot widen
//! its own visibility.
//!
//! Note this controller lives *outside* the `/api` prefix — it serves
//! `/v1/shape`, which is what the Electric client library expects. See
//! `app.rs` for how route ordering achieves that.
//!
//! ## Security note — a deliberate difference from the TypeScript original
//!
//! `electric.controller.ts` builds its role clause by interpolating the `role`
//! query parameter straight into SQL:
//!
//! ```text
//! allowed_roles @> ARRAY['${role}']::text[]
//! ```
//!
//! `role` is attacker-controlled (it is a query parameter), so a crafted value
//! escapes the quotes and rewrites the WHERE clause that is the *only* thing
//! restricting which dictionary rows the caller receives. The design document
//! says to keep the role clause identical; this keeps it identical **for every
//! legitimate role** but validates the value first, rejecting anything outside
//! `[A-Za-z0-9_-]` with a 400. No valid role changes behaviour, and the
//! injection is closed rather than ported.

use axum::{
    body::Body,
    extract::{Query, State},
    http::StatusCode,
    response::Response,
};
use loco_rs::prelude::*;
use std::collections::HashMap;

use crate::errors::{AppError, AppResult};
use crate::services::system_config::SystemConfig;

/// The only tables reachable through the proxy. Identical to the TypeScript
/// `ALLOWED_SYS_TABLES`.
const ALLOWED_SYS_TABLES: [&str; 5] = [
    "sys_table",
    "sys_column",
    "sys_field",
    "sys_reference",
    "sys_window",
];

pub async fn proxy_shape(
    Query(params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
    SharedStore(config): SharedStore<SystemConfig>,
) -> AppResult<Response> {
    let upstream = electric_url(&ctx, &config).await.ok_or_else(|| {
        // Same status and intent as the original: the client falls back to the
        // plain HTTP API when Electric is not deployed.
        AppError::ServiceUnavailable(
            "Electric upstream not configured (set electric_url on the System Configuration \
             screen or ELECTRIC_URL in the environment); client should use HTTP API fallback"
                .to_string(),
        )
    })?;

    let table = params.get("table").map(String::as_str).unwrap_or_default();
    if !ALLOWED_SYS_TABLES.contains(&table) {
        return Err(AppError::Forbidden("forbidden".to_string()));
    }

    let role = params.get("role").map(String::as_str).unwrap_or("user");
    let where_clause = role_where_clause(role)?;

    // Forward every parameter except `role`, which is replaced by the
    // server-generated `where`. A client-supplied `where` is also dropped —
    // otherwise it would override the scoping entirely.
    let mut forwarded: Vec<(String, String)> = params
        .iter()
        .filter(|(key, _)| key.as_str() != "role" && key.as_str() != "where")
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect();
    forwarded.push(("where".to_string(), where_clause));

    let response = reqwest::Client::new()
        .get(format!("{upstream}/v1/shape"))
        .query(&forwarded)
        .send()
        .await
        .map_err(|err| {
            crate::log_event!(jobs_upstream_unreachable, upstream = "electric", error = %err);
            AppError::ServiceUnavailable("Electric upstream unreachable".to_string())
        })?;

    let status = StatusCode::from_u16(response.status().as_u16())
        .unwrap_or(StatusCode::BAD_GATEWAY);

    // Electric's long-polling headers carry the shape cursor; the client cannot
    // resume without them, so they are passed through rather than dropped.
    let mut builder = Response::builder().status(status);
    for name in [
        "content-type",
        "electric-handle",
        "electric-offset",
        "electric-schema",
        "electric-cursor",
        "electric-up-to-date",
        "cache-control",
        "etag",
    ] {
        if let Some(value) = response.headers().get(name) {
            builder = builder.header(name, value);
        }
    }

    let bytes = response
        .bytes()
        .await
        .map_err(|err| AppError::Internal(err.into()))?;

    builder
        .body(Body::from(bytes))
        .map_err(|err| AppError::Internal(err.into()))
}

pub fn routes() -> Routes {
    Routes::new().prefix("v1/shape").add("/", get(proxy_shape))
}

/// Where Electric is, if anywhere.
///
/// A `sys_system` row first, the app's own settings block after it, so the
/// upstream can be pointed somewhere new from the admin screen without a
/// restart. Empty in both means the proxy is off, which is the default and is
/// reported as 503 rather than as an error.
async fn electric_url(ctx: &AppContext, config: &SystemConfig) -> Option<String> {
    config
        .get_optional(ctx.config.settings.as_ref(), "electric_url")
        .await
}

/// Map a role to the WHERE clause applied to every `sys_` shape.
///
/// Same clauses as the TypeScript original; the difference is that the role is
/// validated before it reaches the string (see the module comment).
fn role_where_clause(role: &str) -> AppResult<String> {
    if role.is_empty()
        || !role
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
    {
        return Err(AppError::BadRequest("Invalid role".to_string()));
    }

    Ok(if role == "admin" || role == "superuser" {
        "is_active = true".to_string()
    } else {
        format!("is_active = true AND (allowed_roles IS NULL OR allowed_roles @> ARRAY['{role}']::text[])")
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn admins_see_every_active_row() {
        assert_eq!(role_where_clause("admin").unwrap(), "is_active = true");
        assert_eq!(role_where_clause("superuser").unwrap(), "is_active = true");
    }

    #[test]
    fn ordinary_roles_get_the_membership_clause() {
        assert_eq!(
            role_where_clause("nurse").unwrap(),
            "is_active = true AND (allowed_roles IS NULL OR allowed_roles @> ARRAY['nurse']::text[])"
        );
    }

    #[test]
    fn injection_attempts_are_rejected_not_interpolated() {
        // This is the payload that defeats the TypeScript version's clause.
        assert!(role_where_clause("x'] OR true --").is_err());
        assert!(role_where_clause("a' OR '1'='1").is_err());
        assert!(role_where_clause("").is_err());
        // Legitimate role shapes still pass.
        assert!(role_where_clause("read-only_2").is_ok());
    }

    #[test]
    fn allow_list_matches_the_typescript_set() {
        assert!(ALLOWED_SYS_TABLES.contains(&"sys_field"));
        assert!(!ALLOWED_SYS_TABLES.contains(&"sys_user"));
        assert!(!ALLOWED_SYS_TABLES.contains(&"bus_customer"));
    }
}

//! Background jobs — enqueue one, see what the queue holds, cancel a kind.
//!
//! Generated: {{now}}
//! Project: {{project.name}}
//!
//! `app.rs` has always registered three workers — email, report, sync — and
//! there was no way to enqueue any of them and no way to see whether one ran.
//! Three workers nobody can reach is a dangling half-feature: the code is
//! carried, compiled and connected, and does nothing.
//!
//! **What the queue can answer depends on the mode**, and this says so rather
//! than pretending otherwise. `config/*.yaml` sets `workers.mode`:
//!
//! * `BackgroundQueue` — Loco's Postgres queue. Jobs are rows in
//!   `pg_loco_queue`, so listing and cancelling mean something. Production.
//! * `BackgroundAsync` — the job is spawned in-process. It runs, but nothing
//!   records it, so there is nothing to list. Development.
//! * `ForegroundBlocking` — the job runs inline before the response. Tests.
//!
//! Enqueueing works in all three; listing reports `queueBacked: false` in the
//! other two rather than an empty list that looks like "nothing ran".

use axum::{
    extract::{Path, Query, State},
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::prelude::*;
use serde_json::{json, Value};
use std::collections::HashMap;

use crate::errors::{AppError, AppResult};
use crate::workers::{
    email::{EmailArgs, EmailWorker},
    report::{ReportArgs, ReportWorker},
    sync::{SyncArgs, SyncWorker},
};

/// The worker kinds this backend registers, as the URL spells them.
const KINDS: [&str; 3] = ["email", "report", "sync"];

/// `POST /api/jobs/{kind}` — enqueue one job.
///
/// The body is the worker's own argument struct. It is deserialised into that
/// struct rather than passed through as JSON, so a payload missing a field the
/// worker needs is refused here — where the caller sees it — instead of at the
/// far end of a queue, where a deserialisation failure is a log line.
#[utoipa::path(
    post, path = "/api/jobs/{kind}", tag = "jobs",
    security(("bearer" = [])),
    params(("kind" = String, Path, description = "`email`, `report` or `sync`")),
    request_body(content = serde_json::Value, description = "The worker's arguments"),
    responses(
        (status = 202, description = "`{ id, kind, mode }` — accepted for processing"),
        (status = 400, description = "Unknown kind, or arguments the worker cannot use"),
    ),
)]
pub async fn enqueue(
    _auth: auth::JWT,
    Path(kind): Path<String>,
    State(ctx): State<AppContext>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    let bad_args = |err: serde_json::Error| AppError::Validation {
        message: "Validation failed".to_string(),
        errors: vec![format!("{kind} job arguments: {err}")],
    };

    let id = match kind.as_str() {
        "email" => {
            let args: EmailArgs = serde_json::from_value(payload).map_err(bad_args)?;
            EmailWorker::perform_later(&ctx, args).await
        }
        "report" => {
            let args: ReportArgs = serde_json::from_value(payload).map_err(bad_args)?;
            ReportWorker::perform_later(&ctx, args).await
        }
        "sync" => {
            let args: SyncArgs = serde_json::from_value(payload).map_err(bad_args)?;
            SyncWorker::perform_later(&ctx, args).await
        }
        other => {
            return Err(AppError::BadRequest(format!(
                "unknown job kind '{other}'; this backend registers: {}",
                KINDS.join(", ")
            )))
        }
    }
    .map_err(|err| AppError::Internal(anyhow::anyhow!("enqueueing {kind}: {err}")))?;

    // 202, not 201: in queue mode nothing has happened yet, and saying
    // "created" about work that has not run is the kind of small lie that
    // makes a client stop polling.
    Ok((
        StatusCode::ACCEPTED,
        Json(json!({ "id": id, "kind": kind, "mode": worker_mode(&ctx) })),
    )
        .into_response())
}

/// `GET /api/jobs?status=&limit=` — what the queue holds.
#[utoipa::path(
    get, path = "/api/jobs", tag = "jobs",
    security(("bearer" = [])),
    params(
        ("status" = Option<String>, Query, description = "`queued`, `processing`, `completed`, `failed` or `cancelled`"),
        ("limit" = Option<i64>, Query, description = "Page size, clamped to 1..=500 (default 100)"),
    ),
    responses((status = 200, description = "`{ data, meta }`; `meta.queueBacked` is false when the mode keeps no record")),
)]
pub async fn list(
    _auth: auth::JWT,
    Query(params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let limit = params
        .get("limit")
        .and_then(|value| value.parse::<i64>().ok())
        .unwrap_or(100)
        .clamp(1, 500);
    let status = params.get("status").filter(|value| !value.is_empty());

    // Loco's Postgres queue owns this table. Reading it directly rather than
    // through `Queue::dump`, which writes a file — a listing endpoint should
    // not touch the filesystem to answer a question the database already has.
    let rows = sqlx::query(
        r"SELECT id, name, status, run_at, created_at, updated_at, task_data
            FROM pg_loco_queue
           WHERE ($1::text IS NULL OR status = $1)
           ORDER BY created_at DESC
           LIMIT $2",
    )
    .bind(status)
    .bind(limit)
    .fetch_all(ctx.db.get_postgres_connection_pool())
    .await;

    // The table exists only under `BackgroundQueue`. Its absence is not an
    // error — it is the honest answer "this mode keeps no record", and an empty
    // list without that flag would read as "nothing has run".
    let (data, queue_backed) = match rows {
        Ok(rows) => (crate::services::row_json::rows_to_json(&rows), true),
        Err(_) => (Vec::new(), false),
    };

    Ok(Json(json!({
        "data": data,
        "meta": {
            "queueBacked": queue_backed,
            "mode": worker_mode(&ctx),
            "limit": limit,
            "kinds": KINDS,
        },
    }))
    .into_response())
}

/// `POST /api/jobs/{kind}/cancel` — cancel the queued jobs of one kind.
///
/// By kind, not by id, because that is what Loco's queue offers
/// (`Queue::cancel_jobs` takes a job *name*). Pretending to cancel one job by
/// giving the route an id it then ignored would be worse than the honest shape.
#[utoipa::path(
    post, path = "/api/jobs/{kind}/cancel", tag = "jobs",
    security(("bearer" = [])),
    params(("kind" = String, Path, description = "`email`, `report` or `sync`")),
    responses(
        (status = 200, description = "`{ cancelled: <kind> }`"),
        (status = 400, description = "Unknown kind"),
        (status = 503, description = "This worker mode has no queue to cancel from"),
    ),
)]
pub async fn cancel(
    _auth: auth::JWT,
    Path(kind): Path<String>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    if !KINDS.contains(&kind.as_str()) {
        return Err(AppError::BadRequest(format!(
            "unknown job kind '{kind}'; this backend registers: {}",
            KINDS.join(", ")
        )));
    }

    let Some(queue) = ctx.queue_provider.as_ref() else {
        return Err(AppError::ServiceUnavailable(format!(
            "worker mode is {} — there is no queue to cancel from. Set workers.mode to \
             BackgroundQueue in config/*.yaml.",
            worker_mode(&ctx)
        )));
    };

    // Loco names a job after its worker type, not after the URL segment.
    let job_name = match kind.as_str() {
        "email" => "EmailWorker",
        "report" => "ReportWorker",
        _ => "SyncWorker",
    };
    queue
        .cancel_jobs(job_name)
        .await
        .map_err(|err| AppError::Internal(anyhow::anyhow!("cancelling {kind} jobs: {err}")))?;

    Ok(Json(json!({ "cancelled": kind, "jobName": job_name })).into_response())
}

/// The configured worker mode, as a string the client can show.
fn worker_mode(ctx: &AppContext) -> String {
    format!("{:?}", ctx.config.workers.mode)
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("jobs")
        .add("/", get(list))
        // Static-looking segments are all worker kinds, so there is no
        // ambiguity to order around — but cancel is added first anyway, since
        // `/{kind}/cancel` and `/{kind}` are different arities.
        .add("/{kind}/cancel", post(cancel))
        .add("/{kind}", post(enqueue))
}

//! `/api/me` — what the signed-in caller is allowed to see.
//!
//! Two consumers, both of which break without it:
//!
//! * The dashboard builds its navigation from `windows`, so an empty or absent
//!   response renders a signed-in user an empty app.
//! * The stack-agnostic `tests/` harness probes `/api/me/health` for readiness
//!   and asserts on `/api/me/permissions` in the users-and-roles suite, so this
//!   is part of the cross-stack contract (§9), not a convenience.
//!
//! Permissions are read from `sys_access`, which is the Compiere model: a role
//! is granted or excluded per window, and a *master* role skips the table
//! entirely. Deriving them here rather than storing a flattened copy means an
//! administrator's grant takes effect on the next request.

use axum::{
    extract::State,
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::prelude::*;
use serde_json::{json, Value};
use sqlx::{PgPool, Row};

use crate::errors::AppResult;
use crate::models::_entities::users;
use crate::services::authz::{self, Principal};
use crate::services::system_config::SystemConfig;

/// `GET /api/me/health` — liveness for a caller that has not signed in.
///
/// Deliberately unauthenticated and deliberately not `/_health`: the test
/// harness and any reverse proxy in front of the app probe the API prefix, and
/// a probe that needs a token cannot tell "starting up" from "not logged in".
#[utoipa::path(
    get, path = "/api/me/health", tag = "auth",
    responses((status = 200, description = "`{ status, database, name, description, version }` — the app is up, whether its database answers, and how the app identifies itself")),
)]
pub async fn health(
    State(ctx): State<AppContext>,
    SharedStore(config): SharedStore<SystemConfig>,
) -> AppResult<Response> {
    // A connection check, not just a process check — the app answers requests
    // long before it can serve one, and reporting healthy in that window is
    // what makes a deploy look successful while every request 500s.
    let pool = ctx.db.get_postgres_connection_pool();
    let database = sqlx::query_scalar::<_, i32>("SELECT 1")
        .fetch_one(pool)
        .await
        .is_ok();

    // The application's own name and purpose, resolved through `sys_system` so
    // renaming it is an edit on the admin screen rather than a regeneration.
    // They sit on the probe because that is the one endpoint a client can read
    // before signing in, and the sidebar needs the name on the login page.
    //
    // Neither is a secret: the name is rendered to anyone who opens the app,
    // and the description is the model's own summary, which the generated
    // manual publishes. A sensitive value never reaches here — `is_sensitive`
    // rows are not read by this handler at all.
    // The compiled defaults come from the crate manifest rather than from a
    // second copy rendered into this file: `Cargo.toml` already carries both,
    // and a model name or description containing a quote would otherwise have
    // to be escaped correctly in two places instead of none.
    let settings = ctx.config.settings.as_ref();
    let name = config
        .get(settings, "app_name", env!("CARGO_PKG_NAME"))
        .await;
    let description = config
        .get(settings, "app_description", env!("CARGO_PKG_DESCRIPTION"))
        .await;

    Ok(Json(json!({
        "status": if database { "ok" } else { "degraded" },
        "database": database,
        "name": name,
        "description": description,
        "version": env!("CARGO_PKG_VERSION"),
    }))
    .into_response())
}

/// `GET /api/me` — the current user, same body as `/api/auth/me`.
#[utoipa::path(
    get, path = "/api/me", tag = "auth",
    security(("bearer" = [])),
    responses(
        (status = 200, description = "The signed-in user"),
        (status = 401, description = "No or invalid token"),
    ),
)]
pub async fn current(
    auth: auth::JWTWithUser<users::Model>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let role = auth.user.role_name(&ctx.db).await;
    Ok(Json(json!({
        "user": crate::models::users::UserResponse::new(&auth.user, role)
    }))
    .into_response())
}

/// `GET /api/me/permissions` — role, master flag, and the windows to show.
#[utoipa::path(
    get, path = "/api/me/permissions", tag = "auth",
    security(("bearer" = [])),
    responses((status = 200, description = "Routes and operations this user may reach")),
)]
pub async fn permissions(
    auth: auth::JWTWithUser<users::Model>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let role = auth.user.role_name(&ctx.db).await;

    // The same resolution the request guards use, rather than a second query
    // that answers the same question differently. It used to read
    // `is_master_role` here with `.unwrap_or(false)`, which reports a failed
    // query as "holds no master role" — quietly demoting an administrator to
    // an empty dashboard, and indistinguishable from the real thing.
    let principal = authz::principal(pool, &auth.user).await?;

    Ok(Json(json!({
        "role": role,
        "isMaster": principal.is_master,
        "windows": granted_windows(pool, &principal).await?,
    }))
    .into_response())
}

/// `GET /api/me/dashboard` — the dashboard, scoped to this caller.
///
/// Everything the front page draws, in one request: the categories with the
/// entities inside them, the admin windows this caller may open, and who the
/// caller is as far as the dictionary is concerned.
///
/// **The entities are the ones this caller may actually read.** The dashboard
/// used to be built from `/api/sys/categories/with-entities`, which is an
/// unscoped dictionary read — so every account was offered a card for every
/// entity in the application, and the three gates then answered 403 on the ones
/// it did not hold. A dashboard that offers nine entities and refuses them
/// cannot be told from a broken one, and the reverse of the same mistake is the
/// one `services/authz.rs` already documents: hiding a window used to hide only
/// the menu entry. The menu and the API now answer from the same rows.
///
/// **Line items are not places to navigate to.** An entity with `parent:
/// <Parent>` gives the child no window of its own and puts its tab inside the
/// parent's at `tab_level` 1, so it is reached by opening a parent record. The
/// `NOT EXISTS` below reads that off `sys_tab` rather than re-deriving it, so
/// this screen and the detail screen cannot disagree about what a line item is.
///
/// It is on `/api/me` rather than `/api/sys` deliberately. The dictionary's
/// reads are open — the sign-in page builds its navigation from them before
/// anyone has a token — and a caller-scoped read sitting in that namespace
/// would be the one endpoint there that answers differently per caller.
#[utoipa::path(
    get, path = "/api/me/dashboard", tag = "auth",
    security(("bearer" = [])),
    responses(
        (status = 200, description = "`{ data, windows, role, isMaster }` — categories with the entities this caller may read"),
        (status = 401, description = "No or invalid token"),
    ),
)]
pub async fn dashboard(
    auth: auth::JWTWithUser<users::Model>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let role = auth.user.role_name(&ctx.db).await;
    let principal = authz::principal(pool, &auth.user).await?;

    let categories = sqlx::query(
        r"SELECT sys_category_id, name, code, description, icon, color, seq_no
            FROM sys_category
           WHERE COALESCE(is_active, true) = true
           ORDER BY seq_no NULLS LAST, name",
    )
    .fetch_all(pool)
    .await?;

    // Each entity is offered as the window it opens in: the screens label a
    // card, a menu entry and a heading with the window's own name, description,
    // help and icon, never with the dictionary table's. A table with no window
    // has no screen, so it is not offered.
    let tables = sqlx::query(
        r"SELECT * FROM (
             SELECT DISTINCT ON (t.sys_table_id)
                    t.*,
                    w.sys_window_id AS window_id,
                    w.name          AS window_name,
                    w.description   AS window_description,
                    w.help          AS window_help,
                    w.icon          AS window_icon
               FROM sys_table t
               JOIN sys_tab    tb ON tb.sys_table_id = t.sys_table_id AND tb.tab_level = 0
               JOIN sys_window w  ON w.sys_window_id = tb.sys_window_id
                                 AND COALESCE(w.is_active, true) = true
              WHERE COALESCE(t.is_active, true) = true
                AND t.table_name LIKE 'bus\_%'
                AND NOT EXISTS (
                      SELECT 1 FROM sys_tab tl
                       WHERE tl.sys_table_id = t.sys_table_id
                         AND tl.tab_level > 0)
              ORDER BY t.sys_table_id, tb.seq_no NULLS LAST
           ) entity
           ORDER BY entity.window_name",
    )
    .fetch_all(pool)
    .await?;
    let tables: Vec<Value> = crate::services::row_json::rows_to_json(&tables);

    let candidates: Vec<String> = tables
        .iter()
        .filter_map(|t| t.get("table_name").and_then(Value::as_str))
        .map(ToString::to_string)
        .collect();
    let readable = authz::readable_tables(pool, &principal, &candidates).await?;
    let visible: Vec<&Value> = tables
        .iter()
        .filter(|t| {
            t.get("table_name")
                .and_then(Value::as_str)
                .is_some_and(|name| readable.iter().any(|r| r == name))
        })
        .collect();

    let mut groups: Vec<Value> = Vec::with_capacity(categories.len() + 1);
    let mut claimed: Vec<String> = Vec::new();

    for category in &categories {
        let mut group = crate::services::row_json::row_to_json(category);
        let id = group
            .get("sys_category_id")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string();

        let entities: Vec<Value> = visible
            .iter()
            .filter(|t| t.get("sys_category_id").and_then(Value::as_str) == Some(id.as_str()))
            .map(|t| (*t).clone())
            .collect();
        for entity in &entities {
            if let Some(name) = entity.get("table_name").and_then(Value::as_str) {
                claimed.push(name.to_string());
            }
        }

        // A category whose every entity belongs to another role is not an empty
        // category, it is somebody else's — and a heading over nothing tells a
        // scoped reader nothing they can act on. An administrator is looking at
        // the dictionary itself, where an empty category is one waiting to be
        // filled, so for them it stays.
        if entities.is_empty() && !principal.is_master {
            continue;
        }

        if let Some(object) = group.as_object_mut() {
            object.insert("entities".into(), Value::Array(entities));
        }
        groups.push(group);
    }

    let uncategorised: Vec<Value> = visible
        .iter()
        .filter(|t| {
            t.get("table_name")
                .and_then(Value::as_str)
                .is_none_or(|name| !claimed.iter().any(|c| c == name))
        })
        .map(|t| (*t).clone())
        .collect();

    // Always last, whatever it is called: an entity nobody has filed is still
    // an entity, and leaving it out would make it invisible until an
    // administrator got round to categorising it.
    if !uncategorised.is_empty() {
        groups.push(json!({
            "sys_category_id": Value::Null,
            "name": "Uncategorised",
            "code": "UNCATEGORISED",
            "description": Value::Null,
            "icon": Value::Null,
            "color": Value::Null,
            "entities": uncategorised,
        }));
    }

    Ok(Json(json!({
        "data": groups,
        "windows": granted_windows(pool, &principal).await?,
        "role": role,
        "isMaster": principal.is_master,
    }))
    .into_response())
}

/// The windows this principal may open, as the screens render them.
///
/// Shared by `/api/me/permissions` and `/api/me/dashboard` so the two cannot
/// disagree about what a caller may reach — they are the same question asked by
/// two screens, and answering it twice is how one of them comes to show a
/// window the other hides.
///
/// A master role sees every window; anyone else sees what `sys_access` grants
/// and has not excluded. `is_read_only` rides along so a window can be rendered
/// without its write affordances.
async fn granted_windows(pool: &PgPool, principal: &Principal) -> AppResult<Vec<Value>> {
    let rows = if principal.is_master {
        sqlx::query(
            r"SELECT w.sys_window_id, w.name, w.description, w.icon, w.entity_type,
                     false AS is_read_only,
                     (SELECT t.table_name
                        FROM sys_tab  tb
                        JOIN sys_table t ON t.sys_table_id = tb.sys_table_id
                       WHERE tb.sys_window_id = w.sys_window_id
                       ORDER BY tb.seq_no NULLS LAST
                       LIMIT 1) AS table_name
                FROM sys_window w
               WHERE COALESCE(w.is_active, true) = true
               ORDER BY w.name",
        )
        .fetch_all(pool)
        .await?
    } else {
        // No dictionary identity means no roles, so no grants — and no query to
        // run, because binding a NULL user id would match nothing anyway.
        let Some(sys_user_id) = principal.sys_user_id else {
            return Ok(Vec::new());
        };
        sqlx::query(
            r"SELECT DISTINCT ON (w.sys_window_id)
                     w.sys_window_id, w.name, w.description, w.icon, w.entity_type,
                     COALESCE(a.is_read_only, false) AS is_read_only,
                     (SELECT t.table_name
                        FROM sys_tab  tb
                        JOIN sys_table t ON t.sys_table_id = tb.sys_table_id
                       WHERE tb.sys_window_id = w.sys_window_id
                       ORDER BY tb.seq_no NULLS LAST
                       LIMIT 1) AS table_name
                FROM sys_window w
                JOIN sys_access    a ON a.sys_window_id = w.sys_window_id
                JOIN sys_user_roles ur ON ur.sys_role_id = a.sys_role_id
               WHERE ur.sys_user_id = $1
                 AND COALESCE(w.is_active, true) = true
                 AND COALESCE(a.is_active, true) = true
                 AND COALESCE(a.is_exclude, false) = false
               ORDER BY w.sys_window_id, a.is_read_only
             ",
        )
        .bind(sys_user_id)
        .fetch_all(pool)
        .await?
    };

    Ok(rows
        .iter()
        .map(|row| {
            let entity_type: Option<String> = row.try_get("entity_type").ok().flatten();
            let description: Option<String> = row.try_get("description").ok().flatten();
            let table_name: Option<String> = row.try_get("table_name").ok().flatten();
            let is_system = entity_type.as_deref() == Some("S");

            json!({
                "sys_window_id": row
                    .try_get::<uuid::Uuid, _>("sys_window_id")
                    .ok()
                    .map(|id| id.to_string()),
                "name": row.try_get::<Option<String>, _>("name").ok().flatten(),
                "route": route_for(is_system, description.as_deref(), table_name.as_deref()),
                "icon": row.try_get::<Option<String>, _>("icon").ok().flatten(),
                "category": if is_system { "admin" } else { "business" },
                "is_read_only": row
                    .try_get::<Option<bool>, _>("is_read_only")
                    .ok()
                    .flatten()
                    .unwrap_or(false),
            })
        })
        .collect())
}

/// Where clicking a window takes you.
///
/// System windows store their route in `description` — that is how the
/// dictionary seed writes them, because an admin screen is a hand-built page
/// with no `bus_` table behind it. A business window is named by its first
/// tab's table, minus the `bus_` prefix, which is exactly the segment
/// `/api/bus/{entity}` accepts.
fn route_for(is_system: bool, description: Option<&str>, table_name: Option<&str>) -> Option<String> {
    if is_system {
        return description
            .filter(|d| d.starts_with('/'))
            .map(ToString::to_string);
    }
    let table = table_name?;
    Some(format!("/{}", table.strip_prefix("bus_").unwrap_or(table)))
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("me")
        // `/health` before `/` so the readiness probe never needs a token.
        .add("/health", get(health))
        .add("/", get(current))
        .add("/permissions", get(permissions))
        .add("/dashboard", get(dashboard))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn system_windows_route_to_their_stored_path() {
        assert_eq!(
            route_for(true, Some("/admin/rules"), None).as_deref(),
            Some("/admin/rules")
        );
        // A system window whose description is prose, not a path, has no route
        // rather than a broken one.
        assert_eq!(route_for(true, Some("Manage rules"), None), None);
    }

    #[test]
    fn business_windows_route_by_their_table() {
        assert_eq!(
            route_for(false, Some("Manage Compound records"), Some("bus_compound")).as_deref(),
            Some("/compound")
        );
        // A window with no tab has nowhere to go.
        assert_eq!(route_for(false, None, None), None);
    }
}

