//! One record's trail and its notes.
//!
//! Generated: {{now}}
//! Project: {{project.name}}
//!
//! Two things a person looking at a record wants that the CRUD routes cannot
//! give them: what has happened to it, and what colleagues have said about it.
//!
//! **Why not `/api/audit?entity_id=`.** The audit routes are the compliance
//! surface — the whole trail, every table, plus chain verification — and they
//! are administrator-only for good reason. "What happened to *this* invoice" is
//! an ordinary question for anyone who may read invoices, so it is gated on that
//! entity's own `read` rather than on being an administrator. Same rows, a
//! narrower question, a proportionate permission.
//!
//! **Why notes are not audit entries.** `audit_log` records what the system
//! observed and must not be editable; a note is somebody's sentence about the
//! same record. Putting them in one table would make the history writable,
//! which is the one thing an audit trail may not be. `sys_note` is append-only
//! — no update path, no delete path — because a note that can be quietly
//! rewritten is worth about as much as a conversation nobody remembers.

use axum::{
    extract::{Path, Query, State},
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::prelude::*;
use serde_json::{json, Value};
use std::collections::HashMap;

use crate::errors::{AppError, AppResult};
use crate::models::_entities::users;
use crate::services::authz;
use crate::services::dictionary::DictionaryCache;

/// Resolve the entity and check the caller may read it.
///
/// The dictionary resolves the name, so `/api/records/compound/…` and
/// `/api/records/bus_compound/…` both work and both land on the physical table
/// the guard is asked about — the same resolution `/api/bus/*` does, and the
/// reason there is no second copy of the pluralise-the-URL bypass class here.
async fn readable_table(
    ctx: &AppContext,
    dictionary: &DictionaryCache,
    user: &users::Model,
    entity: &str,
) -> AppResult<String> {
    let table = dictionary.resolve(entity).await?;
    let pool = ctx.db.get_postgres_connection_pool();
    let principal = authz::principal(pool, user).await?;
    authz::require_operation(pool, &principal, table.as_str(), authz::Operation::Read).await?;
    Ok(table.as_str().to_string())
}

/// `GET /api/records/{entity}/{id}/history` — the audit trail for one record.
#[utoipa::path(
    get, path = "/api/records/{entity}/{id}/history", tag = "records",
    security(("bearer" = [])),
    params(
        ("entity" = String, Path, description = "Dictionary table or entity name"),
        ("id" = String, Path, description = "Record id"),
        ("limit" = Option<i64>, Query, description = "Page size, clamped to 1..=500 (default 100)"),
    ),
    responses(
        (status = 200, description = "`{ data, meta }` — entries newest first"),
        (status = 403, description = "The caller may not read this entity"),
        (status = 404, description = "No such entity in the dictionary"),
    ),
)]
pub async fn history(
    auth: auth::JWTWithUser<users::Model>,
    Path((entity, id)): Path<(String, String)>,
    Query(params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
) -> AppResult<Response> {
    let table = readable_table(&ctx, &dictionary, &auth.user, &entity).await?;
    let limit = params
        .get("limit")
        .and_then(|value| value.parse::<i64>().ok())
        .unwrap_or(100)
        .clamp(1, 500);

    let pool = ctx.db.get_postgres_connection_pool();
    let total: i64 = sqlx::query_scalar(
        "SELECT COUNT(*) FROM audit_log WHERE entity_type = $1 AND entity_id = $2",
    )
    .bind(&table)
    .bind(&id)
    .fetch_one(pool)
    .await?;

    let rows = sqlx::query(
        r"SELECT * FROM audit_log
           WHERE entity_type = $1 AND entity_id = $2
           ORDER BY timestamp DESC
           LIMIT $3",
    )
    .bind(&table)
    .bind(&id)
    .bind(limit)
    .fetch_all(pool)
    .await?;

    Ok(Json(json!({
        "data": crate::services::row_json::rows_to_json(&rows),
        "meta": { "total": total, "limit": limit, "entity": table, "recordId": id },
    }))
    .into_response())
}

/// `GET /api/records/{entity}/{id}/notes` — what people have said, newest first.
#[utoipa::path(
    get, path = "/api/records/{entity}/{id}/notes", tag = "records",
    security(("bearer" = [])),
    params(
        ("entity" = String, Path, description = "Dictionary table or entity name"),
        ("id" = String, Path, description = "Record id"),
    ),
    responses(
        (status = 200, description = "`[{ id, note, userName, userEmail, createdAt }]`"),
        (status = 403, description = "The caller may not read this entity"),
    ),
)]
pub async fn notes(
    auth: auth::JWTWithUser<users::Model>,
    Path((entity, id)): Path<(String, String)>,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
) -> AppResult<Response> {
    let table = readable_table(&ctx, &dictionary, &auth.user, &entity).await?;

    let rows = sqlx::query(
        r"SELECT * FROM sys_note
           WHERE table_name = $1 AND record_id = $2
           ORDER BY created_at DESC",
    )
    .bind(&table)
    .bind(&id)
    .fetch_all(ctx.db.get_postgres_connection_pool())
    .await?;

    Ok(Json(crate::services::row_json::rows_to_json(&rows)).into_response())
}

/// `POST /api/records/{entity}/{id}/notes` — add one.
///
/// Reading the record is enough to comment on it. Requiring write access would
/// silence exactly the people worth hearing from — a reviewer who may look at a
/// batch record and not change it is the one with something to say about it.
#[utoipa::path(
    post, path = "/api/records/{entity}/{id}/notes", tag = "records",
    security(("bearer" = [])),
    params(
        ("entity" = String, Path, description = "Dictionary table or entity name"),
        ("id" = String, Path, description = "Record id"),
    ),
    request_body(content = serde_json::Value, description = "`{ \"note\": \"…\" }`"),
    responses(
        (status = 201, description = "The stored note"),
        (status = 400, description = "Empty or missing `note`"),
        (status = 403, description = "The caller may not read this entity"),
    ),
)]
pub async fn add_note(
    auth: auth::JWTWithUser<users::Model>,
    Path((entity, id)): Path<(String, String)>,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    let table = readable_table(&ctx, &dictionary, &auth.user, &entity).await?;

    let note = payload
        .get("note")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|note| !note.is_empty())
        .ok_or_else(|| AppError::Validation {
            message: "Validation failed".to_string(),
            errors: vec!["'note' is required".to_string()],
        })?;

    // The author is taken from the token, never from the body. A note whose
    // attribution the caller chooses is not attribution.
    let row = sqlx::query(
        r"INSERT INTO sys_note (
               sys_note_id, table_name, record_id, note, user_id, user_name, user_email, created_at)
           VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, $6, NOW())
           RETURNING *",
    )
    .bind(&table)
    .bind(&id)
    .bind(note)
    .bind(auth.user.sys_user_id.map(|id| id.to_string()))
    .bind(&auth.user.name)
    .bind(&auth.user.email)
    .fetch_one(ctx.db.get_postgres_connection_pool())
    .await?;

    let stored = crate::services::row_json::rows_to_json(std::slice::from_ref(&row));
    Ok((
        StatusCode::CREATED,
        Json(stored.into_iter().next().unwrap_or(Value::Null)),
    )
        .into_response())
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("records")
        .add("/{entity}/{id}/history", get(history))
        .add("/{entity}/{id}/notes", get(notes))
        .add("/{entity}/{id}/notes", post(add_note))
}

//! The questions the model declared in `reports`, and the queries that
//! answer them.
//!
//! Each row in `sys_report` carries SQL authored in the model document (`reports`).
//! Running one is the only place in this application where stored text becomes
//! a statement, so most of what follows is about that.
//!
//! Not to be confused with the report *designs* under `/api/sys/report-designs`,
//! which render one record as a printable document. This is analysis over the
//! whole database.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

use axum::{
    extract::{Path, State},
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::prelude::*;
use serde_json::{json, Value};
use sqlx::{AssertSqlSafe, Column, Row};
use std::time::Instant;

use crate::errors::{AppError, AppResult};
use crate::services::row_json::row_to_json;

/// The most rows a report will return.
///
/// A report is a question a person reads, not an export. A model is free to
/// declare a query with no LIMIT — most do, because the interesting ones are
/// already narrowed by their WHERE clause — and on a seeded database that is
/// fine. On a real one, "every row of bus_transaction" is a query that ends the
/// tab rather than answering anything. The cap is applied as an outer LIMIT so
/// the report's own ordering still decides *which* rows, and the response says
/// when it bit.
const MAX_ROWS: i64 = 5000;

/// A report may only read, checked again here.
///
/// The generator refuses a non-SELECT at compile time, so a statement that is
/// not a query cannot reach `seed/reports.sql`. This is the second check, and
/// it is not redundant: `sys_report` is an ordinary table, and anything that
/// can write to it — a later migration, a restored backup, an operator with
/// database access — could otherwise put a statement here that this handler
/// would run with the application's own credentials.
fn assert_read_only(text: &str) -> Result<(), AppError> {
    let body = strip_trailing_semicolon(text);
    let head = body.trim_start().to_ascii_lowercase();
    let opens_a_query = ["with", "select"].iter().any(|keyword| {
        head.strip_prefix(keyword).is_some_and(|rest| {
            // A query named `selection_of(...)` is not a SELECT.
            rest.chars()
                .next()
                .is_none_or(|ch| !ch.is_alphanumeric() && ch != '_')
        })
    });
    if !opens_a_query {
        return Err(AppError::BadRequest(
            "A report query must be a SELECT or a WITH query.".to_string(),
        ));
    }

    // A semicolon outside quotes means a second statement is hiding behind the
    // first: `SELECT 1; DROP TABLE bus_account` passes the test above.
    // Semicolons *inside* string literals are ordinary characters, so this
    // tracks quoting rather than searching for the byte.
    let chars: Vec<char> = body.chars().collect();
    let mut quote: Option<char> = None;
    let mut index = 0;
    while index < chars.len() {
        let ch = chars[index];
        match quote {
            Some(open) => {
                if ch == open {
                    // Doubling is how both SQL quote styles escape themselves.
                    if chars.get(index + 1) == Some(&open) {
                        index += 1;
                    } else {
                        quote = None;
                    }
                }
            }
            None => {
                if ch == '\'' || ch == '"' {
                    quote = Some(ch);
                } else if ch == ';' {
                    return Err(AppError::BadRequest(
                        "A report query must be a single statement.".to_string(),
                    ));
                }
            }
        }
        index += 1;
    }
    Ok(())
}

fn strip_trailing_semicolon(sql: &str) -> &str {
    let trimmed = sql.trim_end();
    trimmed.strip_suffix(';').unwrap_or(trimmed).trim_end()
}

/// One report as the screen sees it — everything but the query.
///
/// `sql_text` is deliberately absent. The list feeds a menu; handing the query
/// to the browser would put the application's schema in front of anyone who can
/// open the reports page, and nothing on that screen needs it.
fn describe(row: &sqlx::postgres::PgRow) -> Value {
    json!({
        "id": row.get::<uuid::Uuid, _>("sys_report_id").to_string(),
        "name": row.get::<String, _>("name"),
        "title": row.get::<String, _>("title"),
        "entityName": row.get::<Option<String>, _>("entity_name"),
        "tableName": row.get::<Option<String>, _>("table_name"),
        "chart": row.get::<Option<String>, _>("chart"),
        "xAxis": row.get::<Option<String>, _>("x_axis"),
        "yAxis": row.get::<Option<String>, _>("y_axis"),
        "help": row.get::<Option<String>, _>("help"),
        "sortOrder": row.get::<i32, _>("sort_order"),
    })
}

const DESCRIBE_COLUMNS: &str = "sys_report_id, name, title, entity_name, table_name, chart, \
                                x_axis, y_axis, help, sort_order";

/// `GET /api/reports` — every report the model declared, in declaration order.
#[utoipa::path(
    get, path = "/api/reports", tag = "reports",
    security(("bearer" = [])),
    responses((status = 200, description = "The model's reports, without their queries")),
)]
pub async fn list(_auth: auth::JWT, State(ctx): State<AppContext>) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let rows = sqlx::query(AssertSqlSafe(format!(
        "SELECT {DESCRIBE_COLUMNS} FROM sys_report ORDER BY sort_order, name"
    )))
    .fetch_all(pool)
    .await
    .map_err(|err| AppError::Internal(anyhow::anyhow!("listing reports: {err}")))?;

    let described: Vec<Value> = rows.iter().map(describe).collect();
    Ok(Json(json!({ "data": described, "meta": { "total": described.len() } })).into_response())
}

/// `GET /api/reports/{name}` — one report, without its query.
#[utoipa::path(
    get, path = "/api/reports/{name}", tag = "reports",
    security(("bearer" = [])),
    params(("name" = String, Path, description = "The report's declared name")),
    responses(
        (status = 200, description = "The report's description"),
        (status = 404, description = "No report of that name"),
    ),
)]
pub async fn show(
    _auth: auth::JWT,
    Path(name): Path<String>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let row = sqlx::query(AssertSqlSafe(format!(
        "SELECT {DESCRIBE_COLUMNS} FROM sys_report WHERE name = $1"
    )))
    .bind(&name)
    .fetch_optional(pool)
    .await
    .map_err(|err| AppError::Internal(anyhow::anyhow!("reading report: {err}")))?
    .ok_or_else(|| AppError::NotFound(format!("No report named \"{name}\".")))?;

    Ok(Json(describe(&row)).into_response())
}

/// `GET /api/reports/{name}/run` — run a report and return its rows.
///
/// The query is wrapped rather than concatenated with a LIMIT: a model's query
/// may legitimately end in `ORDER BY`, `LIMIT`, a CTE or a comment, and
/// appending to any of those changes what it means. As a subquery it keeps
/// whatever it already says and the cap applies outside it.
#[utoipa::path(
    get, path = "/api/reports/{name}/run", tag = "reports",
    security(("bearer" = [])),
    params(("name" = String, Path, description = "The report's declared name")),
    responses(
        (status = 200, description = "`{ report, columns, rows, rowCount, truncated, durationMs }`"),
        (status = 400, description = "The stored query is not a single read, or it failed"),
        (status = 404, description = "No report of that name"),
    ),
)]
pub async fn run(
    _auth: auth::JWT,
    Path(name): Path<String>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let row = sqlx::query(AssertSqlSafe(format!(
        "SELECT {DESCRIBE_COLUMNS}, sql_text FROM sys_report WHERE name = $1"
    )))
    .bind(&name)
    .fetch_optional(pool)
    .await
    .map_err(|err| AppError::Internal(anyhow::anyhow!("reading report: {err}")))?
    .ok_or_else(|| AppError::NotFound(format!("No report named \"{name}\".")))?;

    let sql_text: String = row.get("sql_text");
    assert_read_only(&sql_text)?;

    let started = Instant::now();
    // One more than the cap, so a full page can be told from a truncated one
    // without a second count(*) over the same query.
    let capped = format!(
        "SELECT * FROM ({}) AS report_body LIMIT {}",
        strip_trailing_semicolon(&sql_text),
        MAX_ROWS + 1
    );

    let mut result = sqlx::query(AssertSqlSafe(capped))
        .fetch_all(pool)
        .await
        // The query came from the model, so a failure here is a defect in the
        // document rather than in the request. Say which report and what the
        // database said — an author cannot fix "500 Internal Server Error".
        .map_err(|err| AppError::BadRequest(format!("Report \"{name}\" failed: {err}")))?;

    let truncated = i64::try_from(result.len()).unwrap_or(i64::MAX) > MAX_ROWS;
    if truncated {
        result.truncate(usize::try_from(MAX_ROWS).unwrap_or(usize::MAX));
    }

    // The driver's column list is in the order the report's SELECT declares,
    // which is the order it renders in. This used to be read off the first row's
    // JSON keys, and a `serde_json::Map` is sorted: every report came back with
    // its columns alphabetical, so crm's "source, leads, qualified, converted"
    // rendered as "converted, leads, qualified, source".
    let columns: Vec<String> = result
        .first()
        .map(|row| {
            row.columns()
                .iter()
                .map(|column| column.name().to_string())
                .collect()
        })
        .unwrap_or_default();

    let rows: Vec<Value> = result.iter().map(row_to_json).collect();
    let duration_ms = u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX);

    Ok(Json(json!({
        "report": describe(&row),
        "columns": columns,
        "rows": rows,
        "rowCount": rows.len(),
        "truncated": truncated,
        "durationMs": duration_ms,
    }))
    .into_response())
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("reports")
        .add("/", get(list))
        // `{name}/run` before `{name}`: a static segment declared after a
        // parameter on the same level is shadowed by it.
        .add("/{name}/run", get(run))
        .add("/{name}", get(show))
}

//! Business-rule definitions — `sys_rule_definitions`.
//!
//! A rule is a GoRules JDM decision graph bound to an entity and a CRUD verb.
//! The promotion pipeline evaluates them on every business write; these routes
//! are the admin surface that authors them and the dry-run that lets an author
//! test one before it goes live.
//!
//! **The JSON here is camelCase, unlike everywhere else in this API.** The
//! rules screens were written against a NestJS controller that serialised its
//! DTOs with `class-transformer` defaults, so `entityName` / `ruleName` /
//! `jdmContent` / `isActive` are what the frontend reads and writes. Renaming
//! them to match the snake_case columns would be a contract break for no gain,
//! so the mapping lives here, in one place.

use axum::{
    extract::{Path, Query, State},
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::prelude::*;
use serde_json::{json, Map, Value};
use sqlx::Row;
use std::collections::HashMap;
use uuid::Uuid;

use crate::errors::{AppError, AppResult};
use crate::services::rules_engine::{RuleOperation, RulesEngine};

/// `GET /api/rules?entityName=&operation=&isActive=`
///
/// A bare array, not an envelope: the rules list is small, bounded by how many
/// rules a human has written, and the frontend types it as `Rule[]`.
#[utoipa::path(
    get, path = "/api/rules", tag = "rules",
    security(("bearer" = [])),
    params(("entityName" = Option<String>, Query, description = "Filter to one entity's rules")),
    responses((status = 200, description = "Rule definitions")),
)]
pub async fn list(
    _auth: auth::JWT,
    Query(params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();

    let entity = params.get("entityName").or_else(|| params.get("entity_name"));
    let operation = params.get("operation");
    let is_active = params
        .get("isActive")
        .or_else(|| params.get("is_active"))
        .and_then(|v| v.parse::<bool>().ok());

    let rows = sqlx::query(
        r"SELECT * FROM sys_rule_definitions
           WHERE ($1::text IS NULL OR entity_name = $1)
             AND ($2::text IS NULL OR operation   = $2)
             AND ($3::bool IS NULL OR is_active   = $3)
           ORDER BY entity_name, rule_name",
    )
    .bind(entity)
    .bind(operation)
    .bind(is_active)
    .fetch_all(pool)
    .await?;

    let rules: Vec<Value> = rows.iter().map(to_api).collect();
    Ok(Json(rules).into_response())
}

/// `GET /api/rules/{id}` — one rule definition.
#[utoipa::path(
    get, path = "/api/rules/{id}", tag = "rules",
    security(("bearer" = [])),
    params(("id" = String, Path, description = "Rule UUID")),
    responses(
        (status = 200, description = "The rule"),
        (status = 404, description = "No such rule"),
    ),
)]
pub async fn get_one(
    _auth: auth::JWT,
    Path(id): Path<Uuid>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let row = sqlx::query("SELECT * FROM sys_rule_definitions WHERE id = $1")
        .bind(id)
        .fetch_optional(pool)
        .await?
        .ok_or_else(|| AppError::NotFound(format!("Rule {id} not found")))?;

    Ok(Json(to_api(&row)).into_response())
}

#[utoipa::path(
    post, path = "/api/rules", tag = "rules",
    security(("bearer" = [])),
    request_body(content = serde_json::Value, description = "`{ entityName, ruleName, operation, jdmContent }` — jdmContent is a GoRules JDM decision graph"),
    responses(
        (status = 201, description = "The stored rule"),
        (status = 400, description = "Invalid JDM"),
    ),
)]
pub async fn create(
    _auth: auth::JWT,
    State(ctx): State<AppContext>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    let entity_name = required_str(&payload, "entityName")?;
    let rule_name = required_str(&payload, "ruleName")?;
    let jdm_content = required_str(&payload, "jdmContent")?;

    // Reject a graph that cannot be parsed at write time. Discovering it when a
    // business write triggers the rule means a user's save fails for a reason
    // that has nothing to do with what they typed.
    parse_jdm(&jdm_content)?;

    let operation = payload
        .get("operation")
        .and_then(Value::as_str)
        .unwrap_or("ALL");

    let pool = ctx.db.get_postgres_connection_pool();
    let row = sqlx::query(
        r"INSERT INTO sys_rule_definitions
            (entity_name, rule_name, operation, jdm_content, version, is_active)
          VALUES ($1, $2, $3, $4, 1, COALESCE($5, true))
          RETURNING *",
    )
    .bind(&entity_name)
    .bind(&rule_name)
    .bind(operation)
    .bind(&jdm_content)
    .bind(payload.get("isActive").and_then(Value::as_bool))
    .fetch_one(pool)
    .await?;

    Ok((StatusCode::CREATED, Json(to_api(&row))).into_response())
}

/// `PUT /api/rules/{id}` — edit in place, bumping `version`.
///
/// The version bump is what the rule cache keys on, so an edit takes effect on
/// the next evaluation without a restart.
/// `PUT`/`PATCH /api/rules/{id}` — change a rule.
#[utoipa::path(
    put, path = "/api/rules/{id}", tag = "rules",
    security(("bearer" = [])),
    params(("id" = String, Path, description = "Rule UUID")),
    request_body(content = serde_json::Value, description = "The rule fields to change"),
    responses(
        (status = 200, description = "The updated rule"),
        (status = 400, description = "Invalid JDM"),
        (status = 404, description = "No such rule"),
    ),
)]
pub async fn update(
    _auth: auth::JWT,
    Path(id): Path<Uuid>,
    State(ctx): State<AppContext>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    if let Some(jdm) = payload.get("jdmContent").and_then(Value::as_str) {
        parse_jdm(jdm)?;
    }

    let pool = ctx.db.get_postgres_connection_pool();
    let row = sqlx::query(
        r"UPDATE sys_rule_definitions
             SET entity_name = COALESCE($2, entity_name),
                 rule_name   = COALESCE($3, rule_name),
                 operation   = COALESCE($4, operation),
                 jdm_content = COALESCE($5, jdm_content),
                 is_active   = COALESCE($6, is_active),
                 version     = version + 1,
                 updated_at  = NOW()
           WHERE id = $1
           RETURNING *",
    )
    .bind(id)
    .bind(payload.get("entityName").and_then(Value::as_str))
    .bind(payload.get("ruleName").and_then(Value::as_str))
    .bind(payload.get("operation").and_then(Value::as_str))
    .bind(payload.get("jdmContent").and_then(Value::as_str))
    .bind(payload.get("isActive").and_then(Value::as_bool))
    .fetch_optional(pool)
    .await?
    .ok_or_else(|| AppError::NotFound(format!("Rule {id} not found")))?;

    Ok(Json(to_api(&row)).into_response())
}

/// `DELETE /api/rules/{id}` — deactivate, do not destroy.
///
/// Rules are referenced by audit entries explaining why a record was held, so
/// deleting the row would orphan that explanation. The admin UI's own copy
/// calls this "deactivate", which is what it does.
/// `DELETE /api/rules/{id}` — drop a rule.
#[utoipa::path(
    delete, path = "/api/rules/{id}", tag = "rules",
    security(("bearer" = [])),
    params(("id" = String, Path, description = "Rule UUID")),
    responses(
        (status = 204, description = "Deleted"),
        (status = 404, description = "No such rule"),
    ),
)]
pub async fn remove(
    _auth: auth::JWT,
    Path(id): Path<Uuid>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let result = sqlx::query(
        "UPDATE sys_rule_definitions SET is_active = false, updated_at = NOW() WHERE id = $1",
    )
    .bind(id)
    .execute(pool)
    .await?;

    if result.rows_affected() == 0 {
        return Err(AppError::NotFound(format!("Rule {id} not found")));
    }
    Ok(StatusCode::NO_CONTENT.into_response())
}

/// `POST /api/rules/evaluate` — a dry run against sample data.
///
/// Body: `{ entityName, operation, data, jdmContent? }`. With `jdmContent` the
/// unsaved draft in the editor is evaluated; without it, every active rule
/// stored for that entity and verb runs, which is what the record would
/// actually get. Nothing is written either way.
#[utoipa::path(
    post, path = "/api/rules/evaluate", tag = "rules",
    security(("bearer" = [])),
    request_body(content = serde_json::Value, description = "`{ entityName, operation, data, jdmContent? }`. With jdmContent the draft graph is evaluated; without it, the entity's stored rules are."),
    responses((status = 200, description = "`{ matched, results: [{ ruleId, matched, actions }] }`")),
)]
pub async fn evaluate(
    _auth: auth::JWT,
    State(ctx): State<AppContext>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    let entity_name = required_str(&payload, "entityName")?;
    let operation = match payload
        .get("operation")
        .and_then(Value::as_str)
        .unwrap_or("CREATE")
        .to_ascii_uppercase()
        .as_str()
    {
        "UPDATE" => RuleOperation::Update,
        "DELETE" => RuleOperation::Delete,
        _ => RuleOperation::Create,
    };
    let data: Map<String, Value> = payload
        .get("data")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();

    let engine = ctx
        .shared_store
        .get::<RulesEngine>()
        .ok_or_else(|| AppError::Internal(anyhow::anyhow!("rules engine not initialised")))?;

    let mut results = Vec::new();

    if let Some(draft) = payload.get("jdmContent").and_then(Value::as_str) {
        results.extend(
            engine
                .evaluate_jdm_str(&entity_name, draft, &data, operation, Some("draft"))
                .await,
        );
    } else {
        let pool = ctx.db.get_postgres_connection_pool();
        let stored = sqlx::query(
            r"SELECT rule_name, jdm_content FROM sys_rule_definitions
               WHERE entity_name = $1
                 AND is_active = true
                 AND (operation = $2 OR operation = 'ALL')
               ORDER BY rule_name",
        )
        .bind(&entity_name)
        .bind(operation.as_str().to_ascii_uppercase())
        .fetch_all(pool)
        .await?;

        for row in &stored {
            let rule_name: String = row.try_get("rule_name").unwrap_or_default();
            let jdm: String = row.try_get("jdm_content").unwrap_or_default();
            results.extend(
                engine
                    .evaluate_jdm_str(&entity_name, &jdm, &data, operation, Some(&rule_name))
                    .await,
            );
        }
    }

    let matched = results.iter().any(|r| r.matched);
    Ok(Json(json!({
        "entityName": entity_name,
        "operation": operation.as_str(),
        "matched": matched,
        "results": results,
    }))
    .into_response())
}

/// `POST /api/rules/validate` — is this JDM well-formed?
///
/// Separate from `evaluate` because the editor asks it on every keystroke,
/// against a document that is usually still being typed. Parsing is the whole
/// answer, so an invalid graph is a 200 with `valid: false` and the reason,
/// not a 400 — the client is asking a question, not making a mistake.
#[utoipa::path(
    post, path = "/api/rules/validate", tag = "rules",
    security(("bearer" = [])),
    request_body(content = serde_json::Value, description = "`{ jdmContent }` — the decision graph to check"),
    responses((status = 200, description = "`{ valid, errors }`; a malformed graph is a 200 with `valid: false`, not a 400")),
)]
pub async fn validate(_auth: auth::JWT, Json(payload): Json<Value>) -> AppResult<Response> {
    let content = required_str(&payload, "jdmContent")?;
    Ok(match parse_jdm(&content) {
        Ok(()) => Json(json!({ "valid": true, "isValid": true, "errors": [] })),
        Err(AppError::Validation { errors, .. }) => {
            Json(json!({ "valid": false, "isValid": false, "errors": errors }))
        }
        Err(other) => return Err(other),
    }
    .into_response())
}

/// `POST /api/rules/dry-run` — evaluate one stored rule against sample data.
///
/// Body: `{ ruleId, testData }`. `evaluate` runs everything that applies to an
/// entity; this runs exactly the rule you are looking at, which is what the
/// editor's test panel needs.
#[utoipa::path(
    post, path = "/api/rules/dry-run", tag = "rules",
    security(("bearer" = [])),
    request_body(content = serde_json::Value, description = "`{ ruleId, testData }`"),
    responses(
        (status = 200, description = "What that one rule decided about the sample data"),
        (status = 404, description = "No such rule"),
    ),
)]
pub async fn dry_run(
    _auth: auth::JWT,
    State(ctx): State<AppContext>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    let rule_id = payload
        .get("ruleId")
        .and_then(Value::as_str)
        .and_then(|v| Uuid::parse_str(v).ok())
        .ok_or_else(|| AppError::BadRequest("ruleId must be a UUID".to_string()))?;

    let pool = ctx.db.get_postgres_connection_pool();
    let row = sqlx::query(
        "SELECT entity_name, rule_name, operation, jdm_content FROM sys_rule_definitions WHERE id = $1",
    )
    .bind(rule_id)
    .fetch_optional(pool)
    .await?
    .ok_or_else(|| AppError::NotFound(format!("Rule {rule_id} not found")))?;

    let entity_name: String = row.try_get("entity_name").unwrap_or_default();
    let rule_name: String = row.try_get("rule_name").unwrap_or_default();
    let jdm: String = row.try_get("jdm_content").unwrap_or_default();
    let operation = match row
        .try_get::<Option<String>, _>("operation")
        .ok()
        .flatten()
        .unwrap_or_default()
        .to_ascii_uppercase()
        .as_str()
    {
        "UPDATE" => RuleOperation::Update,
        "DELETE" => RuleOperation::Delete,
        _ => RuleOperation::Create,
    };

    let data: Map<String, Value> = payload
        .get("testData")
        .or_else(|| payload.get("data"))
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();

    let engine = ctx
        .shared_store
        .get::<RulesEngine>()
        .ok_or_else(|| AppError::Internal(anyhow::anyhow!("rules engine not initialised")))?;

    let results = engine
        .evaluate_jdm_str(&entity_name, &jdm, &data, operation, Some(&rule_name))
        .await;

    Ok(Json(json!({
        "ruleId": rule_id.to_string(),
        "ruleName": rule_name,
        "entityName": entity_name,
        "matched": results.iter().any(|r| r.matched),
        "results": results,
    }))
    .into_response())
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("rules")
        // Static before the id capture, so `/rules/evaluate` is not read as a
        // rule whose id is the word "evaluate".
        .add("/evaluate", post(evaluate))
        .add("/validate", post(validate))
        .add("/dry-run", post(dry_run))
        .add("/entities", get(entities))
        .add("/migrate", post(migrate))
        .add("/", get(list))
        .add("/", post(create))
        .add("/{id}", get(get_one))
        .add("/{id}/history", get(history))
        .add("/{id}", put(update))
        .add("/{id}", patch(update))
        .add("/{id}", delete(remove))
}

/// `GET /api/rules/entities` — the tables that carry at least one rule.
///
/// The rules screen needs a list to filter by, and deriving it from the
/// dictionary would offer every table in the application — including the ones
/// nobody has written a rule for, which is most of them on a fresh install.
#[utoipa::path(
    get, path = "/api/rules/entities", tag = "rules",
    security(("bearer" = [])),
    responses(
        (status = 200, description = "`[{ entityName, ruleCount, activeCount }]`, ordered by table"),
        (status = 401, description = "No or invalid token"),
    ),
)]
pub async fn entities(_auth: auth::JWT, State(ctx): State<AppContext>) -> AppResult<Response> {
    let rows: Vec<(String, i64, i64)> = sqlx::query_as(
        r"SELECT entity_name,
                 COUNT(*),
                 COUNT(*) FILTER (WHERE is_active)
            FROM sys_rule_definitions
           GROUP BY entity_name
           ORDER BY entity_name",
    )
    .fetch_all(ctx.db.get_postgres_connection_pool())
    .await?;

    let entities: Vec<Value> = rows
        .into_iter()
        .map(|(entity_name, total, active)| {
            json!({ "entityName": entity_name, "ruleCount": total, "activeCount": active })
        })
        .collect();
    Ok(Json(entities).into_response())
}

/// `GET /api/rules/{id}/history` — the versions of one rule.
///
/// **Only the current version exists.** `sys_rule_definitions` stores one row
/// per rule and counts overwrites in `version`; the superseded documents are
/// not kept. So this returns a one-element array, and says so rather than
/// implying a history it does not have — keeping the old JDM would need a
/// history table, which is a schema decision nobody has asked for yet.
///
/// The route exists because the rules screen calls it, and a 404 there reads
/// as a broken rule rather than an absent feature.
#[utoipa::path(
    get, path = "/api/rules/{id}/history", tag = "rules",
    security(("bearer" = [])),
    params(("id" = String, Path, description = "Rule UUID")),
    responses(
        (status = 200, description = "`[rule]` — the current version, the only one stored"),
        (status = 404, description = "No such rule"),
    ),
)]
pub async fn history(
    _auth: auth::JWT,
    Path(id): Path<Uuid>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let row = sqlx::query("SELECT * FROM sys_rule_definitions WHERE id = $1")
        .bind(id)
        .fetch_optional(ctx.db.get_postgres_connection_pool())
        .await?
        .ok_or_else(|| AppError::NotFound(format!("Rule {id} not found")))?;

    Ok(Json(vec![to_api(&row)]).into_response())
}

/// `POST /api/rules/migrate` — re-apply the model's rules over what is stored.
///
/// `seed_rules` installs what is missing and leaves an administrator's edits
/// alone, which is what makes `cargo loco db seed` safe to re-run. That leaves
/// a gap: a model whose rule *changed* has no way to reach a database that
/// already holds the old version, short of dropping it.
///
/// This is that way. It applies the same `seed/rules.sql` inside a transaction
/// with `appwithai.rules_overwrite` set, which turns every statement's
/// conditional `DO UPDATE` on. One file, two policies; the JDM is not carried
/// twice.
///
/// Destructive by design and by request — an edit made in the admin editor is
/// replaced by what the model says. The response reports how many rows changed
/// so the caller can see what it cost.
#[utoipa::path(
    post, path = "/api/rules/migrate", tag = "rules",
    security(("bearer" = [])),
    responses(
        (status = 200, description = "`{ migrated, total, message }` — rows now matching the model"),
        (status = 401, description = "No or invalid token"),
    ),
)]
pub async fn migrate(_auth: auth::JWT, State(ctx): State<AppContext>) -> AppResult<Response> {
    use sea_orm::ConnectionTrait;

    let pool = ctx.db.get_postgres_connection_pool();
    let before: i64 = sqlx::query_scalar("SELECT COALESCE(SUM(version), 0) FROM sys_rule_definitions")
        .fetch_one(pool)
        .await
        .unwrap_or(0);

    // `SET LOCAL` rather than `SET`: the connection goes back to a pool
    // afterwards, and a session-level setting would leave the next request's
    // seed silently overwriting too.
    ctx.db
        .execute_unprepared(&format!(
            "BEGIN;\nSET LOCAL appwithai.rules_overwrite = 'on';\n{}\nCOMMIT;",
            crate::tasks::seed_rules::RULES_SQL
        ))
        .await?;

    let (after, total): (i64, i64) = sqlx::query_as(
        "SELECT COALESCE(SUM(version), 0), COUNT(*) FROM sys_rule_definitions",
    )
    .fetch_one(pool)
    .await?;

    // Every overwrite bumps `version` by one, so the difference is the number
    // of rules the model actually replaced — an install that changed nothing
    // reports zero rather than claiming to have migrated every row.
    let migrated = (after - before).max(0);
    Ok(Json(json!({
        "migrated": migrated,
        "total": total,
        "message": format!("Replaced {migrated} rule(s) with the model's version"),
    }))
    .into_response())
}

