fn truthy(value: Option<&String>) -> bool {
    matches!(value.map(String::as_str), Some("true" | "1" | "yes"))
}

/// `?limit` / `?page` (or `?offset`), clamped.
///
/// Returns `(limit, page, offset)`. A `page` beyond the end yields an empty
/// `data` with a truthful `meta.total`, which is what a table footer needs to
/// render "showing 0 of 137".
fn pagination_from(params: &HashMap<String, String>) -> (u64, u64, u64) {
    let limit = params
        .get("limit")
        .and_then(|v| v.parse::<u64>().ok())
        .filter(|v| *v > 0)
        .unwrap_or(DEFAULT_LIMIT);
    // `Ord::min`, spelled out: `ExprTrait` is in scope for the query builder and
    // also has a `min`, so the bare method call is ambiguous.
    let limit = Ord::min(limit, MAX_LIMIT);

    let page = params
        .get("page")
        .and_then(|v| v.parse::<u64>().ok())
        .filter(|v| *v > 0)
        .unwrap_or(1);

    // An explicit `offset` wins — the two are alternative spellings and a
    // caller that sends both means the more specific one.
    let offset = params
        .get("offset")
        .and_then(|v| v.parse::<u64>().ok())
        .unwrap_or_else(|| (page - 1) * limit);

    (limit, page, offset)
}

/// `?sort=` / `?orderBy=` with `?order=` / `?orderDir=`, falling back to the
/// registry's default. The column is verified against the live schema, so an
/// unknown one is a 400 rather than an interpolated identifier.
async fn ordering_from(
    pool: &PgPool,
    spec: &SysTable,
    params: &HashMap<String, String>,
) -> AppResult<(String, Order)> {
    let requested = params.get("sort").or_else(|| params.get("orderBy"));
    let column = match requested {
        Some(name) => verify_column(pool, spec.table, name).await?.0,
        // The registry's default is verified too. It is a hand-maintained
        // constant against a generated schema, and a stale entry there used to
        // 500 the whole resource — falling back to the primary key keeps the
        // endpoint answering while the log says exactly what to fix.
        None => match verify_column(pool, spec.table, spec.order_by).await {
            Ok((column, _)) => column,
            Err(_) => {
                crate::log_event!(
                    dictionary_column_absent,
                    table = spec.table,
                    column = spec.order_by
                );
                spec.pk.to_string()
            }
        },
    };

    let direction = params
        .get("order")
        .or_else(|| params.get("orderDir"))
        .map(String::as_str);
    let direction = if matches!(direction, Some("desc" | "DESC")) {
        Order::Desc
    } else {
        Order::Asc
    };

    Ok((column, direction))
}

/// Turn the query string into WHERE clauses.
///
/// Three shapes are accepted, because three are already in use:
///
/// * `?filter.{column}=` — explicit and strict; an unknown column is a 400.
/// * `?{column}=` — the shorthand every frontend call site uses. Unknown keys
///   are ignored rather than rejected, because callers append cache-busters and
///   UI state to these URLs and a 400 there would break a working screen.
/// * `?search=` / `?prefix=` — cross-column conveniences.
async fn conditions_from(
    pool: &PgPool,
    spec: &SysTable,
    params: &HashMap<String, String>,
) -> AppResult<Vec<Condition>> {
    let mut conditions = Vec::new();

    for (key, value) in params {
        if let Some(column) = key.strip_prefix("filter.") {
            let (column, _) = verify_column(pool, spec.table, column).await?;
            conditions.push(Condition::all().add(Expr::col(Alias::new(column)).eq(value.clone())));
            continue;
        }
        if RESERVED_PARAMS.contains(&key.as_str()) || key.starts_with('_') {
            continue;
        }

        // `?name=` on `sys_table` means the physical table name as often as the
        // display name — `useSysTable` passes `bus_compound`, the admin search
        // passes "Compound". Matching either is what the local PGlite query
        // (`WHERE table_name = $1`) and the admin UI both expect.
        if key == "name" && spec.table == "sys_table" {
            conditions.push(
                Condition::any()
                    .add(Expr::col(Alias::new("table_name")).eq(value.clone()))
                    .add(Expr::col(Alias::new("name")).eq(value.clone())),
            );
            continue;
        }

        let alias = PARAM_ALIASES
            .iter()
            .find(|(from, _)| from == key)
            .map_or(key.as_str(), |(_, to)| *to);

        // Unknown keys are skipped, not rejected — see the doc comment.
        if let Ok((column, _)) = verify_column(pool, spec.table, alias).await {
            conditions.push(typed_equality(&column, value));
        }
    }

    if let Some(prefix) = params.get("prefix") {
        if verify_column(pool, spec.table, "table_name").await.is_ok() {
            conditions.push(
                Condition::all()
                    .add(Expr::col(Alias::new("table_name")).like(format!("{prefix}%"))),
            );
        }
    }

    if let Some(needle) = params.get("search").filter(|v| !v.is_empty()) {
        let mut any = Condition::any();
        let mut matched = false;
        for candidate in SEARCHABLE_COLUMNS {
            if let Ok((column, _)) = verify_column(pool, spec.table, candidate).await {
                any = any.add(Expr::col(Alias::new(column)).ilike(format!("%{needle}%")));
                matched = true;
            }
        }
        if matched {
            conditions.push(any);
        }
    }

    Ok(conditions)
}

/// Bind a filter value by the type its column actually has.
///
/// Postgres will not compare a `uuid` or an `integer` against a text
/// parameter, so `?table_id=<uuid>` has to bind a `Uuid` — passing the string
/// through raises `operator does not exist: uuid = text` at query time.
fn typed_equality(column: &str, value: &str) -> Condition {
    let expr = Expr::col(Alias::new(column));
    if column.ends_with("_id") && !column.ends_with("reference_id") {
        if let Ok(id) = uuid::Uuid::parse_str(value) {
            return Condition::all().add(expr.eq(id));
        }
    }
    if let Ok(number) = value.parse::<i32>() {
        // Only integer-typed columns should take this branch; a text column
        // holding "42" still compares fine because Postgres coerces the
        // integer literal to text, which the reverse is not true of.
        if column.ends_with("_id") || column.starts_with("seq") || column.ends_with("_no") {
            return Condition::all().add(expr.eq(number));
        }
    }
    match value {
        "true" => Condition::all().add(expr.eq(true)),
        "false" => Condition::all().add(expr.eq(false)),
        other => Condition::all().add(expr.eq(other.to_string())),
    }
}

fn as_object(payload: Value) -> AppResult<Map<String, Value>> {
    match payload {
        Value::Object(map) => Ok(map),
        _ => Err(AppError::BadRequest(
            "Request body must be a JSON object".to_string(),
        )),
    }
}

/// Build the primary-key comparison, honouring the INTEGER/UUID split.
fn pk_predicate(spec: &SysTable, id: &str) -> AppResult<Expr> {
    let column = Expr::col(Alias::new(spec.pk));
    if spec.integer_pk {
        let parsed: i32 = id
            .parse()
            .map_err(|_| AppError::BadRequest(format!("{} id must be an integer", spec.segment)))?;
        Ok(column.eq(parsed))
    } else {
        let parsed = uuid::Uuid::parse_str(id)
            .map_err(|_| AppError::BadRequest(format!("{} id must be a UUID", spec.segment)))?;
        Ok(column.eq(parsed))
    }
}

async fn fetch_one(pool: &PgPool, spec: &SysTable, id: &str) -> AppResult<Option<Value>> {
    let (sql, values) = SeaQuery::select()
        .column(Asterisk)
        .from(Alias::new(spec.table))
        .and_where(pk_predicate(spec, id)?)
        .build_sqlx(PostgresQueryBuilder);

    let row = sqlx::query_with(AssertSqlSafe(sql), values)
        .fetch_optional(pool)
        .await?;
    Ok(row.as_ref().map(crate::services::row_json::row_to_json))
}

/// Column names in a write payload are checked against `information_schema`
/// for this table before they can become SQL identifiers.
///
/// The dictionary describes the *business* tables, not itself, so `sys_column`
/// is not the right oracle here — the live schema is.
/// Confirm the column exists on this dictionary table, and report its SQL type.
///
/// The type is what makes a write bind correctly. Every value used to go in as
/// its JSON type, so a UUID arrived as text and Postgres refused it with 42804
/// — surfacing as `400 A value has the wrong type or format`. That made
/// `POST /api/sys/columns` impossible: `sys_table_id` is a `uuid`, so every
/// attempt to add a column through the dictionary failed. The same held for any
/// `sys_*` write carrying a foreign key, a date or a boolean-as-string.
///
/// Binding is delegated to `dynamic_repo::raw_json_to_expr`, which already does
/// this for the business tables — one binder, so the two cannot disagree about
/// what a `date` accepts.
async fn verify_column(pool: &PgPool, table: &str, column: &str) -> AppResult<(String, String)> {
    let found: Option<(String, String)> = sqlx::query_as(
        r"SELECT column_name, data_type FROM information_schema.columns
           WHERE table_name = $1 AND column_name = $2
           LIMIT 1",
    )
    .bind(table)
    .bind(column)
    .fetch_optional(pool)
    .await?;

    found.ok_or_else(|| AppError::BadRequest(format!("Unknown field '{column}'")))
}

/// Map a payload onto verified column assignments.
///
/// The primary key is accepted on create only when the table uses an INTEGER
/// key (`sys_reference`, whose ids are a fixed vocabulary the caller chooses);
/// UUID keys are always database-generated. On update the key is never
/// writable — it is in the URL.
async fn verified_assignments(
    pool: &PgPool,
    spec: &SysTable,
    payload: &Map<String, Value>,
    is_create: bool,
) -> AppResult<Vec<(String, Expr)>> {
    let mut assignments = Vec::new();
    for (key, value) in payload {
        if key == spec.pk && !(is_create && spec.integer_pk) {
            continue;
        }
        // Timestamps are database-managed on these tables.
        if key == "created_at" || key == "updated_at" {
            continue;
        }
        let (column, data_type) = verify_column(pool, spec.table, key).await?;
        assignments.push((
            column,
            crate::services::dynamic_repo::raw_json_to_expr(value, &data_type),
        ));
    }
    Ok(assignments)
}


/// Drop cached dictionary metadata after a write.
///
/// `sys_table` / `sys_column` are what `DictionaryCache` reads, and `sys_field`
/// carries the ordering the UI renders from — a stale cache here is exactly the
/// "reordering needs a redeploy" failure the dictionary exists to avoid. The
/// blunt clear is deliberate: dictionary writes are rare and admin-driven, and
/// a per-entity invalidation would have to resolve which business table a
/// `sys_column` row belongs to before it could be precise.
async fn invalidate_for(ctx: &AppContext, spec: &SysTable) {
    // `sys_system` is cached by a different service, and missing it is the one
    // failure this table exists to prevent: a setting saved through the admin
    // screen that does not take effect until the process restarts is no better
    // than the YAML file it replaced.
    if spec.table == "sys_system" {
        if let Some(config) = ctx.shared_store.get::<SystemConfig>() {
            config.invalidate().await;
            crate::log_event!(dictionary_cache_invalidated, table = spec.table, cache = "configuration");
        }
        return;
    }
    if !matches!(
        spec.table,
        "sys_table" | "sys_column" | "sys_field" | "sys_tab" | "sys_window"
    ) {
        return;
    }
    if let Some(cache) = ctx.shared_store.get::<DictionaryCache>() {
        cache.invalidate_all();
        crate::log_event!(dictionary_cache_invalidated, table = spec.table, cache = "dictionary");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn registry_covers_every_nestjs_route_segment() {
        // These are the thirteen @Controller('sys/…') prefixes from the
        // TypeScript stack. Drift here is a contract break.
        let expected = [
            "tables", "columns", "fields", "tabs", "windows", "references",
            "ref-lists", "roles", "users", "user-roles", "access", "val-rules",
            "categories",
        ];
        for segment in expected {
            assert!(lookup(segment).is_ok(), "missing dictionary route: {segment}");
        }
    }

    /// Every alias must land on a real segment, or a call site that has used
    /// the alternative spelling for years starts 404ing.
    #[test]
    fn aliases_resolve_to_a_registered_table() {
        for (alias, target) in SEGMENT_ALIASES {
            assert!(lookup(alias).is_ok(), "dangling alias: {alias}");
            assert_eq!(lookup(alias).unwrap().segment, *target);
        }
        assert_eq!(lookup("ref-list").unwrap().table, "sys_ref_list");
    }

    #[test]
    fn unknown_segment_is_not_found() {
        assert!(lookup("passwords").is_err());
        assert!(lookup("../../etc/passwd").is_err());
    }

    #[test]
    fn pagination_clamps_and_derives_offset() {
        let params = |pairs: &[(&str, &str)]| {
            pairs
                .iter()
                .map(|(k, v)| ((*k).to_string(), (*v).to_string()))
                .collect::<HashMap<_, _>>()
        };

        assert_eq!(pagination_from(&params(&[])), (DEFAULT_LIMIT, 1, 0));
        assert_eq!(pagination_from(&params(&[("limit", "10"), ("page", "3")])), (10, 3, 20));
        // Zero and junk fall back rather than producing an empty page.
        assert_eq!(pagination_from(&params(&[("limit", "0")])), (DEFAULT_LIMIT, 1, 0));
        assert_eq!(pagination_from(&params(&[("limit", "nope")])), (DEFAULT_LIMIT, 1, 0));
        // A caller cannot ask for the whole table.
        assert_eq!(pagination_from(&params(&[("limit", "99999")])).0, MAX_LIMIT);
        // An explicit offset overrides the page-derived one.
        assert_eq!(pagination_from(&params(&[("limit", "10"), ("page", "3"), ("offset", "5")])).2, 5);
    }

    /// `?table_id=<uuid>` has to bind a UUID: Postgres has no `uuid = text`.
    #[test]
    fn filter_values_bind_by_column_type() {
        let uuid = "3f2e1669-c3a7-4082-96a4-7a4bde870cd0";

        // Assert on the *bound values*, not the rendered SQL: rendering inlines
        // every parameter as a quoted literal, so the string looks identical
        // whichever type was bound — which is exactly the bug this guards.
        fn bound(condition: Condition) -> Vec<sea_query::Value> {
            let mut select = SeaQuery::select();
            select
                .column(Asterisk)
                .from(Alias::new("sys_column"))
                .cond_where(condition);
            select.build(PostgresQueryBuilder).1.into_iter().collect()
        }

        assert!(matches!(
            bound(typed_equality("sys_table_id", uuid)).as_slice(),
            [sea_query::Value::Uuid(Some(_))]
        ));
        assert!(matches!(
            bound(typed_equality("sys_reference_id", "18")).as_slice(),
            [sea_query::Value::Int(Some(18))]
        ));
        assert!(matches!(
            bound(typed_equality("is_active", "true")).as_slice(),
            [sea_query::Value::Bool(Some(true))]
        ));
        assert!(matches!(
            bound(typed_equality("column_name", "smiles")).as_slice(),
            [sea_query::Value::String(Some(_))]
        ));
        // A malformed UUID falls back to text rather than erroring — the query
        // simply matches nothing, which is the right answer for a bad filter.
        assert!(matches!(
            bound(typed_equality("sys_table_id", "not-a-uuid")).as_slice(),
            [sea_query::Value::String(Some(_))]
        ));
    }

    #[test]
    fn only_sys_reference_uses_an_integer_key() {
        for spec in SYS_TABLES {
            assert_eq!(
                spec.integer_pk,
                spec.table == "sys_reference",
                "{} has the wrong key kind",
                spec.table
            );
        }
    }

    #[test]
    fn primary_key_parsing_rejects_junk() {
        let uuid_table = lookup("tables").unwrap();
        assert!(pk_predicate(uuid_table, "not-a-uuid").is_err());
        assert!(pk_predicate(uuid_table, "3f2e1669-c3a7-4082-96a4-7a4bde870cd0").is_ok());

        let int_table = lookup("references").unwrap();
        assert!(pk_predicate(int_table, "10").is_ok());
        assert!(pk_predicate(int_table, "10; DROP TABLE sys_table").is_err());
    }
}

//! Workflow definitions and runs.
//!
//! `sys_workflow_definitions` holds BPMN documents bound to an entity plus a
//! CRUD operation. This exposes them and lets one be validated or executed.
//!
//! **Every handler here takes `auth::JWT`, including the reads.** A workflow is
//! not dictionary metadata: its steps are `CreateEntity`, `UpdateEntity`,
//! `DeleteEntity` and `REST`, so anyone who can define and run one can write to
//! any `bus_*` table and make the server issue arbitrary outbound HTTP — without
//! ever presenting the token `/api/bus/*` demands. Leaving these open made the
//! bus guard decorative. The reads are guarded too because a definition
//! describes the business process in full; unlike `sys_*`, nothing renders
//! before login from it.

use axum::{
    extract::{Path, Query, State},
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use loco_rs::prelude::*;
use serde_json::{json, Value};
use std::collections::HashMap;
use uuid::Uuid;

use crate::errors::{AppError, AppResult};
use crate::models::_entities::users;
use crate::services::dictionary::DictionaryCache;
use crate::services::workflow::{parse_tasks, WorkflowContext, WorkflowExecutor};

#[utoipa::path(
    get, path = "/api/workflow", tag = "workflow",
    security(("bearer" = [])),
    params(
        ("entityName" = Option<String>, Query, description = "Filter to one entity"),
        ("kind" = Option<String>, Query, description = "`bpmn` for diagrams, `automation` for automations built in the app"),
    ),
    responses((status = 200, description = "Definitions. `isModelManaged` marks one declared in the model — read-only here, because regenerating would overwrite an edit made through this API.")),
)]
pub async fn list(
    _auth: auth::JWT,
    Query(params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let entity = params.get("entityName").map(String::as_str);
    // `bpmn` for diagrams, `automation` for what the automations screen builds.
    let kind = params.get("kind").map(String::as_str);

    let rows = sqlx::query(
        r"SELECT * FROM sys_workflow_definitions
           WHERE ($1::text IS NULL OR entity_name = $1)
             AND ($2::text IS NULL OR kind = $2)
           ORDER BY name",
    )
    .bind(entity)
    .bind(kind)
    .fetch_all(pool)
    .await?;

    Ok(Json(crate::services::row_json::rows_to_json(&rows)).into_response())
}

/// `GET /api/workflow/{id}` — one definition.
#[utoipa::path(
    get, path = "/api/workflow/{id}", tag = "workflow",
    security(("bearer" = [])),
    params(("id" = String, Path, description = "Workflow definition id")),
    responses(
        (status = 200, description = "The definition, BPMN XML included"),
        (status = 404, description = "No such definition"),
    ),
)]
pub async fn get_one(
    _auth: auth::JWT,
    Path(id): Path<Uuid>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let row = sqlx::query("SELECT * FROM sys_workflow_definitions WHERE id = $1")
        .bind(id)
        .fetch_optional(pool)
        .await?
        .ok_or_else(|| AppError::NotFound(format!("Workflow {id} not found")))?;

    Ok(Json(crate::services::row_json::row_to_json(&row)).into_response())
}

/// `POST /api/workflow` — store a new definition.
#[utoipa::path(
    post, path = "/api/workflow", tag = "workflow",
    security(("bearer" = [])),
    request_body(content = serde_json::Value, description = "`{ name, entityName, bpmnXml }` for a BPMN diagram, or `{ kind: \"automation\", name, entityName, definition }` for an automation, whose `definition` is the automation's YAML document. Either is checked at write time, so an unusable definition is refused here rather than at the business write that would have triggered it"),
    responses(
        (status = 201, description = "The stored definition"),
        (status = 400, description = "Missing field, an unknown kind, BPMN that does not parse, or an automation definition that is not an automation YAML document"),
    ),
)]
pub async fn create(
    _auth: auth::JWT,
    State(ctx): State<AppContext>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    let name = required_str(&payload, "name")?;
    let entity_name = required_str(&payload, "entityName")?;

    match payload.get("kind").and_then(Value::as_str).unwrap_or("bpmn") {
        "bpmn" => {}
        "automation" => return create_automation(&ctx, &payload, &name, &entity_name).await,
        other => {
            return Err(AppError::BadRequest(format!(
                "Unknown workflow kind \"{other}\": expected \"bpmn\" or \"automation\""
            )))
        }
    }
    let bpmn_xml = required_str(&payload, "bpmnXml")?;

    // Reject a definition that cannot be parsed at write time rather than
    // discovering it when a business write triggers it.
    parse_tasks(&bpmn_xml)?;

    let operation = payload
        .get("operation")
        .and_then(Value::as_str)
        .unwrap_or("ALL");
    let description = payload.get("description").and_then(Value::as_str);

    let pool = ctx.db.get_postgres_connection_pool();
    let row = sqlx::query(
        r"INSERT INTO sys_workflow_definitions
            (name, entity_name, operation, bpmn_xml, description)
          VALUES ($1, $2, $3, $4, $5)
          RETURNING *",
    )
    .bind(&name)
    .bind(&entity_name)
    .bind(operation)
    .bind(&bpmn_xml)
    .bind(description)
    .fetch_one(pool)
    .await?;

    Ok((
        StatusCode::CREATED,
        Json(crate::services::row_json::row_to_json(&row)),
    )
        .into_response())
}

/// The version of the automation document this application reads.
const AUTOMATION_DOCUMENT_VERSION: &str = "1.0";

/// Hold an automation's YAML document to its shape before it is stored.
///
/// The automations screen writes the document; this is the last place a
/// malformed one can be refused before a later read of it fails in the UI. It
/// checks what every reader relies on — the version, a known kind, the entity
/// the trigger watches, and that the lists are lists — not every field of every
/// step, which the builder validates as the author edits.
fn validate_automation_definition(definition: &str) -> AppResult<()> {
    let document: serde_yaml::Value = serde_yaml::from_str(definition)
        .map_err(|error| AppError::BadRequest(format!("The automation is not YAML: {error}")))?;
    let invalid = |reason: &str| AppError::BadRequest(format!("The automation {reason}"));

    let map = document
        .as_mapping()
        .ok_or_else(|| invalid("must be a YAML mapping"))?;
    let field = |key: &str| map.get(serde_yaml::Value::from(key));

    match field("automation").and_then(serde_yaml::Value::as_str) {
        Some(AUTOMATION_DOCUMENT_VERSION) => {}
        Some(other) => {
            return Err(invalid(&format!(
                "is version {other}; this application reads version {AUTOMATION_DOCUMENT_VERSION}"
            )))
        }
        None => return Err(invalid("has no `automation:` version key")),
    }
    match field("kind").and_then(serde_yaml::Value::as_str) {
        Some("automation" | "hook" | "saga") => {}
        _ => return Err(invalid("needs `kind:` automation, hook or saga")),
    }
    let entity = field("trigger")
        .and_then(serde_yaml::Value::as_mapping)
        .and_then(|trigger| trigger.get(serde_yaml::Value::from("entity")))
        .and_then(serde_yaml::Value::as_str);
    if entity.is_none_or(str::is_empty) {
        return Err(invalid("needs `trigger.entity`"));
    }
    for list in ["conditions", "loops", "steps", "hooks"] {
        if field(list).is_some_and(|value| !value.is_sequence()) {
            return Err(invalid(&format!("has a `{list}:` that is not a list")));
        }
    }
    Ok(())
}

/// Store an automation the automations screen built, as its YAML document.
async fn create_automation(
    ctx: &AppContext,
    payload: &Value,
    name: &str,
    entity_name: &str,
) -> AppResult<Response> {
    let definition = required_str(payload, "definition")?;
    validate_automation_definition(&definition)?;

    let operation = payload
        .get("operation")
        .and_then(Value::as_str)
        .unwrap_or("ALL");
    let description = payload.get("description").and_then(Value::as_str);

    let row = sqlx::query(
        r"INSERT INTO sys_workflow_definitions
            (name, entity_name, operation, kind, definition_yaml, description)
          VALUES ($1, $2, $3, 'automation', $4, $5)
          RETURNING *",
    )
    .bind(name)
    .bind(entity_name)
    .bind(operation)
    .bind(&definition)
    .bind(description)
    .fetch_one(ctx.db.get_postgres_connection_pool())
    .await?;

    Ok((
        StatusCode::CREATED,
        Json(crate::services::row_json::row_to_json(&row)),
    )
        .into_response())
}

/// `PUT|PATCH /api/workflow/{id}` — save an edited definition.
///
/// The Workflow Designer's edit screen has always called this. Without it the
/// route did not exist, so "Save Changes" answered 405 and every edit to a
/// stored workflow was silently lost — the one thing that screen is for.
///
/// Fields are optional so a PATCH can rename a workflow without resubmitting
/// the diagram. A supplied `bpmnXml` is parsed before it is stored, the same
/// way `create` does it: a definition that cannot be parsed must be refused at
/// write time, not when a business write triggers it.
/// `PUT`/`PATCH /api/workflow/{id}` — change a definition.
#[utoipa::path(
    put, path = "/api/workflow/{id}", tag = "workflow",
    security(("bearer" = [])),
    params(("id" = String, Path, description = "Workflow definition id")),
    request_body(content = serde_json::Value, description = "The fields to change. An automation's `definition` (its YAML document) and a diagram's `bpmnXml` are checked before they are stored"),
    responses(
        (status = 200, description = "The updated definition"),
        (status = 400, description = "BPMN that does not parse, or a model-managed definition — those are edited in the model and regenerated, because the next generation would overwrite an edit made here"),
        (status = 404, description = "No such definition"),
    ),
)]
pub async fn update(
    _auth: auth::JWT,
    Path(id): Path<Uuid>,
    State(ctx): State<AppContext>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();

    let existing: Option<(bool, String)> =
        sqlx::query_as("SELECT is_model_managed, name FROM sys_workflow_definitions WHERE id = $1")
            .bind(id)
            .fetch_optional(pool)
            .await?;

    let Some((is_managed, existing_name)) = existing else {
        return Err(AppError::NotFound(format!("Workflow {id} not found")));
    };

    // Same reasoning as `remove`: the next generation would overwrite the edit,
    // so refuse it here instead of losing someone's work without warning.
    if is_managed {
        return Err(AppError::BadRequest(format!(
            "Workflow \"{existing_name}\" is declared in the model. Edit its `kind: saga` section and regenerate."
        )));
    }

    let bpmn_xml = payload.get("bpmnXml").and_then(Value::as_str);
    if let Some(xml) = bpmn_xml {
        parse_tasks(xml)?;
    }
    let definition = payload.get("definition").and_then(Value::as_str);
    if let Some(yaml) = definition {
        validate_automation_definition(yaml)?;
    }

    let row = sqlx::query(
        r"UPDATE sys_workflow_definitions
             SET name        = COALESCE($2, name),
                 entity_name = COALESCE($3, entity_name),
                 operation   = COALESCE($4, operation),
                 bpmn_xml    = COALESCE($5, bpmn_xml),
                 description = COALESCE($6, description),
                 is_active   = COALESCE($7, is_active),
                 definition_yaml = COALESCE($8, definition_yaml),
                 updated_at  = NOW()
           WHERE id = $1
       RETURNING *",
    )
    .bind(id)
    .bind(payload.get("name").and_then(Value::as_str))
    .bind(payload.get("entityName").and_then(Value::as_str))
    .bind(payload.get("operation").and_then(Value::as_str))
    .bind(bpmn_xml)
    .bind(payload.get("description").and_then(Value::as_str))
    .bind(payload.get("isActive").and_then(Value::as_bool))
    .bind(definition)
    .fetch_one(pool)
    .await?;

    Ok(Json(crate::services::row_json::row_to_json(&row)).into_response())
}

/// `DELETE /api/workflow/{id}` — drop a definition.
#[utoipa::path(
    delete, path = "/api/workflow/{id}", tag = "workflow",
    security(("bearer" = [])),
    params(("id" = String, Path, description = "Workflow definition id")),
    responses(
        (status = 204, description = "Deleted"),
        (status = 400, description = "A model-managed definition — remove its `kind: saga` section and regenerate"),
        (status = 404, description = "No such definition"),
    ),
)]
pub async fn remove(
    _auth: auth::JWT,
    Path(id): Path<Uuid>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();

    // A model-declared workflow belongs to the model. Deleting it here would
    // appear to work and then reappear on the next generation, so refuse it and
    // say where the definition actually lives.
    let managed: Option<(bool, String)> =
        sqlx::query_as("SELECT is_model_managed, name FROM sys_workflow_definitions WHERE id = $1")
            .bind(id)
            .fetch_optional(pool)
            .await?;

    if let Some((true, name)) = managed {
        return Err(AppError::BadRequest(format!(
            "Workflow \"{name}\" is declared in the model. Remove its `kind: saga` section and regenerate."
        )));
    }

    let result = sqlx::query("DELETE FROM sys_workflow_definitions WHERE id = $1")
        .bind(id)
        .execute(pool)
        .await?;

    if result.rows_affected() == 0 {
        return Err(AppError::NotFound(format!("Workflow {id} not found")));
    }
    Ok(StatusCode::NO_CONTENT.into_response())
}

/// `POST /api/workflow/{id}/execute` — run a definition against one record.
#[utoipa::path(
    post, path = "/api/workflow/{id}/execute", tag = "workflow",
    security(("bearer" = [])),
    params(("id" = String, Path, description = "Workflow definition id")),
    request_body(content = serde_json::Value, description = "`{ entityId, entityData, decision }` — the run context every step reads from"),
    responses(
        (status = 200, description = "`{ status, tasksExecuted, vars }`"),
        (status = 400, description = "A step failed; the run aborted and is recorded as failed"),
        (status = 404, description = "No such definition"),
    ),
)]
pub async fn execute(
    _auth: auth::JWT,
    Path(id): Path<Uuid>,
    State(ctx): State<AppContext>,
    Json(payload): Json<Value>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();
    let definition: Option<(String, Option<String>)> =
        sqlx::query_as("SELECT entity_name, bpmn_xml FROM sys_workflow_definitions WHERE id = $1")
            .bind(id)
            .fetch_optional(pool)
            .await?;
    let (entity_name, bpmn_xml) =
        definition.ok_or_else(|| AppError::NotFound(format!("Workflow {id} not found")))?;
    // An automation is stored as its YAML document and has no diagram; this
    // endpoint runs BPMN, so say so rather than failing to decode a NULL.
    let bpmn_xml = bpmn_xml.ok_or_else(|| {
        AppError::BadRequest(format!(
            "Workflow {id} is an automation, not a BPMN diagram, and cannot be executed here"
        ))
    })?;

    let executor = ctx
        .shared_store
        .get::<WorkflowExecutor>()
        .ok_or_else(|| AppError::Internal(anyhow::anyhow!("workflow executor not initialised")))?;

    let tasks = parse_tasks(&bpmn_xml)?;
    let mut run = WorkflowContext {
        entity_name,
        entity_id: payload
            .get("entityId")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        entity_data: payload
            .get("entityData")
            .and_then(Value::as_object)
            .cloned()
            .unwrap_or_default(),
        decision: payload
            .get("decision")
            .and_then(Value::as_object)
            .cloned()
            .unwrap_or_default(),
        vars: serde_json::Map::new(),
    };

    let started = chrono::Utc::now();
    let outcome = executor.run(&tasks, &mut run).await;

    // Every run is recorded, successful or not — sys_workflow_runs is the
    // operator's only view into what a workflow actually did.
    let status = if outcome.is_ok() { "completed" } else { "failed" };
    let error = outcome.as_ref().err().map(ToString::to_string);
    let _ = sqlx::query(
        r"INSERT INTO sys_workflow_runs
            (entity_name, entity_id, operation, status, error_details, created_at, completed_at)
          VALUES ($1, $2, 'TRIGGER', $3, $4, $5, NOW())",
    )
    .bind(&run.entity_name)
    .bind(run.entity_id.as_deref().and_then(|id| Uuid::parse_str(id).ok()))
    .bind(status)
    .bind(error.as_deref())
    .bind(started)
    .execute(pool)
    .await;

    outcome?;
    Ok(Json(json!({
        "status": status,
        "tasksExecuted": tasks.len(),
        "vars": run.vars,
    }))
    .into_response())
}

/// `GET /api/workflows/transitions?table=&from=` — the moves that exist.
///
/// A form that offers every value a status column could hold offers moves the
/// state machine does not draw, and the update is then refused with a
/// validation error after the user has committed to it. This is the list to
/// build the control from: ask for a table and the record's current state, get
/// back exactly the moves that will be accepted.
///
/// Open to any signed-in caller, deliberately. It describes the machine, not
/// the data — the same line `/api/sys/*` reads draw between a description and
/// the thing described. Whether *this* caller may cross a given edge is
/// `sys_transition_access`, and it is answered when the write arrives.
///
/// `from` is optional: without it the whole machine comes back, which is what
/// a designer screen wants.
#[utoipa::path(
    get, path = "/api/workflows/transitions", tag = "workflow",
    security(("bearer" = [])),
    params(
        ("table" = Option<String>, Query, description = "Physical table, e.g. `bus_deal`"),
        ("from" = Option<String>, Query, description = "Current state; omit for the whole machine"),
    ),
    responses((status = 200, description = "`[{ tableName, statusField, from, to, transition }]`")),
)]
pub async fn transitions(
    _auth: auth::JWT,
    Query(params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let table = params.get("table").or_else(|| params.get("tableName"));
    let from = params.get("from").or_else(|| params.get("fromState"));

    let rows: Vec<(String, String, String, String, Option<String>)> = sqlx::query_as(
        r"SELECT table_name, status_field, from_state, to_state, transition_name
            FROM sys_workflow_transitions
           WHERE ($1::text IS NULL OR table_name = $1)
             AND ($2::text IS NULL OR from_state = $2)
             AND COALESCE(is_active, true) = true
           ORDER BY table_name, from_state, to_state",
    )
    .bind(table)
    .bind(from)
    .fetch_all(ctx.db.get_postgres_connection_pool())
    .await?;

    let moves: Vec<Value> = rows
        .into_iter()
        .map(|(table_name, status_field, from_state, to_state, transition)| {
            json!({
                "tableName": table_name,
                "statusField": status_field,
                "from": from_state,
                "to": to_state,
                "transition": transition,
            })
        })
        .collect();
    Ok(Json(moves).into_response())
}

/// `GET /api/workflows/runs` — the execution log the admin screen polls.
///
/// A bare array in creation order, newest first, because that screen refreshes
/// every five seconds and reads it as `WorkflowRun[]`.
#[utoipa::path(
    get, path = "/api/workflows/runs", tag = "workflow",
    security(("bearer" = [])),
    params(
        ("entityName" = Option<String>, Query, description = "Filter by entity"),
        ("status" = Option<String>, Query, description = "Filter by run status"),
        ("limit" = Option<i64>, Query, description = "Max rows (default 100, cap 1000)"),
    ),
    responses((status = 200, description = "The run log, newest first — a bare array, not the `{ data, meta }` envelope")),
)]
pub async fn runs(
    _auth: auth::JWT,
    Query(params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
) -> AppResult<Response> {
    let pool = ctx.db.get_postgres_connection_pool();

    let limit = params
        .get("limit")
        .and_then(|v| v.parse::<i64>().ok())
        .filter(|v| *v > 0)
        .unwrap_or(100)
        .min(1000);

    let rows = sqlx::query(
        r"SELECT * FROM sys_workflow_runs
           WHERE ($1::text IS NULL OR entity_name = $1)
             AND ($2::text IS NULL OR status      = $2)
             AND ($3::text IS NULL OR operation   = $3)
           ORDER BY created_at DESC
           LIMIT $4",
    )
    .bind(params.get("entityName").or_else(|| params.get("entity_name")))
    .bind(params.get("status"))
    .bind(params.get("operation"))
    .bind(limit)
    .fetch_all(pool)
    .await?;

    Ok(Json(crate::services::row_json::rows_to_json(&rows)).into_response())
}

pub fn routes() -> Routes {
    Routes::new()
        .prefix("workflow")
        .add("/", get(list))
        .add("/", post(create))
        .add("/{id}", get(get_one))
        .add("/{id}", put(update))
        .add("/{id}", patch(update))
        .add("/{id}", delete(remove))
        .add("/{id}/execute", post(execute))
}

/// `/api/workflows/runs`, mounted separately.
///
/// The plural is not a typo to fix: `/api/workflow` is a definition and
/// `/api/workflows/runs` is the run log, and both spellings are already in the
/// frontend. Loco's `Routes::prefix` is a single segment, so the second prefix
/// needs its own `Routes`.
/// `GET /api/workflows/entity/{entity_name}/{entity_id}` — one record's runs.
///
/// The run log narrowed to a single record, which is the question an operator
/// actually has: not "what has this application run" but "what happened to
/// *this* order". `/runs` answers the first and cannot answer the second — it
/// filters by entity name, not by id.
///
/// Gated on that entity's own `read`, not on being an administrator. A run
/// row names the record and carries `mutations_applied`, so reading a
/// record's runs is reading what was done to the record; anyone who may not
/// read the record may not read that either. Without the check this would be
/// a way around the guard on `/api/bus/*`, which is the same hole the
/// workflow controller had before it was guarded at all.
#[utoipa::path(
    get, path = "/api/workflows/entity/{entity_name}/{entity_id}", tag = "workflow",
    security(("bearer" = [])),
    params(
        ("entity_name" = String, Path, description = "Dictionary table or entity name"),
        ("entity_id" = String, Path, description = "Record id"),
        ("limit" = Option<i64>, Query, description = "Page size, clamped to 1..=500 (default 100)"),
    ),
    responses(
        (status = 200, description = "Runs for this record, newest first"),
        (status = 403, description = "The caller may not read this entity"),
        (status = 404, description = "No such entity in the dictionary"),
    ),
)]
pub async fn entity_runs(
    auth: auth::JWTWithUser<users::Model>,
    Path((entity_name, entity_id)): Path<(String, String)>,
    Query(params): Query<HashMap<String, String>>,
    State(ctx): State<AppContext>,
    SharedStore(dictionary): SharedStore<DictionaryCache>,
) -> AppResult<Response> {
    let table = dictionary.resolve(&entity_name).await?;
    let pool = ctx.db.get_postgres_connection_pool();
    let principal = crate::services::authz::principal(pool, &auth.user).await?;
    crate::services::authz::require_operation(
        pool,
        &principal,
        table.as_str(),
        crate::services::authz::Operation::Read,
    )
    .await?;

    let limit = params
        .get("limit")
        .and_then(|v| v.parse::<i64>().ok())
        .filter(|v| *v > 0)
        .unwrap_or(100)
        .min(500);

    // `entity_name` is matched against the physical table the dictionary
    // resolved, not against what the caller typed: the runs were written with
    // the table name, and `/workflows/entity/companies/…` must find them.
    let rows = sqlx::query(
        r"SELECT * FROM sys_workflow_runs
           WHERE entity_name = $1 AND entity_id = $2::uuid
           ORDER BY created_at DESC
           LIMIT $3",
    )
    .bind(table.as_str())
    .bind(&entity_id)
    .bind(limit)
    .fetch_all(pool)
    .await?;

    Ok(Json(crate::services::row_json::rows_to_json(&rows)).into_response())
}

pub fn run_routes() -> Routes {
    Routes::new()
        .prefix("workflows")
        .add("/runs", get(runs))
        .add("/transitions", get(transitions))
        .add("/entity/{entity_name}/{entity_id}", get(entity_runs))
}

/// `/api/workflow-definitions` — the designer's spelling of `/api/workflow`.
///
/// Same handlers, second URL. The workflow designer screens were written
/// against this name and the rules editor links to it; aliasing costs one route
/// table and breaks nothing.
pub fn definition_routes() -> Routes {
    Routes::new()
        .prefix("workflow-definitions")
        .add("/", get(list))
        .add("/", post(create))
        .add("/{id}", get(get_one))
        .add("/{id}", put(update))
        .add("/{id}", patch(update))
        .add("/{id}", delete(remove))
        .add("/{id}/execute", post(execute))
}

fn required_str(payload: &Value, key: &str) -> AppResult<String> {
    payload
        .get(key)
        .and_then(Value::as_str)
        .filter(|v| !v.is_empty())
        .map(ToString::to_string)
        .ok_or_else(|| AppError::Validation {
            message: "Validation failed".to_string(),
            errors: vec![format!("{key} is required")],
        })
}

//! HTTP error envelope.
//!
//! The frontend parses specific error shapes, so this reproduces the NestJS
//! `HttpExceptionFilter` body byte for byte rather than adopting Loco's own
//! `ErrorDetail` envelope (`{error, description}`), which is a different
//! shape. See docs/MIGRATION-LOCO-ASTRYX.md §6.11.
//!
//! Success responses are *not* wrapped: the TypeScript `TransformInterceptor`
//! passes the payload through unchanged for these routes, and the list
//! envelope (`{data, meta}`) is built explicitly by the handler.

use axum::{
    http::StatusCode,
    response::{IntoResponse, Response},
    Json,
};
use serde::Serialize;

/// The JSON body every error response carries.
///
/// `errors` is omitted entirely (not `null`) when empty, matching
/// `BadRequestException`'s behaviour for non-validation errors.
#[derive(Debug, Serialize)]
pub struct ErrorBody {
    #[serde(rename = "statusCode")]
    pub status_code: u16,
    pub message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub errors: Option<Vec<String>>,
    pub error: String,
    /// Present on a concurrency refusal: what a client needs to resolve it —
    /// the record as it now stands, who changed it, what changed, and where the
    /// transaction stands. See `services::concurrency`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub conflict: Option<serde_json::Value>,
}

#[derive(Debug, thiserror::Error)]
pub enum AppError {
    #[error("{0}")]
    NotFound(String),

    /// 400 — same body as NestJS `BadRequestException` with a validation array.
    #[error("{message}")]
    Validation {
        message: String,
        errors: Vec<String>,
    },

    #[error("{0}")]
    BadRequest(String),

    /// 409 — a Postgres unique violation, or a conflict with no record to
    /// describe.
    #[error("{0}")]
    Conflict(String),

    /// 409 — an update refused for concurrency: the record changed since the
    /// caller read it (`VERSION_CONFLICT`), or it is in a final state and its
    /// transaction is complete (`RECORD_FINAL`). `conflict` carries the
    /// record as it now stands, so the screen can offer refresh or overwrite
    /// without a second request.
    #[error("{message}")]
    Concurrency {
        code: &'static str,
        message: String,
        conflict: serde_json::Value,
    },

    /// 428 — an update with no `If-Match` on an optimistic table. A client
    /// that never read the record cannot overwrite it blind.
    #[error("{0}")]
    PreconditionRequired(String),

    #[error("unauthorized")]
    Unauthorized,

    /// 403 — authenticated, but the role does not grant this. Carries a
    /// reason: "forbidden" alone leaves a caller guessing whether they need a
    /// different role, a different record, or a different endpoint.
    #[error("{0}")]
    Forbidden(String),

    /// 503 — a configured upstream (Electric) is absent or unreachable. The
    /// frontend treats this as "fall back to the plain HTTP API", so it must
    /// not be collapsed into a 500.
    #[error("{0}")]
    ServiceUnavailable(String),

    #[error(transparent)]
    Internal(#[from] anyhow::Error),
}

impl AppError {
    /// The message a `VERSION_CONFLICT` carries.
    pub const VERSION_CONFLICT_MESSAGE: &'static str =
        "This record was changed by another user since you opened it.";

    /// The message a `RECORD_FINAL` carries.
    pub const RECORD_FINAL_MESSAGE: &'static str =
        "This record is in a final state: its transaction is complete and it can no longer be changed.";

    /// The exact message the TypeScript stack returns for Postgres `23505`.
    #[must_use]
    pub fn unique_violation() -> Self {
        Self::Conflict("A record with the same unique field value already exists".into())
    }

    fn status(&self) -> StatusCode {
        match self {
            Self::NotFound(_) => StatusCode::NOT_FOUND,
            Self::Validation { .. } | Self::BadRequest(_) => StatusCode::BAD_REQUEST,
            Self::Conflict(_) | Self::Concurrency { .. } => StatusCode::CONFLICT,
            Self::PreconditionRequired(_) => StatusCode::PRECONDITION_REQUIRED,
            Self::Unauthorized => StatusCode::UNAUTHORIZED,
            Self::Forbidden(_) => StatusCode::FORBIDDEN,
            Self::ServiceUnavailable(_) => StatusCode::SERVICE_UNAVAILABLE,
            Self::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }
}

impl From<sqlx::Error> for AppError {
    fn from(err: sqlx::Error) -> Self {
        // Class 23 is "integrity constraint violation" — the caller sent
        // something the schema rejects. That is a 4xx, not a 500: a 500 says
        // the server is broken, and a client that omitted a required field has
        // no reason to retry against a server that is working fine.
        //
        // 23505 keeps the fixed 409 message the TypeScript stack returned
        // (bus.service.ts.hbs:180-191); the rest become 400s naming the column
        // Postgres objected to. Anything outside class 23 is genuinely internal
        // and must not leak driver detail.
        if let sqlx::Error::Database(ref db_err) = err {
            match db_err.code().as_deref() {
                Some("23505") => return Self::unique_violation(),
                Some("23502") => {
                    // sqlx's `DatabaseError` exposes `constraint` and `table`
                    // but not `column`, and a NOT NULL violation has no named
                    // constraint — so the column is read out of the message
                    // Postgres writes: `null value in column "smiles" of
                    // relation "bus_compound" violates not-null constraint`.
                    let field = quoted_column(db_err.message())
                        .map_or_else(|| "a required field".to_string(), |c| format!("'{c}'"));
                    return Self::Validation {
                        message: "Validation failed".to_string(),
                        errors: vec![format!("{field} is required")],
                    };
                }
                Some("23503") => {
                    return Self::Validation {
                        message: "Validation failed".to_string(),
                        errors: vec![
                            "A referenced record does not exist".to_string(),
                        ],
                    };
                }
                Some("23514") => {
                    return Self::Validation {
                        message: "Validation failed".to_string(),
                        errors: vec!["A value is outside its allowed range".to_string()],
                    };
                }
                // 22P02 is `invalid_text_representation` — a malformed UUID or
                // number in the payload. 42804 is `datatype_mismatch`: a value
                // bound as text against a typed column. Both are the caller's
                // input, not a server fault.
                Some("22P02" | "22007" | "22008" | "42804") => {
                    return Self::BadRequest("A value has the wrong type or format".to_string());
                }
                _ => {}
            }
        }
        Self::Internal(err.into())
    }
}

/// The column name out of `… in column "name" of relation …`.
///
/// Returns `None` for any message that does not have that shape, so a Postgres
/// wording change degrades to the generic "a required field" rather than
/// showing the user a fragment of a driver message.
fn quoted_column(message: &str) -> Option<&str> {
    let after = message.split_once("column \"")?.1;
    after.split_once('"').map(|(name, _)| name)
}

impl From<sea_orm::DbErr> for AppError {
    fn from(err: sea_orm::DbErr) -> Self {
        Self::Internal(err.into())
    }
}

impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let status = self.status();

        // Internal errors are logged in full and reported generically — the
        // same split the NestJS filter makes.
        if let Self::Internal(ref err) = self {
            // `request_unhandled`, not `request_failed`: the middleware emits one line
            // per request and already reports the 5xx this turns into. This one is
            // the detail the middleware cannot see — what the error actually was.
            crate::log_event!(request_unhandled, error = ?err);
        }

        let canonical = || {
            status
                .canonical_reason()
                .unwrap_or("Internal Server Error")
                .to_string()
        };
        let (message, errors, error, conflict) = match self {
            Self::Validation { message, errors } => (message, Some(errors), canonical(), None),
            Self::Internal(_) => ("Internal server error".to_string(), None, canonical(), None),
            // The machine-readable code replaces the reason phrase, so a client
            // can tell a stale version from a closed record without parsing
            // prose.
            Self::Concurrency {
                code,
                message,
                conflict,
            } => (message, None, code.to_string(), Some(conflict)),
            other => (other.to_string(), None, canonical(), None),
        };

        let body = ErrorBody {
            status_code: status.as_u16(),
            message,
            errors,
            error,
            conflict,
        };

        (status, Json(body)).into_response()
    }
}

pub type AppResult<T> = std::result::Result<T, AppError>;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn not_null_messages_yield_the_column_name() {
        assert_eq!(
            quoted_column(
                r#"null value in column "smiles" of relation "bus_compound" violates not-null constraint"#
            ),
            Some("smiles")
        );
        // A message with no column clause degrades rather than guessing.
        assert_eq!(quoted_column("some other database error"), None);
        assert_eq!(quoted_column(r#"unterminated column "smiles"#), None);
    }

    /// Class 23 is the caller's mistake, not the server's. Every one of these
    /// used to surface as a 500, which told a client to retry a request that
    /// could never succeed.
    #[test]
    fn integrity_violations_are_client_errors() {
        for (code, expected) in [
            ("23502", StatusCode::BAD_REQUEST),
            ("23503", StatusCode::BAD_REQUEST),
            ("23514", StatusCode::BAD_REQUEST),
            ("22P02", StatusCode::BAD_REQUEST),
            ("42804", StatusCode::BAD_REQUEST),
            ("23505", StatusCode::CONFLICT),
        ] {
            let error = AppError::from(sqlx::Error::Database(Box::new(TestDbError {
                code: code.to_string(),
            })));
            assert_eq!(error.status(), expected, "wrong status for {code}");
        }
    }

    /// A failure with no SQLSTATE really is internal and must stay a 500.
    #[test]
    fn unclassified_database_errors_stay_internal() {
        let error = AppError::from(sqlx::Error::PoolClosed);
        assert_eq!(error.status(), StatusCode::INTERNAL_SERVER_ERROR);
    }

    #[derive(Debug)]
    struct TestDbError {
        code: String,
    }

    impl std::fmt::Display for TestDbError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            f.write_str("test database error")
        }
    }

    impl std::error::Error for TestDbError {}

    impl sqlx::error::DatabaseError for TestDbError {
        fn message(&self) -> &str {
            "test database error"
        }

        fn code(&self) -> Option<std::borrow::Cow<'_, str>> {
            Some(std::borrow::Cow::Borrowed(&self.code))
        }

        fn as_error(&self) -> &(dyn std::error::Error + Send + Sync + 'static) {
            self
        }

        fn as_error_mut(&mut self) -> &mut (dyn std::error::Error + Send + Sync + 'static) {
            self
        }

        fn into_error(self: Box<Self>) -> Box<dyn std::error::Error + Send + Sync + 'static> {
            self
        }

        fn kind(&self) -> sqlx::error::ErrorKind {
            sqlx::error::ErrorKind::Other
        }
    }
}

