//! Natural-language querying over the business entities (decision D5).
//!
//! ## The model does not write SQL
//!
//! This is the load-bearing design choice and the reason the module looks the
//! way it does. The NestJS original asked an agent for SQL, validated the
//! string, and executed it. That puts generated text on the path to the
//! database with a validator as the only barrier — the same class of risk the
//! Electric proxy deliberately refused to port (see `controllers/electric.rs`).
//!
//! Instead the model returns a **`QueryPlan`**: an entity name, filters drawn
//! from the operator whitelist `/api/bus/{entity}` already accepts, an optional
//! sort, and a limit. `validate` checks every part of it against the
//! Application Dictionary, and execution goes through `DynamicRepo::find_all` —
//! the exact path the REST endpoint uses. Two consequences follow, and both are
//! the point:
//!
//!   * there is no string from the model anywhere near `sea_query`, so a prompt
//!     injection has no SQL to inject into; and
//!   * the natural-language layer cannot express anything the caller could not
//!     already do over REST, so it adds a *phrasing*, not a privilege.
//!
//! The cost is real and worth stating: no joins, no `GROUP BY`, no aggregates
//! beyond the row count `find_all` already returns. A question needing those
//! gets an honest "I can't answer that from one entity" rather than a query
//! nobody vetted.
//!
//! ## Authorisation
//!
//! The caller's readable tables are resolved **before** the prompt is built, so
//! the model is never told about a table the caller cannot see — it cannot
//! suggest one, and the schema itself is not a disclosure. `execute` then calls
//! `authz::require_read` on the resolved table regardless. The filter is a
//! usability measure; the check is the control, and it runs even if the model
//! returns something the filter should have excluded.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

use std::time::Instant;

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use sqlx::PgPool;

use crate::errors::{AppError, AppResult};
use crate::services::authz::{self, Principal};
use crate::services::dictionary::{is_managed_column, DictionaryCache};
use crate::services::dynamic_repo::{DynamicRepo, Filter, FilterOp, OrderDir, PaginationOptions};
use crate::services::system_config::SystemConfig;

/// Hard ceiling on rows a single question can return, whatever the plan asks
/// for. `/api/bus/{entity}` uses the same number.
const MAX_LIMIT: u64 = 500;
/// What a plan gets when it names no limit.
const DEFAULT_LIMIT: u64 = 25;
/// Upper bound on the question itself. A prompt is charged per token and this
/// endpoint is authenticated but not otherwise rate limited.
const MAX_QUESTION_CHARS: usize = 1_000;

/// Where the model's answer is parsed into.
///
/// Deliberately small. Every field is validated against the dictionary before
/// anything runs, and a field that cannot be validated does not belong here —
/// "raw_sql" being the obvious one.
#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct QueryPlan {
    /// Dictionary entity or table name, e.g. `compound` or `bus_compound`.
    pub entity: String,
    #[serde(default)]
    pub filters: Vec<PlanFilter>,
    #[serde(default)]
    pub search: Option<String>,
    #[serde(default)]
    pub order_by: Option<String>,
    #[serde(default)]
    pub order_dir: Option<String>,
    #[serde(default)]
    pub limit: Option<u64>,
    /// How the model expects the answer to read. Advisory only — the frontend
    /// uses it to pick a view and nothing on this side depends on it.
    #[serde(default)]
    pub display_hint: Option<String>,
    /// One sentence restating the question, shown above the results.
    #[serde(default)]
    pub summary: Option<String>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
pub struct PlanFilter {
    pub column: String,
    pub op: String,
    pub value: String,
}

/// A plan that has been checked against the dictionary and is safe to run.
///
/// Separate from `QueryPlan` on purpose: the type is the proof. A `ValidPlan`
/// can only be produced by `validate`, so `execute` cannot be handed an
/// unchecked plan by a future caller who forgot the step.
pub struct ValidPlan {
    table_name: String,
    entity: String,
    filters: Vec<Filter>,
    search: Option<String>,
    opts: PaginationOptions,
    display_hint: String,
    summary: Option<String>,
}

/// One entity as the prompt describes it.
struct EntitySchema {
    table_name: String,
    display_name: String,
    columns: Vec<String>,
}

/// Read the AI settings out of the app's own `settings` block.
///
/// Mirrors `electric_url` in the Electric controller — same shape, same reason:
/// an optional integration is configured in `config/*.yaml` and its absence is
/// a 503 rather than a panic or a missing route.
pub struct AiSettings {
    pub base_url: String,
    pub model: String,
    pub api_key: String,
}

impl AiSettings {
    /// `None` when the add-on is not configured, which is the default.
    ///
    /// The module is always compiled and the route always mounted — a
    /// conditionally emitted module is the `include_str!` trap this codebase
    /// has already been bitten by, and the parity gate cannot see it. The
    /// feature is gated at run time instead.
    #[must_use]
    pub fn from_settings(settings: Option<&Value>) -> Option<Self> {
        let settings = settings?;
        let base_url = settings
            .get("ai_base_url")?
            .as_str()
            .filter(|value| !value.is_empty())?
            .trim_end_matches('/')
            .to_string();
        let model = settings
            .get("ai_model")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())?
            .to_string();
        let api_key = settings
            .get("ai_api_key")
            .and_then(Value::as_str)
            .unwrap_or("local")
            .to_string();

        Some(Self {
            base_url,
            model,
            api_key,
        })
    }

    /// The same three values, resolved through `sys_system` first.
    ///
    /// This is what the route calls, so an operator can point the add-on at an
    /// endpoint from the admin screen and have the next request use it — the
    /// settings-block reader above stays the fallback, and stays separately
    /// testable because it needs no database.
    ///
    /// Both halves are still required: a base URL with no model is not a
    /// half-configured add-on, it is an unconfigured one, and answering with a
    /// model name the operator never chose would be worse than a 503.
    pub async fn resolve(config: &SystemConfig, settings: Option<&Value>) -> Option<Self> {
        let base_url = config
            .get_optional(settings, "ai_base_url")
            .await?
            .trim_end_matches('/')
            .to_string();
        let model = config.get_optional(settings, "ai_model").await?;
        let api_key = config.get(settings, "ai_api_key", "local").await;

        Some(Self {
            base_url,
            model,
            api_key,
        })
    }
}

/// Check the question itself, and hand back the trimmed form.
///
/// Public, and called by the controller *before* it reads the add-on's
/// settings, so a malformed request gets the same 400 whether or not a model is
/// wired up. Ordering it the other way round — which is how this shipped —
/// answered 503 for an empty question on an unconfigured app and 400 on a
/// configured one, so the same request changed meaning when an operator turned
/// the feature on, and a client could not tell "you sent nothing" from "this
/// app has no model".
///
/// `answer` calls it too. It is cheap and idempotent, and a service function
/// that trusts its caller to have validated the input is one that stops being
/// safe the moment a second caller appears.
pub fn validate_question(question: &str) -> AppResult<&str> {
    let question = question.trim();
    if question.is_empty() {
        return Err(AppError::BadRequest("query must not be empty".to_string()));
    }
    if question.chars().count() > MAX_QUESTION_CHARS {
        return Err(AppError::BadRequest(format!(
            "query must be {MAX_QUESTION_CHARS} characters or fewer"
        )));
    }
    Ok(question)
}

/// Answer one question. The whole pipeline, in the order it has to happen.
pub async fn answer(
    pool: &PgPool,
    principal: &Principal,
    dictionary: &DictionaryCache,
    repo: &DynamicRepo,
    settings: &AiSettings,
    question: &str,
) -> AppResult<Value> {
    let started = Instant::now();

    let question = validate_question(question)?;

    let schema = readable_schema(pool, principal, dictionary).await?;
    if schema.is_empty() {
        return Err(AppError::Forbidden(
            "no entities are readable by this account".to_string(),
        ));
    }

    let plan = ask_model(settings, &schema, question).await?;
    let valid = validate(dictionary, &plan).await?;

    // The control, not the filter above: run it whatever the model returned.
    authz::require_read(pool, principal, &valid.table_name).await?;

    // Bound rather than inlined: `meta` is an `Arc<TableMeta>` and `find_all`
    // takes `&TableMeta`. Written inline as `&dictionary.meta(..).await?` the
    // expected type propagates into the `?`, which then tries to convert the
    // `Arc` away instead of letting deref coercion do it at the call site.
    let meta = dictionary.meta(&valid.entity).await?;
    let result = repo
        .find_all(
            &meta,
            &valid.opts,
            &valid.filters,
            valid.search.as_deref(),
        )
        .await?;

    Ok(json!({
        "success": true,
        "data": result.data,
        "count": result.total,
        "entity": valid.table_name,
        "displayHint": valid.display_hint,
        "summary": valid.summary,
        "plan": plan,
        "executionTimeMs": started.elapsed().as_millis(),
    }))
}

/// The entities this caller may read, with their columns.
///
/// Built per request rather than cached: a role change has to take effect on
/// the next question, the same way a dictionary edit takes effect on the next
/// request everywhere else in this application.
async fn readable_schema(
    pool: &PgPool,
    principal: &Principal,
    dictionary: &DictionaryCache,
) -> AppResult<Vec<EntitySchema>> {
    let table_names: Vec<String> = sqlx::query_scalar(
        "SELECT table_name FROM sys_table \
         WHERE is_active = true AND table_name LIKE 'bus\\_%' \
         ORDER BY table_name",
    )
    .fetch_all(pool)
    .await?;

    let mut schema = Vec::new();
    for table_name in table_names {
        if authz::require_read(pool, principal, &table_name).await.is_err() {
            continue;
        }
        let Ok(meta) = dictionary.meta(&table_name).await else {
            continue;
        };
        schema.push(EntitySchema {
            table_name: meta.table_name.clone(),
            display_name: meta.name.clone(),
            columns: meta
                .columns
                .iter()
                .map(|column| column.column_name.clone())
                .collect(),
        });
    }

    Ok(schema)
}

/// Turn the schema and the question into a plan, by asking the model.
async fn ask_model(
    settings: &AiSettings,
    schema: &[EntitySchema],
    question: &str,
) -> AppResult<QueryPlan> {
    let body = json!({
        "model": settings.model,
        "temperature": 0,
        "response_format": { "type": "json_object" },
        "messages": [
            { "role": "system", "content": system_prompt(schema) },
            { "role": "user", "content": question },
        ],
    });

    // `reqwest` rather than a dedicated OpenAI client crate: this is one JSON
    // POST to one endpoint, and an SDK would add a large dependency tree to
    // every generated application for it — including applications that never
    // configure the add-on.
    let response = reqwest::Client::new()
        .post(format!("{}/chat/completions", settings.base_url))
        .bearer_auth(&settings.api_key)
        .json(&body)
        .send()
        .await
        .map_err(|err| AppError::ServiceUnavailable(format!("AI endpoint unreachable: {err}")))?;

    if !response.status().is_success() {
        let status = response.status();
        return Err(AppError::ServiceUnavailable(format!(
            "AI endpoint returned {status}"
        )));
    }

    let payload: Value = response
        .json()
        .await
        .map_err(|err| AppError::ServiceUnavailable(format!("AI endpoint sent no JSON: {err}")))?;

    let content = payload
        .get("choices")
        .and_then(|choices| choices.get(0))
        .and_then(|choice| choice.get("message"))
        .and_then(|message| message.get("content"))
        .and_then(Value::as_str)
        .ok_or_else(|| {
            AppError::ServiceUnavailable("AI endpoint sent no completion".to_string())
        })?;

    serde_json::from_str::<QueryPlan>(strip_code_fence(content)).map_err(|err| {
        // The model's prose is deliberately not echoed back to the caller: it
        // is untrusted text and this error reaches a UI.
        crate::log_event!(assistant_plan_unparseable, error = %err);
        AppError::ServiceUnavailable("AI returned an unusable answer".to_string())
    })
}

/// Models fence JSON in ```json blocks often enough to be worth handling.
fn strip_code_fence(content: &str) -> &str {
    let trimmed = content.trim();
    let Some(rest) = trimmed.strip_prefix("```") else {
        return trimmed;
    };
    let rest = rest.strip_prefix("json").unwrap_or(rest);
    rest.trim_start_matches('\n')
        .strip_suffix("```")
        .unwrap_or(rest)
        .trim()
}

fn system_prompt(schema: &[EntitySchema]) -> String {
    let mut prompt = String::from(
        "You translate a question about business data into a JSON query plan.\n\
         Reply with JSON only — no prose, no code fence.\n\n\
         Shape:\n\
         {\"entity\":\"<table>\",\"filters\":[{\"column\":\"<col>\",\"op\":\"<op>\",\"value\":\"<text>\"}],\
         \"search\":\"<text or null>\",\"order_by\":\"<col or null>\",\"order_dir\":\"asc|desc\",\
         \"limit\":<1-500>,\"display_hint\":\"table|number\",\"summary\":\"<one sentence>\"}\n\n\
         Rules:\n\
         - `entity` must be exactly one of the tables below. Pick the single best one; \
         you cannot join.\n\
         - `column` must be one of that table's columns.\n\
         - `op` must be one of: equals, gt, gte, lt, lte, contains, startsWith, endsWith.\n\
         - Use `search` for a free-text match when no single column fits.\n\
         - Use display_hint \"number\" when the question asks how many.\n\
         - If the question cannot be answered from one table, still pick the closest \
         table and say so in `summary`.\n\n\
         Tables:\n",
    );

    for entity in schema {
        prompt.push_str(&format!(
            "- {} ({}): {}\n",
            entity.table_name,
            entity.display_name,
            entity.columns.join(", ")
        ));
    }

    prompt
}

/// Resolve a column a plan wants to filter or sort on.
///
/// The dictionary describes an entity's *business* columns. It does not
/// describe the framework-managed tail every `bus_*` table carries —
/// `created_at`, `updated_at`, `doc_status` and the rest — so resolving through
/// it alone rejected the most natural questions there are. "The newest
/// compounds" is an `order_by: created_at`, and "added this month" is a filter
/// on the same column; both came back as `Unknown field 'created_at'` while
/// `DynamicRepo::find_all` was meanwhile using that exact column as its own
/// default sort.
///
/// `is_managed_column` is reused rather than a second list written here, for
/// the usual reason: two lists of the same thing drift, and this one already
/// answers precisely the question being asked — does this column exist on every
/// business table regardless of the model. That it is a fixed, code-owned set
/// is also what keeps this safe, because the name reaches `sea_query` as an
/// identifier: a plan still cannot name a column that is neither in the
/// dictionary nor in that set.
async fn resolve_filterable_column(
    dictionary: &DictionaryCache,
    entity: &str,
    column: &str,
) -> AppResult<String> {
    if is_managed_column(column) {
        return Ok(column.to_string());
    }
    dictionary.resolve_column(entity, column).await
}

/// How many rows a plan is allowed to return.
///
/// A function rather than an inline expression so the test exercises the code
/// that runs. Asserting the clamp inline re-derives it in the assertion, which
/// passes just as happily after someone removes the clamp from `validate`.
///
/// Zero is raised to one rather than honoured: a plan asking for no rows reads
/// as "nothing matched" in the UI, which is a wrong answer rather than an empty
/// one.
fn resolve_limit(requested: Option<u64>) -> u64 {
    requested.unwrap_or(DEFAULT_LIMIT).clamp(1, MAX_LIMIT)
}

/// Check every part of the plan against the dictionary.
///
/// Nothing here trusts the model. An unknown entity, an unknown column or an
/// operator outside the whitelist is a 400 naming the offending value, not a
/// silently dropped clause — a filter quietly discarded would return more rows
/// than the caller asked for and look like a correct answer.
async fn validate(dictionary: &DictionaryCache, plan: &QueryPlan) -> AppResult<ValidPlan> {
    // `resolve` fails for anything the dictionary does not describe, which is
    // what stops a hallucinated table name before it becomes an identifier.
    let table = dictionary.resolve(&plan.entity).await?;
    let table_name = table.as_str().to_string();

    let mut filters = Vec::with_capacity(plan.filters.len());
    for filter in &plan.filters {
        let column = resolve_filterable_column(dictionary, &plan.entity, &filter.column).await?;
        filters.push(Filter {
            column,
            op: FilterOp::parse(&filter.op)?,
            value: filter.value.clone(),
        });
    }

    let order_by = match plan.order_by.as_deref().filter(|value| !value.is_empty()) {
        Some(column) => Some(resolve_filterable_column(dictionary, &plan.entity, column).await?),
        None => None,
    };

    let limit = resolve_limit(plan.limit);

    Ok(ValidPlan {
        table_name,
        entity: plan.entity.clone(),
        filters,
        search: plan
            .search
            .clone()
            .filter(|term| !term.trim().is_empty()),
        opts: PaginationOptions {
            page: 1,
            limit,
            order_by,
            order_dir: OrderDir::parse(plan.order_dir.as_deref()),
        },
        display_hint: match plan.display_hint.as_deref() {
            Some("number") => "number".to_string(),
            _ => "table".to_string(),
        },
        summary: plan.summary.clone(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_plan_without_a_limit_gets_the_default_and_one_over_the_cap_is_clamped() {
        // The cap is what stops "list everything" from being a table scan the
        // REST endpoint would have refused.
        assert_eq!(resolve_limit(None), DEFAULT_LIMIT);
        assert_eq!(resolve_limit(Some(10_000)), MAX_LIMIT);
        assert_eq!(resolve_limit(Some(0)), 1);
        // A reasonable request passes through untouched.
        assert_eq!(resolve_limit(Some(10)), 10);
    }

    /// Regression: the managed columns are filterable and sortable.
    ///
    /// Found by /qa driving the page: a plan ordering by `created_at` — the
    /// column `DynamicRepo::find_all` itself defaults to — was refused with
    /// `Unknown field 'created_at'`, because the dictionary only describes
    /// business columns. "Newest first" and "added this month" are the two most
    /// natural questions a user asks, and both were 400s.
    ///
    /// This asserts the gate, not the whole resolver: a name outside the
    /// managed set still has to come from the dictionary, which is what keeps
    /// an arbitrary string out of the identifier position.
    #[test]
    fn managed_columns_are_accepted_without_the_dictionary() {
        for column in ["created_at", "updated_at", "doc_status", "id", "version"] {
            assert!(
                is_managed_column(column),
                "{column} must be filterable/sortable without a sys_column row"
            );
        }
        // Anything else still needs the dictionary to vouch for it.
        assert!(!is_managed_column("smiles"));
        assert!(!is_managed_column("1=1; DROP TABLE bus_compound"));
    }

    /// The question check, exercised through the function the controller calls
    /// rather than by restating its conditions here.
    #[test]
    fn a_question_must_be_non_empty_and_bounded() {
        assert_eq!(validate_question("  how many compounds?  ").unwrap(), "how many compounds?");
        assert!(validate_question("").is_err());
        assert!(validate_question("   \n\t ").is_err());
        assert!(validate_question(&"a".repeat(MAX_QUESTION_CHARS)).is_ok());
        assert!(validate_question(&"a".repeat(MAX_QUESTION_CHARS + 1)).is_err());
    }

    #[test]
    fn fenced_json_is_unwrapped() {
        assert_eq!(strip_code_fence("```json\n{\"a\":1}\n```"), "{\"a\":1}");
        assert_eq!(strip_code_fence("```\n{\"a\":1}\n```"), "{\"a\":1}");
        assert_eq!(strip_code_fence("  {\"a\":1}  "), "{\"a\":1}");
    }

    #[test]
    fn the_add_on_is_off_unless_both_url_and_model_are_set() {
        assert!(AiSettings::from_settings(None).is_none());
        assert!(AiSettings::from_settings(Some(&json!({}))).is_none());
        assert!(AiSettings::from_settings(Some(&json!({ "ai_base_url": "" }))).is_none());
        // A base URL with no model is a half-configuration and stays off.
        assert!(AiSettings::from_settings(Some(&json!({ "ai_base_url": "http://x/v1" }))).is_none());

        let configured = AiSettings::from_settings(Some(&json!({
            "ai_base_url": "http://localhost:8000/v1/",
            "ai_model": "qwen3.6:27b-mlx",
        })))
        .expect("both set");
        // The trailing slash is trimmed so the join cannot produce `//`.
        assert_eq!(configured.base_url, "http://localhost:8000/v1");
        assert_eq!(configured.api_key, "local");
    }

    #[test]
    fn the_prompt_names_only_the_tables_it_was_given() {
        let prompt = system_prompt(&[EntitySchema {
            table_name: "bus_compound".to_string(),
            display_name: "Compound".to_string(),
            columns: vec!["id".to_string(), "smiles".to_string()],
        }]);
        assert!(prompt.contains("bus_compound (Compound): id, smiles"));
        // The caller's unreadable tables are absent because they were filtered
        // before the prompt was built, not because the model was asked nicely.
        assert!(!prompt.contains("bus_secret"));
    }

    /// A plan carries no SQL field, so there is nothing for a prompt injection
    /// to land in. This pins that: `QueryPlan` must reject the shape the
    /// NestJS original accepted.
    #[test]
    fn a_plan_cannot_smuggle_sql() {
        let plan: QueryPlan = serde_json::from_str(
            r#"{"entity":"compound","sql":"DROP TABLE bus_compound","raw_sql":"x"}"#,
        )
        .expect("unknown fields are ignored, not accepted");
        let round_tripped = serde_json::to_value(&plan).expect("serialises");
        assert!(round_tripped.get("sql").is_none());
        assert!(round_tripped.get("raw_sql").is_none());
        assert_eq!(plan.entity, "compound");
    }
}

//! Draft → final promotion.
//!
//! A business row is inserted as a **draft**; this decides whether it becomes
//! **final** by running the entity's business rules and, if a rule asks for it,
//! its workflow.
//!
//! ## Why this runs inline (§6.7 option A, decision D3)
//!
//! The TypeScript stack dispatched promotion to Trigger.dev and then *waited*
//! for the result via `triggerAndPoll`, so the POST response could carry the
//! final `doc_status`. A Loco `BackgroundQueue` job is fire-and-forget, so
//! moving promotion onto the queue would change the create/update response
//! shape and force the client to poll — a contract break (§9) for no benefit.
//!
//! Promotion is a synchronous business decision, not background work, so it
//! runs inline here. The queue is reserved for genuinely asynchronous jobs
//! (email, reports, sync). This also matches what the TypeScript stack already
//! did whenever Trigger.dev was not configured, which was its default.

use serde_json::{Map, Value};

/// Substitute `$`-brace-field references with values from the triggering row.
///
/// This is what lets a cascade carry data forward instead of only writing
/// constants: `updateData` can name a field on the record that fired the rule,
/// and the value that field actually held is what lands on the target.
/// A reference to a field the row does not have is left as written rather than
/// blanked, so a typo is visible in the data instead of silently erasing it.
/// The columns a `transform` action asks to rewrite, resolved and filtered.
///
/// Split out from `transform` so the decision can be tested without a database:
/// what a transform writes is the part worth pinning, and the UPDATE that
/// follows it is `DynamicRepo`'s own contract.
fn transform_columns(config: &Value, row: &Value) -> Map<String, Value> {
    let Some(template) = config.get("transformData").and_then(Value::as_object) else {
        return Map::new();
    };
    let mut resolved = resolve_placeholders(template, row);
    resolved.retain(|column, _| !MANAGED_COLUMNS.contains(&column.as_str()));
    resolved
}

fn resolve_placeholders(template: &Map<String, Value>, row: &Value) -> Map<String, Value> {
    let mut resolved = Map::new();
    for (key, value) in template {
        let Some(text) = value.as_str() else {
            resolved.insert(key.clone(), value.clone());
            continue;
        };

        let Some(field) = text
            .strip_prefix('$')
            .and_then(|rest| rest.strip_prefix('{'))
            .and_then(|rest| rest.strip_suffix('}'))
        else {
            resolved.insert(key.clone(), value.clone());
            continue;
        };

        match row.get(field) {
            Some(found) => resolved.insert(key.clone(), found.clone()),
            None => resolved.insert(key.clone(), value.clone()),
        };
    }
    resolved
}

use crate::errors::AppResult;
use crate::services::dictionary::TableMeta;
use crate::services::dynamic_repo::{DynamicRepo, RawVersion};
use crate::services::rules_engine::{RuleOperation, RulesEngine};
use crate::services::workflow::{WorkflowContext, WorkflowExecutor};

/// Terminal states of the promotion pipeline. These strings are written to
/// `doc_status` and read by the frontend, so they are contract.
pub const STATUS_DRAFT: &str = "draft";
pub const STATUS_FINAL: &str = "final";
pub const STATUS_REJECTED: &str = "rejected";

/// Whether a matched rule action refuses the write rather than acting on it.
///
/// Two action names mean "do not accept this record", and they come from
/// different places: `prevent` is what the rules *editor* writes, and
/// `validation-error` is what a model's rule action compiles to. The language
/// definition is explicit that the second one rejects the write and returns
/// its message to the caller, but only the first was ever checked here — so a
/// modelled validation was compiled into `seed/rules.sql`, matched at run time,
/// fell through to `run_action`, and was logged as an unknown action while the
/// record was written and reported back as `final`.
///
/// That is the worst shape a validation failure can take: the rule is present
/// in the dictionary, the decision graph matches, and the only trace is a
/// warning nobody reads. Both names have to be recognised in the same
/// place, or the two authoring routes disagree about what a rejection is.
fn is_blocking(action_type: &str) -> bool {
    matches!(action_type, "prevent" | "validation-error")
}

/// Columns the pipeline owns, which a rule may not rewrite.
///
/// `doc_status` is what `finalize` settles and `id` names the record; a
/// transform onto either would be a rule fighting the pipeline it runs inside.
const MANAGED_COLUMNS: [&str; 5] = ["id", "doc_status", "created_at", "updated_at", "deleted_at"];

#[derive(Debug, Clone, Default)]
pub struct PromotionOutcome {
    pub doc_status: String,
    pub message: Option<String>,
    /// Columns a `transform` action rewrote, and what it wrote.
    ///
    /// The transform lands in the database as an UPDATE, so a later read shows
    /// it — but the create/update response is built from the row as it was
    /// *sent*, and returning a body that contradicts the row just written is
    /// worse than not transforming at all. The caller merges these back.
    pub transformed: Map<String, Value>,
    /// Whether an action ran that can write rows it does not name up front —
    /// a `trigger-workflow` or a `cascade-update`, either of which may land on
    /// the row that fired the rule. Unlike `transformed`, what they wrote is not
    /// known here, so the caller re-reads the row when this is set.
    pub side_effects_ran: bool,
}

impl PromotionOutcome {
    #[must_use]
    pub fn to_json(&self) -> Value {
        serde_json::json!({
            "docStatus": self.doc_status,
            "message": self.message,
        })
    }
}

#[derive(Clone)]
pub struct PromotionService {
    repo: DynamicRepo,
    rules: RulesEngine,
    /// The same executor `/api/workflow/{id}/execute` drives.
    ///
    /// A rule's `trigger-workflow` action has to *run* the workflow it names,
    /// not merely note that it would have. Holding the executor here rather
    /// than reaching into `shared_store` keeps `promote` callable from
    /// anywhere that already has this service.
    workflows: WorkflowExecutor,
}

impl PromotionService {
    #[must_use]
    pub fn new(repo: DynamicRepo, rules: RulesEngine, workflows: WorkflowExecutor) -> Self {
        Self {
            repo,
            rules,
            workflows,
        }
    }

    /// Evaluate rules for a freshly written row and settle its `doc_status`.
    ///
    /// A blocking action rejects; anything else promotes. Rule *infrastructure*
    /// failure never rejects — `RulesEngine` returns a non-matching result in
    /// that case, so the row promotes and the error is logged (§6.5 fail-open).
    pub async fn promote(
        &self,
        meta: &TableMeta,
        row: &Value,
        operation: RuleOperation,
        jdms: &[String],
        previous: Option<&Value>,
    ) -> AppResult<PromotionOutcome> {
        if jdms.is_empty() {
            // No rules configured for this entity: nothing can block it.
            return self.finalize(meta, row, STATUS_FINAL, None, Map::new(), false)
                .await;
        }

        let mut data: Map<String, Value> = row
            .as_object()
            .cloned()
            .unwrap_or_default();

        // On an update the rules also see the record as it was, under
        // `_previous_<column>`. A condition that says "when the record *enters*
        // a state" — `status == "SUBMITTED" and _previous_status != "SUBMITTED"`
        // — needs it; without it a rule can only say "while in the state", and
        // fires on every edit made there.
        if let Some(Value::Object(before)) = previous {
            for (column, value) in before {
                data.insert(format!("_previous_{column}"), value.clone());
            }
        }

        // Each document is a decision graph in its own right, so they are
        // evaluated independently and their verdicts pooled. One rule matching
        // says nothing about whether another should.
        let mut results = Vec::new();
        for jdm in jdms {
            results.extend(
                self.rules
                    .evaluate_jdm_str(&meta.table_name, jdm, &data, operation, None)
                    .await,
            );
        }

        let blocking = results
            .iter()
            .filter(|result| result.matched)
            .flat_map(|result| &result.actions)
            .find(|action| is_blocking(&action.action_type));

        if let Some(action) = blocking {
            let message = action
                .config
                .get("message")
                .and_then(Value::as_str)
                .unwrap_or("Rejected by a business rule")
                .to_string();
            // A prevented write runs no side effects: the record is not going
            // to exist, so cascading off it would leave the other tables
            // describing something that never happened.
            return self
                .finalize(meta, row, STATUS_REJECTED, Some(message), Map::new(), false)
                .await;
        }

        // Everything the rules asked for, in the order they asked. A pipeline
        // that stopped at the first action would silently drop the rest of a
        // multi-step rule, which is indistinguishable from the rule not
        // matching at all.
        let mut transformed = Map::new();
        let mut side_effects_ran = false;

        for action in results
            .iter()
            .filter(|result| result.matched)
            .flat_map(|result| &result.actions)
        {
            // A transform rewrites the row that fired the rule, so it is
            // applied here rather than in `run_action`: the columns it wrote
            // have to reach the response body, and `run_action` returns only
            // whether it succeeded.
            if action.action_type == "transform" {
                match self.transform(meta, row, &action.config).await {
                    Ok(written) => transformed.extend(written),
                    Err(err) => crate::log_event!(
                        rules_action_failed,
                        error = ?err,
                        action = "transform",
                        table = meta.table_name
                    ),
                }
                continue;
            }

            // Set before the action runs: one that fails part-way may still
            // have written.
            if matches!(action.action_type.as_str(), "trigger-workflow" | "cascade-update") {
                side_effects_ran = true;
            }
            if let Err(err) = self.run_action(meta, row, action).await {
                // A side effect that fails must not fail the write that
                // triggered it — the record is valid, and the rule is
                // automation layered on top (§6.5, fail-open).
                crate::log_event!(
                    rules_action_failed,
                    error = ?err,
                    action = action.action_type,
                    table = meta.table_name
                );
            }
        }

        self.finalize(meta, row, STATUS_FINAL, None, transformed, side_effects_ran)
            .await
    }

    /// Carry out one non-blocking rule action.
    ///
    /// These are what make the rules engine an automation surface rather than a
    /// validator: a matched rule can start a workflow, push an update into a
    /// related record, or create one somewhere else entirely.
    async fn run_action(
        &self,
        meta: &TableMeta,
        row: &Value,
        action: &crate::services::rules_engine::RuleAction,
    ) -> AppResult<()> {
        match action.action_type.as_str() {
            "trigger-workflow" => self.trigger_workflow(meta, row, &action.config).await,
            "cascade-update" => self.cascade_update(row, &action.config).await,
            "create-record" => self.create_record(&action.config, row).await,
            // The blocking actions are handled above and `transform` in the
            // loop that calls this, because it has a value to hand back;
            // anything else is a rule authored against an action this build
            // does not implement, which is worth saying out loud.
            "transform" => Ok(()),
            other if is_blocking(other) => Ok(()),
            other => {
                crate::log_event!(rules_action_unknown, action = other);
                Ok(())
            }
        }
    }

    /// Run the workflow a rule names, and record what it did.
    ///
    /// This used to insert a `sys_workflow_runs` row marked `completed` and
    /// stop. The trace was real and the work was not: a rule whose action
    /// is `trigger-workflow` produced a run log saying a chain of
    /// `CreateEntity`/`UpdateEntity`/`Formula` steps had succeeded while none
    /// of them had executed. That is worse than doing nothing, because the
    /// operator's only view into the pipeline was actively reporting the wrong
    /// answer.
    ///
    /// The definition is resolved by name because that is what a rule can
    /// carry — a JDM document is authored against the workflow the modeller
    /// called "Escalate", not against a uuid that did not exist when the rule
    /// was written. A name matching nothing is a rule pointing at a workflow
    /// somebody deleted or renamed: recorded as a failed run, not silently
    /// dropped, and never fatal to the write that triggered it.
    ///
    /// Rule infrastructure fails open (§6.5), and so does this: a workflow
    /// that throws leaves a `failed` run behind and lets the row promote. A
    /// write is not rolled back because a downstream automation broke.
    async fn trigger_workflow(
        &self,
        meta: &TableMeta,
        row: &Value,
        config: &Value,
    ) -> AppResult<()> {
        let workflow_name = config
            .get("workflowName")
            .and_then(Value::as_str)
            .unwrap_or("unnamed");

        let entity_id = row
            .get("id")
            .and_then(Value::as_str)
            .and_then(|id| uuid::Uuid::parse_str(id).ok());

        // Most recent wins: a definition may be superseded without the older
        // row being deleted, and the rule names only the workflow.
        let definition: Option<(String, String)> = sqlx::query_as(
            r"SELECT entity_name, bpmn_xml
                FROM sys_workflow_definitions
               WHERE name = $1 AND COALESCE(is_active, TRUE)
                 AND bpmn_xml IS NOT NULL
               ORDER BY created_at DESC
               LIMIT 1",
        )
        .bind(workflow_name)
        .fetch_optional(self.repo.pool())
        .await?;

        let (status, error) = match definition {
            None => (
                "failed",
                Some(format!("no active workflow named '{workflow_name}'")),
            ),
            Some((entity_name, bpmn_xml)) => {
                let outcome = self.run_definition(&entity_name, &bpmn_xml, row).await;
                match outcome {
                    Ok(()) => ("completed", None),
                    Err(err) => ("failed", Some(err.to_string())),
                }
            }
        };

        if let Some(message) = error.as_deref() {
            crate::log_event!(
                rules_workflow_incomplete,
                workflow = workflow_name,
                table = %meta.table_name,
                error = message
            );
        }

        sqlx::query(
            r"INSERT INTO sys_workflow_runs
                (entity_name, entity_id, operation, status, error_details, created_by,
                 created_at, completed_at)
              VALUES ($1, $2, 'RULE', $3, $4, $5, NOW(), NOW())",
        )
        .bind(&meta.table_name)
        .bind(entity_id)
        .bind(status)
        .bind(error)
        .bind(workflow_name)
        .execute(self.repo.pool())
        .await?;

        Ok(())
    }

    /// Parse and run one definition against the row that triggered it.
    ///
    /// The triggering row is the run's `entityData`, so a step interpolating
    /// `{{field}}` sees the record as it was written — which is what makes a
    /// rule-triggered chain able to act on the thing that set it off.
    async fn run_definition(
        &self,
        entity_name: &str,
        bpmn_xml: &str,
        row: &Value,
    ) -> AppResult<()> {
        let tasks = crate::services::workflow::parse_tasks(bpmn_xml)?;
        let mut run = WorkflowContext {
            entity_name: entity_name.to_string(),
            entity_id: row
                .get("id")
                .and_then(Value::as_str)
                .map(ToString::to_string),
            entity_data: row.as_object().cloned().unwrap_or_default(),
            decision: serde_json::Map::new(),
            vars: serde_json::Map::new(),
        };
        self.workflows.run(&tasks, &mut run).await
    }

    /// Push an update into rows of another entity related to this one.
    ///
    /// `linkField` names the column on *this* row holding the target's id, so
    /// the cascade follows the relationship the model already describes rather
    /// than inventing one.
    /// Rewrite columns on the row that fired the rule.
    ///
    /// A `transform` action with `field` and `value` is one of the
    /// three action types EML ships, and it was the one with nowhere to land:
    /// the compiler emitted no payload column for it and `run_action` had no
    /// arm, so a declared transform was logged as an unknown action and the
    /// column kept whatever the caller sent.
    ///
    /// Placeholders resolve against the triggering row, the same as a cascade,
    /// so a transform can carry a value forward rather than only write a
    /// constant. Managed columns are refused: `doc_status` is settled by
    /// `finalize` and `id` names the record, so a rule that rewrote either
    /// would be fighting the pipeline it runs inside.
    async fn transform(
        &self,
        meta: &TableMeta,
        row: &Value,
        config: &Value,
    ) -> AppResult<Map<String, Value>> {
        let resolved = transform_columns(config, row);
        if resolved.is_empty() {
            return Ok(Map::new());
        }

        let Some(id) = row
            .get("id")
            .and_then(Value::as_str)
            .and_then(|id| uuid::Uuid::parse_str(id).ok())
        else {
            return Ok(Map::new());
        };

        // Part of the write that fired the rule, so the version the response
        // returns stays the one the next save sends back.
        self.repo
            .update_raw(&meta.table_name, id, &resolved, RawVersion::Keep)
            .await?;
        Ok(resolved)
    }

    async fn cascade_update(&self, row: &Value, config: &Value) -> AppResult<()> {
        let (Some(target), Some(link_field)) = (
            config.get("targetEntity").and_then(Value::as_str),
            config.get("linkField").and_then(Value::as_str),
        ) else {
            return Ok(());
        };

        let Some(target_id) = row
            .get(link_field)
            .and_then(Value::as_str)
            .and_then(|id| uuid::Uuid::parse_str(id).ok())
        else {
            // The triggering row does not point at anything — nothing to
            // cascade into, which is a data shape, not a failure.
            return Ok(());
        };

        let Some(update_data) = config.get("updateData").and_then(Value::as_object) else {
            return Ok(());
        };

        let resolved = resolve_placeholders(update_data, row);
        if resolved.is_empty() {
            return Ok(());
        }

        // A separate write to another record: whoever has it open now holds a
        // stale copy, and their next save must say so.
        self.repo
            .update_raw(target, target_id, &resolved, RawVersion::Advance)
            .await
    }

    /// Create a row in another entity.
    async fn create_record(&self, config: &Value, row: &Value) -> AppResult<()> {
        let Some(target) = config.get("targetEntity").and_then(Value::as_str) else {
            return Ok(());
        };
        let Some(create_data) = config.get("createData").and_then(Value::as_object) else {
            return Ok(());
        };

        let resolved = resolve_placeholders(create_data, row);
        if resolved.is_empty() {
            return Ok(());
        }

        self.repo.insert_raw(target, &resolved).await
    }

    /// Write the settled status back to the row.
    ///
    /// `doc_status` is a managed column, so it is written here directly rather
    /// than through the caller-facing update path, which deliberately refuses
    /// managed columns.
    async fn finalize(
        &self,
        meta: &TableMeta,
        row: &Value,
        status: &str,
        message: Option<String>,
        transformed: Map<String, Value>,
        side_effects_ran: bool,
    ) -> AppResult<PromotionOutcome> {
        let outcome = PromotionOutcome {
            doc_status: status.to_string(),
            message,
            transformed,
            side_effects_ran,
        };

        let Some(id) = row.get("id").and_then(Value::as_str) else {
            return Ok(outcome);
        };
        let Ok(id) = uuid::Uuid::parse_str(id) else {
            return Ok(outcome);
        };

        self.repo
            .set_document_status(&meta.table_name, id, status, outcome.message.as_deref())
            .await?;
        Ok(outcome)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn outcome_serialises_to_the_contract_shape() {
        let outcome = PromotionOutcome {
            doc_status: STATUS_REJECTED.to_string(),
            message: Some("Credit limit exceeded".to_string()),
            ..PromotionOutcome::default()
        };
        let json = outcome.to_json();
        // The frontend reads exactly these keys off create/update responses.
        assert_eq!(json["docStatus"], "rejected");
        assert_eq!(json["message"], "Credit limit exceeded");
    }

    /// A `transform` action with `field` and `value` compiles to a
    /// `transformData` object, and this is what the runtime does with it.
    ///
    /// Before this the compiler emitted no payload column and `run_action` had
    /// no arm, so a declared transform was logged as an unknown action and the
    /// column kept whatever the caller sent — one of EML's three action types,
    /// inert.
    #[test]
    fn a_transform_writes_the_columns_it_names() {
        let config = serde_json::json!({
            "transformData": { "tier": "strategic", "owner": "${created_by}" }
        });
        let row = serde_json::json!({ "id": "r1", "created_by": "priya", "tier": "standard" });

        let written = transform_columns(&config, &row);
        assert_eq!(written["tier"], "strategic");
        // A placeholder carries a value forward off the triggering row, the
        // same as a cascade's `updateData`.
        assert_eq!(written["owner"], "priya");
    }

    /// A rule may not rewrite what the pipeline owns.
    ///
    /// `doc_status` is what `finalize` settles two lines later, so a transform
    /// onto it would be overwritten every time and read as a rule that does
    /// nothing. `id` names the record.
    #[test]
    fn a_transform_cannot_rewrite_a_managed_column() {
        let config = serde_json::json!({
            "transformData": { "doc_status": "final", "id": "somewhere-else", "tier": "strategic" }
        });
        let written = transform_columns(&config, &serde_json::json!({ "id": "r1" }));

        assert_eq!(written.len(), 1);
        assert_eq!(written["tier"], "strategic");
    }

    #[test]
    fn a_transform_with_no_payload_writes_nothing() {
        let row = serde_json::json!({ "id": "r1" });
        assert!(transform_columns(&serde_json::json!({}), &row).is_empty());
        assert!(transform_columns(&serde_json::json!({ "transformData": {} }), &row).is_empty());
    }

    #[test]
    fn statuses_match_the_values_written_to_doc_status() {
        assert_eq!(STATUS_DRAFT, "draft");
        assert_eq!(STATUS_FINAL, "final");
        assert_eq!(STATUS_REJECTED, "rejected");
    }

    /// Both authoring routes have to reach the same verdict. `prevent` is the
    /// editor's word for it; `validation-error` is what a model's rule action
    /// compiles to, and the language definition says it rejects the write.
    /// Recognising only the first let a modelled validation match and be
    /// discarded, with the record written and reported `final`.
    #[test]
    fn both_spellings_of_a_refusal_block_the_write() {
        assert!(is_blocking("prevent"));
        assert!(is_blocking("validation-error"));
    }

    /// The actions that *do* something to other records must not be mistaken
    /// for a refusal: blocking short-circuits before any side effect runs, so
    /// a false positive here silently drops the automation the rule asked for.
    #[test]
    fn an_action_that_does_work_is_not_a_refusal() {
        for action in ["trigger-workflow", "cascade-update", "create-record"] {
            assert!(!is_blocking(action), "{action} is not a refusal");
        }
        assert!(!is_blocking(""));
        assert!(!is_blocking("validation_error"));
    }
}

//! Postgres row → `serde_json::Value` conversion.
//!
//! The generic `bus` controller returns rows it has no compile-time type for,
//! so every value crosses the boundary through this module. The API contract
//! (§9) requires the JSON to look exactly like what the Kysely/`pg` stack
//! emitted, which makes this small module a real correctness surface — it is
//! risk R12 in docs/MIGRATION-LOCO-ASTRYX.md.
//!
//! Mapping (Appendix A):
//!   INT2/INT4/INT8  → number
//!   NUMERIC         → number    (see the note on precision below)
//!   FLOAT4/FLOAT8   → number
//!   BOOL            → boolean
//!   JSON/JSONB      → object/array, passed through untouched
//!   TIMESTAMPTZ     → ISO-8601 string, always UTC with a `Z` suffix
//!   TIMESTAMP       → ISO-8601 string, no offset
//!   DATE            → `YYYY-MM-DD`
//!   UUID            → string
//!   TEXT[]/UUID[]   → array of strings   (NULL elements stay null)
//!   everything else → string
//!
//! SQL NULL becomes JSON `null` for every type.

use chrono::{DateTime, NaiveDate, NaiveDateTime, Utc};
use rust_decimal::prelude::ToPrimitive;
use rust_decimal::Decimal;
use serde_json::{Map, Number, Value};
use sqlx::{postgres::PgRow, Column, Row, TypeInfo};
use uuid::Uuid;

/// Convert one row into a JSON object keyed by column name.
#[must_use]
pub fn row_to_json(row: &PgRow) -> Value {
    let mut map = Map::with_capacity(row.columns().len());
    for column in row.columns() {
        map.insert(column.name().to_string(), column_to_json(row, column));
    }
    Value::Object(map)
}

#[must_use]
pub fn rows_to_json(rows: &[PgRow]) -> Vec<Value> {
    rows.iter().map(row_to_json).collect()
}

fn column_to_json(row: &PgRow, column: &sqlx::postgres::PgColumn) -> Value {
    let idx = column.ordinal();

    // `type_info().name()` is the Postgres type name, upper-cased by sqlx.
    match column.type_info().name() {
        "BOOL" => opt(row.try_get::<Option<bool>, _>(idx), Value::Bool),
        "INT2" => opt(row.try_get::<Option<i16>, _>(idx), |v| {
            Value::Number(Number::from(v))
        }),
        "INT4" => opt(row.try_get::<Option<i32>, _>(idx), |v| {
            Value::Number(Number::from(v))
        }),
        "INT8" => opt(row.try_get::<Option<i64>, _>(idx), |v| {
            Value::Number(Number::from(v))
        }),
        "FLOAT4" => opt(row.try_get::<Option<f32>, _>(idx), |v| {
            f64_value(f64::from(v))
        }),
        "FLOAT8" => opt(row.try_get::<Option<f64>, _>(idx), f64_value),
        // NUMERIC is emitted as a JSON number, matching Appendix A.
        //
        // The hop through f64 is lossless *as far as the emitted JSON text is
        // concerned* for values up to ~15 significant digits, because
        // serde_json formats floats with shortest-round-trip (ryu): the
        // printed decimal is the one that parses back to the same f64. The
        // declared column types allow more than that — DECIMAL(18,6) permits
        // 18 significant digits — so a value above ~15 digits can round in the
        // 16th+ place. That is beyond any monetary magnitude this schema is
        // used for, but it is a real bound, not an absence of one, and the
        // tests below pin both sides of it.
        //
        // If a model ever needs the full 18 digits faithfully, the fix is to
        // emit NUMERIC as a JSON string here rather than to widen the float.
        "NUMERIC" => opt(row.try_get::<Option<Decimal>, _>(idx), |v| {
            v.to_f64().map_or_else(|| Value::String(v.to_string()), f64_value)
        }),
        "JSON" | "JSONB" => opt(row.try_get::<Option<Value>, _>(idx), |v| v),
        "TIMESTAMPTZ" => opt(row.try_get::<Option<DateTime<Utc>>, _>(idx), |v| {
            Value::String(v.to_rfc3339_opts(chrono::SecondsFormat::Millis, true))
        }),
        "TIMESTAMP" => opt(row.try_get::<Option<NaiveDateTime>, _>(idx), |v| {
            Value::String(v.format("%Y-%m-%dT%H:%M:%S%.3f").to_string())
        }),
        "DATE" => opt(row.try_get::<Option<NaiveDate>, _>(idx), |v| {
            Value::String(v.format("%Y-%m-%d").to_string())
        }),
        "UUID" => opt(row.try_get::<Option<Uuid>, _>(idx), |v| {
            Value::String(v.to_string())
        }),
        // A Postgres array of strings becomes a JSON array of strings.
        //
        // Without this arm these columns fall to the `String` catch-all below,
        // whose decode fails and emits `null` — silently, because a failed
        // decode is indistinguishable from a SQL NULL to every caller. The
        // schema has two such columns and both matter: `audit_log
        // .changed_fields`, which is the single field naming *what* an update
        // changed, and `allowed_roles` on the five dictionary tables, which is
        // what m0010 narrows a window by. Both read back through this module,
        // so both reported nothing while the rows held values.
        //
        // Postgres arrays may contain NULL elements; those become JSON `null`
        // rather than collapsing the array.
        "TEXT[]" | "VARCHAR[]" | "CHAR[]" | "NAME[]" => opt(
            row.try_get::<Option<Vec<Option<String>>>, _>(idx),
            |v| {
                Value::Array(
                    v.into_iter()
                        .map(|item| item.map_or(Value::Null, Value::String))
                        .collect(),
                )
            },
        ),
        "UUID[]" => opt(row.try_get::<Option<Vec<Option<Uuid>>>, _>(idx), |v| {
            Value::Array(
                v.into_iter()
                    .map(|item| item.map_or(Value::Null, |id| Value::String(id.to_string())))
                    .collect(),
            )
        }),
        // TEXT, VARCHAR, BPCHAR, NAME and anything unrecognised.
        _ => opt(row.try_get::<Option<String>, _>(idx), Value::String),
    }
}

/// Lift a `sqlx` decode result into JSON, mapping both NULL and a decode
/// failure to `null`. A decode failure is logged rather than swallowed: it
/// means this module is missing a type mapping.
fn opt<T>(
    decoded: Result<Option<T>, sqlx::Error>,
    to_json: impl FnOnce(T) -> Value,
) -> Value {
    match decoded {
        Ok(Some(value)) => to_json(value),
        Ok(None) => Value::Null,
        Err(err) => {
            crate::log_event!(entity_column_undecodable, error = %err);
            Value::Null
        }
    }
}

/// `f64` → JSON number, falling back to `null` for NaN/Infinity which JSON
/// cannot represent.
fn f64_value(value: f64) -> Value {
    Number::from_f64(value).map_or(Value::Null, Value::Number)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn f64_value_rejects_non_finite() {
        assert_eq!(f64_value(f64::NAN), Value::Null);
        assert_eq!(f64_value(f64::INFINITY), Value::Null);
        assert_eq!(f64_value(1.5), Value::Number(Number::from_f64(1.5).unwrap()));
    }

    /// Render a decimal exactly as `column_to_json` would, then serialize it.
    /// The emitted JSON text — not the intermediate f64 — is the contract.
    fn decimal_as_json_text(raw: &str) -> String {
        let decimal: Decimal = raw.parse().unwrap();
        let value = decimal
            .to_f64()
            .map_or_else(|| Value::String(decimal.to_string()), f64_value);
        serde_json::to_string(&value).unwrap()
    }

    #[test]
    fn realistic_decimal_values_survive_the_round_trip() {
        // Money at DECIMAL(18,2) and rates at DECIMAL(18,6), which is what the
        // generated schema actually stores. The contract is the *value* a JSON
        // parser recovers, not the literal text: serde_json prints shortest
        // round-trip form, so `0.000001` is emitted as `1e-6`. Both parse to
        // the same IEEE double, which is what `JSON.parse` hands the frontend.
        for raw in [
            "12345678901.23",
            "0.000001",
            "-98765.4321",
            "0",
            "1000000.5",
        ] {
            let emitted = decimal_as_json_text(raw);
            let reparsed: f64 = emitted.parse().unwrap();
            let expected: f64 = raw.parse().unwrap();
            assert!(
                (reparsed - expected).abs() <= f64::EPSILON * expected.abs().max(1.0),
                "changed value for {raw}: emitted {emitted}"
            );
        }
    }

    #[test]
    fn small_magnitudes_use_exponent_notation() {
        // Pinned deliberately: it is valid JSON and numerically identical, but
        // it is a visible difference from the TypeScript stack's output text.
        assert_eq!(decimal_as_json_text("0.000001"), "1e-6");
    }

    #[test]
    fn precision_bound_is_where_the_docs_claim_it_is() {
        // Beyond ~15 significant digits the f64 hop does round. Pinned so that
        // switching NUMERIC to a JSON string would visibly fail this test
        // rather than silently change the contract.
        assert_ne!(
            decimal_as_json_text("123456789012345678.123456"),
            "123456789012345678.123456"
        );
    }
}

//! Business-rule evaluation via GoRules ZEN.
//!
//! The TypeScript stack used `@gorules/zen-engine`, a Node binding around a Rust
//! core. Here that core is the dependency directly, so JDM files port
//! byte-for-byte and every evaluation saves an N-API boundary crossing. It is a
//! real improvement — with one constraint the design document did not foresee,
//! described under "Why evaluation runs on a blocking thread" below.
//!
//! Two behaviours from the TypeScript service are load-bearing and preserved
//! exactly (see rules-engine.service.ts.hbs):
//!
//! * **`_operation`, never `action`.** The CRUD verb travels in `_operation`
//!   so a model that has its own `action` column can still write rules against
//!   it. Injecting `action` would both clobber the column and make a
//!   required-field rule on it un-fireable, since the injected value makes the
//!   field look present even when omitted.
//! * **Fail-open.** An infrastructure failure (bad JDM, engine error) logs and
//!   returns a non-matching result so the write proceeds. Only an explicit
//!   `prevent` action rejects a request. Rules must not become an availability
//!   risk for ordinary CRUD.
//!
//! ## Why evaluation runs on a blocking thread
//!
//! `zen_engine::Variable` — the engine's own value type — is built on `Rc<str>`
//! and `Rc<RefCell<..>>`, so it is **not `Send`**. Holding one across an `.await`
//! makes the surrounding future `!Send`, and axum requires handler futures to be
//! `Send`. Calling `decision.evaluate(..).await` directly from a controller
//! therefore does not compile.
//!
//! This is worth stating plainly because §2.2 of the design document calls the
//! rules module "the one module where the migration is a strict improvement
//! with near-zero risk". The improvement is real — same engine, no N-API hop —
//! but it is not drop-in: the `!Send` value type is a genuine constraint the
//! document did not anticipate.
//!
//! The containment is to run the whole evaluation inside `spawn_blocking` on a
//! current-thread runtime, so every `Variable` is created and dropped on that
//! one thread and only `serde_json::Value` (which is `Send`) crosses back. That
//! keeps the constraint in this module instead of leaking `!Send` into every
//! caller.

use std::sync::Arc;

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};
use zen_engine::model::DecisionContent;
use zen_engine::{DecisionEngine, Variable};

/// One violation row as a JDM decision table emits it.
///
/// Field names mirror the TypeScript `JdmViolation` interface exactly, because
/// the same JDM documents feed both stacks.
#[derive(Debug, Clone, Default, Deserialize)]
#[serde(default)]
pub struct JdmViolation {
    pub action: String,
    pub message: String,
    #[serde(rename = "ruleId")]
    pub rule_id_camel: Option<String>,
    pub rule_id: Option<String>,
    #[serde(rename = "workflowName")]
    pub workflow_name: Option<String>,
    /// `cascade-*`: the table to act on.
    #[serde(rename = "targetEntity")]
    pub target_entity: Option<String>,
    /// `cascade-update` / `cascade-delete`: column on `target_entity` holding this row's id.
    #[serde(rename = "linkField")]
    pub link_field: Option<String>,
    /// The three payload fields are tolerated as either a JSON object or a
    /// JSON *string* containing one — decision-table authors write both.
    #[serde(rename = "updateData")]
    pub update_data: Option<Value>,
    #[serde(rename = "createData")]
    pub create_data: Option<Value>,
    #[serde(rename = "transformData")]
    pub transform_data: Option<Value>,
}

impl JdmViolation {
    /// `ruleId` or `rule_id`, whichever the table author used.
    #[must_use]
    pub fn rule_id(&self) -> String {
        self.rule_id_camel
            .clone()
            .or_else(|| self.rule_id.clone())
            .unwrap_or_else(|| "unknown".to_string())
    }
}

/// A single action a matched rule asks for.
#[derive(Debug, Clone, Serialize)]
pub struct RuleAction {
    #[serde(rename = "type")]
    pub action_type: String,
    pub config: Value,
}

#[derive(Debug, Clone, Serialize)]
pub struct RuleEvaluationResult {
    #[serde(rename = "ruleId")]
    pub rule_id: String,
    #[serde(rename = "ruleName")]
    pub rule_name: String,
    pub matched: bool,
    pub actions: Vec<RuleAction>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub errors: Option<Vec<String>>,
}

impl RuleEvaluationResult {
    /// The fail-open marker. `matched: false` means callers treat it as "no
    /// rule fired" — the write proceeds — while the error is still visible.
    fn engine_error(message: String) -> Self {
        Self {
            rule_id: "engine-error".to_string(),
            rule_name: "Rules Engine Error".to_string(),
            matched: false,
            actions: Vec::new(),
            errors: Some(vec![message]),
        }
    }
}

/// The CRUD verb a rule set is being evaluated for.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RuleOperation {
    Create,
    Update,
    Delete,
}

impl RuleOperation {
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Create => "create",
            Self::Update => "update",
            Self::Delete => "delete",
        }
    }
}

#[derive(Clone)]
pub struct RulesEngine {
    engine: Arc<DecisionEngine>,
}

impl Default for RulesEngine {
    fn default() -> Self {
        Self::new()
    }
}

impl RulesEngine {
    #[must_use]
    pub fn new() -> Self {
        Self {
            engine: Arc::new(DecisionEngine::default()),
        }
    }

    /// Evaluate a JDM document held as text — the database-backed path
    /// (`sys_rule_definitions.jdm_content`).
    ///
    /// `rule_name` overrides the rule id in the results when the caller knows
    /// it, matching `evaluateRulesWithJDM(.., dbRuleName)`.
    pub async fn evaluate_jdm_str(
        &self,
        entity_type: &str,
        jdm_content: &str,
        data: &Map<String, Value>,
        operation: RuleOperation,
        rule_name: Option<&str>,
    ) -> Vec<RuleEvaluationResult> {
        let content: DecisionContent = match serde_json::from_str(jdm_content) {
            Ok(content) => content,
            Err(err) => {
                crate::log_event!(rules_jdm_invalid, entity = entity_type, error = %err);
                return vec![RuleEvaluationResult::engine_error(err.to_string())];
            }
        };
        self.evaluate(entity_type, content, data, operation, rule_name)
            .await
    }

    /// Evaluate a JDM document and return what it produced, untouched.
    ///
    /// `evaluate` reads the result as a list of *violations* — `{ action,
    /// message, ... }` — which is the right shape for a rule guarding a write
    /// and the wrong one for a decision table that publishes arbitrary columns.
    /// A table emitting `{ priority, slaDays }` deserialises into no violation
    /// at all and its output is lost.
    ///
    /// A `Decision` workflow step needs the columns themselves, so it takes
    /// this path. Both share the `spawn_blocking` hop, which is not optional:
    /// `zen_engine::Variable` is built on `Rc` and is not `Send`, so awaiting
    /// `decision.evaluate` in a handler will not compile.
    pub async fn evaluate_raw(
        &self,
        entity_type: &str,
        content: DecisionContent,
        data: &Map<String, Value>,
        operation: RuleOperation,
    ) -> Result<Value, String> {
        let mut input = data.clone();
        input.insert("_operation".into(), Value::String(operation.as_str().into()));

        let engine = Arc::clone(&self.engine);
        let payload = Value::Object(input);

        let evaluated = tokio::task::spawn_blocking(move || {
            let runtime = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .map_err(|err| err.to_string())?;
            runtime.block_on(async move {
                let decision = engine.create_decision(Arc::new(content));
                decision
                    .evaluate(Variable::from(payload))
                    .await
                    .map(|response| response.result.to_value())
                    .map_err(|err| err.to_string())
            })
        })
        .await;

        match evaluated {
            Ok(Ok(value)) => Ok(value),
            Ok(Err(err)) => {
                crate::log_event!(rules_evaluation_failed, entity = entity_type, error = %err);
                Err(err)
            }
            Err(err) => {
                crate::log_event!(rules_evaluation_failed, entity = entity_type, error = %err);
                Err(err.to_string())
            }
        }
    }

    /// Evaluate a parsed JDM document.
    pub async fn evaluate(
        &self,
        entity_type: &str,
        content: DecisionContent,
        data: &Map<String, Value>,
        operation: RuleOperation,
        rule_name: Option<&str>,
    ) -> Vec<RuleEvaluationResult> {
        let mut input = data.clone();
        // See the module comment: the verb is `_operation`, and the payload is
        // otherwise passed through untouched.
        input.insert("_operation".into(), Value::String(operation.as_str().into()));

        let engine = Arc::clone(&self.engine);
        let payload = Value::Object(input);

        // Everything touching `Variable` happens inside this closure, on one
        // thread, and only a `serde_json::Value` comes back out.
        let evaluated = tokio::task::spawn_blocking(move || {
            let runtime = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .map_err(|err| err.to_string())?;
            runtime.block_on(async move {
                let decision = engine.create_decision(Arc::new(content));
                decision
                    .evaluate(Variable::from(payload))
                    .await
                    .map(|response| response.result.to_value())
                    .map_err(|err| err.to_string())
            })
        })
        .await;

        let result = match evaluated {
            Ok(Ok(value)) => value,
            Ok(Err(err)) => {
                crate::log_event!(rules_evaluation_failed, entity = entity_type, error = %err);
                return vec![RuleEvaluationResult::engine_error(err)];
            }
            Err(err) => {
                crate::log_event!(rules_evaluation_failed, entity = entity_type, error = %err);
                return vec![RuleEvaluationResult::engine_error(err.to_string())];
            }
        };

        parse_violations(&result)
            .into_iter()
            .map(|violation| {
                let id = rule_name
                    .map(ToString::to_string)
                    .unwrap_or_else(|| violation.rule_id());
                RuleEvaluationResult {
                    rule_id: id.clone(),
                    rule_name: id,
                    matched: true,
                    actions: vec![RuleAction {
                        action_type: violation.action.clone(),
                        config: to_action_config(&violation),
                    }],
                    errors: None,
                }
            })
            .collect()
    }
}

/// A decision graph may return a single object or an array of them; both are
/// valid and the TypeScript stack accepted either.
fn parse_violations(result: &Value) -> Vec<JdmViolation> {
    let parsed: Vec<JdmViolation> = match result {
        Value::Array(items) => items
            .iter()
            .filter_map(|item| serde_json::from_value(item.clone()).ok())
            .collect(),
        Value::Object(_) => serde_json::from_value(result.clone())
            .map(|violation| vec![violation])
            .unwrap_or_default(),
        _ => Vec::new(),
    };

    // A decision graph that matched nothing returns `{}`, and every field on
    // `JdmViolation` has a default — so without this an empty result
    // deserialises into a violation with an empty action, and *every* write
    // against an entity with rules reports a match that asks for nothing. The
    // action is what a violation is; one without it did not happen.
    parsed
        .into_iter()
        .filter(|violation| !violation.action.is_empty())
        .collect()
}

/// Flatten a violation into the action config the executor consumes.
fn to_action_config(violation: &JdmViolation) -> Value {
    let mut config = Map::new();
    config.insert("message".into(), Value::String(violation.message.clone()));
    if let Some(name) = &violation.workflow_name {
        config.insert("workflowName".into(), Value::String(name.clone()));
    }
    if let Some(entity) = &violation.target_entity {
        config.insert("targetEntity".into(), Value::String(entity.clone()));
    }
    if let Some(field) = &violation.link_field {
        config.insert("linkField".into(), Value::String(field.clone()));
    }
    for (key, raw) in [
        ("updateData", &violation.update_data),
        ("createData", &violation.create_data),
        ("transformData", &violation.transform_data),
    ] {
        if let Some(value) = raw {
            config.insert(key.into(), as_object(value));
        }
    }
    Value::Object(config)
}

/// Decision-table cells hold either a JSON object or a *string* containing
/// JSON. The TypeScript `asObject()` helper tolerated both, and existing models
/// rely on that, so this does too.
fn as_object(value: &Value) -> Value {
    match value {
        Value::String(text) => serde_json::from_str(text).unwrap_or_else(|_| value.clone()),
        other => other.clone(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rule_id_accepts_either_spelling() {
        let camel = JdmViolation {
            rule_id_camel: Some("R1".into()),
            ..Default::default()
        };
        assert_eq!(camel.rule_id(), "R1");

        let snake = JdmViolation {
            rule_id: Some("R2".into()),
            ..Default::default()
        };
        assert_eq!(snake.rule_id(), "R2");

        assert_eq!(JdmViolation::default().rule_id(), "unknown");
    }

    #[test]
    fn violations_parse_from_object_or_array() {
        let single = serde_json::json!({ "action": "prevent", "message": "no" });
        assert_eq!(parse_violations(&single).len(), 1);

        let many = serde_json::json!([
            { "action": "prevent", "message": "a" },
            { "action": "transform", "message": "b" },
        ]);
        assert_eq!(parse_violations(&many).len(), 2);

        // A scalar result means the graph produced no violations.
        assert!(parse_violations(&serde_json::json!(true)).is_empty());

        // So does an empty object, which is what a decision table returns when
        // no row matched — every field defaults, so this parses cleanly and has
        // to be rejected on its content instead.
        assert!(parse_violations(&serde_json::json!({})).is_empty());
        assert!(
            parse_violations(&serde_json::json!([{ "message": "no action" }])).is_empty(),
            "a violation with no action asks for nothing and is not a match"
        );
    }

    #[test]
    fn payload_fields_tolerate_json_encoded_strings() {
        let as_string = Value::String(r#"{"status":"closed"}"#.to_string());
        assert_eq!(as_object(&as_string), serde_json::json!({"status":"closed"}));

        let as_object_already = serde_json::json!({"status":"open"});
        assert_eq!(as_object(&as_object_already), as_object_already);

        // Not JSON at all — passed through rather than dropped.
        let plain = Value::String("closed".to_string());
        assert_eq!(as_object(&plain), plain);
    }

    #[tokio::test]
    async fn engine_failure_is_fail_open() {
        let engine = RulesEngine::new();
        let results = engine
            .evaluate_jdm_str(
                "bus_order",
                "{ not valid jdm",
                &Map::new(),
                RuleOperation::Create,
                None,
            )
            .await;

        assert_eq!(results.len(), 1);
        // `matched: false` is what makes the caller let the write through.
        assert!(!results[0].matched);
        assert_eq!(results[0].rule_id, "engine-error");
        assert!(results[0].errors.is_some());
    }
}

//! Configuration an operator can change without a redeploy.
//!
//! The app has two configuration layers and this resolves between them:
//!
//! 1. a `sys_system` row — active, and with a non-empty value;
//! 2. Loco's own `settings` block in `config/*.yaml`, which is resolved from
//!    the environment at boot;
//! 3. the compiled default the call site passes.
//!
//! The first layer is the new one. The second is where a deployment states
//! what it wants and is the right place for it; the problem it cannot solve is
//! changing a value while the app runs, which in a container means a redeploy
//! to edit a URL. A row here overrides the deployment, an empty or inactive row
//! falls through to it, and a key with no row at all behaves exactly as it did
//! before this table existed.
//!
//! **The key is the settings block's own name.** `ai_base_url` is one setting
//! with two places to write it, not two settings — a translation table between
//! a `SCREAMING_CASE` row and a `snake_case` setting would be one more thing to
//! keep in step, and an operator reading `config/development.yaml` beside the
//! admin screen would see two different words for the same knob.
//!
//! Values needed *before* the database answers — the connection string, the
//! listen address, the environment name — deliberately have no row and are read
//! from configuration only. A setting that has to be read to open the
//! connection cannot live behind the connection.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

use std::sync::Arc;
use std::time::Duration;

use moka::future::Cache;
use serde_json::Value;
use sqlx::PgPool;

/// The whole table, as one cached snapshot.
///
/// One entry rather than one per key: the table is a handful of rows, every
/// request that reads a setting reads it on a path that must not touch the
/// database, and a per-key cache would issue a query per miss on startup for no
/// saving. `invalidate` after a write to `/api/sys/system` is what refreshes it.
const SNAPSHOT_KEY: &str = "sys_system";

#[derive(Clone, Debug)]
struct Setting {
    value: String,
    is_active: bool,
}

#[derive(Clone)]
pub struct SystemConfig {
    pool: PgPool,
    settings: Cache<&'static str, Arc<std::collections::HashMap<String, Setting>>>,
}

impl SystemConfig {
    #[must_use]
    pub fn new(pool: PgPool) -> Self {
        Self {
            pool,
            settings: Cache::builder()
                .max_capacity(1)
                // A ceiling, not the invalidation mechanism — a dictionary write
                // to `sys_system` invalidates explicitly. This only bounds
                // staleness if some future write path forgets to, and bounds it
                // at a minute because a setting is changed to take effect now.
                .time_to_live(Duration::from_secs(60))
                .build(),
        }
    }

    /// Resolve a key: row, then settings block, then the caller's default.
    ///
    /// Never fails. A database that cannot be read leaves the settings block
    /// and the default, which is the behaviour the app had before the table —
    /// refusing to serve a request because the *optional* configuration layer
    /// is unreachable would be a strict downgrade.
    pub async fn get(&self, settings_block: Option<&Value>, key: &str, default: &str) -> String {
        if let Some(value) = self.row(key).await {
            return value;
        }
        if let Some(value) = settings_block
            .and_then(|block| block.get(key))
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
        {
            return value.to_string();
        }
        default.to_string()
    }

    /// The same resolution, reporting "not configured" rather than substituting.
    ///
    /// Separate from `get` because an empty string is a real answer for some
    /// settings and "switch the feature off" for others: the AI add-on is
    /// unconfigured when its URL is empty, and answering 503 is different from
    /// answering with an empty base URL.
    pub async fn get_optional(&self, settings_block: Option<&Value>, key: &str) -> Option<String> {
        if let Some(value) = self.row(key).await {
            return Some(value);
        }
        settings_block
            .and_then(|block| block.get(key))
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .map(str::to_string)
    }

    /// Drop the snapshot. Called after any write to `/api/sys/system`.
    pub async fn invalidate(&self) {
        self.settings.invalidate(SNAPSHOT_KEY).await;
    }

    /// The active, non-empty row for a key, if there is one.
    async fn row(&self, key: &str) -> Option<String> {
        let snapshot = self.snapshot().await?;
        snapshot
            .get(key)
            .filter(|setting| setting.is_active && !setting.value.is_empty())
            .map(|setting| setting.value.clone())
    }

    async fn snapshot(&self) -> Option<Arc<std::collections::HashMap<String, Setting>>> {
        if let Some(hit) = self.settings.get(SNAPSHOT_KEY).await {
            return Some(hit);
        }

        let rows: Vec<(String, Option<String>, bool)> = sqlx::query_as(
            "SELECT config_key, config_value, is_active FROM sys_system",
        )
        .fetch_all(&self.pool)
        .await
        .map_err(|err| {
            // Not an error the caller can act on: the resolver falls through to
            // the settings block. Recorded because a table that has stopped
            // answering explains an operator's change not taking effect, and
            // nothing else in the request would mention it.
            crate::log_event!(dictionary_config_unreadable, error = %err);
        })
        .ok()?;

        let map = rows
            .into_iter()
            .map(|(key, value, is_active)| {
                (
                    key,
                    Setting {
                        value: value.unwrap_or_default(),
                        is_active,
                    },
                )
            })
            .collect::<std::collections::HashMap<_, _>>();

        let snapshot = Arc::new(map);
        self.settings
            .insert(SNAPSHOT_KEY, Arc::clone(&snapshot))
            .await;
        Some(snapshot)
    }
}

//! BPMN workflow execution.
//!
//! Ports `bpmn-executor.service.ts`. A workflow definition is BPMN 2.0 XML
//! whose `bpmn:serviceTask` elements carry `appwithai:property` extension
//! elements describing what to do; sequence flows give the execution order.
//!
//! ## Decision D6 is moot — and the design document overstated this risk
//!
//! §6.6 and D6 assume the `Formula` task "evaluates a user-authored
//! expression" that "leans on JavaScript", and recommend adopting
//! `zen-expression` with a published compatibility note because it would be a
//! behaviour change.
//!
//! The actual implementation is not an expression evaluator. It reads four
//! named properties (`target`, `source`, `operation`, `operand`) and switches
//! over a closed set of four arithmetic operations — multiply, divide, add,
//! subtract — with an unknown operation falling through to the base value.
//! There is no JavaScript, no parser, and no user-authored syntax anywhere in
//! it. The Rust port below is therefore exact rather than approximate: no
//! expression crate is needed, no dialect changes, and risk R4 does not apply.

use std::collections::HashMap;

use quick_xml::events::Event;
use quick_xml::Reader;
use serde_json::{json, Map, Value};

use crate::errors::{AppError, AppResult};
use crate::services::dictionary::DictionaryCache;
use crate::services::dynamic_repo::{DynamicRepo, UpdateResult, WriteGuard};
use crate::services::rules_engine::{RuleOperation, RulesEngine};

#[derive(Debug, Clone, Default)]
pub struct BpmnTask {
    pub id: String,
    pub name: String,
    pub node_type: String,
    pub properties: HashMap<String, String>,
}

/// Mutable state threaded through a workflow run.
#[derive(Debug, Default)]
pub struct WorkflowContext {
    pub entity_name: String,
    pub entity_id: Option<String>,
    pub entity_data: Map<String, Value>,
    /// Output of the rule evaluation that triggered this workflow.
    pub decision: Map<String, Value>,
    /// Scratch space written by `Formula` tasks and read by later ones.
    pub vars: Map<String, Value>,
}

impl WorkflowContext {
    /// Resolve a name against decision → vars → entity data, in that order.
    /// The precedence matches the TypeScript executor exactly.
    #[must_use]
    pub fn resolve(&self, key: &str) -> Option<&Value> {
        self.decision
            .get(key)
            .or_else(|| self.vars.get(key))
            .or_else(|| self.entity_data.get(key))
    }

    fn resolve_number(&self, key: &str) -> f64 {
        self.resolve(key).map_or(0.0, |value| match value {
            Value::Number(n) => n.as_f64().unwrap_or(0.0),
            Value::String(s) => s.parse().unwrap_or(0.0),
            Value::Bool(b) => f64::from(u8::from(*b)),
            _ => 0.0,
        })
    }

    fn resolve_string(&self, key: &str) -> String {
        self.resolve(key).map_or_else(String::new, render_scalar)
    }
}

/// How a context value reads once it lands in text.
///
/// `Formula` stores every numeric literal as an f64, so a whole number comes
/// back out of serde_json as `42.0`. That is invisible while a value is only
/// ever fed to more arithmetic, and wrong the moment it reaches a person: a
/// step that titles a record `CAPA-{{seq}}` produced `CAPA-42.0`, and one that
/// wrote a computed day count into a text column stored `30.0`. A float that
/// holds a whole number is printed without the fractional part; a genuine
/// fraction keeps it.
fn render_scalar(value: &Value) -> String {
    match value {
        Value::String(s) => s.clone(),
        Value::Number(n) => n.as_f64().map_or_else(
            || n.to_string(),
            |f| {
                if f.fract() == 0.0 && f.is_finite() && f.abs() < 1e15 {
                    format!("{}", f as i64)
                } else {
                    n.to_string()
                }
            },
        ),
        other => other.to_string(),
    }
}

/// Parse the `bpmn:serviceTask` elements out of a BPMN document, in sequence
/// -flow order where the flows are well formed.
///
/// This is a pull parse rather than a DOM walk: BPMN documents are large and
/// mostly diagram layout, and only two element kinds matter here.
pub fn parse_tasks(xml: &str) -> AppResult<Vec<BpmnTask>> {
    let mut reader = Reader::from_str(xml);
    reader.config_mut().trim_text(true);

    // quick-xml reaches EOF without complaint on a truncated document, so
    // element depth is tracked explicitly: a definition with unclosed tags must
    // be rejected here, because `controllers::workflow::create` relies on this
    // parse to refuse invalid BPMN at write time rather than at trigger time.
    let mut depth: i32 = 0;
    let mut tasks: Vec<BpmnTask> = Vec::new();
    let mut flows: Vec<(String, String)> = Vec::new();
    let mut current: Option<BpmnTask> = None;
    // The value of an `appwithai:property` can arrive as a `value` attribute or
    // as element text; both spellings exist in the wild.
    let mut pending_property: Option<String> = None;
    let mut buf = Vec::new();

    loop {
        match reader.read_event_into(&mut buf) {
            Ok(Event::Eof) => {
                if depth != 0 {
                    return Err(AppError::BadRequest(
                        "Malformed BPMN XML: document has unclosed elements".to_string(),
                    ));
                }
                break;
            }
            Ok(Event::Start(e)) => {
                depth += 1;
                match local_name(e.name().as_ref()).as_str() {
                    "serviceTask" => {
                        current = Some(BpmnTask {
                            id: attribute(&e, "id").unwrap_or_default(),
                            name: attribute(&e, "name").unwrap_or_default(),
                            node_type: "Unknown".to_string(),
                            properties: HashMap::new(),
                        });
                    }
                    "property" => {
                        if let Some(task) = current.as_mut() {
                            if let Some(prop_name) = attribute(&e, "name") {
                                if let Some(value) = attribute(&e, "value") {
                                    task.properties.insert(prop_name, value);
                                } else {
                                    pending_property = Some(prop_name);
                                }
                            }
                        }
                    }
                    "sequenceFlow" => {
                        if let (Some(from), Some(to)) =
                            (attribute(&e, "sourceRef"), attribute(&e, "targetRef"))
                        {
                            flows.push((from, to));
                        }
                    }
                    _ => {}
                }
            }
            // Self-closing elements never produce an `End`, so a service task
            // written as `<serviceTask …/>` is complete the moment it is seen.
            Ok(Event::Empty(e)) => {
                match local_name(e.name().as_ref()).as_str() {
                    "serviceTask" => {
                        tasks.push(BpmnTask {
                            id: attribute(&e, "id").unwrap_or_default(),
                            name: attribute(&e, "name").unwrap_or_default(),
                            node_type: "Unknown".to_string(),
                            properties: HashMap::new(),
                        });
                    }
                    "property" => {
                        if let Some(task) = current.as_mut() {
                            if let Some(prop_name) = attribute(&e, "name") {
                                task.properties
                                    .insert(prop_name, attribute(&e, "value").unwrap_or_default());
                            }
                        }
                    }
                    "sequenceFlow" => {
                        if let (Some(from), Some(to)) =
                            (attribute(&e, "sourceRef"), attribute(&e, "targetRef"))
                        {
                            flows.push((from, to));
                        }
                    }
                    _ => {}
                }
            }
            Ok(Event::Text(text)) => {
                if let (Some(task), Some(prop)) = (current.as_mut(), pending_property.take()) {
                    let value = text.unescape().unwrap_or_default().trim().to_string();
                    task.properties.insert(prop, value);
                }
            }
            Ok(Event::End(e)) => {
                depth -= 1;
                if local_name(e.name().as_ref()) == "serviceTask" {
                    if let Some(mut task) = current.take() {
                        task.node_type = task
                            .properties
                            .get("nodeType")
                            .cloned()
                            .unwrap_or_else(|| "Unknown".to_string());
                        tasks.push(task);
                    }
                }
            }
            Err(err) => {
                return Err(AppError::BadRequest(format!("Malformed BPMN XML: {err}")));
            }
            _ => {}
        }
        buf.clear();
    }

    Ok(order_tasks(tasks, &flows))
}

/// Order tasks by walking the sequence flows.
///
/// Falls back to document order when the flows do not produce a usable chain,
/// which is what the TypeScript executor does — a diagram with no flows still
/// runs its tasks rather than silently doing nothing.
fn order_tasks(tasks: Vec<BpmnTask>, flows: &[(String, String)]) -> Vec<BpmnTask> {
    if flows.is_empty() || tasks.len() < 2 {
        return tasks;
    }

    let by_id: HashMap<&str, &BpmnTask> = tasks.iter().map(|t| (t.id.as_str(), t)).collect();
    let targets: Vec<&str> = flows.iter().map(|(_, to)| to.as_str()).collect();
    let next: HashMap<&str, &str> = flows
        .iter()
        .map(|(from, to)| (from.as_str(), to.as_str()))
        .collect();

    // The start of the chain is a task nothing points at.
    let Some(start) = tasks.iter().find(|t| !targets.contains(&t.id.as_str())) else {
        return tasks;
    };

    let mut ordered = Vec::with_capacity(tasks.len());
    let mut seen = std::collections::HashSet::new();
    let mut cursor = start.id.as_str();
    loop {
        if !seen.insert(cursor) {
            break; // A cycle in the diagram must not hang the executor.
        }
        if let Some(task) = by_id.get(cursor) {
            ordered.push((*task).clone());
        }
        match next.get(cursor) {
            Some(following) => cursor = following,
            None => break,
        }
    }

    // Any task the flows skipped still runs, after the ordered ones.
    for task in &tasks {
        if !ordered.iter().any(|t| t.id == task.id) {
            ordered.push(task.clone());
        }
    }
    ordered
}

fn local_name(raw: &[u8]) -> String {
    let name = String::from_utf8_lossy(raw);
    name.rsplit(':').next().unwrap_or(&name).to_string()
}

/// One attribute's value, with XML entities resolved.
///
/// `unescape_value` rather than the raw bytes, and that is not cosmetic: a
/// `CreateEntity` payload is JSON, so every quote in it is stored as `&quot;`.
/// Reading the raw value hands `{&quot;title&quot;:...}` to `serde_json`, which
/// rejects it — meaning *every* CreateEntity step with a field map failed at
/// run time with a parse error that pointed at the payload rather than at the
/// reader. Falls back to the lossy raw value so a malformed entity cannot make
/// the whole document unreadable.
fn attribute(element: &quick_xml::events::BytesStart<'_>, key: &str) -> Option<String> {
    element.attributes().flatten().find_map(|attr| {
        (local_name(attr.key.as_ref() ) == key).then(|| {
            attr.unescape_value().map_or_else(
                |_| String::from_utf8_lossy(&attr.value).to_string(),
                |value| value.into_owned(),
            )
        })
    })
}

/// Wrap a bare decision table in the input → table → output graph the engine
/// evaluates.
///
/// A Decision step's `decisionTable` carries the table itself — hit policy,
/// inputs, outputs, rules — because that is the interesting part and making
/// every author write the three-node plumbing around it is noise. A document
/// that already *is* a full graph (it has `nodes`) is passed through, so a
/// table pasted out of the admin editor works too.
fn wrap_decision_table(raw: &str) -> AppResult<String> {
    let parsed: Value = serde_json::from_str(raw)
        .map_err(|err| AppError::BadRequest(format!("decisionTable is not valid JSON: {err}")))?;

    if parsed.get("nodes").is_some() {
        return Ok(raw.to_string());
    }

    let graph = serde_json::json!({
        "nodes": [
            { "id": "input", "name": "Input", "type": "inputNode" },
            { "id": "table", "name": "Decision", "type": "decisionTableNode", "content": parsed },
            { "id": "output", "name": "Output", "type": "outputNode" },
        ],
        "edges": [
            { "id": "edge-1", "sourceId": "input", "targetId": "table" },
            { "id": "edge-2", "sourceId": "table", "targetId": "output" },
        ],
    });
    Ok(graph.to_string())
}

/// Executes parsed BPMN tasks against the database.
#[derive(Clone)]
pub struct WorkflowExecutor {
    repo: DynamicRepo,
    dictionary: DictionaryCache,
}

impl WorkflowExecutor {
    #[must_use]
    pub fn new(repo: DynamicRepo, dictionary: DictionaryCache) -> Self {
        Self { repo, dictionary }
    }

    /// Run every task in order. A task failure aborts the run — a half-applied
    /// workflow is worse than a reported failure.
    pub async fn run(&self, tasks: &[BpmnTask], ctx: &mut WorkflowContext) -> AppResult<()> {
        for task in tasks {
            self.execute(task, ctx).await?;
        }
        Ok(())
    }

    async fn execute(&self, task: &BpmnTask, ctx: &mut WorkflowContext) -> AppResult<()> {
        crate::log_event!(workflow_node_executing, node = task.node_type, name = task.name);
        match task.node_type.as_str() {
            "UpdateEntity" => self.update_entity(task, ctx).await,
            "CreateEntity" => self.create_entity(task, ctx).await,
            // Pure computation, no I/O — see the module comment on D6.
            "Formula" => {
                formula(task, ctx)?;
                Ok(())
            }
            "DeleteEntity" => self.delete_entity(task, ctx).await,
            "Decision" => self.decision(task, ctx).await,
            "REST" => rest(task, ctx).await,
            // Declared by the language so a diagram round-trips through the
            // designer, but not implemented here. Failing the run is the whole
            // point: skipping it completed the saga and reported success for
            // business outcomes that never happened, which is worse than not
            // offering the node at all. `shipped: false` in
            // `workflowConstructs.stepNodes` is the contract this enforces.
            unshipped @ "Agent" => Err(AppError::BadRequest(format!(
                "workflow step type '{unshipped}' is declared in EML but not executed by this \
                 backend, so the run would silently skip it. Remove the step, or implement it in \
                 services/workflow.rs."
            ))),
            other => {
                // Genuinely unknown nodes are skipped, not fatal: a diagram may
                // contain node types a newer generator understands. That
                // forward-compatibility is why this is not an error — but it
                // only applies to types this backend has never heard of.
                crate::log_event!(workflow_node_unknown, node = other);
                Ok(())
            }
        }
    }

    /// `Decision` — evaluate a decision table and publish what it decided.
    ///
    /// This is what lets a saga branch. Every other step type does a thing;
    /// this one works out *which* thing, by evaluating a GoRules table over the
    /// workflow context and writing the matching row's output columns into
    /// `ctx.vars`, where the steps after it read them.
    ///
    /// Two ways to name the table, and the choice is not stylistic:
    ///
    /// * `rule: <name>` reads a rule already in `sys_rule_definitions` — the
    ///   one the model declared in `rules`. Use it when the same table
    ///   already governs the entity, so the process does not fork a second copy
    ///   that then drifts from it.
    /// * `decisionTable: <json>` carries the table inline, for logic only this
    ///   process cares about.
    ///
    /// **A table that matches no row publishes nothing, and that is not an
    /// error.** It is how "leave it alone" is expressed: the steps after it
    /// that read a variable it would have set find nothing and skip themselves.
    /// Failing the run instead would make every optional branch fatal.
    ///
    /// `publish` narrows the output to a comma-separated allow-list, for a
    /// table that emits more than this process needs.
    async fn decision(&self, task: &BpmnTask, ctx: &mut WorkflowContext) -> AppResult<()> {
        let inline = task.properties.get("decisionTable");
        let rule_name = task.properties.get("rule");

        let jdm = match (inline, rule_name) {
            (Some(table), _) => wrap_decision_table(table)?,
            (None, Some(name)) => {
                let found: Option<(String,)> = sqlx::query_as(
                    r"SELECT jdm_content FROM sys_rule_definitions
                       WHERE rule_name = $1 AND is_active = true
                       ORDER BY updated_at DESC NULLS LAST
                       LIMIT 1",
                )
                .bind(name)
                .fetch_optional(self.repo.pool())
                .await
                .map_err(|err| AppError::Internal(anyhow::anyhow!("looking up rule {name}: {err}")))?;

                // A named rule that is not there is a modelling error, not a
                // condition to shrug at: the step would otherwise publish
                // nothing and every branch after it would quietly take the
                // "no match" path.
                let Some((content,)) = found else {
                    return Err(AppError::BadRequest(format!(
                        "Decision step references rule \"{name}\", which is not in \
                         sys_rule_definitions"
                    )));
                };
                content
            }
            (None, None) => {
                return Err(AppError::BadRequest(
                    "Decision requires either \"rule\" or \"decisionTable\"".into(),
                ))
            }
        };

        // The record plus whatever earlier steps published: a decision usually
        // reads both, and `vars` wins so a Formula can override a column.
        let mut input = ctx.entity_data.clone();
        for (key, value) in &ctx.vars {
            input.insert(key.clone(), value.clone());
        }

        let content: zen_engine::model::DecisionContent = serde_json::from_str(&jdm)
            .map_err(|err| AppError::BadRequest(format!("Decision table is not valid JDM: {err}")))?;

        let evaluated = RulesEngine::new()
            .evaluate_raw(&ctx.entity_name, content, &input, RuleOperation::Update)
            .await
            .map_err(|err| AppError::Internal(anyhow::anyhow!("Decision evaluation failed: {err}")))?;

        let allow: Option<Vec<String>> = task.properties.get("publish").map(|list| {
            list.split(',')
                .map(|key| key.trim().to_string())
                .filter(|key| !key.is_empty())
                .collect()
        });

        // `collect` yields an array, `first` a bare object. Both are legal JDM
        // results and a step should not care which hit policy the table uses.
        let rows: Vec<&Value> = match &evaluated {
            Value::Array(items) => items.iter().collect(),
            Value::Object(_) => vec![&evaluated],
            _ => Vec::new(),
        };

        let mut published = 0_usize;
        for row in rows {
            let Value::Object(fields) = row else { continue };
            for (key, value) in fields {
                if let Some(allow) = &allow {
                    if !allow.contains(key) {
                        continue;
                    }
                }
                ctx.vars.insert(key.clone(), value.clone());
                published += 1;
            }
        }

        crate::log_event!(workflow_decision_published, node = task.name, published);
        Ok(())
    }

    async fn update_entity(&self, task: &BpmnTask, ctx: &mut WorkflowContext) -> AppResult<()> {
        let field = task
            .properties
            .get("field")
            .ok_or_else(|| AppError::BadRequest("UpdateEntity requires \"field\"".into()))?;

        let entity = target_entity(task, ctx);
        let meta = self.dictionary.meta(&entity).await?;

        let value = resolved_value(task, ctx);
        let id = target_id(task, ctx, "UpdateEntity")?;

        let mut payload = Map::new();
        payload.insert(field.clone(), value);
        // A workflow writes as the system, in one statement that advances the
        // row's version — so whoever has the record open is told it changed —
        // and with no condition of its own: it is completing a transaction,
        // which a final state does not refuse.
        match self
            .repo
            .update(&meta, id, &payload, &WriteGuard::default())
            .await?
        {
            UpdateResult::Updated(_) => Ok(()),
            UpdateResult::Refused { .. } => Err(AppError::Conflict(format!(
                "UpdateEntity could not write {} {id}",
                meta.table_name
            ))),
        }
    }

    async fn create_entity(&self, task: &BpmnTask, ctx: &mut WorkflowContext) -> AppResult<()> {
        let entity = target_entity(task, ctx);
        let meta = self.dictionary.meta(&entity).await?;

        // The payload is a JSON object literal carrying placeholders resolved
        // from context. It is read from `fields` *or* `data`: the Workflow
        // Designer has always written `fields` while this executor only ever
        // read `data`, so every CreateEntity node authored in the UI inserted
        // an empty row and reported success. `fields` is the name the language
        // declares and the designer uses; `data` stays readable so diagrams
        // already stored in `sys_workflow_definitions` keep working.
        let raw = task
            .properties
            .get("fields")
            .or_else(|| task.properties.get("data"))
            .cloned()
            .unwrap_or_default();
        let rendered = interpolate(&raw, ctx);
        let declared: Map<String, Value> = if rendered.trim().is_empty() {
            Map::new()
        } else {
            serde_json::from_str(&rendered).map_err(|err| {
                AppError::BadRequest(format!("CreateEntity fields is not JSON: {err}"))
            })?
        };

        // `fields` maps a column to a **context key or a literal**, which is
        // what the language means by
        // `fields: {"account_id":"newAccountId","first_name":"first_name"}`:
        // take the id an earlier step published as `newAccountId`, and the
        // lead's own `first_name`. Only `\{{...}}` was substituted before, so a
        // bare name was written through verbatim — a saga inserted the string
        // "newAccountId" into a uuid column and 400'd, and where the column was
        // text it silently stored the word "first_name" instead of a name.
        //
        // A string that names nothing in context stays a literal, which is what
        // keeps `"status":"active"` working.
        let payload = resolve_fields(declared, ctx);

        let created = self.repo.create(&meta, &payload).await?;

        // `as` binds the new row's id into the run context, which is the only
        // way a later step can act on a record this one created.
        if let Some(key) = task.properties.get("as").filter(|k| !k.is_empty()) {
            if let Some(id) = created.get("id") {
                ctx.vars.insert(key.clone(), id.clone());
            }
        }
        Ok(())
    }

    /// Remove a record.
    ///
    /// Soft by default, like every other delete path in this stack — the row
    /// stays auditable. `hard: true` is for a record that was never real from
    /// the user's point of view, such as a placeholder an earlier step created.
    async fn delete_entity(&self, task: &BpmnTask, ctx: &mut WorkflowContext) -> AppResult<()> {
        let entity = target_entity(task, ctx);
        let meta = self.dictionary.meta(&entity).await?;
        let id = target_id(task, ctx, "DeleteEntity")?;

        let table = crate::services::dictionary::TableName::from_verified(meta.table_name.clone());
        let removed = if task
            .properties
            .get("hard")
            .is_some_and(|v| matches!(v.as_str(), "true" | "1" | "yes"))
        {
            self.repo.hard_delete(&table, id).await?
        } else {
            self.repo.soft_delete(&table, id).await?
        };

        if !removed {
            // Not an error: a step that deletes something already gone has
            // achieved what it was asked to.
            crate::log_event!(entity_delete_no_match, entity = %entity, %id);
        }
        Ok(())
    }
}

/// Which record a step acts on.
///
/// `targetSource` names a context key holding the id — how a step reaches a
/// row some earlier step produced. Without it the step acts on the record that
/// triggered the run. The designer has always offered this field; until now
/// the executor ignored it and silently wrote to the triggering record
/// instead, which on a cross-entity step is the wrong row in the wrong table.
fn target_id(task: &BpmnTask, ctx: &WorkflowContext, node: &str) -> AppResult<uuid::Uuid> {
    let raw = match task.properties.get("targetSource").filter(|s| !s.is_empty()) {
        Some(key) => ctx
            .resolve(key)
            .map(|value| match value {
                Value::String(s) => s.clone(),
                other => other.to_string(),
            })
            .ok_or_else(|| {
                AppError::BadRequest(format!("{node} targetSource \"{key}\" is not in the run context"))
            })?,
        None => ctx
            .entity_id
            .clone()
            .ok_or_else(|| AppError::BadRequest(format!("{node} requires a target record")))?,
    };

    uuid::Uuid::parse_str(raw.trim_matches('"'))
        .map_err(|_| AppError::BadRequest(format!("{node} target id is not a UUID: {raw}")))
}

/// Which `bus_` table a task acts on: its own `entity` property when present,
/// otherwise the entity that triggered the workflow.
fn target_entity(task: &BpmnTask, ctx: &WorkflowContext) -> String {
    task.properties
        .get("entity")
        .filter(|e| !e.is_empty())
        .cloned()
        .unwrap_or_else(|| ctx.entity_name.clone())
}

/// A task's value is either a literal (`value`) or a context lookup (`source`).
fn resolved_value(task: &BpmnTask, ctx: &WorkflowContext) -> Value {
    if let Some(source) = task.properties.get("source").filter(|s| !s.is_empty()) {
        return ctx.resolve(source).cloned().unwrap_or(Value::Null);
    }
    task.properties
        .get("value")
        .map_or(Value::Null, |v| Value::String(v.clone()))
}

/// A computed number, stored as an integer when it holds no fraction.
///
/// Arithmetic is done in f64, but the result is what later steps read and what
/// `{{placeholder}}` renders. Storing `42` as an f64 makes it serialise as
/// `42.0`, so a title built from a step count came out `CAPA-42.0` and a day
/// count written to a text column stored `30.0`. Whole values are narrowed to
/// i64 here so both the JSON and the rendered text say what the author meant;
/// a genuine fraction stays an f64 and keeps its precision.
fn number_value(result: f64) -> Value {
    if result.fract() == 0.0 && result.is_finite() && result.abs() < 1e15 {
        return Value::Number(serde_json::Number::from(result as i64));
    }
    serde_json::Number::from_f64(result).map_or(Value::Null, Value::Number)
}

/// The four arithmetic operations, ported exactly. An unrecognised operation
/// yields the base value unchanged, as in the original.
fn formula(task: &BpmnTask, ctx: &mut WorkflowContext) -> AppResult<()> {
    let target = task
        .properties
        .get("target")
        .ok_or_else(|| AppError::BadRequest("Formula requires \"target\"".into()))?;
    let operation = task.properties.get("operation").map(String::as_str);

    // `set` stages a literal rather than deriving one, so it is the one
    // operation with no source to read. Without it a workflow cannot introduce
    // a constant, and every arithmetic step would need its operand to already
    // exist somewhere in the context.
    if operation == Some("set") {
        let literal = task
            .properties
            .get("value")
            .ok_or_else(|| AppError::BadRequest("Formula set requires \"value\"".into()))?;
        // A literal that parses as a number is stored as one, so a later
        // arithmetic step can read it without a string round trip; anything
        // else is kept verbatim.
        let parsed = literal
            .parse::<f64>()
            .ok()
            .map_or_else(|| Value::String(literal.clone()), number_value);
        ctx.vars.insert(target.clone(), parsed);
        return Ok(());
    }

    let source = task
        .properties
        .get("source")
        .ok_or_else(|| AppError::BadRequest("Formula requires \"source\"".into()))?;

    let base = ctx.resolve_number(source);
    let operand: f64 = task
        .properties
        .get("operand")
        .and_then(|o| o.parse().ok())
        .unwrap_or(0.0);

    let result = match operation {
        Some("multiply") => base * operand,
        // Division by zero yields 0 rather than infinity — same as the original.
        Some("divide") => {
            if operand == 0.0 {
                0.0
            } else {
                base / operand
            }
        }
        Some("add") => base + operand,
        Some("subtract") => base - operand,
        _ => base,
    };

    ctx.vars.insert(target.clone(), number_value(result));
    Ok(())
}

async fn rest(task: &BpmnTask, ctx: &mut WorkflowContext) -> AppResult<()> {
    let url = task
        .properties
        .get("url")
        .filter(|u| !u.is_empty())
        .ok_or_else(|| AppError::BadRequest("REST requires \"url\"".into()))?;
    let method = task
        .properties
        .get("method")
        .cloned()
        .unwrap_or_else(|| "POST".to_string());

    // Read from `bodyTemplate` *or* `body`: the Workflow Designer writes
    // `bodyTemplate` while the language declares the property as `body`, so a
    // REST step authored in EML sent the default payload instead of the one it
    // spelled out — the same mismatch `fields`/`data` had on CreateEntity.
    // Both spellings are honoured so neither authoring path is silently wrong.
    let template = task
        .properties
        .get("bodyTemplate")
        .or_else(|| task.properties.get("body"))
        .filter(|t| !t.is_empty());
    let body = match template {
        Some(template) => interpolate(template, ctx),
        None => json!({ "entityId": ctx.entity_id, "decision": ctx.decision }).to_string(),
    };

    let response = reqwest::Client::new()
        .request(
            reqwest::Method::from_bytes(method.as_bytes())
                .map_err(|_| AppError::BadRequest(format!("Invalid REST method '{method}'")))?,
            url,
        )
        .header("Content-Type", "application/json")
        .body(body)
        .send()
        .await
        .map_err(|err| AppError::Internal(err.into()))?;

    let status = response.status();
    if !status.is_success() {
        return Err(AppError::Internal(anyhow::anyhow!(
            "REST {method} {url} returned {status}"
        )));
    }

    // `as` binds the response into the run context. The language has always
    // declared it and the executor used to discard the body, so a chain could
    // call an endpoint but never act on what it returned — which is most of
    // the reason to call one. A JSON response binds as parsed JSON so later
    // steps can reach into it; anything else binds as the raw string.
    if let Some(key) = task.properties.get("as").filter(|k| !k.is_empty()) {
        let text = response
            .text()
            .await
            .map_err(|err| AppError::Internal(err.into()))?;
        let value = serde_json::from_str::<Value>(&text).unwrap_or(Value::String(text));
        ctx.vars.insert(key.clone(), value);
    }
    Ok(())
}

/// Replace `\{{name}}` placeholders from context. Same syntax and same
/// resolution order as the TypeScript `bodyTemplate` handling.
/// Turn a `CreateEntity` field map into the row to insert.
///
/// Each value is a **context key or a literal**: a string naming something in
/// the run context resolves to it, anything else is written as given. That is
/// what lets one step say `as: newAccountId` and the next say
/// `"account_id":"newAccountId"`, while `"status":"active"` still means the
/// word "active".
fn resolve_fields(declared: Map<String, Value>, ctx: &WorkflowContext) -> Map<String, Value> {
    declared
        .into_iter()
        .map(|(column, source)| {
            let value = match &source {
                Value::String(key) => ctx.resolve(key).cloned().unwrap_or(source),
                _ => source,
            };
            (column, value)
        })
        .collect()
}

fn interpolate(template: &str, ctx: &WorkflowContext) -> String {
    let mut out = String::with_capacity(template.len());
    let mut rest = template;

    while let Some(start) = rest.find("\{{") {
        out.push_str(&rest[..start]);
        let after = &rest[start + 2..];
        match after.find("}}") {
            Some(end) => {
                let key = after[..end].trim();
                out.push_str(&ctx.resolve_string(key));
                rest = &after[end + 2..];
            }
            None => {
                // Unterminated placeholder — emit the rest verbatim.
                out.push_str("\{{");
                rest = after;
            }
        }
    }
    out.push_str(rest);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    const BPMN: &str = r#"<?xml version="1.0"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"
                  xmlns:appwithai="http://appwithai.com/schema">
  <bpmn:process id="p1">
    <bpmn:serviceTask id="t1" name="Compute total">
      <bpmn:extensionElements>
        <appwithai:properties>
          <appwithai:property name="nodeType" value="Formula"/>
          <appwithai:property name="target" value="total"/>
          <appwithai:property name="source" value="qty"/>
          <appwithai:property name="operation" value="multiply"/>
          <appwithai:property name="operand" value="3"/>
        </appwithai:properties>
      </bpmn:extensionElements>
    </bpmn:serviceTask>
    <bpmn:serviceTask id="t2" name="Notify">
      <bpmn:extensionElements>
        <appwithai:properties>
          <appwithai:property name="nodeType">REST</appwithai:property>
        </appwithai:properties>
      </bpmn:extensionElements>
    </bpmn:serviceTask>
    <bpmn:sequenceFlow id="f1" sourceRef="t1" targetRef="t2"/>
  </bpmn:process>
</bpmn:definitions>"#;

    #[test]
    fn parses_service_tasks_and_their_properties() {
        let tasks = parse_tasks(BPMN).unwrap();
        assert_eq!(tasks.len(), 2);
        assert_eq!(tasks[0].node_type, "Formula");
        assert_eq!(tasks[0].properties.get("operand").unwrap(), "3");
        // The second task spells its value as element text rather than an
        // attribute; both forms must work.
        assert_eq!(tasks[1].node_type, "REST");
    }

    #[test]
    fn sequence_flows_determine_order() {
        let tasks = parse_tasks(BPMN).unwrap();
        assert_eq!(tasks[0].id, "t1");
        assert_eq!(tasks[1].id, "t2");
    }

    #[test]
    fn malformed_xml_is_a_bad_request_not_a_panic() {
        assert!(parse_tasks("<bpmn:definitions><unclosed>").is_err());
    }

    fn ctx_with(key: &str, value: Value) -> WorkflowContext {
        let mut ctx = WorkflowContext::default();
        ctx.entity_data.insert(key.to_string(), value);
        ctx
    }

    fn formula_task(operation: &str, operand: &str) -> BpmnTask {
        let mut properties = HashMap::new();
        properties.insert("target".into(), "result".into());
        properties.insert("source".into(), "base".into());
        properties.insert("operation".into(), operation.into());
        properties.insert("operand".into(), operand.into());
        BpmnTask {
            id: "t".into(),
            name: "f".into(),
            node_type: "Formula".into(),
            properties,
        }
    }

    /// Whole results are JSON integers, not floats.
    ///
    /// `number_value` normalises `30.0` to `30` on purpose — that is what makes
    /// the API emit `30` where JavaScript would, rather than `30.0`. These
    /// assertions previously read `json!(30.0)`, which builds a float
    /// `serde_json::Number`; `Number` compares by representation, so they
    /// failed against the integer the code correctly produces. The expectation
    /// was wrong, not the implementation.
    #[test]
    fn formula_ports_all_four_operations() {
        for (op, operand, expected) in [
            ("multiply", "3", 30_i64),
            ("add", "5", 15),
            ("subtract", "4", 6),
            ("divide", "2", 5),
        ] {
            let mut ctx = ctx_with("base", json!(10));
            formula(&formula_task(op, operand), &mut ctx).unwrap();
            assert_eq!(ctx.vars["result"], json!(expected), "{op} was wrong");
            assert!(
                ctx.vars["result"].is_i64(),
                "{op} produced a float where a whole number was expected: {}",
                ctx.vars["result"]
            );
        }
    }

    /// The other half of `number_value`, which no case above reaches.
    ///
    /// Every operation in the table divides evenly, so the float branch went
    /// untested — a change that stringified fractional results, or dropped them
    /// to an integer, would have passed everything.
    #[test]
    fn a_fractional_result_stays_a_float() {
        let mut ctx = ctx_with("base", json!(10));
        formula(&formula_task("divide", "4"), &mut ctx).unwrap();
        assert_eq!(ctx.vars["result"], json!(2.5));
        assert!(ctx.vars["result"].is_f64());
    }

    #[test]
    fn divide_by_zero_yields_zero_not_infinity() {
        // Matches the TypeScript behaviour exactly; Infinity is not valid JSON.
        let mut ctx = ctx_with("base", json!(10));
        formula(&formula_task("divide", "0"), &mut ctx).unwrap();
        assert_eq!(ctx.vars["result"], json!(0));
        // Not merely "equal to zero": a null here would mean `number_value`
        // rejected a non-finite result, which is the failure this guards.
        assert!(ctx.vars["result"].is_i64());
    }

    #[test]
    fn unknown_operation_passes_the_base_through() {
        let mut ctx = ctx_with("base", json!(7));
        formula(&formula_task("exponentiate", "2"), &mut ctx).unwrap();
        assert_eq!(ctx.vars["result"], json!(7));
    }

    #[test]
    fn context_resolution_prefers_decision_then_vars_then_entity() {
        let mut ctx = WorkflowContext::default();
        ctx.entity_data.insert("x".into(), json!("entity"));
        assert_eq!(ctx.resolve_string("x"), "entity");
        ctx.vars.insert("x".into(), json!("vars"));
        assert_eq!(ctx.resolve_string("x"), "vars");
        ctx.decision.insert("x".into(), json!("decision"));
        assert_eq!(ctx.resolve_string("x"), "decision");
    }

    #[test]
    fn create_entity_fields_resolve_context_keys_and_keep_literals() {
        let mut ctx = WorkflowContext::default();
        ctx.vars
            .insert("newAccountId".into(), json!("6f1c1f16-0000-4000-8000-000000000001"));
        ctx.entity_data.insert("first_name".into(), json!("Ada"));

        let declared: Map<String, Value> = serde_json::from_str(
            r#"{"account_id":"newAccountId","first_name":"first_name","status":"active","is_primary":true}"#,
        )
        .unwrap();
        let resolved = resolve_fields(declared, &ctx);

        // A published variable and a field of the triggering record both
        // resolve; the model writes their names, not their values.
        assert_eq!(resolved["account_id"], json!("6f1c1f16-0000-4000-8000-000000000001"));
        assert_eq!(resolved["first_name"], json!("Ada"));
        // A string naming nothing in context is the value itself.
        assert_eq!(resolved["status"], json!("active"));
        // Non-strings are never treated as keys.
        assert_eq!(resolved["is_primary"], json!(true));
    }

    #[test]
    fn interpolation_fills_placeholders_and_survives_malformed_ones() {
        let ctx = ctx_with("name", json!("Ada"));
        assert_eq!(interpolate("hi \{{name}}!", &ctx), "hi Ada!");
        assert_eq!(interpolate("\{{missing}}", &ctx), "");
        assert_eq!(interpolate("\{{unterminated", &ctx), "\{{unterminated");
    }
}

//! `cargo loco task ensure_admin` — create or refresh the administrator.
//!
//! The Rust counterpart of `ensureAdminUser()` in the NestJS stack's
//! `main.ts`, and it keeps the same `ADMIN_EMAIL` / `ADMIN_PASSWORD` env vars
//! and the same defaults — the stack-agnostic `tests/` suites read those
//! defaults to log in, so changing them here would silently break the
//! cross-stack parity oracle.
//!
//! **Two tables, one administrator.** `users` is the credential store for
//! Loco's native JWT auth (decision D1); `sys_user` is the dictionary's
//! identity, and `sys_user_roles` is what every access check reads. This task
//! writes both and links them through `users.sys_user_id`, because an admin
//! that can log in but has no role is indistinguishable from an ordinary user.
//!
//! Re-running is safe and is the intended way to reset a forgotten admin
//! password: the credential row is updated in place rather than duplicated.

use loco_rs::prelude::*;
use loco_rs::task::Vars;
use uuid::Uuid;

/// Defaults shared with the NestJS stack and with `tests/harness/config.ts`.
const DEFAULT_ADMIN_EMAIL: &str = "admin@admin.com";
const DEFAULT_ADMIN_PASSWORD: &str = "admin";

/// Written to `sys_user.password_hash`, which is NOT NULL but is no longer a
/// credential in this stack — `users.password` is.
///
/// Deliberately not a real hash and not a copy of the argon2 one: it parses as
/// no hash format, so nothing can ever authenticate against it, and the admin's
/// password is stored in exactly one place. The convention is the same `!` that
/// `/etc/shadow` uses for "login disabled".
const SYS_USER_PASSWORD_DISABLED: &str = "!";

pub struct EnsureAdmin;

#[async_trait]
impl Task for EnsureAdmin {
    fn task(&self) -> TaskInfo {
        TaskInfo {
            name: "ensure_admin".to_string(),
            detail: "Create or update the administrator from ADMIN_EMAIL / ADMIN_PASSWORD"
                .to_string(),
        }
    }

    async fn run(&self, ctx: &AppContext, vars: &Vars) -> Result<()> {
        // CLI arguments win over the environment, so an operator can reset one
        // account without exporting a password into their shell history.
        let email = vars
            .cli_arg("email")
            .map(ToString::to_string)
            .or_else(|_| std::env::var("ADMIN_EMAIL"))
            .unwrap_or_else(|_| DEFAULT_ADMIN_EMAIL.to_string())
            .to_lowercase();
        let password = vars
            .cli_arg("password")
            .map(ToString::to_string)
            .or_else(|_| std::env::var("ADMIN_PASSWORD"))
            .unwrap_or_else(|_| DEFAULT_ADMIN_PASSWORD.to_string());
        let name = std::env::var("ADMIN_NAME").unwrap_or_else(|_| "Administrator".to_string());

        let pool = ctx.db.get_postgres_connection_pool();

        // The Administrator role comes from `seed_dictionary`. Failing loudly
        // here is right: silently creating a role would give it no `sys_access`
        // rows, so the admin would log in to an empty dictionary.
        let role: Option<(Uuid,)> =
            sqlx::query_as("SELECT sys_role_id FROM sys_role WHERE name = 'Administrator'")
                .fetch_optional(pool)
                .await
                .map_err(|err| Error::Message(format!("looking up Administrator role: {err}")))?;
        let Some((role_id,)) = role else {
            return Err(Error::Message(
                "no Administrator role — run `cargo loco task seed_dictionary` first".to_string(),
            ));
        };

        // `sys_user`: the dictionary identity. `email` is uniquely indexed, so
        // the conflict target is the natural key and the update covers a
        // re-run where the display name changed.
        let (sys_user_id,): (Uuid,) = sqlx::query_as(
            r"INSERT INTO sys_user (
                   sys_user_id, name, email, password_hash, description,
                   is_system_user, is_sales_rep, login_failure_count, is_locked,
                   is_account_verified, default_sys_role_id,
                   entity_type, is_active, created_by, updated_by, created_at, updated_at)
               VALUES (gen_random_uuid(), $1, $2, $3, 'Default system administrator',
                       TRUE, FALSE, 0, FALSE, TRUE, $4,
                       'D', TRUE, 'system', 'system', NOW(), NOW())
               ON CONFLICT (email) DO UPDATE
                   SET name = EXCLUDED.name,
                       default_sys_role_id = EXCLUDED.default_sys_role_id,
                       is_active = TRUE,
                       is_locked = FALSE,
                       updated_at = NOW()
               RETURNING sys_user_id",
        )
        .bind(&name)
        .bind(&email)
        .bind(SYS_USER_PASSWORD_DISABLED)
        .bind(role_id)
        .fetch_one(pool)
        .await
        .map_err(|err| Error::Message(format!("upserting sys_user: {err}")))?;

        sqlx::query(
            r"INSERT INTO sys_user_roles (
                   sys_user_roles_id, sys_user_id, sys_role_id,
                   entity_type, is_active, created_by, updated_by, created_at, updated_at)
               VALUES (gen_random_uuid(), $1, $2, 'D', TRUE, 'system', 'system', NOW(), NOW())
               ON CONFLICT (sys_user_id, sys_role_id) DO NOTHING",
        )
        .bind(sys_user_id)
        .bind(role_id)
        .execute(pool)
        .await
        .map_err(|err| Error::Message(format!("granting Administrator role: {err}")))?;

        // `users`: the credential store. Hashing goes through Loco's helper so
        // the digest is identical to the one `/api/auth/register` produces —
        // the login path has no idea this row came from a task.
        let hashed = loco_rs::hash::hash_password(&password)
            .map_err(|err| Error::Message(format!("hashing admin password: {err}")))?;

        let (created,): (bool,) = sqlx::query_as(
            r"INSERT INTO users (pid, email, password, api_key, name, sys_user_id)
               VALUES (gen_random_uuid(), $1, $2, $3, $4, $5)
               ON CONFLICT (email) DO UPDATE
                   SET password = EXCLUDED.password,
                       name = EXCLUDED.name,
                       sys_user_id = EXCLUDED.sys_user_id,
                       updated_at = NOW()
               RETURNING (xmax = 0) AS created",
        )
        .bind(&email)
        .bind(&hashed)
        .bind(format!("lo-{}", Uuid::new_v4()))
        .bind(&name)
        .bind(sys_user_id)
        .fetch_one(pool)
        .await
        .map_err(|err| Error::Message(format!("upserting admin credentials: {err}")))?;

        println!(
            "{} administrator {email} (sys_user {sys_user_id}) with the Administrator role",
            if created { "Created" } else { "Updated" }
        );
        if password == DEFAULT_ADMIN_PASSWORD {
            println!(
                "  WARNING: using the default password. Set ADMIN_PASSWORD before deploying."
            );
        }

        Ok(())
    }
}

//! One-off tasks, invoked as `cargo loco task <name>`.
//!
//! Loco's clap layer gives every task argument parsing, `--help` and listing,
//! so these need no binary and no dependency of their own (§6.15).
//!
//! * `seed_dictionary` — the `sys_*` Application Dictionary rows.
//! * `ensure_admin` — the administrator, from `ADMIN_EMAIL` / `ADMIN_PASSWORD`.
//! * `seed_workflows` — the model's `kind: saga` workflow definitions.
//! * `seed_rules` — the decision graphs the model's `rules` compile to.
//! * `seed_access` — the roles and restrictions the model's access rules declared.
//! * `seed_system` — the configuration keys an operator may change at run time.
//! * `seed_business` — demonstration records for the model's own entities.
//! * `seed_reports` — the questions the model's `reports` asked.
//!
//! All eight are also run, in this order, by `cargo loco db seed`.

pub mod ensure_admin;
pub mod seed_access;
pub mod seed_business;
pub mod seed_dictionary;
pub mod seed_reports;
pub mod seed_rules;
pub mod seed_system;
pub mod seed_workflows;

//! `cargo loco task seed_access` — the roles and restrictions the model's access rules declared.
//!
//! Two halves, and they are separate because only one of them can be SQL.
//!
//! **The rules** are `seed/access.sql`, generated from the model: roles into
//! `sys_role`, per-operation restrictions into `sys_operation_access`, and
//! per-transition restrictions into `sys_transition_access`. All deterministic
//! UUIDv5 keys, all `ON CONFLICT DO NOTHING`, so applying the file twice is a
//! no-op.
//!
//! **The accounts** are here in Rust, because a credential row needs an argon2
//! digest and SQL cannot produce one. One account per role the model named, so
//! the application can actually demonstrate its own authorization: the
//! administrator bypasses every restriction, so an application whose only
//! account is the administrator cannot show what a single access rule
//! did.
//!
//! **Why a seed rather than a migration**, for the same reason the dictionary
//! is: it is re-runnable. A model that gains a restriction must be able to top
//! up a database that has already migrated, which a migration recorded as
//! applied could never do.
//!
//! Rows are marked `is_model_managed`. A rule added inside the running
//! application is unmarked, so regeneration can replace what it owns without
//! discarding what an administrator added.
//!
//! **A `(table_name, operation)` pair with no rows is unrestricted.** That is
//! what makes the rules additive: a model declaring no access rules leaves
//! every operation exactly as open as it was, and `seed/access.sql` is then a
//! comment header and nothing else.

use loco_rs::prelude::*;
use loco_rs::task::Vars;
use sea_orm::ConnectionTrait;
use uuid::Uuid;

/// The generated access rules. Regenerate rather than edit.
const ACCESS_SQL: &str = include_str!("../../seed/access.sql");

/// The password every seeded role account gets, overridable with
/// `ROLE_ACCOUNT_PASSWORD`.
///
/// These are demonstration accounts for a generated application, and the
/// default matches `ADMIN_PASSWORD`'s so there is one password to remember
/// while trying the thing out. Set the variable — or delete the accounts —
/// before this runs anywhere real.
const DEFAULT_ROLE_PASSWORD: &str = "admin";

/// Written to `sys_user.password_hash`, which is NOT NULL but is not a
/// credential in this stack. Same convention as `ensure_admin`: a value that
/// parses as no hash format, so nothing can authenticate against it.
const SYS_USER_PASSWORD_DISABLED: &str = "!";

/// One demonstration account: email, display name, and the role it holds.
///
/// The administrator is deliberately absent — `ensure_admin` owns that account
/// and reads `ADMIN_EMAIL` / `ADMIN_PASSWORD` for it. Seeding it twice would
/// give two tasks a claim on one password.
struct RoleAccount {
    email: &'static str,
    name: &'static str,
    role_name: &'static str,
    description: &'static str,
}

const ROLE_ACCOUNTS: &[RoleAccount] = &[
{{#each access.users}}
{{#unless this.isAdmin}}
    RoleAccount {
        email: "{{this.email}}",
        name: "{{this.name}}",
        role_name: "{{this.roleName}}",
        description: "{{this.description}}",
    },
{{/unless}}
{{/each}}
];

pub struct SeedAccess;

#[async_trait]
impl Task for SeedAccess {
    fn task(&self) -> TaskInfo {
        TaskInfo {
            name: "seed_access".to_string(),
            detail: "Install the roles and access rules the model declares".to_string(),
        }
    }

    async fn run(&self, ctx: &AppContext, _vars: &Vars) -> Result<()> {
        // One call for the whole file, so a failure part-way leaves the tables
        // untouched rather than half seeded.
        ctx.db.execute_unprepared(ACCESS_SQL).await?;

        let pool = ctx.db.get_postgres_connection_pool();

        let (operations, transitions): (i64, i64) = sqlx::query_as(
            r"SELECT (SELECT COUNT(*) FROM sys_operation_access WHERE is_model_managed),
                     (SELECT COUNT(*) FROM sys_transition_access WHERE is_model_managed)",
        )
        .fetch_one(pool)
        .await
        .map_err(|err| Error::Message(format!("counting access rules: {err}")))?;

        println!(
            "✓ Access rules installed ({operations} operation rule(s), {transitions} transition rule(s))"
        );

        if ROLE_ACCOUNTS.is_empty() {
            return Ok(());
        }

        let password = std::env::var("ROLE_ACCOUNT_PASSWORD")
            .unwrap_or_else(|_| DEFAULT_ROLE_PASSWORD.to_string());
        // Hashed once rather than per account: argon2 is deliberately slow, and
        // every demonstration account shares the one password anyway.
        let hashed = loco_rs::hash::hash_password(&password)
            .map_err(|err| Error::Message(format!("hashing role account password: {err}")))?;

        for account in ROLE_ACCOUNTS {
            let role: Option<(Uuid,)> =
                sqlx::query_as("SELECT sys_role_id FROM sys_role WHERE name = $1")
                    .bind(account.role_name)
                    .fetch_optional(pool)
                    .await
                    .map_err(|err| {
                        Error::Message(format!("looking up role {}: {err}", account.role_name))
                    })?;
            // `seed/access.sql` creates every role this list names, so a miss
            // means the file was not applied. Skip rather than fail: the rules
            // are the point of the task and they are already in.
            let Some((role_id,)) = role else {
                println!(
                    "  ! role \"{}\" not found — skipping {}",
                    account.role_name, account.email
                );
                continue;
            };

            let (sys_user_id,): (Uuid,) = sqlx::query_as(
                r"INSERT INTO sys_user (
                       sys_user_id, name, email, password_hash, description,
                       is_system_user, is_sales_rep, login_failure_count, is_locked,
                       is_account_verified, default_sys_role_id,
                       entity_type, is_active, created_by, updated_by, created_at, updated_at)
                   VALUES (gen_random_uuid(), $1, $2, $3, $4,
                           FALSE, FALSE, 0, FALSE, TRUE, $5,
                           'D', TRUE, 'system', 'system', NOW(), NOW())
                   ON CONFLICT (email) DO UPDATE
                       SET name = EXCLUDED.name,
                           description = EXCLUDED.description,
                           default_sys_role_id = EXCLUDED.default_sys_role_id,
                           updated_at = NOW()
                   RETURNING sys_user_id",
            )
            .bind(account.name)
            .bind(account.email)
            .bind(SYS_USER_PASSWORD_DISABLED)
            .bind(account.description)
            .bind(role_id)
            .fetch_one(pool)
            .await
            .map_err(|err| Error::Message(format!("upserting {}: {err}", account.email)))?;

            sqlx::query(
                r"INSERT INTO sys_user_roles (
                       sys_user_roles_id, sys_user_id, sys_role_id,
                       entity_type, is_active, created_by, updated_by, created_at, updated_at)
                   VALUES (gen_random_uuid(), $1, $2, 'D', TRUE, 'system', 'system', NOW(), NOW())
                   ON CONFLICT (sys_user_id, sys_role_id) DO NOTHING",
            )
            .bind(sys_user_id)
            .bind(role_id)
            .execute(pool)
            .await
            .map_err(|err| {
                Error::Message(format!("granting {} to {}: {err}", account.role_name, account.email))
            })?;

            // The credential row. Unlike `ensure_admin`, a re-run does NOT
            // reset the password: resetting the administrator's is a documented
            // recovery path invoked deliberately, where quietly resetting an
            // account somebody changed during `cargo loco db seed` is not.
            sqlx::query(
                r"INSERT INTO users (pid, email, password, api_key, name, sys_user_id)
                   VALUES (gen_random_uuid(), $1, $2, $3, $4, $5)
                   ON CONFLICT (email) DO UPDATE
                       SET name = EXCLUDED.name,
                           sys_user_id = EXCLUDED.sys_user_id,
                           updated_at = NOW()",
            )
            .bind(account.email)
            .bind(&hashed)
            .bind(format!("lo-{}", Uuid::new_v4()))
            .bind(account.name)
            .bind(sys_user_id)
            .execute(pool)
            .await
            .map_err(|err| {
                Error::Message(format!("upserting credentials for {}: {err}", account.email))
            })?;
        }

        println!(
            "✓ {} role account(s) seeded — password \"{password}\"",
            ROLE_ACCOUNTS.len()
        );
        for account in ROLE_ACCOUNTS {
            println!("    {} ({})", account.email, account.role_name);
        }
        Ok(())
    }
}

