/// A signed-in user with no grant is refused the data, not just the menu.
///
/// `/api/bus/*` used to require a token and nothing else. `sys_access` decided
/// which windows the UI rendered, so hiding an entity hid its menu entry and
/// left its endpoint open to anyone with any account — security by menu. The
/// dictionary described the grant; only the navigation read it.
///
/// The other suites cannot catch this. Every one of them signs in as the
/// seeded administrator, who holds a master role and therefore passes every
/// check, so a guarded endpoint and an open one look identical to them. This
/// test needs a caller who is genuinely authenticated and genuinely ungranted.
///
/// A freshly registered account is exactly that: `create_with_password` makes
/// an auth user with no `sys_user` link, so it holds no roles and no grants.
#[tokio::test]
#[serial]
async fn an_authenticated_user_without_a_grant_is_refused_the_data() {
    support::with_app(|request, _ctx, admin_token| async move {
        let Some(entity) = ENTITIES.first() else { return };
        let path = format!("/api/bus/{}", entity.route);

        let email = format!("ungranted-{}@example.test", uuid::Uuid::new_v4().simple());
        let password = "Sufficiently-Long-Passw0rd";

        let registered = request
            .post("/api/auth/register")
            .json(&serde_json::json!({
                "email": &email,
                "password": password,
                "name": "Ungranted Probe",
            }))
            .await;
        assert_eq!(
            registered.status_code(),
            201,
            "could not register the probe account: {}",
            registered.text()
        );

        let logged_in = request
            .post("/api/auth/login")
            .json(&serde_json::json!({ "email": &email, "password": password }))
            .await;
        assert_eq!(logged_in.status_code(), 200, "probe account could not sign in");
        let token = logged_in.json::<Value>()["token"]
            .as_str()
            .expect("login returns a token")
            .to_string();

        // The point of the test: authenticated, and still refused.
        let refused = request
            .get(&path)
            .add_header("authorization", bearer(&token))
            .await;
        assert_eq!(
            refused.status_code(),
            403,
            "an authenticated user with no sys_access grant read {path} — the dictionary's \
             grant is not being enforced on the API, only in the navigation"
        );

        let refused_write = request
            .post(&path)
            .add_header("authorization", bearer(&token))
            .json(&serde_json::json!({ "probe": "value" }))
            .await;
        assert_eq!(
            refused_write.status_code(),
            403,
            "an authenticated user with no sys_access grant wrote to {path}"
        );

        // And the guard discriminates rather than simply breaking the route:
        // the administrator still reads the same path.
        let allowed = request
            .get(&path)
            .add_header("authorization", bearer(&admin_token))
            .await;
        assert_eq!(
            allowed.status_code(),
            200,
            "the master-role administrator was refused {path}; the guard is too strict"
        );
    })
    .await;
}

//! The rate limiter, driven over HTTP through a router of its own.
//!
//! It is not driven through the application, and that is deliberate.
//! `config/test.yaml` switches both budgets off, because the generated suites
//! produce volumes in seconds that no human session produces in an hour — the
//! bulk-seed suite alone creates thousands of records through HTTP as one
//! caller — so a budget there would be testing the limiter rather than the
//! application, and every unrelated suite would start failing with a 429 whose
//! cause none of them names.
//!
//! So this suite does what `requests/rbac.rs` does with its own rules: it
//! builds the conditions it needs. The middleware is layered over a two-route
//! router with a budget small enough to cross inside one test, and driven with
//! `tower`'s `oneshot`. What is exercised is the real `enforce` — the same
//! function `app.rs` layers onto the real router — including the key it derives
//! from the request, the scope it picks from the path, the 429 it builds and
//! the headers it writes.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

use std::{net::SocketAddr, sync::Arc};

use axum::{
    body::Body,
    extract::ConnectInfo,
    http::{Request, StatusCode},
    routing::{get, post},
    Router,
};
use tower::ServiceExt;

use {{projectSnake}}::common::rate_limit::{enforce, Limiter};

/// A router carrying the middleware, a business route and a credential route.
fn app(general: u32, auth: u32) -> Router {
    let limiter = Arc::new(Limiter::with_budgets(general, auth));
    Router::new()
        .route("/api/bus/thing", get(|| async { "ok" }))
        .route("/api/me/health", get(|| async { "ok" }))
        .route("/api/auth/login", post(|| async { "ok" }))
        .layer(axum::middleware::from_fn_with_state(limiter, enforce))
}

/// A request carrying a peer address, which is what an anonymous caller is
/// counted by. Without it every anonymous caller shares the `unknown` bucket
/// and two "different" callers in a test would be the same one.
fn from(address: &str, method: &str, path: &str) -> Request<Body> {
    let mut request = Request::builder()
        .method(method)
        .uri(path)
        .body(Body::empty())
        .expect("the test request is well-formed");
    let peer: SocketAddr = format!("{address}:54321")
        .parse()
        .expect("the test address is well-formed");
    request.extensions_mut().insert(ConnectInfo(peer));
    request
}

#[tokio::test]
async fn a_caller_over_its_budget_is_refused_with_429() {
    let router = app(2, 2);

    for _ in 0..2 {
        let response = router
            .clone()
            .oneshot(from("10.1.0.1", "GET", "/api/bus/thing"))
            .await
            .expect("the router answers");
        assert_eq!(response.status(), StatusCode::OK);
    }

    let refused = router
        .clone()
        .oneshot(from("10.1.0.1", "GET", "/api/bus/thing"))
        .await
        .expect("the router answers");
    assert_eq!(refused.status(), StatusCode::TOO_MANY_REQUESTS);

    // Retry-After is what a client obeys. Without it a refusal says only "no",
    // and a client that retries immediately turns one refusal into a loop.
    let headers = refused.headers();
    assert!(headers.contains_key("retry-after"), "no Retry-After");
    assert_eq!(
        headers
            .get("ratelimit-remaining")
            .and_then(|value| value.to_str().ok()),
        Some("0")
    );
    assert_eq!(
        headers
            .get("ratelimit-limit")
            .and_then(|value| value.to_str().ok()),
        Some("2")
    );
}

#[tokio::test]
async fn a_served_response_says_how_much_budget_is_left() {
    let router = app(5, 5);

    let response = router
        .oneshot(from("10.1.0.2", "GET", "/api/bus/thing"))
        .await
        .expect("the router answers");

    assert_eq!(response.status(), StatusCode::OK);
    // On the way through, not only at the wall: a client that can read its
    // remaining budget can slow down before it is refused.
    assert_eq!(
        response
            .headers()
            .get("ratelimit-remaining")
            .and_then(|value| value.to_str().ok()),
        Some("4")
    );
    assert!(
        !response.headers().contains_key("retry-after"),
        "Retry-After on a served response says the opposite of what happened"
    );
}

