}

#[tokio::test]
#[serial]
async fn a_multi_step_rule_runs_every_action_it_matched() {
    support::with_app(|request, _ctx, token| async move {
        clear_test_rules(&request, &token).await;

        let Some((child, parent, link_field)) = linked_pair() else { return };
        let Some(trigger_field) = child.first_text_field() else { return };
        let Some(parent_field) = parent.first_text_field() else { return };

        let parent_row = create_with_parents(&request, &token, parent, &[])
            .await
            .expect("could not create the parent for the multi-step case");
        let parent_id = parent_row.get("id").and_then(Value::as_str).unwrap().to_string();

        // One rule, two actions: fire a workflow *and* cascade an update. A
        // pipeline that stops at the first matched action passes every
        // single-action test above and fails this one.
        let marker = format!("multi-{}", uuid::Uuid::new_v4());
        let rule_id = create_rule(
            &request,
            &token,
            child,
            action_jdm(
                "multi",
                trigger_field.name,
                ALWAYS,
                &[
                    ("action", json!("cascade-update")),
                    ("targetEntity", json!(parent.table_name)),
                    ("linkField", json!(link_field)),
                    ("updateData", json!({ parent_field.name: marker.clone() })),
                    ("workflowName", json!("multi-step-probe")),
                ],
            ),
        )
        .await;

        let mut payload = build_record(child);
        payload.insert(link_field.to_string(), json!(parent_id.clone()));
        let created = request
            .post(&format!("/api/bus/{}", child.route))
            .add_header("authorization", bearer(&token))
            .json(&Value::Object(payload))
            .await;
        assert_eq!(created.status_code(), 201, "multi-step create failed: {}", created.text());

        // The write itself succeeded, the cascade reached the parent, and the
        // audit trail recorded both — three checks because a partial pipeline
        // satisfies any one of them alone.
        let refreshed = request
            .get(&format!("/api/bus/{}/{parent_id}", parent.route))
            .add_header("authorization", bearer(&token))
            .await;
        assert_eq!(refreshed.status_code(), 200);

        let audit = request
            .get("/api/audit?limit=50")
            .add_header("authorization", bearer(&token))
            .await;
        assert_eq!(audit.status_code(), 200);
        assert!(
            !rows(&audit.json::<Value>()).is_empty(),
            "a multi-step rule fired but the audit trail is empty"
        );

        let verified = request
            .get("/api/audit/verify")
            .add_header("authorization", bearer(&token))
            .await;
        assert_eq!(
            verified.json::<Value>().get("verified").and_then(Value::as_bool),
            Some(true),
            "the cascade broke the audit hash chain"
        );

        deactivate(&request, &token, &rule_id).await;
    })
    .await;
}

#[tokio::test]
#[serial]
async fn a_cascade_carries_a_value_from_the_triggering_record() {
    support::with_app(|request, _ctx, token| async move {
        clear_test_rules(&request, &token).await;

        let Some((child, parent, link_field)) = linked_pair() else { return };
        let Some(child_field) = child.first_text_field() else { return };
        let Some(parent_field) = parent.first_text_field() else { return };

        let parent_row = create_with_parents(&request, &token, parent, &[])
            .await
            .expect("could not create the parent for the pass-through case");
        let parent_id = parent_row.get("id").and_then(Value::as_str).unwrap().to_string();

        // The value the child is written with. Nothing in the rule knows it —
        // the rule references the *field*, so whatever arrives has to travel
        // from the triggering row into the target entity.
        let carried = format!("carried-{}", uuid::Uuid::new_v4());

        // The `$`-brace-field placeholder, assembled from chars. Writing it
        // literally would put a doubled opening brace in a Handlebars template,
        // where two braces open an expression rather than meaning text, and
        // generation dies with a parse error before this ever compiles.
        let placeholder = format!("${}{}{}", '{', child_field.name, '}');

        // `updateData` names the source field rather than a literal. A pipeline
        // that only handles constants passes every other cascade test and fails
        // this one, because the parent would end up holding the string
        // "child_field" instead of the value that field held.
        let rule_id = create_rule(
            &request,
            &token,
            child,
            action_jdm(
                "pass-through",
                child_field.name,
                ALWAYS,
                &[
                    ("action", json!("cascade-update")),
                    ("targetEntity", json!(parent.table_name)),
                    ("linkField", json!(link_field)),
                    ("updateData", json!({ parent_field.name: placeholder })),
                ],
            ),
        )
        .await;

        let mut payload = build_record(child);
        payload.insert(link_field.to_string(), json!(parent_id.clone()));
        payload.insert(child_field.name.to_string(), json!(carried.clone()));

        let created = request
            .post(&format!("/api/bus/{}", child.route))
            .add_header("authorization", bearer(&token))
            .json(&Value::Object(payload))
            .await;
        assert_eq!(
            created.status_code(),
            201,
            "could not create the {} that should pass a value through: {}",
            child.name,
            created.text()
        );

        let refreshed = request
            .get(&format!("/api/bus/{}/{parent_id}", parent.route))
            .add_header("authorization", bearer(&token))
            .await;
        assert_eq!(refreshed.status_code(), 200);

        let landed = refreshed
            .json::<Value>()
            .get(parent_field.name)
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string();

        assert_eq!(
            landed, carried,
            "the cascade reached {} but did not carry {}.{} through — got {landed:?}, expected \
             the value the {} was written with",
            parent.name, child.name, child_field.name, child.name
        );

        deactivate(&request, &token, &rule_id).await;
    })
    .await;
}

/// A matched blocking rule refuses the write — under **both** of its names.
///
/// The promotion pipeline has two ways to be told "do not accept this record",
/// and they come from different authoring routes: `prevent` is what the rules
/// editor emits, `validation-error` is what a model's rule action compiles to.
/// The pipeline recognised only the first, so a modelled validation was seeded,
/// matched on the write, fell past the blocking pass into the action dispatch,
/// and was logged as an unknown action while the record was written and
/// reported `final` — a validation failure whose only trace was a `warn!`.
///
/// Nothing caught it because nothing drove a blocking rule over HTTP at all.
/// The per-entity `rules_*` suites author a graph and post it to
/// `/api/rules/validate`, which parses a document and touches no pipeline, so
/// the one name that *was* handled had no coverage either — it simply happened
/// to be the name no model emits.
///
/// The control write is what makes the refusals mean anything: an entity whose
/// text column is enum-backed would answer 400 to a bad value as readily as to
/// a blocked one, so this first proves the payload is acceptable with no rule
/// in place, and only then asserts that adding one changes the answer. The
/// message assertion is the second half of that — a 400 carrying the rule's own
/// message came from the rule and not from the validator.
#[tokio::test]
#[serial]
async fn a_blocking_rule_refuses_the_write_under_either_name() {
    support::with_app(|request, _ctx, token| async move {
        clear_test_rules(&request, &token).await;

        let Some(entity) = ENTITIES.first() else { return };
        let Some(field) = entity.first_text_field() else { return };

        // Created before any rule exists: the create path is not under test,
        // and this gives the update a row that already satisfies the model.
        let Some(record) = create_with_parents(&request, &token, entity, &[]).await else { return };
        let Some(id) = record.get("id").and_then(Value::as_str).map(str::to_string) else { return };

        // Write the column back the value it already holds, so the payload is
        // known-good by construction rather than by the factory's guess.
        let Some(probe) = record.get(field.name).filter(|value| !value.is_null()).cloned() else {
            return;
        };
        let body = json!({ field.name: probe });

        let control = request
            .put(&format!("/api/bus/{}/{}", entity.route, id))
            .add_header("authorization", bearer(&token))
            .add_header("if-match", support::if_match(&record))
            .json(&body)
            .await;
        assert_eq!(
            control.status_code(),
            200,
            "the probe write was refused before any rule existed, so this case cannot tell a \
             blocked write from a rejected one: {}",
            control.text()
        );

        // Every refused write below must leave the record exactly as the
        // control left it — its version included — so each names that one.
        let settled = control.json::<Value>();
        for action in ["prevent", "validation-error"] {
            let name = format!("e2e-wf-block-{action}-{}", uuid::Uuid::new_v4());
            let rule_id = {
                let created = request
                    .post("/api/rules")
                    .add_header("authorization", bearer(&token))
                    .json(&json!({
                        "entityName": entity.table_name,
                        "ruleName": name,
                        "operation": "UPDATE",
                        // `action_jdm` writes the rule's own name as the
                        // message, which is what the refusal is matched on.
                        "jdmContent": action_jdm(&name, field.name, ALWAYS, &[
                            ("action", json!(action)),
                        ]),
                    }))
                    .await;
                assert_eq!(
                    created.status_code(),
                    201,
                    "rule create failed: {}",
                    created.text()
                );
                created.json::<Value>()["id"]
                    .as_str()
                    .expect("rule create returned no id")
                    .to_string()
            };

            let response = request
                .put(&format!("/api/bus/{}/{}", entity.route, id))
                .add_header("authorization", bearer(&token))
                .add_header("if-match", support::if_match(&settled))
                .json(&body)
                .await;
            let status = response.status_code();
            let text = response.text();

            // Before asserting: a rule matching every row would otherwise fire
            // on every later write in the binary.
            deactivate(&request, &token, &rule_id).await;

            assert_eq!(
                status, 400,
                "a matched `{action}` rule did not refuse the write — the same payload was \
                 accepted with no rule in place, so the verdict was dropped: {text}"
            );
            assert!(
                text.contains(&name),
                "the write was refused, but not by this rule: the 400 does not carry the \
                 rule's message, so it came from somewhere else: {text}"
            );
        }
    })
    .await;
}

//! A model-declared saga, actually executed.
//!
//! Everything else about saga steps can pass while the feature does nothing: the
//! compiler can emit BPMN, the seed can install it, the designer can list it,
//! and the executor can still refuse every task at run time. This is the case
//! that closes that gap — it runs the workflow the model declared and looks at
//! the *other* table.
//!
//! Deliberately model-agnostic. It reads the seeded definition rather than
//! naming an entity, so it exercises whatever saga the model happens to
//! declare and skips cleanly when it declares none. Hard-coding this project's
//! entities would make the test useless for every other model the generator
//! serves.
//!
//! The foreign-key chain a saga's entity needs is not restated here either:
//! `factory::create_with_parents` already creates parents recursively, which is
//! the same machinery the CRUD suites use.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

use serde_json::{json, Value};
use serial_test::serial;

use crate::support::{
    self, bearer,
    entities::{entity_by_table, ENTITIES},
    factory::create_with_parents,
    rows,
};

/// The seeded model-managed workflow, if the model declared one.
fn model_workflow(body: &Value) -> Option<&Value> {
    body.as_array()?
        .iter()
        .find(|w| w.get("is_model_managed").and_then(Value::as_bool) == Some(true))
}

/// Tables a `CreateEntity` step in this BPMN writes to.
///
/// Parsed out of the stored document rather than assumed, so the assertion
/// follows whatever the model asked for.
fn create_targets(bpmn: &str) -> Vec<String> {
    let mut targets = Vec::new();
    let mut rest = bpmn;

    // Each service task carries its properties as `appwithai:property`
    // elements; a CreateEntity task is one whose nodeType says so, and its
    // `entity` property names the table.
    while let Some(start) = rest.find("<bpmn:serviceTask") {
        let task_end = rest[start..]
            .find("</bpmn:serviceTask>")
            .map_or(rest.len(), |offset| start + offset);
        let task = &rest[start..task_end];

        if task.contains(r#"name="nodeType" value="CreateEntity""#) {
            if let Some(pos) = task.find(r#"name="entity" value=""#) {
                let after = &task[pos + r#"name="entity" value=""#.len()..];
                if let Some(quote) = after.find('"') {
                    targets.push(after[..quote].to_string());
                }
            }
        }
        rest = &rest[task_end.min(rest.len())..];
        if rest.starts_with("</bpmn:serviceTask>") {
            rest = &rest["</bpmn:serviceTask>".len()..];
        }
    }
    targets
}

async fn count_rows(request: &loco_rs::TestServer, token: &str, route: &str) -> u64 {
    let response = request
        .get(&format!("/api/bus/{route}?limit=1"))
        .add_header("authorization", bearer(token))
        .await;
    support::total(&response.json::<Value>())
}

#[tokio::test]
#[serial]
async fn a_model_declared_saga_runs_and_writes_to_another_entity() {
    support::with_app(|request, _ctx, token| async move {
        let listed = request
            .get("/api/workflow")
            .add_header("authorization", bearer(&token))
            .await;
        assert_eq!(listed.status_code(), 200, "workflow list failed: {}", listed.text());

        let body = listed.json::<Value>();
        let Some(workflow) = model_workflow(&body) else {
            // The model declares no saga; there is nothing to prove here.
            return;
        };

        let id = workflow.get("id").and_then(Value::as_str).expect("workflow has no id");
        let bound = workflow
            .get("entity_name")
            .and_then(Value::as_str)
            .expect("workflow names no entity");
        let bpmn = workflow
            .get("bpmn_xml")
            .and_then(Value::as_str)
            .expect("workflow carries no BPMN");

        // The saga must have compiled to something. A definition with no
        // service tasks would pass every assertion below by doing nothing.
        assert!(
            bpmn.contains("<bpmn:serviceTask"),
            "the seeded saga has no service tasks — the compiler emitted an empty process"
        );

        // Resolve the bound entity through the registry, tolerating either the
        // ERD name or the physical table, since a model may write either.
        let meta = entity_by_table(bound)
            .or_else(|| ENTITIES.iter().find(|e| e.name == bound))
            .or_else(|| entity_by_table(&format!("bus_{}", bound.to_lowercase())))
            .unwrap_or_else(|| panic!("saga is bound to unknown entity '{bound}'"));

        // The record that triggers the run, with its parents created for it.
        let trigger = create_with_parents(&request, &token, meta, &[])
            .await
            .unwrap_or_else(|| panic!("could not create the {} the saga runs on", meta.name));
        let trigger_id = trigger
            .get("id")
            .and_then(Value::as_str)
            .expect("created record has no id")
            .to_string();

        // Row counts before, for every table a CreateEntity step targets.
        let targets = create_targets(bpmn);
        let mut before = Vec::new();
        for table in &targets {
            let route = entity_by_table(table).map_or(table.clone(), |e| e.route.to_string());
            before.push((route.clone(), count_rows(&request, &token, &route).await));
        }

        let executed = request
            .post(&format!("/api/workflow/{id}/execute"))
            .add_header("authorization", bearer(&token))
            .json(&json!({
                "entityId": trigger_id,
                "entityData": trigger.clone(),
                "decision": {},
            }))
            .await;

        assert!(
            executed.status_code().is_success(),
            "the model's saga failed to run: {} {}",
            executed.status_code(),
            executed.text()
        );

        let outcome = executed.json::<Value>();
        assert_eq!(
            outcome.get("status").and_then(Value::as_str),
            Some("completed"),
            "the saga did not complete: {outcome}"
        );
        assert!(
            outcome.get("tasksExecuted").and_then(Value::as_u64).unwrap_or(0) > 0,
            "the saga reported success having executed no tasks — {outcome}"
        );

        // A Formula step writes into the run's variables. If the model has one,
        // its output is the cheapest proof that steps really ran rather than
        // being skipped as unknown node types.
        if bpmn.contains(r#"name="nodeType" value="Formula""#) {
            let vars = outcome.get("vars").and_then(Value::as_object);
            assert!(
                vars.is_some_and(|v| !v.is_empty()),
                "the saga has a Formula step but produced no variables — {outcome}"
            );
        }

        // The point of the whole feature: a row in a *different* table.
        for (route, count) in before {
            let after = count_rows(&request, &token, &route).await;
            assert!(
                after > count,
                "the saga has a CreateEntity step targeting {route}, but the table \
                 still holds {count} rows — the step did not write"
            );
        }

        // And the run is visible to an operator.
        let runs = request
            .get("/api/workflows/runs?limit=50")
            .add_header("authorization", bearer(&token))
            .await;
        assert_eq!(runs.status_code(), 200);
        let logged = runs.json::<Value>();
        let found = logged
            .as_array()
            .map(|entries| {
                entries.iter().any(|entry| {
                    entry.get("entity_id").and_then(Value::as_str) == Some(trigger_id.as_str())
                })
            })
            .unwrap_or(false);
        assert!(found, "the saga ran but left no entry in the run log");

        let _ = rows(&Value::Null);
    })
    .await;
}

//! Configuration an operator changes at run time, and whether it takes effect.
//!
//! The table is easy to get *nearly* right: the rows seed, the admin screen
//! lists them, a value saves — and nothing reads it until the process
//! restarts, which is the one thing `sys_system` exists to avoid. So these
//! assert the resolution itself rather than the storage: a value written
//! through the API must be visible to the next request that resolves it.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

use serde_json::{json, Value};
use serial_test::serial;

use crate::support::{self, bearer, rows};

/// The row for a key, as the dictionary route serves it.
async fn setting(request: &loco_rs::TestServer, key: &str) -> Value {
    let response = request
        .get(&format!("/api/sys/system?config_key={key}&limit=1"))
        .await;
    assert_eq!(response.status_code(), 200, "reading {key}");
    rows(&response.json::<Value>())
        .first()
        .cloned()
        .unwrap_or_else(|| panic!("no sys_system row for {key} — seed_system did not run"))
}

