        let restore = request
            .patch(&format!("/api/sys/system/{id}"))
            .add_header("authorization", bearer(&token))
            .json(&json!({ "config_value": original }))
            .await;
        assert_eq!(restore.status_code(), 200);
    })
    .await;
}

