//! Entity registry — generated from the ERD.
//!
//! The single source of truth the suites iterate over. Every entity in the
//! model appears here with the field metadata `factory` needs to invent a valid
//! payload, so adding an entity to the model adds it to the tests without
//! anyone writing a test.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

/// What a column holds, which is what decides the shape of a generated value.
///
/// These mirror the `sys_reference` vocabulary the backend validates against —
/// binding a `Date` column as text is rejected by Postgres, so the factory has
/// to know the difference.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FieldType {
    String,
    Text,
    Integer,
    Decimal,
    Boolean,
    Date,
    DateTime,
    Json,
    /// A `*_id` column pointing at another `bus_` table.
    Reference,
}

impl FieldType {
    /// Map the model's own type name onto a field type.
    ///
    /// `const` so the registry below can stay a `static` rather than becoming a
    /// lazily-initialised global. A foreign key wins over the declared type:
    /// the model calls it a string, but the API wants a UUID that resolves to a
    /// real parent row.
    pub const fn from_model(model_type: &str, is_foreign_key: bool) -> Self {
        if is_foreign_key {
            return Self::Reference;
        }
        // `match` on &str is not const, so this compares bytes.
        match model_type.as_bytes() {
            b"integer" | b"int" | b"bigint" => Self::Integer,
            b"decimal" | b"float" | b"number" | b"amount" => Self::Decimal,
            b"boolean" | b"bool" => Self::Boolean,
            b"date" => Self::Date,
            b"datetime" | b"timestamp" => Self::DateTime,
            b"json" | b"jsonb" => Self::Json,
            b"text" => Self::Text,
            _ => Self::String,
        }
    }
}

/// Columns naming a person by the role they played rather than by entity.
///
/// Mirrors `PERSON_ROLE_COLUMNS` in the backend's dictionary service and
/// `foreignKeys.personRoleColumns` in the language definition. All three must
/// agree or the tests resolve a parent the API will reject.
const PERSON_ROLE_COLUMNS: &[&str] = &[
    "assigned_to",
    "author_id",
    "lab_manager_id",
    "manager_id",
    "owner_id",
    "pi_id",
    "remediation_owner",
    "remediation_owner_id",
    "user_id",
];

/// Prefixes that name the role a reference plays, not a different entity.
///
/// Mirrors `QUALIFIER_PREFIXES` in the backend's dictionary service and
/// `foreignKeys.qualifierPrefixes` in the language definition.
pub const QUALIFIER_PREFIXES: &[&str] = &["parent_"];

/// The table a foreign key points at, derived from its name.
///
/// There is no stored target — the column name carries the reference — so this
/// repeats the backend's own rule. Returning `None` is the documented fallback
/// for a column that resolves to nothing.
pub const fn ref_table_for(column: &str, is_foreign_key: bool) -> Option<&'static str> {
    if !is_foreign_key {
        return None;
    }
    // Person roles all point at the user table, by name or by `_by` suffix.
    let mut i = 0;
    while i < PERSON_ROLE_COLUMNS.len() {
        if const_str_eq(PERSON_ROLE_COLUMNS[i], column) {
            return Some("bus_user");
        }
        i += 1;
    }
    // A qualified person role resolves the same way the bare one does:
    // `parent_owner_id` names a user, exactly as `owner_id` does. Compared
    // against `prefix + role` rather than by slicing the column, because a
    // `const fn` cannot produce a `&str` subslice.
    let mut p = 0;
    while p < QUALIFIER_PREFIXES.len() {
        let mut i = 0;
        while i < PERSON_ROLE_COLUMNS.len() {
            if eq_prefixed(QUALIFIER_PREFIXES[p], PERSON_ROLE_COLUMNS[i], column) {
                return Some("bus_user");
            }
            i += 1;
        }
        p += 1;
    }
    // A suffix is unaffected by a prefix, so this needs no stripped copy:
    // `parent_reported_by_id` ends in `_by_id` either way.
    if ends_with(column, "_by_id") || ends_with(column, "_by") {
        return Some("bus_user");
    }
    // Anything else is resolved at runtime from the registry, because a `const
    // fn` cannot allocate the `bus_<stem>` string.
    None
}

/// Is `column` exactly `prefix` followed by `suffix`?
///
/// The concatenation a `const fn` cannot build, done as a comparison instead.
const fn eq_prefixed(prefix: &str, suffix: &str, column: &str) -> bool {
    let (prefix, suffix, column) = (prefix.as_bytes(), suffix.as_bytes(), column.as_bytes());
    if column.len() != prefix.len() + suffix.len() {
        return false;
    }
    let mut i = 0;
    while i < prefix.len() {
        if column[i] != prefix[i] {
            return false;
        }
        i += 1;
    }
    let mut j = 0;
    while j < suffix.len() {
        if column[prefix.len() + j] != suffix[j] {
            return false;
        }
        j += 1;
    }
    true
}

const fn const_str_eq(a: &str, b: &str) -> bool {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    if a.len() != b.len() {
        return false;
    }
    let mut i = 0;
    while i < a.len() {
        if a[i] != b[i] {
            return false;
        }
        i += 1;
    }
    true
}

const fn ends_with(haystack: &str, needle: &str) -> bool {
    let (h, n) = (haystack.as_bytes(), needle.as_bytes());
    if n.len() > h.len() {
        return false;
    }
    let offset = h.len() - n.len();
    let mut i = 0;
    while i < n.len() {
        if h[offset + i] != n[i] {
            return false;
        }
        i += 1;
    }
    true
}

#[derive(Clone, Copy, Debug)]
pub struct FieldMeta {
    /// Physical column name — what the API expects in a payload.
    pub name: &'static str,
    pub field_type: FieldType,
    pub required: bool,
    /// The `bus_*` table a `Reference` points at, when it resolves to one.
    pub ref_table: Option<&'static str>,
    /// The longest value the column accepts, when the model states one. A
    /// two-letter ISO code rejects the factory's usual `e2e-code-…` string, and
    /// the failure surfaces as "could not create the record".
    pub max_length: Option<usize>,
}

#[derive(Clone, Copy, Debug)]
pub struct EntityMeta {
    /// ERD entity name, e.g. "Compound".
    pub name: &'static str,
    /// Physical table, e.g. `bus_compound` — the identifier the rules API uses.
    pub table_name: &'static str,
    /// Path segment for `/api/bus/{entity}`.
    pub route: &'static str,
    pub fields: &'static [FieldMeta],
}

/// Columns the request handler owns rather than the caller.
///
/// Mirrors `is_managed_column` in the backend's dictionary service. Sending
/// these is not an error — they are ignored — which is exactly why the suites
/// must not build assertions on them: an override of `id` looks like it was
/// accepted and then reads back as the id the server actually assigned.
pub fn is_managed(column: &str) -> bool {
    matches!(
        column,
        "id" | "version"
            | "created_at"
            | "updated_at"
            | "deleted_at"
            | "created_by"
            | "updated_by"
            | "workflow_status"
            | "workflow_run_id"
            | "doc_status"
            | "doc_status_message"
    )
}

impl EntityMeta {
    /// The fields a caller may actually write.
    ///
    /// Everything else on this type filters through here, so a server-managed
    /// column can never end up in a payload or an assertion.
    pub fn writable_fields(&self) -> impl Iterator<Item = &FieldMeta> {
        self.fields.iter().filter(|f| !is_managed(f.name))
    }

    /// Fields a create payload must carry.
    pub fn required_fields(&self) -> impl Iterator<Item = &FieldMeta> {
        self.writable_fields().filter(|f| f.required)
    }

    /// The first free-text field, for "does it persist what I sent?" assertions.
    pub fn first_text_field(&self) -> Option<&FieldMeta> {
        self.writable_fields()
            .find(|f| matches!(f.field_type, FieldType::String | FieldType::Text))
    }

    /// The first numeric field, for the rules suites' range checks.
    pub fn first_numeric_field(&self) -> Option<&FieldMeta> {
        self.writable_fields()
            .find(|f| matches!(f.field_type, FieldType::Integer | FieldType::Decimal))
    }

    /// Optional fields whose column is *not* text.
    ///
    /// This is the family an explicit JSON `null` used to break. Every NULL was
    /// bound as an untyped text parameter, and Postgres will not store text in
    /// a `numeric`, `date`, `timestamptz`, `boolean`, `uuid` or `jsonb` column
    /// — it raised 42804 and the API answered `400 A value has the wrong type
    /// or format`, so an optional field could never be cleared.
    pub fn optional_typed_fields(&self) -> impl Iterator<Item = &FieldMeta> {
        self.writable_fields().filter(|f| {
            !f.required
                && matches!(
                    f.field_type,
                    FieldType::Integer
                        | FieldType::Decimal
                        | FieldType::Boolean
                        | FieldType::Date
                        | FieldType::DateTime
                        | FieldType::Json
                        | FieldType::Reference
                )
        })
    }

    /// Foreign keys that have to be satisfied before this entity can exist.
    pub fn foreign_keys(&self) -> impl Iterator<Item = &FieldMeta> {
        self.writable_fields().filter(|f| f.field_type == FieldType::Reference)
    }
}

/// Look an entity up by its ERD name. Panics on a miss: the name comes from
/// generated code, so a miss is a generator bug, not a runtime condition.
pub fn entity(name: &str) -> &'static EntityMeta {
    ENTITIES
        .iter()
        .find(|e| e.name == name)
        .unwrap_or_else(|| panic!("unknown entity '{name}' — the registry is generated, so this is a generator bug"))
}

/// Find the entity behind a `bus_*` table name.
pub fn entity_by_table(table: &str) -> Option<&'static EntityMeta> {
    ENTITIES.iter().find(|e| e.table_name == table)
}

/// The parent entity a foreign key refers to.
///
/// `FieldMeta::ref_table` covers the person-role columns a `const fn` can
/// decide; everything else is `bus_<stem>` and is matched against the registry
/// here, where allocation is allowed.
pub fn parent_of(field: &FieldMeta) -> Option<&'static EntityMeta> {
    if let Some(table) = field.ref_table {
        return entity_by_table(table);
    }
    // A qualifier names the role the reference plays, not another entity, so it
    // is stripped before the `bus_<stem>` rule — a Sample's `parent_sample_id`
    // is a Sample. Mirrors `QUALIFIER_PREFIXES` in the backend's dictionary
    // service and `foreignKeys.qualifierPrefixes` in the language definition.
    let name = QUALIFIER_PREFIXES
        .iter()
        .find_map(|prefix| field.name.strip_prefix(prefix))
        .unwrap_or(field.name);
    let stem = name.strip_suffix("_id")?;
    entity_by_table(&format!("bus_{stem}"))
}

pub static ENTITIES: &[EntityMeta] = &[
{{#each entities}}
    EntityMeta {
        name: "{{name}}",
        table_name: "{{tableName}}",
        route: "{{tableName}}",
        fields: &[
{{#each attributes}}
            FieldMeta {
                name: "{{columnName}}",
                field_type: FieldType::from_model("{{type}}", {{#if isForeignKey}}true{{else}}false{{/if}}),
                required: {{#if required}}true{{else}}false{{/if}},
{{#if referencesTable}}
                ref_table: Some("{{referencesTable}}"),
{{else}}
                ref_table: ref_table_for("{{columnName}}", {{#if isForeignKey}}true{{else}}false{{/if}}),
{{/if}}
                max_length: {{#if maxLength}}Some({{maxLength}}){{else}}None{{/if}},
            },
{{/each}}
        ],
    },
{{/each}}
];

//! Payload construction.
//!
//! Builds a create payload the API will accept for any entity in the registry,
//! including resolving the parent rows its foreign keys need. This is what lets
//! one generic CRUD suite cover every entity in the model.
//!
//! Values are readable and ordered within a run — a monotonic counter, not
//! randomness — and carry a per-run token so they never collide with the rows
//! an earlier run left behind.
//!
//! Generated: {{now}}
//! Project: {{project.name}}

#![allow(dead_code)]

use serde_json::{json, Map, Value};
use std::collections::HashSet;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::OnceLock;

use loco_rs::TestServer;

use super::entities::{parent_of, EntityMeta, FieldMeta, FieldType};
use super::bearer;

static COUNTER: AtomicU64 = AtomicU64::new(0);
static RUN: OnceLock<(String, u64)> = OnceLock::new();

/// A value nothing else in the run will produce.
fn unique() -> u64 {
    COUNTER.fetch_add(1, Ordering::Relaxed)
}

/// A token and numeric offset unique to this test *run*.
///
/// The counter alone is not enough. It restarts at zero in every process while
/// the test database keeps the rows from the run before, so the second run of a
/// suite reproduces the first run's values exactly and every uniquely
/// constrained column answers 409 — which surfaces as "could not create the
/// record", nowhere near the factory that caused it. The run token is what
/// makes a suite re-runnable against a database it has already written to.
fn run() -> &'static (String, u64) {
    RUN.get_or_init(|| {
        let raw = uuid::Uuid::new_v4();
        let token = raw.simple().to_string()[..8].to_string();
        // Kept under eight digits so it still fits a `numeric(10,2)`, which is
        // what a model that says "decimal" usually becomes. Uniqueness within a
        // run comes from the counter; the offset only has to move each run into
        // a different part of the range.
        let offset = (raw.as_u128() as u64) % 100_000 * 100;
        (token, offset)
    })
}

/// A value for one field, shaped by its type.
///
/// Types are not cosmetic here: the backend binds `Date` and `DateTime`
/// columns as real temporal values, and Postgres rejects text for those — so a
/// factory that sent strings everywhere would fail on any entity with a date.
pub fn value_for(field: &FieldMeta) -> Value {
    let (token, offset) = run();
    let n = unique() + offset;
    match field.field_type {
        FieldType::Integer => json!(i64::try_from(n).unwrap_or(1) + 1),
        FieldType::Decimal => json!(n as f64 + 0.5),
        FieldType::Boolean => json!(n.is_multiple_of(2)),
        FieldType::Date => json!("2026-06-01"),
        FieldType::DateTime => json!("2026-06-01T09:30:00Z"),
        FieldType::Json => json!({ "generated": n }),
        // A reference with no resolved parent still has to be a UUID or the
        // API rejects the shape before it ever checks the row exists.
        FieldType::Reference => json!("00000000-0000-4000-8000-000000000000"),
        FieldType::String | FieldType::Text => json!(fit(field, format!("e2e-{}-{token}-{n}", field.name), n)),
    }
}

/// A fresh value for `field` that carries `label` when the column is long
/// enough to hold it, for the tests that write a marker and read it back.
pub fn marked(field: &FieldMeta, label: &str) -> String {
    let (_, offset) = run();
    let n = unique() + offset;
    fit(field, format!("{label}-{}", uuid::Uuid::new_v4()), n)
}

/// A string no other row holds, no longer than the column allows.
///
/// A column with a short limit (a two-letter country code) cannot hold the
/// readable `e2e-<field>-<run>-<n>` form, so it gets a symbol followed by the
/// counter in base 36 — which keeps it clear of the codes the reference data
/// seeds, all of which are letters or digits. The low digits are the ones that vary, so cutting from
/// the left keeps every value in a run distinct for as long as the limit
/// allows.
fn fit(field: &FieldMeta, readable: String, n: u64) -> String {
    match field.max_length {
        Some(limit) if readable.len() > limit => {
            // The first character is a symbol, so the value cannot equal a seeded
            // ISO code: those are letters (language, country, currency) or
            // digits (a country's numeric code), never punctuation.
            const SYMBOLS: &[u8] = b"!#$%&*+=?@^~";
            let tail = limit.saturating_sub(1);
            let mut rest = n;
            let mut low = Vec::with_capacity(tail);
            for _ in 0..tail {
                low.push(char::from_digit((rest % 36) as u32, 36).unwrap_or('0'));
                rest /= 36;
            }
            low.reverse();
            let lead = SYMBOLS[(rest % SYMBOLS.len() as u64) as usize] as char;
            std::iter::once(lead).chain(low).collect()
        }
        _ => readable,
    }
}

/// A create payload with every required field populated and no foreign keys.
///
/// Useful on its own only for entities with no mandatory parents; everything
/// else wants [`create_with_parents`].
pub fn build_record(entity: &EntityMeta) -> Map<String, Value> {
    let mut payload = Map::new();
    for field in entity.writable_fields() {
        if field.field_type == FieldType::Reference {
            continue;
        }
        payload.insert(field.name.to_string(), value_for(field));
    }
    payload
}

/// A payload that omits one required field, for the "does it reject this?" case.
///
/// Returns `None` when the entity has no required scalar to withhold — there is
/// nothing to assert, and inventing a case would test the factory rather than
/// the API.
pub fn build_invalid_record(entity: &EntityMeta) -> Option<Map<String, Value>> {
    let omitted = entity
        .required_fields()
        .find(|f| f.field_type != FieldType::Reference)?;

    let mut payload = build_record(entity);
    payload.remove(omitted.name);
    Some(payload)
}

/// Create a record, first creating whatever parents its foreign keys need.
///
/// Recursion terminates on cycles — an entity whose parent chain leads back to
/// itself — detected by the set of routes already on the stack. A plain depth
/// limit would look equivalent and is not: the chain a model needs is as long
/// as its deepest foreign-key path, and a fixed cap truncates legitimate ones
/// on an empty database, leaving a mandatory FK unset and failing the create
/// with a validation error about a record that was never malformed.
pub async fn create_with_parents(
    request: &TestServer,
    token: &str,
    entity: &EntityMeta,
    overrides: &[(&str, Value)],
) -> Option<Value> {
    let mut in_flight: HashSet<&'static str> = HashSet::new();
    create_tracked(request, token, entity, overrides, &mut in_flight).await
}

async fn create_tracked(
    request: &TestServer,
    token: &str,
    entity: &EntityMeta,
    overrides: &[(&str, Value)],
    in_flight: &mut HashSet<&'static str>,
) -> Option<Value> {
    if !in_flight.insert(entity.route) {
        return None;
    }
    let created = create_inner(request, token, entity, overrides, in_flight).await;
    in_flight.remove(entity.route);
    created
}

async fn create_inner(
    request: &TestServer,
    token: &str,
    entity: &EntityMeta,
    overrides: &[(&str, Value)],
    in_flight: &mut HashSet<&'static str>,
) -> Option<Value> {
    let mut payload = build_record(entity);

    for fk in entity.foreign_keys() {
        let Some(parent) = parent_of(fk) else { continue };
        // A narrowed lookup (a state within a country, a city within a state)
        // only accepts a row the record's other choices allow, so the parent is
        // taken from the lookup the form itself would use, given what has
        // already been chosen. A column that is not narrowed answers with the
        // target's rows unfiltered, which is what `any_record_id` returns too.
        match narrowed_choice(request, token, entity, fk, &payload).await {
            Choice::Row(id) => {
                payload.insert(fk.name.to_string(), json!(id));
                continue;
            }
            // Optional, and nothing in the table fits what is already chosen:
            // leaving it unset is a valid record, a mismatched one is not.
            Choice::NoneFits if !fk.required => continue,
            Choice::NoneFits | Choice::Unavailable => {}
        }
        if let Some(id) = any_record_id(request, token, parent, in_flight).await {
            payload.insert(fk.name.to_string(), json!(id));
        }
    }

    for (key, value) in overrides {
        payload.insert((*key).to_string(), value.clone());
    }

    let response = request
        .post(&format!("/api/bus/{}", entity.route))
        .add_header("authorization", bearer(token))
        .json(&Value::Object(payload.clone()))
        .await;

    if response.status_code() == 201 {
        return Some(response.json::<Value>());
    }

    // Some models reject an optional combination the factory invented. Retry
    // with only what the entity actually requires before giving up — the same
    // fallback the TypeScript harness used.
    let mut minimal: Map<String, Value> = payload
        .iter()
        .filter(|(key, _)| {
            entity
                .writable_fields()
                .any(|f| f.name == key.as_str() && (f.required || f.field_type == FieldType::Reference))
        })
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    for (key, value) in overrides {
        minimal.insert((*key).to_string(), value.clone());
    }

    let retry = request
        .post(&format!("/api/bus/{}", entity.route))
        .add_header("authorization", bearer(token))
        .json(&Value::Object(minimal))
        .await;

    (retry.status_code() == 201).then(|| retry.json::<Value>())
}

enum Choice {
    Row(String),
    NoneFits,
    Unavailable,
}

/// The first row `fk`'s lookup offers, given the values already in `payload`.
async fn narrowed_choice(
    request: &TestServer,
    token: &str,
    entity: &EntityMeta,
    fk: &FieldMeta,
    payload: &Map<String, Value>,
) -> Choice {
    let controls: Vec<String> = payload
        .iter()
        .filter(|(key, _)| key.ends_with("_id"))
        .filter_map(|(key, value)| value.as_str().map(|id| format!("&{key}={id}")))
        .collect();
    let response = request
        .get(&format!(
            "/api/bus/{}/lookup/{}?limit=1{}",
            entity.route,
            fk.name,
            controls.concat()
        ))
        .add_header("authorization", bearer(token))
        .await;
    if response.status_code() != 200 {
        return Choice::Unavailable;
    }
    match super::rows(&response.json::<Value>())
        .first()
        .and_then(|row| row.get("id"))
        .and_then(Value::as_str)
    {
        Some(id) => Choice::Row(id.to_string()),
        None => Choice::NoneFits,
    }
}

/// An existing row's id for `entity`, creating one if the table is empty.
async fn any_record_id(
    request: &TestServer,
    token: &str,
    entity: &EntityMeta,
    in_flight: &mut HashSet<&'static str>,
) -> Option<String> {
    let listed = request
        .get(&format!("/api/bus/{}?limit=1", entity.route))
        .add_header("authorization", bearer(token))
        .await;

    if listed.status_code() == 200 {
        if let Some(id) = super::rows(&listed.json::<Value>())
            .first()
            .and_then(|row| row.get("id"))
            .and_then(Value::as_str)
        {
            return Some(id.to_string());
        }
    }

    let created = Box::pin(create_tracked(request, token, entity, &[], in_flight)).await?;
    created
        .get("id")
        .and_then(Value::as_str)
        .map(ToString::to_string)
}

