// bpmn-js types (runtime import)
type BpmnModelerInstance = any;

export interface BpmnCanvasHandle {
  getXml: () => Promise<string>;
  importXml: (xml: string) => Promise<void>;
}

interface SelectedTask {
  id: string;
  name: string;
  nodeType: string;
  properties: Record<string, string>;
