import { AlertTriangle, CheckCircle, Clock, FileEdit, XCircle } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { Text } from "@/components/ui/layout";

interface DocStatusBadgeProps {
  status?: string | null;
  message?: string | null;
  className?: string;
}

/**
 * The business-rules verdict on a record (`doc_status`), not where its
 * transaction stands. These labels used to say "Final" for "every rule passed",
 * which beside the lifecycle bar read as a closed transaction: a record in
 * Prospecting carried a Final badge. Final belongs to the lifecycle alone
 * (`transactionStatus.isFinal`); this badge says what the rules decided.
 */
const STATUS_CONFIG: Record<
  string,
  {
    label: string;
    variant: "default" | "secondary" | "destructive" | "outline";
    className: string;
    icon: React.ComponentType<{ className?: string }>;
  }
> = {
  draft: {
    label: "Rules not met",
    variant: "outline",
    className: "border-amber-300 text-amber-700 bg-amber-50",
    icon: FileEdit,
  },
  pending_rules: {
    label: "Checking rules",
    variant: "outline",
    className: "border-blue-300 text-blue-700 bg-blue-50",
    icon: Clock,
  },
  final: {
    label: "Rules passed",
    variant: "outline",
    className: "border-green-300 text-green-700 bg-green-50",
    icon: CheckCircle,
  },
  approved: {
    label: "Rules passed",
    variant: "outline",
    className: "border-green-300 text-green-700 bg-green-50",
    icon: CheckCircle,
  },
  rejected: {
    label: "Rules not met",
    variant: "outline",
    className: "border-amber-300 text-amber-700 bg-amber-50",
    icon: FileEdit,
  },
  none: {
    label: "No Rules",
    variant: "secondary",
    className: "text-gray-500",
    icon: CheckCircle,
  },
};

export function DocStatusBadge({ status, message, className = "" }: DocStatusBadgeProps) {
  if (!status || status === "none") return null;

  const config = STATUS_CONFIG[status] || STATUS_CONFIG.draft;
  const Icon = config.icon;

  let parsedViolations: Array<{ message: string; ruleName?: string }> = [];
  if (message && (status === "rejected" || status === "draft")) {
    try {
      const parsed = JSON.parse(message);
      parsedViolations = (parsed.violations || []).map((v: any) => ({
        message: v.message,
        ruleName: v.ruleName,
      }));
    } catch {
      parsedViolations = [{ message }];
    }
  }

  const badge = (
    <Badge
      variant={config.variant}
      className={`${config.className} ${className} inline-flex items-center gap-1 text-xs`}
    >
      <Icon className="h-3 w-3" />
      {config.label}
    </Badge>
  );

  if (parsedViolations.length > 0) {
    return (
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger>{badge}</TooltipTrigger>
          <TooltipContent side="bottom" className="max-w-sm">
            <div className="space-y-1">
              <Text weight="semibold" size="xs" block>Rule Violations:</Text>
              {parsedViolations.map((v, i) => (
                <div key={`${v.ruleName ?? "rule"}-${v.message ?? i}`} className="flex items-start gap-1 text-xs">
                  <AlertTriangle className="h-3 w-3 mt-0.5 text-red-500 flex-shrink-0" />
                  <span>
                    {v.ruleName && <strong>{v.ruleName}: </strong>}
                    {v.message}
                  </span>
                </div>
              ))}
            </div>
          </TooltipContent>
        </Tooltip>
      </TooltipProvider>
    );
  }

  return badge;
}

/**
 * Field Group Manager
 *
 * Component for managing field groups - add, edit, delete, and reorder groups.
 * Shows groups with their column layouts and field counts.
 */

"use client";

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Check, GripVertical, LayoutGrid, Loader2, Pencil, Plus, Trash2, X } from "lucide-react";
import { useState } from "react";
import {
  type FieldGroup,
  useCreateFieldGroup,
  useDeleteFieldGroup,
  useFieldGroups,
  useUpdateFieldGroup,
} from "@/hooks/use-entities";
import { cn } from "@/lib/utils";
import { Box, HStack, Heading, Text, VStack } from "@/components/ui/layout";

interface FieldGroupManagerProps {
  entityName: string;
}

interface ColumnLayoutOption {
  value: number;
  label: string;
  icon: string;
}

const COLUMN_LAYOUTS: ColumnLayoutOption[] = [
  { value: 1, label: "1 Column", icon: "▯" },
  { value: 2, label: "2 Columns", icon: "▯▯" },
  { value: 3, label: "3 Columns", icon: "▯▯▯" },
  { value: 4, label: "4 Columns", icon: "▯▯▯▯" },
];

export function FieldGroupManager({ entityName }: FieldGroupManagerProps) {
  const { data: groups, isLoading } = useFieldGroups(entityName);
  const [editingGroup, setEditingGroup] = useState<string | null>(null);
  const [newGroupMode, setNewGroupMode] = useState(false);

  // Form state for new/edit group
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    columns: 1,
    layout_type: "single",
  });

  // Mutations
  const createMutation = useCreateFieldGroup(entityName);
  const updateMutation = useUpdateFieldGroup(entityName);
  const deleteMutation = useDeleteFieldGroup(entityName);

  // Reset form
  const resetForm = () => {
    setFormData({ name: "", description: "", columns: 1, layout_type: "single" });
    setEditingGroup(null);
    setNewGroupMode(false);
  };

  // Start editing a group
  const startEdit = (group: FieldGroup) => {
    setFormData({
      name: group.name,
      description: group.description || "",
      columns: group.columns,
      layout_type: group.layout_type,
    });
    setEditingGroup(group.sys_field_group_id);
    setNewGroupMode(false);
  };

  // Get layout type from columns
  const getLayoutType = (columns: number): string => {
    switch (columns) {
      case 1:
        return "single";
      case 2:
        return "two-column";
      case 3:
        return "three-column";
      case 4:
        return "four-column";
      default:
        return "single";
    }
  };

  if (isLoading) {
    return (
      <HStack align="center" justify="center" padding={8}>
        <div className="text-sm text-muted-foreground">Loading field groups...</div>
      </HStack>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <HStack align="center" justify="between">
        <div>
          <Heading level={3}>Field Groups</Heading>
          <Text size="sm" color="secondary" block>
            Organize fields into sections with multi-column layouts
          </Text>
        </div>
        <button type="button"
          onClick={() => {
            resetForm();
            setNewGroupMode(true);
          }}
          className="flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground rounded-md hover:bg-primary/90 transition-colors"
        >
          <Plus size={16} />
          Add Group
        </button>
      </HStack>

      {/* New Group Form */}
      {newGroupMode && (
        <Box radius="lg" padding={6} bg="surface" border="default">
          <Heading level={4} className="text-md mb-4">Create New Field Group</Heading>
          <GroupForm
            formData={formData}
            setFormData={setFormData}
            onCancel={resetForm}
            onSave={() => {
              createMutation.mutate(formData as any, {
                onSuccess: () => {
                  resetForm();
                },
              });
            }}
            isSaving={createMutation.isPending}
          />
        </Box>
      )}

      {/* Groups List */}
      <div className="space-y-4">
        {!groups || groups.length === 0 ? (
          <Box padding={8} radius="lg" border="default" className="text-center border-dashed">
            <Text color="secondary" block>No field groups defined yet.</Text>
            <Text size="sm" color="secondary" block className="mt-2">
              Click "Add Group" to create your first group.
            </Text>
          </Box>
        ) : (
          groups.map((group) => (
            <GroupCard
              key={group.sys_field_group_id}
              group={group}
              isEditing={editingGroup === group.sys_field_group_id}
              formData={formData}
              setFormData={setFormData}
              onEdit={() => startEdit(group)}
              onCancel={resetForm}
              onSave={() => {
                updateMutation.mutate(
                  { id: group.sys_field_group_id, data: formData as Partial<FieldGroup> },
                  {
                    onSuccess: () => {
                      resetForm();
                    },
                  }
                );
              }}
              onDelete={() => {
                if (
                  confirm(
                    `Are you sure you want to delete "${group.name}"? Fields in this group will become ungrouped.`
                  )
                ) {
                  deleteMutation.mutate(group.sys_field_group_id);
                }
              }}
              isSaving={updateMutation.isPending}
              isDeleting={deleteMutation.isPending}
            />
          ))
        )}
      </div>
    </div>
  );
}

interface GroupFormProps {
