      </div>

      {/* Column Layout */}
      <div>
        <p className="block text-sm font-medium mb-2">Column Layout</p>
        <HStack gap={3}>
          {COLUMN_LAYOUTS.map((layout) => (
            <button
              key={layout.value}
              type="button"
              onClick={() =>
                setFormData({
                  ...formData,
                  columns: layout.value,
