/* ─────────────────────────────────────────────────────────── main component */

interface UnifiedFieldLayoutProps {
  entityName: string;
  onEntityChange?: (name: string) => void;
}

export function UnifiedFieldLayout({ entityName }: UnifiedFieldLayoutProps) {
  const queryClient = useQueryClient();
  const [mode, setMode] = useState<"form" | "grid">("form");
  const [groups, setGroups] = useState<WorkingGroup[]>([]);
  const [gridList, setGridList] = useState<WorkingField[]>([]);
  const [isDirty, setIsDirty] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const { data: fieldGroupsData, isLoading: groupsLoading } = useFieldGroups(entityName);
  const { data: formFields, isLoading: formLoading } = useAllFormFields(entityName);
  const { data: gridFields, isLoading: gridLoading } = useAllGridFields(entityName);

  const isLoading = groupsLoading || (mode === "form" ? formLoading : gridLoading);

  // Build form working state (grouped)
  useEffect(() => {
    if (mode !== "form" || !formFields || !fieldGroupsData) return;
    const g = buildGroupedState(formFields, fieldGroupsData as any[]);
    setGroups(g);
    setIsDirty(false);
  }, [formFields, fieldGroupsData, mode]);

  // Build grid working state (flat list, ordered by seq_no_grid)
  useEffect(() => {
    if (mode !== "grid" || !gridFields) return;
    const sorted = [...(gridFields as any[])].sort(
      (a, b) =>
        ((a as any).seq_no_grid ?? a.seq_no ?? 999) - ((b as any).seq_no_grid ?? b.seq_no ?? 999)
    );
    setGridList(
      sorted.map((f: any) => ({
        ...f,
        seq_no: f.seq_no_grid ?? f.seq_no ?? 0,
        is_displayed: f.is_displayed_grid ?? f.is_displayed ?? false,
        originalGroupId: null,
        originalSeqNo: f.seq_no_grid ?? f.seq_no ?? 0,
        dirty: false,
      }))
    );
    setIsDirty(false);
  }, [gridFields, mode]);

  /* ── drag end */
  const onDragEnd = useCallback((result: DropResult) => {
    if (!result.destination) return;
    const { source, destination, draggableId } = result;
    if (source.droppableId === destination.droppableId && source.index === destination.index)
      return;

    setGroups((prev) => {
      const next = prev.map((g) => ({ ...g, fields: [...g.fields] }));
      const srcGroup = next.find((g) => g.id === source.droppableId);
      const dstGroup = next.find((g) => g.id === destination.droppableId);
      // A drop onto a group that is no longer in state leaves the list as it
      // was, rather than throwing inside a state updater.
      if (!srcGroup || !dstGroup) return prev;

      const [movedField] = srcGroup.fields.splice(source.index, 1);

      const newGroupId = destination.droppableId === "unassigned" ? null : destination.droppableId;
      const updatedField: WorkingField = {
        ...movedField,
        field_group_id: newGroupId ?? undefined,
        dirty:
          newGroupId !== movedField.originalGroupId ||
          source.droppableId !== destination.droppableId,
      };

      dstGroup.fields.splice(destination.index, 0, updatedField);

      // Recalculate seq_no within destination group
      dstGroup.fields = dstGroup.fields.map((f, i) => ({
        ...f,
        seq_no: (i + 1) * 10,
        dirty: f.dirty || f.seq_no !== (i + 1) * 10,
      }));

      return next;
    });
    setIsDirty(true);
  }, []);

  /* ── toggle visibility */
  const handleToggleVisibility = useCallback((fieldId: string, groupId: string) => {
    setGroups((prev) =>
      prev.map((g) => {
        if (g.id !== groupId) return g;
        return {
          ...g,
          fields: g.fields.map((f) =>
            f.sys_field_id === fieldId ? { ...f, is_displayed: !f.is_displayed, dirty: true } : f
          ),
        };
      })
    );
    setIsDirty(true);
  }, []);

  /* ── group editing */
  const handleEditToggle = useCallback((id: string) => {
    setGroups((prev) =>
      prev.map((g) =>
        g.id === id ? { ...g, isEditing: !g.isEditing } : { ...g, isEditing: false }
      )
    );
  }, []);

  const handleEditSave = useCallback(
    (id: string, name: string, columns: number, description: string) => {
      setGroups((prev) =>
        prev.map((g) =>
          g.id === id
            ? ({ ...g, name, columns, description, isEditing: false, dirty: true } as any)
            : g
        )
      );
      setIsDirty(true);
    },
    []
  );

  const handleEditCancel = useCallback((id: string) => {
    setGroups((prev) => prev.map((g) => (g.id === id ? { ...g, isEditing: false } : g)));
  }, []);

  const handleDeleteGroup = useCallback((id: string) => {
    setGroups((prev) => {
      const groupToDelete = prev.find((g) => g.id === id);
      if (!groupToDelete) return prev;
      // Move fields from deleted group to unassigned
      const movedFields = groupToDelete.fields.map((f) => ({
        ...f,
        field_group_id: undefined,
        dirty: true,
      }));
      return prev
        .filter((g) => g.id !== id)
        .map((g) => (g.id === "unassigned" ? { ...g, fields: [...g.fields, ...movedFields] } : g));
    });
    setIsDirty(true);
  }, []);

  /* ── toggle summary */
  const handleToggleSummary = useCallback((id: string) => {
    setGroups((prev) =>
      prev.map((g) =>
        g.id === id
          ? ({
              ...g,
              layout_type: g.layout_type === "summary" ? "single" : "summary",
              dirty: true,
            } as any)
          : g
      )
    );
    setIsDirty(true);
  }, []);

  /* ── add group */
  const handleAddGroup = useCallback(() => {
    const tempId = `new-${Date.now()}`;
    const newGroup: WorkingGroup = {
      id: tempId,
      name: "New Group",
      columns: 2,
      description: "",
      layout_type: "single",
      seq_no: (groups.filter((g) => g.id !== "unassigned").length + 1) * 10,
      isNew: true,
      isEditing: true,
      isDeleted: false,
      fields: [],
    };
    // Insert before unassigned
    setGroups((prev) => {
      const idx = prev.findIndex((g) => g.id === "unassigned");
      const next = [...prev];
      next.splice(idx, 0, newGroup);
      return next;
    });
    setIsDirty(true);
  }, [groups]);

  /* ── grid mode: drag-to-reorder flat list */
  const onGridDragEnd = useCallback((result: DropResult) => {
    if (!result.destination) return;
    const { source, destination } = result;
    if (source.index === destination.index) return;
    setGridList((prev) => {
      const next = [...prev];
      const [moved] = next.splice(source.index, 1);
      next.splice(destination.index, 0, moved);
      return next.map((f, i) => ({
        ...f,
        seq_no: (i + 1) * 10,
        dirty: f.dirty || f.originalSeqNo !== (i + 1) * 10,
      }));
    });
    setIsDirty(true);
  }, []);

  /* ── grid mode: visibility toggle */
  const handleGridToggleVisibility = useCallback((fieldId: string) => {
    setGridList((prev) =>
      prev.map((f) =>
        f.sys_field_id === fieldId ? { ...f, is_displayed: !f.is_displayed, dirty: true } : f
      )
    );
    setIsDirty(true);
  }, []);

  /* ── save all */
  const handleSaveAll = useCallback(async () => {
    setIsSaving(true);
    try {
      // Grid mode: save seq_no_grid and is_displayed_grid only
      if (mode === "grid") {
        const dirty = gridList.filter((f) => f.dirty);
        await Promise.all(
          dirty.map((f) =>
            apiClient.put(`/sys/fields/${f.sys_field_id}`, {
              seq_no_grid: f.seq_no,
              is_displayed_grid: f.is_displayed,
            })
          )
        );
        await queryClient.invalidateQueries({ queryKey: ["fields-all", entityName, "grid"] });
        toast.success("Grid layout saved successfully");
        setIsDirty(false);
        return;
      }

      // Form mode: save group assignments, seq_no, and is_displayed
      const fieldUpdates: Array<{
        id: string;
        sys_field_group_id: string | null;
        seq_no: number;
        is_displayed: boolean;
      }> = [];
      const groupCreates: WorkingGroup[] = [];
      const groupUpdates: WorkingGroup[] = [];

      for (const g of groups) {
        if (g.id === "unassigned") continue;
        if (g.isNew) {
          groupCreates.push(g);
        } else if ((g as any).dirty) {
          groupUpdates.push(g);
        }
        for (const f of g.fields) {
          if (f.dirty) {
            fieldUpdates.push({
              id: f.sys_field_id,
              sys_field_group_id: g.id === "unassigned" ? null : g.id,
              seq_no: f.seq_no,
              is_displayed: f.is_displayed,
            });
          }
        }
      }

      const unassigned = groups.find((g) => g.id === "unassigned");
      if (unassigned) {
        for (const f of unassigned.fields) {
          if (f.dirty) {
            fieldUpdates.push({
              id: f.sys_field_id,
              sys_field_group_id: null,
              seq_no: f.seq_no,
              is_displayed: f.is_displayed,
            });
          }
        }
      }

      const tempToRealId = new Map<string, string>();
      for (const g of groupCreates) {
        const created = await apiClient.post(`/sys/field-groups?entity=${entityName}`, {
          name: g.name,
          columns: g.columns,
          description: g.description,
          layout_type: g.layout_type ?? "single",
          seq_no: g.seq_no,
        });
        const realId = (created as any)?.sys_field_group_id;
        if (realId) tempToRealId.set(g.id, realId);
      }

      // Remap temp IDs to real UUIDs returned from the server
      for (const update of fieldUpdates) {
        const realId = update.sys_field_group_id
          ? tempToRealId.get(update.sys_field_group_id)
          : undefined;
        if (realId) {
          update.sys_field_group_id = realId;
        }
      }

      for (const g of groupUpdates) {
        await apiClient.put(`/sys/field-groups/${g.id}?entity=${entityName}`, {
          name: g.name,
          columns: g.columns,
          description: g.description,
          layout_type: g.layout_type ?? "single",
          seq_no: g.seq_no,
        });
      }

      await Promise.all(
        fieldUpdates.map(({ id, ...data }) => apiClient.put(`/sys/fields/${id}`, data))
      );

      await queryClient.invalidateQueries({ queryKey: ["field-groups", entityName] });
      await queryClient.invalidateQueries({ queryKey: ["fields-all", entityName] });

      toast.success("Layout saved successfully");
      setIsDirty(false);
    } catch (err: any) {
      toast.error(`Save failed: ${err.message ?? "Unknown error"}`);
    } finally {
      setIsSaving(false);
    }
  }, [mode, groups, gridList, entityName, queryClient]);

  /* ── reset */
  const handleReset = useCallback(() => {
    if (mode === "grid") {
      if (!gridFields) return;
      const sorted = [...(gridFields as any[])].sort(
        (a, b) =>
          ((a as any).seq_no_grid ?? a.seq_no ?? 999) - ((b as any).seq_no_grid ?? b.seq_no ?? 999)
      );
      setGridList(
        sorted.map((f: any) => ({
          ...f,
          seq_no: f.seq_no_grid ?? f.seq_no ?? 0,
          is_displayed: f.is_displayed_grid ?? f.is_displayed ?? false,
          originalGroupId: null,
          originalSeqNo: f.seq_no_grid ?? f.seq_no ?? 0,
          dirty: false,
        }))
      );
    } else {
      if (!formFields || !fieldGroupsData) return;
      setGroups(buildGroupedState(formFields, fieldGroupsData as any[]));
    }
    setIsDirty(false);
  }, [mode, gridFields, formFields, fieldGroupsData]);

  /* ── computed stats */
  const dirtyFieldCount = useMemo(
    () =>
      mode === "grid"
        ? gridList.filter((f) => f.dirty).length
        : groups.flatMap((g) => g.fields).filter((f) => f.dirty).length,
    [mode, groups, gridList]
  );

  const visibleGroups = groups.filter((g) => g.id !== "unassigned");
  const unassignedGroup = groups.find((g) => g.id === "unassigned");

  if (isLoading) {
    return (
      <div className="space-y-4 p-6">
        <Skeleton className="h-8 w-64" />
        <div className="grid grid-cols-3 gap-4">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-48" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-5">
      {/* Toolbar */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-2">
          <div className="flex rounded-lg border border-border overflow-hidden">
            <button type="button"
              onClick={() => setMode("form")}
              className={cn(
                "px-4 py-1.5 text-sm font-medium transition-colors",
                mode === "form"
                  ? "bg-primary text-primary-foreground"
                  : "bg-background text-muted-foreground hover:bg-muted"
              )}
            >
              Form Fields
            </button>
            <button type="button"
              onClick={() => setMode("grid")}
              className={cn(
                "px-4 py-1.5 text-sm font-medium transition-colors border-l border-border",
                mode === "grid"
                  ? "bg-primary text-primary-foreground"
                  : "bg-background text-muted-foreground hover:bg-muted"
              )}
            >
              Grid Fields
            </button>
          </div>
          {isDirty && (
            <Badge variant="outline" className="text-amber-600 border-amber-300 bg-amber-50">
              {dirtyFieldCount} unsaved change{dirtyFieldCount !== 1 ? "s" : ""}
            </Badge>
          )}
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={handleReset}
            disabled={!isDirty}
            className="h-8 gap-1.5"
          >
            <RotateCcw size={14} />
            Reset
          </Button>
          <Button
            size="sm"
            onClick={handleSaveAll}
            disabled={!isDirty || isSaving}
            className="h-8 gap-1.5 bg-emerald-600 hover:bg-emerald-700 text-white"
          >
            <Save size={14} />
            {isSaving ? "Saving…" : "Save Layout"}
          </Button>
        </div>
      </div>

      {mode === "grid" ? (
        /* ── Grid mode: flat reorderable list, no groups ── */
        <DragDropContext onDragEnd={onGridDragEnd}>
          <Droppable droppableId="grid-fields">
            {(provided) => (
              <div
                ref={provided.innerRef}
                {...provided.droppableProps}
                className="flex flex-col gap-1.5 max-w-xl"
              >
                {gridList.length === 0 && (
                  <p className="text-sm text-muted-foreground py-4 text-center">No fields found.</p>
                )}
                {gridList.map((field, index) => (
                  <Draggable
                    key={field.sys_field_id}
                    draggableId={field.sys_field_id}
                    index={index}
                  >
                    {(prov, snap) => (
                      <div
                        ref={prov.innerRef}
                        {...(prov.draggableProps as any)}
                        className={cn(
                          "flex items-center gap-2 px-3 py-2.5 rounded-md border text-sm transition-all",
                          snap.isDragging
                            ? "bg-primary/5 border-primary/40 shadow-lg"
                            : field.dirty
                              ? "bg-amber-50 border-amber-200"
                              : "bg-white border-border hover:border-primary/30",
                          !field.is_displayed && "opacity-50"
                        )}
                      >
                        <span
                          {...prov.dragHandleProps}
                          className="text-muted-foreground/40 hover:text-muted-foreground cursor-grab active:cursor-grabbing flex-shrink-0"
                        >
                          <GripVertical size={16} />
                        </span>
                        <span className="w-6 text-xs text-muted-foreground font-mono text-center flex-shrink-0">
                          {index + 1}
                        </span>
                        <Box grow width="min">
                          <div className="flex items-center gap-1.5">
                            <span className="font-medium truncate">{field.name}</span>
                            {field.is_mandatory && (
                              <span className="text-red-500 text-xs font-bold">*</span>
                            )}
                          </div>
                          <div className="flex items-center gap-1.5 mt-0.5">
                            <Badge variant="secondary" className="text-[10px] h-4 px-1 py-0">
                              {FIELD_TYPE_LABELS[field.sys_reference_id] ??
                                field.reference_name ??
                                String(field.sys_reference_id)}
                            </Badge>
                          </div>
                        </Box>
                        <button type="button"
                          onClick={() => handleGridToggleVisibility(field.sys_field_id)}
                          className="flex-shrink-0 text-muted-foreground hover:text-foreground transition-colors"
                          title={field.is_displayed ? "Hide column" : "Show column"}
                        >
                          {field.is_displayed ? (
                            <Eye className="h-3.5 w-3.5 text-primary/70" />
                          ) : (
                            <EyeOff size={14} />
                          )}
                        </button>
                      </div>
                    )}
                  </Draggable>
                ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        </DragDropContext>
      ) : (
        /* ── Form mode: grouped panels ── */
        <DragDropContext onDragEnd={onDragEnd}>
          {visibleGroups.length > 0 ? (
            <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
              {visibleGroups.map((group) => (
                <GroupPanel
                  key={group.id}
                  group={group}
                  onEditToggle={handleEditToggle}
                  onEditSave={handleEditSave}
                  onEditCancel={handleEditCancel}
                  onDelete={handleDeleteGroup}
                  onToggleVisibility={handleToggleVisibility}
                  onToggleSummary={handleToggleSummary}
                />
              ))}

              <button type="button"
                onClick={handleAddGroup}
                className="flex flex-col items-center justify-center gap-2 rounded-xl border-2 border-dashed border-primary/30 bg-primary/5 hover:bg-primary/10 hover:border-primary/50 transition-colors min-h-[120px] p-6 text-primary/70 hover:text-primary"
              >
                <Plus size={24} />
                <span className="text-sm font-medium">Add Group</span>
              </button>
            </div>
          ) : (
            <div className="flex items-center justify-center py-8">
              <button type="button"
                onClick={handleAddGroup}
                className="flex flex-col items-center gap-3 px-8 py-6 rounded-xl border-2 border-dashed border-primary/30 bg-primary/5 hover:bg-primary/10 transition-colors text-primary"
              >
                <Plus size={32} />
                <div className="text-center">
                  <p className="font-semibold">No field groups yet</p>
                  <p className="text-sm text-muted-foreground mt-1">
                    Create groups to organize fields into multi-column layouts
                  </p>
                </div>
              </button>
            </div>
          )}

          {unassignedGroup && (
            <div className="mt-2">
              <div className="flex items-center gap-2 mb-2">
                <div className="h-px flex-1 bg-border" />
                <span className="text-xs text-muted-foreground font-medium px-2">
                  Unassigned ({unassignedGroup.fields.length})
                </span>
                <div className="h-px flex-1 bg-border" />
              </div>
              <GroupPanel
                group={unassignedGroup}
                onEditToggle={handleEditToggle}
                onEditSave={handleEditSave}
                onEditCancel={handleEditCancel}
                onDelete={handleDeleteGroup}
                onToggleVisibility={handleToggleVisibility}
                onToggleSummary={handleToggleSummary}
              />
            </div>
          )}
        </DragDropContext>
      )}

      {/* Legend */}
      <div className="flex items-center gap-4 text-xs text-muted-foreground pt-2 border-t border-border flex-wrap">
        <span className="flex items-center gap-1.5">
          <GripVertical size={14} /> Drag to reorder or move between groups
        </span>
        <span className="flex items-center gap-1.5">
          <Eye size={14} /> Toggle field visibility
        </span>
        <span className="flex items-center gap-1.5">
          <Pencil size={14} /> Edit group name &amp; columns
        </span>
        <span className="flex items-center gap-1.5 text-amber-600">
          <Star size={14} /> Mark group as Summary (shown in record header)
        </span>
      </div>
    </div>
  );
}

/**
 * The business entities this application contains, and their fields.
 *
 * Read by anything that has to offer a choice of entity or of column — the
 * rule editors and the report designer today. It was written for the rule
 * screens and named after them; the second caller is what makes the name
 * wrong rather than the code, so the module moved and the code did not.
 *
 * Read from the Application Dictionary, not from a list in the source. The
 * previous version of the rule screens shipped a hard-coded array — `Account`,
 * `Contact`, `Opportunity`, `bus_patient` — left over from the CRM and clinic
 * models the templates were first written against. Every generated app
 * inherited it, so a drug-discovery app offered rules on *Patient* and
 * *Opportunity* and offered none on *Compound* or *Experiment*. The dictionary
 * is the only thing that knows what a given app actually contains.
 *
 * `/sys/*` reads are open, so these work before the caller has any particular
 * permission — the dictionary describes the data, it is not the data.
 */

import { useQuery } from "@tanstack/react-query";
import { apiClient } from "@/lib/api-client";

export interface DictionaryEntity {
  /** Physical table, e.g. `bus_compound`. What the rule is stored against. */
  value: string;
  /** The window the entity opens in, e.g. `Compound`. Never the table's name. */
  label: string;
  table: string;
}

interface TableRow {
  sys_table_id: string;
  table_name: string;
  is_active?: boolean;
}

interface WindowRow {
  sys_window_id: string;
  name: string;
}

interface TabRow {
  sys_window_id: string;
  sys_table_id: string;
  name: string;
  tab_level: number;
  seq_no?: number;
}

interface ColumnRow {
  column_name: string;
  name?: string;
  seq_no?: number;
}

/** Rows out of a response that may be a bare array or `{ data: [...] }`. */
function rows<T>(payload: unknown): T[] {
  if (Array.isArray(payload)) return payload as T[];
  const data = (payload as { data?: unknown })?.data;
  return Array.isArray(data) ? (data as T[]) : [];
}

/** Every business entity in this application, alphabetical by display name. */
export function useDictionaryEntities() {
  return useQuery<DictionaryEntity[]>({
    queryKey: ["dictionary-entities"],
    queryFn: async () => {
      const [tables, windows, tabs] = await Promise.all([
        apiClient.get<unknown>("/sys/tables", { limit: 500 }),
        apiClient.get<unknown>("/sys/windows", { limit: 500 }),
        apiClient.get<unknown>("/sys/tabs", { limit: 500 }),
      ]);
      const windowRows = rows<WindowRow>(windows);
      const tabRows = rows<TabRow>(tabs);
      // The label is the window's (or, for a line item, its tab's) name.
      const labelOf = (table: TableRow): string | undefined => {
        const tab = tabRows
          .filter((candidate) => candidate.sys_table_id === table.sys_table_id)
          .sort((a, b) => a.tab_level - b.tab_level || (a.seq_no ?? 0) - (b.seq_no ?? 0))[0];
        if (!tab) return undefined;
        return tab.tab_level === 0
          ? (windowRows.find((w) => w.sys_window_id === tab.sys_window_id)?.name ?? tab.name)
          : tab.name;
      };
      return rows<TableRow>(tables)
        .filter((table) => table.table_name?.startsWith("bus_") && table.is_active !== false)
        .flatMap((table) => {
          const label = labelOf(table);
          // An entity with no window and no tab has no screen to name.
          return label ? [{ value: table.table_name, label, table: table.table_name }] : [];
        })
        .sort((a, b) => a.label.localeCompare(b.label));
    },
    // The dictionary changes when the model is regenerated, not while someone
    // is writing a rule.
    staleTime: 30 * 60 * 1000,
  });
}

/** The column names of one entity, in dictionary order. */
export function useDictionaryEntityFields(table: string | undefined) {
  return useQuery<string[]>({
    queryKey: ["dictionary-entity-fields", table],
    // The caller may not know the entity yet (a rule still loading).
    enabled: Boolean(table),
    queryFn: async () => {
      const response = await apiClient.get<unknown>("/sys/columns", {
        table: table as string,
        limit: 500,
      });
      const seen = new Set<string>();
      return rows<ColumnRow>(response)
        .sort((a, b) => (a.seq_no ?? 0) - (b.seq_no ?? 0))
        .map((column) => column.column_name)
        .filter((name) => {
          // `/sys/columns` can return a column twice when a field is on more
          // than one tab; a duplicate in a field picker looks like a bug.
          if (!name || seen.has(name)) return false;
          seen.add(name);
          return true;
        });
    },
    staleTime: 30 * 60 * 1000,
  });
}

/**
 * Names an entity the way the screens do: by the window it opens in, never by
 * the table it is stored in. A table the dictionary does not know (a rule left
 * behind by a removed entity) is shown tidied rather than raw.
 */
export function useEntityLabel() {
  const { data } = useDictionaryEntities();
  return (table: string | null | undefined): string => {
    if (!table) return "";
    return (
      data?.find((e) => e.value === table)?.label ?? table.replace(/^bus_/, "").replace(/_/g, " ")
    );
  };
}

/**
 * Report designs, read and written through the generic dictionary verbs.
 *
 * `sys_report_designs` is served by the same `/api/sys/{segment}` handler as
 * every other dictionary resource, so there is no `/report-designs/{table}`
 * route to address a design by the entity it belongs to — the segment is keyed
 * by `sys_report_design_id` like all the others. A table has exactly one
 * design (the unique index says so), so `?filter.table_name=` is an exact
 * lookup and the id it returns is what an update and a delete need.
 *
 * That indirection is deliberate rather than incidental. A bespoke controller
 * keyed by table name would be a second way to reach one table, with its own
 * authorisation to keep in step; the generic verbs already have one.
 */

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { apiClient } from "@/lib/api-client";

export interface ReportDesign {
  sys_report_design_id: string;
  table_name: string;
  name: string;
  layout: Record<string, unknown> | null;
  updated_at?: string;
}

function rows<T>(payload: unknown): T[] {
  if (Array.isArray(payload)) return payload as T[];
  const data = (payload as { data?: unknown })?.data;
  return Array.isArray(data) ? (data as T[]) : [];
}

/** Every design in the application, keyed by the table it belongs to. */
export function useReportDesigns() {
  return useQuery<Map<string, ReportDesign>>({
    queryKey: ["report-designs"],
    queryFn: async () => {
      const response = await apiClient.get<unknown>("/sys/report-designs", { limit: 500 });
      return new Map(rows<ReportDesign>(response).map((design) => [design.table_name, design]));
    },
  });
}

/** The one design for a table, or null if nobody has drawn one yet. */
export function useReportDesign(tableName: string | undefined) {
  return useQuery<ReportDesign | null>({
    queryKey: ["report-design", tableName],
    queryFn: async () => {
      const response = await apiClient.get<unknown>("/sys/report-designs", {
        "filter.table_name": tableName as string,
      });
      return rows<ReportDesign>(response)[0] ?? null;
    },
    enabled: !!tableName,
  });
}

/**
 * Save a table's layout, creating the design on first save.
 *
 * Create-or-update rather than an upsert endpoint, because the segment offers
 * the five generic verbs and nothing else. The existing row is read from the
 * cache the designer already populated, so the common path is one request.
 */
export function useSaveReportDesign(tableName: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      layout,
      name,
      existing,
    }: {
      layout: Record<string, unknown>;
      name: string;
      existing: ReportDesign | null;
    }) => {
      if (existing) {
        return apiClient.put<ReportDesign>(
          `/sys/report-designs/${existing.sys_report_design_id}`,
          { table_name: tableName, name, layout }
        );
      }
      return apiClient.post<ReportDesign>("/sys/report-designs", {
        table_name: tableName,
        name,
        layout,
      });
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ["report-design", tableName] });
      void queryClient.invalidateQueries({ queryKey: ["report-designs"] });
    },
  });
}

import { HelpCircle, X } from "lucide-react";
import { useEffect, useState } from "react";
import { useEntityMetadata, useWindowHelp } from "@/hooks/use-entities";
import { Box, HStack, Heading, Text, VStack } from "@/components/ui/layout";

/**
 * The physical table an endpoint is served from, asked of the dictionary.
 *
 * The endpoint carries the *route* segment, which is not the table name: it
 * has no `bus_` prefix, and under the catch-all `$entity` route it is whatever
 * the URL said — `/api/bus/*` resolves plurals and aliases through the
 * dictionary, so `/bus/companies` is a working endpoint whose table is
 * `bus_company`.
 *
 * A screen that needs the table name for anything matched *literally* — a
 * `filter.table_name=` on `sys_report_designs`, say — therefore cannot derive
 * it from the endpoint, and gets an empty result rather than an error when it
 * tries. Asking `/bus/{route}/meta` is the dictionary's own answer, and it is
 * keyed like every other metadata read, so a screen already holding it pays
 * nothing.
 *
 * Anything not served from `/bus/` — the admin windows on `/sys/` — has no
 * business window to describe, so it resolves to an empty name and the dialog
 * hides itself.
 */
export function useBusTableName(endpoint: string): string {
  const route = /^\/bus\/([^/?]+)/.exec(endpoint)?.[1] ?? "";
  const { data } = useEntityMetadata(route, !!route);
  return data?.tableName ?? "";
}

/**
 * The Help button and screen for a window.
 *
 * Text comes from the Application Dictionary (sys_window.help, sys_tab.help and
 * sys_field.help), so administrators can rewrite any of it from Window, Tab and
 * Field without touching this component. The button hides itself when the
 * window has no help at all rather than opening an empty dialog.
 */
export function WindowHelpDialog({
  tableName,
  entityLabel,
}: {
  tableName: string;
  entityLabel: string;
}) {
  const [open, setOpen] = useState(false);
  const { data: helpData } = useWindowHelp(tableName);

  const windowHelp = helpData?.window;
  const tabs = (helpData?.tabs ?? []).filter((t) => t.help);
  const fields = (helpData?.fields ?? []).filter((f) => f.help);
  const hasHelp = !!windowHelp?.help || tabs.length > 0 || fields.length > 0;

  // Esc closes, matching every other dismissible surface in the app.
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open]);

  if (!hasHelp) return null;

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        aria-label={`Help for ${entityLabel}`}
        className="inline-flex items-center gap-1 rounded-full bg-primary/10 px-2 py-0.5 text-[11px] font-medium text-primary hover:bg-primary/20 transition-colors"
        title={`Help for ${entityLabel}`}
      >
        <HelpCircle size={14} />
        Help
      </button>

      {open && (
        <dialog
          open
          className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-transparent max-w-none max-h-none w-full h-full"
          aria-modal="true"
          aria-label={`${entityLabel} help`}
        >
          <button
            type="button"
            aria-label="Close help"
            className="fixed inset-0 bg-black/50"
            onClick={() => setOpen(false)}
          />
          <VStack fullWidth className="relative z-10 max-w-2xl rounded-xl border border-border bg-background shadow-2xl max-h-[80vh]">
            <HStack align="center" justify="between" paddingInline={6} paddingBlock={4} className="border-b border-border bg-gradient-to-r from-primary/10 to-primary/5 rounded-t-xl">
              <HStack align="center" gap={2}>
                <HelpCircle className="w-5 h-5 text-primary" />
                <Heading level={2} color="primary">{entityLabel} — Help</Heading>
              </HStack>
              <button
                type="button"
                onClick={() => setOpen(false)}
                aria-label="Close help"
                className="text-muted-foreground hover:text-foreground transition-colors"
              >
                <X size={20} />
              </button>
            </HStack>

            <Box padding={6} scrollable className="space-y-6">
              {windowHelp?.help && (
                <section>
                  <Heading level={3} uppercase color="accent" className="mb-2">
                    Window Overview
                  </Heading>
                  <Text size="sm" color="primary" block className="leading-relaxed whitespace-pre-wrap">
                    {windowHelp.help}
                  </Text>
                </section>
              )}

              {tabs.length > 0 && (
                <section className="space-y-3">
                  <Heading level={3} uppercase color="accent">
                    Tabs
                  </Heading>
                  {tabs.map((tab) => (
                    <div
                      key={tab.sys_tab_id}
                      className="rounded-lg border border-border/60 bg-muted/20 p-3"
                    >
                      <Text size="xs" weight="semibold" color="primary" block className="mb-1">{tab.name}</Text>
                      <Text size="xs" color="secondary" block className="leading-relaxed whitespace-pre-wrap">
                        {tab.help}
                      </Text>
                    </div>
                  ))}
                </section>
              )}

              {fields.length > 0 && (
                <section className="space-y-2">
                  <Heading level={3} uppercase color="accent">
                    Fields{" "}
                    <Text weight="normal" color="secondary" className="normal-case tracking-normal">
                      ({fields.length})
                    </Text>
                  </Heading>
                  <dl className="divide-y divide-border/60 rounded-lg border border-border/60 overflow-hidden">
                    {fields.map((field) => (
                      <div
                        key={field.sys_field_id}
                        className="grid grid-cols-1 sm:grid-cols-3 gap-1 sm:gap-3 p-3 odd:bg-muted/20"
                      >
                        <dt className="text-xs font-semibold text-foreground flex items-start gap-1">
                          <span>{field.name}</span>
                          {field.is_mandatory && (
                            <Text color="danger" title="Required">
                              *
                            </Text>
                          )}
                        </dt>
                        <dd className="sm:col-span-2 text-xs text-muted-foreground leading-relaxed whitespace-pre-wrap">
                          {field.help}
                        </dd>
                      </div>
                    ))}
                  </dl>
                </section>
              )}
            </Box>
          </VStack>
        </dialog>
      )}
    </>
  );
}

import { useMutation, useQuery } from "@tanstack/react-query";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Box, HStack, Text } from "@/components/ui/layout";
import { apiClient } from "@/lib/api-client";
import { describeStatus, ifMatch, isConcurrencyError, transactionStatusOf } from "@/lib/concurrency";
import { notifySaved } from "@/lib/embed";

interface Move {
  tableName: string;
  statusField: string;
  from: string;
  to: string;
  transition: string | null;
}

interface WorkflowStateBarProps {
  /** Physical table, e.g. `bus_sales_order` — what the state machine is drawn against. */
  tableName: string;
  /** `/bus/<table>` — where the move is written. */
  endpoint: string;
  recordId: string;
  record: Record<string, unknown>;
  /**
   * A move proposed from outside the screen — the chat's approval request opens
   * a record with the transition it suggested. It is marked, never made: the
   * person presses it.
   */
  proposed?: string | null;
  /** Called after a move is accepted, so the page can read the record again. */
  onMoved: () => void;
}

const words = (value: string) =>
  value
    .toLowerCase()
    .split(/[_\s-]+/)
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
    .join(" ");

/**
 * The state a record is in and the moves out of it.
 *
 * A status column rendered as a text box or a free dropdown offers moves the
 * state machine does not draw, and the write is refused only after the user has
 * committed to it. The machine is read from the dictionary
 * (`/workflows/transitions`) and the buttons are exactly the edges that leave
 * the current state, so what is offered is what will be accepted. A table with
 * no machine renders nothing.
 */
export function WorkflowStateBar({
  tableName,
  endpoint,
  recordId,
  record,
  proposed = null,
  onMoved,
}: WorkflowStateBarProps) {
  const { data: machine } = useQuery({
    queryKey: ["workflow-machine", tableName],
    queryFn: () => apiClient.get<Move[]>("/workflows/transitions", { table: tableName }),
    staleTime: 60_000,
  });

  const move = useMutation({
    // The move names the version the record was read at, like any other save:
    // a move made on a record someone has since changed is refused rather than
    // applied to a state the person never saw.
    mutationFn: (step: Move) =>
      apiClient.patch(
        `${endpoint}/${recordId}`,
        { [step.statusField]: step.to },
        { headers: ifMatch(record) }
      ),
    onSuccess: (saved, step) => {
      notifySaved("transition", saved, recordId);
      const status = describeStatus(transactionStatusOf(saved)) ?? words(step.to);
      toast.success(`${step.transition ? words(step.transition) : "Moved"}: now ${status}`);
      onMoved();
    },
    onError: (err: unknown) => {
      if (isConcurrencyError(err)) {
        // Someone else moved or changed the record first. Say where it is now
        // and re-read it, so the buttons offered are the moves out of the
        // state it is really in.
        const where = describeStatus(err.conflict.status);
        toast.error(
          err.error === "RECORD_FINAL"
            ? `This record is ${where ?? "in a final state"}: its transaction is complete.`
            : `Changed by ${err.conflict.changedBy ?? "another user"} since you opened it${where ? ` — now ${where}` : ""}.`
        );
        onMoved();
        return;
      }
      const e = err as { errors?: string[]; message?: string | string[] };
      const text =
        e?.errors?.join(", ") ??
        (Array.isArray(e?.message) ? e.message.join(", ") : e?.message) ??
        "That move was refused";
      toast.error(text);
    },
  });

  const moves = Array.isArray(machine) ? machine : [];
  const field = moves[0]?.statusField;
  if (!field) return null;

  const current = String(record[field] ?? "");
  const next = moves.filter((m) => m.from === current);
  // The record's own read says whether its state is final (`transactionStatus`).
  const isFinal = transactionStatusOf(record)?.isFinal === true;

  return (
    <Box
      className="workflow-state-bar rounded-md border px-4 py-2"
      data-testid="workflow-state-bar"
    >
      <HStack align="center" gap={3} wrap>
        <Text size="xs" color="secondary" weight="medium">
          State
        </Text>
        <Badge variant="default" data-testid="workflow-current-state">
          {current ? words(current) : "Not set"}
        </Badge>
        {next.length > 0 ? (
          <>
            <Text size="xs" color="secondary">
              Next
            </Text>
            {next.map((step) => (
              <Button
                key={`${step.from}-${step.to}`}
                type="button"
                variant={step.to === proposed ? "default" : "secondary"}
                size="sm"
                disabled={move.isPending}
                data-testid={`workflow-move-${step.to}`}
                onClick={() => move.mutate(step)}
              >
                {step.transition ? words(step.transition) : `→ ${words(step.to)}`}
              </Button>
            ))}
          </>
        ) : (
          <Text size="xs" color="secondary">
            {isFinal ? "Final — this transaction is complete" : "No further moves from here"}
          </Text>
        )}
      </HStack>
    </Box>
  );
}

/**
 * Ask a question about the data (decision D5).
 *
 * Talks to `POST /api/ai/query`, which answers with the rows plus the
 * *validated plan* the question was translated into. Showing that plan is the
 * point rather than a debugging nicety: the backend never lets the model write
 * SQL, so the plan is the whole of what ran, and a reader can tell at a glance
 * whether the question was understood before trusting the number underneath it.
 *
 * The panel deliberately renders nothing clever. Results are the same rows
 * `/api/bus/{entity}` returns, so `DynamicTable` — the component every list
 * screen in this app already uses — displays them, and a "how many" question
 * shows the count large instead; that is what `displayHint` selects.
 */

import { useState } from "react";
import { useMutation } from "@tanstack/react-query";
import { useNavigate } from "@tanstack/react-router";
import { AlertCircle } from "lucide-react";

import { apiClient } from "@/lib/api-client";
import { getErrorMessage } from "@/lib/api-client";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { EmptyState } from "@/components/ui/empty-state";
import { Box, HStack, VStack, Heading, Text } from "@/components/ui/layout";
import { DynamicTable } from "@/components/tables/dynamic-table";

interface PlanFilter {
  column: string;
  op: string;
  value: string;
}

interface QueryPlan {
  entity: string;
  filters?: PlanFilter[];
  search?: string | null;
  order_by?: string | null;
  order_dir?: string | null;
  limit?: number | null;
  display_hint?: string | null;
  summary?: string | null;
}

interface QueryAnswer {
  success: boolean;
  data: Array<Record<string, unknown>>;
  count: number;
  entity: string;
  displayHint: "table" | "number" | string;
  summary: string | null;
  plan: QueryPlan;
  executionTimeMs: number;
}

/** The plan, in one readable line. */
function planSummary(plan: QueryPlan): string {
  const parts = [plan.entity];
  for (const filter of plan.filters ?? []) {
    parts.push(`${filter.column} ${filter.op} ${filter.value}`);
  }
  if (plan.search) parts.push(`search "${plan.search}"`);
  if (plan.order_by) parts.push(`sorted by ${plan.order_by} ${plan.order_dir ?? "asc"}`);
  if (plan.limit) parts.push(`limit ${plan.limit}`);
  return parts.join(" · ");
}

export function NlQueryPanel() {
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState<QueryAnswer | null>(null);
  const navigate = useNavigate();

  const ask = useMutation({
    mutationFn: (query: string) => apiClient.post<QueryAnswer>("/ai/query", { query }),
    onSuccess: (result) => setAnswer(result),
  });

  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    const trimmed = question.trim();
    if (trimmed) ask.mutate(trimmed);
  };

  // A 503 means the add-on is not configured, which is the default and is not
  // an error the operator needs to debug — so it reads as a setup note rather
  // than a failure.
  const notConfigured =
    ask.isError && getErrorMessage(ask.error).toLowerCase().includes("not configured");

  // The dictionary routes and the record routes both take the entity unprefixed
  // — `/bus/compound/fields/grid`, `/compound/{id}` — while the answer names
  // the table it actually read. Strip once, here, rather than at each use.
  const entityName = answer ? answer.entity.replace(/^bus_/, "") : "";

  return (
    <VStack gap={4}>
      <form onSubmit={submit}>
        <HStack gap={2} align="center">
          {/* `grow` on a wrapper rather than on the Input: the Input adapter
              forwards no layout props, so without this the question box renders
              at its intrinsic width — about 25 characters on a 960px page, for
              the one control the whole page exists to serve. */}
          <Box grow>
            <Input
              value={question}
              onChange={(event) => setQuestion(event.target.value)}
              placeholder="Ask about your data — e.g. “how many compounds were added this month?”"
              aria-label="Question"
              disabled={ask.isPending}
            />
          </Box>
          {/* A plain string label, and `isLoading` for the spinner. The Button
              adapter passes a string child to Astryx's `label` prop and
              anything else to `children`, which Astryx stacks vertically — an
              icon plus a `<span>` rendered the magnifier sitting on top of the
              word "Ask". Every other labelled button in this app is a string
              for the same reason. */}
          <Button
            type="submit"
            disabled={ask.isPending || !question.trim()}
            isLoading={ask.isPending}
          >
            Ask
          </Button>
        </HStack>
      </form>

      {notConfigured && (
        <Card>
          <VStack gap={2}>
            <Heading level={3}>Natural-language querying is turned off</Heading>
            <Text size="sm" color="secondary">
              Set <code>LOCAL_AI_BASE_URL</code> and <code>LOCAL_AI_MODEL</code> in the backend’s
              environment and restart it. Any OpenAI-compatible endpoint works. Nothing else in the
              application changes while it is off.
            </Text>
          </VStack>
        </Card>
      )}

      {ask.isError && !notConfigured && (
        <Card>
          <HStack gap={2} align="center">
            <AlertCircle size={16} />
            <Text size="sm">{getErrorMessage(ask.error)}</Text>
          </HStack>
        </Card>
      )}

      {answer && (
        <Card>
          <VStack gap={3}>
            {answer.summary && <Text size="sm">{answer.summary}</Text>}

            {/* What actually ran. Shown because the plan *is* the query. */}
            <Text size="xs" color="secondary">
              {planSummary(answer.plan)} · {answer.count} row{answer.count === 1 ? "" : "s"} ·{" "}
              {answer.executionTimeMs}ms
            </Text>

            {answer.displayHint === "number" ? (
              <Box>
                <Heading level={1}>{answer.count}</Heading>
                <Text size="sm" color="secondary">
                  matching {entityName}
                </Text>
              </Box>
            ) : answer.data.length === 0 ? (
              <EmptyState
                title="No matching records"
                description="The question was understood — nothing in this entity matches it."
              />
            ) : (
              /* The same component every list screen uses, for the same reason
                 the answer comes back as plain `/api/bus/*` rows: an answer
                 should look like the records it is about. Hand-rolling a table
                 here rendered raw `sys_column` names as headers and raw UUIDs
                 in every foreign key — `registered_by_id` showed
                 `cda967a2-…` where the Compound screen one click away showed
                 "Ada Lovelace". DynamicTable reads the dictionary for the
                 labels, the column order and the grid's own hidden set, and
                 batch-resolves lookups to their identifier columns.

                 No pagination props on purpose: a plan returns one capped page,
                 and DynamicTable hides both the pager and the "showing N of M"
                 line while `totalCount` is 0. */
              <DynamicTable
                tableName={entityName}
                data={answer.data}
                onRowClick={(row) =>
                  navigate({
                    to: "/$entity/$id",
                    params: { entity: entityName, id: String(row.id) },
                  })
                }
              />
            )}
          </VStack>
        </Card>
      )}
    </VStack>
  );
}

