export function RailSection({
  heading,
  items,
  total,
  selectedId,
  onSelect,
  onLoadMore,
  loadingMore = false,
  emptyText = "None yet.",
}: RailSectionProps) {
  const knownTotal = total ?? items.length;
  const hasMore = items.length < knownTotal;

  return (
    <>
      <h2 className="flex items-baseline gap-2 px-4 pb-1.5 pt-4 text-[11px] font-semibold uppercase tracking-[0.07em] text-muted-foreground">
        {heading}
        {knownTotal > 0 ? (
          <span className="font-normal tabular-nums">
            {items.length < knownTotal
              ? `${items.length.toLocaleString()} of ${knownTotal.toLocaleString()}`
              : knownTotal.toLocaleString()}
          </span>
        ) : null}
      </h2>

      {items.length === 0 ? (
        <p className="px-4 pb-2 text-xs text-muted-foreground">{emptyText}</p>
      ) : null}

      {items.map((item) => (
        <button
          key={item.id}
          type="button"
          onClick={() => onSelect(item.id)}
          aria-current={selectedId === item.id ? "page" : undefined}
          className={cn(
            "mx-2 flex items-start gap-2.5 rounded-lg px-2.5 py-2 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary",
            selectedId === item.id ? "bg-primary/10" : "hover:bg-muted"
          )}
        >
          <span
            aria-hidden="true"
            className={cn(
              "mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full",
              item.state === "live"
                ? "bg-emerald-500"
                : item.state === "draft"
                  ? "bg-amber-500"
                  : "bg-neutral-400"
            )}
          />
          <span className="min-w-0">
            <span
              className={cn(
                "block truncate text-[13px]",
                selectedId === item.id && "font-semibold"
              )}
            >
              {item.title}
            </span>
            <span className="block truncate text-[11.5px] text-muted-foreground">
              {item.subtitle}
            </span>
          </span>
        </button>
      ))}

      {hasMore && onLoadMore ? (
        <button
          type="button"
          onClick={onLoadMore}
          disabled={loadingMore}
          className="mx-2 mt-1 rounded-lg border border-dashed border-border px-2.5 py-2 text-[12.5px] font-semibold text-muted-foreground hover:border-primary/50 hover:text-primary disabled:opacity-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          {loadingMore
            ? "Loading…"
            : `Show ${Math.min(PAGE_SIZE, knownTotal - items.length).toLocaleString()} more`}
        </button>
      ) : null}
    </>
  );
}

/**
 * A rule table: the conditions on the left, the answer on the right.
 *
 * Rows are read top to bottom and the first one that fits wins. That ordering
 * is the whole semantics, so the editor makes it visible — rows are numbered,
 * draggable, and the catch-all is pinned last and worded as "Otherwise" rather
 * than left as a row of empty cells the author has to recognise.
 *
 * The two panels underneath answer the questions a table always raises: what
 * does it say for this input, and is there an input it says nothing for.
 */

import { useMemo, useState } from "react";
import { cn } from "@/lib/utils";
import {
  type DecisionColumn,
  type DecisionRow,
  type DecisionTable,
  getColumnOptions,
  KNOWN_OUTPUT_FIELDS,
  newRowId,
} from "@/lib/workflow/bpmn-model";

const cellClass =
  "w-full min-w-[80px] rounded-md border border-input bg-card px-2 py-1.5 text-[13px] focus-visible:outline-none focus-visible:border-primary focus-visible:ring-[3px] focus-visible:ring-primary/10";

/* -------------------------------------------------------------------------- */
/*  Evaluation — the same first-match rule the engine applies                  */
/* -------------------------------------------------------------------------- */

export interface TableTestResult {
  rowIndex: number | null;
  outputs: Record<string, string>;
}

/**
 * Which row fits, given some values.
 *
 * Deliberately a small subset of the expression language: `=`, `>`, `>=`, `<`,
 * `<=`, `!=`, and a bare value meaning equality. A blank cell means "any". This
 * runs in the browser so the author gets an answer while typing; the engine
 * remains the authority at run time, and anything this cannot parse is treated
 * as not matching rather than as matching by accident.
 */
export function evaluateTable(
  table: DecisionTable,
  values: Record<string, string>
): TableTestResult {
  for (let i = 0; i < table.rules.length; i++) {
    const row = table.rules[i];
    if (!row) continue;
    const fits = table.inputs.every((col) => {
      const cell = (row[col.id] ?? "").trim();
      if (!cell) return true;
      return cellMatches(cell, values[col.field] ?? "");
    });
    if (fits) {
      const outputs: Record<string, string> = {};
      for (const col of table.outputs) outputs[col.field || col.name] = unquote(row[col.id] ?? "");
      return { rowIndex: i, outputs };
    }
  }
  return { rowIndex: null, outputs: {} };
}

function cellMatches(cell: string, value: string): boolean {
  const m = cell.match(/^\s*(>=|<=|!=|=|>|<)?\s*(.+)$/);
  if (!m) return false;
  const op = m[1] ?? "=";
  const raw = unquote((m[2] ?? "").trim());

  const a = Number(value);
  const b = Number(raw);
  const numeric = !Number.isNaN(a) && !Number.isNaN(b) && value.trim() !== "";

  switch (op) {
    case "=":
      return numeric ? a === b : value === raw;
    case "!=":
      return numeric ? a !== b : value !== raw;
    case ">":
      return numeric && a > b;
    case ">=":
      return numeric && a >= b;
    case "<":
      return numeric && a < b;
    case "<=":
      return numeric && a <= b;
    default:
      return false;
  }
}

function unquote(s: string): string {
  const t = s.trim();
  if (t.length >= 2 && (t.startsWith('"') || t.startsWith("'"))) {
    const q = t[0] as string;
    if (t.endsWith(q)) return t.slice(1, -1);
  }
  return t;
}

/* -------------------------------------------------------------------------- */
/*  Coverage — the two things that silently break a table                      */
/* -------------------------------------------------------------------------- */

export interface CoverageNote {
  level: "ok" | "warn";
  message: string;
}

/**
 * Report gaps and shadowed rows.
 *
 * A gap means some input reaches no row and the step quietly produces nothing.
 * A shadowed row means an earlier row already covers everything a later one
 * does, so the later row can never fire — almost always a reordering mistake
 * rather than an intention.
 */
export function checkCoverage(table: DecisionTable): CoverageNote[] {
  const notes: CoverageNote[] = [];
  const hasCatchAll = table.rules.some((row) =>
    table.inputs.every((c) => !(row[c.id] ?? "").trim())
  );

  notes.push(
    hasCatchAll
      ? { level: "ok", message: "Every combination of inputs reaches a row. No gaps." }
      : {
          level: "warn",
          message:
            "No catch-all row. If nothing fits, this table returns no answer and the step produces nothing. Add a row with every check left blank.",
        }
  );

  for (let i = 0; i < table.rules.length; i++) {
    for (let j = i + 1; j < table.rules.length; j++) {
      const earlier = table.rules[i];
      const later = table.rules[j];
      if (!earlier || !later) continue;
      const shadowed = table.inputs.every((c) => {
        const e = (earlier[c.id] ?? "").trim();
        const l = (later[c.id] ?? "").trim();
        return !e || e === l;
      });
      if (shadowed) {
        notes.push({
          level: "warn",
          message: `Row ${i + 1} already covers everything row ${j + 1} does, so row ${j + 1} can never fire. Reorder if that is not what you meant.`,
        });
        return notes;
      }
    }
  }

  return notes;
}

/* -------------------------------------------------------------------------- */
/*  Editor                                                                     */
/* -------------------------------------------------------------------------- */

export interface RuleTableEditorProps {
  name: string;
  table: DecisionTable;
  onChange: (next: DecisionTable) => void;
  /** Automations that look this table up, so a change's blast radius is visible. */
  usedBy?: { name: string; where: string }[];
  /** Entity field names for the input column dropdowns. */
  entityFields?: string[];
}

export function RuleTableEditor({
  name,
  table,
  onChange,
  usedBy = [],
  entityFields = [],
}: RuleTableEditorProps) {
  const [testValues, setTestValues] = useState<Record<string, string>>({});

  const result = useMemo(() => evaluateTable(table, testValues), [table, testValues]);
  const coverage = useMemo(() => checkCoverage(table), [table]);

  const setCell = (rowIndex: number, colId: string, value: string) => {
    const rules = table.rules.map((r, i) => (i === rowIndex ? { ...r, [colId]: value } : r));
    onChange({ ...table, rules });
  };

  const addRow = () => {
    const row: DecisionRow = { _id: newRowId() };
    for (const c of [...table.inputs, ...table.outputs]) row[c.id] = "";
    onChange({ ...table, rules: [...table.rules, row] });
  };

  const removeRow = (index: number) =>
    onChange({ ...table, rules: table.rules.filter((_, i) => i !== index) });

  const moveRow = (index: number, delta: number) => {
    const to = index + delta;
    if (to < 0 || to >= table.rules.length) return;
    const rules = [...table.rules];
    const [moved] = rules.splice(index, 1);
    if (moved) rules.splice(to, 0, moved);
    onChange({ ...table, rules });
  };

  const addColumn = (side: "inputs" | "outputs") => {
    const prefix = side === "inputs" ? "i" : "o";
    const col: DecisionColumn = {
      id: `${prefix}${Date.now().toString(36)}`,
      name: side === "inputs" ? "New input" : "New outcome",
      field: "",
    };
    onChange({ ...table, [side]: [...table[side], col] });
  };

  const setColumn = (side: "inputs" | "outputs", id: string, patch: Partial<DecisionColumn>) =>
    onChange({
      ...table,
      [side]: table[side].map((c) => (c.id === id ? { ...c, ...patch } : c)),
    });

  const isCatchAll = (row: DecisionRow) => table.inputs.every((c) => !(row[c.id] ?? "").trim());
  const lastCatchAllIndex = (() => {
    for (let i = table.rules.length - 1; i >= 0; i--) {
      // Narrowed rather than asserted: noUncheckedIndexedAccess types this as
      // possibly undefined, and the assertion was the file's only lint warning.
      const row = table.rules[i];
      if (row && isCatchAll(row)) return i;
    }
    return -1;
  })();

  return (
    <div className="flex-1 overflow-y-auto bg-muted/30 px-7 py-6">
      <div className="flex items-center gap-3">
        <h1 className="text-xl font-bold tracking-tight">{name}</h1>
        {usedBy.length > 0 ? (
          <span className="rounded-full border border-border bg-muted px-2.5 py-1 text-[11px] font-semibold text-muted-foreground">
            Used by {usedBy.length} automation{usedBy.length === 1 ? "" : "s"}
          </span>
        ) : null}
      </div>
      <p className="mb-4 mt-1 text-[13px] text-muted-foreground">
        Rows are read top to bottom. The first row where every check fits is the answer.
      </p>

      {/* the table's declaration, as a sentence */}
      <div className="mb-4 rounded-xl border border-border bg-card px-4 py-3.5 text-[15px] leading-loose">
        Given{" "}
        {table.inputs.map((c, i) => (
          <span key={c.id}>
            {i > 0 ? " and " : ""}
            {entityFields.length > 0 ? (
              <select
                aria-label={`Input ${i + 1} field`}
                value={c.field}
                onChange={(e) => setColumn("inputs", c.id, { field: e.target.value })}
                className="mx-0.5 w-[9.5rem] rounded-md border border-border bg-muted px-2 py-1 text-sm font-semibold focus-visible:outline-none focus-visible:border-primary"
              >
                <option value="">— pick field —</option>
                {entityFields.map((f) => (
                  <option key={f} value={f}>
                    {f}
                  </option>
                ))}
              </select>
            ) : (
              <input
                aria-label={`Input ${i + 1} field`}
                value={c.field}
                onChange={(e) => setColumn("inputs", c.id, { field: e.target.value })}
                placeholder="Customer.tier"
                className="mx-0.5 w-[9.5rem] rounded-md border border-border bg-muted px-2 py-1 text-sm font-semibold focus-visible:outline-none focus-visible:border-primary"
              />
            )}
          </span>
        ))}
        , decide{" "}
        {table.outputs.map((c, i) => (
          <span key={c.id}>
            {i > 0 ? " and " : ""}
            <select
              aria-label={`Outcome ${i + 1} field`}
              value={c.field}
              onChange={(e) => setColumn("outputs", c.id, { field: e.target.value })}
              className="mx-0.5 w-[9.5rem] rounded-md border border-primary/30 bg-primary/5 px-2 py-1 text-sm font-semibold text-primary focus-visible:outline-none focus-visible:border-primary"
            >
              <option value="">— pick output —</option>
              {KNOWN_OUTPUT_FIELDS.map((f) => (
                <option key={f.field} value={f.field}>
                  {f.label}
                </option>
              ))}
            </select>
          </span>
        ))}
        <button
          type="button"
          onClick={() => addColumn("inputs")}
          className="ml-3 text-[13px] font-semibold text-primary hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          ＋ input
        </button>
        <button
          type="button"
          onClick={() => addColumn("outputs")}
          className="ml-2 text-[13px] font-semibold text-primary hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          ＋ outcome
        </button>
      </div>

      <div className="overflow-x-auto rounded-xl border border-border bg-card">
        <table className="w-full border-collapse text-[13.5px]">
          <thead>
            <tr>
              <th className="w-9 border-b border-border bg-muted/40 px-3 py-2" />
              <th
                colSpan={table.inputs.length}
                className="border-b border-border bg-muted/40 px-3 py-2 text-center text-[10.5px] font-bold uppercase tracking-[0.1em] text-blue-600"
              >
                ◇ When all of these fit
              </th>
              <th
                colSpan={table.outputs.length}
                className="border-b border-l-2 border-border px-3 py-2 text-center text-[10.5px] font-bold uppercase tracking-[0.1em] text-primary"
              >
                ▸ The answer is
              </th>
              <th className="w-10 border-b border-border bg-muted/40" />
            </tr>
            <tr>
              <th className="border-b border-border bg-muted/40" />
              {table.inputs.map((c) => (
                <th
                  key={c.id}
                  className="border-b border-border bg-muted/40 px-3 py-2 text-left text-[10.5px] font-bold uppercase tracking-[0.07em] text-blue-600"
                >
                  {c.field || c.name}
                </th>
              ))}
              {table.outputs.map((c, i) => (
                <th
                  key={c.id}
                  className={cn(
                    "border-b border-border bg-muted/40 px-3 py-2 text-left text-[10.5px] font-bold uppercase tracking-[0.07em] text-primary",
                    i === 0 && "border-l-2"
                  )}
                >
                  {c.field || c.name}
                </th>
              ))}
              <th className="border-b border-border bg-muted/40" />
            </tr>
          </thead>
          <tbody>
            {table.rules.map((row, rowIndex) => {
              const catchAll = isCatchAll(row) && rowIndex === lastCatchAllIndex;
              return (
                <tr key={row._id} className={cn(catchAll && "bg-muted/30")}>
                  <td className="border-b border-border px-2 py-2 text-center text-xs text-muted-foreground">
                    {catchAll ? "↓" : rowIndex + 1}
                  </td>

                  {catchAll ? (
                    <td
                      colSpan={table.inputs.length}
                      className="border-b border-border px-3 py-2 italic text-muted-foreground"
                    >
                      Otherwise — nothing above fit
                    </td>
                  ) : (
                    table.inputs.map((c) => (
                      <td key={c.id} className="border-b border-border px-2 py-2">
                        <input
                          aria-label={`Row ${rowIndex + 1}, ${c.field || c.name}`}
                          className={cellClass}
                          value={row[c.id] ?? ""}
                          onChange={(e) => setCell(rowIndex, c.id, e.target.value)}
                          placeholder="any"
                        />
                      </td>
                    ))
                  )}

                  {table.outputs.map((c, i) => {
                    const opts = getColumnOptions(c);
                    return (
                      <td
                        key={c.id}
                        className={cn("border-b border-border px-2 py-2", i === 0 && "border-l-2")}
                      >
                        {opts ? (
                          <select
                            aria-label={`Row ${rowIndex + 1}, ${c.field || c.name} answer`}
                            className={cn(
                              cellClass,
                              "border-primary/30 bg-primary/5 font-semibold text-primary"
                            )}
                            value={row[c.id] ?? ""}
                            onChange={(e) => setCell(rowIndex, c.id, e.target.value)}
                          >
                            <option value="">— pick —</option>
                            {opts.map((o) => (
                              <option key={o} value={o}>
                                {o}
                              </option>
                            ))}
                          </select>
                        ) : (
                          <input
                            aria-label={`Row ${rowIndex + 1}, ${c.field || c.name} answer`}
                            className={cn(
                              cellClass,
                              "border-primary/30 bg-primary/5 font-semibold text-primary"
                            )}
                            value={row[c.id] ?? ""}
                            onChange={(e) => setCell(rowIndex, c.id, e.target.value)}
                          />
                        )}
                      </td>
                    );
                  })}

                  <td className="border-b border-border px-1 py-2 text-center">
                    <div className="flex items-center justify-center gap-0.5">
                      <button
                        type="button"
                        aria-label={`Move row ${rowIndex + 1} up`}
                        onClick={() => moveRow(rowIndex, -1)}
                        disabled={rowIndex === 0}
                        className="rounded px-1 text-xs text-muted-foreground hover:bg-muted disabled:opacity-30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
                      >
                        ↑
                      </button>
                      <button
                        type="button"
                        aria-label={`Move row ${rowIndex + 1} down`}
                        onClick={() => moveRow(rowIndex, 1)}
                        disabled={rowIndex === table.rules.length - 1}
                        className="rounded px-1 text-xs text-muted-foreground hover:bg-muted disabled:opacity-30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
                      >
                        ↓
                      </button>
                      <button
                        type="button"
                        aria-label={`Remove row ${rowIndex + 1}`}
                        onClick={() => removeRow(rowIndex)}
                        className="rounded px-1 text-xs text-muted-foreground hover:bg-muted hover:text-red-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
                      >
                        ✕
                      </button>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="mt-3 flex items-center gap-3">
        <button
          type="button"
          onClick={addRow}
          className="rounded-lg border border-border bg-card px-3.5 py-2 text-[13px] font-semibold hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          ＋ Add row
        </button>
        <span className="text-[12.5px] text-muted-foreground">
          Move rows with ↑ ↓. A row with every check left blank is the catch-all — keep it last.
        </span>
      </div>

      <div className="mt-5 grid gap-3.5 lg:grid-cols-2">
        <section className="rounded-xl border border-border bg-card p-4">
          <h2 className="mb-3 text-[10.5px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
            Test with values
          </h2>
          <div className="mb-3 grid gap-2.5 sm:grid-cols-2">
            {table.inputs.map((c) => (
              <label key={c.id} className="block">
                <span className="mb-1 block text-[11.5px] text-muted-foreground">
                  {c.field || c.name}
                </span>
                <input
                  className={cellClass}
                  value={testValues[c.field] ?? ""}
                  onChange={(e) => setTestValues((v) => ({ ...v, [c.field]: e.target.value }))}
                />
              </label>
            ))}
          </div>
          {result.rowIndex === null ? (
            <p className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-[12.5px] text-amber-800">
              No row fits these values, so this table would return nothing.
            </p>
          ) : (
            <p className="rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-[12.5px] text-emerald-800">
              <b>Row {result.rowIndex + 1} fits.</b>{" "}
              {Object.entries(result.outputs)
                .map(([k, v]) => `${k} = ${v || "(empty)"}`)
                .join(", ")}
              .
            </p>
          )}
        </section>

        <section className="rounded-xl border border-border bg-card p-4">
          <h2 className="mb-3 text-[10.5px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
            Coverage check
          </h2>
          {coverage.map((note) => (
            <p
              key={note.message}
              className={cn(
                "mb-2 rounded-lg border px-3 py-2 text-[12.5px] last:mb-0",
                note.level === "ok"
                  ? "border-emerald-200 bg-emerald-50 text-emerald-800"
                  : "border-amber-200 bg-amber-50 text-amber-800"
              )}
            >
              {note.message}
            </p>
          ))}

          {usedBy.length > 0 ? (
            <>
              <h2 className="mb-2 mt-4 text-[10.5px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
                Where this is used
              </h2>
              {usedBy.map((u) => (
                <p key={`${u.name}-${u.where}`} className="text-[12.5px] leading-relaxed">
                  <span className="font-semibold text-primary">{u.name}</span>{" "}
                  <span className="text-muted-foreground">— {u.where}</span>
                </p>
              ))}
              <p className="mt-2 text-[11.5px] text-muted-foreground">
                Publishing a change affects all of them immediately.
              </p>
            </>
          ) : null}
        </section>
      </div>
    </div>
  );
}

/**
 * The right-hand panel: how a step is set up, and what it actually did.
 *
 * Putting the last run's input and output directly under the fields that
 * produced them is the one idea worth taking from a canvas-style editor. The
 * question an author has while configuring a step is almost always "did that
 * do what I meant", and answering it in the same panel removes a trip to a
 * separate run view — along with the guessing that happens on the way back.
 */

import { useMemo } from "react";
import {
  type AutomationStep,
  type AvailableValue,
  type Condition,
  LOOP_MIN_PASSES,
  type Loop,
  OPERATORS,
  operatorArity,
  STEP_FIELDS,
  STEP_GLYPHS,
  STEP_HINTS,
  STEP_LABELS,
} from "@/lib/automation/model";
import { cn } from "@/lib/utils";

/* -------------------------------------------------------------------------- */
/*  Run output                                                                 */
/* -------------------------------------------------------------------------- */

export interface StepRunResult {
  status: "ok" | "failed" | "skipped";
  durationMs?: number;
  input?: Record<string, unknown>;
  output?: Record<string, unknown>;
  /** Plain-words summary of why the step produced what it did. */
  note?: string;
  error?: string;
  /** True when the step was edited after this run, so the result is out of date. */
  stale?: boolean;
}

function ValueRows({ values }: { values: Record<string, unknown> }) {
  const entries = Object.entries(values);
  if (entries.length === 0) {
    return <div className="px-3 py-1.5 text-xs text-muted-foreground">Nothing</div>;
  }
  return (
    <>
      {entries.map(([k, v]) => (
        <div
          key={k}
          className="flex gap-3 border-t border-border/60 px-3 py-1.5 text-xs first:border-t-0"
        >
          <span className="font-mono text-[11px] text-muted-foreground">{k}</span>
          <span className="ml-auto font-semibold tabular-nums">{formatValue(v)}</span>
        </div>
      ))}
    </>
  );
}

function formatValue(v: unknown): string {
  if (typeof v === "string") return `"${v}"`;
  if (v === null || v === undefined) return "—";
  return String(v);
}

function RunOutput({
  result,
  resultName,
  onRerun,
}: {
  result: StepRunResult;
  resultName: string;
  onRerun?: () => void;
}) {
  return (
    <section className="-mx-4 mt-1 border-t border-border bg-muted/40 px-4 py-4">
      <div className="mb-3 flex items-center gap-2">
        <span
          aria-hidden="true"
          className={cn(
            "grid h-[22px] w-[22px] place-items-center rounded-md border text-[11px]",
            result.status === "ok"
              ? "border-primary/30 bg-primary/10 text-primary"
              : result.status === "failed"
                ? "border-red-200 bg-red-50 text-red-600"
                : "border-border bg-muted text-muted-foreground"
          )}
        >
          {result.status === "ok" ? "✓" : result.status === "failed" ? "!" : "–"}
        </span>
        <h4 className="text-[10.5px] font-bold uppercase tracking-[0.09em] text-muted-foreground">
          What this step did
        </h4>
        <span className="ml-auto text-[11px] text-muted-foreground">
          last test run
          {typeof result.durationMs === "number" ? ` · ${result.durationMs} ms` : ""}
        </span>
      </div>

      {result.status === "failed" && result.error ? (
        <p className="mb-2 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">
          {result.error}
        </p>
      ) : null}

      {result.input ? (
        <div className="mb-2 overflow-hidden rounded-lg border border-border bg-card">
          <div className="border-b border-border bg-muted/50 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
            Went in
          </div>
          <ValueRows values={result.input} />
        </div>
      ) : null}

      {result.note ? (
        <p className="mb-2 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs text-emerald-800">
          {result.note}
        </p>
      ) : null}

      {result.output ? (
        <div className="mb-2 overflow-hidden rounded-lg border border-border bg-card">
          <div className="flex border-b border-border bg-muted/50 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
            Came out
            {resultName ? <span className="ml-auto text-primary">as {resultName}</span> : null}
          </div>
          <ValueRows values={result.output} />
        </div>
      ) : null}

      {onRerun ? (
        <button
          type="button"
          onClick={onRerun}
          className="w-full rounded-lg border border-border bg-card py-2 text-xs font-semibold hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        >
          Run this step again
        </button>
      ) : null}

      {result.stale ? (
        <p className="mt-2 flex gap-1.5 text-[11.5px] leading-snug text-amber-700">
          <span aria-hidden="true">⚠</span>
          <span>You changed this step since that run. Re-run to see what it does now.</span>
        </p>
      ) : null}
    </section>
  );
}

/* -------------------------------------------------------------------------- */
/*  Field primitives                                                           */
/* -------------------------------------------------------------------------- */

function Field({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: React.ReactNode;
  children: React.ReactNode;
}) {
  // A real <label> wrapping the control, not a styled <span> beside it: without
  // it the selects announce as "combobox" with no name at all, which is the
  // difference between a usable panel and an unusable one on a screen reader.
  return (
    <label className="mb-3.5 block">
      <span className="mb-1.5 block text-[11px] font-semibold uppercase tracking-[0.06em] text-muted-foreground">
        {label}
      </span>
      {children}
      {hint ? (
        <p className="mt-1.5 text-[11.5px] leading-snug text-muted-foreground">{hint}</p>
      ) : null}
    </label>
  );
}

const inputClass =
  "w-full rounded-lg border border-input bg-card px-3 py-2 text-sm focus-visible:outline-none focus-visible:border-primary focus-visible:ring-[3px] focus-visible:ring-primary/10";

export function Ref({ children }: { children: React.ReactNode }) {
  return (
    <code className="rounded border border-border bg-muted px-1 py-0.5 font-mono text-[11px] text-primary">
      {children}
    </code>
  );
}

/* -------------------------------------------------------------------------- */
/*  Step inspector                                                             */
/* -------------------------------------------------------------------------- */

interface StepInspectorProps {
  step: AutomationStep;
  index: number;
  available: AvailableValue[];
  ruleTables: { id: string; name: string; rowCount: number; outputs: string[] }[];
  entities: string[];
  fieldsFor: (entity: string) => string[];
  run?: StepRunResult;
  onChange: (next: AutomationStep) => void;
  onRerun?: () => void;
  onOpenRuleTable?: (name: string) => void;
}

export function StepInspector({
  step,
  index,
  available,
  ruleTables,
  entities,
  fieldsFor,
  run,
  onChange,
  onRerun,
  onOpenRuleTable,
}: StepInspectorProps) {
  const setProp = (key: string, value: string) =>
    onChange({ ...step, props: { ...step.props, [key]: value } });

  const table = useMemo(
    () => ruleTables.find((t) => t.name === step.props.ruleTable),
    [ruleTables, step.props.ruleTable]
  );

  const fields = STEP_FIELDS[step.type] ?? [];

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 px-4 py-3.5">
        <span
          aria-hidden="true"
          className="grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border border-primary/30 bg-primary/10 text-sm text-primary"
        >
          {STEP_GLYPHS[step.type]}
        </span>
        <div>
          <span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-primary">
            Step {index + 1} · Then do this
          </span>
          <h3 className="text-[15px] font-bold">{STEP_LABELS[step.type]}</h3>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4">
        <p className="mb-4 text-xs leading-snug text-muted-foreground">{STEP_HINTS[step.type]}</p>

        {/* One list per step, not per field: every input that offers references
            points at this id, and emitting it only under some fields left the
            others with an autocomplete that quietly did nothing. */}
        <datalist id={`vals-${step.id}`}>
          {available.map((v) => (
            <option key={v.path} value={`{{${v.path}}}`} />
          ))}
        </datalist>

        {fields.includes("ruleTable") ? (
          <Field
            label="Rule table"
            hint={
              table ? (
                <>
                  {table.rowCount} rows · decides{" "}
                  {table.outputs.map((o, i) => (
                    <span key={o}>
                      {i > 0 ? " and " : ""}
                      <Ref>{o}</Ref>
                    </span>
                  ))}
                  .{" "}
                  {onOpenRuleTable ? (
                    <button
                      type="button"
                      onClick={() => onOpenRuleTable(table.name)}
                      className="font-semibold text-primary hover:underline"
                    >
                      Open table →
                    </button>
                  ) : null}
                </>
              ) : (
                "Pick the table this step should ask."
              )
            }
          >
            <select
              className={inputClass}
              value={step.props.ruleTable ?? ""}
              onChange={(e) => setProp("ruleTable", e.target.value)}
            >
              <option value="">Choose a rule table…</option>
              {ruleTables.map((t) => (
                <option key={t.id} value={t.name}>
                  {t.name}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("entity") ? (
          <Field label="Record type">
            <select
              className={inputClass}
              value={step.props.entity ?? ""}
              onChange={(e) => setProp("entity", e.target.value)}
            >
              <option value="">Choose a record type…</option>
              {entities.map((e) => (
                <option key={e} value={e}>
                  {e}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("values") ? (
          <Field
            label="Columns to set"
            hint={
              <>
                One <code className="font-mono text-[11px]">column: value</code> per line. A value
                can be a reference to an earlier step, like <Ref>{"{{tier.discount_pct}}"}</Ref>.
              </>
            }
          >
            <textarea
              className={cn(inputClass, "min-h-[76px] font-mono text-xs")}
              value={step.props.values ?? ""}
              onChange={(e) => setProp("values", e.target.value)}
              placeholder={"status: open\nraised_by: {{order.id}}"}
            />
          </Field>
        ) : null}

        {fields.includes("target") ? (
          <Field
            label="Which record"
            hint={
              <>
                The record to delete, usually a reference from an earlier step —{" "}
                <Ref>{"{{invoiceId}}"}</Ref>.
              </>
            }
          >
            <input
              className={inputClass}
              value={step.props.target ?? ""}
              onChange={(e) => setProp("target", e.target.value)}
              list={`vals-${step.id}`}
            />
          </Field>
        ) : null}

        {fields.includes("field") ? (
          <Field label="Field to write">
            <select
              className={inputClass}
              value={step.props.field ?? ""}
              onChange={(e) => setProp("field", e.target.value)}
            >
              <option value="">Choose a field…</option>
              {fieldsFor(step.props.entity ?? "").map((f) => (
                <option key={f} value={f}>
                  {f}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("value") ? (
          <Field
            label="New value"
            hint={
              <>
                A fixed value, or a reference to an earlier step like{" "}
                <Ref>{"{{tier.discount_pct}}"}</Ref>.
              </>
            }
          >
            <input
              className={inputClass}
              value={step.props.value ?? ""}
              onChange={(e) => setProp("value", e.target.value)}
              list={`vals-${step.id}`}
              placeholder="high"
            />
          </Field>
        ) : null}

        {fields.includes("operation") ? (
          <Field label="Operation">
            <select
              className={inputClass}
              value={step.props.operation ?? "set"}
              onChange={(e) => setProp("operation", e.target.value)}
            >
              {["set", "copy", "add", "subtract", "multiply", "divide"].map((op) => (
                <option key={op} value={op}>
                  {op}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("left") ? (
          <Field label="Value to work from">
            <input
              className={inputClass}
              value={step.props.left ?? ""}
              onChange={(e) => setProp("left", e.target.value)}
              list={`vals-${step.id}`}
            />
          </Field>
        ) : null}

        {fields.includes("right") ? (
          <Field label="And this value" hint="Leave empty when the operation only needs one value.">
            <input
              className={inputClass}
              value={step.props.right ?? ""}
              onChange={(e) => setProp("right", e.target.value)}
              list={`vals-${step.id}`}
            />
          </Field>
        ) : null}

        {fields.includes("method") ? (
          <Field label="Method">
            <select
              className={inputClass}
              value={step.props.method ?? "POST"}
              onChange={(e) => setProp("method", e.target.value)}
            >
              {["POST", "PUT", "PATCH", "GET", "DELETE"].map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </Field>
        ) : null}

        {fields.includes("url") ? (
          <Field label="URL">
            <input
              className={inputClass}
              value={step.props.url ?? ""}
              onChange={(e) => setProp("url", e.target.value)}
              placeholder="https://example.com/hooks/orders"
            />
          </Field>
        ) : null}

        {fields.includes("body") ? (
          <Field
            label="Body"
            hint={
              <>
                JSON. References like <Ref>{"{{order.id}}"}</Ref> are filled in before sending.
              </>
            }
          >
            <textarea
              className={cn(inputClass, "min-h-[76px] font-mono text-xs")}
              value={step.props.body ?? ""}
              onChange={(e) => setProp("body", e.target.value)}
            />
          </Field>
        ) : null}

        <Field
          label="Save the answer as"
          hint={
            step.resultName ? (
              <>
                Later steps can use <Ref>{`{{${step.resultName}}}`}</Ref>.
              </>
            ) : (
              "Leave empty if no later step needs this step's result."
            )
          }
        >
          <input
            className={inputClass}
            value={step.resultName}
            onChange={(e) => onChange({ ...step, resultName: e.target.value })}
            placeholder="tier"
          />
        </Field>

        {run ? <RunOutput result={run} resultName={step.resultName} onRerun={onRerun} /> : null}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*  Condition inspector                                                        */
/* -------------------------------------------------------------------------- */

export function ConditionInspector({
  condition,
  available,
  onChange,
}: {
  condition: Condition;
  available: AvailableValue[];
  onChange: (next: Condition) => void;
}) {
  const needsValue = operatorArity(condition.operator) === 1;

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 px-4 py-3.5">
        <span
          aria-hidden="true"
          className="grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border border-blue-200 bg-blue-50 text-sm text-blue-600"
        >
          ◇
        </span>
        <div>
          <span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-blue-600">
            Only continue if
          </span>
          <h3 className="text-[15px] font-bold">A check</h3>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4">
        <p className="mb-4 text-xs leading-snug text-muted-foreground">
          Every check must pass. To run on either of two cases, build two automations — each one
          then reports its own run history.
        </p>

        <Field label="Field to look at">
          <select
            className={inputClass}
            value={condition.field}
            onChange={(e) => onChange({ ...condition, field: e.target.value })}
          >
            <option value="">Choose a field…</option>
            {available.map((v) => (
              <option key={v.path} value={v.path}>
                {v.path}
              </option>
            ))}
          </select>
        </Field>

        <Field label="Test">
          <select
            className={inputClass}
            value={condition.operator}
            onChange={(e) => onChange({ ...condition, operator: e.target.value })}
          >
            {OPERATORS.map((op) => (
              <option key={op.id} value={op.id}>
                {op.label}
              </option>
            ))}
          </select>
        </Field>

        {needsValue ? (
          <Field label="Value" hint="A fixed value, or another field to compare against.">
            <input
              className={inputClass}
              value={condition.value}
              onChange={(e) => onChange({ ...condition, value: e.target.value })}
              placeholder="1000"
            />
          </Field>
        ) : null}
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/*  Loop inspector                                                             */
/* -------------------------------------------------------------------------- */

/**
 * The panel for a repeat.
 *
 * It edits one thing — the check that ends the loop — so most of the panel is
 * spent explaining the consequences instead. A repeat is the only construct in
 * the builder that can hang a request, and the place to say so is where someone
 * is deciding what to check, not in help they would have to go looking for.
 */
export function LoopInspector({
  loop,
  stepCount,
  available,
  onChange,
}: {
  loop: Loop;
  stepCount: number;
  available: AvailableValue[];
  onChange: (next: Loop) => void;
}) {
  const needsValue = operatorArity(loop.condition.operator) === 1;
  const set = (patch: Partial<Condition>) =>
    onChange({ ...loop, condition: { ...loop.condition, ...patch } });

  return (
    <div className="flex h-full flex-col">
      <header className="flex items-center gap-3 px-4 py-3.5">
        <span
          aria-hidden="true"
          className="grid h-[30px] w-[30px] shrink-0 place-items-center rounded-lg border border-teal-200 bg-teal-50 text-sm text-teal-700"
        >
          ↻
        </span>
        <div>
          <span className="block text-[10px] font-bold uppercase tracking-[0.1em] text-teal-700">
            Keep repeating
          </span>
          <h3 className="text-[15px] font-bold">A repeat</h3>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4">
        <p className="mb-4 text-xs leading-snug text-muted-foreground">
          The {stepCount === 1 ? "step" : `${stepCount} steps`} inside run over and over while this
          check passes. It is re-checked before every pass, so something inside the repeat has to
          change what it looks at — otherwise it never stops.
        </p>

        <Field label="Field to look at">
          <select
            className={inputClass}
            value={loop.condition.field}
            onChange={(e) => set({ field: e.target.value })}
          >
            <option value="">Choose a field…</option>
            {available.map((v) => (
              <option key={v.path} value={v.path}>
                {v.path}
              </option>
            ))}
          </select>
        </Field>

        <Field label="Keep going while">
          <select
            className={inputClass}
            value={loop.condition.operator}
            onChange={(e) => set({ operator: e.target.value })}
          >
            {OPERATORS.map((op) => (
              <option key={op.id} value={op.id}>
                {op.label}
              </option>
            ))}
          </select>
        </Field>

        {needsValue ? (
          <Field label="Value" hint="A fixed value, or another field to compare against.">
            <input
              className={inputClass}
              value={loop.condition.value}
              onChange={(e) => set({ value: e.target.value })}
              placeholder="5"
            />
          </Field>
        ) : null}

        <Field
          label="Give up after (required)"
          hint="How many passes is obviously too many for this loop? There is no default — only you know what this work should cost."
        >
          <input
            className={inputClass}
            inputMode="numeric"
            value={loop.maxPasses}
            onChange={(e) => onChange({ ...loop, maxPasses: e.target.value })}
            placeholder="e.g. 10"
            aria-invalid={!loop.maxPasses.trim() || Number(loop.maxPasses) < LOOP_MIN_PASSES}
          />
        </Field>

        <div className="mb-4 rounded-lg border border-teal-200 bg-teal-50/60 p-3">
          <p className="text-[11.5px] font-semibold text-teal-800">
            Inside the repeat you can use {`{{${loop.id}.iteration}}`}
          </p>
          <p className="mt-1 text-[11.5px] leading-snug text-teal-800/80">
            The pass number, counting from 1. Handy for writing an attempt count, or for building a
            value that changes each time round.
          </p>
        </div>

        <div className="mb-4 rounded-lg border border-amber-200 bg-amber-50/60 p-3">
          <p className="text-[11.5px] font-semibold text-amber-900">
            If the check never fails, the run is stopped at{" "}
            {loop.maxPasses.trim() ? `${loop.maxPasses} passes` : "the limit you set"}
          </p>
          <p className="mt-1 text-[11.5px] leading-snug text-amber-900/80">
            An automation runs inside the save that triggered it, so a repeat that cannot end holds
            the record open. Hitting the limit marks the whole run failed rather than letting it
            look like it finished.
          </p>
        </div>
      </div>
    </div>
  );
}

