interface DynamicFormProps {
  tableName: string;
  fields?: FieldMetadata[];
  initialData?: Record<string, unknown>;
  onSubmit?: (data: Record<string, unknown>) => void | Promise<void>;
  /** Called whenever any field value changes — useful for parent to track dirty state */
  onChange?: (data: Record<string, unknown>) => void;
  isLoading?: boolean;
  isSaving?: boolean;
  mode?: "create" | "edit" | "view";
  readOnly?: boolean;
  serverErrors?: Record<string, string>;
  parentField?: string;
  readOnlyFields?: string[];
  /** Data from the immediate parent record — used to filter lookup dropdowns (e.g. filter columns by parent tab's sys_table_id) */
  parentContext?: Record<string, unknown>;
  /**
   * `id` of the rendered `<form>`, so a control outside it — a toolbar Save —
   * can submit it with `requestSubmit()` and go through the same validation and
   * normalisation as the form's own button.
   */
  formId?: string;
}

const REFERENCE_TYPE = {
  STRING: 10,
  INTEGER: 11,
  AMOUNT: 12,
  ID: 13,
  TEXT: 14,
  DATE: 15,
  DATETIME: 16,
  LIST: 17,
  TABLE: 18,
  TABLE_DIRECT: 19,
  YES_NO: 20,
  URL: 24,
  EMAIL: 30,
  PHONE: 31,
  PASSWORD: 29,
};

type FormValues = Record<string, unknown>;

/**
 * Fill in every Yes/No field the user never touched with `false`.
 *
 * TanStack Form only records a field once it changes, so a checkbox left alone
 * is missing from the value map rather than present and false. The dictionary
 * marks these columns NOT NULL, so the backend is right to reject the absence —
 * the form is what was lying about the answer.
 */
function applyBooleanDefaults(
  value: Record<string, unknown>,
  fields: FieldMetadata[] | undefined
): void {
  if (!fields) return;
  for (const field of fields) {
    if (field.sys_reference_id !== REFERENCE_TYPE.YES_NO) continue;
    const current = value[field.column_name];
    if (current === undefined || current === null || current === "") {
      value[field.column_name] = false;
    }
  }
}

function getFieldIcon(sysReferenceId: number) {
  switch (sysReferenceId) {
    case REFERENCE_TYPE.STRING:
      return Type;
    case REFERENCE_TYPE.INTEGER:
      return Hash;
    case REFERENCE_TYPE.AMOUNT:
      return Hash;
    case REFERENCE_TYPE.EMAIL:
      return Mail;
    case REFERENCE_TYPE.URL:
      return Link2;
    case REFERENCE_TYPE.PHONE:
      return Phone;
    case REFERENCE_TYPE.DATE:
    case REFERENCE_TYPE.DATETIME:
      return Calendar;
    case REFERENCE_TYPE.YES_NO:
      return ToggleLeft;
    case REFERENCE_TYPE.TEXT:
      return FileText;
    case REFERENCE_TYPE.PASSWORD:
      return KeyRound;
    case REFERENCE_TYPE.TABLE:
    case REFERENCE_TYPE.TABLE_DIRECT:
      return Table2;
    default:
      return sysReferenceId >= 1000 ? List : Type;
  }
}

/**
 * A lookup's label on the read-only detail view.
 *
 * Two sources, the same two the editable picker uses: a custom endpoint
 * (`/sys/references` and friends) or an ordinary business table named by
 * `ref_table_name`. Only the custom one was fetched here, so every lookup at a
 * business table fell through to `label = id` and the detail view rendered a
 * raw UUID — `Compound Id  9980b173-201c-…` where the grid two clicks away
 * showed the compound's SMILES. The grid was right because it reads
 * `ref_label_fields`; this read the singular `ref_label_field` and defaulted to
 * "name", which most entities do not have.
 */
function TableReferenceViewValue({ field, id }: { field: FieldMetadata; id: string }) {
  const customEndpoint = field.ref_endpoint || null;
  const referencedTableName = field.ref_table_name || null;
  const idField = field.ref_id_field || "id";

  const { data } = useQuery({
    queryKey: ["table-ref-view", customEndpoint, id],
    // `enabled` below guarantees a value here, but the callback's type cannot
    // know that; the guard says it instead of asserting it.
    queryFn: () =>
      customEndpoint
        ? apiClient.get<{ data: any[] }>(customEndpoint, { limit: 500 })
        : Promise.resolve({ data: [] }),
    enabled: !!customEndpoint && !!id,
  });

  // The one record, by id. This used to read the first page of the referenced
  // table (25 rows) and look for the record in it, so a city past the first
  // page showed as a raw id.
  const { data: one } = useEntity<any>(referencedTableName || "", id, {
    enabled: !!referencedTableName && !customEndpoint && !!id,
  });

  const records: any[] = customEndpoint ? ((data as any)?.data ?? []) : one ? [one] : [];
  const record = records.find((r: any) => String(r[idField]) === String(id));

  // Same precedence as the grid: the dictionary's list first, then the single
  // field, then "name". Kept in step with `dynamic-table.tsx` — a lookup that
  // reads one way in a list and another on the record it opens is worse than
  // either being wrong on its own.
  const labelFields: string[] = (field as any).ref_label_fields?.length
    ? (field as any).ref_label_fields
    : field.ref_label_field
      ? [field.ref_label_field]
      : ["name"];

  // Falls back to the id while the fetch is in flight, which is what it showed
  // before and is still better than an empty cell.
  const label = record ? referenceLabel(record, labelFields, id) : id;
  return <span>{label}</span>;
}

interface TableReferenceFieldProps {
  field: FieldMetadata;
  fieldApi: any;
  isDisabled: boolean;
  error: string | undefined;
  parentContext?: Record<string, unknown>;
  /** The entity the form edits, which the lookup endpoint is addressed by. */
  entityName: string;
  form: any;
}

function TableReferenceField({
  field,
  fieldApi,
  isDisabled,
  error,
  parentContext,
  entityName,
  form,
}: TableReferenceFieldProps) {
  const referencedTableName = field.ref_table_name || null;
  const idField = field.ref_id_field || "id";

  // The columns of this record that narrow the choices: a state is offered only
  // from the country already chosen, a city from its state. Their current values
  // go to the lookup endpoint, which does the narrowing — the list that comes
  // back is already the right one.
  const narrowedBy: string[] = (field as any).narrowed_by ?? [];
  const formValues = form.useStore((state: any) => state.values) as Record<string, unknown>;
  const controlValues: Record<string, string> = {};
  for (const control of narrowedBy) {
    const value = formValues?.[control];
    if (value !== undefined && value !== null && value !== "") controlValues[control] = String(value);
  }

  // Resolve filtered endpoint: append ref_filter_param=<parentContext[ref_filter_source]> when configured
  const filterValue =
    field.ref_filter_source && parentContext ? parentContext[field.ref_filter_source] : undefined;
  const customEndpoint = field.ref_endpoint
    ? field.ref_filter_param && filterValue != null
      ? `${field.ref_endpoint}?${field.ref_filter_param}=${encodeURIComponent(String(filterValue))}`
      : field.ref_endpoint
    : null;

  // Custom endpoint (e.g. /sys/references) — use apiClient directly
  const { data: customData, isLoading: isLoadingCustom } = useQuery({
    queryKey: ["table-ref-custom", customEndpoint],
    queryFn: () =>
      customEndpoint
        ? apiClient.get<{ data: any[] }>(customEndpoint, { limit: 500 })
        : Promise.resolve({ data: [] }),
    enabled: !!customEndpoint,
  });

  // A business table: the lookup endpoint returns every choice (a dropdown is
  // not paged, and a list page of 25 offered a fraction of them), narrowed by
  // the dictionary's rule for this column.
  const { data: records, isLoading: isLoadingRecords } = useQuery({
    queryKey: ["lookup", entityName, field.column_name, controlValues],
    queryFn: () =>
      apiClient.get<{ data: any[] }>(
        `/bus/${entityName}/lookup/${field.column_name}`,
        controlValues
      ),
    enabled: !!referencedTableName && !customEndpoint,
  });

  const isLoading = isLoadingCustom || isLoadingRecords;
  const tableRecords: any[] = customEndpoint
    ? ((customData as any)?.data ?? [])
    : ((records as any)?.data ?? []);

  // What a choice is called: the dictionary's identifier columns, joined — the
  // code and the name where an entity has both ("US · United States").
  const labelFields: string[] = (field as any).ref_label_fields?.length
    ? (field as any).ref_label_fields
    : field.ref_label_field
      ? [field.ref_label_field]
      : ["name"];

  // When a control changes, a choice that no longer belongs to it is cleared
  // rather than left selected: change the country and the state chosen for the
  // old one would otherwise stay on the record, and the server would refuse it.
  const currentChoice = fieldApi.state.value;
  const stillOffered = tableRecords.some((record) => String(record[idField]) === String(currentChoice));
  useEffect(() => {
    if (
      narrowedBy.length > 0 &&
      !isLoading &&
      currentChoice !== undefined &&
      currentChoice !== null &&
      currentChoice !== "" &&
      !stillOffered
    ) {
      fieldApi.handleChange("");
    }
  }, [narrowedBy.length, isLoading, currentChoice, stillOffered, fieldApi]);

  if (!referencedTableName && !customEndpoint) {
    return (
      <Input
        id={field.column_name}
        name={field.column_name}
        value={(fieldApi.state.value as string) || ""}
        onChange={(e) => fieldApi.handleChange(e.target.value)}
        onBlur={fieldApi.handleBlur}
        disabled={isDisabled}
        className={cn(error && "border-destructive")}
      />
    );
  }

  const currentValue = fieldApi.state.value;

  return isLoading ? (
    <Skeleton className="h-10 w-full" />
  ) : (
    <select
      id={field.column_name}
      name={field.column_name}
      value={currentValue !== undefined && currentValue !== null ? String(currentValue) : ""}
      onChange={(e) => {
        const raw = e.target.value;
        // Preserve numeric IDs for sys_reference_id etc.
        const parsed = raw !== "" && !Number.isNaN(Number(raw)) ? Number(raw) : raw;
        fieldApi.handleChange(parsed || raw);
      }}
      onBlur={fieldApi.handleBlur}
      disabled={isDisabled}
      className={cn(
        "flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50",
        error && "border-destructive"
      )}
    >
      <option value="">Select {field.name}...</option>
      {tableRecords.map((record: any) => {
        const optValue = record[idField];
        const optLabel = referenceLabel(record, labelFields, String(optValue));
        return (
          <option key={String(optValue)} value={String(optValue)}>
            {optLabel}
          </option>
        );
      })}
    </select>
  );
}

function FieldTypeBadge({ field }: { field: FieldMetadata }) {
  const Icon = getFieldIcon(field.sys_reference_id);
  const typeLabel = getFieldTypeLabel(field.sys_reference_id);
  const colorClass = getFieldTypeColor(field.sys_reference_id);

  return (
    <span
      className={cn(
        "inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-medium",
        colorClass
      )}
    >
      <Icon className="h-3 w-3" />
      {typeLabel}
    </span>
  );
}

function FieldHelpPopover({ help, fieldName }: { help: string; fieldName: string }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="relative inline-block">
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="inline-flex items-center justify-center w-4 h-4 rounded-full bg-muted text-muted-foreground hover:bg-primary/10 hover:text-primary transition-colors"
        aria-label={`Help for ${fieldName}`}
      >
        <HelpCircle size={14} />
      </button>
      {open && (
        <>
          <button
            type="button"
            aria-label="Dismiss help"
            className="fixed inset-0 z-40"
            onClick={() => setOpen(false)}
          />
          <Box radius="lg" padding={3} border="default" className="absolute left-0 top-5 z-50 w-64 bg-popover shadow-lg text-popover-foreground">
            <HStack align="start" gap={2}>
              <HelpCircle className="w-4 h-4 text-primary mt-0.5 flex-shrink-0" />
              <Text size="xs" block className="leading-relaxed whitespace-pre-wrap">{help}</Text>
            </HStack>
          </Box>
        </>
      )}
    </div>
  );
}

function FieldConstraints({ field, charCount }: { field: FieldMetadata; charCount?: number }) {
  const hints: string[] = [];
  if (field.field_length && field.sys_reference_id !== REFERENCE_TYPE.YES_NO) {
    hints.push(`max ${field.field_length}`);
  }
  if (field.sys_reference_id === REFERENCE_TYPE.PASSWORD) {
    hints.push("min 6");
  }

  if (hints.length === 0 && charCount === undefined) return null;

  return (
    <HStack align="center" justify="between" className="mt-1">
      {hints.length > 0 && (
        <Text color="secondary" className="text-[10px]">{hints.join(" · ")}</Text>
      )}
      {charCount !== undefined && field.field_length && (
        <span
          className={cn(
            "text-[10px] font-mono",
            charCount > field.field_length
              ? "text-destructive font-semibold"
              : charCount > field.field_length * 0.8
                ? "text-amber-500"
                : "text-muted-foreground"
          )}
        >
          {charCount}/{field.field_length}
        </span>
      )}
    </HStack>
  );
}

interface FieldRendererProps {
  field: FieldMetadata;
  form: ReturnType<typeof useForm<FormValues>>;
  serverErrors?: Record<string, string>;
  zodErrors?: Record<string, string>;
  tableName: string;
  readOnlyFields?: string[];
  parentContext?: Record<string, unknown>;
}

function FieldRenderer({
  field,
  form,
  serverErrors = {},
  zodErrors = {},
  tableName,
  readOnlyFields = [],
  parentContext,
}: FieldRendererProps) {
  const isFormReadOnly = (form as any).readOnly || false;
  const formMode = (form as any).mode || "edit";
  const fieldLabel = getFieldLabel(tableName, (field as any).tab_name, field.name, field.name);
  const isDisabled =
    (field.is_read_only && formMode !== "create") || readOnlyFields.includes(field.column_name);
  const isReadOnly = isDisabled || isFormReadOnly;

  const { data: refListValues, isLoading: isLoadingRefList } = useRefList(
    field.sys_reference_id >= 1000 ? field.sys_reference_id : 0
  );

  return (
    <form.Field
      name={field.column_name}
      validators={{
        onChange: ({ value }: { value: unknown }) => {
          // `false` is an answer, not a blank. Testing falsiness made every
          // mandatory Yes/No field report "is required" the moment it was
          // unticked, which is the one state a checkbox spends most of its
          // life in.
          const isBlank =
            typeof value === "boolean" ? false : value === undefined || value === null || value === "";
          if (field.is_mandatory && isBlank) return `${fieldLabel} is required`;
          if (
            field.field_length &&
            typeof value === "string" &&
            value.length > field.field_length
          ) {
            return `${fieldLabel} must be at most ${field.field_length} characters`;
          }
          return undefined;
        },
      }}
    >
      {(fieldApi: any) => {
        const clientError = fieldApi.state.meta.errors?.[0] as string | undefined;
        const serverError = serverErrors?.[field.column_name];
        const zodError = zodErrors?.[field.column_name];
        const error = clientError || serverError || zodError;
        const currentValue = fieldApi.state.value;
        const charCount = typeof currentValue === "string" ? currentValue.length : undefined;

        const labelBlock = (
          <HStack align="center" gap={2} className="mb-1.5">
            <Label
              htmlFor={field.column_name}
              className={cn("text-sm font-medium", error && "text-destructive")}
            >
              {fieldLabel}
              {field.is_mandatory && <Text color="danger" className="ml-0.5">*</Text>}
            </Label>
            <FieldTypeBadge field={field} />
            {isDisabled && (
              <Text color="secondary" className="inline-flex items-center gap-0.5 rounded-full bg-muted px-1.5 py-0.5 text-[10px]">
                <Lock size={10} /> Read-only
              </Text>
            )}
            {field.help && <FieldHelpPopover help={field.help} fieldName={fieldLabel} />}
          </HStack>
        );

        const errorBlock = error && (
          <HStack align="center" gap={1} className="mt-1.5 text-destructive">
            <AlertCircle size={14} />
            <Text size="xs" block>{error}</Text>
          </HStack>
        );

        const inputStyles = cn(
          error && "border-destructive ring-destructive/20",
          isDisabled && "bg-muted/50 cursor-not-allowed",
          field.is_mandatory && !error && "border-primary/30"
        );

        // ── VIEW MODE: render clean plain text, no inputs ──────────────
        const isRefField = field.sys_reference_id === 18 || field.sys_reference_id === 19;
        if (formMode === "view") {
          // TABLE/TABLE_DIRECT refs: show label lookup or "—"
          if (isRefField) {
            return (
              <div>
                <HStack align="center" gap={1.5} className="mb-0.5">
                  <Text size="xs" weight="medium" color="secondary">{fieldLabel}</Text>
                  {field.is_mandatory && <Text size="xs" className="text-red-400">*</Text>}
                  {field.help && <FieldHelpPopover help={field.help} fieldName={fieldLabel} />}
                </HStack>
                <div className="text-sm text-foreground font-medium min-h-[1.25rem]">
                  {!currentValue || currentValue === "" ? (
                    <span className="text-muted-foreground/60 italic">—</span>
                  ) : (
                    <TableReferenceViewValue field={field} id={String(currentValue)} />
                  )}
                </div>
              </div>
            );
          }

          const displayValue = (() => {
            if (currentValue === null || currentValue === undefined || currentValue === "")
              return "—";
            if (typeof currentValue === "boolean") return currentValue ? "Yes" : "No";
            if (field.sys_reference_id === 15 || field.sys_reference_id === 16) {
              const d = new Date(String(currentValue));
              return Number.isNaN(d.getTime()) ? String(currentValue) : d.toLocaleString();
            }
            return String(currentValue);
          })();

          return (
            <div>
              <HStack align="center" gap={1.5} className="mb-0.5">
                <Text size="xs" weight="medium" color="secondary">{fieldLabel}</Text>
                {field.is_mandatory && <Text size="xs" className="text-red-400">*</Text>}
                {field.help && <FieldHelpPopover help={field.help} fieldName={fieldLabel} />}
              </HStack>
              <div className="text-sm text-foreground font-medium min-h-[1.25rem]">
                {displayValue}
              </div>
            </div>
          );
        }

        // Static options list (inline enum — no DB fetch required)
        if (field.options && field.options.length > 0) {
          return (
            <div>
              {labelBlock}
              <select
                id={field.column_name}
                name={field.column_name}
                value={(currentValue as string) || ""}
                onChange={(e) => fieldApi.handleChange(e.target.value)}
                onBlur={fieldApi.handleBlur}
                disabled={isReadOnly}
                className={cn(
                  "flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50",
                  inputStyles
                )}
              >
                <option value="">Select {fieldLabel}...</option>
                {field.options.map((opt) => (
                  <option key={opt.value} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
              {errorBlock}
            </div>
          );
        }

        // Reference list dropdown
        if (field.sys_reference_id >= 1000) {
          return (
            <div>
              {labelBlock}
              {isLoadingRefList ? (
                <Skeleton className="h-10 w-full" />
              ) : (
                <select
                  id={field.column_name}
                  name={field.column_name}
                  value={(currentValue as string) || ""}
                  onChange={(e) => fieldApi.handleChange(e.target.value)}
                  onBlur={fieldApi.handleBlur}
                  disabled={isReadOnly}
                  className={cn(
                    "flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50",
                    inputStyles
                  )}
                >
                  <option value="">Select {fieldLabel}...</option>
                  {refListValues?.map((refValue) => (
                    <option key={refValue.sys_ref_list_id} value={refValue.value}>
                      {refValue.name}
                    </option>
                  ))}
                </select>
              )}
              {errorBlock}
            </div>
          );
        }

        // Table or Table Direct reference
        if (
          field.sys_reference_id === REFERENCE_TYPE.TABLE ||
          field.sys_reference_id === REFERENCE_TYPE.TABLE_DIRECT
        ) {
          return (
            <div>
              {labelBlock}
              <TableReferenceField
                field={field}
                fieldApi={fieldApi}
                isDisabled={isReadOnly}
                error={error}
                parentContext={parentContext}
                entityName={tableName}
                form={form}
              />
              {errorBlock}
            </div>
          );
        }

        switch (field.sys_reference_id) {
          case REFERENCE_TYPE.TEXT:
            return (
              <div>
                {labelBlock}
                <Textarea
                  id={field.column_name}
                  name={field.column_name}
                  value={(currentValue as string) || ""}
                  onChange={(e) => fieldApi.handleChange(e.target.value)}
                  onBlur={fieldApi.handleBlur}
                  disabled={isReadOnly}
                  className={cn(inputStyles)}
                  rows={4}
                />
                <FieldConstraints field={field} charCount={charCount} />
                {errorBlock}
              </div>
            );

          case REFERENCE_TYPE.YES_NO:
            return (
              <HStack align="center" gap={3} className="pt-6">
                <Checkbox
                  id={field.column_name}
                  checked={(currentValue as boolean) || false}
                  onCheckedChange={(checked) => fieldApi.handleChange(checked)}
                  disabled={isReadOnly}
                  className={cn(field.is_mandatory && "border-primary/50")}
                />
                <HStack align="center" gap={2}>
                  <Label htmlFor={field.column_name} className="text-sm">
                    {fieldLabel}
                  </Label>
                  <FieldTypeBadge field={field} />
                </HStack>
              </HStack>
            );

          case REFERENCE_TYPE.DATE:
            return (
              <div>
                {labelBlock}
                <Input
                  id={field.column_name}
                  name={field.column_name}
                  type="date"
                  value={(currentValue as string)?.split("T")[0] || ""}
                  onChange={(e) => fieldApi.handleChange(e.target.value)}
                  onBlur={fieldApi.handleBlur}
                  disabled={isReadOnly}
                  className={cn(inputStyles)}
                />
                {errorBlock}
              </div>
            );

          case REFERENCE_TYPE.DATETIME:
            return (
              <div>
                {labelBlock}
                <Input
                  id={field.column_name}
                  name={field.column_name}
                  type="datetime-local"
                  value={(currentValue as string)?.slice(0, 16) || ""}
                  onChange={(e) => fieldApi.handleChange(e.target.value)}
                  onBlur={fieldApi.handleBlur}
                  disabled={isReadOnly}
                  className={cn(inputStyles)}
                />
                {errorBlock}
              </div>
            );

          case REFERENCE_TYPE.INTEGER:
          case REFERENCE_TYPE.AMOUNT:
            return (
              <div>
                {labelBlock}
                <Input
                  id={field.column_name}
                  name={field.column_name}
                  type="number"
                  step={field.sys_reference_id === REFERENCE_TYPE.AMOUNT ? 0.01 : 1}
                  value={(currentValue as number) ?? ""}
                  // `valueAsNumber || null` turned a legitimate 0 into null, so
                  // a required amount could not be set to zero and an optional
                  // one silently lost it. An empty input is NaN; that is the
                  // only value that means "cleared".
                  onChange={(e) =>
                    fieldApi.handleChange(
                      Number.isNaN(e.target.valueAsNumber) ? null : e.target.valueAsNumber
                    )
                  }
                  onBlur={fieldApi.handleBlur}
                  disabled={isReadOnly}
                  className={cn(inputStyles)}
                />
                {errorBlock}
              </div>
            );

          case REFERENCE_TYPE.EMAIL:
            return (
              <div>
                {labelBlock}
                <Input
                  id={field.column_name}
                  name={field.column_name}
                  type="email"
                  value={(currentValue as string) || ""}
                  onChange={(e) => fieldApi.handleChange(e.target.value)}
                  onBlur={fieldApi.handleBlur}
                  disabled={isReadOnly}
                  className={cn(inputStyles)}
                />
                <FieldConstraints field={field} charCount={charCount} />
                {errorBlock}
              </div>
            );

          case REFERENCE_TYPE.URL:
            return (
              <div>
                {labelBlock}
                <Input
                  id={field.column_name}
                  name={field.column_name}
                  type="url"
                  value={(currentValue as string) || ""}
                  onChange={(e) => fieldApi.handleChange(e.target.value)}
                  onBlur={fieldApi.handleBlur}
                  disabled={isReadOnly}
                  className={cn(inputStyles)}
                  placeholder="https://..."
                />
                <FieldConstraints field={field} charCount={charCount} />
                {errorBlock}
              </div>
            );

          case REFERENCE_TYPE.PHONE:
            return (
              <div>
                {labelBlock}
                <Input
                  id={field.column_name}
                  name={field.column_name}
                  type="tel"
                  value={(currentValue as string) || ""}
                  onChange={(e) => fieldApi.handleChange(e.target.value)}
                  onBlur={fieldApi.handleBlur}
                  disabled={isReadOnly}
                  className={cn(inputStyles)}
                />
                <FieldConstraints field={field} charCount={charCount} />
                {errorBlock}
              </div>
            );

          case REFERENCE_TYPE.PASSWORD:
            return (
              <div>
                {labelBlock}
                <Input
                  id={field.column_name}
                  name={field.column_name}
                  type="password"
                  value={(currentValue as string) || ""}
                  onChange={(e) => fieldApi.handleChange(e.target.value)}
                  onBlur={fieldApi.handleBlur}
                  disabled={isReadOnly}
                  className={cn(inputStyles)}
                />
                <FieldConstraints field={field} charCount={charCount} />
                {errorBlock}
              </div>
            );

          default:
            return (
              <div>
                {labelBlock}
                <Input
                  id={field.column_name}
                  name={field.column_name}
                  type="text"
                  value={(currentValue as string) || ""}
                  onChange={(e) => fieldApi.handleChange(e.target.value)}
                  onBlur={fieldApi.handleBlur}
                  disabled={isReadOnly}
                  maxLength={field.field_length}
                  className={cn(inputStyles)}
                />
                <FieldConstraints field={field} charCount={charCount} />
                {errorBlock}
              </div>
            );
        }
      }}
    </form.Field>
  );
}

/** Subscribes to form value changes and notifies the parent via onChange.
 *  Skips the initial render so the parent isn't notified with the initial data. */
function FormChangeNotifier({
  form,
  onChange,
}: {
  form: ReturnType<typeof useForm<FormValues>>;
  onChange: (data: Record<string, unknown>) => void;
}) {
  const values = form.useStore((state: any) => state.values);
  const isFirst = useRef(true);

  // The effect fires on value changes only, but it must call the *current*
  // `onChange`. Listing `onChange` as a dependency is what an exhaustive-deps
  // rule asks for and it is wrong here: parents pass an inline arrow, so its
  // identity changes every render, the effect re-runs every render, the parent
  // sets state, and React aborts with "Maximum update depth exceeded" — the
  // form crashed into the error boundary immediately after a successful save.
  // A ref keeps the callback fresh without making it a trigger.
  const onChangeRef = useRef(onChange);
  useEffect(() => {
    onChangeRef.current = onChange;
  });

  useEffect(() => {
    if (isFirst.current) {
      isFirst.current = false;
      return;
    }
    onChangeRef.current(values);
  }, [values]);
  return null;
}

export function DynamicForm({
  tableName,
  fields: externalFields,
  initialData = {},
  onSubmit,
  onChange,
  isLoading: externalLoading = false,
  isSaving = false,
  mode = "create",
  readOnly = false,
  serverErrors = {},
  parentField,
  readOnlyFields = [],
  parentContext,
  formId,
}: DynamicFormProps) {
  const { t } = useTranslations();
  const {
    data: fetchedFields,
    isLoading: fieldsLoading,
    error,
  } = useFormFields(tableName, { enabled: !externalFields });
  const fields = externalFields || fetchedFields;
  const [zodErrors, setZodErrors] = useState<Record<string, string>>({});

  // Derive the entity PK column name from the table name (bus_patient → patient_id)
  // The dictionary knows which column is the key; guessing it from the table
  // name does not. `bus_vendor` + "_id" produced `vendor_id`, a column that
  // exists nowhere in this stack — every `bus_*` table's primary key is plain
  // `id` — so create mode invented that field, posted it, and the backend
  // rejected the whole request with "Unknown field 'vendor_id'". No record
  // could be created through the UI for any entity.
  const pkColumnName =
    fields?.find((f: FieldMetadata) => f.is_key)?.column_name ?? "id";

  const form = useForm<FormValues>({
    defaultValues: initialData,
    onSubmit: async ({ value }) => {
      if (readOnly || !onSubmit) return;

      // Auto-generate UUID for the entity PK in create mode
      if (mode === "create" && fields && !value[pkColumnName]) {
        value[pkColumnName] = crypto.randomUUID();
      }

      // An untouched checkbox never enters the form's value map at all, so a
      // mandatory NOT NULL boolean arrived absent and the backend rejected the
      // create with "'is_active' is required". The checkbox was on screen and
      // showed the right state — "no" — it just never said so. Both submit
      // paths need this, so both call it.
      applyBooleanDefaults(value, fields);


      // Zod validation
      if (fields) {
        const displayedFields = fields.filter((f) => {
          if (!f.is_displayed || f.column_name === parentField) return false;
          if (mode === "create" && f.column_name === pkColumnName) return false;
          return true;
        });
        const validation = validateFormData(
          displayedFields,
          value,
          mode === "view" ? "edit" : mode
        );
        if (!validation.success) {
          setZodErrors(validation.errors);
          toast.error("Please fix the validation errors");
          return;
        }
        setZodErrors({});
      }

      const filteredValues =
        mode === "edit" && fields
          ? Object.entries(value).reduce(
              (acc, [key, val]) => {
                if (
                  key === "id" ||
                  key === "created_at" ||
                  key === "updated_at" ||
                  key === "deleted_at"
                )
                  return acc;
                const field = fields.find((f: FieldMetadata) => f.column_name === key);
                const isUpdateable = field?.is_updateable !== false;
                const isVersionField = key === "version";
                if (isUpdateable || isVersionField) acc[key] = val;
                return acc;
              },
              {} as Record<string, unknown>
            )
          : value;

      await onSubmit(filteredValues);
    },
  });

  (form as any).readOnly = readOnly;
  (form as any).mode = mode;

  // Same reasoning as `FormChangeNotifier`: `form` is rebuilt by `useForm` on
  // every render, so depending on `form.setFieldValue` makes this effect run
  // every render, and each run writes to the store and schedules another one.
  // Only `initialData` should trigger it; the form is reached through a ref.
  const formRef = useRef(form);
  formRef.current = form;

  useEffect(() => {
    if (Object.keys(initialData).length > 0) {
      for (const [key, value] of Object.entries(initialData)) {
        formRef.current.setFieldValue(key, value);
      }
    }
  }, [initialData]);

  const isLoading = externalFields ? false : fieldsLoading;

  const groupedFields = useMemo(() => {
    if (!fields || fields.length === 0) return new Map();
    const displayFields = fields.filter((f) => {
      if (!f.is_displayed || f.column_name === parentField) return false;
      // Hide the entity's own PK field in create mode — it's auto-generated on submit
      if (mode === "create" && f.column_name === pkColumnName) return false;
      return true;
    });
    const groups: Map<string | null, FieldMetadata[]> = new Map();
    for (const field of displayFields) {
      const groupName = field.group_name || null;
      if (!groups.has(groupName)) groups.set(groupName, []);
      groups.get(groupName)?.push(field);
    }
    return groups;
  }, [fields, parentField, mode, pkColumnName]);

  if (isLoading) {
    return (
      <div className="space-y-4">
        {[1, 2, 3, 4].map((i) => (
          <div key={i} className="space-y-2">
            <Skeleton className="h-4 w-24" />
            <Skeleton className="h-10 w-full" />
          </div>
        ))}
      </div>
    );
  }

  if (error && !externalFields) {
    return (
      <Box radius="md" padding={4} className="bg-destructive/15 text-destructive">
        Failed to load form fields: {error.message}
      </Box>
    );
  }

  if (!fields || fields.length === 0) {
    return (
      <Box radius="md" bg="muted" padding={4} className="text-muted-foreground">
        No fields configured for this entity.
      </Box>
    );
  }

  const handleFormSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (readOnly || !onSubmit) return;

    const currentValues = form.state.values;
    const value = currentValues as Record<string, unknown>;

    // Auto-generate UUID for the entity PK in create mode
    if (mode === "create" && fields && !value[pkColumnName]) {
      value[pkColumnName] = crypto.randomUUID();
    }

      // An untouched checkbox never enters the form's value map at all, so a
    // mandatory NOT NULL boolean arrived absent and the backend rejected the
    // create with "'is_active' is required". The checkbox was on screen and
    // showed the right state — "no" — it just never said so. Both submit
    // paths need this, so both call it.
    applyBooleanDefaults(value, fields);


    // Zod validation
    if (fields) {
      const displayedFields = fields.filter((f) => {
        if (!f.is_displayed || f.column_name === parentField) return false;
        if (mode === "create" && f.column_name === pkColumnName) return false;
        return true;
      });
      const validation = validateFormData(displayedFields, value, mode === "view" ? "edit" : mode);
      if (!validation.success) {
        setZodErrors(validation.errors);
        toast.error("Please fix the validation errors");
        return;
      }
      setZodErrors({});
    }

    const filteredValues =
      mode === "edit" && fields
        ? Object.entries(value).reduce(
            (acc, [key, val]) => {
              if (
                key === "id" ||
                key === "created_at" ||
                key === "updated_at" ||
                key === "deleted_at"
              )
                return acc;
              const field = fields.find((f: FieldMetadata) => f.column_name === key);
              const isUpdateable = !field?.is_read_only;
              const isVersionField = key === "version";
              if (isUpdateable || isVersionField) acc[key] = val;
              return acc;
            },
            {} as Record<string, unknown>
          )
        : value;

    await onSubmit(filteredValues);
  };

  const requiredCount = fields.filter((f) => {
    if (!f.is_displayed || !f.is_mandatory || f.column_name === parentField) return false;
    if (mode === "create" && f.column_name === pkColumnName) return false;
    return true;
  }).length;
  const totalDisplayed = fields.filter((f) => {
    if (!f.is_displayed || f.column_name === parentField) return false;
    if (mode === "create" && f.column_name === pkColumnName) return false;
    return true;
  }).length;

  return (
    <form.Provider>
      {onChange && <FormChangeNotifier form={form} onChange={onChange} />}
      <form id={formId} onSubmit={handleFormSubmit} className="space-y-6">
        {/* Form summary bar */}
        <HStack align="center" justify="between">
          <HStack align="center" gap={3}>
            <Text size="xs" color="secondary">{totalDisplayed} fields</Text>
            {requiredCount > 0 && (
              <>
                <span className="text-muted-foreground/30">|</span>
                <Text size="xs" weight="medium" className="text-red-500/80">
                  {requiredCount} required
                </Text>
              </>
            )}
            {Object.keys(zodErrors).length > 0 && (
              <>
                <span className="text-muted-foreground/30">|</span>
                <Text size="xs" color="danger" weight="medium" className="inline-flex items-center gap-1">
                  <AlertCircle size={12} />
                  {Object.keys(zodErrors).length} validation{" "}
                  {Object.keys(zodErrors).length === 1 ? "error" : "errors"}
                </Text>
              </>
            )}
          </HStack>
          {!readOnly && onSubmit && (
            <form.Subscribe selector={(state: any) => [state.isSubmitting]}>
              {([isFormSubmitting]: any) => (
                <Button
                  type="submit"
                  disabled={isSaving || isFormSubmitting}
                  size="sm"
                  className="bg-primary hover:bg-primary/90"
                >
                  {isSaving || isFormSubmitting
                    ? "Saving..."
                    : mode === "create"
                      ? "Create"
                      : "Save"}
                </Button>
              )}
            </form.Subscribe>
          )}
        </HStack>

        {Array.from(groupedFields.entries()).map(([groupName, fieldsInGroup]) => {
          const groupColumns = fieldsInGroup[0]?.group_columns || 1;

          return (
            <div key={groupName || "ungrouped"} className="space-y-4">
              {groupName && (
                <div className="border-b border-primary/20 pb-2">
                  <Heading level={3} color="accent">{groupName}</Heading>
                  {fieldsInGroup[0]?.group_description && (
                    <Text size="xs" color="secondary" block className="mt-0.5">
                      {fieldsInGroup[0].group_description}
                    </Text>
                  )}
                </div>
              )}

              <div
                className={cn(
                  "grid gap-x-6 gap-y-5",
                  groupColumns === 1 && "grid-cols-1",
                  groupColumns === 2 && "grid-cols-1 md:grid-cols-2",
                  groupColumns === 3 && "grid-cols-1 md:grid-cols-3",
                  groupColumns === 4 && "grid-cols-1 md:grid-cols-4"
                )}
              >
                {fieldsInGroup.map((field: FieldMetadata) => (
                  <div
                    key={field.sys_field_id}
                    className={cn(
                      field.col_span &&
                        field.col_span > 1 &&
                        `md:col-span-${Math.min(groupColumns, field.col_span)}`
                    )}
                  >
                    <FieldRenderer
                      field={field}
                      form={form}
                      serverErrors={serverErrors}
                      zodErrors={zodErrors}
                      tableName={tableName}
                      readOnlyFields={
                        mode === "edit" ? [...readOnlyFields, pkColumnName] : readOnlyFields
                      }
                      parentContext={parentContext}
                    />
                  </div>
                ))}
              </div>
            </div>
          );
        })}

        {!readOnly && onSubmit && (
          <HStack justify="end" gap={4} className="pt-2 border-t border-border">
            <form.Subscribe selector={(state: any) => [state.isSubmitting]}>
              {([isFormSubmitting]: any) => (
                <Button
                  type="submit"
                  disabled={isSaving || isFormSubmitting}
                  className="bg-primary hover:bg-primary/90"
                >
                  {isSaving || isFormSubmitting
                    ? "Saving..."
                    : mode === "create"
                      ? "Create"
                      : "Save"}
                </Button>
              )}
            </form.Subscribe>
          </HStack>
        )}
      </form>
    </form.Provider>
  );
}

/**
 * The application shell: one sidebar and one header, on every screen that has
 * chrome at all.
 *
 * `AppLayout`, `Sidebar` and `Header` have been generated into every
 * application and rendered by none of them — `app-layout.tsx` imported
 * `Sidebar`, and nothing imported `app-layout`. The sidebar's own source said
 * so in a comment. This is what mounts them.
 *
 * **It decides by route, not by auth state.** A shell that waited for a session
 * would flash its chrome around the sign-in page on every cold load, and an
 * unauthenticated visitor to a deep link would see a sidebar full of nothing
 * while the redirect resolved. `CHROMELESS` names the prefixes that are their
 * own full-page experience; everything else gets the shell.
 *
 * It deliberately does **not** guard the routes. `AppLayout` did — it redirected
 * to `/auth/login` when `useAuth()` reported no session — and mounting that at
 * the root would have put a second, competing redirect behind every page that
 * already does its own. One guard per screen, where the screen can say what it
 * needs.
 */
import { type ReactNode, useEffect, useState } from "react";
import { useLocation } from "@tanstack/react-router";
import { Header } from "@/components/layout/header";
import { Sidebar } from "@/components/layout/sidebar";
import { VStack } from "@/components/ui/layout";
import { isEmbedded } from "@/lib/embed";

/**
 * Route prefixes that render without chrome.
 *
 * Sign-in and sign-up are their own page. `/manual.html` is not here because it
 * is a static file the server hands over rather than a route in this router.
 */
const CHROMELESS = ["/auth"];

export function AppShell({ children }: { children: ReactNode }) {
  const { pathname, searchStr } = useLocation();
  // A screen the chat opened (`?embed=1`) is a card in a conversation, not an
  // application: no sidebar, no header. The query string decides on the first
  // render, which the server renders too; `isEmbedded()` then keeps the frame
  // chromeless as it navigates (a create lands on the record it made, a URL
  // without the flag).
  const [embedded, setEmbedded] = useState(false);
  useEffect(() => {
    setEmbedded(isEmbedded());
  }, [pathname]);
  const bare =
    embedded ||
    new URLSearchParams(searchStr).get("embed") === "1" ||
    CHROMELESS.some((prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`));

  if (bare) {
    return <main className="min-h-screen bg-background">{children}</main>;
  }

  return (
    <div className="flex h-screen overflow-hidden bg-background">
      <Sidebar />
      <VStack grow className="overflow-hidden">
        <Header />
        <main className="flex-1 overflow-auto">{children}</main>
      </VStack>
    </div>
  );
}

/**
 * Layout Components Index
 *
 * Central export for all layout components.
 *
 */

export { AppShell } from "./app-shell";
export { Header } from "./header";
export { Sidebar } from "./sidebar";

'use client';

/**
 * Sidebar Navigation
 *
 * **Every entry comes from the Application Dictionary**, through the same
 * `/api/me/dashboard` query the dashboard's cards are built from. That is one
 * fetch for both — whichever renders first pays for it and the other reads the
 * cache — and it means the menu offers exactly what this caller may open,
 * because that endpoint answers from the rows `/api/bus/*` is guarded by.
 *
 * It used to carry three hardcoded lists instead, and mounting it would have
 * shipped all three defects:
 *
 * - `navItems` interpolated the entities at generation time and gave each one
 *   an icon guessed from its name, while the dashboard drew `sys_table.icon`.
 *   Two derivations of the same picture, free to disagree.
 * - `adminItems` named six admin screens. One of them, `/admin/dictionary`,
 *   does not exist in the generated application — a dead link in the menu that
 *   exists to say what the application has.
 * - Neither list was scoped to the caller, so the menu offered entities the API
 *   would refuse.
 *
 * Generated: {{now}}
 */

import { useState } from 'react';
import { Link, useLocation } from '@tanstack/react-router';
import {
  ChevronLeft,
  ChevronRight,
  Database,
  FileBarChart,
  LayoutDashboard,
  Sparkles,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Icon } from '@/components/ui/icon';
import { adminWindows, entityHref, useDashboard } from '@/hooks/use-dashboard';
import { Box, HStack, Text } from '@/components/ui/layout';

interface SidebarProps {
  className?: string;
}

/** One link, as the sidebar needs it: a label, a route, and a way to draw it. */
interface NavEntry {
  title: string;
  href: string;
  /** A lucide id from the dictionary. Null falls back to the section default. */
  icon?: string | null;
}

/** Icons for the entries every application has, whatever its model. */
const FIXED_ICONS: Record<string, typeof LayoutDashboard> = {
  '/dashboard': LayoutDashboard,
  '/ask': Sparkles,
  '/reports': FileBarChart,
};

export function Sidebar({ className }: SidebarProps) {
  const location = useLocation();
  const pathname = location.pathname;
  const [isCollapsed, setIsCollapsed] = useState(false);
  const { data: dashboard } = useDashboard();

  const entities: NavEntry[] = (dashboard?.data ?? []).flatMap((group) =>
    group.entities.map((table) => ({
      title: table.window_name,
      href: entityHref(table),
      icon: table.window_icon ?? null,
    }))
  );

  const admin: NavEntry[] = adminWindows(dashboard).map((window) => ({
    title: window.name,
    href: window.route,
    icon: window.icon,
  }));

  // Always listed. The page itself explains that the add-on is off when the
  // backend answers 503, which is more use than a missing menu entry.
  const fixed: NavEntry[] = [
    { title: 'Dashboard', href: '/dashboard' },
    { title: 'Ask', href: '/ask' },
    { title: 'Reports', href: '/reports' },
  ];

  return (
    <div
      className={cn(
        'relative flex flex-col border-r bg-background',
        isCollapsed ? 'w-16' : 'w-64',
        'transition-all duration-300',
        className
      )}
    >
      <HStack align="center" justify="between" paddingInline={4} className="h-16 border-b">
        {!isCollapsed && (
          <HStack align="center" gap={2} className="min-w-0">
            <HStack align="center" justify="center" className="h-8 w-8 rounded-lg bg-primary flex-shrink-0">
              <Database className="h-4 w-4 text-primary-foreground" />
            </HStack>
            <Text weight="semibold" truncate>{{project.name}}</Text>
          </HStack>
        )}
        <Button
          variant="ghost"
          size="icon"
          onClick={() => setIsCollapsed(!isCollapsed)}
          className="h-8 w-8 flex-shrink-0"
          aria-label={isCollapsed ? 'Expand navigation' : 'Collapse navigation'}
        >
          {isCollapsed ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}
        </Button>
      </HStack>

      <ScrollArea className="flex-1 px-2 py-4">
        <nav className="space-y-6">
          <div className="space-y-1">
            {fixed.map((entry) => (
              <NavLink
                key={entry.href}
                entry={entry}
                fallback={FIXED_ICONS[entry.href] ?? LayoutDashboard}
                isActive={pathname === entry.href || pathname.startsWith(`${entry.href}/`)}
                isCollapsed={isCollapsed}
              />
            ))}
          </div>

          {entities.length > 0 && (
            <div className="space-y-1">
              {!isCollapsed && (
                <Box paddingInline={2}>
                  <Text size="xs" weight="semibold" color="secondary" block className="mb-2 px-2">
                    Entities
                  </Text>
                </Box>
              )}
              {entities.map((entry) => (
                <NavLink
                  key={entry.href}
                  entry={entry}
                  fallback={Database}
                  isActive={pathname === entry.href || pathname.startsWith(`${entry.href}/`)}
                  isCollapsed={isCollapsed}
                />
              ))}
            </div>
          )}

          {admin.length > 0 && (
            <div className="space-y-1">
              {!isCollapsed && (
                <Box paddingInline={2}>
                  <Text size="xs" weight="semibold" color="secondary" block className="mb-2 px-2">
                    Application Dictionary
                  </Text>
                </Box>
              )}
              {admin.map((entry) => (
                <NavLink
                  key={entry.href}
                  entry={entry}
                  fallback={Database}
                  isActive={pathname === entry.href || pathname.startsWith(`${entry.href}/`)}
                  isCollapsed={isCollapsed}
                />
              ))}
            </div>
          )}
        </nav>
      </ScrollArea>
    </div>
  );
}

interface NavLinkProps {
  entry: NavEntry;
  /** Drawn when the dictionary row names no icon. */
  fallback: React.ElementType;
  isActive: boolean;
  isCollapsed: boolean;
}

function NavLink({ entry, fallback: Fallback, isActive, isCollapsed }: NavLinkProps) {
  // A real anchor rather than a button with `navigate()`: the browser's own
  // middle-click, open-in-new-tab and copy-link all work on a link and none of
  // them work on a click handler, and a menu is the one place people use them.
  const link = (
    <Link
      to={entry.href}
      aria-current={isActive ? 'page' : undefined}
      aria-label={entry.title}
      className={cn(
        'flex w-full items-center gap-2 rounded-md px-3 py-2 text-sm transition-colors',
        isActive
          ? 'bg-secondary text-secondary-foreground font-medium'
          : 'text-foreground hover:bg-muted',
        isCollapsed && 'justify-center px-2'
      )}
    >
      {entry.icon ? (
        <Icon name={entry.icon} size={16} />
      ) : (
        <Fallback className="h-4 w-4" />
      )}
      {!isCollapsed && <span className="flex-1 truncate text-left">{entry.title}</span>}
    </Link>
  );

  if (!isCollapsed) return link;

  return (
    <TooltipProvider delayDuration={0}>
      <Tooltip>
        <TooltipTrigger asChild>{link}</TooltipTrigger>
        <TooltipContent side="right">{entry.title}</TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

/**
 * The chart a report declares: `chart: bar | line | area | pie`, plotting the
 * result column named by `x` against the one named by `y`.
 *
 * Plain SVG rather than a charting library. Four chart types over one series
 * is the whole requirement, and a library would be a dependency in every
 * generated application for a screen many models never use. Colour comes from
 * the theme through `currentColor`, so the chart follows the theme selector
 * like everything else on the page.
 */

import { useMemo } from "react";

import type { ReportChart as ChartKind } from "@/hooks/use-reports";

interface ReportChartProps {
  kind: ChartKind;
  rows: Record<string, unknown>[];
  x: string;
  y: string;
}

interface Point {
  label: string;
  value: number;
}

const WIDTH = 760;
const HEIGHT = 320;
const MARGIN = { top: 16, right: 16, bottom: 56, left: 64 };
const PLOT_W = WIDTH - MARGIN.left - MARGIN.right;
const PLOT_H = HEIGHT - MARGIN.top - MARGIN.bottom;

/** Slice colours for a pie. Categorical, so they are fixed rather than themed. */
const SLICE_CLASSES = [
  "text-sky-600",
  "text-emerald-600",
  "text-amber-500",
  "text-rose-600",
  "text-violet-600",
  "text-teal-600",
  "text-orange-600",
  "text-indigo-600",
  "text-lime-600",
  "text-fuchsia-600",
];

/** More rows than this and a chart stops being readable; the table has them all. */
const MAX_POINTS = 60;

const numberFormat = new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 });

function toNumber(value: unknown): number | null {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

/** A tick step of 1, 2 or 5 × 10ⁿ giving about five ticks up to `max`. */
function niceStep(max: number): number {
  if (max <= 0) return 1;
  const raw = max / 5;
  const magnitude = 10 ** Math.floor(Math.log10(raw));
  const normalised = raw / magnitude;
  const factor = normalised <= 1 ? 1 : normalised <= 2 ? 2 : normalised <= 5 ? 5 : 10;
  return factor * magnitude;
}

function truncateLabel(label: string, length = 14): string {
  return label.length > length ? `${label.slice(0, length - 1)}…` : label;
}

export function ReportChart({ kind, rows, x, y }: ReportChartProps) {
  const points = useMemo<Point[]>(
    () =>
      rows.slice(0, MAX_POINTS).flatMap((row) => {
        const value = toNumber(row[y]);
        if (value === null) return [];
        const raw = row[x];
        return [{ label: raw === null || raw === undefined ? "—" : String(raw), value }];
      }),
    [rows, x, y]
  );

  if (points.length === 0) {
    return (
      <p className="text-sm text-muted-foreground">
        No row has a number in <code>{y}</code> to plot.
      </p>
    );
  }

  // Axes over nothing but zeros read as a chart that failed to draw.
  if (points.every((p) => p.value === 0)) {
    return (
      <p className="text-sm text-muted-foreground">
        Every row has 0 in <code>{y}</code>, so there is nothing to plot yet. The rows are below.
      </p>
    );
  }

  const omitted = Math.min(rows.length, MAX_POINTS) < rows.length;
  const caption = omitted ? `First ${MAX_POINTS} of ${rows.length} rows.` : null;

  return (
    <figure className="w-full overflow-x-auto">
      {kind === "pie" ? <Pie points={points} /> : <Cartesian kind={kind} points={points} x={x} y={y} />}
      {caption && <figcaption className="mt-2 text-xs text-muted-foreground">{caption}</figcaption>}
    </figure>
  );
}

function Cartesian({
  kind,
  points,
  x,
  y,
}: {
  kind: Exclude<ChartKind, "pie">;
  points: Point[];
  x: string;
  y: string;
}) {
  const low = Math.min(0, ...points.map((p) => p.value));
  const high = Math.max(0, ...points.map((p) => p.value));
  // Counts are whole numbers, and an axis reading 0.2, 0.4 … over them invents
  // precision the data does not have.
  const whole = points.every((p) => Number.isInteger(p.value));
  const rawStep = niceStep(Math.max(Math.abs(high), Math.abs(low)));
  const step = whole ? Math.max(1, Math.round(rawStep)) : rawStep;
  const top = Math.ceil(high / step) * step || step;
  const bottom = Math.floor(low / step) * step;
  const span = top - bottom;
  const scaleY = (value: number) => MARGIN.top + PLOT_H - ((value - bottom) / span) * PLOT_H;
  const band = PLOT_W / points.length;
  const centre = (index: number) => MARGIN.left + band * index + band / 2;

  const ticks: number[] = [];
  for (let tick = bottom; tick <= top + step / 2; tick += step) ticks.push(tick);

  const line = points.map((p, i) => `${centre(i)},${scaleY(p.value)}`).join(" ");
  const area = `${centre(0)},${scaleY(0)} ${line} ${centre(points.length - 1)},${scaleY(0)}`;
  const everyNth = Math.ceil(points.length / 12);

  return (
    <svg
      viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
      role="img"
      aria-label={`${kind} chart of ${y} by ${x}`}
      className="h-auto w-full min-w-[480px]"
    >
      {ticks.map((tick) => (
        <g key={tick}>
          <line
            x1={MARGIN.left}
            x2={WIDTH - MARGIN.right}
            y1={scaleY(tick)}
            y2={scaleY(tick)}
            className="stroke-muted-foreground/20"
          />
          <text
            x={MARGIN.left - 8}
            y={scaleY(tick)}
            textAnchor="end"
            dominantBaseline="middle"
            className="fill-muted-foreground text-[11px]"
          >
            {numberFormat.format(tick)}
          </text>
        </g>
      ))}

      <g className="text-primary">
        {kind === "bar" &&
          points.map((p, i) => {
            const zero = scaleY(0);
            const value = scaleY(p.value);
            return (
              <rect
                key={`${p.label}-${i}`}
                x={centre(i) - (band * 0.7) / 2}
                width={band * 0.7}
                y={Math.min(zero, value)}
                height={Math.max(1, Math.abs(zero - value))}
                rx={2}
                fill="currentColor"
              >
                <title>{`${p.label}: ${numberFormat.format(p.value)}`}</title>
              </rect>
            );
          })}
        {kind === "area" && <polygon points={area} fill="currentColor" fillOpacity={0.18} />}
        {(kind === "line" || kind === "area") && (
          <>
            <polyline points={line} fill="none" stroke="currentColor" strokeWidth={2} />
            {points.map((p, i) => (
              <circle key={`${p.label}-${i}`} cx={centre(i)} cy={scaleY(p.value)} r={3} fill="currentColor">
                <title>{`${p.label}: ${numberFormat.format(p.value)}`}</title>
              </circle>
            ))}
          </>
        )}
      </g>

      {points.map((p, i) =>
        i % everyNth === 0 ? (
          <text
            key={`${p.label}-${i}`}
            x={centre(i)}
            y={HEIGHT - MARGIN.bottom + 16}
            textAnchor="middle"
            className="fill-muted-foreground text-[11px]"
          >
            {truncateLabel(p.label)}
          </text>
        ) : null
      )}
      <text
        x={MARGIN.left + PLOT_W / 2}
        y={HEIGHT - 8}
        textAnchor="middle"
        className="fill-foreground text-xs font-medium"
      >
        {x}
      </text>
    </svg>
  );
}

function Pie({ points }: { points: Point[] }) {
  const positive = points.filter((p) => p.value > 0);
  const total = positive.reduce((sum, p) => sum + p.value, 0);
  if (total === 0) {
    return <p className="text-sm text-muted-foreground">Every value is zero; there is nothing to divide.</p>;
  }

  const radius = 120;
  const cx = 150;
  const cy = 150;
  let angle = -Math.PI / 2;
  const slices = positive.map((p, index) => {
    const sweep = (p.value / total) * Math.PI * 2;
    const start = angle;
    angle += sweep;
    const end = angle;
    const large = sweep > Math.PI ? 1 : 0;
    const x1 = cx + radius * Math.cos(start);
    const y1 = cy + radius * Math.sin(start);
    const x2 = cx + radius * Math.cos(end);
    const y2 = cy + radius * Math.sin(end);
    // A single slice is a full circle, which an arc from a point to itself
    // cannot draw.
    const d =
      positive.length === 1
        ? `M ${cx - radius} ${cy} a ${radius} ${radius} 0 1 0 ${radius * 2} 0 a ${radius} ${radius} 0 1 0 ${-radius * 2} 0`
        : `M ${cx} ${cy} L ${x1} ${y1} A ${radius} ${radius} 0 ${large} 1 ${x2} ${y2} Z`;
    return { ...p, d, colour: SLICE_CLASSES[index % SLICE_CLASSES.length] ?? "text-primary" };
  });

  return (
    <div className="flex flex-wrap items-center gap-8">
      <svg viewBox="0 0 300 300" role="img" aria-label="Pie chart" className="h-72 w-72 shrink-0">
        {slices.map((slice, i) => (
          <path key={`${slice.label}-${i}`} d={slice.d} fill="currentColor" className={slice.colour}>
            <title>{`${slice.label}: ${numberFormat.format(slice.value)}`}</title>
          </path>
        ))}
      </svg>
      <ul className="space-y-1 text-sm">
        {slices.map((slice, i) => (
          <li key={`${slice.label}-${i}`} className="flex items-center gap-2">
            <svg viewBox="0 0 10 10" className={`h-3 w-3 ${slice.colour}`} aria-hidden="true">
              <rect width="10" height="10" rx="2" fill="currentColor" />
            </svg>
            <span className="font-medium">{slice.label}</span>
            <span className="text-muted-foreground">
              {numberFormat.format(slice.value)} ({Math.round((slice.value / total) * 100)}%)
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

/**
 * The report layout designer for one entity.
 *
 * `ankareport` is a plain DOM library, not a React component, so it is created
 * once against a ref and torn down on unmount. It is imported dynamically for
 * two reasons: it is only ever reached from this screen, and it touches
 * `document` at module scope, which would break the server render every route
 * in this app goes through.
 *
 * The layout it produces is opaque to us on purpose. It is stored as JSONB in
 * `sys_report_designs.layout` and handed straight back to the same library to
 * render, so nothing here parses it, validates it, or has an opinion about its
 * shape. That is what lets the designer be upgraded without a migration.
 */

import { useEffect, useRef, useState } from "react";
import { AlertCircle } from "lucide-react";
import { useReportDesign, useSaveReportDesign } from "@/components/admin/use-report-designs";
import { Skeleton } from "@/components/ui/skeleton";

interface ReportDesignerProps {
  /** Physical table, e.g. `bus_compound`. */
  tableName: string;
  /** Display name for the design, e.g. `Compound`. */
  entityLabel: string;
  /** Column names offered in the data-source tree. */
  columns: string[];
}

/** Minimal shape of what we use; the library's own types are not published. */
interface AnkaDesigner {
  dispose?: () => void;
}

export function ReportDesigner({ tableName, entityLabel, columns }: ReportDesignerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [status, setStatus] = useState<"idle" | "saving" | "saved">("idle");
  const [loadError, setLoadError] = useState<string | null>(null);

  const { data: design, isLoading } = useReportDesign(tableName);
  const save = useSaveReportDesign(tableName);

  // The designer is built once the existing layout has been fetched, so it
  // opens on what is already stored rather than on a blank page that would
  // overwrite it at the first save.
  const ready = !isLoading;

  // Held in a ref so the effect does not re-run — and rebuild the designer,
  // discarding unsaved work — every time the mutation object changes identity.
  const saveRef = useRef(save);
  saveRef.current = save;
  const designRef = useRef(design);
  designRef.current = design ?? null;

  useEffect(() => {
    if (!ready || !containerRef.current) return;

    const element = containerRef.current;
    let instance: AnkaDesigner | undefined;
    let disposed = false;

    void (async () => {
      try {
        const anka = await import("ankareport");
        // The package publishes `designer` as a named export; older builds put
        // it behind `default`. Accept either rather than assume.
        const factory =
          (anka as { designer?: unknown }).designer ??
          (anka as { default?: { designer?: unknown } }).default?.designer;

        if (typeof factory !== "function") {
          setLoadError("The report designer library did not expose a designer.");
          return;
        }
        if (disposed) return;

        instance = (factory as (options: unknown) => AnkaDesigner)({
          element,
          dataSource: columns.map((column) => ({ label: column, field: column })),
          layout: designRef.current?.layout ?? undefined,
          onSaveButtonClick: async (layout: Record<string, unknown>) => {
            setStatus("saving");
            try {
              await saveRef.current.mutateAsync({
                layout,
                name: `${entityLabel} Report`,
                existing: designRef.current ?? null,
              });
              setStatus("saved");
            } catch {
              setStatus("idle");
            }
          },
        });
      } catch {
        setLoadError("The report designer library could not be loaded.");
      }
    })();

    return () => {
      disposed = true;
      instance?.dispose?.();
      // Clear by node removal rather than innerHTML: the library attaches
      // listeners to the children it created.
      while (element.firstChild) element.removeChild(element.firstChild);
    };
    // `design` is deliberately absent — it is read through `designRef` so that
    // a refetch after saving does not tear the designer down mid-edit.
  }, [ready, tableName, entityLabel, columns]);

  if (isLoading) {
    return (
      <div className="p-6 space-y-4">
        <Skeleton className="h-10 w-full" />
        <Skeleton className="h-10 w-full" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  if (loadError) {
    return (
      <div className="p-6">
        <div className="flex items-start gap-3 rounded-lg border border-border bg-muted/40 p-4">
          <AlertCircle className="h-5 w-5 text-muted-foreground shrink-0 mt-0.5" />
          <div className="text-sm">
            <p className="font-medium text-foreground">{loadError}</p>
            <p className="text-muted-foreground mt-1">
              Any design already saved for {entityLabel} is untouched — this screen could not
              open it, and nothing was written.
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {status !== "idle" && (
        <div className="px-4 py-2 text-sm border-b border-border text-muted-foreground">
          {status === "saving" ? "Saving report design…" : "Report design saved."}
        </div>
      )}
      {save.isError && (
        <div className="px-4 py-2 text-sm border-b border-border text-destructive">
          The design could not be saved.
        </div>
      )}
      <div ref={containerRef} className="flex-1 w-full min-h-[600px]" />
    </div>
  );
}

/**
 * Render one record through its entity's saved report design.
 *
 * This is the half that makes a design worth drawing: the designer stores a
 * layout, and this hands that layout and a record to the same library to
 * produce the printable document. If nothing has been designed for the entity,
 * the button that opens this never appears — an empty print dialog is worse
 * than no print button.
 *
 * The record is passed as both the top-level bindings and a one-element
 * `records` collection, because a layout may bind either a field directly or a
 * content section repeating over a collection, and a designer has no way to
 * know which the author chose.
 */

import { useEffect, useRef, useState } from "react";
import { Printer, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";

interface ReportPrintModalProps {
  open: boolean;
  onClose: () => void;
  layout: Record<string, unknown>;
  data: Record<string, unknown>;
  entityLabel?: string;
}

interface AnkaRenderer {
  exportToPdf?: (fileName: string) => Promise<void>;
}

export function ReportPrintModal({
  open,
  onClose,
  layout,
  data,
  entityLabel,
}: ReportPrintModalProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const rendererRef = useRef<AnkaRenderer | null>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    if (!open || !containerRef.current) return;

    const element = containerRef.current;
    let disposed = false;
    setFailed(false);

    void (async () => {
      try {
        const anka = await import("ankareport");
        const factory =
          (anka as { render?: unknown }).render ??
          (anka as { default?: { render?: unknown } }).default?.render;

        if (typeof factory !== "function") {
          setFailed(true);
          return;
        }
        if (disposed) return;

        rendererRef.current = (factory as (options: unknown) => AnkaRenderer)({
          element,
          layout,
          data: { ...data, records: [data] },
        });
      } catch {
        setFailed(true);
      }
    })();

    return () => {
      disposed = true;
      rendererRef.current = null;
      while (element.firstChild) element.removeChild(element.firstChild);
    };
  }, [open, layout, data]);

  const exportPdf = () => {
    void rendererRef.current?.exportToPdf?.(`${entityLabel ?? "report"}.pdf`);
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next) onClose();
      }}
    >
      <DialogContent className="max-w-4xl w-full h-[90vh] flex flex-col p-0">
        <DialogHeader className="flex flex-row items-center justify-between px-6 py-4 border-b border-border shrink-0">
          <DialogTitle className="text-base font-semibold">
            {entityLabel ? `Print — ${entityLabel}` : "Print Report"}
          </DialogTitle>
          <div className="flex items-center gap-2">
            <Button size="sm" variant="outline" onClick={exportPdf} disabled={failed}>
              <Printer className="h-4 w-4 mr-2" />
              Export PDF
            </Button>
            <Button size="sm" variant="ghost" onClick={onClose}>
              <X className="h-4 w-4" />
            </Button>
          </div>
        </DialogHeader>
        <div className="flex-1 overflow-auto p-6">
          {failed ? (
            <p className="text-sm text-muted-foreground">
              The report renderer could not be loaded, so this document cannot be shown.
            </p>
          ) : null}
          <div ref={containerRef} className="w-full" />
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { Skeleton } from "@/components/ui/skeleton";
import { Grid, HStack } from "@/components/ui/layout";

function QuickAccessCardSkeleton() {
  return (
    <div className="swiss-card p-6 space-y-4">
      <HStack align="start" justify="between" gap={4}>
        <HStack align="center" gap={3} grow>
          <Skeleton className="h-12 w-12 rounded-xl flex-shrink-0" />
          <div className="space-y-2 flex-1">
            <Skeleton className="h-5 w-3/4" />
            <Skeleton className="h-3 w-1/2" />
          </div>
        </HStack>
      </HStack>
      <Skeleton className="h-4 w-full" />
      <Skeleton className="h-4 w-2/3" />
      <div className="pt-2 border-t border-border/50">
        <Skeleton className="h-3 w-24" />
      </div>
    </div>
  );
}

export function DashboardSkeleton() {
  return (
    <Grid columns={1} gap={4}>
      {Array.from({ length: 6 }).map((_, i) => (
