// ============================================================================
// Dynamic Table Component
// ============================================================================

export function DynamicTable({
  tableName,
  fields: externalFields,
  data,
  isLoading: dataLoading = false,
  totalCount = 0,
  page = 1,
  pageSize = 20,
  onPageChange,
  onPageSizeChange: _onPageSizeChange,
  onRowClick,
  onDelete: _onDelete,
  onView,
  onEdit,
  selectedId,
}: DynamicTableProps) {
  const { t } = useTranslations();
  const {
    data: fetchedFields,
    isLoading: fetchFieldsLoading,
    error,
  } = useGridFields(tableName, { enabled: !externalFields });
  const fields = externalFields || fetchedFields;
  const fieldsLoading = externalFields ? false : fetchFieldsLoading;

  // Collect unique lookup fields from the current data
  const lookupFieldDefs = useMemo(() => {
    if (!fields) return [];
    return fields.filter(
      (f) =>
        (f.sys_reference_id === REFERENCE_TYPE.TABLE ||
          f.sys_reference_id === REFERENCE_TYPE.TABLE_DIRECT) &&
        !!f.ref_table_name
    );
  }, [fields]);

  // For each lookup field, collect unique FK values from data
  const lookupQueries = useMemo(() => {
    return lookupFieldDefs
      .map((f) => {
        const uniqueIds = Array.from(
          new Set(
            data
              .map((row) => row[f.column_name])
              .filter((v) => v != null)
              .map(String)
          )
        );
        return { field: f, uniqueIds };
      })
      .filter((q) => q.uniqueIds.length > 0);
  }, [lookupFieldDefs, data]);

  // Several columns can point at the same referenced table — a compound with
  // both a `submitted_by` and an `approved_by` FK to bus_scientist, say. Fetch
  // each referenced table once: passing the same queryKey twice to useQueries
  // makes React Query drop the duplicate and warn, leaving a result slot that
  // does not line up with the field it was meant for.
  const lookupSources = useMemo(() => {
    const byTable = new Map<
      string,
      { field: (typeof lookupFieldDefs)[number]; endpoint: string; ids: Set<string> }
    >();
    for (const { field, uniqueIds } of lookupQueries) {
      const refTable = field.ref_table_name;
      if (!refTable) continue;
      const known = byTable.get(refTable);
      if (known) {
        for (const id of uniqueIds) known.ids.add(id);
        continue;
      }
      const entity = refTable.replace(/^bus_/, "");
      byTable.set(refTable, {
        field,
        endpoint: field.ref_endpoint ?? `/bus/${entity}`,
        ids: new Set(uniqueIds),
      });
    }
    return Array.from(byTable.entries()).map(([refTable, v]) => ({
      refTable,
      field: v.field,
      endpoint: v.endpoint,
      ids: Array.from(v.ids).sort(),
    }));
  }, [lookupQueries]);

  // Only the records this page points at, by id. This used to fetch the first
  // 500 rows of every referenced table and look the page's records up in them,
  // so a state or city past the 500th showed as a raw id.
  const lookupResults = useQueries({
    queries: lookupSources.map(({ refTable, endpoint, ids, field }) => ({
      queryKey: ["lookup", refTable, endpoint, ids],
      queryFn: () =>
        field.ref_endpoint
          ? apiClient.get<PaginatedResponse<Record<string, unknown>>>(endpoint, { limit: 500 })
          : apiClient.get<PaginatedResponse<Record<string, unknown>>>(endpoint, {
              limit: Math.min(Math.max(ids.length, 1), 500),
              "filter.id": `in:${ids.join(",")}`,
            }),
      staleTime: 60_000,
    })),
  });

  // Build a lookup map: { refTableName: { id: displayName } }
  const lookupMap = useMemo<LookupMap>(() => {
    const map: LookupMap = {};
    lookupSources.forEach(({ field }, i) => {
      const result = lookupResults[i];
      if (!result?.data) return;
      const records = Array.isArray(result.data) ? result.data : ((result.data as any).data ?? []);
      const idField = field.ref_id_field ?? "id";
      // The dictionary describes a label as `ref_label_fields` — a list, so an
      // entity identified by more than one column reads properly. Honour it
      // before the single `ref_label_field`; defaulting straight to "name"
      // rendered a raw UUID for every table that names its records something
      // else (bus_experiment.title, say).
      const labelFields: string[] = (field as any).ref_label_fields?.length
        ? (field as any).ref_label_fields
        : field.ref_label_field
          ? [field.ref_label_field]
          : ["name"];
      const tableMap: Record<string, string> = {};
      for (const rec of records) {
        const id = String((rec as any)[idField] ?? "");
        if (id) tableMap[id] = referenceLabel(rec as Record<string, unknown>, labelFields, id);
      }
      if (field.ref_table_name) map[field.ref_table_name] = tableMap;
    });
    return map;
  }, [lookupSources, lookupResults]);

  const [sorting, setSorting] = useState<SortingState>([]);
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
  const [globalFilter, setGlobalFilter] = useState("");
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [rowToDelete, setRowToDelete] = useState<{ id: string; name?: string } | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isExporting, setIsExporting] = useState(false);

  // Handle delete with confirmation
  const handleDeleteClick = useCallback((rowId: string) => {
    const row = data.find((r) => (r as any).id === rowId);
    const rowName = row
      ? (row as any).name || (row as any).title || (row as any).patient_name || `Record #${rowId}`
      : undefined;
    setRowToDelete({ id: rowId, name: rowName });
    setDeleteDialogOpen(true);
  }, [data]);

  /**
   * Download the list as CSV.
   *
   * The rows are fetched rather than read off the screen: `data` holds one page
   * and the point of the export is the list, so it asks the API for the first
   * CSV_EXPORT_LIMIT rows. Cells go through the same formatter and the same
   * lookup map the grid renders with, so a date, an enum-bound column and a
   * referenced record read in the file exactly as they read on screen — an
   * export of raw uuids and ISO timestamps would be a different document from
   * the one the reader asked for.
   */
  const handleExportCsv = async () => {
    if (!fields || fields.length === 0) return;
    setIsExporting(true);
    try {
      const response = await apiClient.get<PaginatedResponse<Record<string, unknown>>>(
        `/bus/${tableName}`,
        { page: 1, limit: CSV_EXPORT_LIMIT }
      );
      const rows = Array.isArray(response)
        ? (response as Record<string, unknown>[])
        : (response?.data ?? []);

      const headers = fields.map((field) => field.name);
      const body = rows.map((row) =>
        fields.map((field) => {
          const value = row[field.column_name];
          if (value === null || value === undefined) return "";

          const isLookup =
            field.sys_reference_id === REFERENCE_TYPE.TABLE ||
            field.sys_reference_id === REFERENCE_TYPE.TABLE_DIRECT;
          if (isLookup && field.ref_table_name) {
            const label = lookupMap[field.ref_table_name]?.[String(value)];
            return label ?? String(value);
          }

          // A dash is the table's way of drawing an empty cell; a CSV says the
          // same thing with an empty field, and a literal "-" would import as
          // data.
          const formatted = formatCellValue(value, field.sys_reference_id);
          return formatted === "-" ? "" : formatted;
        })
      );

      downloadCsv(csvFileName(tableName), toCsv(headers, body));

      if (totalCount > rows.length) {
        toast.success(`Exported ${rows.length} of ${totalCount} rows`, {
          description: `A download holds at most ${CSV_EXPORT_LIMIT} rows. Narrow the list with a filter to export the rest.`,
        });
      }
    } catch (error) {
      toast.error("Export failed", {
        description: error instanceof Error ? error.message : String(error),
      });
    } finally {
      setIsExporting(false);
    }
  };

  const confirmDelete = async () => {
    if (!rowToDelete || !_onDelete) return;

    setIsDeleting(true);
    try {
      await _onDelete(rowToDelete.id);
      setDeleteDialogOpen(false);
      setRowToDelete(null);

      // Show success toast (handled by the parent component's mutation)
    } catch (error) {
      // Show error toast
      const errorMessage =
        error instanceof Error ? error.message : t("common.unexpectedError" as any);
      toast.error(t("table.deleteFailed" as any), {
        description: errorMessage,
      });
    } finally {
      setIsDeleting(false);
    }
  };

  // Generate columns from field metadata (ordered by seq_no_grid)
  const columns = useMemo(() => {
    const baseColumns = !fields ? [] : generateColumns(fields, lookupMap);

    // Add actions column FIRST if callbacks are provided
    if (onView || onEdit || _onDelete) {
      baseColumns.unshift({
        id: "actions",
        header: t("common.actions" as any),
        cell: ({ row }) => {
          // The primary key column is always 'id' in the database schema
          const rowId = row.original.id as string;

          return (
            <HStack gap={2}>
              {onView && (
                <button type="button"
                  onClick={() => onView(rowId)}
                  className="text-blue-600 hover:text-blue-800 text-sm"
                >
                  View
                </button>
              )}
              {onEdit && (
                <button type="button"
                  onClick={() => onEdit(rowId)}
                  className="text-green-600 hover:text-green-800 text-sm"
                >
                  Edit
                </button>
              )}
              {_onDelete && (
                <button type="button"
                  onClick={() => handleDeleteClick(rowId)}
                  className="text-red-600 hover:text-red-800 text-sm"
                >
                  Delete
                </button>
              )}
            </HStack>
          );
        },
        enableSorting: false,
        // enableFiltering is not supported in TanStack Table v8
      });
    }

    return baseColumns;
  }, [fields, onView, onEdit, _onDelete, handleDeleteClick, t, lookupMap]);

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      columnFilters,
      globalFilter,
    },
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    manualPagination: true,
    pageCount: Math.ceil(totalCount / pageSize),
  });

  if (fieldsLoading || dataLoading) {
    return <TableSkeleton />;
  }

  if (error && !externalFields) {
    return (
      <Box radius="md" padding={4} className="bg-destructive/15 text-destructive">
        Failed to load table columns: {error.message}
      </Box>
    );
  }

  if (!fields || fields.length === 0) {
    return (
      <Box radius="md" bg="muted" padding={4} className="text-muted-foreground">
        No columns configured for grid display.
      </Box>
    );
  }

  const totalPages = Math.ceil(totalCount / pageSize);

  return (
    <div className="space-y-4">
      {/* Delete Confirmation Dialog */}
      <DeleteConfirmDialog
        open={deleteDialogOpen}
        onOpenChange={setDeleteDialogOpen}
        itemName={rowToDelete?.name}
        onConfirm={confirmDelete}
        isConfirming={isDeleting}
      />

      {/* Search */}
      <HStack align="center" justify="between" gap={2}>
        <Box grow maxWidth="sm" className="relative">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search..."
            value={globalFilter}
            onChange={(e) => setGlobalFilter(e.target.value)}
            className="pl-8"
          />
        </Box>
        {/* Record Count - Moved above table */}
        <HStack align="center" gap={3}>
          {totalCount > 0 && (
            <div className="text-sm text-muted-foreground">
              Showing {(page - 1) * pageSize + 1} to {Math.min(page * pageSize, totalCount)} of{" "}
              {totalCount} entries
            </div>
          )}
          <Button
            variant="outline"
            size="sm"
            onClick={handleExportCsv}
            disabled={isExporting || !fields || fields.length === 0}
            data-testid="export-csv"
            aria-label="Download this list as CSV"
          >
            <Download className="mr-2 h-4 w-4" />
            {isExporting ? "Exporting..." : "CSV"}
          </Button>
        </HStack>
      </HStack>

      {/* Table */}
      <Box radius="md" border="default" data-testid="entity-table-container">
        <Table data-testid="entity-table">
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className="bg-slate-700 hover:bg-slate-700">
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id} className="text-white font-semibold">
                    {header.isPlaceholder
                      ? null
                      : flexRender(header.column.columnDef.header, header.getContext())}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => {
                // The primary key column is always 'id' in the database schema
                const rowId = row.original.id as string;
                const isSelected = selectedId === rowId;

                return (
                  <TableRow
                    key={row.id}
                    data-state={isSelected && "selected"}
                    className={`${onRowClick ? "cursor-pointer hover:bg-primary/10" : ""} ${row.index % 2 === 1 ? "bg-primary/[0.04]" : ""} transition-colors`}
                    onClick={() => onRowClick?.(row.original)}
                  >
                    {row.getVisibleCells().map((cell) => (
                      <TableCell key={cell.id}>
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                      </TableCell>
                    ))}
                  </TableRow>
                );
              })
            ) : (
              <TableRow data-testid="no-results-row">
                <TableCell colSpan={columns.length} className="h-24 text-center">
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </Box>

      {/* Pagination */}
      {totalPages > 1 && (
        <HStack align="center" justify="end" gap={2}>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onPageChange?.(1)}
            disabled={page === 1}
          >
            <ChevronsLeft size={16} />
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onPageChange?.(page - 1)}
            disabled={page === 1}
          >
            <ChevronLeft size={16} />
          </Button>
          <Text size="sm">
            Page {page} of {totalPages}
          </Text>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onPageChange?.(page + 1)}
            disabled={page === totalPages}
          >
            <ChevronRight size={16} />
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onPageChange?.(totalPages)}
            disabled={page === totalPages}
          >
            <ChevronsRight size={16} />
          </Button>
        </HStack>
      )}
    </div>
  );
}

'use client';

/**
 * Theme selector — switches the app between the seven Astryx themes at runtime.
 *
 * Mounted once in the root layout (`routes/__root.tsx`), so it is present on
 * every page. It deliberately does *not* live in a header: each route in this
 * app builds its own header inline, and `components/layout/header.tsx` is not
 * rendered by any of them — putting the switcher there made it invisible
 * everywhere while looking, in the source, like it worked.
 *
 * `variant="floating"` is the app-wide control: a fixed, self-contained pill in
 * the bottom-left corner. `variant="inline"` is the same dropdown with no
 * positioning, for dropping into a settings page or a header that wants one.
 *
 * The change applies immediately across the whole app and persists, because the
 * provider writes the choice to localStorage.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { useEffect, useState } from 'react';
import { Selector } from '@astryxdesign/core/Selector';

import { isEmbedded } from '@/lib/embed';
import { THEME_NAMES, useAstryxTheme, type ThemeName } from '@/providers/astryx-provider';

export interface ThemeSelectorProps {
  /**
   * `floating` fixes the control to the bottom-left of the viewport;
   * `inline` renders it in flow. Defaults to `inline` so dropping it into a
   * page does not surprise you with fixed positioning.
   */
  variant?: 'floating' | 'inline';
  /** Hide the visible label (it stays in the accessibility tree). */
  isLabelHidden?: boolean;
  className?: string;
}

/**
 * Bottom-*left*: the toast region is top-right and the router devtools sit
 * bottom-right, so this is the one corner nothing else claims.
 *
 * Hoisted to module scope because a `style={ {…} }` literal inside a
 * Handlebars template is a parse error — two braces open an expression.
 */
const FLOATING_STYLE = {
  position: 'fixed' as const,
  bottom: '1rem',
  left: '1rem',
  zIndex: 50,
};

export function ThemeSelector({
  variant = 'inline',
  isLabelHidden,
  className,
}: ThemeSelectorProps) {
  const { theme, setTheme, themes } = useAstryxTheme();
  // Inside the chat's frame the screen is a card in a conversation: a control
  // floating over it would cover the form. Read after mount, like the shell.
  const [embedded, setEmbedded] = useState(false);
  useEffect(() => {
    setEmbedded(isEmbedded());
  }, []);

  const options = THEME_NAMES.map((name) => ({
    value: name,
    label: themes[name].label,
  }));

  const selector = (
    <Selector
      label="Theme"
      isLabelHidden={isLabelHidden ?? variant === 'floating'}
      options={options}
      value={theme}
      size="sm"
      width={160}
      // Astryx's default is a selected-item overlay clamped to the viewport,
      // which for a control pinned to the bottom edge lands the option list on
      // top of its own trigger — after one or two switches the trigger is no
      // longer clickable. `above` is what their docs prescribe for exactly this
      // case (a bottom-fixed toolbar).
      placement={variant === 'floating' ? 'above' : undefined}
      className={className}
      data-testid="theme-selector"
      onChange={(next: string) => setTheme(next as ThemeName)}
    />
  );

  if (variant !== 'floating') return selector;
  if (embedded) return null;

  return (
    <div style={FLOATING_STYLE} data-testid="theme-selector-floating">
      {selector}
    </div>
  );
}

export default ThemeSelector;

/**
 * AlertDialog — shadcn surface over Astryx `AlertDialog`.
 *
 * Astryx takes the whole confirmation as props (`title`, `description`,
 * `actionLabel`, `cancelLabel`, `onAction`) rather than as composed children.
 * The shadcn sub-components are therefore read, not rendered: `AlertDialog`
 * walks them for their text and the action handler, then hands the result to
 * Astryx.
 *
 * That keeps the destructive-confirm call sites (delete row, discard changes)
 * working untouched, which matters — these are the dialogs where a silent
 * rendering regression loses user data.
 */
import { Children, cloneElement, isValidElement, useState, type ReactElement, type ReactNode } from "react";
import { AlertDialog as AstryxAlertDialog } from "@astryxdesign/core/AlertDialog";

interface PartProps {
  children?: ReactNode;
  className?: string;
}

export function AlertDialogTrigger({ children }: PartProps & { asChild?: boolean }) {
  return <>{children}</>;
}

export function AlertDialogContent({ children }: PartProps) {
  return <>{children}</>;
}

export function AlertDialogHeader({ children }: PartProps) {
  return <>{children}</>;
}

export function AlertDialogFooter({ children }: PartProps) {
  return <>{children}</>;
}

export function AlertDialogTitle(_props: PartProps) {
  return null;
}

export function AlertDialogDescription(_props: PartProps) {
  return null;
}

export function AlertDialogAction(_props: PartProps & { onClick?: () => void }) {
  return null;
}

export function AlertDialogCancel(_props: PartProps & { onClick?: () => void }) {
  return null;
}

export interface AlertDialogProps {
  open?: boolean;
  children?: ReactNode;
  onOpenChange?: (open: boolean) => void;
}

/** Depth-first search for the first element of a given type. */
function find(children: ReactNode, target: unknown): ReactElement | undefined {
  let found: ReactElement | undefined;
  Children.forEach(children, (child) => {
    if (found || !isValidElement(child)) return;
    if (child.type === target) {
      found = child;
      return;
    }
    const nested = (child as ReactElement<{ children?: ReactNode }>).props.children;
    if (nested) found = find(nested, target);
  });
  return found;
}

function text(element: ReactElement | undefined, fallback: string): string {
  const content = (element?.props as { children?: ReactNode } | undefined)?.children;
  return typeof content === "string" ? content : fallback;
}

export function AlertDialog({ open, children, onOpenChange }: AlertDialogProps) {
  const action = find(children, AlertDialogAction);
  const cancel = find(children, AlertDialogCancel);
  const trigger = find(children, AlertDialogTrigger);
  const onAction = (action?.props as { onClick?: () => void } | undefined)?.onClick;

  // The shadcn form comes in two shapes. Controlled: the caller owns `open`.
  // Uncontrolled: an `AlertDialogTrigger` inside the dialog opens it. The
  // second was dropped, so a Delete button written that way was never drawn and
  // the screen had no way to delete anything.
  const [inner, setInner] = useState(false);
  const controlled = open !== undefined;
  const isOpen = controlled ? open : inner;
  const setOpen = (next: boolean) => {
    if (!controlled) setInner(next);
    onOpenChange?.(next);
  };

  const triggerChild = (trigger?.props as { children?: ReactNode } | undefined)?.children;
  const triggerNode =
    !controlled && isValidElement(triggerChild)
      ? cloneElement(triggerChild as ReactElement<{ onClick?: () => void }>, {
          onClick: () => setOpen(true),
        })
      : null;

  return (
    <>
      {triggerNode}
      <AstryxAlertDialog
        isOpen={isOpen}
        onOpenChange={(next: boolean) => setOpen(next)}
        title={text(find(children, AlertDialogTitle), "Are you sure?")}
        description={text(find(children, AlertDialogDescription), "")}
        actionLabel={text(action, "Continue")}
        cancelLabel={text(cancel, "Cancel")}
        onAction={() => {
          onAction?.();
          // Astryx does not close on action; the shadcn call sites expect it to.
          setOpen(false);
        }}
      />
    </>
  );
}

export default AlertDialog;

/**
 * The destructive-confirm dialog the grids and the entity shell both use.
 *
 * Kept as a named export because those call sites import it directly, and it
 * maps onto Astryx more cleanly than the composed form does: Astryx already
 * takes the title, description and labels as props, so this is a straight
 * translation rather than a walk over children.
 *
 * `actionVariant="destructive"` replaces the red Tailwind classes the shadcn
 * version carried — the warning colour now comes from the active theme.
 */
export interface DeleteConfirmDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: string;
  description?: string;
  itemName?: string;
  onConfirm: () => void;
  isConfirming?: boolean;
}

export function DeleteConfirmDialog({
  open,
  onOpenChange,
  title = "Delete Record",
  description,
  itemName,
  onConfirm,
  isConfirming = false,
}: DeleteConfirmDialogProps) {
  return (
    <AstryxAlertDialog
      isOpen={open}
      onOpenChange={(next: boolean) => onOpenChange(next)}
      title={title}
      description={
        description ?? `Are you sure you want to delete ${itemName ?? "this record"}? This action cannot be undone.`
      }
      cancelLabel="Cancel"
      // The label doubles as the progress indicator, the same way the shadcn
      // version did — Astryx's action button has no loading state to drive.
      actionLabel={isConfirming ? "Deleting…" : "Delete"}
      actionVariant="destructive"
      onAction={() => {
        onConfirm();
        onOpenChange(false);
      }}
    />
  );
}

/**
 * Avatar — shadcn surface over Astryx `Avatar`.
 *
 * Radix composes Avatar/AvatarImage/AvatarFallback; Astryx takes `src` and
 * `name` (from which it derives initials) on one component. The sub-components
 * are read for their `src` and fallback text rather than rendered.
 */
import { Children, isValidElement, type ReactElement, type ReactNode } from "react";
import { Avatar as AstryxAvatar } from "@astryxdesign/core/Avatar";

export function AvatarImage(_props: { src?: string; alt?: string; className?: string }) {
  return null;
}

export function AvatarFallback(_props: { children?: ReactNode; className?: string }) {
  return null;
}

export interface AvatarProps {
  children?: ReactNode;
  className?: string;
  src?: string;
  alt?: string;
}

export function Avatar({ children, className, src, alt }: AvatarProps) {
  let imageSrc = src;
  let fallback: string | undefined;

  Children.forEach(children, (child) => {
    if (!isValidElement(child)) return;
    if (child.type === AvatarImage) {
      imageSrc ??= (child.props as { src?: string }).src;
    }
    if (child.type === AvatarFallback) {
      const content = (child as ReactElement<{ children?: ReactNode }>).props.children;
      if (typeof content === "string") fallback = content;
    }
  });

  return <AstryxAvatar src={imageSrc} name={fallback ?? alt} alt={alt} className={className} />;
}

export default Avatar;

