/**
 * DropdownMenu — shadcn surface over Astryx `DropdownMenu`.
 *
 * Radix splits the menu into Root / Trigger / Content / Item and expects the
 * consumer to nest them. Astryx's `DropdownMenu` owns the trigger *and* the
 * popover: it renders a button from a `button` prop and the items as children.
 *
 * So `DropdownMenu` reads its `DropdownMenuTrigger` for the button's label and
 * icon, and passes everything inside `DropdownMenuContent` through as menu
 * children. Radix's structural parts (`Content`, `Group`, `Portal`) become
 * pass-throughs, because Astryx already portals the popover itself.
 *
 * Submenus are the one place this cannot be transparent: Radix builds them from
 * `Sub` + `SubTrigger` + `SubContent`, and Astryx's `DropdownMenuSubMenu` takes
 * the whole submenu as one component. `DropdownMenuSub` therefore reads its own
 * children the same way the root does.
 */
import { Children, isValidElement, useState, type ReactElement, type ReactNode } from "react";
import {
  DropdownMenu as AstryxMenu,
  type DropdownMenuButtonProps,
  DropdownMenuCheckboxItem as AstryxCheckboxItem,
  DropdownMenuItem as AstryxItem,
  DropdownMenuRadioGroup as AstryxRadioGroup,
  DropdownMenuRadioItem as AstryxRadioItem,
  DropdownMenuSubMenu as AstryxSubMenu,
} from "@astryxdesign/core/DropdownMenu";
import { Divider } from "@astryxdesign/core/Divider";
import { Text } from "@astryxdesign/core/Text";

interface PartProps {
  children?: ReactNode;
  className?: string;
}

// Style objects live at module scope rather than inline in JSX: an inline
// style prop opens with two braces, which Handlebars reads as the start of an
// expression and refuses to render.
const LABEL_PADDING: React.CSSProperties = { padding: "0.375rem 0.75rem" };
const SHORTCUT_STYLE: React.CSSProperties = { marginInlineStart: "auto", opacity: 0.6 };

/** Depth-first search for the first element of a given type. */
function find(children: ReactNode, target: unknown): ReactElement | undefined {
  let found: ReactElement | undefined;
  Children.forEach(children, (child) => {
    if (found || !isValidElement(child)) return;
    if (child.type === target) {
      found = child;
      return;
    }
    const nested = (child as ReactElement<{ children?: ReactNode }>).props.children;
    if (nested) found = find(nested, target);
  });
  return found;
}

/**
 * Declarative only — the root reads it to build Astryx's trigger button.
 *
 * `aria-label` and `title` are read as well as `children`: Astryx's button
 * requires a `label`, and when the trigger is a glyph the only place an
 * accessible name can come from is the caller.
 */
export function DropdownMenuTrigger(
  _props: PartProps & { asChild?: boolean; "aria-label"?: string; title?: string }
) {
  return null;
}

/** Astryx portals its own popover, so these are structural pass-throughs. */
export function DropdownMenuContent({ children }: PartProps & { align?: string; sideOffset?: number }) {
  return <>{children}</>;
}

export function DropdownMenuGroup({ children }: PartProps) {
  return <>{children}</>;
}

export function DropdownMenuPortal({ children }: PartProps) {
  return <>{children}</>;
}

export interface DropdownMenuItemProps extends PartProps {
  onSelect?: (event: Event) => void;
  onClick?: () => void;
  disabled?: boolean;
  inset?: boolean;
}

export function DropdownMenuItem({ children, className, onSelect, onClick, disabled }: DropdownMenuItemProps) {
  return (
    <AstryxItem
      className={className}
      label={children}
      isDisabled={disabled}
      onClick={() => {
        onClick?.();
        // Radix hands `onSelect` the DOM event; Astryx has none to give, so a
        // synthetic one keeps the handler's signature honest rather than
        // passing undefined into code that reads `event.preventDefault()`.
        onSelect?.(new Event("select"));
      }}
    />
  );
}

export function DropdownMenuCheckboxItem({
  children,
  checked,
  onCheckedChange,
  disabled,
}: PartProps & {
  checked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  disabled?: boolean;
}) {
  return (
    <AstryxCheckboxItem
      label={children}
      // Astryx names the checked state `value`, not `isChecked`.
      value={checked === true}
      isDisabled={disabled}
      onChange={(next: boolean) => onCheckedChange?.(next)}
    />
  );
}

export function DropdownMenuRadioGroup({
  children,
  value,
  onValueChange,
}: PartProps & { value?: string; onValueChange?: (value: string) => void }) {
  return (
    // `onChange` is required on Astryx's radio group, so it is always supplied
    // — an uncontrolled Radix radio group would otherwise fail to typecheck.
    <AstryxRadioGroup value={value} onChange={(next: string) => onValueChange?.(next)}>
      {children}
    </AstryxRadioGroup>
  );
}

export function DropdownMenuRadioItem({
  children,
  value,
  disabled,
}: PartProps & { value: string; disabled?: boolean }) {
  return <AstryxRadioItem value={value} label={children} isDisabled={disabled} />;
}

/** A section heading. Astryx has no menu-label part; `Text` is the closest. */
export function DropdownMenuLabel({ children, className }: PartProps & { inset?: boolean }) {
  return (
    <div className={className} style={LABEL_PADDING}>
      <Text size="sm" color="secondary">
        {children}
      </Text>
    </div>
  );
}

export function DropdownMenuSeparator({ className }: PartProps) {
  return <Divider className={className} />;
}

/**
 * A right-aligned keyboard hint. Radix styles this purely with classes, so it
 * stays a plain element — there is nothing in Astryx it maps onto, and Kbd
 * would render a key cap the shadcn call sites do not ask for.
 */
export function DropdownMenuShortcut({ children, className }: PartProps) {
  return (
    <span className={className} style={SHORTCUT_STYLE}>
      {children}
    </span>
  );
}

export function DropdownMenuSubTrigger(_props: PartProps & { inset?: boolean }) {
  return null;
}

export function DropdownMenuSubContent({ children }: PartProps) {
  return <>{children}</>;
}

export function DropdownMenuSub({ children }: PartProps) {
  const trigger = find(children, DropdownMenuSubTrigger);
  const label = (trigger?.props as { children?: ReactNode } | undefined)?.children;
  return (
    <AstryxSubMenu label={typeof label === "string" ? label : "More"}>
      {find(children, DropdownMenuSubContent)}
    </AstryxSubMenu>
  );
}

/**
 * Astryx's trigger button, built from whatever the caller put inside
 * `DropdownMenuTrigger`.
 *
 * `label` is required and typed `string` — Astryx has no `children`-as-label
 * escape hatch — so a non-string trigger goes into `icon` instead, with
 * `isIconOnly` so the button sizes for a glyph, and an accessible name taken
 * from the caller's `aria-label` or `title`.
 *
 * **The unwrapping is the part that matters.** Radix's `asChild` means "render
 * my child *as* the trigger", and in a shadcn call site that child is a
 * `<Button>`. Astryx owns the trigger and renders a `<button>` of its own, so
 * passing the child straight through puts one button inside another. That is
 * not merely invalid markup: the HTML parser hoists the inner button out of the
 * outer one, so the DOM React hydrates against is not the tree it rendered,
 * React discards the whole tree and re-renders it on the client, and every page
 * carrying the menu reports a hydration failure. Mounting the application shell
 * is what first rendered this adapter at all, which is how a defect that had
 * been generated into every application became visible.
 *
 * Unwrapping one level is the faithful reading of `asChild`, not a workaround:
 * the child's *content* becomes the trigger's content, and the props that say
 * how the trigger should look and be announced move onto Astryx's button, which
 * is the element that now carries them. `components/ui/button` already resolves
 * the same conflict the same way — a non-link `asChild` renders its children
 * rather than nesting them.
 *
 * A named function rather than an inline object because the JSX would open
 * with two braces, which Handlebars reads as the start of an expression.
 */
function triggerButton(trigger: ReactElement | undefined): DropdownMenuButtonProps {
  const props = (trigger?.props ?? {}) as {
    children?: ReactNode;
    asChild?: boolean;
    "aria-label"?: string;
    title?: string;
  };

  let content = props.children;
  let label = props["aria-label"] ?? props.title;
  let variant: DropdownMenuButtonProps["variant"];

  // A single element child is unwrapped when the caller said `asChild`, and
  // also when it is a bare `<button>` — nesting that is invalid whether or not
  // the Radix prop was written.
  const child = isValidElement(content) ? content : undefined;
  if (child && (props.asChild === true || child.type === "button")) {
    const childProps = child.props as {
      children?: ReactNode;
      variant?: DropdownMenuButtonProps["variant"];
      "aria-label"?: string;
      title?: string;
    };
    content = childProps.children;
    label = label ?? childProps["aria-label"] ?? childProps.title;
    variant = childProps.variant;
  }

  if (typeof content === "string") {
    return { label: content, variant };
  }

  return {
    label: label ?? "Open menu",
    icon: content,
    isIconOnly: true,
    variant: variant ?? "ghost",
  };
}

export interface DropdownMenuProps {
  children?: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export function DropdownMenu({ children, open, defaultOpen = false, onOpenChange }: DropdownMenuProps) {
  // Controlled when `open` is supplied, uncontrolled otherwise — the same
  // contract Radix offers, so existing call sites keep working either way.
  const [internal, setInternal] = useState(defaultOpen);
  const isOpen = open ?? internal;

  const trigger = find(children, DropdownMenuTrigger);

  return (
    <AstryxMenu
      isMenuOpen={isOpen}
      onOpenChange={(next: boolean) => {
        if (open === undefined) setInternal(next);
        onOpenChange?.(next);
      }}
      button={triggerButton(trigger)}
      hasChevron={false}
    >
      {find(children, DropdownMenuContent) ?? children}
    </AstryxMenu>
  );
}

export default DropdownMenu;

/**
 * EmptyState — shadcn-era local component over Astryx `EmptyState`.
 *
 * The generated list views render this for the zero-row case. Astryx requires
 * a `title`, so the adapter supplies a neutral default rather than rendering an
 * untitled state.
 */
import type { ReactNode } from "react";
import { EmptyState as AstryxEmptyState } from "@astryxdesign/core/EmptyState";

export interface EmptyStateProps {
  title?: string;
  description?: string;
  icon?: ReactNode;
  action?: ReactNode;
  className?: string;
}

export function EmptyState({ title = "Nothing to show", description, icon, action, className }: EmptyStateProps) {
  return (
    <AstryxEmptyState title={title} description={description} icon={icon} actions={action} className={className} />
  );
}

export default EmptyState;

/**
 * Icon — lucide resolution, Astryx rendering.
 *
 * These two do different jobs and both are needed. The dictionary stores icon
 * *names* — `sys_table.icon`, `sys_category.icon`, `sys_window.icon`, written
 * by the seed from an entity's `icon` in the model and by an administrator at
 * runtime — so the component must resolve an arbitrary name to a glyph, which
 * is what lucide gives us and Astryx does not: `@astryxdesign/core/Icon`
 * accepts a component or one of 26 semantic names (`close`, `chevronDown`, …),
 * not a free-form lucide name.
 *
 * So: lucide resolves the name, Astryx renders the result. Colour and size then
 * come from the active theme rather than from Tailwind classes, which is the
 * whole point of the swap.
 *
 * **How the name is looked up is the part that was wrong.** It used to be
 * `LucideIcons[name]` over `import * as LucideIcons`, and that is two defects
 * in one line:
 *
 * - The barrel is keyed by lucide's **PascalCase export names** (`FlaskConical`,
 *   `ShieldCheck`), while every name the dictionary actually holds is lucide's
 *   own **kebab-case id** — that is what a model's `icon: flask-conical`
 *   writes, and the language definition names `flask-conical` as the spelling
 *   to use. The lookup missed on all of them and fell through to the
 *   placeholder, so a model that named an icon rendered exactly like one that
 *   named none.
 * - A namespace import of a barrel cannot be tree-shaken, so the whole icon set
 *   was downloaded by whichever screen imported it — the dashboard, which draws
 *   a handful.
 *
 * `dynamicIconImports` is one lazy import per icon, keyed by those kebab ids. A
 * name is normalised to that form, fetched on demand, and only the icons a
 * screen actually names are ever downloaded.
 *
 * It is not quite the same set as the barrel: lucide 0.312 exports 1475 icon
 * components and lists 1401 dynamic ids, so a handful of names the barrel could
 * render are unreachable this way. None of them is a name a seed writes — those
 * are lucide's own ids, which are exactly this map's keys — but a hand-typed
 * `sys_table.icon` can land on one, and it renders the placeholder.
 */
import dynamicIconImports from "lucide-react/dynamicIconImports";
import {
  type ComponentType,
  type CSSProperties,
  type SVGProps,
  lazy,
  Suspense,
  useMemo,
} from "react";
import { Icon as AstryxIcon } from "@astryxdesign/core/Icon";

type IconComponent = ComponentType<SVGProps<SVGSVGElement>>;
type IconModules = Record<string, () => Promise<{ default: IconComponent }>>;

const ICON_IMPORTS = dynamicIconImports as unknown as IconModules;

export interface IconProps {
  name: string;
  /**
   * Pixel size, kept for call-site compatibility. Astryx sizes from a scale, so
   * this is mapped to the nearest step rather than applied literally — a theme
   * that changes its icon scale should move every icon with it.
   */
  size?: number;
  className?: string;
  style?: CSSProperties;
  /** Set only when the icon carries meaning no adjacent text conveys. */
  label?: string;
}

/**
 * Whatever the dictionary wrote, in lucide's own spelling.
 *
 * Accepts the three forms a row is realistically written in — `LayoutGrid`,
 * `layout_grid`, `layout-grid` — because a seed writes the third, an
 * administrator typing into the icon field may write either of the first two,
 * and none of that is worth a migration.
 *
 * Two rules exist because the obvious version of this function got them wrong,
 * both ways:
 *
 * - **A name that is already an id is returned untouched.** Without that, the
 *   digit rule splits ids that were correct on arrival: `grid-2x2` becomes
 *   `grid-2x-2`, so an icon that used to render stops. Asking the map first is
 *   also the right order — the common case needs no transformation at all.
 * - **A run of capitals splits before the last one, not after the first.**
 *   `AArrowDown` is `a-arrow-down` and `ArrowDownAZ` is `arrow-down-a-z`; a
 *   single `([a-z])([A-Z])` boundary produces `aarrow-down` and `arrow-down-az`,
 *   neither of which is an id.
 */
export function normalizeIconName(name: string): string {
  const trimmed = name.trim();
  // Already one of lucide's own ids — the common case, since that is what the
  // seeds write.
  if (Object.hasOwn(ICON_IMPORTS, trimmed)) return trimmed;

  return trimmed
    .replace(/[\s_]+/g, "-")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1-$2")
    .replace(/([a-z\d])([A-Z])/g, "$1-$2")
    .replace(/([A-Za-z])(\d)/g, "$1-$2")
    .replace(/([A-Z])(?=[A-Z])/g, "$1-")
    .toLowerCase()
    .replace(/-+/g, "-");
}

// Style objects live at module scope rather than inline in JSX: an inline
// style prop opens with two braces, which Handlebars reads as the start of an
// expression and refuses to render.
function placeholderStyle(size: number, incoming?: CSSProperties): CSSProperties {
  return {
    width: `${size}px`,
    height: `${size}px`,
    fontSize: `${size}px`,
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    ...incoming,
  };
}

/**
 * The placeholder, for a name lucide does not have — and for the moment an
 * icon that does is still in flight.
 *
 * One component for both paths deliberately: an icon that resolves late must
 * not move the layout when it arrives, so the fallback occupies the same box.
 */
function IconPlaceholder({
  size,
  className,
  style,
  label,
}: {
  size: number;
  className?: string;
  style?: CSSProperties;
  label?: string;
}) {
  return (
    <span
      className={className}
      aria-hidden={label ? undefined : true}
      aria-label={label}
      role={label ? "img" : undefined}
      style={placeholderStyle(size, style)}
    >
      ▫
    </span>
  );
}

/**
 * One `lazy()` per icon name, not per render.
 *
 * `React.lazy` returns a new component type on every call, and a new type
 * unmounts and remounts the subtree — building one inside the render would make
 * every icon re-fetch its own chunk on every parent render.
 */
const lazyIcons = new Map<string, IconComponent>();

function getLazyIcon(id: string): IconComponent | null {
  const cached = lazyIcons.get(id);
  if (cached) return cached;

  const loader = ICON_IMPORTS[id];
  if (!loader) return null;

  const component = lazy(loader);
  lazyIcons.set(id, component);
  return component;
}

/** Astryx's four steps, in pixels at a 16px root: 12, 16, 20, 24. */
function nearestSize(px: number): "xsm" | "sm" | "md" | "lg" {
  if (px <= 14) return "xsm";
  if (px <= 18) return "sm";
  if (px <= 22) return "md";
  return "lg";
}

export function Icon({ name, size = 16, className, style, label }: IconProps) {
  const resolved = useMemo(() => getLazyIcon(normalizeIconName(name)), [name]);

  if (!resolved) {
    // An unknown name means the dictionary holds an icon this build does not
    // have. Rendering a placeholder rather than throwing keeps one bad
    // metadata row from blanking the screen it appears on.
    return <IconPlaceholder size={size} className={className} style={style} label={label} />;
  }

  return (
    <Suspense
      fallback={<IconPlaceholder size={size} className={className} style={style} label={label} />}
    >
      <AstryxIcon
        icon={resolved}
        size={nearestSize(size)}
        className={className}
        style={style}
        {...(label ? { label } : {})}
      />
    </Suspense>
  );
}

/**
 * Every name `Icon` will resolve — lucide's own ids, which is the spelling the
 * dictionary stores. Used by the icon picker in admin forms.
 */
export function getAvailableIconNames(): string[] {
  return Object.keys(ICON_IMPORTS);
}

export default Icon;

/**
 * Input — shadcn surface over Astryx `TextInput` / `NumberInput`.
 *
 * The gap here is the widest of any primitive. shadcn's `Input` is a thin
 * wrapper over `<input>`: uncontrolled by default, `onChange(event)`, no label.
 * Astryx's `TextInput` is a controlled field: `value` and `label` are required
 * and `onChange` receives `(value, event)`.
 *
 * This adapter bridges both directions so `dynamic-form.tsx` and the admin
 * editors keep working unchanged:
 *
 *  * `value ?? defaultValue ?? ""` — an uncontrolled call site still renders.
 *  * `onChange` is re-wrapped so callers reading `e.target.value` still work.
 *  * `label` falls back to `aria-label` or `placeholder`, because Astryx
 *    requires a non-empty label for accessibility and silently rendering an
 *    empty one would defeat that.
 */
import type { ChangeEvent } from "react";
import { NumberInput } from "@astryxdesign/core/NumberInput";
import { TextInput } from "@astryxdesign/core/TextInput";

export interface InputProps {
  type?: string;
  value?: string | number;
  defaultValue?: string | number;
  placeholder?: string;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  className?: string;
  id?: string;
  name?: string;
  "aria-label"?: string;
  onChange?: (event: ChangeEvent<HTMLInputElement>) => void;
  onBlur?: () => void;
  /**
   * Native attributes the login and admin forms set. `NumberInput` declares
   * `autoComplete` and `step` explicitly; `TextInput` spreads its rest props
   * onto the `<input>`, so the rest arrive the same way they did under shadcn.
   * Autofocus is Astryx's `hasAutoFocus`, translated below.
   */
  autoComplete?: string;
  autoFocus?: boolean;
  maxLength?: number;
  step?: number;
}

/**
 * `autoComplete` and `maxLength` for the text input.
 *
 * `TextInputProps` does not declare them — Astryx types its own props and
 * leaves the native surface to the rest spread, which does reach the `<input>`.
 * Bridging it here keeps a browser-filled password field and a length-capped
 * code field working, which is what those two attributes are actually for.
 * `NumberInput` declares `autoComplete` itself, so this is the text path only.
 */
function nativeAttrs(autoComplete?: string, maxLength?: number): Record<string, unknown> {
  const attrs: Record<string, unknown> = {};
  if (autoComplete !== undefined) attrs.autoComplete = autoComplete;
  if (maxLength !== undefined) attrs.maxLength = maxLength;
  return attrs;
}

/** A controlled number field's value: a number, or `null` for empty. */
export function toNumberOrNull(current: string | number | null | undefined): number | null {
  if (typeof current === "number") return Number.isNaN(current) ? null : current;
  if (current === null || current === undefined || current.trim() === "") return null;
  const parsed = Number(current);
  return Number.isNaN(parsed) ? null : parsed;
}

export function Input({
  type = "text",
  value,
  defaultValue,
  placeholder,
  disabled,
  readOnly,
  required,
  className,
  id,
  name,
  "aria-label": ariaLabel,
  onChange,
  onBlur,
  autoComplete,
  autoFocus,
  maxLength,
  step,
}: InputProps) {
  const label = ariaLabel ?? placeholder ?? name ?? id ?? "Value";
  const current = value ?? defaultValue ?? "";

  if (type === "number") {
    return (
      <NumberInput
        label={label}
        isLabelHidden
        // Empty is `null`, which Astryx renders as an empty field. It used to
        // be coerced to 0, so an unset field displayed a 0 the form did not
        // hold, and a keystroke that the form rejected snapped back to it.
        value={toNumberOrNull(current)}
        placeholder={placeholder}
        isDisabled={disabled || readOnly}
        isRequired={required}
        className={className}
        id={id}
        htmlName={name}
        autoComplete={autoComplete}
        hasAutoFocus={autoFocus}
        step={step}
        // Astryx's NumberInput reports only the parsed value, with no DOM
        // event. Call sites read `e.target.value`, so a minimal event-shaped
        // object carrying the same string is synthesised rather than dropping
        // the callback. Anything reading further into the event (currentTarget,
        // key modifiers) would need the real thing — no generated call site
        // does, and Phase C removes this shim entirely.
        //
        // `valueAsNumber` is part of that shape, not an extra: `dynamic-form`
        // reads it for every integer and amount field. Without it the read was
        // `undefined`, which is not NaN, so the form stored `undefined` and
        // JSON.stringify dropped the field — every number typed into a create
        // or edit form was silently discarded.
        onChange={(next: number | null) =>
          onChange?.({
            target: {
              value: next === null ? "" : String(next),
              valueAsNumber: next === null ? Number.NaN : next,
              name: name ?? "",
            },
          } as ChangeEvent<HTMLInputElement>)
        }
        onBlur={onBlur}
      />
    );
  }

  return (
    <TextInput
      label={label}
      // Call sites render their own <Label>; keeping Astryx's label in the
      // accessibility tree but out of the layout avoids showing it twice.
      isLabelHidden
      type={type as never}
      value={String(current)}
      placeholder={placeholder}
      isDisabled={disabled || readOnly}
      isRequired={required}
      className={className}
      id={id}
      htmlName={name}
      hasAutoFocus={autoFocus}
      {...nativeAttrs(autoComplete, maxLength)}
      onChange={(_next: string, event: ChangeEvent<HTMLInputElement>) => onChange?.(event)}
      onBlur={onBlur}
    />
  );
}

export default Input;

/**
 * Label — plain `<label>`, deliberately not Astryx `Field`.
 *
 * Astryx's `Field` owns label, required marker, help text and error state
 * together, and the input adapters already pass their own (hidden) label to
 * the underlying Astryx control. Mapping this component onto `Field` as well
 * would nest two labelled wrappers around every input and announce the label
 * twice to screen readers.
 *
 * So this stays a bare `<label>` through Phase B. Phase C is where
 * `dynamic-form.tsx` moves to `Field` properly and both this component and the
 * hidden labels in the input adapters go away — that is the rebuild §7.5 calls
 * for, not a rename.
 */
import type { ReactNode } from "react";

export interface LabelProps {
  children?: ReactNode;
  /** Native tooltip text; several admin forms use it for field hints. */
  title?: string;
  htmlFor?: string;
  className?: string;
}

export function Label({ children, htmlFor, className }: LabelProps) {
  return (
    <label htmlFor={htmlFor} className={className}>
      {children}
    </label>
  );
}

export default Label;

/**
 * Layout and typography primitives — the Astryx implementation.
 *
 * Same prop surface as the NestJS stack's `layout.tsx`, which renders these
 * with Tailwind classes. The shared screens under `components/admin/*`,
 * `components/forms/*`, `components/tables/*` and `routes/*` compose these
 * instead of naming classes, so one set of screens renders under both stacks
 * and this stack needs no Tailwind at all.
 *
 * Everything here is a thin translation of the shared vocabulary onto Astryx's:
 * `align`/`justify` become `vAlign`/`hAlign`, and the spacing steps are already
 * Astryx's `SpacingStep` values — that is why the shared type is exactly those
 * eleven numbers rather than Tailwind's fuller scale.
 */
import type { ElementType, HTMLAttributes, ReactNode } from "react";
import { Grid as AstryxGrid } from "@astryxdesign/core/Grid";
import { HStack as AstryxHStack } from "@astryxdesign/core/HStack";
import { VStack as AstryxVStack } from "@astryxdesign/core/VStack";
import { Heading as AstryxHeading } from "@astryxdesign/core/Heading";
import { Text as AstryxText } from "@astryxdesign/core/Text";

export type Space = 0 | 0.5 | 1 | 1.5 | 2 | 3 | 4 | 5 | 6 | 8 | 10;
export type Align = "start" | "center" | "end" | "stretch";
export type Justify = "start" | "center" | "end" | "between" | "around";

export interface StackProps extends Omit<HTMLAttributes<HTMLElement>, "color"> {
  children?: ReactNode;
  gap?: Space;
  padding?: Space;
  paddingInline?: Space;
  paddingBlock?: Space;
  align?: Align;
  justify?: Justify;
  grow?: boolean;
  wrap?: boolean;
  fullWidth?: boolean;
  as?: ElementType;
}

// `Justify` needs no translation: the shared vocabulary was chosen to match
// Astryx's `justifyContent` names exactly (start/center/end/between/around).

/**
 * `grow` has no Astryx prop — it is the parent's flex behaviour, not the
 * child's layout — so it stays an inline style. This is the one place the
 * translation is not a rename.
 */
const GROW: React.CSSProperties = { flex: 1 };

/**
 * Narrow the leftover HTML attributes to what Astryx's `BaseProps` accepts.
 *
 * `BaseProps` omits a long list of rarely-used HTML attributes (`title`,
 * `color`, `lang`, `popover`, …) that `HTMLAttributes` declares, so spreading
 * the rest wholesale does not typecheck. These are the ones call sites actually
 * pass; anything else is dropped rather than smuggled through with a cast.
 */
function passThrough(rest: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (
      key === "className" ||
      key === "id" ||
      key === "role" ||
      key === "onClick" ||
      key.startsWith("data-") ||
      key.startsWith("aria-")
    ) {
      out[key] = value;
    }
  }
  return out;
}

export function HStack({
  children,
  gap,
  padding,
  paddingInline,
  paddingBlock,
  align,
  justify,
  grow,
  wrap,
  fullWidth,
  style,
  as: _as,
  ...rest
}: StackProps) {
  return (
    <AstryxHStack
      gap={gap}
      padding={padding}
      paddingInline={paddingInline}
      paddingBlock={paddingBlock}
      vAlign={align}
      hAlign={justify}
      wrap={wrap ? "wrap" : undefined}
      width={fullWidth ? "100%" : undefined}
      style={grow ? { ...GROW, ...style } : style}
      {...passThrough(rest)}
    >
      {children}
    </AstryxHStack>
  );
}

export function VStack({
  children,
  gap,
  padding,
  paddingInline,
  paddingBlock,
  align,
  justify,
  grow,
  wrap,
  fullWidth,
  style,
  as: _as,
  ...rest
}: StackProps) {
  return (
    <AstryxVStack
      gap={gap}
      padding={padding}
      paddingInline={paddingInline}
      paddingBlock={paddingBlock}
      // A column's cross axis is horizontal, so the shared `align` maps to
      // `hAlign` here and to `vAlign` on the row above — the same reversal
      // Tailwind's `items-*` performs implicitly.
      hAlign={align}
      vAlign={justify}
      wrap={wrap ? "wrap" : undefined}
      width={fullWidth ? "100%" : undefined}
      style={grow ? { ...GROW, ...style } : style}
      {...passThrough(rest)}
    >
      {children}
    </AstryxVStack>
  );
}

export interface GridProps extends Omit<HTMLAttributes<HTMLDivElement>, "color"> {
  children?: ReactNode;
  columns?: 1 | 2 | 3 | 4 | 6 | 12;
  gap?: Space;
  padding?: Space;
  paddingInline?: Space;
  paddingBlock?: Space;
  fullWidth?: boolean;
}

export function Grid({
  children,
  columns = 1,
  gap,
  padding,
  paddingInline,
  paddingBlock,
  fullWidth,
  ...rest
}: GridProps) {
  // Astryx's `Grid` takes gaps but not padding — it is a track definition, not
  // a box. Wrapping in a padded `VStack` keeps the padding props working
  // without pretending the grid itself has an inner edge.
  const grid = (
    <AstryxGrid
      columns={columns}
      gap={gap}
      width={fullWidth ? "100%" : undefined}
      {...passThrough(rest)}
    >
      {children}
    </AstryxGrid>
  );
  const padded = padding !== undefined || paddingInline !== undefined || paddingBlock !== undefined;
  return padded ? (
    <AstryxVStack padding={padding} paddingInline={paddingInline} paddingBlock={paddingBlock}>
      {grid}
    </AstryxVStack>
  ) : (
    grid
  );
}

// ---------------------------------------------------------------------------
// Typography
// ---------------------------------------------------------------------------

export type TextSize = "xs" | "sm" | "base" | "lg" | "xl";
export type TextWeight = "normal" | "medium" | "semibold" | "bold";
export type TextColor = "primary" | "secondary" | "accent" | "success" | "warning" | "danger";

export interface TextProps extends Omit<HTMLAttributes<HTMLElement>, "color"> {
  children?: ReactNode;
  size?: TextSize;
  weight?: TextWeight;
  color?: TextColor;
  block?: boolean;
  truncate?: boolean;
  uppercase?: boolean;
  as?: ElementType;
}

/** The shared scale onto Astryx's — `xs` is Astryx's `xsm`. */
const SIZE = {
  xs: "xsm",
  sm: "sm",
  base: "base",
  lg: "lg",
  xl: "xl",
} as const;

/**
 * Astryx's `TextColor` has no success/warning/danger, so those three resolve
 * through the `Icon` palette's semantic names instead, applied as a colour
 * variable. The alternative — dropping them to `primary` — would render a
 * validation error in body-text colour, which is the one case where the colour
 * is the message.
 */
const SEMANTIC_COLOR: Record<"success" | "warning" | "danger", string> = {
  success: "var(--astryx-color-text-success, #0D8626)",
  warning: "var(--astryx-color-text-warning, #E9AF08)",
  danger: "var(--astryx-color-text-error, #E3193B)",
};

const ASTRYX_COLOR = {
  primary: "primary",
  secondary: "secondary",
  accent: "accent",
} as const;

const UPPERCASE: React.CSSProperties = { textTransform: "uppercase", letterSpacing: "0.05em" };
/**
 * Astryx's `WordBreak` is `break-word | break-all` — it has no ellipsis mode,
 * so truncation is CSS here rather than a prop.
 */
const TRUNCATE: React.CSSProperties = {
  overflow: "hidden",
  textOverflow: "ellipsis",
  whiteSpace: "nowrap",
};

export function Text({
  children,
  size,
  weight,
  color,
  block,
  truncate,
  uppercase,
  style,
  // Astryx's `Text` picks its own element from `type`; there is no `as`
  // escape hatch, so this is accepted for call-site compatibility and
  // dropped rather than forwarded into a prop that does not exist.
  as: _as,
  ...rest
}: TextProps) {
  const semantic = color && color in SEMANTIC_COLOR ? SEMANTIC_COLOR[color as never] : undefined;
  const merged: React.CSSProperties = {
    ...(uppercase ? UPPERCASE : null),
    ...(truncate ? TRUNCATE : null),
    ...(semantic ? { color: semantic } : null),
    ...style,
  };

  return (
    <AstryxText
      size={size ? SIZE[size] : undefined}
      weight={weight}
      color={color && color in ASTRYX_COLOR ? ASTRYX_COLOR[color as never] : undefined}
      display={block ? "block" : undefined}
      style={merged}
      {...passThrough(rest)}
    >
      {children}
    </AstryxText>
  );
}

export interface HeadingProps extends Omit<HTMLAttributes<HTMLHeadingElement>, "color"> {
  children?: ReactNode;
  level: 1 | 2 | 3 | 4 | 5 | 6;
  color?: TextColor;
  /** Small-caps section labels — the shape most admin sub-headings take. */
  uppercase?: boolean;
  truncate?: boolean;
}

export function Heading({
  children,
  level,
  color,
  uppercase,
  truncate,
  style,
  ...rest
}: HeadingProps) {
  const semantic = color && color in SEMANTIC_COLOR ? SEMANTIC_COLOR[color as never] : undefined;
  const merged: React.CSSProperties = {
    ...(uppercase ? UPPERCASE : null),
    ...(truncate ? TRUNCATE : null),
    ...(semantic ? { color: semantic } : null),
    ...style,
  };
  return (
    <AstryxHeading level={level} style={merged} {...passThrough(rest)}>
      {children}
    </AstryxHeading>
  );
}

const SPACER: React.CSSProperties = { flex: 1 };

/** Pushes siblings apart in a flex container. */
export function Spacer() {
  return <div style={SPACER} />;
}

// ---------------------------------------------------------------------------
// Box — the non-flex container
// ---------------------------------------------------------------------------

/**
 * A plain block with spacing, a border, a radius and a background.
 *
 * `HStack` / `VStack` / `Grid` cover elements that lay their children out.
 * `Box` covers the rest — the `<div className="mb-2 p-4 border rounded-lg
 * bg-card">` shape, which is most of them. Without it there is no way to say
 * "padded, bordered card" without naming a Tailwind class, and Phase C cannot
 * finish.
 *
 * **Every value is semantic, never a palette entry.** `bg="subtle"` rather than
 * `bg-gray-50`, `border="default"` rather than `border-gray-200`. That is the
 * point of the port: a hardcoded shade survives a theme switch unchanged, and
 * this app ships seven themes.
 */
export type BoxBackground = "none" | "surface" | "subtle" | "muted" | "accent" | "inverse";
export type BoxBorder = "none" | "default" | "strong" | "accent";
export type BoxSide = "all" | "top" | "bottom" | "start" | "end" | "block" | "inline";
export type BoxRadius = "none" | "sm" | "md" | "lg" | "full";
export type BoxWidth = "auto" | "full" | "fit" | "min" | "sm" | "md" | "lg" | "xl";

export interface BoxProps extends Omit<HTMLAttributes<HTMLElement>, "color"> {
  children?: ReactNode;
  padding?: Space;
  paddingInline?: Space;
  paddingBlock?: Space;
  margin?: Space;
  marginTop?: Space;
  marginBottom?: Space;
  marginInline?: Space;
  bg?: BoxBackground;
  border?: BoxBorder;
  /** Which edges the border is drawn on. @default "all" */
  borderSide?: BoxSide;
  radius?: BoxRadius;
  width?: BoxWidth;
  /**
   * A ceiling, not a size. Separate from `width` because `w-full max-w-md` is
   * two different constraints on one element, and collapsing them onto a single
   * prop silently drops one.
   */
  maxWidth?: BoxWidth;
  fullHeight?: boolean;
  /** Scroll rather than clip when the content overflows. */
  scrollable?: boolean;
  grow?: boolean;
  as?: ElementType;
}

/**
 * Theme tokens with a literal fallback.
 *
 * Astryx publishes these as CSS custom properties, so the active theme drives
 * them at runtime. The fallbacks cover the moment before the stylesheet applies
 * and anyone rendering a component in isolation.
 */
const BACKGROUND: Record<BoxBackground, string | undefined> = {
  none: undefined,
  surface: "var(--astryx-color-background-primary, light-dark(#FFFFFF, #1C1E21))",
  subtle: "var(--astryx-color-background-secondary, light-dark(#F5F6F7, #242629))",
  muted: "var(--astryx-color-background-tertiary, light-dark(#EBEDF0, #2C2F33))",
  accent: "var(--astryx-color-background-accent, light-dark(#E7F0FE, #17293F))",
  inverse: "var(--astryx-color-background-inverse, light-dark(#0A1317, #DFE2E5))",
};

const BORDER_COLOR: Record<BoxBorder, string | undefined> = {
  none: undefined,
  default: "var(--astryx-color-border-primary, light-dark(#DFE2E5, #3A3D42))",
  strong: "var(--astryx-color-border-secondary, light-dark(#A4B0BC, #6F747C))",
  accent: "var(--astryx-color-border-accent, light-dark(#0064E0, #2694FE))",
};

const RADIUS: Record<BoxRadius, string> = {
  none: "0",
  sm: "0.25rem",
  md: "0.375rem",
  lg: "0.5rem",
  full: "9999px",
};

const WIDTH: Record<BoxWidth, string | undefined> = {
  auto: undefined,
  full: "100%",
  fit: "fit-content",
  min: "0",
  sm: "24rem",
  md: "28rem",
  lg: "32rem",
  xl: "36rem",
};

/** Astryx's spacing steps in rem, matching `SpacingStep`. */
function rem(step: Space): string {
  return `${step * 0.25}rem`;
}

/** Inline object literals in JSX open with two braces, which Handlebars eats. */
function merge(computed: React.CSSProperties, incoming?: React.CSSProperties) {
  return incoming ? { ...computed, ...incoming } : computed;
}

function boxStyle(p: BoxProps): React.CSSProperties {
  const s: React.CSSProperties = {};

  if (p.padding !== undefined) s.padding = rem(p.padding);
  if (p.paddingInline !== undefined) s.paddingInline = rem(p.paddingInline);
  if (p.paddingBlock !== undefined) s.paddingBlock = rem(p.paddingBlock);
  if (p.margin !== undefined) s.margin = rem(p.margin);
  if (p.marginTop !== undefined) s.marginTop = rem(p.marginTop);
  if (p.marginBottom !== undefined) s.marginBottom = rem(p.marginBottom);
  if (p.marginInline !== undefined) s.marginInline = rem(p.marginInline);

  if (p.bg && p.bg !== "none") s.background = BACKGROUND[p.bg];

  if (p.border && p.border !== "none") {
    const rule = `1px solid ${BORDER_COLOR[p.border]}`;
    switch (p.borderSide ?? "all") {
      case "top":
        s.borderTop = rule;
        break;
      case "bottom":
        s.borderBottom = rule;
        break;
      case "start":
        s.borderInlineStart = rule;
        break;
      case "end":
        s.borderInlineEnd = rule;
        break;
      case "block":
        s.borderBlock = rule;
        break;
      case "inline":
        s.borderInline = rule;
        break;
      default:
        s.border = rule;
    }
  }

  if (p.radius) s.borderRadius = RADIUS[p.radius];
  if (p.width) s.width = WIDTH[p.width];
  if (p.maxWidth) s.maxWidth = WIDTH[p.maxWidth];
  if (p.fullHeight) s.height = "100%";
  if (p.scrollable) s.overflow = "auto";
  if (p.grow) s.flex = 1;

  return s;
}

export function Box({
  children,
  className,
  style,
  as: Element = "div",
  padding,
  paddingInline,
  paddingBlock,
  margin,
  marginTop,
  marginBottom,
  marginInline,
  bg,
  border,
  borderSide,
  radius,
  width,
  maxWidth,
  fullHeight,
  scrollable,
  grow,
  ...rest
}: BoxProps) {
  const computed = boxStyle({
    padding,
    paddingInline,
    paddingBlock,
    margin,
    marginTop,
    marginBottom,
    marginInline,
    bg,
    border,
    borderSide,
    radius,
    width,
    maxWidth,
    fullHeight,
    scrollable,
    grow,
  });
  return (
    <Element className={className} style={merge(computed, style)} {...rest}>
      {children}
    </Element>
  );
}

/**
 * MobileSidebar — shadcn surface over Astryx `MobileNav`.
 *
 * The shadcn version is a Radix Dialog dressed as a drawer: a fixed overlay, a
 * hand-positioned panel, slide-in animation classes, and a close button the
 * call site never sees. `MobileNav` is that drawer as a component — it owns the
 * overlay, the slide, the focus trap, the Escape handler and the close affordance.
 *
 * So this is close to a straight delegation. The one thing worth keeping is the
 * `md:hidden` behaviour: the shadcn drawer was hidden on desktop by a Tailwind
 * class, and `MobileNav` has no viewport prop, so the call site's own
 * responsive logic (it only sets `open` on small screens) is what governs.
 * That was already true — the class was belt and braces — but it is now the
 * only mechanism, so it is stated here rather than left implicit.
 */
import type { ReactNode } from "react";
import { MobileNav } from "@astryxdesign/core/MobileNav";

export interface MobileSidebarProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  children: ReactNode;
  /** Rendered above the navigation content — a logo or a title. */
  header?: ReactNode;
}

export function MobileSidebar({ open, onOpenChange, children, header }: MobileSidebarProps) {
  return (
    <MobileNav isOpen={open} onOpenChange={onOpenChange} label="Navigation menu" side="start" header={header}>
      {children}
    </MobileNav>
  );
}

export default MobileSidebar;

/**
 * ScrollArea — native overflow, not a component.
 *
 * This is the one primitive in the set with no Astryx counterpart, and that is
 * deliberate on Astryx's side rather than a gap: its scrollable surfaces
 * (`Table`, `SideNav`, `Layer`) use native overflow, because since Radix
 * shipped, `scrollbar-width` and `scrollbar-color` became styleable in every
 * browser the generated app supports. Radix's ScrollArea exists to draw a
 * custom scrollbar over a hidden native one; there is nothing left for it to
 * fix.
 *
 * So this keeps the call surface — `<ScrollArea>` and `<ScrollBar>` are
 * imported by the admin shell and the sidebar — and implements it with the
 * native scroller. That also fixes a real Radix behaviour: a custom scrollbar
 * does not respond to the OS "always show scrollbars" accessibility setting.
 */
import { forwardRef, type HTMLAttributes, type ReactNode } from "react";

export interface ScrollAreaProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
  /** Which axis may scroll. @default "vertical" */
  orientation?: "vertical" | "horizontal" | "both";
}

// Style objects live at module scope rather than inline in JSX: an inline
// style prop opens with two braces, which Handlebars reads as the start of an
// expression and refuses to render.
function scrollStyle(
  orientation: "vertical" | "horizontal" | "both",
  incoming?: React.CSSProperties
): React.CSSProperties {
  return {
    overflowY: orientation === "horizontal" ? "hidden" : "auto",
    overflowX: orientation === "vertical" ? "hidden" : "auto",
    // Thin, theme-coloured scrollbars — the effect Radix's custom bar was
    // there to produce, from two CSS properties.
    scrollbarWidth: "thin",
    ...incoming,
  };
}

export const ScrollArea = forwardRef<HTMLDivElement, ScrollAreaProps>(
  ({ className, children, orientation = "vertical", style, ...props }, ref) => (
    <div ref={ref} className={className} style={scrollStyle(orientation, style)} {...props}>
      {children}
    </div>
  )
);
ScrollArea.displayName = "ScrollArea";

/**
 * The scrollbar is drawn by the browser, so there is nothing to render here.
 * Kept as an export because the shadcn call sites place it inside `ScrollArea`,
 * and removing it would mean editing them for no behavioural gain.
 */
export function ScrollBar(_props: {
  orientation?: "vertical" | "horizontal";
  className?: string;
}) {
  return null;
}

export default ScrollArea;

/**
 * Select — shadcn surface over Astryx `Selector`.
 *
 * This is the largest structural difference in the set. shadcn/Radix compose a
 * select out of five elements:
 *
 * ```tsx
 * <Select value={v} onValueChange={set}>
 *   <SelectTrigger><SelectValue placeholder="Pick" /></SelectTrigger>
 *   <SelectContent>
 *     <SelectItem value="a">A</SelectItem>
 *   </SelectContent>
 * </Select>
 * ```
 *
 * Astryx's `Selector` takes a flat `options` array instead. Rather than force
 * every call site to change in the same commit, `Select` walks its children,
 * collects the `SelectItem`s, and hands the resulting array to `Selector`. The
 * sub-components render nothing themselves — they exist purely as a
 * declarative description that this component reads.
 *
 * Phase C should replace these call sites with `Selector` directly; this
 * adapter is what buys the time to do that incrementally.
 */
import { Children, isValidElement, type ReactElement, type ReactNode } from "react";
import { Selector } from "@astryxdesign/core/Selector";

interface SelectOption {
  value: string;
  label: string;
}

export interface SelectProps {
  value?: string;
  defaultValue?: string;
  disabled?: boolean;
  required?: boolean;
  name?: string;
  "aria-label"?: string;
  className?: string;
  children?: ReactNode;
  onValueChange?: (value: string) => void;
}

/**
 * Structural parts accept the ordinary HTML attributes their Radix originals
 * did — `className`, `style`, `title`, `onClick`, `aria-*`. The classes are
 * inert once Phase C removes Tailwind, but the call sites in
 * `components/admin/*` pass them today and an adapter those call sites cannot
 * typecheck against is not a finished adapter.
 */
interface PartProps extends React.HTMLAttributes<HTMLElement> {
  children?: ReactNode;
}

export interface SelectItemProps extends PartProps {
  /** Radix marks unavailable options disabled; Astryx names it `isDisabled`. */
  disabled?: boolean;
  value: string;
  children?: ReactNode;
}

/** Declarative only — `Select` reads these; they render nothing on their own. */
export function SelectItem(_props: SelectItemProps) {
  return null;
}

export function SelectTrigger({ children }: PartProps) {
  return <>{children}</>;
}

export function SelectContent({ children }: PartProps) {
  return <>{children}</>;
}

export function SelectValue(_props: { placeholder?: string }) {
  return null;
}

export function SelectGroup({ children }: PartProps) {
  return <>{children}</>;
}

export function SelectLabel({ children }: PartProps) {
  return <>{children}</>;
}

/**
 * Depth-first walk for `SelectItem`s, since call sites nest them inside
 * `SelectContent` and sometimes `SelectGroup`.
 */
function collectOptions(children: ReactNode, found: SelectOption[] = []): SelectOption[] {
  Children.forEach(children, (child) => {
    if (!isValidElement(child)) return;
    if (child.type === SelectItem) {
      const props = child.props as SelectItemProps;
      found.push({
        value: props.value,
        label: typeof props.children === "string" ? props.children : props.value,
      });
      return;
    }
    const nested = (child as ReactElement<{ children?: ReactNode }>).props.children;
    if (nested) collectOptions(nested, found);
  });
  return found;
}

/** The placeholder lives on `SelectValue`, one or two levels down. */
function findPlaceholder(children: ReactNode): string | undefined {
  let placeholder: string | undefined;
  Children.forEach(children, (child) => {
    if (placeholder || !isValidElement(child)) return;
    if (child.type === SelectValue) {
      placeholder = (child.props as { placeholder?: string }).placeholder;
      return;
    }
    const nested = (child as ReactElement<{ children?: ReactNode }>).props.children;
    if (nested) placeholder = findPlaceholder(nested);
  });
  return placeholder;
}

export function Select({
  value,
  defaultValue,
  disabled,
  required,
  name,
  "aria-label": ariaLabel,
  className,
  children,
  onValueChange,
}: SelectProps) {
  const options = collectOptions(children);
  const placeholder = findPlaceholder(children);

  return (
    <Selector
      label={ariaLabel ?? name ?? placeholder ?? "Select"}
      isLabelHidden
      options={options}
      value={value ?? defaultValue}
      placeholder={placeholder}
      isDisabled={disabled}
      isRequired={required}
      htmlName={name}
      className={className}
      onChange={(next: string) => onValueChange?.(next)}
    />
  );
}

export default Select;

/**
 * Separator — shadcn surface over Astryx `Divider`.
 *
 * A near-exact match; only the component name differs. `decorative` has no
 * Astryx counterpart because Divider is already non-semantic.
 */
import { Divider } from "@astryxdesign/core/Divider";

export interface SeparatorProps {
  orientation?: "horizontal" | "vertical";
  decorative?: boolean;
  className?: string;
}

export function Separator({ orientation = "horizontal", className }: SeparatorProps) {
  return <Divider orientation={orientation} className={className} />;
}

export default Separator;

/**
 * Skeleton — shadcn surface over Astryx `Skeleton`.
 *
 * shadcn's version is a bare `<div>` sized entirely by Tailwind classes
 * (`h-4 w-32`). Astryx takes explicit `width`/`height`. `className` is still
 * forwarded so existing sizing classes keep working through the Tailwind
 * bridge during Phase B; the explicit props are there for callers written
 * after the swap.
 */
import { Skeleton as AstryxSkeleton } from "@astryxdesign/core/Skeleton";

export interface SkeletonProps {
  className?: string;
  width?: number | string;
  height?: number | string;
}

export function Skeleton({ className, width, height }: SkeletonProps) {
  return <AstryxSkeleton className={className} width={width} height={height} />;
}

export default Skeleton;

/**
 * Slider — shadcn surface over Astryx `Slider`.
 *
 * shadcn's slider takes `value` as an array (Radix's shape, which supports any
 * number of thumbs) and reports changes through `onValueChange`. Astryx has two
 * typed modes: a single `number`, or a `[number, number]` range. The array
 * length picks the mode, which covers everything the shadcn surface can
 * actually express — three or more thumbs is a Radix capability the generated
 * app has no call site for.
 *
 * `label` is required by Astryx and has no shadcn equivalent, because Radix
 * expects an adjacent `<Label>` element. Call sites that supply one get it
 * visually hidden here rather than rendered twice; those that do not get a
 * generic accessible name, which is still better than the unlabelled range
 * input shadcn produced.
 */
import { Slider as AstryxSlider } from "@astryxdesign/core/Slider";

export interface SliderProps {
  value?: number[];
  defaultValue?: number[];
  onValueChange?: (value: number[]) => void;
  min?: number;
  max?: number;
  step?: number;
  disabled?: boolean;
  className?: string;
  /**
   * Accessible name. Supply it when the call site has no visible `<Label>`;
   * when it does, pass the same text — the label is hidden here, not repeated.
   */
  label?: string;
}

export function Slider({
  value,
  defaultValue,
  onValueChange,
  min = 0,
  max = 100,
  step = 1,
  disabled = false,
  className,
  label = "Value",
}: SliderProps) {
  const current = value ?? defaultValue ?? [min];

  if (current.length >= 2) {
    return (
      <AstryxSlider
        className={className}
        label={label}
        isLabelHidden
        min={min}
        max={max}
        step={step}
        isDisabled={disabled}
        value={[current[0] ?? min, current[1] ?? max]}
        onChange={(next: [number, number]) => onValueChange?.([next[0], next[1]])}
      />
    );
  }

  return (
    <AstryxSlider
      className={className}
      label={label}
      isLabelHidden
      min={min}
      max={max}
      step={step}
      isDisabled={disabled}
      value={current[0] ?? min}
      onChange={(next: number) => onValueChange?.([next])}
    />
  );
}

export default Slider;

/**
 * Switch — shadcn surface over Astryx `Switch`.
 *
 * shadcn (Radix) uses `checked` / `onCheckedChange`; Astryx uses `value` and
 * `onChange(checked, event)`. Both spellings are accepted.
 */
import type { ChangeEvent } from "react";
import { Switch as AstryxSwitch } from "@astryxdesign/core/Switch";

export interface SwitchProps {
  checked?: boolean;
  defaultChecked?: boolean;
  disabled?: boolean;
  className?: string;
  id?: string;
  name?: string;
  "aria-label"?: string;
  onCheckedChange?: (checked: boolean) => void;
}

export function Switch({
  checked,
  defaultChecked,
  disabled,
  className,
  id,
  name,
  "aria-label": ariaLabel,
  onCheckedChange,
}: SwitchProps) {
  return (
    <AstryxSwitch
      label={ariaLabel ?? name ?? id ?? "Toggle"}
      value={checked ?? defaultChecked ?? false}
      isDisabled={disabled}
      isLabelHidden
      className={className}
      id={id}
      htmlName={name}
      onChange={(next: boolean, _event: ChangeEvent<HTMLInputElement>) => onCheckedChange?.(next)}
    />
  );
}

export default Switch;

/**
 * Table — shadcn surface over Astryx's table parts.
 *
 * Astryx ships two tables: a data-driven `Table` that takes `columns` + `data`
 * and renders everything itself, and the composable parts it builds that from.
 * This uses the parts, because the shadcn surface *is* a composition —
 * `<Table><TableHeader><TableRow><TableHead>` — and the admin screens that call
 * it interleave their own cells, checkboxes and row actions. Routing them
 * through the data-driven component would mean rewriting every call site.
 *
 * The parts are a near-exact match: `TableHeaderCell` is `TableHead` under a
 * different name, and the rest line up one to one.
 *
 * `Table` supplies `TableContext` so density, dividers, striping and hover come
 * from the theme rather than from Tailwind classes. Astryx's parts tolerate a
 * missing context and fall back to bare elements, so the provider is what
 * actually buys the styling.
 */
import { forwardRef, type ReactNode } from "react";
import {
  TableBody as AstryxBody,
  TableCell as AstryxCell,
  TableFooter as AstryxFooter,
  TableHeader as AstryxHeader,
  TableHeaderCell as AstryxHeaderCell,
  TableRow as AstryxRow,
  TableContext,
} from "@astryxdesign/core/Table";

/** Matches the defaults of Astryx's own `Table`. */
const TABLE_CONTEXT = {
  density: "balanced",
  dividers: "rows",
  isStriped: false,
  // The shadcn table hovers rows; keeping that on preserves the affordance the
  // admin grids rely on to show a row is clickable.
  hasHover: true,
  verticalAlign: "middle",
  textOverflow: "wrap",
} as const;

interface PartProps {
  children?: ReactNode;
  className?: string;
}

// Style objects live at module scope rather than inline in JSX. An inline
// style prop opens with two braces, which Handlebars reads as the start of an
// expression and refuses to render — so this is a hard constraint on every
// template in this directory, not a preference. They are constants, so module
// scope is where they belong anyway.
const SCROLL_WRAPPER: React.CSSProperties = { width: "100%", overflowX: "auto" };
const FULL_WIDTH: React.CSSProperties = { width: "100%" };
/**
 * `colSpan` for a header cell.
 *
 * Astryx's `TableHeaderCellProps` extends `HTMLAttributes`, which omits the
 * table-cell-only attributes, so `colSpan` is not in the type — but the
 * component spreads its rest props straight onto the `<th>`, so it works at
 * runtime. This is where that gap is bridged, once and visibly, rather than
 * with a cast at each call site or by dropping a spanning header on the floor.
 */
function spanAttrs(colSpan?: number): Record<string, unknown> {
  return colSpan === undefined ? {} : { colSpan };
}

/** A sortable header reads as its cell, not as a button. */
const SORT_TRIGGER: React.CSSProperties = {
  all: "unset",
  cursor: "pointer",
  display: "inline-flex",
  alignItems: "center",
  gap: "0.25rem",
};

export const Table = forwardRef<HTMLTableElement, React.HTMLAttributes<HTMLTableElement>>(
  ({ className, children, ...props }, ref) => (
    <TableContext.Provider value={TABLE_CONTEXT}>
      {/* Wide grids must scroll inside the table, not push the page sideways. */}
      <div style={SCROLL_WRAPPER}>
        <table ref={ref} className={className} style={FULL_WIDTH} {...props}>
          {children}
        </table>
      </div>
    </TableContext.Provider>
  )
);
Table.displayName = "Table";

export function TableHeader({ children, className }: PartProps) {
  return <AstryxHeader className={className}>{children}</AstryxHeader>;
}

export function TableBody({ children, className }: PartProps) {
  return <AstryxBody className={className}>{children}</AstryxBody>;
}

export function TableFooter({ children, className }: PartProps) {
  return <AstryxFooter className={className}>{children}</AstryxFooter>;
}

export interface TableRowProps extends PartProps {
  onClick?: () => void;
  /**
   * Radix's selected marker. Typed to include `false` because the call sites
   * write `data-state={isSelected && "selected"}` — a falsy value is how they
   * say "not selected", and React omits the attribute for it.
   */
  "data-state"?: string | false;
}

export function TableRow({ children, className, ...props }: TableRowProps) {
  return (
    <AstryxRow className={className} {...props}>
      {children}
    </AstryxRow>
  );
}

/**
 * shadcn's `TableHead` is Astryx's `TableHeaderCell`.
 *
 * `onClick` is accepted because the sortable grids attach it to header cells,
 * but Astryx's props do not include it, so it is applied to a wrapper rather
 * than spread onto the cell — spreading it would not typecheck, and dropping
 * it would silently break column sorting.
 */
export function TableHead({
  children,
  className,
  colSpan,
  scope = "col",
  onClick,
}: PartProps & { colSpan?: number; scope?: "col" | "row"; onClick?: () => void }) {
  return (
    <AstryxHeaderCell className={className} scope={scope} {...spanAttrs(colSpan)}>
      {onClick ? (
        <button type="button" onClick={onClick} style={SORT_TRIGGER}>
          {children}
        </button>
      ) : (
        children
      )}
    </AstryxHeaderCell>
  );
}

export function TableCell({
  children,
  className,
  colSpan,
  rowSpan,
  ...props
}: PartProps & { colSpan?: number; rowSpan?: number }) {
  return (
    <AstryxCell className={className} colSpan={colSpan} rowSpan={rowSpan} {...props}>
      {children}
    </AstryxCell>
  );
}

/** shadcn exports a `<caption>` helper; Astryx has no equivalent part. */
export function TableCaption({ children, className }: PartProps) {
  return <caption className={className}>{children}</caption>;
}

export default Table;

/**
 * Tabs — shadcn surface over Astryx `TabList`.
 *
 * Radix splits tabs into Root / List / Trigger / Content and renders the
 * active panel itself. Astryx's `TabList` is only the tab strip — it reports
 * which tab is selected and leaves panel rendering to the caller.
 *
 * So `Tabs` keeps the selected value (controlled or uncontrolled), passes it to
 * `TabList`, and renders whichever `TabsContent` matches. That preserves the
 * Radix call shape while using Astryx for the part it actually provides.
 */
import { Children, isValidElement, useState, type ReactElement, type ReactNode } from "react";
import { Tab, TabList } from "@astryxdesign/core/TabList";

export interface TabsProps {
  value?: string;
  defaultValue?: string;
  className?: string;
  children?: ReactNode;
  onValueChange?: (value: string) => void;
}

export interface TabsTriggerProps {
  className?: string;
  value: string;
  children?: ReactNode;
  disabled?: boolean;
}

export interface TabsContentProps {
  value: string;
  children?: ReactNode;
  className?: string;
}

/** Declarative only — `Tabs` reads these to build the strip. */
export function TabsTrigger(_props: TabsTriggerProps) {
  return null;
}

export function TabsList({ children }: { children?: ReactNode; className?: string }) {
  return <>{children}</>;
}

export function TabsContent({ children, className }: TabsContentProps) {
  return <div className={className}>{children}</div>;
}

function collectTriggers(children: ReactNode, found: TabsTriggerProps[] = []) {
  Children.forEach(children, (child) => {
    if (!isValidElement(child)) return;
    if (child.type === TabsTrigger) {
      found.push(child.props as TabsTriggerProps);
      return;
    }
    const nested = (child as ReactElement<{ children?: ReactNode }>).props.children;
    if (nested) collectTriggers(nested, found);
  });
  return found;
}

export function Tabs({ value, defaultValue, className, children, onValueChange }: TabsProps) {
  // Astryx's `Tab` has no disabled state. Omitting a disabled trigger keeps the
  // gating intent — the user still cannot reach that panel — where rendering it
  // enabled would silently grant access the call site tried to withhold. The
  // cost is that the tab disappears instead of appearing greyed out; making it
  // visible-but-inert needs an upstream Astryx feature.
  const triggers = collectTriggers(children).filter((trigger) => !trigger.disabled);
  const [internal, setInternal] = useState(defaultValue ?? triggers[0]?.value ?? "");
  // Controlled when `value` is supplied, uncontrolled otherwise — the same
  // contract Radix offers, so existing call sites keep working either way.
  const active = value ?? internal;

  const select = (next: string) => {
    if (value === undefined) setInternal(next);
    onValueChange?.(next);
  };

  const panels = Children.toArray(children).filter(
    (child): child is ReactElement<TabsContentProps> => isValidElement(child) && child.type === TabsContent
  );

  return (
    <div className={className}>
      <TabList value={active} onChange={select}>
        {triggers.map((trigger) => (
          <Tab
            key={trigger.value}
            value={trigger.value}
            label={typeof trigger.children === "string" ? trigger.children : trigger.value}
          />
        ))}
      </TabList>
      {panels.filter((panel) => panel.props.value === active)}
    </div>
  );
}

export default Tabs;

/**
 * Textarea — shadcn surface over Astryx `TextArea`.
 *
 * Same controlled/uncontrolled and `onChange` bridging as `Input`; see that
 * file for why the label fallback exists.
 */
import type { ChangeEvent } from "react";
import { TextArea } from "@astryxdesign/core/TextArea";

export interface TextareaProps {
  value?: string;
  defaultValue?: string;
  placeholder?: string;
  disabled?: boolean;
  readOnly?: boolean;
  rows?: number;
  className?: string;
  id?: string;
  name?: string;
  "aria-label"?: string;
  onChange?: (event: ChangeEvent<HTMLTextAreaElement>) => void;
  onBlur?: () => void;
}

export function Textarea({
  value,
  defaultValue,
  placeholder,
  disabled,
  readOnly,
  rows,
  className,
  id,
  name,
  "aria-label": ariaLabel,
  onChange,
  onBlur,
}: TextareaProps) {
  return (
    <TextArea
      label={ariaLabel ?? placeholder ?? name ?? id ?? "Value"}
      value={value ?? defaultValue ?? ""}
      placeholder={placeholder}
      isLabelHidden
      isDisabled={disabled || readOnly}
      rows={rows}
      className={className}
      id={id}
      htmlName={name}
      onChange={(_next: string, event: ChangeEvent<HTMLTextAreaElement>) => onChange?.(event)}
      onBlur={onBlur}
    />
  );
}

export default Textarea;

/**
 * Toast — shadcn surface over Astryx `ToastViewport` / `useToast`.
 *
 * The shapes disagree in one structural way. shadcn exposes a module-level
 * `toast(...)` callable from anywhere — a mutation's `onError`, a route loader,
 * a plain async helper — while Astryx exposes `useToast()`, a hook, which only
 * a component can call. Bridging that needs a queue: `toast(...)` pushes onto
 * it, and a component mounted inside `<Toaster>` drains it through the hook.
 *
 * The shadcn implementation this replaces did the same thing with a `Map` and
 * `window` CustomEvents. This uses a subscriber list instead, which works
 * under SSR and in tests where `window` may not exist, and drops the globals.
 *
 * Toasts fired before `<Toaster>` mounts are buffered and flushed on
 * subscribe — the case that matters is an error thrown during initial data
 * loading, which is exactly when a dropped toast is least acceptable.
 *
 * **One deliberate loss.** Astryx has two toast types, `info` and `error`.
 * shadcn had five variants. `destructive` maps to `error` and the rest to
 * `info`, so success and warning would become indistinguishable — a "saved"
 * and a "check this before continuing" rendering identically is worse than
 * ugly. The variant's icon is therefore prepended to the body, which keeps
 * them apart without inventing a toast type Astryx does not have.
 */
import { useEffect, type ReactNode } from "react";
import { ToastViewport, useToast, type ToastOptions } from "@astryxdesign/core/Toast";
import { Icon } from "@astryxdesign/core/Icon";
import { HStack } from "@astryxdesign/core/HStack";
import { Text } from "@astryxdesign/core/Text";

export type ToastVariant = "default" | "destructive" | "success" | "warning" | "info";

export interface ToastProps {
  title?: string;
  description?: ReactNode;
  variant?: ToastVariant;
  /** Correlation id surfaced with server errors so a user can quote it. */
  referenceId?: string;
  duration?: number;
}

/** Astryx's semantic icon names, per shadcn variant. */
const VARIANT_ICON = {
  default: null,
  destructive: "error",
  success: "success",
  warning: "warning",
  info: "info",
} as const;

/** Astryx's `error` is its only non-neutral type. */
function astryxType(variant: ToastVariant): "info" | "error" {
  return variant === "destructive" ? "error" : "info";
}

function ToastBody({ title, description, variant = "default", referenceId }: ToastProps) {
  const icon = VARIANT_ICON[variant];
  // Astryx's gap is a numeric step, not a t-shirt size; 2 is 0.5rem.
  return (
    <HStack gap={2} vAlign="start">
      {icon ? <Icon icon={icon} size="sm" /> : null}
      <div>
        {title ? (
          <Text weight="medium" display="block">
            {title}
          </Text>
        ) : null}
        {description ? <Text size="sm">{description}</Text> : null}
        {referenceId ? (
          <Text size="xsm" color="secondary" display="block">
            Reference: {referenceId}
          </Text>
        ) : null}
      </div>
    </HStack>
  );
}

// ---------------------------------------------------------------------------
// The queue that lets `toast()` be called outside React
// ---------------------------------------------------------------------------

type Subscriber = (options: ToastOptions) => void;

let subscriber: Subscriber | null = null;
/** Toasts fired before `<Toaster>` mounted. Flushed on subscribe. */
const buffered: ToastOptions[] = [];

function emit(options: ToastOptions) {
  if (subscriber) {
    subscriber(options);
  } else {
    buffered.push(options);
  }
}

export interface ToastFunction {
  (props: ToastProps): void;
  success: (description: ReactNode, options?: Omit<ToastProps, "description" | "variant">) => void;
  error: (description: ReactNode, options?: Omit<ToastProps, "description" | "variant">) => void;
  warning: (description: ReactNode, options?: Omit<ToastProps, "description" | "variant">) => void;
  info: (description: ReactNode, options?: Omit<ToastProps, "description" | "variant">) => void;
}

function show(props: ToastProps) {
  emit({
    body: <ToastBody {...props} />,
    type: astryxType(props.variant ?? "default"),
    isAutoHide: true,
    autoHideDuration: props.duration ?? 5000,
  });
}

export const toast = show as ToastFunction;

toast.success = (description, options) => show({ title: "Success", ...options, description, variant: "success" });
toast.error = (description, options) => show({ title: "Error", ...options, description, variant: "destructive" });
toast.warning = (description, options) => show({ title: "Warning", ...options, description, variant: "warning" });
toast.info = (description, options) => show({ title: "Info", ...options, description, variant: "info" });

/** Drains the queue through the hook. Rendered inside `ToastViewport`. */
function ToastBridge() {
  const showToast = useToast();

  useEffect(() => {
    subscriber = (options) => {
      showToast(options);
    };
    // Anything fired before mount lands now, in the order it was raised.
    while (buffered.length > 0) {
      const next = buffered.shift();
      if (next) showToast(next);
    }
    return () => {
      subscriber = null;
    };
  }, [showToast]);

  return null;
}

/**
 * Mount once, near the root. Astryx's viewport owns positioning, stacking,
 * the exit animation and focus handling, so there is nothing to configure
 * beyond where it sits.
 */
export function Toaster() {
  return (
    <ToastViewport position="bottomEnd">
      <ToastBridge />
    </ToastViewport>
  );
}

/**
 * A single toast, for the rare call site that renders one itself rather than
 * going through `toast()`. Astryx's `Toast` requires viewport-managed
 * lifecycle props, so this renders the body only — the same content, without
 * claiming to manage a dismissal it is not wired to.
 */
export function Toast(props: ToastProps) {
  return <ToastBody {...props} />;
}

export default toast;

/**
 * Tooltip — shadcn surface over Astryx `Tooltip`.
 *
 * Radix splits this into Provider/Root/Trigger/Content; Astryx takes the
 * trigger as children and the text as a `content` prop. `TooltipContent`
 * therefore does not render — `Tooltip` reads its children as the content and
 * `TooltipTrigger` supplies the anchor.
 */
import { Children, isValidElement, type ReactElement, type ReactNode } from "react";
import { Tooltip as AstryxTooltip } from "@astryxdesign/core/Tooltip";

/**
 * Structural parts accept the ordinary HTML attributes their Radix originals
 * did — `className`, `style`, `title`, `onClick`, `aria-*`. The classes are
 * inert once Phase C removes Tailwind, but the call sites in
 * `components/admin/*` pass them today and an adapter those call sites cannot
 * typecheck against is not a finished adapter.
 */
interface PartProps extends React.HTMLAttributes<HTMLElement> {
  children?: ReactNode;
}

export function TooltipProvider({
  children,
}: PartProps & {
  /**
   * Radix's open delay. Astryx's `Tooltip` owns its own timing, so this is
   * accepted and ignored rather than rejected — a provider-level delay is not
   * worth editing every call site to drop.
   */
  delayDuration?: number;
}) {
  return <>{children}</>;
}

export function TooltipTrigger({ children }: PartProps & { asChild?: boolean }) {
  return <>{children}</>;
}

export function TooltipContent(_props: PartProps & { side?: string }) {
  return null;
}

export interface TooltipProps {
  children?: ReactNode;
  content?: ReactNode;
  delayDuration?: number;
}

function extract(children: ReactNode, target: unknown): ReactNode | undefined {
  let found: ReactNode | undefined;
  Children.forEach(children, (child) => {
    if (found !== undefined || !isValidElement(child)) return;
    if (child.type === target) {
      found = (child as ReactElement<{ children?: ReactNode }>).props.children;
    }
  });
  return found;
}

export function Tooltip({ children, content, delayDuration }: TooltipProps) {
  const trigger = extract(children, TooltipTrigger) ?? children;
  const text = content ?? extract(children, TooltipContent);

  // Astryx requires content; with nothing to say, render the trigger bare
  // rather than an empty bubble.
  if (text === undefined || text === null) {
    return <>{trigger}</>;
  }

  return (
    <AstryxTooltip content={text} delay={delayDuration}>
      {trigger}
    </AstryxTooltip>
  );
}

export default Tooltip;

import React, { createContext, type ReactNode, useCallback, useContext, useEffect, useState } from "react";
import { setUnauthorizedCallback } from "@/lib/api-client";
import {
  signIn as authSignIn,
  signOut as authSignOut,
  signUp as authSignUp,
  getSession,
} from "@/lib/auth";

/**
 * The signed-in user, as `/api/auth/me` and `/api/auth/login` actually return
 * them.
 *
 * The key is `pid`, not `id` — that is what the backend's `UserResponse`
 * serialises. This interface used to claim an `id` that never arrived; nothing
 * read it, so the lie was invisible, but it would have handed the next caller
 * `undefined`.
 */
interface User {
  pid: string;
  email: string;
  name: string;
  sysUserId?: string;
  role?: string;
}

interface AuthContextType {
  user: User | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  isAdmin: () => boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  signup: (email: string, password: string, name: string) => Promise<void>;
  refreshSession: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

interface AuthProviderProps {
  children: ReactNode;
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // `useCallback` so the effect below can depend on it honestly. Declared
  // inline it was a new function every render, which is why it was omitted from
  // the dependency list — and an omitted dependency is a stale closure waiting
  // to happen, not a smaller one.
  const refreshSession = useCallback(async () => {
    try {
      const { data } = await getSession();
      setUser((data as { user?: User } | null)?.user ?? null);
    } catch (error) {
      console.error("Failed to refresh session:", error);
    }
  }, []);

  useEffect(() => {
    const checkSession = async () => {
      await refreshSession();
      setIsLoading(false);
    };

    checkSession();

    // Register 401 unauthorized callback for API client
    setUnauthorizedCallback(async () => {
      setUser(null);
      await authSignOut();
      window.location.href = "/auth/login";
    });
  }, [refreshSession]);

  const login = async (email: string, password: string) => {
    setIsLoading(true);
    try {
      const { data, error } = await authSignIn(email, password);
      if (error) throw new Error(error);
      setUser((data as { user?: User } | null)?.user ?? null);
    } finally {
      setIsLoading(false);
    }
  };

  const logout = async () => {
    setIsLoading(true);
    try {
      await authSignOut();
      setUser(null);
    } finally {
      setIsLoading(false);
    }
  };

  const signup = async (email: string, password: string, name: string) => {
    setIsLoading(true);
    try {
      const { data: _data, error } = await authSignUp(email, password, name);
      if (error) {
        throw new Error(error);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const isAdmin = () => user?.role === "admin";

  return (
    <AuthContext.Provider
      value={{
        user,
        isLoading,
        isAuthenticated: !!user,
        isAdmin,
        login,
        logout,
        signup,
        refreshSession,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return context;
}

import { useQueries } from "@tanstack/react-query";
import type { ADLevel } from "@/components/admin/ad-window-configs";
import {
  findTableForEntity,
  useSysTables,
  useSysWindows,
} from "@/hooks/use-dictionary-lists";
import type { FieldMetadata } from "@/hooks/use-entities";
import { apiClient } from "@/lib/api-client";

/**
 * Builds an ADLevel entirely from Application Dictionary metadata fetched
 * from the backend.  No field lists or display names are hardcoded.
 *
 * entityName: the bus_ entity name without prefix, e.g. 'account', 'contact'
 */
export function useBusEntityLevel(entityName: string) {
  // Only the two field lists are per-entity. The dictionary's own lists are
  // the same for every entity, so they come from the shared hooks and the
  // second entity page reads them out of the cache — see
  // `hooks/use-dictionary-lists.ts` for what that replaced.
  const results = useQueries({
    queries: [
      {
        queryKey: ["bus-form-fields", entityName],
        queryFn: () => apiClient.get<FieldMetadata[]>(`/bus/${entityName}/fields/form`),
        staleTime: 5 * 60 * 1000,
      },
      {
        queryKey: ["bus-grid-fields", entityName],
        queryFn: () => apiClient.get<FieldMetadata[]>(`/bus/${entityName}/fields/grid`),
        staleTime: 5 * 60 * 1000,
      },
    ],
  });

  const { data: tables, isLoading: tablesLoading } = useSysTables();
  const { data: windows, isLoading: windowsLoading } = useSysWindows();

  const [formQuery, gridQuery] = results;
  const isLoading =
    formQuery.isLoading || gridQuery.isLoading || tablesLoading || windowsLoading;

  const table = findTableForEntity(tables, entityName);
  const windowName = table?.name ?? entityName;
  // Match a window by its display name, or by the slug derived from that name.
  const win = windows?.find(
    (w) =>
      w.name.toLowerCase() === windowName.toLowerCase() ||
      w.name.toLowerCase().replace(/\s+/g, "-") === entityName
  );
  const windowMeta = {
    label: win?.name ?? table?.name ?? entityName,
    windowId: win?.sys_window_id,
    windowSlug: win?.name.toLowerCase().replace(/\s+/g, "-") ?? entityName,
  };

  const formFields: FieldMetadata[] = (formQuery.data as FieldMetadata[]) ?? [];
  const gridFields: FieldMetadata[] = (gridQuery.data as FieldMetadata[]) ?? [];
  const label = windowMeta.label;
  const windowSlug = windowMeta.windowSlug;

  // Derive the name field — first non-id identifier field, then common name fallbacks
  const NAME_FALLBACKS = ["name", "title", "first_name", "description", "type"];
  const nameField =
    formFields.find((f) => f.is_identifier && f.column_name !== "id")?.column_name ??
    NAME_FALLBACKS.find((candidate) => formFields.some((f) => f.column_name === candidate)) ??
    "name";

  const level: ADLevel | null = isLoading
    ? null
    : {
        id: entityName,
        label,
        endpoint: `/bus/${entityName}`,
        idField: "id",
        nameField,
        searchField: nameField,
        formFields,
        gridFields,
        // Route path derived from Window name in Application Dictionary (kebab-case slug)
        baseRoutePath: `/${windowSlug}`,
      };

  return { level, isLoading };
}

/**
 * The navigation this caller may actually open.
 *
 * `/api/me/dashboard` answers the whole front page in one request, scoped to
 * the caller: the categories with the entities inside them, the admin windows
 * it may open, its role and its master flag. It answers from the same rows
 * `/api/bus/*` is guarded by, so what a screen offers is what opens.
 *
 * It lives here rather than inside the dashboard route because **two** surfaces
 * draw that navigation now — the dashboard's cards and the sidebar. One query
 * key means the sidebar costs no request of its own: whichever renders first
 * fetches, the other reads the cache, and every later screen keeps the sidebar
 * without asking again.
 *
 * That sharing is also what stops the sidebar drifting. It used to carry its
 * own hardcoded lists — a `navItems` array with the entities interpolated at
 * generation time and their icons guessed from their names, and an `adminItems`
 * array naming six admin screens, one of which (`/admin/dictionary`) does not
 * exist in the generated application at all. A menu is a claim about what the
 * application has; deriving it from the dictionary is what makes the claim
 * true, and RBAC-scoped into the bargain.
 */
import { useQuery } from "@tanstack/react-query";
import { apiClient } from "@/lib/api-client";

/**
 * An entity as the front page offers it: the window it opens in.
 *
 * Every label the screens draw for an entity — the card, the menu entry, the
 * heading — is the **window's** (`window_name`, `window_description`,
 * `window_help`, `window_icon`), and a tab's or a field's inside it. The
 * dictionary's table and column names (`table_name`, `name`, `description`,
 * `icon` of `sys_table`) are what the application stores things in, not what a
 * person reads, and nothing on a screen is drawn from them. `table_name` stays
 * because it keys the entity to the API.
 */
export interface DashboardTable {
  sys_table_id: string;
  /** The key to the API. Never drawn. */
  table_name: string;
  window_id: string;
  window_name: string;
  window_description?: string | null;
  window_help?: string | null;
  window_icon?: string | null;
  is_active: boolean;
}

/** A dictionary category with the entities assigned to it. */
export interface DashboardCategory {
  sys_category_id: string | null;
  name: string;
  code: string;
  description: string | null;
  icon: string | null;
  color: string | null;
  entities: DashboardTable[];
}

export interface DashboardWindow {
  sys_window_id: string;
  name: string;
  /** Where clicking it goes — `sys_window.description` for an admin screen. */
  route: string | null;
  /** A lucide icon id from `sys_window.icon`. Null when the row names none. */
  icon: string | null;
  category: "admin" | "business";
  is_read_only: boolean;
}

export interface DashboardResponse {
  data: DashboardCategory[];
  windows: DashboardWindow[];
  role: string;
  isMaster: boolean;
}

export function useDashboard() {
  return useQuery<DashboardResponse>({
    queryKey: ["dashboard"],
    queryFn: () => apiClient.get<DashboardResponse>("/me/dashboard"),
    staleTime: 5 * 60 * 1000,
  });
}

/**
 * Where an entity's screen lives.
 *
 * Derived from the display name rather than from `table_name`, because that is
 * what the route tree was built against: `Chemical Inventory` is
 * `/chemical-inventory`, where stripping `bus_` would give
 * `/chemical_inventory` and 404. One helper so the dashboard's cards and the
 * sidebar's links cannot disagree about it.
 */
export function entityHref(table: Pick<DashboardTable, "window_name">): string {
  return `/${table.window_name.toLowerCase().replace(/\s+/g, "-")}`;
}

/** The admin windows this caller may open, in the order the dictionary gives. */
export function adminWindows(
  dashboard: DashboardResponse | undefined
): Array<DashboardWindow & { route: string }> {
  return (dashboard?.windows ?? []).filter(
    (window): window is DashboardWindow & { route: string } =>
      window.category === "admin" &&
      typeof window.route === "string" &&
      window.route.length > 0
  );
}

/**
 * The Application Dictionary's own lists, fetched once per session.
 *
 * `sys_table`, `sys_window` and `sys_tab` describe the application rather than
 * its data: they change when an administrator edits the dictionary, not when
 * somebody creates a record. Three hooks used to fetch them under keys scoped
 * to the *entity being viewed* — `["sys-window-for-entity", entityName]`,
 * `["window-tabs", tableName]`, `entityKeys.table(entity)` — so opening
 * Compound, then Experiment, then Sample re-fetched the whole table list three
 * times and the whole window list twice, for three identical answers.
 *
 * Keyed by the list itself, the second reader is a cache hit and so is the next
 * screen. That is the only thing these hooks do: a caller that wants the row
 * for one entity filters the list it already has, because the alternative is a
 * request per entity for data that is the same for all of them.
 *
 * `LIST_LIMIT` is one number on purpose. Callers used 500, 200, 100 and the
 * server's own default of 200, and a hook that asked for fewer rows than
 * another got a different answer to the same question — a dictionary of 250
 * tables would have resolved an entity on one screen and not on the next. The
 * server clamps at 1000 (`MAX_LIMIT` in `controllers/sys.rs`), so an
 * application with more dictionary rows than this needs paging here rather
 * than a larger constant.
 */
import { useQuery } from "@tanstack/react-query";
import { apiClient, type PaginatedResponse } from "@/lib/api-client";

export const LIST_LIMIT = 500;

/** Long, because the dictionary changes on an admin's edit, not on a write. */
const DICTIONARY_STALE_TIME = 30 * 60 * 1000;

export const dictionaryKeys = {
  tables: ["dictionary", "tables"] as const,
  windows: ["dictionary", "windows"] as const,
  tabs: ["dictionary", "tabs"] as const,
};

export interface SysTableRow {
  sys_table_id: string;
  table_name: string;
  name: string;
  description?: string;
  icon?: string | null;
  [key: string]: unknown;
}

export interface SysWindowRow {
  sys_window_id: string;
  name: string;
  description?: string;
  [key: string]: unknown;
}

export interface SysTabRow {
  sys_tab_id: string;
  sys_window_id: string;
  sys_table_id: string;
  name: string;
  description?: string;
  tab_level: number;
  seq_no: number;
  is_active: boolean;
  [key: string]: unknown;
}

async function list<T>(segment: string): Promise<T[]> {
  const response = await apiClient.get<PaginatedResponse<T>>(`/sys/${segment}`, {
    limit: LIST_LIMIT,
  });
  return response?.data ?? [];
}

export function useSysTables() {
  return useQuery({
    queryKey: dictionaryKeys.tables,
    queryFn: () => list<SysTableRow>("tables"),
    staleTime: DICTIONARY_STALE_TIME,
  });
}

export function useSysWindows() {
  return useQuery({
    queryKey: dictionaryKeys.windows,
    queryFn: () => list<SysWindowRow>("windows"),
    staleTime: DICTIONARY_STALE_TIME,
  });
}

export function useSysTabs() {
  return useQuery({
    queryKey: dictionaryKeys.tabs,
    queryFn: () => list<SysTabRow>("tabs"),
    staleTime: DICTIONARY_STALE_TIME,
  });
}

/**
 * What a person calls an entity: the name of the window it opens in.
 *
 * A table's own `name` is the dictionary's, not the screen's. The window an
 * entity opens in is found through its top tab (`tab_level` 0), and its name —
 * or, for a line item that has no window of its own, its tab's — is what every
 * picker, heading and list draws. Returns `undefined` until the lists load, so a
 * caller shows nothing rather than a table name in the meantime.
 */
export function useEntityLabel(): (table: { sys_table_id: string }) => string | undefined {
  const { data: windows } = useSysWindows();
  const { data: tabs } = useSysTabs();
  return (table) => {
    const tab = (tabs ?? [])
      .filter((candidate) => candidate.sys_table_id === table.sys_table_id)
      .sort((a, b) => a.tab_level - b.tab_level || a.seq_no - b.seq_no)[0];
    if (!tab) return undefined;
    const window = (windows ?? []).find((w) => w.sys_window_id === tab.sys_window_id);
    return tab.tab_level === 0 ? (window?.name ?? tab.name) : tab.name;
  };
}

/**
 * The `sys_table` row for a `bus_` entity slug.
 *
 * Accepts both spellings a route can carry: `sales-order` and `sales_order`
 * both name `bus_sales_order`.
 */
export function findTableForEntity(
  tables: SysTableRow[] | undefined,
  entityName: string
): SysTableRow | undefined {
  if (!tables) return undefined;
  const candidates = [`bus_${entityName}`, `bus_${entityName.replace(/-/g, "_")}`];
  return tables.find((table) => candidates.includes(table.table_name));
}

/**
 * TanStack Query Hooks for Entity CRUD Operations
 *
 * Generated: {{now}}
 */

import {
  useQuery,
  useMutation,
  useQueryClient,
  type QueryClient,
  type UseQueryOptions,
} from '@tanstack/react-query';
import { apiClient, type PaginatedResponse, type ApiError } from '@/lib/api-client';
import { useSysTables } from '@/hooks/use-dictionary-lists';
import { toast } from 'sonner';
