// ============================================================================
// Logger Utility
// ============================================================================

enum LogLevel {
  DEBUG = 0,
  INFO = 1,
  WARN = 2,
  ERROR = 3,
}

class Logger {
  private level: LogLevel;
  private prefix: string;

  constructor(prefix = "[ApiClient]") {
    this.prefix = prefix;
    // Use INFO level in production, DEBUG level in development
    this.level = import.meta.env.MODE === "production" ? LogLevel.INFO : LogLevel.DEBUG;
  }

  private shouldLog(level: LogLevel): boolean {
    return level >= this.level;
  }

  debug(...args: unknown[]) {
    if (this.shouldLog(LogLevel.DEBUG)) {
      console.log(`${this.prefix} [DEBUG]`, ...args);
    }
  }

  log(...args: unknown[]) {
    if (this.shouldLog(LogLevel.INFO)) {
      console.log(`${this.prefix} [INFO]`, ...args);
    }
  }

  warn(...args: unknown[]) {
    if (this.shouldLog(LogLevel.WARN)) {
      console.warn(`${this.prefix} [WARN]`, ...args);
    }
  }

  error(...args: unknown[]) {
    if (this.shouldLog(LogLevel.ERROR)) {
      console.error(`${this.prefix} [ERROR]`, ...args);
    }
  }

  /**
   * Log request details
   */
  logRequest(method: string, url: string, options?: RequestInit & { body?: unknown }) {
    this.debug(`→ ${method} ${url}`);

    if (options?.headers) {
      this.debug("  Headers:", this.sanitizeHeaders(options.headers as HeadersInit));
    }

    if (options?.body) {
      try {
        const bodyStr =
          typeof options.body === "string" ? options.body : JSON.stringify(options.body);
        if (bodyStr.length < 500) {
          this.debug("  Body:", bodyStr);
        } else {
          this.debug("  Body:", `${bodyStr.substring(0, 500)}... (truncated)`);
        }
      } catch (e) {
        this.debug("  Body: [Unable to stringify]");
      }
    }
  }

  /**
   * Log response details
   */
  logResponse(method: string, url: string, response: Response, duration: number) {
    const statusEmoji = response.ok ? "✓" : "✗";
    this.log(
      `${statusEmoji} ${method} ${url} - ${response.status} ${response.statusText} (${duration}ms)`
    );

    if (!response.ok) {
      this.error(`  Response failed: ${response.status} ${response.statusText}`);
    }
  }

  /**
   * Log error details
   */
  logError(method: string, url: string, error: unknown, duration?: number) {
    const durationStr = duration ? ` (${duration}ms)` : "";

    if (error instanceof Error) {
      // Network/fetch errors (ERR_CONNECTION_REFUSED, offline) — expected when backend is unavailable
      this.warn(`✗ ${method} ${url} - ${error.message}${durationStr}`);
      return;
    }

    this.error(`✗ ${method} ${url} - Failed${durationStr}`);

    if (error && typeof error === "object") {
      if ("statusCode" in error) {
        this.error(`  Status: ${(error as ApiError).statusCode}`);
      }
      if ("message" in error) {
        this.error(`  Message: ${(error as ApiError).message}`);
      }
      if ("error" in error) {
        this.error(`  Error: ${(error as ApiError).error}`);
      }
      if ("errors" in error && (error as ApiError).errors) {
        this.error("  Validation Errors:", (error as ApiError).errors);
      }
      if ("details" in error && (error as ApiError).details) {
        this.error("  Details:", (error as ApiError).details);
      }
    } else {
      this.error("  Unknown error:", error);
    }
  }

  /**
   * Sanitize headers to remove sensitive information
   */
  private sanitizeHeaders(headers: HeadersInit): Record<string, string> {
    const sanitized: Record<string, string> = {};

    if (headers instanceof Headers) {
      for (const [key, value] of headers) {
        sanitized[key] = this.shouldSanitizeHeader(key) ? "[REDACTED]" : value;
      }
    } else if (Array.isArray(headers)) {
      for (const [key, value] of headers) {
        sanitized[key] = this.shouldSanitizeHeader(key) ? "[REDACTED]" : value;
      }
    } else {
      for (const [key, value] of Object.entries(headers)) {
        sanitized[key] = this.shouldSanitizeHeader(key) ? "[REDACTED]" : value;
      }
    }

    return sanitized;
  }

  private shouldSanitizeHeader(key: string): boolean {
    const sensitiveHeaders = ["authorization", "cookie", "x-api-key"];
    return sensitiveHeaders.includes(key.toLowerCase());
  }
}

// ============================================================================
// Types
// ============================================================================

export interface PaginatedResponse<T> {
  data: T[];
  meta: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  };
}

export interface ApiError {
  statusCode: number;
  message: string | string[];
  error: string;
  timestamp: string;
  path: string;
  requestId?: string;
  details?: Record<string, unknown>;
  errors?: Record<string, string[] | string>; // Field-level validation errors from backend
}

export interface RequestOptions {
  headers?: Record<string, string>;
  signal?: AbortSignal;
  /**
   * Treat 401 as an ordinary answer rather than a failure.
   *
   * `/auth/me` asks "is anyone signed in?" and 401 *is* the answer when nobody
   * is. Logged as an error it put four red lines and "Session expired. Please
   * sign in again." in the console of the sign-in page, before the visitor had
   * done anything at all. The call still throws — callers rely on that — it is
   * only the reporting that changes.
   */
  expectUnauthorized?: boolean;
}

// ============================================================================
// API Client
// ============================================================================

class ApiClient {
  private baseUrl: string;
  private authToken: string | null = null;
  private logger: Logger;

  constructor(baseUrl: string) {
    this.baseUrl = baseUrl;
    this.logger = new Logger();
    this.logger.log(`ApiClient initialized with baseUrl: ${baseUrl}`);
  }

  setAuthToken(token: string | null) {
    this.authToken = token;
    this.logger.debug(`Auth token ${token ? "set" : "cleared"}`);
  }

  private getHeaders(customHeaders?: Record<string, string>): HeadersInit {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      ...customHeaders,
    };

    if (this.authToken) {
      headers.Authorization = `Bearer ${this.authToken}`;
    }

    return headers;
  }

  private buildUrl(path: string, params?: Record<string, unknown>): string {
    const origin = typeof window !== "undefined" ? window.location.origin : "http://localhost:3000";
    let basePath = this.baseUrl || "/api";

    // If baseUrl is an absolute URL without /api, append /api
    if (basePath.startsWith("http") && !basePath.includes("/api")) {
      basePath = `${basePath}/api`;
    }

    const fullUrl = basePath.startsWith("http") ? basePath : origin + basePath;
    // Strip leading /api from path if fullUrl already ends with /api to avoid double /api/api
    const normalizedPath = fullUrl.endsWith("/api") && path.startsWith("/api/")
      ? path.slice(4)
      : path;
    const url = new URL(`${fullUrl}${normalizedPath}`);

    if (params) {
      for (const [key, value] of Object.entries(params)) {
        if (value !== undefined && value !== null && value !== "") {
          url.searchParams.append(key, String(value));
        }
      }
    }

    return url.toString();
  }

  private async handleResponse<T>(
    response: Response,
    method: string,
    url: string,
    startTime: number,
    options?: RequestOptions
  ): Promise<T> {
    const duration = Date.now() - startTime;
    const contentType = response.headers.get("content-type");

    // Log response
    this.logger.logResponse(method, url, response, duration);

    // Intercept 401 Unauthorized — trigger auto-logout
    if (response.status === 401) {
      const expected = options?.expectUnauthorized === true;
      if (!expected) onUnauthorizedCallback?.();
      const error = {
        statusCode: 401,
        message: expected
          ? 'Not signed in.'
          : 'Session expired. Please sign in again.',
        error: 'Unauthorized',
        timestamp: new Date().toISOString(),
        path: response.url,
      } as ApiError;
      if (!expected) this.logger.logError(method, url, error, duration);
      throw error;
    }

    if (response.status === 204) {
      return undefined as T;
    }

    if (contentType?.includes("application/json")) {
      const data = await response.json();

      if (!response.ok) {
        this.logger.logError(method, url, data, duration);
        throw data as ApiError;
      }

      return data as T;
    }

    if (!response.ok) {
      const error = {
        statusCode: response.status,
        message: response.statusText,
        error: "Request Failed",
        timestamp: new Date().toISOString(),
        path: response.url,
      } as ApiError;
      this.logger.logError(method, url, error, duration);
      throw error;
    }

    return (await response.text()) as T;
  }

  async get<T>(
    path: string,
    params?: Record<string, unknown>,
    options?: RequestOptions
  ): Promise<T> {
    const startTime = Date.now();
    const url = this.buildUrl(path, params);
    const requestOptions = {
      method: "GET" as const,
      headers: this.getHeaders(options?.headers),
      credentials: "include" as const,
      signal: options?.signal,
    };

    this.logger.logRequest(requestOptions.method, url, requestOptions);

    try {
      const response = await fetch(url, requestOptions);
      return this.handleResponse<T>(response, requestOptions.method, url, startTime, options);
    } catch (error) {
      this.logger.logError(requestOptions.method, url, error, Date.now() - startTime);
      throw error;
    }
  }

  async post<T>(path: string, data?: unknown, options?: RequestOptions): Promise<T> {
    const startTime = Date.now();
    const url = this.buildUrl(path);
    const requestOptions = {
      method: "POST" as const,
      headers: this.getHeaders(options?.headers),
      credentials: "include" as const,
      body: data ? JSON.stringify(data) : undefined,
      signal: options?.signal,
    };

    this.logger.logRequest(requestOptions.method, url, requestOptions);

    try {
      const response = await fetch(url, requestOptions);
      return this.handleResponse<T>(response, requestOptions.method, url, startTime, options);
    } catch (error) {
      this.logger.logError(requestOptions.method, url, error, Date.now() - startTime);
      throw error;
    }
  }

  async put<T>(path: string, data?: unknown, options?: RequestOptions): Promise<T> {
    const startTime = Date.now();
    const url = this.buildUrl(path);
    const requestOptions = {
      method: "PUT" as const,
      headers: this.getHeaders(options?.headers),
      credentials: "include" as const,
      body: data ? JSON.stringify(data) : undefined,
      signal: options?.signal,
    };

    this.logger.logRequest(requestOptions.method, url, requestOptions);

    try {
      const response = await fetch(url, requestOptions);
      return this.handleResponse<T>(response, requestOptions.method, url, startTime, options);
    } catch (error) {
      this.logger.logError(requestOptions.method, url, error, Date.now() - startTime);
      throw error;
    }
  }

  async patch<T>(path: string, data?: unknown, options?: RequestOptions): Promise<T> {
    const startTime = Date.now();
    const url = this.buildUrl(path);
    const requestOptions = {
      method: "PATCH" as const,
      headers: this.getHeaders(options?.headers),
      credentials: "include" as const,
      body: data ? JSON.stringify(data) : undefined,
      signal: options?.signal,
    };

    this.logger.logRequest(requestOptions.method, url, requestOptions);

    try {
      const response = await fetch(url, requestOptions);
      return this.handleResponse<T>(response, requestOptions.method, url, startTime, options);
    } catch (error) {
      this.logger.logError(requestOptions.method, url, error, Date.now() - startTime);
      throw error;
    }
  }

  async delete<T = void>(path: string, options?: RequestOptions): Promise<T> {
    const startTime = Date.now();
    const url = this.buildUrl(path);
    // DELETE requests have no body — omit Content-Type to avoid Fastify's
    // "body cannot be empty when content-type is application/json" error.
    const { "Content-Type": _ct, ...headersWithoutContentType } = this.getHeaders(options?.headers) as Record<string, string>;
    const requestOptions = {
      method: "DELETE" as const,
      headers: headersWithoutContentType,
      credentials: "include" as const,
      signal: options?.signal,
    };

    this.logger.logRequest(requestOptions.method, url, requestOptions);

    try {
      const response = await fetch(url, requestOptions);
      return this.handleResponse<T>(response, requestOptions.method, url, startTime, options);
    } catch (error) {
      this.logger.logError(requestOptions.method, url, error, Date.now() - startTime);
      throw error;
    }
  }
}

// Export singleton instance
export const apiClient = new ApiClient(API_BASE_URL);

// ============================================================================
// Error Utilities
// ============================================================================

export function isApiError(error: unknown): error is ApiError {
  return typeof error === "object" && error !== null && "statusCode" in error && "message" in error;
}

export function getErrorMessage(error: unknown): string {
  if (isApiError(error)) {
    // Handle array of validation errors
    if (Array.isArray(error.message)) {
      return error.message.join(", ");
    }
    return error.message;
  }
  if (error instanceof Error) {
    return error.message;
  }
  return "An unexpected error occurred";
}

export function getErrorDetails(error: unknown): Record<string, unknown> | undefined {
  if (isApiError(error)) {
    return {
      statusCode: error.statusCode,
      error: error.error,
      timestamp: error.timestamp,
      path: error.path,
      requestId: error.requestId,
      details: error.details,
      errors: error.errors,
    };
  }
  if (error instanceof Error) {
    return {
      name: error.name,
      message: error.message,
      stack: error.stack,
    };
  }
  return undefined;
}

/**
 * Format API error for user display
 */
export function formatApiError(error: unknown): {
  title: string;
  message: string;
  details?: string[];
} {
  if (isApiError(error)) {
    // If there are field-level validation errors, format them for display
    if (error.errors) {
      const fieldErrors: string[] = [];
      for (const [field, messages] of Object.entries(error.errors)) {
        const errorMessages = Array.isArray(messages) ? messages : [messages];
        fieldErrors.push(`${field}: ${errorMessages.join(", ")}`);
      }

      return {
        title: error.error || "Validation Error",
        message: (error.message as string) || "Please check the form for errors",
        details: fieldErrors,
      };
    }

    const details = Array.isArray(error.message) ? error.message : [error.message];

    return {
      title: error.error || "Error",
      message: details[0] || "An error occurred",
      details: details.length > 1 ? details.slice(1) : undefined,
    };
  }

  if (error instanceof Error) {
    return {
      title: error.name || "Error",
      message: error.message || "An unexpected error occurred",
    };
  }

  return {
    title: "Error",
    message: "An unexpected error occurred",
  };
}

// Restore auth token persisted across hard navigations (window.location.href)
if (typeof window !== "undefined") {
  const saved = sessionStorage.getItem("auth_token");
  if (saved) apiClient.setAuthToken(saved);
}

/**
 * Authentication Client
 *
 * Talks to the Loco backend's own auth routes. This is the one place the API
 * contract deliberately changed in the migration (decision D1): better-auth's
 * `/api/auth/*` catch-all — `sign-in/email`, `sign-up/email`, `sign-out`,
 * `get-session` — is gone, replaced by explicit handlers over Loco's native
 * JWT. Calling the old paths returns Loco's 404 page, which is what the login
 * screen used to render as "Sign in failed — Not Found".
 *
 *   POST /api/auth/login     -> { token, user }
 *   POST /api/auth/register  -> { user }
 *   POST /api/auth/logout
 *   GET  /api/auth/me        -> { user }
 *
 * Paths are relative so they go through the Vite dev proxy and stay same-origin
 * with the app. The backend sets the session as an httpOnly cookie *and*
 * returns the JWT in the body; `credentials: "include"` carries the cookie, and
 * the caller persists the token for `api-client` to send as a bearer header
 * after a hard navigation, when a client-side store would have been lost.
 */

const AUTH_BASE = "/api/auth";

/** Where the bearer token lives between a hard navigation and the next render. */
const TOKEN_KEY = "auth_token";

async function authFetch<T = unknown>(
  path: string,
  options: RequestInit = {}
): Promise<{ data: T | null; error: string | null }> {
  try {
    const hasBody = options.body != null;
    const headers: Record<string, string> = {
      ...(options.headers as Record<string, string>),
    };
    if (hasBody) {
      headers["Content-Type"] = "application/json";
    }

    // `/api/auth/me` is the only authenticated call here, and it can run before
    // the cookie is readable (first paint after a hard navigation). Sending the
    // stored token too means the session survives that window.
    const token =
      typeof window === "undefined" ? null : window.sessionStorage.getItem(TOKEN_KEY);
    if (token && !headers.Authorization) {
      headers.Authorization = `Bearer ${token}`;
    }

    const res = await fetch(`${AUTH_BASE}${path}`, {
      credentials: "include",
      ...options,
      headers,
    });

    const text = await res.text();
    let body: T | null = null;
    try {
      body = JSON.parse(text);
    } catch {
      // non-JSON response
    }

    if (!res.ok) {
      const message =
        (body as Record<string, string>)?.message ||
        (body as Record<string, string>)?.error ||
        res.statusText;
      return { data: null, error: message };
    }

    return { data: body, error: null };
  } catch (err: unknown) {
    return {
      data: null,
      error: err instanceof Error ? err.message : "Network error",
    };
  }
}

export async function signIn(email: string, password: string) {
  const result = await authFetch<{ token?: string; user?: unknown }>("/login", {
    method: "POST",
    body: JSON.stringify({ email, password }),
  });

  // Persisted here rather than at the call site so every entry point into
  // sign-in gets the same behaviour.
  const token = result.data?.token;
  if (token && typeof window !== "undefined") {
    window.sessionStorage.setItem(TOKEN_KEY, token);
  }
  return result;
}

/**
 * Register an account. Note this does *not* sign you in — the backend returns
 * the created user and no token, so the caller must follow with `signIn`.
 */
export async function signUp(email: string, password: string, name: string) {
  return authFetch("/register", {
    method: "POST",
    body: JSON.stringify({ email, password, name }),
  });
}

export async function signOut() {
  const result = await authFetch("/logout", { method: "POST" });
  // Drop the token whatever the server said. A logout that leaves a usable
  // bearer token behind has not logged anyone out.
  if (typeof window !== "undefined") {
    window.sessionStorage.removeItem(TOKEN_KEY);
  }
  return result;
}

export async function getSession() {
  return authFetch<{ user?: unknown }>("/me");
}

/**
 * The automation model — one sentence, three parts.
 *
 * "When an Order is created, only if Order.total is greater than 1000, then
 * look up a rule table, set a field, and create an Invoice."
 *
 * That sentence is the whole model. A trigger, a flat list of conditions that
 * must all pass, and an ordered list of steps. There is deliberately no graph
 * here: the executor runs steps in order and stops at the first failure, so a
 * list is the honest representation and the one the builder can draw as a
 * ladder without inventing layout the author never asked for.
 *
 * Storage is YAML: `lib/automation/yaml.ts` writes this model as its own
 * document, the way the application's model is written.
 */

import {
  type DecisionTable,
  emptyDecisionTable,
  STEP_TYPES,
  type StepType,
} from "../workflow/bpmn-model";

export type { DecisionTable, StepType };
export { emptyDecisionTable, STEP_TYPES };

/* -------------------------------------------------------------------------- */
/*  Triggers                                                                   */
/* -------------------------------------------------------------------------- */

/**
 * The events an automation can start from.
 *
 * These are the entity lifecycle hooks the generated services already fire, so
 * a trigger is not a new concept — it is the hook, named the way someone
 * describing their business would name it.
 */
export const TRIGGER_EVENTS = [
  "created",
  "beforeCreated",
  "updated",
  "beforeUpdated",
  "deleted",
  "beforeDeleted",
] as const;

export type TriggerEvent = (typeof TRIGGER_EVENTS)[number];

/** How each event reads in the builder, and what it means for the write. */
export const TRIGGER_LABELS: Record<TriggerEvent, string> = {
  created: "is created",
  beforeCreated: "is about to be created",
  updated: "is updated",
  beforeUpdated: "is about to be updated",
  deleted: "is deleted",
  beforeDeleted: "is about to be deleted",
};

export const TRIGGER_HINTS: Record<TriggerEvent, string> = {
  created: "Runs after the record is written. The record already exists.",
  beforeCreated: "Runs before the record is written, so it can still block the write.",
  updated: "Runs after the change is saved.",
  beforeUpdated: "Runs before the change is saved, so it can still block it.",
  deleted: "Runs after the record is removed.",
  beforeDeleted: "Runs before the record is removed, so it can still block it.",
};

/** The hook name each trigger maps to on the generated service. */
export const TRIGGER_HOOKS: Record<TriggerEvent, string> = {
  created: "afterCreate",
  beforeCreated: "beforeCreate",
  updated: "afterUpdate",
  beforeUpdated: "beforeUpdate",
  deleted: "afterDelete",
  beforeDeleted: "beforeDelete",
};

export interface Trigger {
  /** The entity this automation watches, e.g. "Order". */
  entity: string;
  event: TriggerEvent;
}

/* -------------------------------------------------------------------------- */
/*  Conditions                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * Comparison operators, worded as a check reads rather than as an expression.
 *
 * `arity: 0` means the operator takes no value — "is empty" has nothing on the
 * right-hand side, and the builder hides the value box for it rather than
 * leaving an input that must stay blank to be correct.
 */
export const OPERATORS = [
  { id: "eq", label: "is", arity: 1 },
  { id: "neq", label: "is not", arity: 1 },
  { id: "gt", label: "is greater than", arity: 1 },
  { id: "gte", label: "is greater than or equal to", arity: 1 },
  { id: "lt", label: "is less than", arity: 1 },
  { id: "lte", label: "is less than or equal to", arity: 1 },
  { id: "contains", label: "contains", arity: 1 },
  { id: "startsWith", label: "starts with", arity: 1 },
  { id: "isEmpty", label: "is empty", arity: 0 },
  { id: "isNotEmpty", label: "is not empty", arity: 0 },
  { id: "changed", label: "changed", arity: 0 },
] as const;

export type OperatorId = (typeof OPERATORS)[number]["id"];

export function operatorLabel(id: string): string {
  return OPERATORS.find((o) => o.id === id)?.label ?? id;
}

export function operatorArity(id: string): number {
  return OPERATORS.find((o) => o.id === id)?.arity ?? 1;
}

export interface Condition {
  id: string;
  /** Dotted path read from the run context, e.g. "order.total". */
  field: string;
  operator: OperatorId | string;
  /** Ignored when the operator takes no value. */
  value: string;
}

/* -------------------------------------------------------------------------- */
/*  Steps                                                                      */
/* -------------------------------------------------------------------------- */

/**
 * How each step type reads in the ladder and what it is for.
 *
 * The vocabulary is the executor's — Decision, CreateEntity, UpdateEntity,
 * DeleteEntity, Formula, REST — relabelled so the palette answers "what do I
 * want to happen" rather than "which node class is this".
 */
export const STEP_LABELS: Record<StepType, string> = {
  Decision: "Look up a rule table",
  CreateEntity: "Create a record",
  UpdateEntity: "Update a field",
  DeleteEntity: "Delete a record",
  Formula: "Work out a value",
  REST: "Call a web service",
};

export const STEP_HINTS: Record<StepType, string> = {
  Decision: "Ask a table of rules for an answer, then use it in a later step.",
  CreateEntity: "Insert a row and remember its id for later steps.",
  UpdateEntity: "Write one field, on this record or a related one.",
  DeleteEntity: "Soft delete by default, so the audit trail still resolves.",
  Formula: "Set, copy, add, subtract, multiply or divide.",
  REST: "POST to an external URL and keep the response.",
};

/** A single glyph per step type. Kept text so it renders without an icon font. */
export const STEP_GLYPHS: Record<StepType, string> = {
  Decision: "▤",
  CreateEntity: "✚",
  UpdateEntity: "✎",
  DeleteEntity: "✕",
  Formula: "ƒ",
  REST: "↗",
};

export interface AutomationStep {
  id: string;
  type: StepType;
  /**
   * What later steps call this step's result. Empty means the step produces
   * nothing worth naming (a delete, usually).
   */
  resultName: string;
  /** Type-specific configuration. Keys are documented per type in STEP_FIELDS. */
  props: Record<string, string>;
  /**
   * The loop this step belongs to, if any. At most one: loops do not nest, so
   * a step is either inside exactly one repeat or outside them all.
   */
  loopId?: string;
  /** Only set on Decision steps that own an inline table rather than a shared one. */
  table?: DecisionTable;
}

/** Which property fields each step type shows, in the order they read. */
export const STEP_FIELDS: Record<StepType, readonly string[]> = {
  Decision: ["ruleTable", "inputs"],
  CreateEntity: ["entity", "values"],
  UpdateEntity: ["entity", "field", "value"],
  DeleteEntity: ["entity", "target"],
  Formula: ["operation", "left", "right"],
  REST: ["method", "url", "body"],
};

/* -------------------------------------------------------------------------- */
/*  Loops                                                                      */
/* -------------------------------------------------------------------------- */

/**
 * Repeat while a rule holds — the steps run again and again until the check
 * fails.
 *
 * The check is re-evaluated before every pass against the record *as it stands
 * then*, which is the point: a step inside the loop changes the record, and
 * that change is what eventually ends the loop.
 *
 * This is genuinely unbounded, and an automation runs inside the write that
 * triggered it — so a check that never fails does not spin a harmless
 * background job, it holds a database transaction open until something times
 * out. `maxPasses` is the backstop, and every loop must state its own. It is
 * not a second way to say "how many times": reaching it means the automation
 * was wrong, so the run is marked failed and says so, rather than finishing
 * quietly as though the loop had ended on its own.
 */
export interface Loop {
  id: string;
  /** Re-checked before each pass. The loop ends the first time it fails. */
  condition: Condition;
  /**
   * Passes after which this loop is abandoned and the run reported as failed.
   *
   * Required, and deliberately per-loop rather than a constant: how many passes
   * is "obviously too many" is a property of the work, not of the engine. A
   * retry loop that should give up after 5 and a reconciliation that legitimately
   * runs 800 cannot share one number without the ceiling being meaningless for
   * one of them.
   *
   * Held as a string because it is bound to a text input; validation is what
   * turns it into a number.
   */
  maxPasses: string;
}

/**
 * Smallest sensible ceiling. There is no upper bound — the author owns the
 * number, and capping it here would be the hardcoded limit this replaced.
 */
export const LOOP_MIN_PASSES = 1;

/**
 * A tolerant read of `loops`.
 *
 * Automations stored before loops existed have no such field, and they are the
 * majority of what is in any database today. Defaulting here rather than at
 * each call site means an old record opens and serialises unchanged instead of
 * throwing in whichever function reaches it first.
 */
export function loopsOf(automation: Automation): Loop[] {
  return automation.loops ?? [];
}

/** The steps belonging to a loop, in ladder order. */
export function stepsInLoop(automation: Automation, loopId: string): AutomationStep[] {
  return automation.steps.filter((step) => step.loopId === loopId);
}

/** The loop a step sits in, if any. */
export function loopOf(automation: Automation, step: AutomationStep): Loop | undefined {
  return step.loopId ? loopsOf(automation).find((l) => l.id === step.loopId) : undefined;
}

/**
 * A loop's members must sit together in the ladder.
 *
 * The list is the running order, so members split by an outside step would mean
 * the workflow runs A, (something else), B and repeats only part of it — a
 * shape the drawn subgraph could not honestly represent either.
 */
export function loopIsContiguous(automation: Automation, loopId: string): boolean {
  const positions = automation.steps
    .map((step, i) => (step.loopId === loopId ? i : -1))
    .filter((i) => i >= 0);
  if (positions.length === 0) return true;
  const first = positions[0] as number;
  return positions.every((position, offset) => position === first + offset);
}

/* -------------------------------------------------------------------------- */
/*  The automation                                                             */
/* -------------------------------------------------------------------------- */

/* -------------------------------------------------------------------------- */
/*  Hook rungs — the multi-trigger case                                        */
/* -------------------------------------------------------------------------- */

/**
 * The thirteen lifecycle events, in the order they run.
 *
 * Wider than `TRIGGER_EVENTS`, which names only the six an automation can
 * *start* from. A hook workflow binds handlers to any of these, including the
 * read and list points that have no "when this happens, then do that" reading.
 */
export const HOOK_EVENTS = [
  "beforeCreate",
  "afterCreate",
  "beforeUpdate",
  "afterUpdate",
  "beforeDelete",
  "afterDelete",
  "beforeRead",
  "afterRead",
  "beforeQuery",
  "afterQuery",
  "beforeList",
  "afterList",
  "customValidate",
] as const;

export type HookEvent = (typeof HOOK_EVENTS)[number];

export const HOOK_EVENT_HINTS: Record<HookEvent, string> = {
  beforeCreate: "Runs before a record is written — hash a password, set a default.",
  afterCreate: "Runs once the record exists — send a welcome email, emit an event.",
  beforeUpdate: "Validate or transform before the write.",
  afterUpdate: "Audit the change, invalidate a cache.",
  beforeDelete: "Block the delete if the record is still referenced.",
  afterDelete: "Clean up related rows or files.",
  beforeRead: "Guard a single-record read.",
  afterRead: "Redact or enrich a record on the way out.",
  beforeQuery: "Scope the query — tenant filters, injected conditions.",
  afterQuery: "Post-process the rows that came back.",
  beforeList: "Adjust filtering, sorting or pagination.",
  afterList: "Post-process a page of results.",
  customValidate: "Cross-field or business validation on any write.",
};

/**
 * One named handler bound to one lifecycle event.
 *
 * This is the rung a hook workflow is made of, and the reason `trigger` alone
 * could not carry it: `ContactHygiene` binds twelve handlers across
 * beforeCreate, customValidate, afterUpdate and beforeList. That is not one
 * automation with twelve steps — it is twelve triggers, each with its own
 * handler, sharing a name and an entity. A single `trigger` field can only say
 * one of them, so reading such a workflow through the automation shape dropped
 * every handler.
 */
export interface AutomationHook {
  id: string;
  event: HookEvent;
  /** Generated function name — the handler the backend will call. */
  handler: string;
  /** Optional field the hook is scoped to. */
  field?: string;
}

/**
 * Which shape an automation is.
 *
 * `automation` is the original sentence: one trigger, conditions, ordered
 * steps. `hook` is the multi-trigger list above. `saga` is the same ordered
 * steps as an automation, started by a rule rather than by a lifecycle event.
 * They share a rail, a ladder and an inspector; they differ in what a rung
 * means and in how the run begins.
 */
export type AutomationKind = "automation" | "hook" | "saga";

/** How a saga is started. `rule` means a business rule's trigger-workflow action names it. */
export type SagaTrigger = "automatic" | "rule";
export type SagaOperation = "CREATE" | "UPDATE" | "DELETE" | "ALL";

export type AutomationStatus = "draft" | "live" | "paused";

export interface Automation {
  id: string;
  name: string;
  description?: string;
  kind: AutomationKind;
  trigger: Trigger;
  conditions: Condition[];
  /** Bounded repeats. A step joins one by carrying its id in `loopId`. */
  loops: Loop[];
  steps: AutomationStep[];
  /**
   * The rungs, when `kind` is `hook`. Each carries its own event, so
   * `trigger.event` is not meaningful for a hook workflow — only
   * `trigger.entity` is, because every hook binds to the same record type.
   */
  hooks: AutomationHook[];
  /**
   * How a saga starts, when `kind` is `saga`.
   *
   * They are the saga's own `trigger` and `operation`, carried here rather than
   * inferred from `trigger`. Reading a saga into the single-trigger shape
   * mapped `operation` onto a lifecycle event and threw both away: a
   * `trigger: rule` saga came back as "runs when created", and saving it said
   * so.
   */
  sagaTrigger?: SagaTrigger;
  sagaOperation?: SagaOperation;
  status: AutomationStatus;
  updatedAt?: string;
}

export function isHookWorkflow(automation: Automation): boolean {
  return automation.kind === "hook";
}

export function newHook(event: HookEvent = "beforeCreate"): AutomationHook {
  return { id: newId("hook"), event, handler: "", field: "" };
}

export function describeHook(hook: AutomationHook): string {
  return `${hook.event} → ${hook.handler || "(unnamed)"}${hook.field ? ` · ${hook.field}` : ""}`;
}

let seq = 0;
export function newId(prefix: string): string {
  seq += 1;
  return `${prefix}_${seq.toString(36)}${Date.now().toString(36)}`;
}

export function emptyAutomation(entity: string, kind: AutomationKind = "automation"): Automation {
  return {
    id: newId("auto"),
    name:
      kind === "hook"
        ? "Untitled process"
        : kind === "saga"
          ? "Untitled process"
          : "Untitled automation",
    kind,
    trigger: { entity, event: "created" },
    conditions: [],
    loops: [],
    steps: [],
    hooks: kind === "hook" ? [newHook()] : [],
    ...(kind === "saga" ? { sagaTrigger: "rule" as const, sagaOperation: "CREATE" as const } : {}),
    status: "draft",
  };
}

export function newCondition(): Condition {
  return { id: newId("cond"), field: "", operator: "eq", value: "" };
}

/**
 * A new loop, named `L1`, `L2`, … rather than with the opaque id every other
 * object gets. The id is what an author types in `{{L1.iteration}}` and what
 * they read in the serialised model, so it has to be short and predictable.
 */
export function newLoop(existing: Loop[]): Loop {
  let n = existing.length + 1;
  while (existing.some((loop) => loop.id === `L${n}`)) n += 1;
  // Empty rather than pre-filled: the ceiling is a decision about this
  // particular loop, and a default would be accepted unread by most authors.
  return { id: `L${n}`, condition: newCondition(), maxPasses: "" };
}

/** How a loop reads on its card: "Repeat while status is open". */
export function describeLoop(loop: Loop): string {
  const check = loop.condition.field
    ? describeCondition(loop.condition)
    : "a check that is not set yet";
  return `Repeat while ${check}`;
}

export function newStep(type: StepType): AutomationStep {
  return {
    id: newId("step"),
    type,
    resultName: defaultResultName(type),
    props: {},
    ...(type === "Decision" ? {} : {}),
  };
}

function defaultResultName(type: StepType): string {
  switch (type) {
    case "Decision":
      return "decision";
    case "CreateEntity":
      return "createdId";
    case "Formula":
      return "value";
    case "REST":
      return "response";
    default:
      return "";
  }
}

/* -------------------------------------------------------------------------- */
/*  Reading an automation back as a sentence                                   */
/* -------------------------------------------------------------------------- */

/** The trigger line, as the WHEN card shows it. */
export function describeTrigger(t: Trigger): string {
  return `${article(t.entity)} ${t.entity} ${TRIGGER_LABELS[t.event] ?? t.event}`;
}

/** One condition, as the IF card shows it. */
export function describeCondition(c: Condition): string {
  const op = operatorLabel(c.operator);
  return operatorArity(c.operator) === 0
    ? `${c.field || "a field"} ${op}`
    : `${c.field || "a field"} ${op} ${c.value || "…"}`;
}

/** One step, as the THEN card shows it. */
export function describeStep(s: AutomationStep): string {
  const p = s.props;
  switch (s.type) {
    case "Decision":
      return `Look up ${p.ruleTable || "a rule table"}${s.resultName ? ` → ${s.resultName}` : ""}`;
    case "CreateEntity":
      return `Create ${article(p.entity || "record")} ${p.entity || "record"}${
        s.resultName ? ` → ${s.resultName}` : ""
      }`;
    case "UpdateEntity":
      return `Set ${p.entity && p.field ? `${p.entity}.${p.field}` : p.field || "a field"} to ${
        p.value || "…"
      }`;
    case "DeleteEntity":
      return `Delete ${article(p.entity || "record")} ${p.entity || "record"}`;
    case "Formula":
      return `${p.operation || "Set"} ${p.left || "…"}${p.right ? ` and ${p.right}` : ""}${
        s.resultName ? ` → ${s.resultName}` : ""
      }`;
    case "REST":
      return `${p.method || "POST"} to ${p.url || "a URL"}${
        s.resultName ? ` → ${s.resultName}` : ""
      }`;
    default:
      return STEP_LABELS[s.type] ?? s.type;
  }
}

function article(word: string): string {
  return /^[aeiou]/i.test(word) ? "an" : "a";
}

/* -------------------------------------------------------------------------- */
/*  Values available at a point in the run                                     */
/* -------------------------------------------------------------------------- */

export interface AvailableValue {
  /** The reference an author types, without braces, e.g. "tier.discount_pct". */
  path: string;
  type: string;
  /** Where it came from, shown beside the path. */
  origin: string;
}

/**
 * Everything a step at `index` may reference.
 *
 * Only values produced *above* the step are returned, so the picker can never
 * offer a reference to a step that has not run yet — the single most common way
 * a hand-written workflow breaks in production.
 */
export function valuesAvailableAt(
  automation: Automation,
  index: number,
  entityFields: Record<string, string[]> = {}
): AvailableValue[] {
  const out: AvailableValue[] = [];
  const entity = automation.trigger.entity;
  const root = entity.toLowerCase();

  for (const field of entityFields[entity] ?? []) {
    out.push({ path: `${root}.${field}`, type: "field", origin: entity });
  }
  if (out.length === 0) {
    out.push({ path: `${root}.id`, type: "uuid", origin: entity });
  }

  // Only offered to steps actually inside the repeat — outside it the pass
  // number has no meaning, and a picker that offers it anyway teaches the
  // wrong model of when a loop variable exists.
  const own = automation.steps[index];
  const loop = own ? loopOf(automation, own) : undefined;
  if (loop) {
    out.push({
      path: `${loop.id}.iteration`,
      type: "number",
      origin: `repeat ${loop.id}`,
    });
  }

  automation.steps.slice(0, Math.max(0, index)).forEach((step, i) => {
    if (!step.resultName) return;
    const origin = `step ${i + 1}`;
    if (step.type === "Decision") {
      const outputs = step.table?.outputs ?? [];
      if (outputs.length === 0) {
        out.push({ path: step.resultName, type: "answer", origin });
      }
      for (const o of outputs) {
        out.push({ path: `${step.resultName}.${o.field || o.name}`, type: "answer", origin });
      }
    } else {
      out.push({ path: step.resultName, type: stepResultType(step.type), origin });
    }
  });

  return out;
}

function stepResultType(type: StepType): string {
  switch (type) {
    case "CreateEntity":
      return "uuid";
    case "Formula":
      return "value";
    case "REST":
      return "response";
    default:
      return "value";
  }
}

/* -------------------------------------------------------------------------- */
/*  Validation — stated as the author would fix it                             */
/* -------------------------------------------------------------------------- */

export interface Problem {
  /** Which card the problem belongs to, so the ladder can mark it. */
  target: string;
  message: string;
}

export function validateAutomation(automation: Automation): Problem[] {
  const problems: Problem[] = [];

  if (!automation.name.trim()) {
    problems.push({ target: "name", message: "Give the automation a name." });
  }
  if (!automation.trigger.entity.trim()) {
    problems.push({ target: "trigger", message: "Pick the record type this watches." });
  }

  // A hook workflow starts from one or more lifecycle rungs. It has no single
  // `trigger.event`, so validate the handlers, then fall through to check any
  // conditions and steps the author added after them.
  if (automation.kind === "hook") {
    if (automation.hooks.length === 0) {
      problems.push({ target: "hooks", message: "Add at least one lifecycle step." });
    }
    const seen = new Set<string>();
    for (const hook of automation.hooks) {
      if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(hook.handler)) {
        problems.push({
          target: hook.id,
          message: `"${hook.handler || "(unnamed)"}" is not a valid handler name — letters, digits and underscore, not starting with a digit.`,
        });
      }
      const key = `${hook.event}:${hook.handler}`;
      if (seen.has(key)) {
        problems.push({
          target: hook.id,
          message: `${hook.event} ${hook.handler} is listed twice, so it would run twice.`,
        });
      }
      seen.add(key);
    }
  }

  for (const c of automation.conditions) {
    if (!c.field.trim()) {
      problems.push({ target: c.id, message: "This check does not say which field to look at." });
    } else if (operatorArity(c.operator) === 1 && !c.value.trim()) {
      problems.push({
        target: c.id,
        message: `"${c.field} ${operatorLabel(c.operator)}" needs a value to compare against.`,
      });
    }
  }

  // A hook's rungs are what it does, so an empty step list is not a problem
  // there the way it is for an automation — but steps it does carry are checked.
  if (automation.kind !== "hook" && automation.steps.length === 0) {
    problems.push({ target: "steps", message: "Add at least one thing for this to do." });
  }

  const named = new Set<string>();
  automation.steps.forEach((step, i) => {
    for (const field of STEP_FIELDS[step.type] ?? []) {
      if (field === "inputs" || field === "values" || field === "body") continue;
      // A Decision may carry its own table instead of naming a saved rule —
      // the shape every saga in the example models uses — and an UpdateEntity
      // with no record type writes the record that triggered the run. Demanding
      // either told authors their working process was broken.
      if (field === "ruleTable" && step.table) continue;
      if (field === "entity" && step.type === "UpdateEntity") continue;
      if (!(step.props[field] ?? "").trim()) {
        problems.push({
          target: step.id,
          message: `Step ${i + 1} is missing ${humanField(field)}.`,
        });
      }
    }
    if (step.resultName) {
      if (named.has(step.resultName)) {
        problems.push({
          target: step.id,
          message: `Two steps both save their answer as "${step.resultName}". Rename one.`,
        });
      }
      named.add(step.resultName);
    }
  });

  for (const loop of loopsOf(automation)) {
    const members = stepsInLoop(automation, loop.id);
    if (members.length === 0) {
      problems.push({
        target: loop.id,
        message: `Repeat ${loop.id} has no steps in it. Add one, or remove the repeat.`,
      });
      continue;
    }

    if (!loopIsContiguous(automation, loop.id)) {
      problems.push({
        target: loop.id,
        message: `The steps in repeat ${loop.id} have something else between them. Move them together.`,
      });
    }

    const check = loop.condition;
    if (!check.field.trim()) {
      problems.push({
        target: loop.id,
        message: `Repeat ${loop.id} does not say what to check, so it would never stop.`,
      });
    } else if (operatorArity(check.operator) === 1 && !check.value.trim()) {
      problems.push({
        target: loop.id,
        message: `"${check.field} ${operatorLabel(check.operator)}" needs a value to compare against.`,
      });
    }

    const max = loop.maxPasses.trim();
    if (!max) {
      problems.push({
        target: loop.id,
        message: `Say how many passes ${loop.id} may run before it gives up. There is no default.`,
      });
    } else {
      const n = Number(max);
      if (!Number.isInteger(n)) {
        problems.push({
          target: loop.id,
          message: `"${max}" is not a whole number of passes for repeat ${loop.id}.`,
        });
      } else if (n < LOOP_MIN_PASSES) {
        problems.push({
          target: loop.id,
          message: `Repeat ${loop.id} must be allowed at least ${LOOP_MIN_PASSES} pass.`,
        });
      }
    }

    // A check on a field no step in the loop writes cannot change between
    // passes, so the loop either never runs or runs until the safety limit
    // aborts it. Both are bugs, and both are invisible until it is live.
    if (check.field.trim() && !membersCanChange(members, check.field)) {
      problems.push({
        target: loop.id,
        message:
          `Nothing inside repeat ${loop.id} changes "${check.field}", so the check will ` +
          `read the same every pass. Add a step that updates it, or the repeat will run ` +
          `until it is cut off at its limit of ${loop.maxPasses || "?"} passes.`,
      });
    }
  }

  return problems;
}

/**
 * Does any step in the loop write the field the loop checks?
 *
 * Deliberately shallow — it matches an `UpdateEntity` on the field by name and
 * treats every other step type as opaque. A `REST` call or a `Decision` can
 * change the world in ways this cannot see, so this only ever reports the case
 * it is certain about: a loop whose body contains no write to that field at all.
 */
function membersCanChange(members: AutomationStep[], field: string): boolean {
  const bare = field.includes(".") ? (field.split(".").pop() as string) : field;
  return members.some((step) => {
    if (step.type !== "UpdateEntity") return true;
    const written = (step.props.field ?? "").trim();
    return written === "" || written === bare || written === field;
  });
}

function humanField(field: string): string {
  switch (field) {
    case "ruleTable":
      return "a rule table to look up";
    case "entity":
      return "a record type";
    case "field":
      return "a field to write";
    case "value":
      return "a value to write";
    case "operation":
      return "an operation";
    case "left":
      return "a value to work from";
    case "url":
      return "a URL";
    case "method":
      return "a method";
    case "target":
      return "a record to delete";
    default:
      return field;
  }
}

/**
 * Reading and writing what the rules API stores.
 *
 * Rules predate the rule-table editor, so `jdm_content` may hold either a
 * decision table or an older JDM decision graph. Anything that is not a table
 * opens as an empty one rather than a guessed conversion: a graph flattened by
 * assumption would look like a working table while deciding something different,
 * and visibly empty is the failure an author can actually see and fix.
 */

import { type DecisionTable, emptyDecisionTable } from "../workflow/bpmn-model";

/** What the rules API round-trips. Kept loose because older rows vary. */
export type StoredRuleContent = DecisionTable | Record<string, unknown>;

export function isDecisionTable(content: unknown): content is DecisionTable {
  if (!content || typeof content !== "object") return false;
  const c = content as Partial<DecisionTable>;
  return Array.isArray(c.inputs) && Array.isArray(c.outputs) && Array.isArray(c.rules);
}

/** A table to edit, whatever was stored. */
export function asDecisionTable(content: unknown): DecisionTable {
  // Parse JSON strings that came back from the API as raw text
  const parsed: unknown =
    typeof content === "string"
      ? (() => {
          try {
            return JSON.parse(content);
          } catch {
            return null;
          }
        })()
      : content;

  if (isDecisionTable(parsed)) {
    const t = parsed as DecisionTable;
    return {
      hitPolicy: t.hitPolicy === "collect" ? "collect" : "first",
      inputs: t.inputs,
      outputs: t.outputs,
      rules: t.rules,
    };
  }

  // JDM graph format: { name, nodes: [..., { type: "decisionTableNode", content: {...} }] }
  if (
    parsed &&
    typeof parsed === "object" &&
    Array.isArray((parsed as Record<string, unknown>).nodes)
  ) {
    const nodes = (parsed as { nodes: unknown[] }).nodes;
    for (const node of nodes) {
      if (
        node &&
        typeof node === "object" &&
        (node as Record<string, unknown>).type === "decisionTableNode"
      ) {
        const tableContent = (node as Record<string, unknown>).content;
        if (isDecisionTable(tableContent)) {
          const t = tableContent as DecisionTable;
          return {
            hitPolicy: t.hitPolicy === "collect" ? "collect" : "first",
            inputs: t.inputs,
            outputs: t.outputs,
            rules: t.rules,
          };
        }
      }
    }
  }

  return emptyDecisionTable();
}

/** The older decision-graph shape, still accepted on write for existing tooling. */
export function isJdmGraph(content: unknown): boolean {
  if (!content || typeof content !== "object") return false;
  const c = content as { name?: unknown; nodes?: unknown };
  return typeof c.name === "string" && Array.isArray(c.nodes) && c.nodes.length > 0;
}

/**
 * What is wrong with a rule someone is trying to save, in the words they would
 * use to fix it. Empty means it is fine.
 *
 * Both shapes are accepted: a decision table, which is what the rule table
 * editor writes, and a JDM graph, which is what older rules and any external
 * tooling still write. Validating only the graph shape is what made the table
 * editor unable to save at all.
 */
export function validateStoredRuleContent(content: unknown): string[] {
  if (!content || typeof content !== "object") {
    return ["The rule has no content. Add at least one row."];
  }

  if (isDecisionTable(content)) {
    const table = content as DecisionTable;
    const problems: string[] = [];
    if (table.inputs.length === 0) problems.push("Add at least one input column to test against.");
    if (table.outputs.length === 0) {
      problems.push("Add at least one outcome column — a table that decides nothing does nothing.");
    }
    if (table.rules.length === 0) problems.push("Add at least one row.");
    for (const column of [...table.inputs, ...table.outputs]) {
      if (!String(column.field ?? "").trim()) {
        problems.push(`Column "${column.name || column.id}" does not say which field it reads.`);
      }
    }
    return problems;
  }

  if (isJdmGraph(content)) return [];

  return [
    "The rule content is neither a decision table nor a decision graph. Build it in the rule table editor.",
  ];
}

/**
 * Whether opening this rule will lose what was stored.
 *
 * True for a rule saved as something other than a table — the editor shows an
 * empty table, and saving would replace the old content. The routes use this to
 * warn before that happens rather than after.
 */
export function wouldReplaceStoredContent(content: unknown): boolean {
  return content !== null && content !== undefined && !isDecisionTable(content);
}

/**
 * Automations, stored as YAML.
 *
 * The application's model is written in YAML, so an automation built here is
 * stored the same way: as the YAML document of the automation's own model — a
 * trigger, conditions, loops, ordered steps — in
 * `sys_workflow_definitions.definition_yaml`. The backend checks the document's
 * shape before it stores it. Every automation is stored this way: migration
 * m0017 converted the rows an earlier release had written otherwise.
 */

import { parse, stringify } from "yaml";
import {
  type Automation,
  type AutomationHook,
  type AutomationKind,
  type AutomationStatus,
  type AutomationStep,
  type Condition,
  type DecisionTable,
  type HookEvent,
  HOOK_EVENTS,
  type Loop,
  loopsOf,
  newId,
  type SagaOperation,
  type SagaTrigger,
  STEP_TYPES,
  type StepType,
  TRIGGER_EVENTS,
  type TriggerEvent,
} from "./model";

/** The document version this application writes and reads. */
export const AUTOMATION_DOCUMENT_VERSION = "1.0";

const KINDS: readonly AutomationKind[] = ["automation", "hook", "saga"];
const STATUSES: readonly AutomationStatus[] = ["draft", "live", "paused"];
const SAGA_TRIGGERS: readonly SagaTrigger[] = ["automatic", "rule"];
const SAGA_OPERATIONS: readonly SagaOperation[] = ["CREATE", "UPDATE", "DELETE", "ALL"];

function conditionDocument(condition: Condition) {
  return {
    id: condition.id,
    field: condition.field,
    operator: condition.operator,
    value: condition.value,
  };
}

/**
 * The automation as its YAML document.
 *
 * Keys in a fixed order and nothing that belongs to the screen rather than the
 * automation (its in-memory id, when it was last touched), so saving the same
 * automation twice writes the same bytes.
 */
export function automationToYaml(automation: Automation): string {
  const document = {
    automation: AUTOMATION_DOCUMENT_VERSION,
    name: automation.name,
    ...(automation.description ? { description: automation.description } : {}),
    kind: automation.kind,
    trigger: { entity: automation.trigger.entity, event: automation.trigger.event },
    ...(automation.kind === "saga"
      ? {
          sagaTrigger: automation.sagaTrigger ?? "automatic",
          sagaOperation: automation.sagaOperation ?? "CREATE",
        }
      : {}),
    conditions: automation.conditions.map(conditionDocument),
    loops: loopsOf(automation).map((loop) => ({
      id: loop.id,
      condition: conditionDocument(loop.condition),
      maxPasses: loop.maxPasses,
    })),
    steps: automation.steps.map((step) => ({
      id: step.id,
      type: step.type,
      resultName: step.resultName,
      props: { ...step.props },
      ...(step.loopId ? { loopId: step.loopId } : {}),
      ...(step.table ? { table: step.table } : {}),
    })),
    hooks: automation.hooks.map((hook) => ({
      id: hook.id,
      event: hook.event,
      handler: hook.handler,
      ...(hook.field ? { field: hook.field } : {}),
    })),
    status: automation.status,
  };
  return stringify(document, { lineWidth: 0 });
}

/** Why a stored document could not be read, naming the key at fault. */
export class AutomationDocumentError extends Error {
  constructor(reason: string) {
    super(`This automation's stored YAML ${reason}`);
    this.name = "AutomationDocumentError";
  }
}

type Mapping = Record<string, unknown>;

function isMapping(value: unknown): value is Mapping {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function text(value: unknown, key: string): string {
  if (value === undefined || value === null) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  throw new AutomationDocumentError(`has a \`${key}\` that is not text`);
}

function list(document: Mapping, key: string): unknown[] {
  const value = document[key];
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value))
    throw new AutomationDocumentError(`has a \`${key}:\` that is not a list`);
  return value;
}

function oneOf<T extends string>(value: unknown, allowed: readonly T[], key: string): T {
  const read = text(value, key);
  if (!(allowed as readonly string[]).includes(read)) {
    throw new AutomationDocumentError(
      `has \`${key}: ${read}\`; expected one of ${allowed.join(", ")}`
    );
  }
  return read as T;
}

function readCondition(value: unknown, key: string): Condition {
  if (!isMapping(value))
    throw new AutomationDocumentError(`has a \`${key}\` that is not a mapping`);
  return {
    id: text(value.id, `${key}.id`) || newId("cond"),
    field: text(value.field, `${key}.field`),
    operator: text(value.operator, `${key}.operator`),
    value: text(value.value, `${key}.value`),
  };
}

function readProps(value: unknown, key: string): Record<string, string> {
  if (value === undefined || value === null) return {};
  if (!isMapping(value))
    throw new AutomationDocumentError(`has a \`${key}\` that is not a mapping`);
  const props: Record<string, string> = {};
  for (const [name, entry] of Object.entries(value)) props[name] = text(entry, `${key}.${name}`);
  return props;
}

/**
 * Read an automation's YAML document. Throws `AutomationDocumentError`, naming
 * the key at fault, for a document that is not one.
 */
export function automationFromYaml(source: string): Automation {
  let document: unknown;
  try {
    document = parse(source, { uniqueKeys: true });
  } catch (error) {
    throw new AutomationDocumentError(
      `is not YAML: ${error instanceof Error ? error.message.split("\n")[0] : String(error)}`
    );
  }
  if (!isMapping(document)) throw new AutomationDocumentError("is not a YAML mapping");

  const version = text(document.automation, "automation");
  if (version !== AUTOMATION_DOCUMENT_VERSION) {
    throw new AutomationDocumentError(
      version
        ? `is version ${version}; this application reads version ${AUTOMATION_DOCUMENT_VERSION}`
        : "has no `automation:` version key"
    );
  }

  const kind = oneOf(document.kind, KINDS, "kind");
  if (!isMapping(document.trigger)) throw new AutomationDocumentError("has no `trigger:` mapping");
  const entity = text(document.trigger.entity, "trigger.entity");
  if (!entity) throw new AutomationDocumentError("needs `trigger.entity`");

  const loops: Loop[] = list(document, "loops").map((value, index) => {
    const key = `loops[${index}]`;
    if (!isMapping(value))
      throw new AutomationDocumentError(`has a \`${key}\` that is not a mapping`);
    return {
      id: text(value.id, `${key}.id`) || newId("loop"),
      condition: readCondition(value.condition, `${key}.condition`),
      maxPasses: text(value.maxPasses, `${key}.maxPasses`),
    };
  });

  const declaredLoops = new Set(loops.map((loop) => loop.id));
  const steps: AutomationStep[] = list(document, "steps").map((value, index) => {
    const key = `steps[${index}]`;
    if (!isMapping(value))
      throw new AutomationDocumentError(`has a \`${key}\` that is not a mapping`);
    const loopId = text(value.loopId, `${key}.loopId`);
    // A step in a repeat nobody declared has no check to repeat on: it would
    // run once and look as though it had repeated.
    if (loopId && !declaredLoops.has(loopId)) {
      throw new AutomationDocumentError(
        `has \`${key}.loopId: ${loopId}\`, a repeat the document does not declare`
      );
    }
    return {
      id: text(value.id, `${key}.id`) || newId("step"),
      type: oneOf(value.type, STEP_TYPES as readonly StepType[], `${key}.type`),
      resultName: text(value.resultName, `${key}.resultName`),
      props: readProps(value.props, `${key}.props`),
      ...(loopId ? { loopId } : {}),
      ...(isMapping(value.table) ? { table: value.table as unknown as DecisionTable } : {}),
    };
  });

  const hooks: AutomationHook[] = list(document, "hooks").map((value, index) => {
    const key = `hooks[${index}]`;
    if (!isMapping(value))
      throw new AutomationDocumentError(`has a \`${key}\` that is not a mapping`);
    const field = text(value.field, `${key}.field`);
    return {
      id: text(value.id, `${key}.id`) || newId("hook"),
      event: oneOf(value.event, HOOK_EVENTS as readonly HookEvent[], `${key}.event`),
      handler: text(value.handler, `${key}.handler`),
      ...(field ? { field } : {}),
    };
  });

  const description = text(document.description, "description");
  return {
    id: newId("auto"),
    name: text(document.name, "name"),
    ...(description ? { description } : {}),
    kind,
    trigger: {
      entity,
      event: oneOf(
        document.trigger.event,
        TRIGGER_EVENTS as readonly TriggerEvent[],
        "trigger.event"
      ),
    },
    conditions: list(document, "conditions").map((value, index) =>
      readCondition(value, `conditions[${index}]`)
    ),
    loops,
    steps,
    hooks,
    ...(kind === "saga"
      ? {
          sagaTrigger: oneOf(document.sagaTrigger ?? "automatic", SAGA_TRIGGERS, "sagaTrigger"),
          sagaOperation: oneOf(
            document.sagaOperation ?? "CREATE",
            SAGA_OPERATIONS,
            "sagaOperation"
          ),
        }
      : {}),
    status: oneOf(document.status ?? "draft", STATUSES, "status"),
  };
}

/** A stored `sys_workflow_definitions` row, as the list endpoint returns it. */
export interface StoredAutomationRow {
  id: string;
  name: string;
  entity_name?: string;
  definition_yaml?: string | null;
}

/**
 * The automation a stored row holds, named as the row names it. A row with no
 * document is refused by name rather than opened empty: saving an empty one
 * would overwrite whatever the row was meant to hold.
 */
export function readStoredAutomation(row: StoredAutomationRow): Automation {
  if (!row.definition_yaml) {
    throw new AutomationDocumentError(`for "${row.name}" is missing`);
  }
  return { ...automationFromYaml(row.definition_yaml), name: row.name };
}

/**
 * Optimistic locking, as the screens see it.
 *
 * Every record the API returns carries its `version`, and every save names the
 * version it was read at (`If-Match: "v<n>"`). When someone else has saved the
 * record since, the API refuses with 409 and a `conflict` describing the record
 * as it now stands — who changed it, when, which fields, and where its
 * transaction stands — so the screen can offer to refresh or to overwrite
 * without a second request. A record in a final state of its lifecycle is a
 * completed transaction: the API refuses every save to it, and the only choice
 * offered is to refresh.
 *
 * The backend's half is `services/concurrency.rs`; the shapes below are its
 * response, field for field.
 */

/** Where a record's transaction stands. Present only on tables with a lifecycle. */
export interface TransactionStatus {
  field: string;
  value: string | null;
  label: string | null;
  isFinal: boolean;
}

/** The `conflict` a 409 carries. */
export interface VersionConflict {
  yourVersion: number | null;
  currentVersion: number | null;
  changedBy: string | null;
  changedAt: string | null;
  changedFields: string[];
  current: Record<string, unknown>;
  status: TransactionStatus | null;
  /** False for a record in a final state: refresh is the only way forward. */
  overwritable: boolean;
}

/** The two refusals, by the code the API puts in `error`. */
export type ConcurrencyCode = "VERSION_CONFLICT" | "RECORD_FINAL";

export interface ConcurrencyError {
  statusCode: 409;
  error: ConcurrencyCode;
  message: string;
  conflict: VersionConflict;
}

/** Whether an error thrown by the API client is a concurrency refusal. */
export function isConcurrencyError(error: unknown): error is ConcurrencyError {
  if (typeof error !== "object" || error === null) return false;
  const candidate = error as Partial<ConcurrencyError>;
  return (
    candidate.statusCode === 409 &&
    (candidate.error === "VERSION_CONFLICT" || candidate.error === "RECORD_FINAL") &&
    typeof candidate.conflict === "object" &&
    candidate.conflict !== null
  );
}

/** The record's version, when it has one. */
export function versionOf(record: Record<string, unknown> | null | undefined): number | null {
  const version = record?.version;
  return typeof version === "number" && Number.isFinite(version) ? version : null;
}

/**
 * The `If-Match` header a save of `record` sends: the version it was read at.
 *
 * A record with no version — one the API never returned, so there is nothing
 * it could have been read at — sends no header, and an optimistic table then
 * answers 428 rather than letting the save overwrite blind.
 */
export function ifMatch(record: Record<string, unknown> | null | undefined): Record<string, string> {
  const version = versionOf(record);
  return version === null ? {} : { "If-Match": `"v${version}"` };
}

/** `Closed Won` — or `Closed Won (final)` — for a status line. */
export function describeStatus(status: TransactionStatus | null | undefined): string | null {
  if (!status || status.value === null) return null;
  const label = status.label ?? status.value;
  return status.isFinal ? `${label} (final)` : label;
}

/** The transaction status a save's response carries, if its table has a lifecycle. */
export function transactionStatusOf(response: unknown): TransactionStatus | null {
  if (typeof response !== "object" || response === null) return null;
  const status = (response as { transactionStatus?: unknown }).transactionStatus;
  if (typeof status !== "object" || status === null) return null;
  const candidate = status as Partial<TransactionStatus>;
  return typeof candidate.field === "string" && typeof candidate.isFinal === "boolean"
    ? (candidate as TransactionStatus)
    : null;
}

/** Keys a response carries that are not columns, and so are never saved back. */
export const RESPONSE_ONLY_KEYS = ["promotion", "transactionStatus"] as const;

/** `record` without the response-only keys. */
export function withoutResponseKeys(record: Record<string, unknown>): Record<string, unknown> {
  const copy = { ...record };
  for (const key of RESPONSE_ONLY_KEYS) delete copy[key];
  return copy;
}

/**
 * CSV export for the list grids.
 *
 * Every grid in the application offers its list as a CSV download. The rows are
 * fetched from the API rather than taken off the screen, so the file holds the
 * list the reader is looking at rather than the page of it they happen to be
 * on — capped at CSV_EXPORT_LIMIT rows, because this is a convenience export
 * and not a data dump: a browser building the whole string in memory and a
 * server paging an unbounded table are both worth avoiding.
 */

/**
 * The most rows any one export contains.
 *
 * The same number the grid's lookup queries already use as their ceiling, which
 * is not a coincidence: labels for referenced records are resolved from those
 * queries, so an export longer than they are would print raw uuids past the
 * cut.
 */
export const CSV_EXPORT_LIMIT = 500;

/**
 * One field, quoted the way RFC 4180 asks.
 *
 * Quotes are doubled and the field is wrapped whenever it holds a comma, a
 * quote, a line break or leading/trailing space — an unwrapped field with a
 * newline in it silently becomes two rows, which is the failure that makes an
 * export look fine and import wrong.
 */
function escapeField(value: string): string {
  const needsQuotes = /[",\r\n]/.test(value) || value !== value.trim();
  if (!needsQuotes) return value;
  return `"${value.replace(/"/g, '""')}"`;
}

/**
 * Defuse a field a spreadsheet would treat as a formula.
 *
 * Excel, LibreOffice and Sheets all evaluate a cell that opens with `=`, `+`,
 * `-`, `@` or a control character, so a record whose name a user typed as
 * `=HYPERLINK(...)` executes on open. The value is data, so it is prefixed with
 * an apostrophe — the convention those applications read back as "this is
 * text". Numbers are left alone: a leading `-` on something that parses as a
 * number is a minus sign, not an injection.
 */
function defuseFormula(value: string): string {
  if (value === "") return value;
  if (!/^[=+\-@\t\r]/.test(value)) return value;
  if (/^-?\d+(\.\d+)?$/.test(value)) return value;
  return `'${value}`;
}

/** A CSV document: one header row, then the rows, CRLF-separated per RFC 4180. */
export function toCsv(headers: string[], rows: string[][]): string {
  const lines = [headers, ...rows].map((cells) =>
    cells.map((cell) => escapeField(defuseFormula(cell ?? ""))).join(",")
  );
  return lines.join("\r\n");
}

/**
 * Hand the CSV to the browser as a download.
 *
 * The byte order mark is what makes Excel read the file as UTF-8; without it
 * every non-ASCII name in the export arrives mojibaked, which for an
 * application generated from a model in any language is most of them.
 */
export function downloadCsv(fileName: string, csv: string): void {
  const blob = new Blob([`﻿${csv}`], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName.endsWith(".csv") ? fileName : `${fileName}.csv`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

/** `bus_class_session` on 2026-09-04 → `class-session-2026-09-04.csv`. */
export function csvFileName(tableName: string): string {
  const stem = tableName
    .replace(/^bus_/, "")
    .replace(/[^a-zA-Z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .toLowerCase();
  const today = new Date().toISOString().slice(0, 10);
  return `${stem || "export"}-${today}.csv`;
}

/**
 * ElectricSQL + PGlite — local-first sync for sys_ (Application Dictionary) tables.
 *
 * sys_ rows are scoped to the authenticated user's role: each Electric shape
 * subscription forwards a `role` query param so the Electric proxy can apply
 * server-side filtering before sending rows to the client. Only the rows that
 * belong to the current role are loaded into the local PGlite instance and
 * subsequently into TanStack DB Collections — nothing else is synced
 * client-side.
 *
 * **PGlite is imported dynamically, and that is load-bearing.** It is a
 * PostgreSQL compiled to WebAssembly, and a static import put it in the shared
 * entry chunk — 972KB raw, 229KB over the wire, on every page of every
 * generated application. `VITE_ELECTRIC_URL` is empty unless someone sets it,
 * so in a default deployment `ELECTRIC_ENABLED` is false, `getDb` is never
 * called, and all of that was downloaded to run nothing. The import now lives
 * inside `getDb`, which is reached only after that flag has been checked, so
 * an application with sync configured pays for PGlite when it first syncs and
 * one without never pays at all.
 *
 * Keep the module-scope imports type-only. A value imported from
 * `@electric-sql/pglite` at the top of this file puts the whole package back
 * on the critical path, and nothing in the bundle output says so — the entry
 * chunk simply grows.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import type { PGlite } from '@electric-sql/pglite';

export const ELECTRIC_URL: string =
  import.meta.env.VITE_ELECTRIC_URL || '';

/** When ELECTRIC_URL is not set, sync is disabled and hooks use HTTP fallback. */
export const ELECTRIC_ENABLED = !!ELECTRIC_URL;

let _db: PGlite | null = null;
let _initPromise: Promise<PGlite> | null = null;

/** DDL for the local PGlite schema — mirrors the server-side sys_ tables. */
const SYS_DDL = `
  CREATE TABLE IF NOT EXISTS sys_table (
    sys_table_id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    table_name TEXT NOT NULL,
    description TEXT,
    is_active BOOLEAN DEFAULT TRUE
  );
  CREATE TABLE IF NOT EXISTS sys_column (
    sys_column_id TEXT PRIMARY KEY,
    sys_table_id TEXT NOT NULL,
    column_name TEXT NOT NULL,
    name TEXT NOT NULL,
    sys_reference_id INTEGER,
    is_key BOOLEAN DEFAULT FALSE,
    is_mandatory BOOLEAN DEFAULT FALSE,
    seq_no INTEGER DEFAULT 0
  );
  CREATE TABLE IF NOT EXISTS sys_field (
    sys_field_id TEXT PRIMARY KEY,
    sys_column_id TEXT NOT NULL,
    name TEXT NOT NULL,
    seq_no INTEGER DEFAULT 0,
    seq_no_grid INTEGER DEFAULT 0,
    is_displayed BOOLEAN DEFAULT TRUE,
    is_displayed_grid BOOLEAN DEFAULT TRUE,
    is_read_only BOOLEAN DEFAULT FALSE,
    is_mandatory BOOLEAN DEFAULT FALSE
  );
  CREATE TABLE IF NOT EXISTS sys_reference (
    sys_reference_id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT
  );
  CREATE TABLE IF NOT EXISTS sys_window (
    sys_window_id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT,
    sys_table_id TEXT
  );
`;

export async function getDb(): Promise<PGlite> {
  if (_db) return _db;
  if (_initPromise) return _initPromise;

  _initPromise = (async () => {
    // Loaded here rather than at module scope: see the note at the top of this
    // file. Both packages are fetched in parallel, once, and only by a caller
    // that has already established sync is configured.
    const [{ PGlite }, { electricSync }] = await Promise.all([
      import('@electric-sql/pglite'),
      import('@electric-sql/pglite-sync'),
    ]);
    const db = await PGlite.create({ extensions: { electric: electricSync() } });
    await db.exec(SYS_DDL);
    _db = db;
    return db;
  })();

  return _initPromise;
}

export interface SyncConfig {
  /** User role — forwarded to the Electric proxy to filter sys_ rows per role. */
  role: string;
  /** Session token forwarded as a header for proxy-level auth. */
  token?: string;
}

export type UnsubscribeFn = () => void;

/**
 * Subscribe to Electric shapes for all sys_ tables, scoped to the given role.
 *
 * The `role` param is forwarded to the NestJS Electric proxy (`/v1/shape`) which
 * applies a WHERE clause so only the rows visible to that role are streamed.
 * This is the only place where sys_ data enters the client — everything else
 * reads from TanStack DB Collections that are populated from PGlite.
 */
export async function syncSysTablesForRole(config: SyncConfig): Promise<UnsubscribeFn> {
  if (!ELECTRIC_ENABLED) {
    return () => {};
  }

  const db = await getDb();
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const ext = (db as any).electric as { syncShapeToTable: (opts: any) => Promise<any> };

  const commonParams = { role: config.role };
  const authHeaders = config.token ? { Authorization: `Bearer ${config.token}` } : {};

  type ShapeSpec = { table: string; primaryKey: string[] };

  const specs: ShapeSpec[] = [
    { table: 'sys_table',     primaryKey: ['sys_table_id'] },
    { table: 'sys_column',    primaryKey: ['sys_column_id'] },
    { table: 'sys_field',     primaryKey: ['sys_field_id'] },
    { table: 'sys_reference', primaryKey: ['sys_reference_id'] },
    { table: 'sys_window',    primaryKey: ['sys_window_id'] },
  ];

  const subscriptions = await Promise.all(
    specs.map(({ table, primaryKey }) =>
      ext.syncShapeToTable({
        shape: {
          url: ELECTRIC_URL,
          params: { table, ...commonParams },
          headers: authHeaders,
        },
        table,
        primaryKey,
      })
    )
  );

  return () => {
    for (const sub of subscriptions) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (sub as any).unsubscribe?.();
    }
  };
}

/**
 * The application inside a conversation.
 *
 * The chat (`chat/`, generated beside this front end) opens this application's
 * own screens in a frame, so the person creates, edits and moves records here —
 * under this application's validation, rules, permissions and optimistic
 * locking — and never through the assistant. Three things make that work, and
 * all three live in this file so there is one statement of the contract:
 *
 * - **`?embed=1` drops the chrome.** The frame is a card in a scrolling
 *   conversation; a sidebar and header inside it would be a second application
 *   nested in the first. The flag is remembered for the frame's session, so a
 *   save that navigates from `/new` to the record it created stays chromeless.
 * - **`?edit=1` and `?transition=<state>` say what the screen was opened for.**
 *   An update form opens in edit mode; an approval opens with the move the
 *   assistant proposed marked — the person still presses it.
 * - **Every accepted write is reported to the frame's parent** as a
 *   `record-saved` message, posted to this application's own origin only. The
 *   chat validates the source, the origin and the shape, reads the record back
 *   through its own session, and only then tells the assistant — so the
 *   assistant's "saved" is the server's, never the frame's.
 *
 * Outside a frame none of this changes anything: `isEmbedded()` is false and
 * `notifySaved` posts nothing.
 */
import type { TransactionStatus } from "@/lib/concurrency";

const STORAGE_KEY = "appwithai.embed";

/** The message the chat listens for. Versioned: the chat refuses any other `v`. */
export interface RecordSavedMessage {
  source: "appwithai-app";
  v: 1;
  type: "record-saved";
  operation: "create" | "update" | "transition" | "delete";
  id: string;
  version: number | null;
  transactionStatus: TransactionStatus | null;
}

function searchParams(): URLSearchParams | null {
  return typeof window === "undefined" ? null : new URLSearchParams(window.location.search);
}

function framed(): boolean {
  if (typeof window === "undefined") return false;
  try {
    return window.parent !== window;
  } catch {
    // A cross-origin parent throws on access: still a frame, and not ours to
    // report to, which `notifySaved` handles by posting to our own origin only.
    return true;
  }
}

/** True when this page is the chat's embedded view of a screen. */
export function isEmbedded(): boolean {
  if (!framed()) return false;
  const params = searchParams();
  try {
    if (params?.get("embed") === "1") {
      window.sessionStorage.setItem(STORAGE_KEY, "1");
      return true;
    }
    return window.sessionStorage.getItem(STORAGE_KEY) === "1";
  } catch {
    // Storage refused (a sandboxed frame without it): the URL alone decides.
    return params?.get("embed") === "1";
  }
}

/** What the screen was opened for: edit mode, and a proposed workflow move. */
export function embedIntent(): { edit: boolean; transition: string | null } {
  const params = searchParams();
  if (!params || !isEmbedded()) return { edit: false, transition: null };
  const transition = params.get("transition");
  return {
    edit: params.get("edit") === "1",
    transition: transition && /^[A-Za-z0-9_.-]{1,64}$/.test(transition) ? transition : null,
  };
}

/**
 * Tell the conversation a write was accepted.
 *
 * Posted with this application's own origin as the target, so a frame that is
 * not the chat — anything else that framed this page — receives nothing.
 */
export function notifySaved(
  operation: RecordSavedMessage["operation"],
  record: Record<string, unknown> | null,
  id: string
): void {
  if (!isEmbedded()) return;
  const version = record && typeof record.version === "number" ? record.version : null;
  const status = record?.transactionStatus;
  const message: RecordSavedMessage = {
    source: "appwithai-app",
    v: 1,
    type: "record-saved",
    operation,
    id,
    version,
    transactionStatus:
      status && typeof status === "object" ? (status as TransactionStatus) : null,
  };
  try {
    window.parent.postMessage(message, window.location.origin);
  } catch {
    // A parent on another origin rejects the post; nothing to report to.
  }
}

import { z, type ZodTypeAny } from 'zod';
import type { FieldMetadata } from '@/hooks/use-entities';

const REFERENCE_TYPE = {
  STRING: 10,
  INTEGER: 11,
  AMOUNT: 12,
  ID: 13,
  TEXT: 14,
  DATE: 15,
  DATETIME: 16,
  LIST: 17,
  TABLE: 18,
  TABLE_DIRECT: 19,
  YES_NO: 20,
  URL: 24,
  EMAIL: 30,
  PHONE: 31,
  PASSWORD: 29,
} as const;

function buildFieldValidator(field: FieldMetadata, mode: 'create' | 'edit'): ZodTypeAny {
  const label = field.name;
  let schema: ZodTypeAny;

  switch (field.sys_reference_id) {
    case REFERENCE_TYPE.YES_NO:
      // An untouched checkbox means "no". It does not mean "unanswered".
      //
      // Without this, a mandatory Yes/No column that the user simply left
      // alone arrived as `undefined`, failed `z.boolean()`, and blocked the
      // create with a bare "Invalid input" — on a checkbox, which renders no
      // error text, so the form reported a validation error the user could not
      // see and had no way to clear. Any entity with a mandatory boolean was
      // uncreatable through the UI. Normalising absence to `false` here fixes
      // it for every caller of the schema at once, rather than in whichever
      // submit path happens to remember to do it.
      schema = z.preprocess(
        (val) => (val === undefined || val === null || val === '' ? false : val),
        z.boolean({ invalid_type_error: `${label} must be Yes or No` })
      );
      break;

    case REFERENCE_TYPE.INTEGER:
      schema = z.coerce.number({ invalid_type_error: `${label} must be a number` })
        .int({ message: `${label} must be a whole number` })
        .or(z.literal(''))
        .or(z.null());
      break;

    case REFERENCE_TYPE.AMOUNT:
      schema = z.coerce.number({ invalid_type_error: `${label} must be a number` })
        .or(z.literal(''))
        .or(z.null());
      break;

    case REFERENCE_TYPE.EMAIL: {
      let s = z.string().email({ message: `${label} must be a valid email` });
      if (field.field_length) s = s.max(field.field_length, { message: `${label} max ${field.field_length} chars` });
      schema = s.or(z.literal(''));
      break;
    }

    case REFERENCE_TYPE.URL: {
      let s = z.string().url({ message: `${label} must be a valid URL` });
      if (field.field_length) s = s.max(field.field_length, { message: `${label} max ${field.field_length} chars` });
      schema = s.or(z.literal(''));
      break;
    }

    case REFERENCE_TYPE.PHONE: {
      let s = z.string().regex(/^[+\d\s\-().]*$/, { message: `${label} must be a valid phone number` });
      if (field.field_length) s = s.max(field.field_length, { message: `${label} max ${field.field_length} chars` });
      schema = s.or(z.literal(''));
      break;
    }

    case REFERENCE_TYPE.DATE:
    case REFERENCE_TYPE.DATETIME:
      schema = z.string().or(z.literal('')).or(z.null());
      break;

    case REFERENCE_TYPE.PASSWORD: {
      let s = z.string().min(6, { message: `${label} must be at least 6 characters` });
      if (field.field_length) s = s.max(field.field_length, { message: `${label} max ${field.field_length} chars` });
      schema = s.or(z.literal(''));
      break;
    }

    default: {
      let s = z.string();
      if (field.field_length) s = s.max(field.field_length, { message: `${label} max ${field.field_length} chars` });
      schema = s.or(z.literal('')).or(z.null()).or(z.number());
      break;
    }
  }

  if (field.is_mandatory && !(field.is_read_only && mode === 'edit')) {
    schema = schema.refine(
      (val) => val !== undefined && val !== null && val !== '',
      { message: `${label} is required` }
    );
  } else {
    schema = schema.optional();
  }

  return schema;
}

export function buildFormSchema(
  fields: FieldMetadata[],
  mode: 'create' | 'edit' = 'create'
): z.ZodObject<Record<string, ZodTypeAny>> {
  const shape: Record<string, ZodTypeAny> = {};

  for (const field of fields) {
    if (!field.is_displayed) continue;
    shape[field.column_name] = buildFieldValidator(field, mode);
  }

  return z.object(shape).passthrough();
}

export function validateFormData(
  fields: FieldMetadata[],
  data: Record<string, unknown>,
  mode: 'create' | 'edit' = 'create'
): { success: boolean; errors: Record<string, string> } {
  const schema = buildFormSchema(fields, mode);
  const result = schema.safeParse(data);

  if (result.success) {
    return { success: true, errors: {} };
  }

  const errors: Record<string, string> = {};
  for (const issue of result.error.issues) {
    const path = issue.path[0];
    if (path && typeof path === 'string') {
      errors[path] = issue.message;
    }
  }
  return { success: false, errors };
}

