/**
 * i18n Field Label Utilities
 *
 * Generates i18n keys for field labels in the format:
 * <entity>_<tab>_<field>
 *
 * Example: patient_identification_first_name -> "First Name"
 *
 * Auto-generated file
 */

import { translate } from "./translations";

/**
 * Convert a string to snake_case for i18n keys
 */
function toSnakeCase(str: string): string {
  return str
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

/**
 * Generate i18n key for a field label
 * @param tableName - Table name (e.g., "bus_patient" -> "patient")
 * @param tabName - Tab name (e.g., "Identification" -> "identification")
 * @param fieldName - Field name (e.g., "First Name" -> "first_name")
 * @returns i18n key (e.g., "patient_identification_first_name")
 */
export function generateFieldI18nKey(
  tableName: string,
  tabName: string,
  fieldName: string
): string {
  // Remove 'bus_' prefix from table name
  const entity = tableName.replace(/^bus_/, "");
  const entityKey = toSnakeCase(entity);
  const tabKey = toSnakeCase(tabName);
  const fieldKey = toSnakeCase(fieldName);

  return `${entityKey}_${tabKey}_${fieldKey}`;
}

/**
 * Get field label from i18n
 * @param tableName - Table name
 * @param tabName - Tab name (optional, for more specific keys)
 * @param fieldName - Field name
 * @param fallback - Fallback label if translation not found
 * @returns Translated field label
 */
export function getFieldLabel(
  tableName: string,
  tabName: string | undefined,
  fieldName: string,
  fallback?: string
): string {
  // Try with tab first (most specific)
  if (tabName) {
    const keyWithTab = `fields.${generateFieldI18nKey(tableName, tabName, fieldName)}`;
    const translatedWithTab = translate(keyWithTab);

    if (translatedWithTab !== keyWithTab) {
      return translatedWithTab;
    }
  }

  // Fallback to entity_field format (less specific)
  const entity = tableName.replace(/^bus_/, "");
  const entityKey = toSnakeCase(entity);
  const fieldKey = toSnakeCase(fieldName);
  const simpleKey = `fields.${entityKey}_${fieldKey}`;

  const translatedSimple = translate(simpleKey);
  if (translatedSimple !== simpleKey) {
    return translatedSimple;
  }

  // Final fallback
  return fallback || fieldName;
}

/**
 * Get entity display name from i18n
 * @param tableName - Table name (e.g., "bus_patient")
 * @returns Translated entity name
 */
export function getEntityLabel(tableName: string): string {
  const entity = tableName.replace(/^bus_/, "");
  const key = `entities.${toSnakeCase(entity)}`;
  const translated = translate(key);

  // If translation not found, return formatted entity name
  if (translated === key) {
    return entity
      .split("_")
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join(" ");
  }

  return translated;
}

/**
 * Get tab display name from i18n
 * @param tableName - Table name
 * @param tabName - Tab name
 * @returns Translated tab name
 */
export function getTabLabel(tableName: string, tabName: string): string {
  const entity = tableName.replace(/^bus_/, "");
  const key = `tabs.${toSnakeCase(entity)}.${toSnakeCase(tabName)}`;
  const translated = translate(key);

  // If translation not found, return tab name as-is
  if (translated === key) {
    return tabName;
  }

  return translated;
}

/**
 * Authentication Query Hooks
 *
 * TanStack Query hooks for authentication operations.
 *
 */

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { type ApiError, apiClient } from "@/lib/api-client";

// ============================================================================
// Types
// ============================================================================

export interface LoginCredentials {
  email: string;
  password: string;
}

export interface RegisterData {
  name: string;
  email: string;
  password: string;
}

export interface AuthResponse {
  access_token: string;
  user: {
    sys_user_id: string;
    email: string;
    name: string;
    roles: Array<{
      sys_role_id: string;
      name: string;
    }>;
  };
}

export interface UserProfile {
  sys_user_id: string;
  name: string;
  email: string;
  description?: string;
  is_active: boolean;
  is_locked: boolean;
  last_login?: string;
  created_at: string;
  updated_at: string;
}

// ============================================================================
// Query Keys
// ============================================================================

export const authKeys = {
  all: ["auth"] as const,
  profile: () => [...authKeys.all, "profile"] as const,
};

// ============================================================================
// Login Mutation
// ============================================================================

export function useLogin() {
  const queryClient = useQueryClient();

  return useMutation<AuthResponse, ApiError, LoginCredentials>({
    mutationFn: (credentials) => apiClient.post<AuthResponse>("/auth/login", credentials),
    onSuccess: (data) => {
      // Store token
      localStorage.setItem("auth_token", data.access_token);
      localStorage.setItem("auth_user", JSON.stringify(data.user));

      // Update API client
      apiClient.setAuthToken(data.access_token);

      // Invalidate queries
      queryClient.invalidateQueries({ queryKey: authKeys.all });
    },
  });
}

// ============================================================================
// Register Mutation
// ============================================================================

export function useRegister() {
  return useMutation<AuthResponse, ApiError, RegisterData>({
    mutationFn: (data) => apiClient.post<AuthResponse>("/auth/register", data),
    onSuccess: (data) => {
      // Store token
      localStorage.setItem("auth_token", data.access_token);
      localStorage.setItem("auth_user", JSON.stringify(data.user));

      // Update API client
      apiClient.setAuthToken(data.access_token);
    },
  });
}

// ============================================================================
// Get Current User Query
// ============================================================================

export function useCurrentUser() {
  return useQuery<UserProfile, ApiError>({
    queryKey: authKeys.profile(),
    // 401 here means "nobody is signed in", which is a legitimate answer on
    // every public page — not a failure worth a console error.
    queryFn: () => apiClient.get<UserProfile>("/auth/me", undefined, { expectUnauthorized: true }),
    retry: false,
  });
}

// ============================================================================
// Logout Mutation
// ============================================================================

export function useLogout() {
  const queryClient = useQueryClient();

  return useMutation<void, ApiError>({
    mutationFn: () => apiClient.post<void>("/auth/logout"),
    onSuccess: () => {
      // Clear storage
      localStorage.removeItem("auth_token");
      localStorage.removeItem("auth_user");

      // Update API client
      apiClient.setAuthToken(null);

      // Clear all queries
      queryClient.clear();
    },
  });
}

// ============================================================================
// Change Password Mutation
// ============================================================================

export function useChangePassword() {
  return useMutation<{ message: string }, ApiError, { old_password: string; new_password: string }>(
    {
      mutationFn: (data) => apiClient.post<{ message: string }>("/auth/change-password", data),
    }
  );
}

/**
 * In-memory cache for sys_ (Application Dictionary) entities.
 *
 * Data is populated from the local PGlite database after ElectricSQL sync
 * completes. Components read from this cache via `getSysCache()` — reads are
 * instant because they skip the network entirely.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import type { FieldMetadata, ColumnMetadata, SysTable, SysReference } from '@/hooks/use-field-metadata';
import { getDb } from './electric';

/* -------------------------------------------------------------------------- */
/*  Cache state                                                                */
/* -------------------------------------------------------------------------- */

export interface SysCache {
  tables: SysTable[];
  columns: ColumnMetadata[];
  fields: FieldMetadata[];
  references: SysReference[];
  loaded: boolean;
}

let _cache: SysCache = { tables: [], columns: [], fields: [], references: [], loaded: false };
const _listeners = new Set<() => void>();

/* -------------------------------------------------------------------------- */
/*  Public API                                                                 */
/* -------------------------------------------------------------------------- */

/** Subscribe to cache invalidations. Returns an unsubscribe function. */
export function subscribeSysCache(fn: () => void): () => void {
  _listeners.add(fn);
  return () => _listeners.delete(fn);
}

/** Read the current cache snapshot (synchronous, zero-cost). */
export function getSysCache(): SysCache {
  return _cache;
}

/**
 * Reload all sys_ collections from PGlite.
 * Called by ElectricProvider after each sync batch completes.
 */
export async function reloadSysCollections(): Promise<void> {
  const db = await getDb();

  const [tables, columns, fields, references] = await Promise.all([
    db.query<SysTable>('SELECT * FROM sys_table WHERE is_active = TRUE ORDER BY name'),
    db.query<ColumnMetadata>('SELECT * FROM sys_column ORDER BY seq_no'),
    db.query<FieldMetadata>('SELECT * FROM sys_field ORDER BY seq_no'),
    db.query<SysReference>('SELECT * FROM sys_reference ORDER BY name'),
  ]);

  _cache = {
    tables: tables.rows,
    columns: columns.rows,
    fields: fields.rows,
    references: references.rows,
    loaded: true,
  };

  for (const fn of _listeners) {
    fn();
  }
}

