}

/**
 * Render the display label for a referenced record.
 *
 * The Application Dictionary describes a record's label as `ref_label_fields` —
 * a list, because an entity can be identified by more than one column. Name
 * parts are one label and have to read as a name ("James Smith"), while
 * genuinely distinct facts are separated ("ACME-01 · Acme Corporation").
 *
 * Falls back to a person's first/last name, then to the raw id, so a lookup
 * never renders blank.
 */
export function referenceLabel(
  record: Record<string, unknown>,
  labelFields: string[],
  id: string
): string {
  const parts = labelFields
    .map((f) => record[f])
    .filter((v) => v != null && v !== "")
    .map(String);

  if (parts.length) {
    const separator = labelFields.every((f) => /(^|_)name$/.test(f)) ? " " : " · ";
    return parts.join(separator);
  }

  const fullName = [record.first_name, record.last_name].filter(Boolean).map(String).join(" ");
  return fullName || id;
}

/**
 * Reading and writing the workflow model that lives inside BPMN.
 *
 * bpmn-js owns the diagram; this owns what the diagram *means*. Every
 * executable step is a `bpmn:serviceTask` whose behaviour is carried by
 * `appwithai:property` extension elements, and the executor runs them in
 * sequence-flow order. These functions read that back out — in the same order
 * the executor will use — so the editor can show a workflow's variable wiring
 * without guessing.
 *
 * Kept free of React and of bpmn-js so both applications can share it and so
 * the analysis can be tested without a browser.
 */

/**
 * Step types come from `./step-types`, which is generated out of the EML
 * language definition the backend's executor is written against. Listing them
 * again here would be a second vocabulary to keep in step, and the designer's
 * palette had already drifted that way once — offering a step the executor
 * refuses and missing one it had gained.
 *
 * The labels and hints below are this editor's own wording and stay here: a
 * palette needs "Create" and one line of guidance, which is a different job
 * from the language's `purpose`.
 */
export { STEP_TYPES, type StepType } from "./step-types";
import type { StepType } from "./step-types";

export const STEP_LABELS: Partial<Record<StepType, string>> = {
  Decision: "Decision",
  CreateEntity: "Create",
  UpdateEntity: "Update",
  DeleteEntity: "Delete",
  Formula: "Formula",
  REST: "REST call",
};

export const STEP_HINTS: Partial<Record<StepType, string>> = {
  Decision: "Run a decision table and publish what it decides.",
  CreateEntity: "Insert a row, and remember its id for later steps.",
  UpdateEntity: "Write one column, on this record or a related one.",
  DeleteEntity: "Delete a record. Soft by default, so the audit trail resolves.",
  Formula: "Work out a value, or stage a literal, for a later step.",
