/**
 * Astryx theme + link plumbing, with runtime theme switching.
 *
 * All seven published Astryx themes ship in the generated app and any of them
 * can be selected at runtime. That works because each theme's stylesheet is
 * `@scope`-d to `[data-astryx-theme="<name>"]`, so the seven can coexist
 * without fighting; `<Theme>` sets that attribute, and swapping the theme
 * object is the whole switch. No rebuild, no reload.
 *
 * `LinkProvider` is how Astryx components render router-aware links — without
 * it, anything Astryx renders as an anchor triggers a full page load instead of
 * a client-side navigation.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import { Theme } from '@astryxdesign/core/theme';
import { LinkProvider } from '@astryxdesign/core/Link';
import { Link } from '@tanstack/react-router';

import { butterTheme } from '@astryxdesign/theme-butter/built';
import { chocolateTheme } from '@astryxdesign/theme-chocolate/built';
import { gothicTheme } from '@astryxdesign/theme-gothic/built';
import { matchaTheme } from '@astryxdesign/theme-matcha/built';
import { neutralTheme } from '@astryxdesign/theme-neutral/built';
import { stoneTheme } from '@astryxdesign/theme-stone/built';
import { y2kTheme } from '@astryxdesign/theme-y2k/built';

/** The seven themes Astryx actually publishes. */
export const THEMES = {
  neutral: { label: 'Neutral', theme: neutralTheme },
  butter: { label: 'Butter', theme: butterTheme },
  chocolate: { label: 'Chocolate', theme: chocolateTheme },
  matcha: { label: 'Matcha', theme: matchaTheme },
  stone: { label: 'Stone', theme: stoneTheme },
  gothic: { label: 'Gothic', theme: gothicTheme },
  y2k: { label: 'Y2K', theme: y2kTheme },
} as const;

export type ThemeName = keyof typeof THEMES;

export const THEME_NAMES = Object.keys(THEMES) as ThemeName[];

/** The theme this project was generated with; the starting point until a user chooses. */
export const DEFAULT_THEME: ThemeName = '{{astryxThemeName}}';

const STORAGE_KEY = '{{projectKebab}}:astryx-theme';

interface ThemeContextValue {
  theme: ThemeName;
  setTheme: (name: ThemeName) => void;
  themes: typeof THEMES;
}

const ThemeContext = createContext<ThemeContextValue | null>(null);

/** Read the persisted choice. Any unknown value falls back to the default. */
function readStoredTheme(): ThemeName {
  if (typeof window === 'undefined') return DEFAULT_THEME;
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    return stored && stored in THEMES ? (stored as ThemeName) : DEFAULT_THEME;
  } catch {
    // Private browsing and some kiosk configurations throw on localStorage.
    return DEFAULT_THEME;
  }
}

export function AstryxProvider({ children }: { children: ReactNode }) {
  // Deliberately NOT seeded from localStorage: this component renders on the
  // server too, and starting from a stored value would make the first client
  // render disagree with the server HTML. The stored choice is applied in the
  // effect below, after hydration.
  const [theme, setThemeState] = useState<ThemeName>(DEFAULT_THEME);

  useEffect(() => {
    setThemeState(readStoredTheme());
  }, []);

  const setTheme = useCallback((name: ThemeName) => {
    setThemeState(name);
    try {
      window.localStorage.setItem(STORAGE_KEY, name);
    } catch {
      // Not being able to persist is not a reason to refuse the switch.
    }
  }, []);

  const value = useMemo(() => ({ theme, setTheme, themes: THEMES }), [theme, setTheme]);

  return (
    <ThemeContext.Provider value={value}>
      <Theme theme={THEMES[theme].theme}>
        <LinkProvider component={Link}>{children}</LinkProvider>
      </Theme>
    </ThemeContext.Provider>
  );
}

/** Read and change the active theme. Throws outside the provider, which is a bug. */
export function useAstryxTheme(): ThemeContextValue {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useAstryxTheme must be used inside <AstryxProvider>');
  }
  return context;
}

"use client";

/**
 * ElectricSQL Provider
 *
 * Initialises PGlite + ElectricSQL sync for sys_ (Application Dictionary) tables.
 * Only rows visible to the authenticated user's role are synced to the local
 * PGlite database and loaded into TanStack DB Collections — nothing else is
 * pulled client-side.
 *
 * The `role` prop must match a role string known to the backend Electric proxy
 * so the server-side WHERE clause is applied before rows leave the server.
 */

import type { PGlite } from "@electric-sql/pglite";
import React, {
  createContext,
  type ReactNode,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import {
  ELECTRIC_ENABLED,
  getDb,
  type SyncConfig,
  syncSysTablesForRole,
  type UnsubscribeFn,
} from "@/lib/electric";
import { reloadSysCollections } from "@/lib/sys-collections";

/* -------------------------------------------------------------------------- */
/*  Context                                                                    */
/* -------------------------------------------------------------------------- */

interface ElectricContextValue {
  db: PGlite | null;
  isSyncing: boolean;
  isSynced: boolean;
  error: Error | null;
  /** False when VITE_ELECTRIC_URL is unset — hooks read over HTTP instead. */
  isEnabled: boolean;
}

const ElectricContext = createContext<ElectricContextValue>({
  db: null,
  isSyncing: false,
  isSynced: false,
  error: null,
  isEnabled: false,
});

export function useElectric(): ElectricContextValue {
  return useContext(ElectricContext);
}

/* -------------------------------------------------------------------------- */
/*  Provider                                                                   */
/* -------------------------------------------------------------------------- */

export interface ElectricProviderProps {
  children: ReactNode;
  /** Role of the authenticated user — scopes the Electric shape subscription. */
  role: string;
  /** Session token forwarded to the Electric proxy for auth. */
  token?: string;
}

export function ElectricProvider({ children, role, token }: ElectricProviderProps) {
  const [db, setDb] = useState<PGlite | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSynced, setIsSynced] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const unsubRef = useRef<UnsubscribeFn | null>(null);

  useEffect(() => {
    // Without an Electric endpoint there is nothing to sync, and booting PGlite
    // would download a WASM runtime only to leave it empty. Staying idle here is
    // the supported configuration, not a failure: the sys_ hooks fall back to
    // fetching the Application Dictionary over HTTP.
    if (!ELECTRIC_ENABLED || !role) return;

    let cancelled = false;

    async function init() {
      try {
        setIsSyncing(true);
        setIsSynced(false);
        setError(null);

        const database = await getDb();
        if (cancelled) return;
        setDb(database);

        const config: SyncConfig = { role, token };
        const unsub = await syncSysTablesForRole(config);
        if (cancelled) {
          unsub();
          return;
        }
        unsubRef.current = unsub;

        await reloadSysCollections();
        if (cancelled) return;

        setIsSynced(true);
      } catch (err) {
        if (!cancelled) {
          // Sync is an optimisation. Record the failure for anything that wants
          // to surface it, warn rather than error, and let the HTTP fallback
          // carry the app — a broken sync must not break the UI.
          const failure = err instanceof Error ? err : new Error(String(err));
          console.warn(
            "[ElectricProvider] sync unavailable, falling back to HTTP:",
            failure.message
          );
          setError(failure);
          setDb(null);
        }
      } finally {
        if (!cancelled) setIsSyncing(false);
      }
    }

    void init();

    return () => {
      cancelled = true;
      unsubRef.current?.();
      unsubRef.current = null;
      setIsSynced(false);
    };
  }, [role, token]);

  return (
    <ElectricContext.Provider
      value={{ db, isSyncing, isSynced, error, isEnabled: ELECTRIC_ENABLED }}
    >
      {children}
    </ElectricContext.Provider>
  );
}

