    }
  }, [form.name, codeTouched, editing]);

  function openCreate() {
    setEditing(null);
    setForm(EMPTY_FORM);
    setCodeTouched(false);
    setFormError(null);
    setShowForm(true);
  }

  function openEdit(category: Category) {
    setEditing(category);
    setForm({
      name: category.name,
      code: category.code,
      description: category.description ?? '',
      icon: category.icon ?? '',
      color: category.color ?? '',
      seq_no: category.seq_no,
      is_default: category.is_default,
      is_active: category.is_active,
    });
    setCodeTouched(true);
    setFormError(null);
    setShowForm(true);
  }

  function closeForm() {
    setShowForm(false);
