import { useState } from 'react';
import { createFileRoute, Link } from '@tanstack/react-router';
import { useQuery } from '@tanstack/react-query';
import { apiClient } from '@/lib/api-client';
import { useEntityLabel } from '@/components/admin/use-dictionary-entities';
import {
  Workflow,
  RefreshCw,
  Search,
  CheckCircle,
  XCircle,
  Clock,
  AlertCircle,
  ChevronRight,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Box, Grid, HStack, Heading, Text } from "@/components/ui/layout";

export const Route = createFileRoute('/admin/workflows')({
  component: AdminWorkflowsPage,
});

interface WorkflowRun {
  id: string;
  trigger_run_id: string;
  entity_name: string;
  entity_id: string;
  operation: string;
  status: 'draft' | 'success' | 'error';
  input_payload?: any;
  output_payload?: any;
  error_details?: string;
  mutations_applied?: any;
  duration_ms?: number;
  created_at: string;
  completed_at?: string;
}

function AdminWorkflowsPage() {
  const entityLabel = useEntityLabel();
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [entityFilter, setEntityFilter] = useState<string>('');
  const [operationFilter, setOperationFilter] = useState<string>('');

  const { data: workflows, isLoading, refetch } = useQuery({
    queryKey: ['admin', 'workflows', { statusFilter, entityFilter, operationFilter }],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (statusFilter) params.append('status', statusFilter);
      if (entityFilter) params.append('entityName', entityFilter);
      if (operationFilter) params.append('operation', operationFilter);
      params.append('limit', '100');

      const response = await apiClient.get<WorkflowRun[]>(`/api/workflows/runs?${params.toString()}`);
      return response;
    },
    refetchInterval: 5000, // Refresh every 5 seconds
  });

  const filteredWorkflows = workflows?.filter((wf) => {
    const matchesSearch =
      searchQuery === '' ||
      wf.entity_name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      wf.entity_id.toLowerCase().includes(searchQuery.toLowerCase()) ||
      wf.trigger_run_id?.toLowerCase().includes(searchQuery.toLowerCase());

    return matchesSearch;
  }) || [];

  const entityNames = Array.from(new Set(workflows?.map((w) => w.entity_name) || []));
  const operations = Array.from(new Set(workflows?.map((w) => w.operation) || []));

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'success':
        return <CheckCircle className="h-4 w-4 text-emerald-600" />;
      case 'error':
        return <XCircle className="h-4 w-4 text-red-600" />;
      case 'draft':
        return <Clock className="h-4 w-4 text-blue-600" />;
      default:
        return <AlertCircle className="h-4 w-4 text-gray-400" />;
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'success':
        return 'bg-emerald-50 text-emerald-700 border-emerald-200';
      case 'error':
        return 'bg-red-50 text-red-700 border-red-200';
      case 'draft':
        return 'bg-blue-50 text-blue-700 border-blue-200';
      default:
        return 'bg-gray-50 text-gray-700 border-gray-200';
    }
  };

  const formatDuration = (ms?: number) => {
    if (!ms) return '-';
    if (ms < 1000) return `${Math.round(ms)}ms`;
    if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`;
    return `${(ms / 60000).toFixed(1)}m`;
  };

  return (
    <div className="min-h-screen bg-white">
      <header className="border-b-4 border-black bg-white">
        <div className="max-w-7xl mx-auto px-8 pt-6 pb-0">
          <nav aria-label="breadcrumb" className="flex items-center gap-1 text-sm text-gray-500 mb-4">
            <Link to="/dashboard" className="hover:text-gray-700 hover:underline">Dashboard</Link>
            <ChevronRight size={14} />
            <Text color="primary" weight="medium">Workflow Monitor</Text>
          </nav>
        </div>
        <div className="max-w-7xl mx-auto px-8 pb-12">
          <HStack align="start" justify="between">
            <div className="flex-1">
              <HStack align="center" gap={4} className="mb-4">
                <Workflow className="h-8 w-8 text-black" />
                <div>
                  <Heading level={1} color="primary" className="text-6xl tracking-tight">
                    Workflow Monitor
                  </Heading>
                  <Text size="xl" color="secondary" block className="font-light mt-2">
                    Real-time workflow execution and status tracking
                  </Text>
                </div>
              </HStack>
            </div>
            <Button
              variant="outline"
              size="default"
              onClick={() => refetch()}
              disabled={isLoading}
              className="border-2 border-black hover:bg-black hover:text-white transition-colors rounded-none"
            >
              <RefreshCw className={`h-4 w-4 mr-2 ${isLoading ? 'animate-spin' : ''}`} />
              Refresh
            </Button>
          </HStack>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-8 py-12">
        {/* Stats Cards */}
        <section className="mb-12">
          <Grid gap={0} className="grid-cols-5 border-l border-r border-black">
            <Box padding={6} bg="subtle" border="strong" borderSide="end">
              <Text size="sm" uppercase color="secondary" block className="tracking-widest mb-2">Total</Text>
              <Text weight="bold" color="primary" block className="text-4xl">{workflows?.length || 0}</Text>
            </Box>
            <Box padding={6} bg="subtle" border="strong" borderSide="end">
              <Text size="sm" uppercase color="secondary" block className="tracking-widest mb-2">Draft</Text>
              <Text weight="bold" block className="text-4xl text-blue-700">
                {workflows?.filter((w) => w.status === 'draft').length || 0}
              </Text>
            </Box>
            <Box padding={6} bg="subtle" border="strong" borderSide="end">
              <Text size="sm" uppercase color="secondary" block className="tracking-widest mb-2">Success</Text>
              <Text weight="bold" block className="text-4xl text-emerald-700">
                {workflows?.filter((w) => w.status === 'success').length || 0}
              </Text>
            </Box>
            <Box padding={6} bg="subtle" border="strong" borderSide="end">
              <Text size="sm" uppercase color="secondary" block className="tracking-widest mb-2">Error</Text>
              <Text weight="bold" block className="text-4xl text-red-700">
                {workflows?.filter((w) => w.status === 'error').length || 0}
              </Text>
            </Box>
            <Box padding={6} bg="subtle" border="strong" borderSide="bottom">
              <Text size="sm" uppercase color="secondary" block className="tracking-widest mb-2">Avg Duration</Text>
              <Text weight="bold" color="primary" block className="text-4xl">
                {formatDuration(
                  (workflows?.filter((w) => w.duration_ms).reduce((acc, w) => acc + (w.duration_ms || 0), 0) ?? 0) /
                    (workflows?.filter((w) => w.duration_ms).length || 1)
                )}
              </Text>
            </Box>
          </Grid>
        </section>

        {/* Search and Filter Bar */}
        <section className="mb-8">
          <HStack gap={4} className="mb-6">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
              <Input
                type="text"
                placeholder="Search by entity, ID, or run ID..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 border-2 border-black rounded-none focus:ring-0 focus:border-black"
              />
            </div>

            <select
              value={entityFilter}
              onChange={(e) => setEntityFilter(e.target.value)}
              className="px-4 py-2 border-2 border-black rounded-none focus:ring-0 focus:border-black bg-white"
            >
              <option value="">All Entities</option>
              {entityNames.map((entity) => (
                <option key={entity} value={entity}>
                  {entityLabel(entity)}
                </option>
              ))}
            </select>

            <select
              value={operationFilter}
              onChange={(e) => setOperationFilter(e.target.value)}
              className="px-4 py-2 border-2 border-black rounded-none focus:ring-0 focus:border-black bg-white"
            >
              <option value="">All Operations</option>
              {operations.map((op) => (
                <option key={op} value={op}>
                  {op}
                </option>
              ))}
            </select>

            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2 border-2 border-black rounded-none focus:ring-0 focus:border-black bg-white"
            >
              <option value="">All Status</option>
              <option value="draft">Draft</option>
              <option value="success">Success</option>
              <option value="error">Error</option>
            </select>
          </HStack>
        </section>

        {/* Workflows List */}
        {isLoading ? (
          <Box border="strong" className="text-center py-16 text-gray-500">
            Loading workflows...
          </Box>
        ) : filteredWorkflows.length === 0 ? (
          <Box border="strong" className="text-center py-16 text-gray-500">
            {searchQuery || statusFilter || entityFilter || operationFilter
              ? 'No workflows match your search criteria.'
              : 'No workflows found. Workflows will appear here after entity operations.'}
          </Box>
        ) : (
          <Box border="strong">
            <Grid columns={12} gap={4} paddingInline={6} paddingBlock={4} className="bg-gray-50 border-b-2 border-black text-sm uppercase tracking-wider font-semibold">
              <div className="col-span-2">Entity</div>
              <div className="col-span-2">Entity ID</div>
              <div className="col-span-1">Operation</div>
              <div className="col-span-1">Status</div>
              <div className="col-span-2">Duration</div>
              <div className="col-span-2">Started</div>
              <div className="col-span-2 text-right">Run ID</div>
            </Grid>

            {filteredWorkflows.map((wf) => (
              <div
                key={wf.id}
                className="grid grid-cols-12 gap-4 px-6 py-4 border-t border-gray-200 hover:bg-gray-50 items-center"
              >
                <div className="col-span-2">
                  <code className="text-sm bg-gray-100 px-2 py-1 font-mono">
                    {entityLabel(wf.entity_name)}
                  </code>
                </div>

                <div className="col-span-2">
                  <div className="text-sm font-mono text-gray-600">
                    {wf.entity_id.slice(0, 8)}...
                  </div>
                </div>

                <div className="col-span-1">
                  <Text size="sm" weight="medium" uppercase>{wf.operation}</Text>
                </div>

                <div className="col-span-1">
                  <span className={`inline-flex items-center gap-1 text-xs px-2 py-1 border ${getStatusBadge(wf.status)}`}>
                    {getStatusIcon(wf.status)}
                    {wf.status}
                  </span>
                </div>

                <div className="col-span-2">
                  <div className="text-sm font-medium">{formatDuration(wf.duration_ms)}</div>
                  {wf.status === 'draft' && (
                    <div className="text-xs text-blue-600">Running...</div>
                  )}
                </div>

                <div className="col-span-2">
                  <div className="text-sm text-gray-600">
                    {new Date(wf.created_at).toLocaleDateString()}
                  </div>
                  <div className="text-xs text-gray-500">
                    {new Date(wf.created_at).toLocaleTimeString()}
                  </div>
                </div>

                <div className="col-span-2 text-right">
