/**
 * `/reports/$name` — one report, run against the live data.
 *
 * The chart the model declares comes first when there is one; the rows always
 * follow, because a chart summarises and a reader checking a number needs the
 * row behind it. Rows are paged here rather than on the server: a report is one
 * statement, capped at 5,000 rows by the backend, and running it again to fetch
 * page two could answer a different question than page one did.
 */

import { Link, createFileRoute } from "@tanstack/react-router";
import { ArrowLeft, Download, FileBarChart, RefreshCw } from "lucide-react";
import { useMemo, useState } from "react";

import { ReportChart } from "@/components/reports/report-chart";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { EmptyState } from "@/components/ui/empty-state";
import { Box, Heading, HStack, Text, VStack } from "@/components/ui/layout";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { getErrorMessage } from "@/lib/api-client";
import { useReportRun } from "@/hooks/use-reports";

export const Route = createFileRoute("/reports/$name")({
  component: ReportPage,
});

const pageStyle = { maxWidth: 1200, margin: "0 auto", padding: "24px 32px" } as const;
const PAGE_SIZE = 100;

const numberFormat = new Intl.NumberFormat(undefined, { maximumFractionDigits: 4 });

/** How a result cell reads. Dates stay as the database wrote them: unambiguous. */
function display(value: unknown): string {
  if (value === null || value === undefined) return "—";
  if (typeof value === "number") return numberFormat.format(value);
  if (typeof value === "boolean") return value ? "Yes" : "No";
  if (typeof value === "object") return JSON.stringify(value);
  return String(value);
}

/** RFC 4180: quote every field, double any quote inside it. */
function toCsv(columns: string[], rows: Record<string, unknown>[]): string {
  const cell = (value: unknown) => {
    const text = value === null || value === undefined ? "" : typeof value === "object" ? JSON.stringify(value) : String(value);
    return `"${text.replace(/"/g, '""')}"`;
  };
  return [columns.map(cell).join(","), ...rows.map((row) => columns.map((c) => cell(row[c])).join(","))].join("\r\n");
}

function download(name: string, csv: string) {
  const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `${name}.csv`;
  anchor.click();
  URL.revokeObjectURL(url);
}

function ReportPage() {
  const { name } = Route.useParams();
  const { data: result, isLoading, isFetching, error, refetch } = useReportRun(name);
  const [page, setPage] = useState(1);

  const pages = Math.max(1, Math.ceil((result?.rows.length ?? 0) / PAGE_SIZE));
  const current = Math.min(page, pages);
  const visible = useMemo(
    () => result?.rows.slice((current - 1) * PAGE_SIZE, current * PAGE_SIZE) ?? [],
    [result, current]
  );

  const report = result?.report;
  const numeric = useMemo(() => {
    const columns = new Set<string>();
    for (const column of result?.columns ?? []) {
      if (result?.rows.some((row) => typeof row[column] === "number")) columns.add(column);
    }
    return columns;
  }, [result]);

  return (
    <Box style={pageStyle}>
      <VStack gap={5}>
        <Link to="/reports" className="inline-flex w-fit items-center gap-1 text-sm text-muted-foreground hover:text-foreground">
          <ArrowLeft size={14} aria-hidden="true" /> All reports
        </Link>

        {isLoading && (
          <VStack gap={3}>
            <Skeleton height={36} width={360} />
            <Skeleton height={20} width={600} />
            <Skeleton height={320} />
          </VStack>
        )}

        {error && !isLoading && (
          <EmptyState
            title="This report could not be run"
            description={getErrorMessage(error)}
            icon={<FileBarChart size={32} />}
            action={
              <Button variant="outline" onClick={() => refetch()}>
                Try again
              </Button>
            }
          />
        )}

        {result && report && (
          <>
            <HStack align="start" justify="between" gap={4} className="flex-wrap">
              <VStack gap={1} className="min-w-0">
                <Heading level={1}>{report.title}</Heading>
                {report.help && (
                  <Text size="sm" color="secondary">
                    {report.help}
                  </Text>
                )}
                <Text size="xs" color="secondary">
                  {result.rowCount.toLocaleString()} {result.rowCount === 1 ? "row" : "rows"} ·{" "}
                  {result.durationMs} ms
                </Text>
              </VStack>
              <HStack gap={2}>
                <Button variant="outline" size="sm" onClick={() => refetch()} disabled={isFetching}>
                  <RefreshCw size={14} aria-hidden="true" /> {isFetching ? "Running…" : "Run again"}
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => download(report.name, toCsv(result.columns, result.rows))}
                  disabled={result.rows.length === 0}
                >
                  <Download size={14} aria-hidden="true" /> CSV
                </Button>
              </HStack>
            </HStack>

            {result.truncated && (
              <Card className="border-amber-300 bg-amber-50 p-3 text-sm text-amber-900">
                This report returned more rows than the 5,000 the server sends. The first 5,000, in
                the report's own order, are shown and exported.
              </Card>
            )}

            {report.chart && report.xAxis && report.yAxis && result.rows.length > 0 && (
              <Card className="p-4">
                <ReportChart kind={report.chart} rows={result.rows} x={report.xAxis} y={report.yAxis} />
              </Card>
            )}

            {result.rows.length === 0 ? (
              <EmptyState
                title="No rows"
                description="The report ran and nothing in the data matches it yet."
                icon={<FileBarChart size={32} />}
              />
            ) : (
              <Card className="overflow-x-auto p-0">
                <Table>
                  <TableHeader>
                    <TableRow>
                      {result.columns.map((column) => (
                        <TableHead key={column} className={numeric.has(column) ? "text-right" : undefined}>
                          {column}
                        </TableHead>
                      ))}
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {visible.map((row, index) => (
                      <TableRow key={(current - 1) * PAGE_SIZE + index}>
                        {result.columns.map((column) => (
                          <TableCell
                            key={column}
                            className={numeric.has(column) ? "text-right tabular-nums" : undefined}
                          >
                            {display(row[column])}
                          </TableCell>
                        ))}
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </Card>
            )}

            {pages > 1 && (
              <HStack align="center" justify="between">
                <Text size="sm" color="secondary">
                  Rows {((current - 1) * PAGE_SIZE + 1).toLocaleString()}–
                  {Math.min(current * PAGE_SIZE, result.rows.length).toLocaleString()} of{" "}
                  {result.rows.length.toLocaleString()}
                </Text>
                <HStack gap={2}>
                  <Button variant="outline" size="sm" onClick={() => setPage(current - 1)} disabled={current === 1}>
                    Previous
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setPage(current + 1)}
                    disabled={current === pages}
                  >
                    Next
                  </Button>
                </HStack>
              </HStack>
            )}
          </>
        )}
      </VStack>
    </Box>
  );
}

/**
 * `/reports` — the reports the model declares.
 *
 * A report is a question the application's users ask often enough that the
 * model wrote down the query answering it (`reports:` in the model, `sys_report`
 * in the database). They are grouped by the entity each is about, because that
 * is how the model groups them and how a reader looks for one.
 *
 * Outside `/admin`: a report answers a business question, and the people who
 * ask it are the application's users, not its administrators.
 */

import { Link, createFileRoute } from "@tanstack/react-router";
import { AreaChart, BarChart3, FileBarChart, LineChart, PieChart, Table2 } from "lucide-react";
import { useMemo } from "react";

import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { EmptyState } from "@/components/ui/empty-state";
import { Box, Heading, HStack, Text, VStack } from "@/components/ui/layout";
import { Skeleton } from "@/components/ui/skeleton";
import { getErrorMessage } from "@/lib/api-client";
import { type ReportSummary, useReports } from "@/hooks/use-reports";

export const Route = createFileRoute("/reports/")({
  component: ReportsPage,
});

const pageStyle = { maxWidth: 1200, margin: "0 auto", padding: "24px 32px" } as const;

const CHART_ICONS = {
  bar: BarChart3,
  line: LineChart,
  area: AreaChart,
  pie: PieChart,
} as const;

/** "bus_support_case" or "SupportCase" → "Support Case". */
function entityHeading(report: ReportSummary): string {
  const raw = report.entityName ?? report.tableName?.replace(/^bus_/, "") ?? "";
  if (!raw) return "General";
  return raw
    .replace(/_/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function ReportsPage() {
  const { data: reports, isLoading, error } = useReports();

  const groups = useMemo(() => {
    const byEntity = new Map<string, ReportSummary[]>();
    for (const report of reports ?? []) {
      const heading = entityHeading(report);
      byEntity.set(heading, [...(byEntity.get(heading) ?? []), report]);
    }
    return [...byEntity.entries()]
      .map(([heading, items]) => ({
        heading,
        items: [...items].sort(
          (a, b) => a.sortOrder - b.sortOrder || a.title.localeCompare(b.title)
        ),
      }))
      .sort((a, b) => a.heading.localeCompare(b.heading));
  }, [reports]);

  return (
    <Box style={pageStyle}>
      <VStack gap={6}>
        <VStack gap={1}>
          <Heading level={1}>Reports</Heading>
          <Text size="sm" color="secondary">
            The questions this application answers, as its model defines them. Each report runs
            against the live data when you open it.
          </Text>
        </VStack>

        {isLoading && (
          <VStack gap={3}>
            <Skeleton height={72} />
            <Skeleton height={72} />
            <Skeleton height={72} />
          </VStack>
        )}

        {error && (
          <EmptyState
            title="The reports could not be loaded"
            description={getErrorMessage(error)}
            icon={<FileBarChart size={32} />}
          />
        )}

        {!isLoading && !error && groups.length === 0 && (
          <EmptyState
            title="This model declares no reports"
            description="Reports are written in the model under `reports:`; regenerate the application after adding one."
            icon={<FileBarChart size={32} />}
          />
        )}

        {groups.map((group) => (
          <VStack key={group.heading} gap={2}>
            <HStack align="center" gap={2}>
              <Heading level={2} className="text-lg">
                {group.heading}
              </Heading>
              <Text size="sm" color="secondary">
                ({group.items.length})
              </Text>
            </HStack>
            <div className="grid gap-3 md:grid-cols-2">
              {group.items.map((report) => {
                const ChartIcon = report.chart ? CHART_ICONS[report.chart] : Table2;
                return (
                  <Link
                    key={report.name}
                    to="/reports/$name"
                    params={{ name: report.name }}
                    className="block rounded-lg focus:outline-none focus-visible:ring-2 focus-visible:ring-primary"
                  >
                    <Card className="h-full p-4 transition-colors hover:bg-muted/40">
                      <HStack align="start" gap={3}>
                        <span className="mt-0.5 text-primary">
                          <ChartIcon size={20} aria-hidden="true" />
                        </span>
                        <VStack gap={1} className="min-w-0">
                          <HStack align="center" gap={2}>
                            <Text weight="semibold">{report.title}</Text>
                            {report.chart && <Badge variant="secondary">{report.chart}</Badge>}
                          </HStack>
                          {report.help && (
                            <Text size="sm" color="secondary">
                              {report.help}
                            </Text>
                          )}
                        </VStack>
                      </HStack>
                    </Card>
                  </Link>
                );
              })}
            </div>
          </VStack>
        ))}
      </VStack>
    </Box>
  );
}

/**
 * Astryx design system + Tailwind bridge.
 *
 * This is Phase A of the incremental migration (MIGRATION-LOCO-ASTRYX.md §7.3).
 * The import order below IS the cascade contract — the explicit `@layer`
 * declaration on the first line fixes layer precedence regardless of the order
 * the bundler happens to emit these in.
 *
 * ## All seven themes are imported, on purpose
 *
 * Each theme stylesheet is `@scope`-d to `[data-astryx-theme="<name>"]`, so
 * they do not conflict: only the one whose name is on the wrapper element
 * applies. `<Theme>` sets that attribute, which is what lets the app switch
 * themes at runtime without a rebuild. Dropping the unused six would break the
 * theme selector.
 *
 * `@astryxdesign/core/tailwind-theme.css` maps Astryx design tokens onto
 * Tailwind utility names via `@theme inline`. That is what lets the existing
 * ~2,300 `className` sites keep rendering — and start inheriting Astryx's
 * palette — while components are swapped over one at a time, instead of
 * requiring a stop-the-world rewrite.
 *
 * Phase C deletes everything Tailwind on this page: the three `tailwindcss/*`
 * imports and the bridge import, leaving only the Astryx ones.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

@layer reset, theme, base, astryx-base, astryx-theme, components, utilities;

@import 'tailwindcss/theme.css' layer(theme);
@import 'tailwindcss/preflight.css' layer(base);

@import '@astryxdesign/core/reset.css';
@import '@astryxdesign/core/astryx.css';

/* The seven themes. Scoped by [data-astryx-theme], so all seven coexist. */
@import '@astryxdesign/theme-neutral/theme.css';
@import '@astryxdesign/theme-butter/theme.css';
@import '@astryxdesign/theme-chocolate/theme.css';
@import '@astryxdesign/theme-matcha/theme.css';
@import '@astryxdesign/theme-stone/theme.css';
@import '@astryxdesign/theme-gothic/theme.css';
@import '@astryxdesign/theme-y2k/theme.css';

/* The bridge — remove in Phase C, together with the Tailwind imports. */
@import '@astryxdesign/core/tailwind-theme.css';

@import 'tailwindcss/utilities.css' layer(utilities);

/* ---------------------------------------------------------------------------
 * shadcn token compatibility
 *
 * Astryx's bridge above names its Tailwind colours after its own tokens —
 * `card`, `muted`, `surface`, `body`. The screens in this app were written
 * against shadcn's vocabulary — `background`, `foreground`, `muted-foreground`,
 * `destructive`, `input`, `ring` — and those names are not in the bridge, so
 * every one of them generated no CSS at all: `text-muted-foreground` (the most
 * used class in the app), `bg-background` and `text-foreground` were silently
 * doing nothing.
 *
 * Worse than nothing, in two cases. Astryx's `--color-primary` is the *text*
 * colour — near-black in light themes, near-white in dark — while shadcn's
 * `primary` is a brand accent. So `bg-primary` painted cards white-on-white
 * under Gothic, which is why a dark theme rendered the page unreadable.
 *
 * This block defines the shadcn names in terms of Astryx system properties, so
 * the existing `className` sites theme correctly under all seven themes without
 * being rewritten. `@theme inline` emits no declarations of its own — it only
 * registers the names, and the values stay live `var()` references, which is
 * what makes switching themes take effect with no rebuild and no reload.
 *
 * Phase C deletes this along with the rest of Tailwind.
 * ------------------------------------------------------------------------- */
@theme inline {
  /* Surfaces */
  --color-background: var(--color-background-body);
  --color-foreground: var(--color-text-primary);
  --color-card: var(--color-background-card);
  --color-card-foreground: var(--color-text-primary);
  --color-popover: var(--color-background-popover);
  --color-popover-foreground: var(--color-text-primary);

  /* Muted / secondary text and fills */
  --color-muted: var(--color-background-muted);
  --color-muted-foreground: var(--color-text-secondary);
  --color-secondary: var(--color-background-muted);
  --color-secondary-foreground: var(--color-text-primary);

  /* Brand accent. Mapped to Astryx's accent, NOT to `--color-primary`, which
     is a text colour there — see the note above. */
  --color-primary: var(--color-accent);
  --color-primary-foreground: var(--color-on-accent);
  --color-accent: var(--color-background-muted);
  --color-accent-foreground: var(--color-text-primary);

  /* Status */
  --color-destructive: var(--color-error);
  --color-destructive-foreground: var(--color-on-error);

  /* Lines and focus */
  --color-border: var(--color-border);
  --color-input: var(--color-border);
  --color-ring: var(--color-text-accent);
}

/* ---------------------------------------------------------------------------
 * The `swiss-*` component classes the generated screens use.
 *
 * These were referenced throughout the app but never defined, so cards had no
 * surface, inputs no border, and the page no gutter. Built from the same Astryx
 * properties as the block above, so they follow the theme too.
 * ------------------------------------------------------------------------- */
@layer components {
  .container-swiss {
    width: 100%;
    margin-inline: auto;
    max-width: 80rem;
    padding-inline: 1.5rem;
  }

  .swiss-card {
    background-color: var(--color-background-card);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-container);
    color: var(--color-text-primary);
  }

  .swiss-input {
    background-color: var(--color-background-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-element);
    color: var(--color-text-primary);
  }

  .swiss-input::placeholder {
    color: var(--color-text-secondary);
  }

  .swiss-input:focus-visible {
    outline: 2px solid var(--color-text-accent);
    outline-offset: 1px;
  }

  /* One signal hue per theme. Astryx's own accent is monochrome in `neutral`
   * and `gothic`, so tints derived from it vanish there; this is the colour the
   * highlights below are made from. Chosen to sit apart from each theme's
   * surfaces and to keep contrast on both its light and dark backgrounds. */
  [data-astryx-theme="neutral"]   { --ad-highlight: #2563eb; }
  [data-astryx-theme="butter"]    { --ad-highlight: #d97706; }
  [data-astryx-theme="chocolate"] { --ad-highlight: #ea580c; }
  [data-astryx-theme="matcha"]    { --ad-highlight: #16a34a; }
  [data-astryx-theme="stone"]     { --ad-highlight: #0d9488; }
  [data-astryx-theme="gothic"]    { --ad-highlight: #a78bfa; }
  [data-astryx-theme="y2k"]       { --ad-highlight: #db2777; }

  /* ---- Highlights ------------------------------------------------------
   * Every tint is a mix of the *theme's own* accent and its own surface, so
   * each of the seven themes gets its own colour and light and dark both keep
   * their contrast. Nothing here names a hex value. The mix percentages are
   * deliberately strong enough to read as a signal rather than decoration:
   * what the user acts on (primary action, current page, table header, the
   * selected row, a form's focus) is tinted, what they only read is not. */
  .swiss-card {
    border-top: 3px solid var(--ad-highlight, var(--color-accent));
  }

  table thead th {
    background-color: color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 14%, var(--color-background-card));
    color: var(--color-text-primary);
    border-bottom: 2px solid var(--ad-highlight, var(--color-accent));
  }

  /* Alternate rows: every other row a slight shade of the theme's own
     highlight, so a long list can be followed across. Written before the
     hover and selected rules, which share its specificity and must win. */
  table tbody tr:nth-child(even) {
    background-color: color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 6%, transparent);
  }

  table tbody tr:hover {
    background-color: color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 10%, transparent);
  }

  table tbody tr[aria-selected="true"],
  table tbody tr[data-selected="true"] {
    background-color: color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 20%, transparent);
    box-shadow: inset 3px 0 0 var(--ad-highlight, var(--color-accent));
  }

  /* The page the user is on, in the navigation. */
  nav a[aria-current="page"],
  nav [data-active="true"] {
    background-color: color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 18%, transparent);
    color: var(--color-text-accent);
    font-weight: 600;
    box-shadow: inset 3px 0 0 var(--ad-highlight, var(--color-accent));
  }

  /* Links and the field the user is typing in. */
  a:not([role="button"]):not([class*="button"]) {
    color: var(--color-text-accent);
  }

  input:focus-visible,
  select:focus-visible,
  textarea:focus-visible,
  [role="combobox"]:focus-visible {
    outline: 2px solid var(--ad-highlight, var(--color-accent));
    outline-offset: 1px;
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 25%, transparent);
  }

  /* ---- Business palette -------------------------------------------------
   * A small set of muted, mid-tone hues for telling features apart at a glance
   * (dashboard sections, toolbar actions, the navigation). They are tints,
   * never fills: backgrounds come from a few percent of the hue over the
   * theme's own surface, so a light theme stays light and a dark one stays
   * dark, and text keeps the theme's own colour. */
  :where([data-astryx-theme]) {
    --ad-c1: #5b7db1; /* steel blue */
    --ad-c2: #4f9a94; /* teal */
    --ad-c3: #7a9a5b; /* sage */
    --ad-c4: #c39a4a; /* ochre */
    --ad-c5: #9a7bb0; /* heather */
  }

  /* Dashboard cards and sections: one muted hue each, cycling. */
  .grid > .swiss-card { border-top-color: var(--ad-c1); background-image: linear-gradient(color-mix(in srgb, var(--ad-c1) 7%, transparent), transparent 60%); }
  .grid > .swiss-card:nth-child(5n + 2) { border-top-color: var(--ad-c2); background-image: linear-gradient(color-mix(in srgb, var(--ad-c2) 7%, transparent), transparent 60%); }
  .grid > .swiss-card:nth-child(5n + 3) { border-top-color: var(--ad-c3); background-image: linear-gradient(color-mix(in srgb, var(--ad-c3) 7%, transparent), transparent 60%); }
  .grid > .swiss-card:nth-child(5n + 4) { border-top-color: var(--ad-c4); background-image: linear-gradient(color-mix(in srgb, var(--ad-c4) 7%, transparent), transparent 60%); }
  .grid > .swiss-card:nth-child(5n + 5) { border-top-color: var(--ad-c5); background-image: linear-gradient(color-mix(in srgb, var(--ad-c5) 7%, transparent), transparent 60%); }

  /* Actions. A primary action is the theme's highlight; a secondary one (the
     toolbar's Search and New) is a light tint of it, so the screen reads as
     "one thing to do" and "things you can also do". */
  .astryx-button.secondary {
    background-color: color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 12%, var(--color-background-card));
    border: 1px solid color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 30%, transparent);
  }
  .astryx-button.secondary:hover {
    background-color: color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 22%, var(--color-background-card));
  }

  /* The bar above every screen, and the navigation. */
  header.sticky {
    border-bottom: 2px solid color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 55%, transparent);
  }
  aside a:hover,
  nav a:hover {
    background-color: color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 12%, transparent);
  }
  aside a svg,
  nav a svg {
    color: color-mix(in srgb, var(--ad-highlight, var(--color-accent)) 75%, var(--color-text-primary));
  }

  /* A required field's marker and a validation message must be unmissable. */
  [aria-invalid="true"] {
    border-color: var(--color-error);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-error) 25%, transparent);
  }
}

/* The page itself, so the body behind every route follows the theme rather
   than staying the browser default white under a dark theme. */
