#!/usr/bin/env bun
/**
 * Remove faker-generated test data.
 *
 * Two modes:
 *
 *   bun run cleanup.ts            Delete exactly the rows recorded in
 *                                 .e2e-seed-manifest.json — the records the
 *                                 bulk-seed suite created. The application's own
 *                                 seed data (roles, admin user, dictionary,
 *                                 sample business rows) is left alone.
 *
 *   bun run cleanup.ts --all      Delete every row in every bus_ table,
 *                                 manifest or not. Use when a run crashed before
 *                                 writing the manifest, or when you want a truly
 *                                 empty set of business tables.
 *
 * Flags:
 *   --rules      Also deactivate the business rules the suites registered.
 *   --dry-run    Report what would be deleted without deleting it.
 *   --yes        Skip the confirmation prompt for --all.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { login } from "./harness/auth";
import { config } from "./harness/config";
import { entities, topologicalEntities } from "./harness/entities";
import { HttpClient } from "./harness/http";
import {
  clearManifest,
  readManifest,
  type SeedManifest,
  totalRecords,
} from "./harness/manifest";
import { isServerUp, waitForServer } from "./harness/server";

const args = process.argv.slice(2);
const all = args.includes("--all");
const alsoRules = args.includes("--rules");
const dryRun = args.includes("--dry-run");
const assumeYes = args.includes("--yes") || args.includes("-y");

/** Batch size for concurrent deletes — matches the seeder's write concurrency. */
const DELETE_BATCH = 25;

interface Outcome {
  entity: string;
  deleted: number;
  failed: number;
}

async function deleteIds(
  client: HttpClient,
  route: string,
  ids: string[]
): Promise<Outcome> {
  let deleted = 0;
  let failed = 0;

  for (let offset = 0; offset < ids.length; offset += DELETE_BATCH) {
    const batch = ids.slice(offset, offset + DELETE_BATCH);
    const results = await Promise.allSettled(
      batch.map((id) => client.delete(`/bus/${route}/${id}`, { allowFailure: true }))
    );

    for (const result of results) {
      // 404 counts as deleted: the row is gone, which is the goal.
      if (
        result.status === "fulfilled" &&
        (result.value.ok || result.value.status === 404)
      ) {
        deleted += 1;
      } else {
        failed += 1;
      }
    }
  }

  return { entity: route, deleted, failed };
}

/** Every id currently in a bus_ table, paged out. */
async function allIds(client: HttpClient, route: string): Promise<string[]> {
  const ids: string[] = [];
  const limit = 200;

  for (let page = 1; ; page++) {
    const response = await client.get<{ data: Array<{ id: string }>; meta?: { total: number } }>(
      `/bus/${route}?page=${page}&limit=${limit}&orderBy=id&orderDir=asc`,
      { allowFailure: true }
    );
    if (!response.ok) break;

    const rows = response.data?.data ?? [];
    if (rows.length === 0) break;

    ids.push(...rows.map((row) => row.id).filter(Boolean));
    if (rows.length < limit) break;

    // Defensive stop — a misbehaving pager should not spin forever.
    if (page > 500) break;
  }

  return ids;
}

async function confirm(question: string): Promise<boolean> {
  if (assumeYes) return true;
  process.stdout.write(`${question} [y/N] `);
  for await (const line of console) {
    return /^y(es)?$/i.test(line.trim());
  }
  return false;
}

async function main(): Promise<void> {
  console.log("\n═══════════════════════════════════════════");
  console.log("  {{project.name}} — E2E data cleanup");
  console.log("═══════════════════════════════════════════\n");

  if (!(await isServerUp())) {
    console.error(
      `✗ No backend listening on ${config.baseUrl}.\n` +
        `  Start it first: cd ../backend && bun run start`
    );
    process.exit(1);
  }
  await waitForServer();

  const client = new HttpClient();
  await login(client);

  let manifest: SeedManifest | null = null;
  let plan: Array<{ route: string; ids: string[] }> = [];

  if (all) {
    console.log("  Mode: --all (every row in every bus_ table)\n");

    // Children before parents so foreign keys never block a delete.
    const ordered = [...topologicalEntities()].reverse();
    for (const entity of ordered) {
      const ids = await allIds(client, entity.route);
      if (ids.length > 0) plan.push({ route: entity.route, ids });
    }
  } else {
    manifest = await readManifest();
    if (!manifest) {
      console.log("  No .e2e-seed-manifest.json found — nothing recorded to clean.");
      console.log("  Run with --all to clear every bus_ table instead.\n");
      return;
    }

    console.log(`  Mode: manifest (${manifest.createdAt})`);
    console.log(`  Faker seed: ${manifest.fakerSeed}, ${manifest.recordsPerEntity}/entity\n`);

    const order = new Map(topologicalEntities().map((e, index) => [e.route, index]));
    plan = Object.entries(manifest.records)
      .map(([route, ids]) => ({ route, ids }))
      // Reverse topological order: children first.
      .sort((a, b) => (order.get(b.route) ?? 0) - (order.get(a.route) ?? 0));
  }

  const total = plan.reduce((sum, item) => sum + item.ids.length, 0);

  if (total === 0) {
    console.log("  Nothing to delete.\n");
    if (manifest) await clearManifest();
    return;
  }

  for (const item of plan) {
    const entity = entities.find((e) => e.route === item.route);
    console.log(`  ${(entity?.displayName ?? item.route).padEnd(28)} ${item.ids.length} records`);
  }
  console.log(`  ${"".padEnd(28)} ${"─".repeat(16)}`);
  console.log(`  ${"Total".padEnd(28)} ${total} records\n`);

  if (dryRun) {
    console.log("  --dry-run: nothing was deleted.\n");
    return;
  }

  if (all && !(await confirm(`  Delete all ${total} business records?`))) {
    console.log("\n  Cancelled.\n");
    return;
  }

  const outcomes: Outcome[] = [];
  for (const item of plan) {
    const outcome = await deleteIds(client, item.route, item.ids);
    outcomes.push(outcome);
    const entity = entities.find((e) => e.route === item.route);
    console.log(
      `  ✓ ${(entity?.displayName ?? item.route).padEnd(28)} deleted ${outcome.deleted}` +
        (outcome.failed > 0 ? ` (${outcome.failed} failed)` : "")
    );
  }

  if (alsoRules) {
    const ruleIds = manifest?.ruleIds ?? [];
    let deactivated = 0;
    for (const id of ruleIds) {
      const response = await client.delete(`/rules/${id}`, { allowFailure: true });
      if (response.ok) deactivated += 1;
    }
    if (ruleIds.length > 0) {
      console.log(`  ✓ ${"Business rules".padEnd(28)} deactivated ${deactivated}/${ruleIds.length}`);
    }
  }

  const deleted = outcomes.reduce((sum, o) => sum + o.deleted, 0);
  const failed = outcomes.reduce((sum, o) => sum + o.failed, 0);

  if (manifest && failed === 0) await clearManifest();

  console.log(`\n  ${deleted} deleted, ${failed} failed\n`);
  if (failed > 0) {
    console.log("  Some rows could not be deleted — they may be referenced by");
    console.log("  records outside the manifest. Re-run with --all to clear those.\n");
    process.exit(1);
  }
}

main().catch((error) => {
  console.error("\n✗ Cleanup failed:", error instanceof Error ? error.message : error);
  process.exit(1);
});

/**
 * Authentication helpers.
 *
 * The auth routes sit at /api/auth/* rather than under the resource prefix the
 * rest of the client applies, hence `absolute: true` on those calls.
 *
 * The backend issues a JWT *and* sets it as an httpOnly cookie, so the cookie
 * jar carries the session for every later request on the same client and the
 * token is there for anything that would rather send a bearer header.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { config } from "./config";
import { type HttpClient, HttpError } from "./http";

export interface SessionUser {
  id: string;
  email: string;
  name?: string;
  role?: string;
  [key: string]: unknown;
}

export interface Permissions {
  role: string;
  isMaster: boolean;
  windows: Array<{
    sys_window_id: string;
    name: string;
    route: string;
    category: "admin" | "business";
    is_read_only: boolean;
  }>;
}

/**
 * Sign in with email + password. The session cookie lands in the client's jar,
 * so every later request on this client is authenticated.
 */
export async function login(
  client: HttpClient,
  email: string = config.admin.email,
  password: string = config.admin.password
): Promise<SessionUser> {
  const response = await client.post<{ user?: SessionUser; token?: string }>(
    "/api/auth/login",
    { email, password },
    { absolute: true, allowFailure: true }
  );

  if (!response.ok) {
    throw new HttpError(
      `Login failed for ${email} (${response.status}). ` +
        `Confirm the app was seeded — the bootstrap creates ${config.admin.email}. Body: ${response.raw.slice(0, 300)}`,
      response.status,
      response.data,
      "POST",
      "/api/auth/login"
    );
  }

  if (client.jar.size === 0) {
    throw new Error("Login returned 2xx but set no session cookie — the session would not persist.");
  }

  const user = response.data?.user;
  if (!user) {
    // A response carrying only a token is still a valid login — resolve the
    // user through /api/me rather than failing.
    return await currentUser(client);
  }
  return user;
}

/** Register a new account. Returns the created user. */
export async function register(
  client: HttpClient,
  email: string,
  password: string,
  name: string
): Promise<{ ok: boolean; status: number; user?: SessionUser }> {
  const response = await client.post<{ user?: SessionUser }>(
    "/api/auth/register",
    { email, password, name },
    { absolute: true, allowFailure: true }
  );
  return { ok: response.ok, status: response.status, user: response.data?.user };
}

export async function logout(client: HttpClient): Promise<void> {
  await client.post("/api/auth/logout", {}, { absolute: true, allowFailure: true });
  client.jar.clear();
}

/** The currently authenticated user, via the backend's own /api/me route. */
export async function currentUser(client: HttpClient): Promise<SessionUser> {
  const response = await client.get<{ user: SessionUser }>("/me");
  return response.data.user;
}

export async function permissions(client: HttpClient): Promise<Permissions> {
  const response = await client.get<Permissions>("/me/permissions");
  return response.data;
}

/** True when the client currently holds a usable session. */
export async function isAuthenticated(client: HttpClient): Promise<boolean> {
  const response = await client.get("/me", { allowFailure: true });
  return response.ok;
}

/**
 * Browser lifecycle for the suites that must drive the real UI.
 *
 * Everything else in `tests/` talks to the backend over HTTP, which is the
 * right level for a contract oracle. The volume suite is different: the claim
 * it makes is about the *application* under load — the frontend's session, its
 * origin, its dev-server proxy, its grid — so it has to run inside a browser
 * that loaded the app.
 *
 * Two things this deliberately does not do:
 *
 *  - It does not bypass the login screen. The session under test is the one a
 *    user gets, cookie and bearer token included, obtained by typing into the
 *    form. A fixture that injected a token would stop testing the thing that
 *    broke most often in this project's history.
 *
 *  - It does not type 100,000 records into a form. Writes are issued by
 *    `apiFetch`, which runs `fetch` *inside the page* — same origin, same
 *    cookie, same proxy, same headers the app itself sends. That is genuinely
 *    "through the browser"; driving a form a hundred thousand times would
 *    measure Playwright's typing speed and take days.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { existsSync } from "node:fs";
import { join } from "node:path";
import { spawn, type Subprocess } from "bun";
import type { Browser, Page } from "playwright";
import { config } from "./config";

/** A response as seen from inside the page. */
export interface PageResponse<T = unknown> {
  status: number;
  ok: boolean;
  data: T | null;
}

export interface BrowserSession {
  browser: Browser;
  page: Page;
  /** Issue an API request from inside the page, with the app's own session. */
  apiFetch<T = unknown>(
    path: string,
    init?: { method?: string; body?: unknown; headers?: Record<string, string> }
  ): Promise<PageResponse<T>>;
  /**
   * Issue many requests from inside the page with bounded concurrency,
   * returning one round trip's worth of results rather than N.
   */
  apiBatch<T = unknown>(
    requests: Array<{ path: string; method?: string; body?: unknown }>,
    concurrency?: number
  ): Promise<Array<PageResponse<T>>>;
  close(): Promise<void>;
}

/** True when something is already serving the frontend origin. */
export async function isFrontendUp(): Promise<boolean> {
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 2000);
    const response = await fetch(config.origin, { signal: controller.signal });
    clearTimeout(timer);
    return response.ok;
  } catch {
    return false;
  }
}

export interface ManagedFrontend {
  process: Subprocess;
  stop: () => Promise<void>;
}

/**
 * Start the Vite dev server, unless one is already listening.
 *
 * The dev server rather than a production build: its proxy is what puts the API
 * on the same origin as the app, and that is precisely the path this suite is
 * meant to exercise.
 */
export async function startFrontend(frontendDir: string): Promise<ManagedFrontend | null> {
  if (await isFrontendUp()) {
    console.log(`  ✓ Attaching to the frontend already listening on ${config.origin}`);
    return null;
  }
  if (!existsSync(join(frontendDir, "package.json"))) {
    throw new Error(`No package.json in ${frontendDir} — cannot start the frontend.`);
  }

  console.log(`  ▸ Starting frontend from ${frontendDir}…`);
  const child = spawn({
    cmd: ["bun", "run", "dev"],
    cwd: frontendDir,
    stdout: config.verbose ? "inherit" : "ignore",
    stderr: config.verbose ? "inherit" : "ignore",
    env: { ...process.env },
  });

  const deadline = Date.now() + config.serverReadyTimeoutMs;
  while (Date.now() < deadline) {
    if (await isFrontendUp()) {
      console.log("  ✓ Frontend is serving");
      return {
        process: child,
        stop: async () => {
          try {
            child.kill();
            await child.exited;
          } catch {
            // already gone
          }
        },
      };
    }
    await Bun.sleep(500);
  }

  child.kill();
  throw new Error(`Frontend at ${config.origin} was not ready within ${config.serverReadyTimeoutMs}ms.`);
}

/**
 * Fill in the login form and wait for the app to leave it.
 *
 * Retried, and not for flake tolerance. Until the page hydrates, the submit
 * button is a plain HTML button inside a form with no handler attached, so a
 * click performs a *native* GET submit — the URL picks up a `?` and the app
 * lands back on the login screen having never called the API. Nothing about the
 * DOM distinguishes a hydrated form from one that only looks hydrated, so the
 * honest test is whether the submit did anything.
 */
async function signIn(page: Page): Promise<void> {
  const attempts = 4;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    await page.goto(`${config.origin}/auth/login`, { waitUntil: "networkidle" });
    await page.fill('input[type="email"]', config.admin.email);
    await page.fill('input[type="password"]', config.admin.password);
    await page.click('button[type="submit"]');

    try {
      // Waiting on the URL rather than a spinner keeps this independent of the
      // dashboard's markup.
      await page.waitForURL((url) => !url.pathname.startsWith("/auth/login"), {
        timeout: 15_000,
      });
      return;
    } catch (error) {
      if (attempt === attempts) {
        const visible = await page.locator("text=/failed|invalid|incorrect/i").first().textContent()
          .catch(() => null);
        throw new Error(
          `Could not sign in as ${config.admin.email} after ${attempts} attempts` +
            (visible ? ` — the page says: ${visible.trim()}` : "") +
            `\n${error instanceof Error ? error.message : String(error)}`
        );
      }
    }
  }
}

/**
 * Launch a browser, load the app, and sign in through the login form.
 *
 * Chromium headless by default; set E2E_HEADED=1 to watch it work.
 */
export async function openApp(): Promise<BrowserSession> {
  // Imported here rather than at module scope so the rest of the harness stays
  // usable in a checkout where playwright was never installed.
  const { chromium } = await import("playwright");

  const browser = await chromium.launch({
    headless: process.env.E2E_HEADED !== "1",
    // CI images and dev containers often ship a Chromium already, and a
    // playwright upgrade otherwise demands a fresh several-hundred-megabyte
    // download before any test can run. Point E2E_CHROMIUM_PATH at the binary
    // to use it instead; unset, playwright resolves its own as usual.
    executablePath: process.env.E2E_CHROMIUM_PATH || undefined,
    // The volume suite keeps one page open for a long time under load; the
    // default /dev/shm in a container is too small for that.
    args: ["--disable-dev-shm-usage"],
  });
  const context = await browser.newContext({ baseURL: config.origin });
  const page = await context.newPage();

  await signIn(page);

  const apiFetch = async <T = unknown>(
    path: string,
    init: { method?: string; body?: unknown; headers?: Record<string, string> } = {}
  ): Promise<PageResponse<T>> =>
    page.evaluate(
      async ([target, method, body, prefix, deadlineMs, extra]) => {
        // `window` is not in this package's `lib`, and adding DOM to it would
        // change the types every other suite sees. The page has the global
        // regardless; this just names the one member we use.
        const store = (globalThis as { sessionStorage?: { getItem(key: string): string | null } })
          .sessionStorage;
        const token = store ? store.getItem("auth_token") : null;
        const headers: Record<string, string> = {
          "Content-Type": "application/json",
          ...(extra as Record<string, string>),
        };
        if (token) headers.Authorization = `Bearer ${token}`;
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), deadlineMs as number);
        try {
          const response = await fetch(`${prefix}${target}`, {
            method: method as string,
            credentials: "include",
            headers,
            signal: controller.signal,
            body: body == null ? undefined : (body as string),
          });
          const text = await response.text();
          let parsed: unknown = null;
          try {
            parsed = JSON.parse(text);
          } catch {
            // a 204 and an error page both land here; status carries the meaning
          }
          return { status: response.status, ok: response.ok, data: parsed };
        } finally {
          clearTimeout(timer);
        }
      },
      [
        path,
        init.method ?? "GET",
        init.body == null ? null : JSON.stringify(init.body),
        config.apiPrefix,
        config.requestTimeoutMs,
        init.headers ?? {},
      ] as const
    ) as Promise<PageResponse<T>>;

  const apiBatch = async <T = unknown>(
    requests: Array<{ path: string; method?: string; body?: unknown }>,
    concurrency = 16
  ): Promise<Array<PageResponse<T>>> =>
    page.evaluate(
      async ([specs, limit, prefix, deadlineMs]) => {
        const store = (globalThis as { sessionStorage?: { getItem(key: string): string | null } })
          .sessionStorage;
        const token = store ? store.getItem("auth_token") : null;
        const headers: Record<string, string> = { "Content-Type": "application/json" };
        if (token) headers.Authorization = `Bearer ${token}`;

        const list = specs as Array<{ path: string; method?: string; body?: unknown }>;
        const results = new Array(list.length);
        let next = 0;

        // A worker pool rather than Promise.all over the whole batch: the point
        // of a batch is fewer round trips to the page, not an unbounded number
        // of open sockets. See `config.browserVolume.concurrency` for why the
        // default is what it is.
        const worker = async (): Promise<void> => {
          for (;;) {
            const index = next;
            next += 1;
            if (index >= list.length) return;
            const spec = list[index]!;
            // Every request is abortable. Without this one request that never
            // settles — a socket the browser queued behind its per-origin
            // connection limit and then lost — hangs its worker forever, and
            // `Promise.all` below never resolves. That surfaces as the whole
            // suite stopping dead partway through a phase, with a live process,
            // an idle database and nothing logged. A timeout turns it into a
            // failed request, which the caller can see and count.
            const controller = new AbortController();
            const timer = setTimeout(() => controller.abort(), deadlineMs as number);
            try {
              const response = await fetch(`${prefix}${spec.path}`, {
                method: spec.method ?? "GET",
                credentials: "include",
                headers,
                signal: controller.signal,
                body: spec.body == null ? undefined : JSON.stringify(spec.body),
              });
              const text = await response.text();
              let parsed: unknown = null;
              try {
                parsed = JSON.parse(text);
              } catch {
                // see apiFetch
              }
              results[index] = { status: response.status, ok: response.ok, data: parsed };
            } catch (error) {
              results[index] = {
                status: 0,
                ok: false,
                data: { message: error instanceof Error ? error.message : String(error) },
              };
            } finally {
              clearTimeout(timer);
            }
          }
        };

        await Promise.all(
          Array.from({ length: Math.min(limit as number, list.length) }, () => worker())
        );
        return results;
      },
      [requests, concurrency, config.apiPrefix, config.requestTimeoutMs] as const
    ) as Promise<Array<PageResponse<T>>>;

  return {
    browser,
    page,
    apiFetch,
    apiBatch,
    close: async () => {
      await context.close();
      await browser.close();
    },
  };
}

/**
 * Test harness configuration.
 *
 * Every knob is env-overridable so the same suites run against a locally
 * started app, a docker-compose stack, or CI.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

function int(name: string, fallback: number): number {
  const raw = process.env[name];
  if (!raw) return fallback;
  const parsed = Number(raw);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function str(name: string, fallback: string): string {
  const raw = process.env[name];
  return raw && raw.length > 0 ? raw : fallback;
}

export const config = {
  /** Base URL of the running backend, without a trailing slash. */
  baseUrl: str("E2E_BASE_URL", "http://localhost:{{config.port}}").replace(/\/+$/, ""),

  /** Prefix applied by `app.setGlobalPrefix('api')` in the backend. */
  apiPrefix: "/api",

  /** Frontend origin — sent as the Origin header so CORS + better-auth accept us. */
  origin: str("E2E_ORIGIN", "http://localhost:{{config.frontendPort}}"),

  /**
   * Seeded administrator. Must match the backend bootstrap in `src/main.ts`,
   * which reads ADMIN_EMAIL / ADMIN_PASSWORD and defaults to these values.
   */
  admin: {
    email: str("E2E_ADMIN_EMAIL", process.env.ADMIN_EMAIL ?? "admin@admin.com"),
    password: str("E2E_ADMIN_PASSWORD", process.env.ADMIN_PASSWORD ?? "admin"),
  },

  /**
   * Records created per entity by the bulk-seed suite.
   *
   * Two presets are wired into the runner:
   *   --small   10   quick smoke run
   *   --full  1000   the full volume run (the default)
   *
   * `--records <n>` or E2E_RECORDS_PER_ENTITY sets an arbitrary value.
   */
  recordsPerEntity: int("E2E_RECORDS_PER_ENTITY", 1000),

