export * from "./workflows";

/**
 * Seed manifest.
 *
 * The bulk-seed suite deliberately leaves its records in the database for the
 * rules and workflow suites that follow, so nothing tracks them for teardown.
 * This manifest is what makes that reversible: every id the seeder creates is
 * recorded here, and `cleanup.ts` deletes exactly those rows — leaving the
 * application's own seed data (roles, admin user, dictionary) untouched.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { existsSync } from "node:fs";
import { readFile, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";

export const MANIFEST_PATH = join(import.meta.dir, "..", ".e2e-seed-manifest.json");

export interface SeedManifest {
  /** ISO timestamp of the run that produced this manifest. */
  createdAt: string;
  /** Faker seed used, so a run can be reproduced. */
  fakerSeed: number;
  /** Records requested per entity. */
  recordsPerEntity: number;
  /** entity route → created record ids. */
  records: Record<string, string[]>;
  /** Rule ids created by the suites. */
  ruleIds: string[];
}

function empty(): SeedManifest {
  return {
    createdAt: new Date().toISOString(),
    fakerSeed: 0,
    recordsPerEntity: 0,
    records: {},
    ruleIds: [],
  };
}

export async function readManifest(): Promise<SeedManifest | null> {
  if (!existsSync(MANIFEST_PATH)) return null;
  try {
    const raw = await readFile(MANIFEST_PATH, "utf8");
    const parsed = JSON.parse(raw) as SeedManifest;
    // Tolerate a manifest written by an older version.
    return { ...empty(), ...parsed, records: parsed.records ?? {} };
  } catch {
    return null;
  }
}

/**
 * Merge ids into the manifest on disk. Merging rather than overwriting means a
 * partial re-run adds to the cleanup set instead of orphaning the previous run's
 * rows.
 */
export async function recordSeeded(
  entityRoute: string,
  ids: string[],
  meta: { fakerSeed: number; recordsPerEntity: number }
): Promise<void> {
  const manifest = (await readManifest()) ?? empty();

  manifest.createdAt = new Date().toISOString();
  manifest.fakerSeed = meta.fakerSeed;
  manifest.recordsPerEntity = meta.recordsPerEntity;

  const existing = new Set(manifest.records[entityRoute] ?? []);
  for (const id of ids) existing.add(id);
  manifest.records[entityRoute] = [...existing];

  await writeFile(MANIFEST_PATH, JSON.stringify(manifest, null, 2));
}

export async function recordRules(ids: string[]): Promise<void> {
  if (ids.length === 0) return;
  const manifest = (await readManifest()) ?? empty();
  const existing = new Set(manifest.ruleIds ?? []);
  for (const id of ids) existing.add(id);
  manifest.ruleIds = [...existing];
  await writeFile(MANIFEST_PATH, JSON.stringify(manifest, null, 2));
}

export async function clearManifest(): Promise<void> {
  if (existsSync(MANIFEST_PATH)) await unlink(MANIFEST_PATH);
}

export function totalRecords(manifest: SeedManifest): number {
  return Object.values(manifest.records).reduce((sum, ids) => sum + ids.length, 0);
}

/**
 * What the end-to-end run actually did, and how long it took.
 *
 * Every suite runs in its own test-runner process, so there is no shared memory
 * to accumulate into. Each process appends NDJSON to its own shard under the
 * run directory and the runner merges the shards once every suite has
 * finished — append-only, one file per process, so two suites writing at the
 * same moment cannot interleave a half-written line into each other's output.
 *
 * Inserts, updates and deletes are timed from the client: the round trip is
 * what a user waits for, and it is the number that changes when an index goes
 * missing or a hook starts doing real work.
 *
 * Rules and workflows are counted from the server's own report rather than
 * guessed at. A write returns its promotion result, which names every rule
 * action and every workflow that ran and how long the pipeline took — so a
 * single insert that fires one rule and two workflows is recorded as exactly
 * that, without the test having to know what the model declares.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { appendFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

/**
 * The write and execution phases every run measures.
 *
 * A phase is any named unit of work worth a throughput and a tail latency.
 * These five come from instrumenting the client and reading the server's
 * promotion result; the benchmark suite adds read phases ("list deep page",
 * "search substring") by name, which is why `phase` is a string rather than
 * this union — a phase the suites invent must not require editing the
 * collector.
 */
export const WRITE_PHASES = ["insert", "update", "delete", "rule", "workflow"] as const;

export type MetricOp = (typeof WRITE_PHASES)[number];

export interface MetricSample {
  /** `insert`, `list deep page`, … — whatever the run wants averaged. */
  op: string;
  /** Milliseconds. Client round trip for writes; server pipeline for rules and workflows. */
  ms: number;
  /**
   * When the sample finished, epoch millis.
   *
   * Throughput has to come from the wall-clock span a phase occupied, not from
   * the sum of its latencies: suites issue requests concurrently, so summed
   * latency exceeds elapsed time and dividing by it understates throughput —
   * badly. 870 inserts inside a 41-second run is not 14 per second.
   *
   * Stamped by `record` — callers never pass it.
   */
  at?: number;
  /** Entity or rule/workflow name, for a per-name breakdown. */
  name?: string;
}

/**
 * Where this run's shards go. Set by the runner so every suite process agrees;
 * absent when a suite is run directly, in which case nothing is recorded and
 * the suite behaves exactly as before.
 */
const shardDir = process.env.E2E_METRICS_DIR;

const shardFile = shardDir
  ? join(shardDir, `shard-${process.pid}.ndjson`)
  : null;

if (shardDir) {
  try {
    mkdirSync(shardDir, { recursive: true });
  } catch {
    // The runner already created it; a race here is harmless.
  }
}

/**
 * Record one sample.
 *
 * Never throws. Metrics are an observation of the run, and a failure to write
 * one must not turn a passing suite red.
 */
export function record(sample: MetricSample): void {
  if (!shardFile) return;
  try {
    appendFileSync(shardFile, `${JSON.stringify({ ...sample, at: Date.now() })}\n`);
  } catch {
    // Losing a sample costs an average a little accuracy; failing the test
    // because of it would cost far more.
  }
}

/** The promotion result a write returns, as far as metrics care. */
interface PromotionShape {
  ranRules?: unknown;
  ranWorkflows?: unknown;
  durationMs?: unknown;
}

/**
 * Record the rules and workflows a write set off.
 *
 * The promotion reports one duration for the whole pipeline rather than a
 * figure per rule and per workflow, so that duration is attributed to each
 * thing that ran. It is the honest reading of what the server measured: five
 * executions sharing a 40ms pipeline each get 40ms, because 40ms is how long
 * the work they were part of took.
 */
export function recordPromotion(payload: unknown): void {
  if (!shardFile || !payload || typeof payload !== "object") return;

  const promotion = (payload as { promotion?: PromotionShape }).promotion;
  if (!promotion || typeof promotion !== "object") return;

  const ms = typeof promotion.durationMs === "number" ? promotion.durationMs : 0;

  if (Array.isArray(promotion.ranRules)) {
    for (const name of promotion.ranRules) record({ op: "rule", ms, name: String(name) });
  }
  if (Array.isArray(promotion.ranWorkflows)) {
    for (const name of promotion.ranWorkflows) record({ op: "workflow", ms, name: String(name) });
  }
}

/**
 * Which operation a request represents, if any.
 *
 * Only business-entity writes count. Auth, dictionary reads and the health
 * check are traffic the run makes but not work the application was asked to
 * do, and averaging them in would flatter or distort every number.
 */
/**
 * Time one phase and record it.
 *
 * The benchmark suite's whole vocabulary: name what is being measured, run it,
 * and the sample lands in the same file as everything else. Returns whatever
 * the body returned, so a phase can assert on its own result.
 */
export async function timed<T>(phase: string, body: () => Promise<T>, name?: string): Promise<T> {
  const startedAt = performance.now();
  try {
    return await body();
  } finally {
    record({ op: phase, ms: performance.now() - startedAt, name });
  }
}

export function classify(method: string, path: string): { op: MetricOp; name: string } | null {
  const match = /^\/bus\/([^/?]+)/.exec(path);
  if (!match?.[1]) return null;

  const name = match[1];
  const verb = method.toUpperCase();

  if (verb === "POST") return { op: "insert", name };
  if (verb === "PUT" || verb === "PATCH") return { op: "update", name };
  if (verb === "DELETE") return { op: "delete", name };
  return null;
}

/**
 * What the model declared — as data.
 *
 * `entities.ts` describes the *shape* the suites have to build payloads for.
 * This file is the other half: the values a column is allowed to hold and the
 * states a record is allowed to move between, taken straight from the enums
 * and state machines of the source model.
 *
 * The distinction matters. A suite that reads the running application's
 * dictionary and then asserts against that same dictionary proves only that
 * the application is self-consistent — it passes just as happily when the
 * generator dropped a value on the floor. Everything here is the model's own
 * word, so a dropdown that lost an option or a state machine that lost an edge
 * fails a test instead of quietly shipping.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

export interface ModelEnum {
  /** Name as the model spells it. */
  name: string;
  /** sys_reference_id the generator allocated — 1000 and up. */
  referenceId: number;
  /** Allowed values, in declaration order. */
  values: string[];
}

export interface StateEdge {
  from: string;
  to: string;
  /** The `:` label on the diagram's arrow, where it carries one. */
  trigger: string;
}

export interface StateMachine {
  /** ERD entity name, e.g. "Program". */
  entity: string;
  /** Physical table the guard reads transitions for. */
  tableName: string;
  /** Column holding the state — `status` unless the entity has no such column. */
  statusField: string;
  /** The state a record starts in, from the `[*] --> x` edge. */
  initial: string;
  /** States with no outgoing edge. */
  terminal: string[];
  /** Every edge the diagram draws, minus the `[*]` start and end markers. */
  edges: StateEdge[];
}

export const modelEnums: ModelEnum[] = [
{{#each modelEnums}}
  {
    name: "{{name}}",
    referenceId: {{referenceId}},
    values: [{{#each values}}"{{this}}"{{#unless @last}}, {{/unless}}{{/each}}],
  },
{{/each}}
];

export const stateMachines: StateMachine[] = [
{{#each stateMachines}}
  {
    entity: "{{entity}}",
    tableName: "{{tableName}}",
    statusField: "{{statusField}}",
    initial: "{{initial}}",
    terminal: [{{#each terminal}}"{{this}}"{{#unless @last}}, {{/unless}}{{/each}}],
    edges: [
{{#each edges}}
      { from: "{{from}}", to: "{{to}}", trigger: "{{trigger}}" },
{{/each}}
    ],
  },
{{/each}}
];

/** The state machine declared for a table, if the model declared one. */
export function stateMachineFor(tableName: string): StateMachine | undefined {
  return stateMachines.find((machine) => machine.tableName === tableName);
}

/** Every state either end of an edge names, plus the initial state. */
export function statesOf(machine: StateMachine): string[] {
  const seen = new Set<string>();
  if (machine.initial) seen.add(machine.initial);
  for (const edge of machine.edges) {
    seen.add(edge.from);
    seen.add(edge.to);
  }
  return [...seen];
}

/** The states reachable from `from` in one step. */
export function successorsOf(machine: StateMachine, from: string): string[] {
  return machine.edges.filter((edge) => edge.from === from).map((edge) => edge.to);
}

/**
 * A state the model does *not* allow moving to from `from`, or null when the
 * machine allows every state from there and there is nothing illegal to try.
 */
export function illegalTargetFrom(machine: StateMachine, from: string): string | null {
  const allowed = new Set(successorsOf(machine, from));
  allowed.add(from);
  return statesOf(machine).find((state) => !allowed.has(state)) ?? null;
}

/**
 * A shortest path of edges from the machine's initial state to `target`,
 * or null when no path exists. Breadth-first, so a suite walking a record into
 * a given state takes the fewest writes that get it there.
 */
export function pathTo(machine: StateMachine, target: string): StateEdge[] | null {
  if (!machine.initial) return null;
  if (machine.initial === target) return [];

  const queue: Array<{ state: string; path: StateEdge[] }> = [
    { state: machine.initial, path: [] },
  ];
  const seen = new Set<string>([machine.initial]);

  while (queue.length > 0) {
    const current = queue.shift();
    if (!current) break;
    for (const edge of machine.edges) {
      if (edge.from !== current.state || seen.has(edge.to)) continue;
      const path = [...current.path, edge];
      if (edge.to === target) return path;
      seen.add(edge.to);
      queue.push({ state: edge.to, path });
    }
  }
  return null;
}

/**
 * Merge the per-process shards into one report for the run, and compare it
 * with the run before it.
 *
 * Called by the runner once every suite has exited, so all shards are complete
 * and nothing is still being appended to.
 *
 * Two things this deliberately does not do. It does not average across runs —
 * each report is one run, and a trend is read by comparing files rather than
 * by folding them together. And it does not call a change a regression: the
 * comparison names the record count of both runs, because 50× the data costing
 * 3× the time is a scaling curve while 1× the data costing 3× the time is a
 * regression, and only the reader knows which question was asked.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { MetricSample } from "./metrics";
import { WRITE_PHASES } from "./metrics";

export interface PhaseSummary {
  count: number;
  /** Mean milliseconds. */
  averageMs: number;
  minMs: number;
  maxMs: number;
  /** Half the samples are faster than this; less swayed by one slow outlier. */
  medianMs: number;
  p95Ms: number;
  /** The tail users actually notice. */
  p99Ms: number;
  /** Wall time spent inside this phase. */
  totalMs: number;
  /**
   * Completed operations per second while the phase was actually busy.
   *
   * Neither of the obvious denominators works. Summed latency over-counts,
   * because suites issue requests concurrently and overlapping latencies add
   * up to more than the elapsed time — it reported 870 inserts inside a
   * 41-second run as 14 per second. First-sample-to-last under-counts just as
   * badly, because a phase like `update` fires a handful of requests scattered
   * across the whole run and spends most of that span idle: 59 updates over 27
   * seconds is not 2 updates per second.
   *
   * So the denominator is busy time: the union of the intervals during which at
   * least one request of this phase was in flight. Idle gaps drop out,
   * concurrency is counted once.
   *
   * This is the number to read when the record count changes: elapsed grows
   * with volume by definition, throughput does not have to.
   */
  opsPerSec: number;
  /** Busy time — the union of the phase's in-flight intervals. */
  wallMs: number;
}

export interface RunReport {
  project: string;
  /** When the run started, to the second. Matches the filename. */
  startedAt: string;
  finishedAt: string;
  durationMs: number;
  /** Records the bulk-seed phase was asked for — the axis of any comparison. */
  recordsPerEntity: number;
  /** Rows actually written across every phase, the run's real volume. */
  totalWrites: number;
  suites: { total: number; passed: number; failed: number };
  phases: Record<string, PhaseSummary>;
  /** Per entity, rule and workflow — where an average hides a slow outlier. */
  byName: Record<string, PhaseSummary & { op: string }>;
  /** Set when an earlier report was found to compare against. */
  comparison?: Comparison;
}

export interface Comparison {
  againstFile: string;
  againstStartedAt: string;
  againstRecordsPerEntity: number;
  /** True when both runs used the same volume — the only honest regression check. */
  sameScale: boolean;
  phases: Record<
    string,
    {
      previousMs: number;
      currentMs: number;
      /** Change in average latency. */
      changePct: number;
      previousOpsPerSec: number;
      currentOpsPerSec: number;
      /** Change in throughput — the number that survives a change of scale. */
      throughputChangePct: number;
    }
  >;
}

function percentile(sorted: number[], fraction: number): number {
  if (sorted.length === 0) return 0;
  // Nearest-rank: with 200 samples a p99 is the 198th, an actual observation
  // rather than an interpolation between two that never happened.
  const rank = Math.ceil(fraction * sorted.length) - 1;
  return sorted[Math.min(Math.max(rank, 0), sorted.length - 1)] ?? 0;
}

function summarise(entries: { ms: number; at?: number }[]): PhaseSummary {
  if (entries.length === 0) {
    return {
      count: 0,
      averageMs: 0,
      minMs: 0,
      maxMs: 0,
      medianMs: 0,
      p95Ms: 0,
      p99Ms: 0,
      totalMs: 0,
      opsPerSec: 0,
      wallMs: 0,
    };
  }
  const sorted = entries.map((entry) => entry.ms).sort((a, b) => a - b);
  const total = sorted.reduce((sum, value) => sum + value, 0);

  // Fall back to summed latency when nothing is stamped (an older report).
  const busy = busyMs(entries) || total;

  return {
    count: sorted.length,
    averageMs: round(total / sorted.length),
    minMs: round(sorted[0] ?? 0),
    maxMs: round(sorted[sorted.length - 1] ?? 0),
    medianMs: round(percentile(sorted, 0.5)),
    p95Ms: round(percentile(sorted, 0.95)),
    p99Ms: round(percentile(sorted, 0.99)),
    totalMs: round(total),
    opsPerSec: busy > 0 ? round((sorted.length / busy) * 1000) : 0,
    wallMs: round(busy),
  };
}

/**
 * Total time at least one of these samples was in flight.
 *
 * Each sample carries the moment it completed and how long it took, which gives
 * a half-open interval. Sorting by start and merging overlaps collapses
 * concurrent requests into the wall time they really occupied and drops the
 * gaps between bursts entirely.
 */
function busyMs(entries: { ms: number; at?: number }[]): number {
  const intervals = entries
    .filter((entry) => typeof entry.at === "number")
    .map((entry) => ({ start: (entry.at as number) - entry.ms, end: entry.at as number }))
    .sort((a, b) => a.start - b.start);

  let busy = 0;
  let openStart = Number.NaN;
  let openEnd = Number.NaN;

  for (const interval of intervals) {
    if (Number.isNaN(openStart)) {
      openStart = interval.start;
      openEnd = interval.end;
      continue;
    }
    if (interval.start <= openEnd) {
      // Overlaps the run in hand — extend it rather than counting it twice.
      openEnd = Math.max(openEnd, interval.end);
      continue;
    }
    busy += openEnd - openStart;
    openStart = interval.start;
    openEnd = interval.end;
  }

  if (!Number.isNaN(openStart)) busy += openEnd - openStart;
  return busy;
}

function round(value: number): number {
  return Math.round(value * 100) / 100;
}

/** Read every shard the run produced. A missing directory means no samples. */
function readSamples(shardDir: string): MetricSample[] {
  let files: string[];
  try {
    files = readdirSync(shardDir).filter((file) => file.endsWith(".ndjson"));
  } catch {
    return [];
  }

  const samples: MetricSample[] = [];
  for (const file of files) {
    let text: string;
    try {
      text = readFileSync(join(shardDir, file), "utf-8");
    } catch {
      continue;
    }
    for (const line of text.split("\n")) {
      if (!line.trim()) continue;
      try {
        samples.push(JSON.parse(line) as MetricSample);
      } catch {
        // A torn final line from a process killed mid-write; the rest stands.
      }
    }
  }
  return samples;
}

/**
 * `2026-08-04T05-34-12` — the run's start, to the second.
 *
 * Colons are legal in a filename on Linux and a nuisance everywhere else, so
 * the time separators become hyphens. The unabbreviated instant is kept inside
 * the report as `startedAt`.
 */
export function timestampFor(date: Date): string {
  return date.toISOString().slice(0, 19).replace(/:/g, "-");
}

/** The most recent earlier report in the directory, if there is one. */
function previousReport(outputDir: string): { file: string; report: RunReport } | null {
  let files: string[];
  try {
    files = readdirSync(outputDir)
      .filter((file) => file.startsWith("e2e-metrics-") && file.endsWith(".json"))
      .sort();
  } catch {
    return null;
  }

  // Filenames lead with the run's start, so the last one is the most recent.
  for (const file of files.reverse()) {
    try {
      const report = JSON.parse(readFileSync(join(outputDir, file), "utf-8")) as RunReport;
      if (report.phases) return { file, report };
    } catch {
      // A truncated or hand-edited report is skipped, not fatal.
    }
  }
  return null;
}

function compare(current: RunReport, previous: { file: string; report: RunReport }): Comparison {
  const phases: Comparison["phases"] = {};

  for (const [name, summary] of Object.entries(current.phases)) {
    const before = previous.report.phases?.[name];
    if (!before || before.count === 0 || summary.count === 0) continue;

    phases[name] = {
      previousMs: before.averageMs,
      currentMs: summary.averageMs,
      changePct: round(((summary.averageMs - before.averageMs) / before.averageMs) * 100),
      previousOpsPerSec: before.opsPerSec,
      currentOpsPerSec: summary.opsPerSec,
      throughputChangePct:
        before.opsPerSec > 0
          ? round(((summary.opsPerSec - before.opsPerSec) / before.opsPerSec) * 100)
          : 0,
    };
  }

  return {
    againstFile: previous.file,
    againstStartedAt: previous.report.startedAt,
    againstRecordsPerEntity: previous.report.recordsPerEntity ?? 0,
    sameScale: (previous.report.recordsPerEntity ?? 0) === current.recordsPerEntity,
    phases,
  };
}

export interface WriteReportInput {
  outputDir: string;
  shardDir: string;
  startedAt: Date;
  recordsPerEntity: number;
  suites: { total: number; passed: number; failed: number };
}

/** Write the report. Returns it and its path, or null if nothing was recorded. */
export function writeReport(input: WriteReportInput): { path: string; report: RunReport } | null {
  const samples = readSamples(input.shardDir);
  if (samples.length === 0) return null;

  const finishedAt = new Date();

  type Entry = { ms: number; at?: number };
  const byPhase = new Map<string, Entry[]>();
  const byName = new Map<string, { op: string; values: Entry[] }>();

  for (const sample of samples) {
    const entry: Entry = { ms: sample.ms, at: sample.at };
    const bucket = byPhase.get(sample.op) ?? [];
    bucket.push(entry);
    byPhase.set(sample.op, bucket);

    if (!sample.name) continue;
    const key = `${sample.op}:${sample.name}`;
    const named = byName.get(key) ?? { op: sample.op, values: [] };
    named.values.push(entry);
    byName.set(key, named);
  }

  // Write phases first and in a fixed order, then whatever the suites named,
  // alphabetically — so two reports list their phases the same way and a diff
  // between them lines up.
  const ordered = [
    ...WRITE_PHASES.filter((phase) => byPhase.has(phase)),
    ...[...byPhase.keys()]
      .filter((phase) => !(WRITE_PHASES as readonly string[]).includes(phase))
      .sort(),
  ];

  const totalWrites = (["insert", "update", "delete"] as const).reduce(
    (sum, phase) => sum + (byPhase.get(phase)?.length ?? 0),
    0
  );

  const report: RunReport = {
    project: "{{project.name}}",
    startedAt: input.startedAt.toISOString(),
    finishedAt: finishedAt.toISOString(),
    durationMs: finishedAt.getTime() - input.startedAt.getTime(),
    recordsPerEntity: input.recordsPerEntity,
    totalWrites,
    suites: input.suites,
    phases: Object.fromEntries(
      ordered.map((phase) => [phase, summarise(byPhase.get(phase) ?? [])])
    ),
    byName: Object.fromEntries(
      [...byName].map(([key, entry]) => [key, { op: entry.op, ...summarise(entry.values) }])
    ),
  };

  // Compared before writing, so the current run does not find itself.
  const previous = previousReport(input.outputDir);
  if (previous) report.comparison = compare(report, previous);

  mkdirSync(input.outputDir, { recursive: true });
  const path = join(input.outputDir, `e2e-metrics-${timestampFor(input.startedAt)}.json`);
  writeFileSync(path, `${JSON.stringify(report, null, 2)}\n`);
  return { path, report };
}

/* -------------------------------------------------------------------------- */
/*  Console rendering                                                          */
/* -------------------------------------------------------------------------- */

function pad(value: string, width: number): string {
  return value.padStart(width);
}

/** The per-phase table. */
export function formatSummary(report: RunReport): string {
  const names = Object.keys(report.phases).filter((phase) => report.phases[phase]!.count > 0);
  if (names.length === 0) return "  (nothing recorded)";

  const label = Math.max(9, ...names.map((name) => name.length));
  const head =
    `  ${"phase".padEnd(label)} ${pad("count", 7)} ${pad("avg", 10)} ` +
    `${pad("p95", 9)} ${pad("p99", 9)} ${pad("ops/sec", 9)}`;

  const rows = names.map((name) => {
    const phase = report.phases[name]!;
    return (
      `  ${name.padEnd(label)} ${pad(String(phase.count), 7)} ${pad(`${phase.averageMs}ms`, 10)} ` +
      `${pad(`${phase.p95Ms}ms`, 9)} ${pad(`${phase.p99Ms}ms`, 9)} ${pad(String(phase.opsPerSec), 9)}`
    );
  });

  return [head, ...rows].join("\n");
}

/**
 * The comparison table.
 *
 * Leads with what the two runs were, because the same numbers mean different
 * things at the same scale and at 50×. Shows the throughput change beside the
 * latency change: at a different scale, latency growing is expected and
 * throughput holding is the finding.
 */
export function formatComparison(report: RunReport): string {
  const comparison = report.comparison;
  if (!comparison) return "";

  const names = Object.keys(comparison.phases);
  if (names.length === 0) return "";

  const label = Math.max(9, ...names.map((name) => name.length));
  const scaleNote = comparison.sameScale
    ? `same volume (${report.recordsPerEntity}/entity) — a change here is a change in behaviour`
    : `different volume (${comparison.againstRecordsPerEntity} → ${report.recordsPerEntity}/entity) — ` +
      "read ops/sec, not elapsed";

  const head =
    `  ${"phase".padEnd(label)} ${pad("was", 10)} ${pad("now", 10)} ${pad("Δ avg", 9)} ` +
    `${pad("was/sec", 9)} ${pad("now/sec", 9)} ${pad("Δ tput", 9)}`;

  const rows = names.map((name) => {
    const phase = comparison.phases[name]!;
    return (
      `  ${name.padEnd(label)} ${pad(`${phase.previousMs}ms`, 10)} ${pad(`${phase.currentMs}ms`, 10)} ` +
      `${pad(signed(phase.changePct), 9)} ${pad(String(phase.previousOpsPerSec), 9)} ` +
      `${pad(String(phase.currentOpsPerSec), 9)} ${pad(signed(phase.throughputChangePct), 9)}`
    );
  });

  return [`  vs ${comparison.againstFile}`, `  ${scaleNote}`, "", head, ...rows].join("\n");
}

function signed(value: number): string {
  return `${value > 0 ? "+" : ""}${value}%`;
}

/**
 * Business-rule helpers.
 *
 * Rules are GoRules JDM decision graphs. The backend evaluates them through
 * zen-engine on every bus_ write, and a rule may emit a `trigger-workflow`
 * action that the workflow suite then follows.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import type { EntityMeta, FieldMeta } from "./entities";
import type { HttpClient } from "./http";

export interface RuleRecord {
  id: string;
  entity_name: string;
  rule_name: string;
  operation: string;
  jdm_content: string;
  is_active: boolean;
  version: number;
  [key: string]: unknown;
}

export interface RuleAction {
  type: string;
  config: Record<string, unknown>;
}

export interface EvaluationResult {
  ruleName?: string;
  actions?: RuleAction[];
  [key: string]: unknown;
}

export type RuleOperation = "CREATE" | "READ" | "UPDATE" | "DELETE" | "ALL";

// ── JDM construction ────────────────────────────────────────────────────────

interface DecisionRow {
  _id: string;
  /** Zen expression evaluated against the input, e.g. `amount < 0`. */
  when: string;
  action: string;
  message: string;
  workflowName?: string;
  targetEntity?: string;
  linkField?: string;
  createData?: string;
  updateData?: string;
}

/**
 * Build a JDM decision graph with one decision table.
 *
 * Every row shares the same single input (`i1`) bound to the whole context, so
 * a row's `when` expression can reference any field of the record.
 */
export function buildJdm(name: string, rows: DecisionRow[]): string {
  const tableId = `${name}-table`;

  const graph = {
    nodes: [
      { id: "input", type: "inputNode", name: "Input", position: { x: 0, y: 0 } },
      {
        id: tableId,
        type: "decisionTableNode",
        name,
        position: { x: 300, y: 0 },
        content: {
          hitPolicy: "collect",
          inputs: [{ id: "i1", name: "Record", field: "" }],
          outputs: [
            { id: "o1", name: "Action", field: "action" },
            { id: "o2", name: "Message", field: "message" },
            { id: "o3", name: "Rule ID", field: "ruleId" },
            { id: "o4", name: "Workflow Name", field: "workflowName" },
            { id: "o5", name: "Target Entity", field: "targetEntity" },
            { id: "o6", name: "Link Field", field: "linkField" },
            { id: "o7", name: "Update Data", field: "updateData" },
            { id: "o8", name: "Create Data", field: "createData" },
          ],
          rules: rows.map((row) => ({
            _id: row._id,
            i1: row.when,
            o1: `'${row.action}'`,
            o2: `'${row.message.replace(/'/g, "\\'")}'`,
            o3: `'${row._id}'`,
            o4: row.workflowName ? `'${row.workflowName}'` : "''",
            o5: row.targetEntity ? `'${row.targetEntity}'` : "''",
            o6: row.linkField ? `'${row.linkField}'` : "''",
            o7: row.updateData ?? "''",
            o8: row.createData ?? "''",
          })),
        },
      },
      { id: "output", type: "outputNode", name: "Output", position: { x: 600, y: 0 } },
    ],
    edges: [
      { id: "e1", sourceId: "input", targetId: tableId },
      { id: "e2", sourceId: tableId, targetId: "output" },
    ],
  };

  return JSON.stringify(graph);
}

/**
 * A static validation rule set for one entity: required fields must be present
 * and numeric fields must not be negative. These are assertions about the
 * entity's own shape — no side effects.
 */
export function buildStaticValidationJdm(entity: EntityMeta, fields: FieldMeta[]): string {
  const rows: DecisionRow[] = [];

  for (const field of fields) {
    if (field.required) {
      rows.push({
        _id: `${entity.tableName}-${field.name}-required`,
        when: `${field.name} == null`,
        action: "prevent",
        message: `${field.displayName} is required`,
      });
    }
    if (field.type === "integer" || field.type === "decimal") {
      rows.push({
        _id: `${entity.tableName}-${field.name}-non-negative`,
        when: `${field.name} != null and ${field.name} < 0`,
        action: "prevent",
        message: `${field.displayName} must not be negative`,
      });
    }
  }

  // Guarantee at least one row so the table is well-formed for entities whose
  // fields are all optional strings.
  if (rows.length === 0) {
    rows.push({
      _id: `${entity.tableName}-always-allow`,
      when: "true",
      action: "allow",
      message: `${entity.displayName} accepted`,
    });
  }

  return buildJdm(`${entity.displayName} Validation`, rows);
}

/**
 * A rule that fires a workflow on write, optionally cascading into another
 * entity. This is what the workflow suite exercises.
 */
export function buildWorkflowTriggerJdm(
  entity: EntityMeta,
  workflowName: string,
  cascade?: { targetEntity: string; linkField: string; updateData: string }
): string {
  const rows: DecisionRow[] = [
    {
      _id: `${entity.tableName}-trigger-${workflowName}`,
      when: "true",
      action: "trigger-workflow",
      message: `${entity.displayName} write — triggering ${workflowName}`,
      workflowName,
    },
  ];

  if (cascade) {
    rows.push({
      _id: `${entity.tableName}-cascade-${cascade.targetEntity}`,
      when: "true",
      action: "cascade-update",
      message: `Cascading update into ${cascade.targetEntity}`,
      targetEntity: cascade.targetEntity,
      linkField: cascade.linkField,
      updateData: cascade.updateData,
    });
  }

  return buildJdm(`${entity.displayName} Workflow Trigger`, rows);
}

