/**
 * Application Dictionary — the window, tab and field layout.
 *
 * `02-dictionary` checks that every column the ERD declares reached
 * `sys_column`. That is the data half. This is the presentation half: a column
 * nothing draws is a column nobody can edit, and the three tables that decide
 * what gets drawn are `sys_window` (the screen), `sys_tab` (the section of it
 * bound to a table) and `sys_field` (the control bound to a column).
 *
 * The failure this suite exists to catch is silent by construction. A missing
 * `sys_field` row does not error anywhere — the form simply renders without
 * that input, the API keeps accepting the column, and the only symptom is a
 * field a user cannot fill in. Same for a window with no tab: the screen opens
 * empty and the application looks like it has no data.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import { entities, harness, writableFields } from "../harness";

interface WindowRow {
  sys_window_id: string;
  name: string;
  description?: string | null;
  help?: string | null;
  window_type?: string | null;
  is_active?: boolean;
}

interface TabRow {
  sys_tab_id: string;
  sys_window_id: string;
  sys_table_id: string;
  name: string;
  seq_no?: number;
  is_active?: boolean;
  /** 0 for a master tab, 1 for a line item's tab inside its parent's window. */
  tab_level?: number;
  /** The column a detail tab links to its master on. */
  link_column_id?: string | null;
}

interface TableRow {
  sys_table_id: string;
  table_name: string;
  name?: string;
}

interface MetaResponse {
  table: { sys_table_id: string; table_name: string; name?: string };
  columns: Array<{
    sys_field_id?: string;
    column_name: string;
    name: string;
    seq_no?: number;
    seq_no_grid?: number;
    is_displayed?: boolean;
    is_displayed_grid?: boolean;
  }>;
  window?: WindowRow | null;
}

/** `/sys/...` list endpoints answer either a bare array or `{ data: [...] }`. */
function rows<T>(body: unknown): T[] {
  if (Array.isArray(body)) return body as T[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as T[];
  }
  return [];
}

describe("application dictionary — window, tab and field", () => {
  let windows: WindowRow[] = [];
  let tabs: TabRow[] = [];
  /** entity route → its `/meta` payload, fetched once and shared. */
  const metaByRoute = new Map<string, MetaResponse>();

  beforeAll(async () => {
    await harness.setup();

    const [windowResponse, tabResponse, tableResponse] = await Promise.all([
      harness.client.get("/sys/windows?limit=500", { allowFailure: true }),
      harness.client.get("/sys/tabs?limit=500", { allowFailure: true }),
      harness.client.get("/sys/tables?limit=500", { allowFailure: true }),
    ]);
    windows = windowResponse.ok ? rows<WindowRow>(windowResponse.data) : [];
    tabs = tabResponse.ok ? rows<TabRow>(tabResponse.data) : [];
    const tables = tableResponse.ok ? rows<TableRow>(tableResponse.data) : [];

    // `/bus/{route}/meta` on this backend answers `{ name, tableName, columns }`
    // — it describes the entity, not its place in the dictionary. The table id
    // and the window are assembled here from `/sys/*` instead, so the
    // assertions below read the same shape whichever way the backend serves it.
    //
    // The window is reached through the entity's own tab rather than looked up
    // by name: `sys_tab.sys_window_id` is the edge the seed actually writes,
    // and a line item has no window of its own — its tab hangs off its
    // parent's, which is precisely what several of these tests are here to
    // check. Matching on names would make a child look windowless instead.
    const tableByName = new Map(tables.map((table) => [table.table_name, table]));
    const windowById = new Map(windows.map((window) => [window.sys_window_id, window]));

    for (const entity of entities) {
      const table = tableByName.get(entity.tableName);
      const ownTab = tabs.find((tab) => tab.sys_table_id === table?.sys_table_id);
      const fields = await harness.client.get<MetaResponse["columns"]>(
        `/bus/${entity.route}/fields/form?includeHidden=true`,
        { allowFailure: true }
      );

      metaByRoute.set(entity.route, {
        table: {
          sys_table_id: table?.sys_table_id ?? "",
          table_name: entity.tableName,
          name: table?.name,
        },
        columns: fields.ok ? rows<MetaResponse["columns"][number]>(fields.data) : [],
        window: ownTab ? (windowById.get(ownTab.sys_window_id) ?? null) : null,
      });
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("serves the window registry", () => {
    expect(windows.length).toBeGreaterThan(0);
  });

  it("serves the tab registry", () => {
    expect(tabs.length).toBeGreaterThan(0);
  });

  it("registers a window for every entity", () => {
    const missing = entities.filter((entity) => !metaByRoute.get(entity.route)?.window).map(
      (entity) => entity.tableName
    );
    expect(missing).toEqual([]);
  });

  // A tab whose sys_table_id names no registered table draws a section bound
  // to nothing — the screen renders a heading and no rows.
  it("binds every tab to a registered table", () => {
    const tableIds = new Set(
      [...metaByRoute.values()].map((meta) => meta.table?.sys_table_id).filter(Boolean)
    );
    // Only tabs belonging to entity windows are checked: the Application
    // Dictionary's own screens (Audit Log, Workflow Designer…) describe how the
    // application is built and have no bus_ table behind them.
    const entityWindowIds = new Set(
      [...metaByRoute.values()].map((meta) => meta.window?.sys_window_id).filter(Boolean)
    );
    const orphans = tabs
      .filter((tab) => entityWindowIds.has(tab.sys_window_id))
      .filter((tab) => !tab.sys_table_id || !tableIds.has(tab.sys_table_id))
      .map((tab) => tab.name);
    expect(orphans).toEqual([]);
  });

  it("gives every window a distinct name", () => {
    const names = windows.map((window) => window.name);
    const duplicates = names.filter((name, index) => names.indexOf(name) !== index);
    expect([...new Set(duplicates)]).toEqual([]);
  });

  for (const entity of entities) {
    describe(entity.displayName, () => {
      it("has a window carrying a name and help", () => {
        const meta = metaByRoute.get(entity.route);
        expect(meta?.window).toBeTruthy();
        expect(typeof meta?.window?.name).toBe("string");
        expect((meta?.window?.name ?? "").length).toBeGreaterThan(0);
      });

      it("has at least one tab under that window", () => {
        const meta = metaByRoute.get(entity.route);
        const windowId = meta?.window?.sys_window_id;
        expect(windowId).toBeTruthy();
        const owned = tabs.filter((tab) => tab.sys_window_id === windowId);
        expect(owned.length).toBeGreaterThan(0);
      });

      it("has a tab of its own on that window", () => {
        const meta = metaByRoute.get(entity.route);
        const windowId = meta?.window?.sys_window_id;
        const owned = tabs.filter((tab) => tab.sys_window_id === windowId);
        // The entity's own tab must be there. It used to be asserted the other
        // way round — that *every* tab on the window pointed at this table —
        // which was right while a window held exactly one entity and wrong the
        // moment an entity's `parent` put a line item's tab
        // beside its master's. What matters is that the entity is represented,
        // and that anything else on the window is a declared child of it.
        const mine = owned.filter((tab) => tab.sys_table_id === meta?.table?.sys_table_id);
        expect(mine.length).toBeGreaterThan(0);
      });

      it("shares its window only with its own line items", () => {
        const meta = metaByRoute.get(entity.route);
        const windowId = meta?.window?.sys_window_id;
        const owned = tabs.filter((tab) => tab.sys_window_id === windowId);

        // A window belongs to one entity and may hold that entity's tab plus
        // the tabs of its line items — so the question is asked of the window's
        // *owner*, which for a child is its parent. Asking it of the child put
        // the master's own tab in the foreign list, which is the arrangement
        // working rather than failing.
        const owner = entity.parentEntity
          ? (entities.find((candidate) => candidate.name === entity.parentEntity) ?? entity)
          : entity;
        const permitted = new Set<string | undefined>([
          metaByRoute.get(owner.route)?.table?.sys_table_id,
        ]);
        for (const child of entities) {
          if (child.parentEntity !== owner.name) continue;
          permitted.add(metaByRoute.get(child.route)?.table?.sys_table_id);
        }

        const foreign = owned
          .filter((tab) => !permitted.has(tab.sys_table_id))
          .map((tab) => tab.name);
        expect(foreign).toEqual([]);
      });

      it("is a detail tab when the model declares a parent", () => {
        const meta = metaByRoute.get(entity.route);
        const own = tabs.filter((tab) => tab.sys_table_id === meta?.table?.sys_table_id);
        expect(own.length).toBeGreaterThan(0);

        if (entity.parentEntity) {
          // A line item lives inside its parent's window, one level down, and
          // links on the foreign key it declared. Without the link column the
          // tab would list every child in the table under whichever parent
          // happened to be open.
          const parentMeta = metaByRoute.get(
            entities.find((candidate) => candidate.name === entity.parentEntity)?.route ?? ""
          );
          expect(meta?.window?.sys_window_id).toBe(parentMeta?.window?.sys_window_id);
          expect(own[0]?.tab_level).toBe(1);
          expect(own[0]?.link_column_id).toBeTruthy();
        } else {
          expect(own[0]?.tab_level).toBe(0);
        }
      });

      it("draws a field for every column the model declares", async () => {
        const response = await harness.client.get<Array<{ column_name: string }>>(
          `/bus/${entity.route}/fields/form?includeHidden=true`
        );
        const drawn = new Set(response.data.map((field) => field.column_name));
        const missing = writableFields(entity)
          .map((field) => field.name)
          .filter((name) => !drawn.has(name));
        expect(missing).toEqual([]);
      });

      // Two fields sharing a sequence leave the form's order down to whatever
      // the database returns first, which is not stable between runs.
      it("gives its form fields distinct sequence numbers", async () => {
        const response = await harness.client.get<Array<{ seq_no?: number }>>(
          `/bus/${entity.route}/fields/form?includeHidden=true`
        );
        const sequences = response.data
          .map((field) => field.seq_no)
          .filter((seq): seq is number => typeof seq === "number");
        expect(sequences.length).toBe(new Set(sequences).size);
      });

      it("labels every field with something other than the raw column name", async () => {
        const response = await harness.client.get<
          Array<{ column_name: string; name?: string }>
        >(`/bus/${entity.route}/fields/form?includeHidden=true`);

        // `smiles` and `id` are already words; the check is that a column with
        // underscores in it was turned into a label, not printed as stored.
        const raw = response.data
          .filter((field) => field.column_name.includes("_"))
          .filter((field) => !field.name || field.name === field.column_name)
          .map((field) => field.column_name);
        expect(raw).toEqual([]);
      });

      // Grid columns are drawn from the same field rows as the form, so a grid
      // field that is not also a form field is a row the form cannot reach.
      it("draws its grid from fields the form also knows", async () => {
        const [form, grid] = await Promise.all([
          harness.client.get<Array<{ column_name: string }>>(
            `/bus/${entity.route}/fields/form?includeHidden=true`
          ),
          harness.client.get<Array<{ column_name: string }>>(`/bus/${entity.route}/fields/grid`),
        ]);
        const known = new Set(form.data.map((field) => field.column_name));
        const unknown = grid.data
          .map((field) => field.column_name)
          .filter((name) => !known.has(name));
        expect(unknown).toEqual([]);
      });

      it("shows at least one column in the grid", async () => {
        const response = await harness.client.get<Array<unknown>>(
          `/bus/${entity.route}/fields/grid`
        );
        // A grid with no columns is a list screen that renders empty rows.
        expect(response.data.length).toBeGreaterThan(0);
      });

      it("answers the window-help request its screens make", async () => {
        const response = await harness.client.get<{
          window?: { name?: string };
          tabs?: unknown[];
          fields?: unknown[];
        }>(`/sys/window-help/${entity.tableName}`, { allowFailure: true });

        expect(response.status).toBe(200);
        expect(response.data?.window?.name).toBeTruthy();
      });
    });
  }
});

/**
 * Application Dictionary — references.
 *
 * A reference is what turns a column into a control. `sys_reference_id` 13 on a
 * uuid column makes it read-only; a list reference makes a dropdown and carries
 * the values it offers; a table reference makes a lookup and carries the table
 * it searches and the column it shows instead of the stored id.
 *
 * Every failure here has the same shape on screen: the control degrades to a
 * plain text box. A dropdown that lost its list becomes free text, so `status`
 * accepts a value the state machine has no edge for. A lookup that lost its
 * table becomes a box asking a human to type a uuid. Neither errors, and both
 * are invisible to a test that only checks the column exists.
 *
 * So the assertions here compare the running application against the *model* —
 * `harness/model.ts`, generated from the model's enums — rather than
 * against the dictionary that the same generator wrote.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import {
  entities,
  foreignKeyFields,
  harness,
  modelEnums,
  writableFields,
} from "../harness";

/** sys_reference ids the generator treats as built-in scalars. */
const STANDARD = {
  string: 10,
  integer: 11,
  amount: 12,
  id: 13,
  text: 14,
  date: 15,
  dateTime: 16,
  list: 17,
  table: 18,
  tableDirect: 19,
  yesNo: 20,
} as const;

/** Model enums are allocated from 1000 up; anything at or above is a dropdown. */
const FIRST_MODEL_REFERENCE = 1000;

interface FormField {
  column_name: string;
  name?: string;
  sys_reference_id?: number;
  is_mandatory?: boolean;
  /** Present on table references — the table the lookup searches. */
  ref_table_name?: string | null;
  /** Present on table references — the columns shown instead of the id. */
  ref_label_fields?: string[] | null;
  /**
   * Present on list references in stacks that inline them. This one does not:
   * the form resolves a dropdown through `/sys/ref-list?sys_reference_id=`,
   * so the tests below go there rather than reading this.
   */
  options?: Array<{ value: string; label: string }> | null;
}

interface ReferenceRow {
  sys_reference_id: number;
  name: string;
  validation_type?: string;
}

function rows<T>(body: unknown): T[] {
  if (Array.isArray(body)) return body as T[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as T[];
  }
  return [];
}

describe("application dictionary — references", () => {
  let references: ReferenceRow[] = [];
  let referenceIds = new Set<number>();
  /** entity route → its form fields, including the hidden ones. */
  const fieldsByRoute = new Map<string, FormField[]>();
  /** sys_reference_id → the values its list offers. Fetched once each. */
  const refListCache = new Map<number, string[]>();

  async function refListValues(referenceId: number): Promise<string[]> {
    const cached = refListCache.get(referenceId);
    if (cached) return cached;
    const response = await harness.client.get<Array<{ value: string }>>(
      `/sys/ref-list?sys_reference_id=${referenceId}`,
      { allowFailure: true }
    );
    const values = response.ok ? rows<{ value: string }>(response.data).map((e) => e.value) : [];
    refListCache.set(referenceId, values);
    return values;
  }
  const registeredTables = new Set(entities.map((entity) => entity.tableName));

  beforeAll(async () => {
    await harness.setup();

    const response = await harness.client.get("/sys/references?limit=1000", {
      allowFailure: true,
    });
    references = response.ok ? rows<ReferenceRow>(response.data) : [];
    referenceIds = new Set(references.map((reference) => reference.sys_reference_id));

    for (const entity of entities) {
      const fields = await harness.client.get<FormField[]>(
        `/bus/${entity.route}/fields/form?includeHidden=true`,
        { allowFailure: true }
      );
      if (fields.ok) fieldsByRoute.set(entity.route, fields.data);
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("serves the reference registry", () => {
    expect(references.length).toBeGreaterThan(0);
  });

  it("registers the standard scalar references", () => {
    const missing = Object.values(STANDARD).filter((id) => !referenceIds.has(id));
    expect(missing).toEqual([]);
  });

  // ── The model's enums ─────────────────────────────────────────────────────

  describe("model enums", () => {
    it("registers a reference for every enum the model declares", () => {
      const missing = modelEnums
        .filter((modelEnum) => !referenceIds.has(modelEnum.referenceId))
        .map((modelEnum) => modelEnum.name);
      expect(missing).toEqual([]);
    });

    for (const modelEnum of modelEnums) {
      it(`${modelEnum.name} offers exactly the values the model declares`, async () => {
        const response = await harness.client.get<Array<{ value: string; name?: string }>>(
          `/sys/ref-list?sys_reference_id=${modelEnum.referenceId}`,
          { allowFailure: true }
        );
        expect(response.status).toBe(200);

        const served = rows<{ value: string }>(response.data)
          .map((entry) => entry.value)
          .sort();
        expect(served).toEqual([...modelEnum.values].sort());
      });
    }
  });

  // ── Per entity ────────────────────────────────────────────────────────────

  for (const entity of entities) {
    describe(entity.displayName, () => {
      it("gives every field a reference that resolves", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        expect(fields.length).toBeGreaterThan(0);

        const dangling = fields
          .filter((field) => typeof field.sys_reference_id === "number")
          .filter((field) => !referenceIds.has(field.sys_reference_id as number))
          .map((field) => `${field.column_name}→${field.sys_reference_id}`);
        expect(dangling).toEqual([]);
      });

      // The one that catches a lookup degraded to a uuid text box.
      it("points every foreign key at a table that exists", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byColumn = new Map(fields.map((field) => [field.column_name, field]));

        const unresolved: string[] = [];
        for (const fk of foreignKeyFields(entity)) {
          const field = byColumn.get(fk.name);
          if (!field) continue; // absence is 02b's failure, not this one's
          const target = field.ref_table_name;
          if (!target || !registeredTables.has(target)) {
            unresolved.push(`${fk.name}→${target ?? "unresolved"}`);
          }
        }
        expect(unresolved).toEqual([]);
      });

      // A reference the model named outright (a CEDM `deliveryLocation →
      // Location`) must reach the table it named, not the one its column name
      // would derive.
      it("points a named reference at the entity the model named", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byColumn = new Map(fields.map((field) => [field.column_name, field]));
        const wrong: string[] = [];
        for (const fk of foreignKeyFields(entity)) {
          if (!fk.references) continue;
          const expected = entities.find((item) => item.name === fk.references)?.tableName;
          const actual = byColumn.get(fk.name)?.ref_table_name;
          if (actual !== expected) wrong.push(`${fk.name}→${actual ?? "unresolved"} (model: ${expected})`);
        }
        expect(wrong).toEqual([]);
      });

      it("gives every foreign key a column to display instead of the id", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byColumn = new Map(fields.map((field) => [field.column_name, field]));

        const unlabelled: string[] = [];
        for (const fk of foreignKeyFields(entity)) {
          const field = byColumn.get(fk.name);
          if (!field?.ref_table_name) continue; // covered by the test above
          const labels = field.ref_label_fields;
          if (!Array.isArray(labels) || labels.length === 0) unlabelled.push(fk.name);
        }
        expect(unlabelled).toEqual([]);
      });

      // A label column the target table does not have resolves to nothing at
      // render time, which puts the raw id back on screen.
      it("names label columns the target table actually has", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byTable = new Map(entities.map((item) => [item.tableName, item]));

        const bad: string[] = [];
        for (const fk of foreignKeyFields(entity)) {
          const field = byColumn(fields, fk.name);
          const target = field?.ref_table_name;
          if (!target) continue;
          const targetEntity = byTable.get(target);
          if (!targetEntity) continue;
          const columns = new Set(targetEntity.fields.map((item) => item.name));
          for (const label of field?.ref_label_fields ?? []) {
            if (!columns.has(label)) bad.push(`${fk.name}→${target}.${label}`);
          }
        }
        expect(bad).toEqual([]);
      });

      // This backend does not inline a dropdown's values on the field. The
      // field carries `sys_reference_id`, and the form resolves the values
      // with a separate `/sys/ref-list?sys_reference_id=` call — which is why
      // `options` being absent here is the shape, not a fault. What must hold
      // is that the id resolves to a list with something in it: an empty list
      // renders an empty dropdown, which is the same dead end as a text box.
      it("gives every dropdown a reference list with values in it", async () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const empty: string[] = [];

        for (const field of fields) {
          const referenceId = field.sys_reference_id ?? 0;
          if (referenceId < FIRST_MODEL_REFERENCE) continue;
          const values = await refListValues(referenceId);
          if (values.length === 0) empty.push(`${field.column_name}→${referenceId}`);
        }
        expect(empty).toEqual([]);
      });

      // A dropdown offering a value the model never declared lets a user pick
      // something no rule and no workflow edge was written for.
      it("offers only values the model declares", async () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byReference = new Map(modelEnums.map((item) => [item.referenceId, item]));

        const strays: string[] = [];
        for (const field of fields) {
          const modelEnum = byReference.get(field.sys_reference_id ?? -1);
          if (!modelEnum) continue;
          const allowed = new Set(modelEnum.values);
          for (const value of await refListValues(modelEnum.referenceId)) {
            if (!allowed.has(value)) strays.push(`${field.column_name}=${value}`);
          }
        }
        expect(strays).toEqual([]);
      });

      it("marks the model's required fields mandatory", () => {
        const fields = fieldsByRoute.get(entity.route) ?? [];
        const byName = new Map(fields.map((field) => [field.column_name, field]));

        const wrong = writableFields(entity)
          .filter((field) => field.required)
          .filter((field) => byName.has(field.name))
          .filter((field) => byName.get(field.name)?.is_mandatory !== true)
          .map((field) => field.name);
        expect(wrong).toEqual([]);
      });
    });
  }
});

function byColumn(fields: FormField[], name: string): FormField | undefined {
  return fields.find((field) => field.column_name === name);
}

/**
 * Bulk seeding — faker-generated volume data.
 *
 * Creates `E2E_RECORDS_PER_ENTITY` (default 1000) records for every entity,
 * parents first so foreign keys resolve. This is the slow suite; it doubles as
 * a load smoke test for list/pagination at realistic row counts.
 *
 * Records here are deliberately NOT tracked for harness teardown — the point is
 * to leave the database populated for the rules and workflow suites that follow.
 * Every id is written to `.e2e-seed-manifest.json` instead, so `bun run clean`
 * can remove exactly this data later without touching the app's own seed rows.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import {
  buildRecord,
  config,
  type EntityMeta,
  foreignKeyFields,
  harness,
  recordSeeded,
  reseed,
} from "../harness";

/** Ids created per entity, reused to satisfy the next entity's foreign keys. */
const createdIds = new Map<string, string[]>();

/**
 * Requests a minute the backend allows one caller, as it advertises in
 * `ratelimit-limit`; 0 when the limiter is off.
 *
 * `bun run test` starts the backend with the limiter off, but `test:attach`
 * runs against one someone else started — 300 a minute in development. The
 * harness waits out every 429, so the records still land, just no faster than
 * the budget: 1000 of them take more than three minutes, which a timeout sized
 * for an unthrottled server cut off on every entity. Read once, before any
 * test is registered, because a test's timeout is fixed when it is declared.
 */
const budgetPerMinute =
  Number(
    (await fetch(`${config.baseUrl}${config.apiPrefix}/sys/tables?limit=1`)).headers.get(
      "ratelimit-limit"
    )
  ) || 0;

/** How long seeding `count` records may take through the rules + audit pipeline. */
function seedTimeoutMs(count: number): number {
  const pipeline = Math.max(120_000, count * 200);
  if (budgetPerMinute === 0) return pipeline;
  // One POST per record: a full window per budget's worth, plus one to spare.
  return pipeline + (Math.ceil(count / budgetPerMinute) + 1) * 60_000;
}

/**
 * How many times a record the application refuses is rebuilt from fresh values.
 *
 * A model's business rules refuse input the factory has no way to foresee —
 * crm's quote policy refuses any discount above 40 percent, and a percentage
 * drawn from 0–100 breaks it more often than not. The rules are zen
 * expressions evaluated by the backend; restating them here would be a second
 * rules engine to keep in step with the first. So the seed does what a person
 * at the form does when a rule says no: it submits different values. A record
 * still refused after every attempt counts as rejected, and a rule no value
 * can satisfy still fails the suite.
 */
const REBUILD_ATTEMPTS = 8;

/** Insert records in bounded-concurrency batches so we do not open 1000 sockets. */
async function seedEntity(
  entity: EntityMeta,
  count: number
): Promise<{ created: number; failed: number; rebuilt: number }> {
  const fks = foreignKeyFields(entity);
  const ids: string[] = [];
  let failed = 0;
  let rebuilt = 0;

  const post = (payload: Record<string, unknown>) =>
    harness.client.post<{ id: string }>(`/bus/${entity.route}`, payload, { allowFailure: true });

  for (let offset = 0; offset < count; offset += config.seedBatchSize) {
    const size = Math.min(config.seedBatchSize, count - offset);

    const foreignKeysFor = (position: number): Record<string, string> => {
      const foreignKeys: Record<string, string> = {};
      for (const fk of fks) {
        const parent = harness.resolveParentEntity(fk.name, fk.references);
        if (!parent) continue;
        const pool = createdIds.get(parent.route);
        if (pool && pool.length > 0) {
          foreignKeys[fk.name] = pool[position % pool.length]!;
        }
      }
      return foreignKeys;
    };

    const results = await Promise.allSettled(
      Array.from({ length: size }, async (_unused, index) => {
        const position = offset + index;
        const foreignKeys = foreignKeysFor(position);
        let response = await post(buildRecord(entity, { foreignKeys, uniqueSalt: `${position}` }));
        // Only a validation refusal is worth another draw; anything else would
        // fail the same way with any values.
        for (
          let attempt = 1;
          !response.ok && response.status === 400 && attempt <= REBUILD_ATTEMPTS;
          attempt++
        ) {
          rebuilt += 1;
          response = await post(
            buildRecord(entity, { foreignKeys, uniqueSalt: `${position}r${attempt}` })
          );
        }
        return response;
      })
    );

    for (const result of results) {
      if (result.status === "fulfilled" && result.value.ok && result.value.data?.id) {
        ids.push(result.value.data.id);
      } else {
        failed += 1;
      }
    }
  }

  createdIds.set(entity.route, ids);

  // Record before asserting, so a partially-failed batch is still cleanable.
  await recordSeeded(entity.route, ids, {
    fakerSeed: config.fakerSeed,
    recordsPerEntity: count,
  });

  return { created: ids.length, failed, rebuilt };
}

describe("bulk seed", () => {
  beforeAll(async () => {
    await harness.setup();
    reseed();
  });

  afterAll(async () => {
    // Volume data is intentionally left in place for later suites; only the
    // harness-tracked records (none here) are removed.
    harness.invalidateCache();
  });

  const target = config.recordsPerEntity;

  it(`is configured for at least 1000 records per entity (got ${target})`, () => {
    expect(target).toBeGreaterThanOrEqual(1);
  });

  for (const entity of harness.orderedEntities()) {
    it(
      `seeds ${target} ${entity.displayName} records`,
      async () => {
        const { created, failed, rebuilt } = await seedEntity(entity, target);

        console.log(
          `    ${entity.displayName}: created ${created}/${target}` +
            (failed > 0 ? ` (${failed} rejected)` : "") +
            (rebuilt > 0 ? ` (${rebuilt} redrawn after a validation refusal)` : "")
        );

        // Allow a small rejection margin for unique-constraint collisions the
        // factory cannot foresee, but the bulk of the batch must land.
        expect(created).toBeGreaterThanOrEqual(Math.floor(target * 0.95));
      },
      seedTimeoutMs(target)
    );

    it(`reports the seeded ${entity.displayName} rows in the list total`, async () => {
      const response = await harness.client.get<{ meta: { total: number } }>(
        `/bus/${entity.route}?limit=1`
      );

      expect(response.data.meta.total).toBeGreaterThanOrEqual(
        Math.floor(target * 0.95)
      );
    });

    it(`paginates ${entity.displayName} consistently`, async () => {
      const first = await harness.client.get<{ data: Array<{ id: string }> }>(
        `/bus/${entity.route}?page=1&limit=50&orderBy=id&orderDir=asc`
      );
      const second = await harness.client.get<{ data: Array<{ id: string }> }>(
        `/bus/${entity.route}?page=2&limit=50&orderBy=id&orderDir=asc`
      );

      expect(first.data.data.length).toBeGreaterThan(0);

      const firstIds = new Set(first.data.data.map((row) => row.id));
      const overlap = second.data.data.filter((row) => firstIds.has(row.id));
      expect(overlap).toEqual([]);
    });
  }
});

/**
 * Rules that trigger workflows.
 *
 * Registers `trigger-workflow` rules and proves the chain end to end:
 * write a record → rule matches → workflow run is enqueued → run reaches a
 * terminal state.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import {
  buildWorkflowTriggerJdm,
  collectActions,
  config,
  createRule,
  entities,
  evaluate,
  harness,
  hasAction,
  isTerminal,
  listRuns,
  runsForEntity,
  waitForEntityRuns,
  type RuleRecord,
} from "../harness";

const suiteId = `e2e-wf-${Date.now().toString(36)}`;

describe("rules triggering workflows", () => {
  const registered: Array<{ entityRoute: string; entityTable: string; rule: RuleRecord }> = [];

  beforeAll(async () => {
    await harness.setup();

    for (const entity of entities) {
      const workflowName = `${entity.tableName}-on-write-workflow`;
      const jdm = buildWorkflowTriggerJdm(entity, workflowName);

      const rule = await createRule(harness.client, {
        entityName: entity.tableName,
        ruleName: `${suiteId}-${entity.tableName}-trigger`,
        operation: "CREATE",
        jdmContent: jdm,
      });

      harness.trackRule(rule.id);
      registered.push({ entityRoute: entity.route, entityTable: entity.tableName, rule });
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("registers a workflow-trigger rule for every entity", () => {
    expect(registered).toHaveLength(entities.length);
    for (const item of registered) {
      expect(item.rule.id).toBeTruthy();
    }
  });

  for (const entity of entities) {
    describe(entity.displayName, () => {
      it("emits a trigger-workflow action on create", async () => {
        const outcome = await evaluate(
          harness.client,
          entity.tableName,
          "CREATE",
          { action: "create", id: "evaluation-probe" }
        );

        expect(hasAction(outcome.results, "trigger-workflow")).toBe(true);
      });

      it("names the workflow in the action config", async () => {
        const outcome = await evaluate(harness.client, entity.tableName, "CREATE", {
          action: "create",
        });

        const trigger = collectActions(outcome.results).find(
          (action) => action.type === "trigger-workflow"
        );

        expect(trigger).toBeTruthy();
        expect(String(trigger?.config.workflowName ?? "")).toContain(entity.tableName);
      });

      it("enqueues a workflow run when a record is created", async () => {
        const created = await harness.createWithParents(entity);
        expect(created).not.toBeNull();

        const runs = await waitForEntityRuns(
          harness.client,
          entity.tableName,
          String(created?.id),
          { timeoutMs: config.workflowTimeoutMs }
        );

        // Dispatch is asynchronous and, depending on the deployment, may be
        // handled out of process. Assert on what we can observe: either a run
        // was recorded for this record, or the workflow endpoint reports none
        // because dispatch is disabled — never a crash.
        expect(Array.isArray(runs)).toBe(true);

        for (const run of runs) {
          expect(run.entity_id ?? created?.id).toBeTruthy();
        }
      });

      it("drives its runs to a terminal state", async () => {
        const created = await harness.createWithParents(entity);
        expect(created).not.toBeNull();

        const runs = await waitForEntityRuns(
          harness.client,
          entity.tableName,
          String(created?.id),
          { timeoutMs: config.workflowTimeoutMs, requireTerminal: true }
        );

        for (const run of runs) {
          expect(isTerminal(run.status)).toBe(true);
        }
      });
    });
  }

  it("records workflow runs in the global run list", async () => {
    const runs = await listRuns(harness.client, { limit: 50 });
    expect(Array.isArray(runs)).toBe(true);
  });

  it("does not leave runs stuck in a non-terminal state", async () => {
    const runs = await listRuns(harness.client, { limit: 100 });
    const stale = runs.filter(
      (run) =>
        !isTerminal(run.status) &&
        run.created_at !== undefined &&
        Date.now() - new Date(String(run.created_at)).getTime() > 60_000
    );

    expect(stale.map((run) => `${run.workflow_name}:${run.status}`)).toEqual([]);
  });

  it("reports no runs for an unknown record", async () => {
    const runs = await runsForEntity(
      harness.client,
      entities[0]!.tableName,
      "00000000-0000-4000-8000-000000000000"
    );

    expect(runs).toEqual([]);
  });
});

/**
 * State machines — the edges the model drew, and only those.
 *
 * A state machine declares a lifecycle: which state a record starts
 * in, which moves are legal from there, and which states it can end in. The
 * backend stores those edges in `sys_workflow_transitions` and the
 * entity-access guard refuses any status write with no matching edge.
 *
 * There are two ways for that to be wrong, and both look like a working
 * application from the outside:
 *
 *   the table is empty      — every transition is allowed, because the guard
 *                             only enforces a topology it can find. A record
 *                             jumps from draft straight to approved and no rule
 *                             or workflow in between ever runs.
 *   the table disagrees     — an edge the diagram drew is missing, so a move
 *     with the model           the model calls routine is refused in production.
 *
 * So this suite checks both directions: every edge the model declared is
 * offered and accepted, and a move the model never drew is refused. It walks
 * each machine breadth-first from its initial state rather than assuming a
 * record can be created directly in the state under test.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import { config } from "../harness/config";
import {
  getEntity,
  harness,
  illegalTargetFrom,
  pathTo,
  stateMachines,
  successorsOf,
  type StateMachine,
} from "../harness";

interface TransitionRow {
  table_name: string;
  status_field: string;
  from_state: string;
  to_state: string;
  transition_name?: string | null;
}

/**
 * What `/api/workflows/transitions` actually answers on this backend: a bare
 * array, keyed the way the controller reads the row rather than the way the
 * column is named. Normalised into `TransitionRow` at the two places it is
 * read, so the assertions below name one shape.
 */
interface ServedTransition {
  tableName?: string;
  statusField?: string;
  from?: string;
  to?: string;
  transition?: string | null;
}

function normalise(rows: unknown): TransitionRow[] {
  const list = Array.isArray(rows)
    ? (rows as ServedTransition[])
    : (((rows as { data?: unknown })?.data ?? []) as ServedTransition[]);
  return list.map((row) => ({
    table_name: row.tableName ?? "",
    status_field: row.statusField ?? "",
    from_state: row.from ?? "",
    to_state: row.to ?? "",
    transition_name: row.transition ?? null,
  }));
}

/** `from→to`, the shape both the model and the API are reduced to for compare. */
function edgeKey(from: string, to: string): string {
  return `${from}→${to}`;
}

/**
 * The state a record is actually in, which is not always the one just written.
 *
 * A model's own rules and workflows may advance the status as a side effect of
 * the write: the CRM example's Lead moves itself from `qualified` straight on
 * to `converted`. Assuming the write sticks made this suite attempt an edge
 * from a state the record had already left, and read the resulting — entirely
 * correct — 403 as the guard refusing an edge the model had drawn.
 *
 * A write answers with the record it produced, so the state after a move is
 * usually already in hand. `stateOf` reads it out of whatever a create, patch
 * or read answered; `currentState` is the extra round trip, for the cases where
 * it is not — and each one of those costs the walk a request per step, which is
 * what put this suite over its timeout on the larger machines.
 */
function stateOf(payload: unknown, field: string): string | null {
  if (!payload || typeof payload !== "object") return null;
  const record = payload as Record<string, unknown>;
  const body = (record.data ?? record) as Record<string, unknown>;
  const value = body?.[field];
  return value === undefined || value === null ? null : String(value);
}

async function currentState(route: string, id: string, field: string): Promise<string | null> {
  const response = await harness.client.get<Record<string, unknown>>(`/bus/${route}/${id}`, {
    allowFailure: true,
  });
  if (!response.ok) return null;
  return stateOf(response.data, field);
}

/**
 * How long the walk may take, in milliseconds.
 *
 * The work is one create plus a short walk per edge, and every one of those
 * writes runs the entity's rules and workflows. So the cost is a property of
 * the diagram, not of this suite, and a flat ceiling means a model fails the
 * moment it draws one state too many. Scaled per edge instead, with a floor for
 * the small machines and `E2E_SUITE_TIMEOUT_MS` still the minimum.
 */
const PER_EDGE_BUDGET_MS = Number(process.env.E2E_TRANSITION_EDGE_BUDGET_MS ?? 15_000);

function walkBudget(machine: StateMachine): number {
  return Math.max(config.suiteTimeoutMs, machine.edges.length * PER_EDGE_BUDGET_MS);
}

describe("state machines", () => {
  let served: TransitionRow[] = [];
  let endpointAvailable = false;

  beforeAll(async () => {
    await harness.setup();
    const response = await harness.client.get<unknown>("/workflows/transitions", {
      allowFailure: true,
    });
    endpointAvailable = response.ok;
    served = response.ok ? normalise(response.data) : [];
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("exposes the declared transitions", () => {
    expect(endpointAvailable).toBe(true);
  });

  // A model with no state diagrams is legitimate; the suite then has nothing
  // to assert and says so rather than passing silently on an empty loop.
  it("has a state machine to drive, or declares none", () => {
    if (stateMachines.length === 0) {
      console.log("  the model declares no state machines — nothing to drive");
      return;
    }
    expect(served.length).toBeGreaterThan(0);
  });

  for (const machine of stateMachines) {
    describe(machine.entity, () => {
      const entity = getEntity(machine.entity);

      it("stores every edge the model drew", () => {
        const declared = machine.edges.map((edge) => edgeKey(edge.from, edge.to)).sort();
        const stored = served
          .filter((row) => row.table_name === machine.tableName)
          .map((row) => edgeKey(row.from_state, row.to_state))
          .sort();
        expect([...new Set(stored)]).toEqual([...new Set(declared)]);
      });

      it("stores them against the status column the guard reads", () => {
        const fields = new Set(
          served
            .filter((row) => row.table_name === machine.tableName)
            .map((row) => row.status_field)
        );
        expect([...fields]).toEqual([machine.statusField]);
      });

      it(
        "accepts every legal move, walking from the initial state",
        async () => {
          const refused: string[] = [];
          /** Edges whose start state the model's automations would not let us hold. */
          const carriedOn: string[] = [];

          for (const edge of machine.edges) {
            // Reach `edge.from` first. A machine whose initial state cannot reach
            // it has nothing to test for that edge — a disconnected diagram,
            // which the model, not this record, would have to fix.
            const approach = pathTo(machine, edge.from);
            if (approach === null) continue;

            const record = await harness.createWithParents(entity, {
              [machine.statusField]: machine.initial,
            });
            if (!record?.id) continue;

            // Where the record actually is, tracked across the walk rather than
            // re-read before every step. The model's own rules and workflows may
            // move it: the CRM example's Contract leaves `in_approval` for
            // `expiring` on its own. Once that happens the rest of the planned
            // walk is asking the guard about edges leading out of a state the
            // record is no longer in, and the 403 it rightly answers is not
            // evidence of anything.
            //
            // So the two outcomes are kept apart. A refusal of an edge the record
            // *was* correctly positioned for is a real failure and names that
            // edge. Being carried elsewhere is reported and skipped.
            let at =
              stateOf(record, machine.statusField) ??
              (await currentState(entity.route, String(record.id), machine.statusField));
            let diverted: string | null = null;
            let blocked: string | null = null;

            for (const step of approach) {
              // Carried straight to where this edge starts: the rest of the
              // planned walk is moot and the edge is testable after all.
              if (at === edge.from) break;
              if (at !== step.from) {
                diverted = `${edgeKey(edge.from, edge.to)} (carried to ${at ?? "?"})`;
                break;
              }
              const response = await harness.saveRecord(
                entity.route,
                String(record.id),
                { [machine.statusField]: step.to },
                { allowFailure: true }
              );
              if (!response.ok) {
                if (response.status === 403) {
                  blocked = `${edgeKey(step.from, step.to)} (reached while approaching ${edge.from})`;
                } else {
                  diverted = `${edgeKey(edge.from, edge.to)} (approach answered ${response.status})`;
                }
                break;
              }
              // The write answers with the record it produced, so the state
              // after the move is already here; only fall back to a read when
              // it is not.
              at =
                stateOf(response.data, machine.statusField) ??
                (await currentState(entity.route, String(record.id), machine.statusField));
            }

            if (blocked) {
              refused.push(blocked);
              continue;
            }
            if (diverted) {
              carriedOn.push(diverted);
              continue;
            }

            // And confirm it came to rest where the edge starts, rather than being
            // moved on by whatever ran on the last write.
            if (at !== edge.from) {
              carriedOn.push(`${edgeKey(edge.from, edge.to)} (landed in ${at ?? "?"})`);
              continue;
            }

            const move = await harness.saveRecord(
              entity.route,
              String(record.id),
              { [machine.statusField]: edge.to },
              { allowFailure: true }
            );
            // 403 is the guard refusing an edge the model drew — the failure this
            // test is for. Any other error is the record, not the topology.
            if (move.status === 403) refused.push(edgeKey(edge.from, edge.to));
          }

          if (carriedOn.length > 0) {
            console.log(
              `  ${machine.entity}: ${carriedOn.length} edge(s) not exercised — ` +
                `a rule or workflow moved the record on: ${carriedOn.join(", ")}`
            );
          }
          expect(refused).toEqual([]);
        },
        walkBudget(machine)
      );

      it("refuses a move the model never drew", async () => {
        const from = machine.initial || machine.edges[0]?.from;
        if (!from) return;

        const illegal = illegalTargetFrom(machine, from);
        if (!illegal) {
          // Every state is reachable from here in one step, so there is no
          // illegal move to attempt. Not a failure — a very permissive machine.
          console.log(`  ${machine.entity}: every state is legal from "${from}"`);
          return;
        }

        const record = await harness.createWithParents(entity, {
          [machine.statusField]: from,
        });
        expect(record?.id).toBeTruthy();
        if (!record?.id) return;

        // The create may itself have set the record moving; the illegal move
        // has to be attempted from wherever it settled, and `illegal` recomputed
        // for that state, or the refusal this asserts could be the right answer
        // to the wrong question.
        const settled =
          stateOf(record, machine.statusField) ??
          (await currentState(entity.route, String(record.id), machine.statusField));
        const target = settled === from ? illegal : settled ? illegalTargetFrom(machine, settled) : null;
        if (!settled || !target) {
          console.log(`  ${machine.entity}: no illegal move to attempt from "${settled ?? "?"}"`);
          return;
        }

        const response = await harness.saveRecord(
          entity.route,
          String(record.id),
          { [machine.statusField]: target },
          { allowFailure: true }
        );

        expect(response.ok).toBe(false);
        // 400, not 403. An edge the diagram never drew is a move that does not
        // exist, so asking for it is a malformed request rather than a
        // forbidden one — and the distinction is load-bearing here, because
        // topology is refused for *every* caller including the master role,
        // while 403 is what the role rules return. A 403 would say an
        // administrator lacks a permission, which is not what happened.
        expect(response.status).toBe(400);
      });

      it("leaves the record in its old state when a move is refused", async () => {
        const from = machine.initial || machine.edges[0]?.from;
        const illegal = from ? illegalTargetFrom(machine, from) : null;
        if (!from || !illegal) return;

        const record = await harness.createWithParents(entity, {
          [machine.statusField]: from,
        });
        if (!record?.id) return;

        // Compare against where the record actually settled, not what was asked
        // for — see the note on currentState.
        const settled =
          stateOf(record, machine.statusField) ??
          (await currentState(entity.route, String(record.id), machine.statusField));
        const target = settled === from ? illegal : settled ? illegalTargetFrom(machine, settled) : null;
        if (!settled || !target) return;

        await harness.saveRecord(
          entity.route,
          String(record.id),
          { [machine.statusField]: target },
          { allowFailure: true }
        );

        // A refused write that still landed would be worse than one that was
        // allowed: the guard would be reporting a state the record is not in.
        const after = await harness.client.get<Record<string, unknown>>(
          `/bus/${entity.route}/${record.id}`,
          { allowFailure: true }
        );
        if (!after.ok) return;
        const body = (after.data as { data?: Record<string, unknown> })?.data ?? after.data;
        expect(String(body?.[machine.statusField] ?? "")).toBe(settled);
      });

      it("answers which moves are legal from a given state", async () => {
        const from = machine.initial || machine.edges[0]?.from;
        if (!from) return;

        const response = await harness.client.get<unknown>(
          `/workflows/transitions?table=${machine.tableName}&from=${encodeURIComponent(from)}`,
          { allowFailure: true }
        );
        expect(response.status).toBe(200);

        const offered = normalise(response.data)
          .map((row) => row.to_state)
          .sort();
        expect([...new Set(offered)]).toEqual([...new Set(successorsOf(machine, from))].sort());
      });
    });
  }

  it("stores no transition for a table the model gave no state machine", () => {
    const modelled = new Set(stateMachines.map((machine: StateMachine) => machine.tableName));
    // A stray row here means something other than the model wrote the topology,
    // and the guard would be enforcing a lifecycle nobody declared.
    const stray = [...new Set(served.map((row) => row.table_name))].filter(
      (table) => !modelled.has(table)
    );
    expect(stray).toEqual([]);
  });
});

/**
 * Randomised workflow chaos.
 *
 * Registers cascade rules that reach across relationships, then performs
 * `E2E_RANDOM_WORKFLOW_OPS` random creates and updates against random
 * entities. The point is to exercise rule → workflow → cross-entity write
 * paths in combinations no hand-written test would enumerate, and to prove the
 * app stays consistent afterwards.
 *
 * The faker seed is fixed, so a failing run replays exactly.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import {
  buildRecord,
  buildWorkflowTriggerJdm,
  config,
  createRule,
  entities,
  type EntityMeta,
  faker,
  firstTextField,
  harness,
  isTerminal,
  listRuns,
  relationships,
  reseed,
  runsForEntity,
  type RuleRecord,
} from "../harness";

const suiteId = `e2e-chaos-${Date.now().toString(36)}`;

interface Operation {
  kind: "create" | "update";
  entity: EntityMeta;
  id?: string;
  ok: boolean;
  status: number;
}

/** Relationships we can cascade along: source holds an FK to target. */
function cascadePairs(): Array<{ from: EntityMeta; to: EntityMeta; linkField: string }> {
  const pairs: Array<{ from: EntityMeta; to: EntityMeta; linkField: string }> = [];

  for (const rel of relationships) {
    const source = entities.find((e) => e.name === rel.sourceEntity);
    const target = entities.find((e) => e.name === rel.targetEntity);
    if (!source || !target) continue;

    const linkField =
      rel.foreignKey ??
      source.fields.find((f) => f.name === `${target.route.replace(/^bus_/, "")}_id`)?.name;
    if (!linkField) continue;

    pairs.push({ from: source, to: target, linkField });
  }

  return pairs;
}

describe("randomised workflow chaos", () => {
  const operations: Operation[] = [];
  const rules: RuleRecord[] = [];

  beforeAll(async () => {
    await harness.setup();
    reseed(config.fakerSeed + 1);

    // A workflow trigger on every entity…
    for (const entity of entities) {
      const rule = await createRule(harness.client, {
        entityName: entity.tableName,
        ruleName: `${suiteId}-${entity.tableName}-any`,
        operation: "ALL",
        jdmContent: buildWorkflowTriggerJdm(entity, `${entity.tableName}-chaos-workflow`),
      });
      harness.trackRule(rule.id);
      rules.push(rule);
    }

    // …plus cascade rules that write into a related entity.
    for (const pair of cascadePairs().slice(0, 5)) {
      const textField = firstTextField(pair.from);
      if (!textField) continue;

      const rule = await createRule(harness.client, {
        entityName: pair.to.tableName,
        ruleName: `${suiteId}-${pair.to.tableName}-cascade-${pair.from.tableName}`,
        operation: "UPDATE",
        jdmContent: buildWorkflowTriggerJdm(
          pair.to,
          `${pair.to.tableName}-cascade-workflow`,
          {
            targetEntity: pair.from.tableName,
            linkField: pair.linkField,
            updateData: `{ ${textField.name}: 'cascaded-${suiteId}' }`,
          }
        ),
      });
      harness.trackRule(rule.id);
      rules.push(rule);
    }
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("registers chaos rules across the model", () => {
    expect(rules.length).toBeGreaterThanOrEqual(entities.length);
  });

  it(
    `performs ${config.randomWorkflowOps} random writes across random entities`,
    async () => {
      const ordered = harness.orderedEntities();

      for (let i = 0; i < config.randomWorkflowOps; i++) {
        const entity = faker.helpers.arrayElement(ordered);
        const doUpdate = faker.datatype.boolean() && operations.some((op) => op.ok && op.id);

        if (doUpdate) {
          const candidates = operations.filter(
            (op) => op.ok && op.id && op.entity.route === entity.route
          );
          const previous = candidates.length > 0 ? faker.helpers.arrayElement(candidates) : null;

          if (previous?.id) {
            const textField = firstTextField(entity);
            const payload = textField
              ? { [textField.name]: `chaos-${faker.string.alphanumeric(8)}` }
              : buildRecord(entity);

            const response = await harness.saveRecord(
              entity.route,
              String(previous.id),
              payload,
              { allowFailure: true }
            );

            operations.push({
              kind: "update",
              entity,
              id: previous.id,
              ok: response.ok,
              status: response.status,
            });
            continue;
          }
        }

        const created = await harness.createWithParents(entity);
        operations.push({
          kind: "create",
          entity,
          id: created?.id ? String(created.id) : undefined,
          ok: created !== null,
          status: created ? 201 : 0,
        });
      }

      expect(operations).toHaveLength(config.randomWorkflowOps);
    },
    Math.max(120_000, config.randomWorkflowOps * 3000)
  );

  it("never responds with a server error", () => {
    const serverErrors = operations.filter((op) => op.status >= 500);

    expect(
      serverErrors.map((op) => `${op.kind} ${op.entity.route} → ${op.status}`)
    ).toEqual([]);
  });

  it("succeeds on the majority of random operations", () => {
    const succeeded = operations.filter((op) => op.ok).length;

    // Some rejections are legitimate — a rule preventing a write is the system
    // working. A collapse to near-zero is not.
    expect(succeeded).toBeGreaterThan(operations.length * 0.5);
  });

  it("records workflow activity for the records it touched", async () => {
    const touched = operations.filter((op) => op.ok && op.id).slice(0, 10);

    for (const op of touched) {
      const runs = await runsForEntity(harness.client, op.entity.tableName, op.id!);
      expect(Array.isArray(runs)).toBe(true);
    }
  });

  it("leaves every observed workflow run in a terminal state", async () => {
    // Give any in-flight dispatch a moment to settle before judging it.
    await Bun.sleep(Math.min(config.workflowTimeoutMs, 5000));

    const runs = await listRuns(harness.client, { limit: 100 });
    const pending = runs.filter((run) => !isTerminal(run.status));

    // Recently-created runs are allowed to still be working.
    const stuck = pending.filter(
      (run) =>
        run.created_at !== undefined &&
        Date.now() - new Date(String(run.created_at)).getTime() > 30_000
    );

    expect(stuck.map((run) => `${run.workflow_name}:${run.status}`)).toEqual([]);
  });

  it("keeps every touched record readable afterwards", async () => {
    const touched = operations.filter((op) => op.ok && op.id).slice(-20);

    for (const op of touched) {
      const response = await harness.client.get(`/bus/${op.entity.route}/${op.id}`, {
        allowFailure: true,
      });

      // 404 is acceptable only if a cascade-delete rule removed it.
      expect([200, 404]).toContain(response.status);
    }
  });
});

/**
 * Users and roles.
 *
 * Covers the seeded role hierarchy, faker-generated user registration at
 * volume, and the access-control surface that role membership drives.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import {
  buildUser,
  config,
  faker,
  harness,
  HttpClient,
  login,
  permissions,
  register,
  reseed,
} from "../harness";

interface SysRole {
  sys_role_id: string;
  name: string;
  is_master_role?: boolean;
  [key: string]: unknown;
}

interface SysUser {
  sys_user_id: string;
  email: string;
  name?: string;
  [key: string]: unknown;
}

function rows<T>(body: unknown): T[] {
  if (Array.isArray(body)) return body as T[];
  if (body && typeof body === "object") {
    const record = body as Record<string, unknown>;
    if (Array.isArray(record.data)) return record.data as T[];
  }
  return [];
}

describe("users and roles", () => {
  const createdUsers: Array<{ email: string; password: string }> = [];

  beforeAll(async () => {
    await harness.setup();
    reseed(config.fakerSeed + 2);
  });

  afterAll(async () => {
    await harness.teardown();
  });

  it("seeds the system roles", async () => {
    const response = await harness.client.get("/sys/roles", { allowFailure: true });
    if (!response.ok) return; // route naming differs across generator versions

    const roles = rows<SysRole>(response.data);
    expect(roles.length).toBeGreaterThan(0);

    const names = roles.map((role) => String(role.name).toLowerCase());
    expect(names).toContain("administrator");
  });

  it("seeds the administrator user", async () => {
    const response = await harness.client.get("/sys/users", { allowFailure: true });
    if (!response.ok) return;

    const users = rows<SysUser>(response.data);
    const emails = users.map((user) => String(user.email).toLowerCase());

    expect(emails).toContain(config.admin.email.toLowerCase());
  });

  it("grants the administrator master access", async () => {
    const perms = await permissions(harness.client);

    expect(perms.role).toBeTruthy();
    expect(Array.isArray(perms.windows)).toBe(true);
  });

  it(
    `registers ${config.usersToCreate} faker-generated users`,
    async () => {
      let succeeded = 0;

      for (let i = 0; i < config.usersToCreate; i++) {
        const candidate = buildUser(i);
        const client = new HttpClient();
        const result = await register(client, candidate.email, candidate.password, candidate.name);

        if (result.ok) {
          succeeded += 1;
          createdUsers.push({ email: candidate.email, password: candidate.password });
        }
      }

      console.log(`    registered ${succeeded}/${config.usersToCreate} users`);
      expect(succeeded).toBeGreaterThan(0);
    },
    Math.max(60_000, config.usersToCreate * 3000)
  );

  it("signs in as a registered user", async () => {
    if (createdUsers.length === 0) return;

    const candidate = faker.helpers.arrayElement(createdUsers);
    const client = new HttpClient();
    const user = await login(client, candidate.email, candidate.password);

    expect(String(user.email).toLowerCase()).toBe(candidate.email.toLowerCase());
  });

  it("gives a fresh user narrower permissions than the administrator", async () => {
    if (createdUsers.length === 0) return;

    const candidate = createdUsers[0]!;
    const client = new HttpClient();
    await login(client, candidate.email, candidate.password);

    const theirs = await permissions(client);
    const admin = await permissions(harness.client);

    expect(theirs.isMaster).toBe(false);
    expect(theirs.windows.length).toBeLessThanOrEqual(admin.windows.length);
  });

  it("rejects duplicate registration", async () => {
    if (createdUsers.length === 0) return;

    const existing = createdUsers[0]!;
    const client = new HttpClient();
    const result = await register(client, existing.email, existing.password, "Duplicate");

    expect(result.ok).toBe(false);
  });

  it("refuses rule creation for a non-admin user", async () => {
    if (createdUsers.length === 0) return;

    const candidate = createdUsers[0]!;
    const client = new HttpClient();
    await login(client, candidate.email, candidate.password);

    const response = await client.post(
      "/rules",
      {
        entityName: "bus_probe",
        ruleName: "should-not-exist",
        operation: "ALL",
        jdmContent: "{}",
      },
      { allowFailure: true }
    );

    // Admin-only route: a non-admin must not get a 2xx.
    expect(response.ok).toBe(false);
    expect([400, 401, 403]).toContain(response.status);
  });
});

/**
 * Volume CRUD through the browser — 100,000 records on one entity.
 *
 * Every other suite answers "does this work?". This one answers "does this
 * still work when the table is not empty?", which is a different question and
 * the one that gets found in production instead of in CI. A list endpoint that
 * counts with `SELECT COUNT(*)` over an unindexed predicate, a grid that
 * renders every row it was handed, a pagination scheme that offsets its way to
 * page 2000 — all of them pass a ten-row test.
 *
 * The whole run happens inside a Chromium page that logged in through the
 * application's own form, so the numbers below are the application's: its
 * origin, its session, its dev-server proxy, its React grid. Writes go through
 * `fetch` *inside that page* rather than through form typing — see the note in
 * `harness/browser.ts` for why that is still the browser and why typing would
 * not be.
 *
 * The run is self-cleaning. Every id it creates is written to the seed manifest
 * before anything else happens, so a crash mid-run leaves `bun run clean` able
 * to finish the job, and the suite deletes them all at the end and checks the
 * table came back to the size it started at.
 *
 * Not part of the default run — it is minutes long by design. Start it with:
 *
 *   bun run test:browser-volume            # 100,000 records
 *   E2E_BROWSER_RECORDS=5000 bun run test:browser-volume
 *   bun run run.ts --browser-volume        # in sequence with everything else
 *
 * A caveat worth reading before quoting a number from this: the runner starts
 * the backend with `cargo loco start`, which is a **debug** build. That is the
 * right default — the suite's job is to catch a query that got quadratically
 * worse, and debug-vs-release does not change the shape of a curve — but it is
 * several times slower than what ships. For a figure you intend to publish,
 * start a release build yourself and attach to it:
 *
 *   (cd backend && cargo loco start --release) &
 *   bun run run.ts --browser-volume --only browser-volume --no-server
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import { join } from "node:path";
import {
  buildRecord,
  type BrowserSession,
  clearManifest,
  config,
  type EntityMeta,
  entities,
  firstTextField,
  foreignKeyFields,
  harness,
  numericFields,
  openApp,
  recordSeeded,
  reseed,
  startFrontend,
  writableFields,
} from "../harness";

const TOTAL = config.browserVolume.records;
const WRITE_BATCH = config.browserVolume.writeBatch;
const CONCURRENCY = config.browserVolume.concurrency;
const SAMPLE = config.browserVolume.sampleSize;

/** Distinguishes this run's rows from any other run's, for cleanup and filters. */
const RUN_ID = `perf-${Date.now().toString(36)}`;

/**
 * The entity to load up.
 *
 * "Any one business entity" — but not an arbitrary one. Foreign keys are the
 * problem: an entity with mandatory parents needs 100,000 parents to exist
 * first, which measures the parent's insert path instead of this one. So:
 * prefer an entity with no required foreign keys, and among those take the one
 * with the most scalar columns, since a wide row is the honest case. E2E_VOLUME_ENTITY
 * overrides all of it.
 */
function pickEntity(): EntityMeta {
  const override = process.env.E2E_VOLUME_ENTITY;
  if (override) {
    const found = entities.find(
      (entity) => entity.name === override || entity.route === override
    );
    if (!found) {
      throw new Error(
        `E2E_VOLUME_ENTITY="${override}" matches no entity. Known: ${entities
          .map((entity) => entity.route)
          .join(", ")}`
      );
    }
    return found;
  }

  const score = (entity: EntityMeta): number =>
    foreignKeyFields(entity).filter((field) => field.required).length * -1000 +
    writableFields(entity).length;

  return [...entities].sort((a, b) => score(b) - score(a))[0]!;
}

const entity = pickEntity();
const marker = firstTextField(entity);
const numeric = numericFields(entity)[0];

/** Wall-clock timing for one named phase. */
interface Phase {
  name: string;
  ms: number;
  ops: number;
  /** Individual operation latencies, when the phase measured them. */
  samples?: number[];
}

const phases: Phase[] = [];
const createdIds: string[] = [];

let session: BrowserSession;
let stopFrontend: Awaited<ReturnType<typeof startFrontend>> = null;
let baselineTotal = 0;

async function timed<T>(name: string, ops: number, work: () => Promise<T>): Promise<T> {
  const started = performance.now();
  const result = await work();
  phases.push({ name, ms: performance.now() - started, ops });
  return result;
}

function percentile(sorted: number[], p: number): number {
  if (sorted.length === 0) return 0;
  const index = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
  return sorted[index]!;
}

function ms(value: number): string {
  return value < 1000 ? `${value.toFixed(0)}ms` : `${(value / 1000).toFixed(1)}s`;
}

/** `meta.total` for the entity, which is what the grid's pager reads. */
async function totalRows(): Promise<number> {
  const response = await session.apiFetch<{ meta?: { total?: number } }>(
    `/bus/${entity.route}?limit=1`
  );
  return response.data?.meta?.total ?? 0;
}

/** One run's worth of payloads, marked so they can be found again. */
function payloadsFor(offset: number, count: number): Array<Record<string, unknown>> {
  return Array.from({ length: count }, (_unused, index) => {
    const record = buildRecord(entity, { uniqueSalt: `${RUN_ID}-${offset + index}` });
    if (marker) {
      record[marker.name] = `${RUN_ID}-${offset + index}`;
    }
    return record;
  });
}

describe(`volume CRUD via the browser — ${entity.displayName}`, () => {
  beforeAll(async () => {
    reseed();
    stopFrontend = await startFrontend(join(import.meta.dir, "..", "..", "frontend"));
    session = await openApp();
    baselineTotal = await totalRows();

    console.log(`\n  Entity:        ${entity.displayName} (${entity.route})`);
    console.log(`  Records:       ${TOTAL.toLocaleString("en")}`);
    console.log(`  Batch/conc.:   ${WRITE_BATCH} per wave, ${CONCURRENCY} in flight`);
    console.log(`  Baseline rows: ${baselineTotal.toLocaleString("en")}\n`);
  }, config.browserVolume.setupTimeoutMs);

  afterAll(async () => {
    await session?.close();
    await stopFrontend?.stop();
  });

  it(
    `inserts ${TOTAL.toLocaleString("en")} records`,
    async () => {
      await timed("insert", TOTAL, async () => {
        for (let offset = 0; offset < TOTAL; offset += WRITE_BATCH) {
          const size = Math.min(WRITE_BATCH, TOTAL - offset);
          const requests = payloadsFor(offset, size).map((body) => ({
            path: `/bus/${entity.route}`,
            method: "POST",
            body,
          }));

          const results = await session.apiBatch<{ id?: string }>(requests, CONCURRENCY);
          for (const result of results) {
            if (result.ok && result.data?.id) createdIds.push(result.data.id);
          }

          // Record as we go, not at the end: a run killed at record 60,000
          // should still be cleanable, and a manifest written only on success
          // is a manifest that never exists when it is needed.
          if (createdIds.length % (WRITE_BATCH * 20) === 0 || offset + size >= TOTAL) {
            await recordSeeded(entity.route, createdIds, {
              fakerSeed: config.fakerSeed,
              recordsPerEntity: TOTAL,
            });
            const done = offset + size;
            process.stdout.write(
              `\r  inserted ${done.toLocaleString("en")}/${TOTAL.toLocaleString("en")}   `
            );
          }
        }
        process.stdout.write("\n");
      });

      expect(createdIds.length).toBe(TOTAL);
      expect(await totalRows()).toBe(baselineTotal + TOTAL);
    },
    config.browserVolume.insertTimeoutMs
  );

  it(
    "lists, paginates and filters at volume",
    async () => {
      await timed("list first page", 1, () =>
        session.apiFetch(`/bus/${entity.route}?page=1&limit=50`)
      );

      // The page a user reaches by holding the "next" button, which is where an
      // OFFSET-based pager stops being free.
      const deepPage = Math.max(1, Math.floor((baselineTotal + TOTAL) / 50) - 1);
      await timed("list deep page", 1, () =>
        session.apiFetch(`/bus/${entity.route}?page=${deepPage}&limit=50`)
      );

      await timed("count only", 1, () => session.apiFetch(`/bus/${entity.route}?limit=1`));

      if (marker) {
        // `filter.<column>=<op>:<value>` — the shape `ad-list-shell` builds from
        // the grid's column filters, so this measures the query a user's filter
        // actually produces rather than one invented for the test.
        const exact = await timed("filter exact", 1, () =>
          session.apiFetch<{ meta?: { total?: number } }>(
            `/bus/${entity.route}?filter.${marker.name}=eq:${encodeURIComponent(`${RUN_ID}-0`)}`
          )
        );
        expect(exact.status).toBe(200);
        expect(exact.data?.meta?.total).toBe(1);

        const partial = await timed("filter contains", 1, () =>
          session.apiFetch<{ meta?: { total?: number } }>(
            `/bus/${entity.route}?filter.${marker.name}=contains:${encodeURIComponent(RUN_ID)}&limit=50`
          )
        );
        expect(partial.data?.meta?.total).toBe(TOTAL);

        await timed("search substring", 1, () =>
          session.apiFetch(`/bus/${entity.route}?search=${encodeURIComponent(RUN_ID)}&limit=50`)
        );
      }

      if (numeric) {
        await timed("sort by column", 1, () =>
          session.apiFetch(`/bus/${entity.route}?sort=${numeric.name}&order=desc&limit=50`)
        );
      }
    },
    config.browserVolume.phaseTimeoutMs
  );

  it(
    "renders the grid with the table loaded",
    async () => {
      // The one phase that goes through the UI rather than through fetch: a
      // backend that answers a list call in 40ms and a grid that then spends
      // eight seconds laying it out are the same experience to a user, and only
      // this measures the second half.
      const started = performance.now();
      await session.page.goto(`${config.origin}/${entity.route}`, {
        waitUntil: "domcontentloaded",
      });
      await session.page.waitForSelector("table tbody tr", {
        timeout: config.browserVolume.phaseTimeoutMs,
      });
      phases.push({ name: "grid first row (UI)", ms: performance.now() - started, ops: 1 });

      const rows = await session.page.locator("table tbody tr").count();
      expect(rows).toBeGreaterThan(0);
      // A grid that put all 100,000 rows in the DOM is a bug, not a fast path.
      expect(rows).toBeLessThan(1000);

      // Leave the grid before the phases that issue thousands of requests. The
      // list route keeps refetching, and its requests compete for the same
      // handful of connections the browser allows per origin — which both
      // distorts the latency figures below and makes a stall far likelier.
      await session.page.goto(`${config.origin}/dashboard`, { waitUntil: "domcontentloaded" });
    },
    config.browserVolume.phaseTimeoutMs
  );

  it(
    `reads, updates and re-reads ${SAMPLE} records`,
    async () => {
      const sample = createdIds.slice(0, SAMPLE);

      const readLatencies: number[] = [];
      const versions = new Map<string, number>();
      await timed("read by id", sample.length, async () => {
        for (const id of sample) {
          const started = performance.now();
          const response = await session.apiFetch<Record<string, unknown>>(
            `/bus/${entity.route}/${id}`
          );
          readLatencies.push(performance.now() - started);
          expect(response.status).toBe(200);
          // What the update below names in If-Match, as a screen would.
          const version = response.data?.version;
          if (typeof version === "number") versions.set(id, version);
        }
      });
      phases[phases.length - 1]!.samples = [...readLatencies].sort((a, b) => a - b);

      const updateLatencies: number[] = [];
      await timed("update (PATCH)", sample.length, async () => {
        for (const [index, id] of sample.entries()) {
          const body: Record<string, unknown> = marker
            ? { [marker.name]: `${RUN_ID}-updated-${index}` }
            : { version: undefined };
          const started = performance.now();
          const version = versions.get(id);
          const response = await session.apiFetch(`/bus/${entity.route}/${id}`, {
            method: "PATCH",
            body,
            headers: version === undefined ? {} : { "If-Match": `"v${version}"` },
          });
          updateLatencies.push(performance.now() - started);
          expect(response.ok).toBe(true);
        }
      });
      phases[phases.length - 1]!.samples = [...updateLatencies].sort((a, b) => a - b);

      if (marker) {
        const check = await session.apiFetch<Record<string, unknown>>(
          `/bus/${entity.route}/${sample[0]}`
        );
        expect(check.data?.[marker.name]).toBe(`${RUN_ID}-updated-0`);
      }
    },
    config.browserVolume.phaseTimeoutMs
  );

  it(
    "deletes every record it created and leaves the table as it found it",
    async () => {
      await timed("delete", createdIds.length, async () => {
        for (let offset = 0; offset < createdIds.length; offset += WRITE_BATCH) {
          const batch = createdIds.slice(offset, offset + WRITE_BATCH);
          await session.apiBatch(
            batch.map((id) => ({ path: `/bus/${entity.route}/${id}`, method: "DELETE" })),
            CONCURRENCY
          );
          process.stdout.write(
            `\r  deleted ${Math.min(offset + batch.length, createdIds.length).toLocaleString(
              "en"
            )}/${createdIds.length.toLocaleString("en")}   `
          );
        }
        process.stdout.write("\n");
      });

      // The point of the assertion: not "delete answered 204" but "the rows are
      // gone from the view every other part of the app reads".
      expect(await totalRows()).toBe(baselineTotal);
      await clearManifest();

      report();
    },
    config.browserVolume.insertTimeoutMs
  );
});

/**
 * The performance summary.
 *
 * Printed once, at the end, from data collected as the run went — so a phase
 * that failed still shows the phases that came before it in the failure output.
 */
function report(): void {
  const line = "─".repeat(78);
  console.log(`\n${line}`);
  console.log(`  PERFORMANCE — ${entity.displayName} @ ${TOTAL.toLocaleString("en")} records`);
  console.log(line);
  console.log(
    `  ${"phase".padEnd(24)}${"ops".padStart(9)}${"elapsed".padStart(11)}` +
      `${"ops/sec".padStart(11)}${"p50".padStart(8)}${"p95".padStart(8)}${"p99".padStart(8)}`
  );
  console.log(line);

  for (const phase of phases) {
    const perSecond = phase.ops > 0 && phase.ms > 0 ? (phase.ops / phase.ms) * 1000 : 0;
    const sorted = phase.samples ?? [];
    const cell = (value: number): string => (sorted.length > 0 ? ms(value) : "–");
    console.log(
      `  ${phase.name.padEnd(24)}${phase.ops.toLocaleString("en").padStart(9)}` +
        `${ms(phase.ms).padStart(11)}${(perSecond >= 1 ? perSecond.toFixed(0) : perSecond.toFixed(2)).padStart(11)}` +
        `${cell(percentile(sorted, 50)).padStart(8)}${cell(percentile(sorted, 95)).padStart(8)}` +
        `${cell(percentile(sorted, 99)).padStart(8)}`
    );
  }

  const total = phases.reduce((sum, phase) => sum + phase.ms, 0);
  console.log(line);
  console.log(`  ${"total".padEnd(24)}${"".padStart(9)}${ms(total).padStart(11)}`);
  console.log(line);
  console.log(
    "  Measured against whichever backend was listening. `bun run test:e2e`\n" +
      "  starts a debug build — compare runs, do not quote them."
  );
  console.log(`${line}\n`);
}

/** Referenced so an unused-import lint cannot fire on a harness re-export. */
void harness;

/**
 * Multi-step workflows triggered by a business rule.
 *
 * The chain under test, end to end:
 *
 *   write a record  →  rule fires `trigger-workflow`  →  the workflow runs
 *     step 1  stage a value into a workflow variable
 *     step 2  compute a second variable from the first
 *     step 3  CREATE a row in another entity, capturing its id
 *     step 4  CREATE a second row in that entity, capturing its id
 *     step 5  UPDATE the record that triggered the workflow
 *     step 6  UPDATE the row created in step 3, using both the captured id and
 *             the computed value
 *     step 7  DELETE the row created in step 4, by its captured id
 *
 * That covers what a multi-step workflow has to get right: ordering,
 * create/update/delete against an entity other than the triggering one, and
 * values carried from one step into a later one. A workflow that could not
 * carry a created row's id forward could only ever touch the record it
 * started from.
 *
 * The suite also pins the negative case: a rule-triggered definition must NOT
 * run when its rule does not fire. Definitions used to be auto-run purely on
 * entity + operation, so a workflow gated on a condition ran regardless of it.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import { sleep } from "bun";
import {
  buildRecord,
  buildWorkflowBpmn,
  createRule,
  createWorkflowDefinition,
  deleteWorkflowDefinition,
  entities,
  foreignKeyFields,
  harness,
  isFailure,
  isTerminal,
  runNameOf,
  runsForEntity,
  updateRule,
  type EntityMeta,
  type FieldMeta,
  type WorkflowRun,
  type WorkflowStep,
} from "../harness";

const suiteId = `ms${Date.now().toString(36).slice(-5)}`;

/**
 * Writable text columns the workflow can stamp a value into.
 *
 * Wide enough to hold the suite's marker strings — a `varchar(8)` column would
 * truncate them and turn every assertion into a mystery.
 */
function stampableFields(entity: EntityMeta): FieldMeta[] {
  return entity.fields.filter(
    (field) =>
      !field.isForeignKey &&
      !field.name.endsWith("_id") &&
      field.name !== "id" &&
      (field.type === "string" || field.type === "text") &&
      (field.maxLength === undefined || field.maxLength >= 24)
  );
}

/**
 * Pick a trigger entity and a different target entity.
 *
 * The target needs two writable columns: one holds the marker that identifies
 * the rows this suite created, the other receives the computed value. Reusing a
 * single column would erase the marker the assertions look the rows up by.
 *
 * Returns null when the model has no such pair, so the suite skips rather than
 * asserting against a shape this model does not have.
 */
function pickPair(): { trigger: EntityMeta; target: EntityMeta } | null {
  const target = entities.find((entity) => stampableFields(entity).length >= 2);
  if (!target) return null;
  const trigger = entities.find(
    (entity) => entity.tableName !== target.tableName && stampableFields(entity).length >= 1
  );
  return trigger ? { trigger, target } : null;
}

const pair = pickPair();

describe("multi-step workflows triggered by rules", () => {
  const registered: { ruleId?: string; definitionId?: string } = {};
  let triggerEntity: EntityMeta;
  let targetEntity: EntityMeta;
  let triggerField: FieldMeta;
  /** Carries the suite marker, so the rows the workflow created can be found. */
  let targetMarker: FieldMeta;
  /** Receives the value computed by steps 1–2. */
  let targetValue: FieldMeta;
  let workflowName: string;
  let setupFailure: string | null = null;

  beforeAll(async () => {
    if (!pair) return;
    await harness.setup();

    triggerEntity = pair.trigger;
    targetEntity = pair.target;
    triggerField = stampableFields(triggerEntity)[0]!;
    [targetMarker, targetValue] = stampableFields(targetEntity) as [FieldMeta, FieldMeta];
    workflowName = `${suiteId}-escalation`;

    try {
      const keptFields = await buildTargetPayload("kept");
      const doomedFields = await buildTargetPayload("doomed");

      const steps: WorkflowStep[] = [
        {
          id: "s1_stage",
          name: "Stage a value",
          props: { nodeType: "Formula", target: "stagedNumber", operation: "set", value: "6" },
        },
        {
          id: "s2_compute",
          name: "Compute from the staged value",
          props: {
            nodeType: "Formula",
            target: "computedNumber",
            source: "stagedNumber",
            operation: "multiply",
            operand: "7",
          },
        },
        {
          id: "s3_create_kept",
          name: `Create a ${targetEntity.displayName}`,
          props: {
            nodeType: "CreateEntity",
            entity: targetEntity.tableName,
            as: "keptId",
            fields: JSON.stringify(keptFields),
          },
        },
        {
          id: "s4_create_doomed",
          name: `Create a ${targetEntity.displayName} to retire`,
          props: {
            nodeType: "CreateEntity",
            entity: targetEntity.tableName,
            as: "doomedId",
            fields: JSON.stringify(doomedFields),
          },
        },
        {
          id: "s5_update_self",
          name: "Update the triggering record",
          props: {
            nodeType: "UpdateEntity",
            field: triggerField.name,
            value: `${suiteId}-touched`,
          },
        },
        {
          id: "s6_update_other",
          name: "Write the computed value onto the created row",
          props: {
            nodeType: "UpdateEntity",
            entity: targetEntity.tableName,
            targetSource: "keptId",
            field: targetValue.name,
            source: "computedNumber",
          },
        },
        {
          id: "s7_delete_other",
          name: "Retire the second created row",
          props: {
            nodeType: "DeleteEntity",
            entity: targetEntity.tableName,
            targetSource: "doomedId",
          },
        },
      ];

      const definition = await createWorkflowDefinition(harness.client, {
        name: workflowName,
        entityName: triggerEntity.tableName,
        operation: "CREATE",
        bpmnXml: buildWorkflowBpmn(`${suiteId}_process`, steps),
        description: "E2E: multi-step rule-triggered workflow",
        // Reached only through the rule, so the rule is what decides.
        triggerType: "rule",
      });
      registered.definitionId = definition.id;

      const rule = await createRule(harness.client, {
        entityName: triggerEntity.tableName,
        ruleName: `${suiteId}-trigger`,
        operation: "CREATE",
        jdmContent: buildTriggerJdm(workflowName),
      });
      registered.ruleId = rule.id;
      harness.trackRule(rule.id);
    } catch (error) {
      // Surface the reason in a failing assertion instead of an opaque
      // beforeAll crash that takes every test in the file with it.
      setupFailure = error instanceof Error ? error.message : String(error);
    }
  });

  afterAll(async () => {
    if (registered.definitionId) {
      await deleteWorkflowDefinition(harness.client, registered.definitionId);
    }
    await harness.teardown();
  });

  it.skipIf(!pair)("registers a rule-triggered definition", () => {
    expect(setupFailure).toBeNull();
    expect(registered.definitionId).toBeTruthy();
    expect(registered.ruleId).toBeTruthy();
  });

  it.skipIf(!pair)("runs the whole chain on a matching write", async () => {
    const created = await harness.createWithParents(triggerEntity, {
      [triggerField.name]: `${suiteId}-source`,
    });
    const triggerId = created?.id as string;
    expect(triggerId).toBeTruthy();

    const run = await waitForOurRun(triggerId);
    expect(run).not.toBeNull();
    expect(isFailure(run?.status)).toBe(false);

    // Step 5 — the triggering record was updated by its own workflow.
    const self = await readRecord(triggerEntity, triggerId);
    expect(String(self?.[triggerField.name])).toBe(`${suiteId}-touched`);

    // And the create response already says so. The workflow runs inside the
    // request, so the row the caller is handed must be the row it left behind:
    // it used to be the row as inserted, one `version` behind, and a client
    // acting on it — a form, a conditional update — acted on a state the
    // record no longer had.
    expect(String(created?.[triggerField.name])).toBe(`${suiteId}-touched`);
    expect(created?.version).toBe(self?.version);
  });

  it.skipIf(!pair)("carries a computed value into a row an earlier step created", async () => {
    const rows = await listTargetRows();
    const kept = rows.find((row) => String(row[targetMarker.name]) === `${suiteId}-kept`);

    // Step 3 created it; step 6 found it again by the id step 3 captured and
    // wrote `computedNumber` — which step 2 derived from what step 1 staged:
    // 6 * 7 = 42. Nothing else in the chain could have produced that value.
    expect(kept).toBeDefined();
    expect(String(kept?.[targetValue.name])).toBe("42");
  });

  it.skipIf(!pair)("deletes a row a later step targeted by captured id", async () => {
    const rows = await listTargetRows();
    const doomed = rows.find((row) => String(row[targetMarker.name]) === `${suiteId}-doomed`);

    // The delete is soft, so dropping out of the list is the observable effect.
    expect(doomed).toBeUndefined();
  });

  it.skipIf(!pair)("does not run when the rule does not fire", async () => {
    // Deactivating the rule has the same shape as its condition evaluating
    // false: no `trigger-workflow` action is emitted for this write.
    await updateRule(harness.client, registered.ruleId!, { isActive: false });

    try {
      const before = (await listTargetRows()).length;
      const created = await harness.createWithParents(triggerEntity, {
        [triggerField.name]: `${suiteId}-nomatch`,
      });
      const triggerId = created?.id as string;
      expect(triggerId).toBeTruthy();
      await sleep(2000);

      const runs = await ourRuns(triggerId);
      const after = (await listTargetRows()).length;

      // A rule-triggered definition must not be auto-run on entity + operation.
      expect(runs.length).toBe(0);
      expect(after).toBe(before);
    } finally {
      await updateRule(harness.client, registered.ruleId!, { isActive: true });
    }
  });

  /**
   * A create payload for the target entity, as the literal field map the
   * CreateEntity steps insert. Built through the same factory the CRUD suites
   * use, so it stays valid for whatever this model is.
   */
  async function buildTargetPayload(stamp: string): Promise<Record<string, unknown>> {
    const foreignKeys: Record<string, string> = {};
    for (const fk of foreignKeyFields(targetEntity)) {
      const parent = harness.resolveParentEntity(fk.name, fk.references);
      if (!parent) continue;
      const id = await harness.anyRecordId(parent);
      if (id) foreignKeys[fk.name] = id;
    }

    const record = buildRecord(targetEntity, {
      requiredOnly: true,
      foreignKeys,
      uniqueSalt: `${suiteId}${stamp}`,
      overrides: { [targetMarker.name]: `${suiteId}-${stamp}` },
    });

    // The executor writes these values straight into the column — it does not
    // go through the API's serialisation — so structured values have to arrive
    // as text the driver can store.
    for (const [key, value] of Object.entries(record)) {
      if (value !== null && typeof value === "object") record[key] = JSON.stringify(value);
    }
    return record;
  }

  /**
   * Runs of *this* suite's workflow. Filtering by name matters: the generator
   * also seeds automatic definitions per entity, and those produce runs of
   * their own against the same record.
   */
  async function ourRuns(triggerId: string): Promise<WorkflowRun[]> {
    const runs = await runsForEntity(harness.client, triggerEntity.tableName, triggerId);
    return runs.filter((run) => runNameOf(run) === workflowName);
  }

  async function waitForOurRun(triggerId: string): Promise<WorkflowRun | null> {
    const deadline = Date.now() + 20_000;
    let last: WorkflowRun | null = null;
    while (Date.now() < deadline) {
      const [run] = await ourRuns(triggerId);
      if (run) {
        last = run;
        if (isTerminal(run.status)) return run;
      }
      await sleep(400);
    }
    return last;
  }

  async function readRecord(
    entity: EntityMeta,
    id: string
  ): Promise<Record<string, unknown> | null> {
    const response = await harness.client.get<Record<string, unknown>>(
      `/bus/${entity.route}/${id}`,
      { allowFailure: true }
    );
    if (!response.ok) return null;
    const body = response.data as Record<string, unknown> | undefined;
    return (body?.data as Record<string, unknown>) ?? body ?? null;
  }

  /**
   * The rows this suite's workflow created, found by the marker it stamps.
   *
   * Filtered server-side rather than paged through: the bulk-seed suite leaves
   * thousands of rows behind, and a fixed `limit` would quietly stop containing
   * the rows under test as the database fills up.
   */
  async function listTargetRows(): Promise<Array<Record<string, unknown>>> {
    const response = await harness.client.get<{ data?: Array<Record<string, unknown>> }>(
      `/bus/${targetEntity.route}?limit=100&filter.${targetMarker.name}=contains:${suiteId}`,
      { allowFailure: true }
    );
    return response.ok ? (response.data?.data ?? []) : [];
  }
});

/** A decision graph whose only row emits `trigger-workflow` naming one workflow. */
function buildTriggerJdm(workflowName: string): string {
  return JSON.stringify({
    nodes: [
      { id: "input", type: "inputNode", name: "Input", position: { x: 0, y: 0 } },
      {
        id: "trigger-table",
        type: "decisionTableNode",
        name: "Multi-step trigger",
        position: { x: 300, y: 0 },
        content: {
          hitPolicy: "collect",
          inputs: [{ id: "i1", name: "Record", field: "" }],
          outputs: [
            { id: "o1", name: "Action", field: "action" },
            { id: "o2", name: "Message", field: "message" },
            { id: "o3", name: "Rule ID", field: "ruleId" },
            { id: "o4", name: "Workflow Name", field: "workflowName" },
          ],
          rules: [
            {
              _id: `${workflowName}-row`,
              i1: "true",
              o1: "'trigger-workflow'",
              o2: "'Multi-step workflow triggered'",
              o3: `'${workflowName}'`,
              o4: `'${workflowName}'`,
            },
          ],
        },
      },
      { id: "output", type: "outputNode", name: "Output", position: { x: 600, y: 0 } },
    ],
    edges: [
      { id: "e1", sourceId: "input", targetId: "trigger-table" },
      { id: "e2", sourceId: "trigger-table", targetId: "output" },
    ],
  });
}

/**
 * Read performance against whatever volume the run seeded.
 *
 * Runs last, so the tables are as full as this run will make them. Each phase
 * is one query shape repeated enough times for a p99 to be an observation
 * rather than a guess, and every sample lands in the same report as the writes.
 *
 * The point is the shape of the curve, not the absolute milliseconds. A laptop
 * and a CI box will disagree about every number here; what neither can hide is
 * a phase whose cost grows in step with the row count, because that is a scan
 * where an index was expected.
 *
 * Which is why the entity benchmarked is the one with the most rows: a phase
 * measured against a hundred rows tells you nothing about a hundred thousand.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import { config, entities, firstTextField, harness, scalarFields, timed } from "../harness";

/** Repetitions per phase. 30 is enough for a median and a believable p95. */
const REPS = Number(process.env.E2E_BENCH_REPS ?? 30);

/** Page size the phases read with — a realistic screenful, not a whole table. */
const PAGE = 25;

interface ListResponse {
  data: Array<Record<string, unknown>>;
  meta: { total: number; page?: number; limit?: number };
}

describe("read benchmark", () => {
  /** The entity with the most rows, and a text column to filter on. */
  let target: (typeof entities)[number] | null = null;
  let total = 0;
  let textField: string | null = null;
  let sortField: string | null = null;
  /** A value known to exist, so the filter phases match rather than miss. */
  let exactValue: string | null = null;

  beforeAll(async () => {
    await harness.setup();

    // Ask each entity how many rows it has and benchmark the largest. The
    // count is one request per entity and is not itself measured.
    let best = -1;
    for (const entity of entities) {
      const response = await harness.client.get<ListResponse>(
        `/bus/${entity.route}?page=1&limit=1`,
        { allowFailure: true }
      );
      if (!response.ok) continue;
      const rows = Number(response.data?.meta?.total ?? 0);
      if (rows > best) {
        best = rows;
        target = entity;
      }
    }

    total = Math.max(best, 0);
    if (!target) return;

    textField = firstTextField(target)?.name ?? null;
    sortField = scalarFields(target)[0]?.name ?? null;

    if (textField) {
      const sample = await harness.client.get<ListResponse>(
        `/bus/${target.route}?page=1&limit=1`,
        { allowFailure: true }
      );
      const value = sample.data?.data?.[0]?.[textField];
      if (typeof value === "string" && value.length > 0) exactValue = value;
    }

    console.log(
      `\n  benchmarking ${target.displayName}: ${total} rows, ${REPS} reps per phase\n`
    );
  });

  afterAll(async () => {
    await harness.teardown();
  });

  /** Run one phase `REPS` times. Skips cleanly when the data cannot support it. */
  async function phase(name: string, path: () => string): Promise<number> {
    let ok = 0;
    for (let index = 0; index < REPS; index++) {
      const response = await timed(name, () =>
        harness.client.get<ListResponse>(path(), { allowFailure: true })
      );
      if (response.ok) ok++;
    }
    return ok;
  }

  it("has a populated entity to measure", () => {
    expect(target).not.toBeNull();
    // Under `--fast` the bulk seed is skipped and only the CRUD fixtures exist.
    // The phases still run; they just describe a small table.
    expect(total).toBeGreaterThan(0);
  });

  it("list first page", async () => {
    if (!target) return;
    const ok = await phase("list first page", () => `/bus/${target!.route}?page=1&limit=${PAGE}`);
    expect(ok).toBe(REPS);
  });

  // The one phase whose work genuinely grows with the table: the last page sits
  // behind every row before it. Sublinear growth here means the pager is not
  // walking them one at a time.
  it("list deep page", async () => {
    if (!target) return;
    const lastPage = Math.max(1, Math.floor(total / PAGE));
    const ok = await phase(
      "list deep page",
      () => `/bus/${target!.route}?page=${lastPage}&limit=${PAGE}`
    );
    expect(ok).toBe(REPS);
  });

  it("count only", async () => {
    if (!target) return;
    const ok = await phase("count only", () => `/bus/${target!.route}?page=1&limit=1`);
    expect(ok).toBe(REPS);
  });

  it("sort by column", async () => {
    if (!target || !sortField) return;
    const ok = await phase(
      "sort by column",
      () => `/bus/${target!.route}?page=1&limit=${PAGE}&orderBy=${sortField}&orderDir=asc`
    );
    expect(ok).toBe(REPS);
  });

  it("filter exact", async () => {
    if (!target || !textField || !exactValue) return;
    const encoded = encodeURIComponent(exactValue);
    const ok = await phase(
      "filter exact",
      () => `/bus/${target!.route}?limit=${PAGE}&filter.${textField}=equals:${encoded}`
    );
    expect(ok).toBe(REPS);
  });

  // Contains and search are the two that cannot use a plain B-tree index, so
  // they are the ones to watch as the table grows.
  it("filter contains", async () => {
    if (!target || !textField || !exactValue) return;
    const needle = encodeURIComponent(exactValue.slice(0, Math.min(5, exactValue.length)));
    const ok = await phase(
      "filter contains",
      () => `/bus/${target!.route}?limit=${PAGE}&filter.${textField}=contains:${needle}`
    );
    expect(ok).toBe(REPS);
  });

  it("search substring", async () => {
    if (!target || !exactValue) return;
    const needle = encodeURIComponent(exactValue.slice(0, Math.min(5, exactValue.length)));
    const ok = await phase(
      "search substring",
      () => `/bus/${target!.route}?limit=${PAGE}&search=${needle}`
    );
    expect(ok).toBe(REPS);
  });

  it("records the volume it measured", () => {
    // Printed rather than asserted: the number is the run's context, and
    // failing on it would make a small run look broken.
    console.log(`  measured against ${total} ${target?.displayName ?? "?"} rows`);
    expect(config.recordsPerEntity).toBeGreaterThan(0);
  });
});

/**
 * Performance budgets.
 *
 * `10-benchmark` measures and reports; nothing there fails. That is the right
 * shape for a number that depends on the machine — a laptop and a CI runner
 * will never agree on milliseconds, and a suite that asserts on them is a suite
 * people learn to ignore.
 *
 * What *is* worth failing on is a query whose cost grows with the table. A
 * missing index does not show up as "slow" on a seeded run of ten rows; it
 * shows up as the deep page costing twenty times the first one, and as the
 * filtered read costing far more than the unfiltered one that returns the same
 * page size. Those are ratios, and a ratio survives the change of machine that
 * an absolute millisecond does not.
 *
 * So the assertions here are shape assertions with deliberately loose bounds,
 * plus one very generous absolute ceiling to catch an application that is not
 * slow-in-proportion but simply broken. Every bound is env-overridable, and the
 * suite reports what it measured either way.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import { entities, firstTextField, harness, scalarFields } from "../harness";

/** Samples per shape. Enough for a median to mean something, cheap enough to run. */
const REPS = Number(process.env.E2E_BUDGET_REPS ?? 15);

/** Page size — a screenful, matching what the benchmark suite reads. */
const PAGE = 25;

/**
 * The absolute ceiling, per request, in milliseconds. Set high on purpose: it
 * is here to catch a read that has stopped working, not to police a slow disk.
 */
const CEILING_MS = Number(process.env.E2E_BUDGET_CEILING_MS ?? 5000);

/**
 * How much more the last page may cost than the first. A pager that walks every
 * preceding row to reach the deep page blows past this on any real volume; one
 * that uses the index does not.
 */
const DEEP_PAGE_RATIO = Number(process.env.E2E_BUDGET_DEEP_PAGE_RATIO ?? 12);

/**
 * How much more a filtered read may cost than an unfiltered one returning the
 * same number of rows. A filter served by a scan grows with the table; one
 * served by an index does not.
 */
const FILTER_RATIO = Number(process.env.E2E_BUDGET_FILTER_RATIO ?? 15);

/** Below this many rows the ratios are noise, so they are reported not asserted. */
const MIN_ROWS_FOR_RATIOS = Number(process.env.E2E_BUDGET_MIN_ROWS ?? 200);

interface ListResponse {
  data: Array<Record<string, unknown>>;
  meta: { total: number };
}

interface Sample {
  median: number;
  p95: number;
  max: number;
  ok: number;
}

function percentile(sorted: number[], fraction: number): number {
  if (sorted.length === 0) return 0;
  const index = Math.min(sorted.length - 1, Math.floor(sorted.length * fraction));
  return sorted[index] ?? 0;
}

describe("performance budgets", () => {
  let target: (typeof entities)[number] | null = null;
  let total = 0;
  let textField: string | null = null;
  let sortField: string | null = null;
  let exactValue: string | null = null;

  const measured = new Map<string, Sample>();

  beforeAll(async () => {
    await harness.setup();

    // Measure whichever entity this run made the biggest — a budget checked
    // against the smallest table in the model would never fail.
    let best = -1;
    for (const entity of entities) {
      const response = await harness.client.get<ListResponse>(
        `/bus/${entity.route}?page=1&limit=1`,
        { allowFailure: true }
      );
      if (!response.ok) continue;
      const rows = Number(response.data?.meta?.total ?? 0);
      if (rows > best) {
        best = rows;
        target = entity;
      }
    }
    total = Math.max(best, 0);
    if (!target) return;

    textField = firstTextField(target)?.name ?? null;
    sortField = scalarFields(target)[0]?.name ?? null;

    if (textField) {
      const sample = await harness.client.get<ListResponse>(`/bus/${target.route}?page=1&limit=1`, {
        allowFailure: true,
      });
      const value = sample.data?.data?.[0]?.[textField];
      if (typeof value === "string" && value.length > 0) exactValue = value;
    }
  });

  afterAll(async () => {
    await harness.teardown();
    if (measured.size === 0) return;
    console.log(`\n  budgets measured against ${total} ${target?.displayName ?? "?"} rows`);
    for (const [name, sample] of measured) {
      console.log(
        `    ${name.padEnd(22)} median ${sample.median.toFixed(1)}ms  ` +
          `p95 ${sample.p95.toFixed(1)}ms  max ${sample.max.toFixed(1)}ms`
      );
    }
    console.log("");
  });

  /**
   * Time one request shape `REPS` times. Deliberately *not* routed through the
   * metrics collector: this suite must not move the numbers the benchmark
   * report publishes, or the report would describe the budget run as well.
   */
  async function measure(name: string, path: () => string): Promise<Sample> {
    const timings: number[] = [];
    let ok = 0;
    for (let index = 0; index < REPS; index++) {
      const started = performance.now();
      const response = await harness.client.get<ListResponse>(path(), { allowFailure: true });
      timings.push(performance.now() - started);
      if (response.ok) ok++;
    }
    const sorted = [...timings].sort((a, b) => a - b);
    const sample: Sample = {
      median: percentile(sorted, 0.5),
      p95: percentile(sorted, 0.95),
      max: sorted[sorted.length - 1] ?? 0,
      ok,
    };
    measured.set(name, sample);
    return sample;
  }

  it("has a populated entity to measure", () => {
    expect(target).not.toBeNull();
    expect(total).toBeGreaterThan(0);
  });

  it("serves the first page inside the ceiling", async () => {
    if (!target) return;
    const sample = await measure("first page", () => `/bus/${target!.route}?page=1&limit=${PAGE}`);
    expect(sample.ok).toBe(REPS);
    expect(sample.p95).toBeLessThan(CEILING_MS);
  });

  it("serves a single record inside the ceiling", async () => {
    if (!target) return;
    const first = await harness.client.get<ListResponse>(`/bus/${target.route}?page=1&limit=1`, {
      allowFailure: true,
    });
    const id = first.data?.data?.[0]?.id;
    if (typeof id !== "string") return;

    const sample = await measure("single record", () => `/bus/${target!.route}/${id}`);
    expect(sample.ok).toBe(REPS);
    expect(sample.p95).toBeLessThan(CEILING_MS);
  });

  it("serves a count inside the ceiling", async () => {
    if (!target) return;
    const sample = await measure("count", () => `/bus/${target!.route}?page=1&limit=1`);
    expect(sample.ok).toBe(REPS);
    expect(sample.p95).toBeLessThan(CEILING_MS);
  });

  // The scaling assertion. The deep page returns the same PAGE rows as the
  // first one; the only difference is how many rows the database had to pass
  // over to find them.
  it("reaches a deep page without walking the table", async () => {
    if (!target) return;
    const lastPage = Math.max(1, Math.floor(total / PAGE));
    const first = measured.get("first page") ?? (await measure("first page", () => `/bus/${target!.route}?page=1&limit=${PAGE}`));
    const deep = await measure(
      "deep page",
      () => `/bus/${target!.route}?page=${lastPage}&limit=${PAGE}`
    );

    expect(deep.ok).toBe(REPS);
    expect(deep.p95).toBeLessThan(CEILING_MS);

    if (total < MIN_ROWS_FOR_RATIOS || lastPage === 1) {
      console.log(`  ${total} rows — too few to judge deep-page scaling, reporting only`);
      return;
    }
    // Guard against a sub-millisecond baseline making the ratio meaningless.
    const baseline = Math.max(first.median, 1);
    expect(deep.median / baseline).toBeLessThan(DEEP_PAGE_RATIO);
  });

  it("sorts by an indexed column inside the ceiling", async () => {
    if (!target || !sortField) return;
    const sample = await measure(
      "sorted page",
      () => `/bus/${target!.route}?page=1&limit=${PAGE}&orderBy=${sortField}&orderDir=asc`
    );
    expect(sample.ok).toBe(REPS);
    expect(sample.p95).toBeLessThan(CEILING_MS);
  });

  it("filters without scanning the table", async () => {
    if (!target || !textField || !exactValue) return;
    const encoded = encodeURIComponent(exactValue);
    const first = measured.get("first page");
    const sample = await measure(
      "filtered page",
      () => `/bus/${target!.route}?limit=${PAGE}&filter.${textField}=equals:${encoded}`
    );

    expect(sample.ok).toBe(REPS);
    expect(sample.p95).toBeLessThan(CEILING_MS);

    if (!first || total < MIN_ROWS_FOR_RATIOS) return;
    expect(sample.median / Math.max(first.median, 1)).toBeLessThan(FILTER_RATIO);
  });

  it("searches without scanning the table", async () => {
    if (!target || !exactValue) return;
    const needle = encodeURIComponent(exactValue.slice(0, Math.min(5, exactValue.length)));
    const first = measured.get("first page");
    const sample = await measure(
      "search",
      () => `/bus/${target!.route}?limit=${PAGE}&search=${needle}`
    );

    expect(sample.ok).toBe(REPS);
    expect(sample.p95).toBeLessThan(CEILING_MS);

    if (!first || total < MIN_ROWS_FOR_RATIOS) return;
    expect(sample.median / Math.max(first.median, 1)).toBeLessThan(FILTER_RATIO);
  });

  // The dictionary is read on the way into every screen, so it is on the
  // critical path for the whole application and not just for one entity.
  it("serves the dictionary a screen needs inside the ceiling", async () => {
    if (!target) return;
    const meta = await measure("entity metadata", () => `/bus/${target!.route}/meta`);
    expect(meta.ok).toBe(REPS);
    expect(meta.p95).toBeLessThan(CEILING_MS);

    const fields = await measure("form fields", () => `/bus/${target!.route}/fields/form`);
    expect(fields.ok).toBe(REPS);
    expect(fields.p95).toBeLessThan(CEILING_MS);
  });

  it("writes a record inside the ceiling", async () => {
    if (!target) return;
    const timings: number[] = [];
    for (let index = 0; index < Math.min(REPS, 5); index++) {
      const started = performance.now();
      const record = await harness.createWithParents(target);
      timings.push(performance.now() - started);
      if (!record) return;
    }
    const sorted = [...timings].sort((a, b) => a - b);
    const sample: Sample = {
      median: percentile(sorted, 0.5),
      p95: percentile(sorted, 0.95),
      max: sorted[sorted.length - 1] ?? 0,
      ok: sorted.length,
    };
    measured.set("create (with rules)", sample);
    // A create runs the rules and workflows bound to the entity, so it is
    // allowed considerably more than a read — but not unboundedly more.
    expect(sample.p95).toBeLessThan(CEILING_MS * 2);
  });
});

/**
 * Two people, one record — optimistic locking over HTTP.
 *
 * The Rust request suite (`backend/tests/requests/concurrency.rs`) proves the
 * same contract in-process; this one walks it as a client does, with a
 * readable transcript when it fails: read, save, be refused, overwrite,
 * refresh — and a record in a final state refusing every save.
 *
 * Generated: {{now}}
 * Project: {{project.name}}
 */

import { beforeAll, describe, expect, it } from "bun:test";
import { entities, firstTextField, getEntity, harness, stateMachines } from "../harness";

type Row = Record<string, unknown>;

interface Meta {
  concurrency?: "optimistic" | "last-write-wins";
}

const ifMatch = (row: Row | null | undefined): Record<string, string> =>
  typeof row?.version === "number" ? { "If-Match": `"v${row.version}"` } : {};

beforeAll(async () => {
  await harness.setup();
});

/** The first optimistic entity with a text column to edit. */
async function optimisticEntity() {
  for (const entity of entities) {
    const field = firstTextField(entity);
    if (!field) continue;
    const meta = await harness.client.get<Meta>(`/bus/${entity.route}/meta`, { allowFailure: true });
    if (meta.ok && meta.data?.concurrency !== "last-write-wins") return { entity, field };
  }
  return null;
}

describe("optimistic locking", () => {
  it("refuses a stale save with the record as it stands, then accepts the overwrite", async () => {
    const target = await optimisticEntity();
    if (!target) return; // a model with no text column anywhere has nothing to edit
    const { entity, field } = target;

    const read = await harness.createWithParents(entity);
    expect(read?.id).toBeTruthy();
    const url = `/bus/${entity.route}/${read?.id}`;

    const first = await harness.client.patch<Row>(
      url,
      { [field.name]: `first-${Date.now()}` },
      { headers: ifMatch(read) }
    );
    expect(first.status).toBe(200);

    const stale = await harness.client.patch<Row>(
      url,
      { [field.name]: `second-${Date.now()}` },
      { headers: ifMatch(read), allowFailure: true }
    );
    expect(stale.status).toBe(409);
    const refusal = stale.data as Row & { error: string; conflict: Row };
    expect(refusal.error).toBe("VERSION_CONFLICT");
    expect(refusal.conflict.currentVersion).toBe(first.data.version);
    expect((refusal.conflict.current as Row)[field.name]).toBe(first.data[field.name]);
    expect(refusal.conflict.overwritable).toBe(true);

    const mine = `overwrite-${Date.now()}`;
    const overwrite = await harness.client.patch<Row>(
      url,
      { [field.name]: mine },
      { headers: ifMatch(refusal.conflict.current as Row) }
    );
    expect(overwrite.status).toBe(200);

    const refreshed = await harness.client.get<Row>(url);
    expect(refreshed.data[field.name]).toBe(mine);
    expect(refreshed.headers.get("etag")).toBe(`"v${overwrite.data.version}"`);
  });

  it("refuses an update that names no version", async () => {
    const target = await optimisticEntity();
    if (!target) return;
    const read = await harness.createWithParents(target.entity);
    expect(read?.id).toBeTruthy();

    const blind = await harness.client.patch(
      `/bus/${target.entity.route}/${read?.id}`,
      { [target.field.name]: `blind-${Date.now()}` },
      { allowFailure: true }
    );
    expect(blind.status).toBe(428);
  });
});

const closing = stateMachines.find((machine) => machine.terminal.length > 0);

describe.if(Boolean(closing))("a record in a final state", () => {
  it("is closed to every save, and says so", async () => {
    const machine = closing!;
    const entity = getEntity(machine.entity);
    const finalState = machine.terminal[0]!;
    const read = await harness.createWithParents(entity, { [machine.statusField]: finalState });
    expect(read?.id).toBeTruthy();
    const url = `/bus/${entity.route}/${read?.id}`;

    for (const headers of [ifMatch(read), { "If-Match": "*" }]) {
      const response = await harness.client.patch(
        url,
        { [machine.statusField]: finalState },
        { headers, allowFailure: true }
      );
      expect(response.status).toBe(409);
      const body = response.data as { error: string; conflict: Row };
      expect(body.error).toBe("RECORD_FINAL");
      expect(body.conflict.overwritable).toBe(false);
      expect((body.conflict.status as Row).isFinal).toBe(true);
    }
  });
});

