    ],
    "statusVocabulary": {
      "compiled": "A generator reads this key and it changes the generated application. `consumedBy` names the file that reads it.",
      "validated": "No generator compiles it, but the schema and the checker enforce its shape and cross-references, so a malformed one fails validation rather than being silently ignored.",
      "reserved": "Documented and validated for shape, with no reader. Writing one is legal and inert; the key is held so a later meaning cannot collide with it."
    }
  },
