/chat-deepseek/gateway/application.ts:
/**
 * The generated application, as the gateway speaks to it: always with the
 * signed-in person's own token, never with a service account. Every answer has
 * therefore already passed the application's three authorisation gates
 * (`sys_access`, the model's `rbac` operations, workflow transitions); the
 * gateway adds no data access of its own and needs none.
 */

export class ApplicationError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string
  ) {
    super(message);
    this.name = "ApplicationError";
  }
}

export interface ApplicationUser {
  pid: string;
  email: string;
  name: string;
  role: string | null;
}

export interface SignedIn {
  token: string;
  user: ApplicationUser;
  /** The application's own `Set-Cookie` for its session, relayed to the browser. */
  setCookie: string | null;
}

/** One entity the person may read, as the dashboard describes it. */
export interface EntityEntry {
  table: string;
  windowName: string;
  description: string;
  /** The front-end route of its window, e.g. `/sales-order`. Null for a line item. */
  route: string | null;
}

export interface Dashboard {
  isMaster: boolean;
  role: string | null;
  entities: EntityEntry[];
}

export interface ColumnMeta {
  column_name: string;
  name: string;
  is_key: boolean;
  is_identifier: boolean;
  is_updateable: boolean;
  sys_reference_id: number;
}

export interface EntityMeta {
  table: string;
  columns: ColumnMeta[];
  lifecycle: { statusField: string; finals: string[] } | null;
}

export interface TransactionStatus {
  field: string;
  value: string;
  label: string;
  isFinal: boolean;
}

type Json = Record<string, unknown>;

export class ApplicationClient {
  constructor(private readonly apiUrl: string) {}

  private async request(path: string, init: RequestInit & { token?: string } = {}): Promise<{ status: number; body: any; headers: Headers }> {
    const headers = new Headers(init.headers);
    headers.set("accept", "application/json");
    if (init.body !== undefined) headers.set("content-type", "application/json");
    if (init.token) headers.set("authorization", `Bearer ${init.token}`);
    let response: Response;
    try {
      response = await fetch(`${this.apiUrl}${path}`, { ...init, headers, redirect: "manual" });
    } catch (error) {
      throw new ApplicationError(502, "APPLICATION_UNREACHABLE", `The application could not be reached: ${(error as Error).message}`);
    }
    const text = await response.text();
    let body: any = null;
    if (text) {
      try {
        body = JSON.parse(text);
      } catch {
        body = { message: text.slice(0, 300) };
      }
    }
    return { status: response.status, body, headers: response.headers };
  }

  private fail(status: number, body: any, fallback: string): never {
    const message =
      (typeof body?.message === "string" && body.message) ||
      (typeof body?.error === "string" && body.error) ||
      fallback;
    const code =
      status === 401 ? "UNAUTHENTICATED" : status === 403 ? "FORBIDDEN" : status === 404 ? "NOT_FOUND" : "APPLICATION_ERROR";
    throw new ApplicationError(status, code, message);
  }

  /** Check a password with the application, and receive its token. */
  async signIn(email: string, password: string): Promise<SignedIn> {
    const { status, body, headers } = await this.request("/auth/login", {
      method: "POST",
      body: JSON.stringify({ email, password }),
    });
    if (status !== 200 || typeof body?.token !== "string") {
      this.fail(status === 200 ? 502 : status, body, "The email or password was not accepted.");
    }
    return {
      token: body.token,
      user: {
        pid: String(body.user?.pid ?? ""),
        email: String(body.user?.email ?? email),
        name: String(body.user?.name ?? email),
        role: typeof body.user?.role === "string" ? body.user.role : null,
      },
      setCookie: headers.get("set-cookie"),
    };
  }

  async currentUser(token: string): Promise<ApplicationUser> {
    const { status, body } = await this.request("/auth/me", { token });
    if (status !== 200) this.fail(status, body, "The application session has ended.");
    return {
      pid: String(body.user?.pid ?? ""),
      email: String(body.user?.email ?? ""),
      name: String(body.user?.name ?? ""),
      role: typeof body.user?.role === "string" ? body.user.role : null,
    };
  }

  /** The entities this person may read — the same answer their dashboard gets. */
  async dashboard(token: string): Promise<Dashboard> {
    const { status, body } = await this.request("/me/dashboard", { token });
    if (status !== 200) this.fail(status, body, "The application did not describe what you may see.");
    const entities: EntityEntry[] = [];
    for (const group of (body?.data ?? []) as Json[]) {
      for (const table of (group.entities ?? []) as Json[]) {
        const windowName = String(table.window_name ?? table.name ?? table.table_name);
        entities.push({
          table: String(table.table_name),
          windowName,
          description: String(table.window_help ?? table.window_description ?? table.description ?? ""),
          // `entityHref` in the generated front end: the window name, lower-cased, spaces to dashes.
          route: table.window_name ? `/${String(table.window_name).toLowerCase().replace(/\s+/g, "-")}` : null,
        });
      }
    }
    return { isMaster: body?.isMaster === true, role: typeof body?.role === "string" ? body.role : null, entities };
  }

  async meta(token: string, table: string): Promise<EntityMeta> {
    const { status, body } = await this.request(`/bus/${encodeURIComponent(table)}/meta`, { token });
    if (status !== 200) this.fail(status, body, `The application did not describe ${table}.`);
    const lifecycle = body?.lifecycle;
    return {
      table,
      columns: (body?.columns ?? []) as ColumnMeta[],
      // `services::dictionary::Lifecycle`, serialised as written: snake_case.
      lifecycle:
        lifecycle && typeof lifecycle.status_field === "string"
          ? { statusField: lifecycle.status_field, finals: (lifecycle.finals ?? []).map(String) }
          : null,
    };
  }

  async search(
    token: string,
    table: string,
    options: { text?: string; filters?: Record<string, unknown>; page: number; pageSize: number }
  ): Promise<{ rows: Json[]; total: number }> {
    const query = new URLSearchParams({ page: String(options.page), limit: String(options.pageSize) });
    if (options.text) query.set("search", options.text);
    for (const [column, value] of Object.entries(options.filters ?? {})) {
      if (!/^[a-z_][a-z0-9_]*$/.test(column)) {
        throw new ApplicationError(400, "INVALID_FILTER", `"${column}" is not a column name.`);
      }
      if (value === null || typeof value === "object") {
        throw new ApplicationError(400, "INVALID_FILTER", `The filter on ${column} must be a single value.`);
      }
      query.set(`filter.${column}`, `equals:${String(value)}`);
    }
    const { status, body } = await this.request(`/bus/${encodeURIComponent(table)}?${query}`, { token });
    if (status !== 200) this.fail(status, body, `The application refused the search on ${table}.`);
    return { rows: (body?.data ?? []) as Json[], total: Number(body?.meta?.total ?? 0) };
  }

  async read(token: string, table: string, id: string): Promise<{ row: Json; status: TransactionStatus | null }> {
    const { status, body } = await this.request(`/bus/${encodeURIComponent(table)}/${encodeURIComponent(id)}`, { token });
    if (status !== 200) this.fail(status, body, "The application did not return that record.");
    const transaction = body?.transactionStatus;
    return {
      row: body as Json,
      status:
        transaction && typeof transaction.field === "string"
          ? {
              field: transaction.field,
              value: String(transaction.value ?? ""),
              label: String(transaction.label ?? transaction.value ?? ""),
              isFinal: transaction.isFinal === true,
            }
          : null,
    };
  }

  /** The workflow moves drawn out of `from`; the application still decides who may make them. */
  async transitions(token: string, table: string, from: string): Promise<Array<{ to: string; label: string }>> {
    const query = new URLSearchParams({ table, from });
    const { status, body } = await this.request(`/workflows/transitions?${query}`, { token });
    if (status !== 200) this.fail(status, body, "The application did not list the workflow moves.");
    // `controllers::workflow::transitions`: a bare array of drawn edges. It is
    // topology only — whether this person may make a move is decided by the
    // application when they confirm it, and that refusal is theirs to see.
    if (!Array.isArray(body)) throw new ApplicationError(502, "APPLICATION_ERROR", "Unexpected transitions response.");
    return (body as Json[]).map((edge) => ({
      to: String(edge.to),
      label: typeof edge.transition === "string" && edge.transition ? edge.transition : String(edge.to),
    }));
  }
}

/chat-deepseek/gateway/auth.ts:
/**
 * Sign-in: one password, three sessions.
 *
 * The chat has no password store of its own. A person signs in with their
 * account in the generated application; the application checks the password
 * and answers with its token. The gateway then:
 *
 * 1. creates the chat's own Better Auth session (`chat.session_token`), which
 *    is what every chat request is authenticated by;
 * 2. keeps the application token, sealed, keyed by that session, so tools can
 *    act as the person — and relays the application's own cookie to the
 *    browser, narrowed to the application's path, so embedded screens are
 *    signed in;
 * 3. signs the person in to the reporting platform with a sixty-second,
 *    single-use Ed25519 assertion, keeps that session sealed too, and relays its
 *    cookie narrowed to the reporting path.
 *
 * Roles are not copied anywhere they could go stale: the application and the
 * reporting platform read them per request. Signing out ends all three.
 */

import { betterAuth, type BetterAuthPlugin } from "better-auth";
import { APIError, createAuthEndpoint } from "better-auth/api";
import { setSessionCookie } from "better-auth/cookies";
import { getMigrations } from "better-auth/db/migration";
import type { Kysely } from "kysely";
import type pg from "pg";
import * as z from "zod";
import { ApplicationClient, ApplicationError } from "./application";
import type { GatewayConfig } from "./config";
import { deriveKey, open, seal, signAssertion } from "./crypto";
import type { ChatDatabase } from "./db";
import type { ReportingClient } from "./reporting";

/** Set by the gateway on every request it hands to Better Auth; overwritten if a client sends it. */
export const CLIENT_IP_HEADER = "x-chat-client-ip";

export interface SessionCredentials {
  sessionId: string;
  userId: string;
  email: string;
  name: string;
  roles: string[];
  isMaster: boolean;
  appToken: string;
  reportSession: string | null;
}

interface AuthDependencies {
  config: GatewayConfig;
  pool: pg.Pool;
  db: Kysely<ChatDatabase>;
  application: ApplicationClient;
  reporting: ReportingClient | null;
}

interface CookieParts {
  name: string;
  value: string;
  maxAge: number | undefined;
}

/** Name, value and lifetime of the first cookie in a `Set-Cookie` header. */
/**
 * Split one upstream `Set-Cookie` into what `ctx.setCookie` takes.
 *
 * The value is decoded once, because `ctx.setCookie` encodes it: the reporting
 * platform's signed cookie is already percent-encoded (`…%3D`), and relayed as
 * it came it reached the browser as `…%253D` — a cookie the platform could no
 * longer verify, so every embedded report page redirected to its sign-in.
 */
export function parseSetCookie(header: string): CookieParts | null {
  const [pair, ...attributes] = header.split(";");
  const at = pair?.indexOf("=") ?? -1;
  if (!pair || at <= 0) return null;
  const maxAge = attributes
    .map((part) => part.trim())
    .find((part) => /^max-age=/i.test(part))
    ?.split("=")[1];
  const raw = pair.slice(at + 1).trim();
  let value = raw;
  try {
    value = decodeURIComponent(raw);
  } catch {
    // Not percent-encoded after all (a bare `%`): relay it as written.
  }
  return {
    name: pair.slice(0, at).trim(),
    value,
    maxAge: maxAge === undefined ? undefined : Number(maxAge),
  };
}

export function createAuth(deps: AuthDependencies) {
  const { config, db, application, reporting } = deps;
  const credentialKey = deriveKey(config.authSecret, "stored-credential");

  const applicationSignIn = {
    id: "application-sign-in",
    endpoints: {
      signInApplication: createAuthEndpoint(
        "/sign-in/application",
        {
          method: "POST",
          body: z.object({
            email: z.string().min(3).max(320),
            password: z.string().min(1).max(1024),
          }),
        },
        async (ctx) => {
          const { email, password } = ctx.body;
          let signedIn;
          try {
            signedIn = await application.signIn(email.trim(), password);
          } catch (error) {
            if (error instanceof ApplicationError && error.status === 401) {
              throw APIError.from("UNAUTHORIZED", {
                code: "INVALID_EMAIL_OR_PASSWORD",
                message: "The email or password was not accepted by the application.",
              });
            }
            throw APIError.from("SERVICE_UNAVAILABLE", {
              code: "APPLICATION_UNAVAILABLE",
              message: error instanceof Error ? error.message : "The application could not be reached.",
            });
          }
          const dashboard = await application.dashboard(signedIn.token);
          const roles = [signedIn.user.role ?? dashboard.role].filter((role): role is string => Boolean(role));

          const normalisedEmail = signedIn.user.email.toLowerCase();
          const adapter = ctx.context.internalAdapter;
          const existing = await adapter.findUserByEmail(normalisedEmail);
          const user =
            existing?.user ??
            (await adapter.createUser({
              email: normalisedEmail,
              name: signedIn.user.name,
              emailVerified: true,
            }));
          if (!user) {
            throw APIError.from("INTERNAL_SERVER_ERROR", { code: "USER_NOT_CREATED", message: "The chat could not record the account." });
          }
          const session = await adapter.createSession(user.id, false);
          if (!session) {
            throw APIError.from("INTERNAL_SERVER_ERROR", { code: "SESSION_NOT_CREATED", message: "The chat could not start a session." });
          }

          let reportSession: string | null = null;
          if (reporting && config.ssoSigningKey) {
            try {
              const assertion = signAssertion(config.ssoSigningKey, {
                email: normalisedEmail,
                name: signedIn.user.name,
                roles,
                master: dashboard.isMaster,
              });
              const report = await reporting.signInWithAssertion(assertion);
              reportSession = report.cookie;
              const parts = parseSetCookie(report.setCookie);
              if (parts) {
                ctx.setCookie(parts.name, parts.value, {
                  httpOnly: true,
                  secure: config.secureCookies,
                  sameSite: "lax",
                  path: config.reportPublicPath || "/",
                  ...(parts.maxAge === undefined ? {} : { maxAge: parts.maxAge }),
                });
              }
            } catch (error) {
              // The reporting platform being down must not keep someone out of
              // the application; the report tools say it is unavailable.
              ctx.context.logger.warn("reporting sign-in failed", { error: (error as Error).message });
            }
          }

          if (signedIn.setCookie) {
            const parts = parseSetCookie(signedIn.setCookie);
            if (parts) {
              ctx.setCookie(parts.name, parts.value, {
                httpOnly: true,
                secure: config.secureCookies,
                sameSite: "lax",
                path: config.appPublicPath || "/",
                ...(parts.maxAge === undefined ? {} : { maxAge: parts.maxAge }),
              });
            }
          }

          await db
            .insertInto("credentials")
            .values({
              session_id: session.id,
              user_id: user.id,
              email: normalisedEmail,
              name: signedIn.user.name,
              roles,
              is_master: dashboard.isMaster,
              app_token: seal(credentialKey, signedIn.token, `session:${session.id}`),
              report_token: reportSession === null ? null : seal(credentialKey, reportSession, `session:${session.id}`),
              expires_at: session.expiresAt,
            })
            .onConflict((oc) => oc.column("session_id").doNothing())
            .execute();

          await setSessionCookie(ctx, { session, user });
          return ctx.json({ user: { email: normalisedEmail, name: signedIn.user.name }, reporting: reportSession !== null });
        }
      ),
    },
    rateLimit: [{ pathMatcher: (path: string) => path === "/sign-in/application", window: 60, max: 5 }],
  } satisfies BetterAuthPlugin;

  const auth = betterAuth({
    appName: "Business chat",
    secret: config.authSecret,
    baseURL: config.publicOrigin,
    basePath: `${config.basePath}/_/auth`,
    database: deps.pool,
    trustedOrigins: [config.publicOrigin],
    emailAndPassword: { enabled: false },
    session: { expiresIn: 60 * 60 * 12, updateAge: 60 * 60 },
    advanced: {
      // The gateway writes this header itself on every request (server.ts), from
      // the socket or from a trusted proxy's X-Forwarded-For — never from the
      // client — so the sign-in rate limit counts real addresses.
      ipAddress: { ipAddressHeaders: [CLIENT_IP_HEADER] },
      cookiePrefix: "chat",
      useSecureCookies: config.secureCookies,
      defaultCookieAttributes: { path: config.basePath || "/", sameSite: "lax", httpOnly: true },
    },
    rateLimit: { enabled: true, window: 60, max: 120, storage: "memory" },
    plugins: [applicationSignIn],
  });

  async function migrate(): Promise<void> {
    const { runMigrations } = await getMigrations(auth.options);
    await runMigrations();
  }

  /** The signed-in person behind a request, with their sealed credentials opened; null when signed out. */
  async function credentialsFor(request: Request): Promise<SessionCredentials | null> {
    const session = await auth.api.getSession({ headers: request.headers });
    if (!session) return null;
    return credentialsForSession(session.session.id);
  }

  async function credentialsForSession(sessionId: string): Promise<SessionCredentials | null> {
    const row = await db.selectFrom("credentials").selectAll().where("session_id", "=", sessionId).executeTakeFirst();
    if (!row || row.expires_at.getTime() < Date.now()) return null;
    const appToken = open(credentialKey, row.app_token, `session:${sessionId}`);
    if (appToken === null) return null;
    return {
      sessionId,
      userId: row.user_id,
      email: row.email,
      name: row.name,
      roles: row.roles,
      isMaster: row.is_master,
      appToken,
      reportSession: row.report_token === null ? null : open(credentialKey, row.report_token, `session:${sessionId}`),
    };
  }

  /** The newest live credentials of a person — what a host's tool call acts with. */
  async function latestCredentialsForUser(userId: string): Promise<SessionCredentials | null> {
    const row = await db
      .selectFrom("credentials")
      .select("session_id")
      .where("user_id", "=", userId)
      .where("expires_at", ">", new Date())
      .orderBy("created_at", "desc")
      .executeTakeFirst();
    return row ? credentialsForSession(row.session_id) : null;
  }

  /** End the chat session and the two it opened. Returns the `Set-Cookie` headers that clear them. */
  async function signOutEverywhere(request: Request): Promise<string[]> {
    const credentials = await credentialsFor(request);
    const cleared: string[] = [];
    const secure = config.secureCookies ? "; Secure" : "";
    if (credentials) {
      if (credentials.reportSession && reporting) await reporting.signOut(credentials.reportSession).catch(() => undefined);
      await db.deleteFrom("credentials").where("session_id", "=", credentials.sessionId).execute();
      const reportName = credentials.reportSession?.split("=")[0];
      if (reportName) cleared.push(`${reportName}=; Path=${config.reportPublicPath || "/"}; Max-Age=0; HttpOnly; SameSite=Lax${secure}`);
    }
    cleared.push(`token=; Path=${config.appPublicPath || "/"}; Max-Age=0; HttpOnly; SameSite=Lax${secure}`);
    const response = await auth.api.signOut({ headers: request.headers, asResponse: true });
    for (const header of response.headers.getSetCookie()) cleared.push(header);
    return cleared;
  }

  return { auth, migrate, credentialsFor, credentialsForSession, latestCredentialsForUser, signOutEverywhere };
}

export type GatewayAuth = ReturnType<typeof createAuth>;

/chat-deepseek/gateway/config.ts:
/**
 * The gateway's configuration, read once and checked before anything listens.
 *
 * A missing secret or a malformed URL stops the process with a sentence naming
 * the variable. There are no fallbacks for anything that protects someone: a
 * chat that starts with a default signing key is a chat anyone can sign in to.
 */

import { existsSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";

export interface GatewayConfig {
  /** Public origin and mount, e.g. `https://crm.example.com` and `/chat`. */
  publicOrigin: string;
  basePath: string;
  /** Where the browser-facing server listens. */
  host: string;
  port: number;
  /** Loopback listener for the Harness hosts' tool calls. Never published. */
  internalPort: number;
  /** The gateway's own database (sessions, view ids), and its schema. */
  databaseUrl: string;
  databaseSchema: string;
  /** Better Auth secret; also the root of the reference and credential keys. */
  authSecret: string;
  /** The generated application's API, as the gateway reaches it, and its public mount. */
  appApiUrl: string;
  appPublicPath: string;
  /** The reporting platform's API and public mount. Optional: an application can run without it. */
  reportApiUrl: string | null;
  reportPublicPath: string;
  /** Ed25519 private key (PKCS#8 PEM) the gateway signs reporting assertions with. */
  ssoSigningKey: string | null;
  /** Node, which runs each Harness host; the Harness installation, patch, skills and instructions. */
  nodeBin: string;
  dshBin: string;
  businessPatch: string;
  pluginsDir: string;
  skillsDir: string;
  agentsFile: string;
  /** Where each person's Harness home lives. */
  dataDir: string;
  /** DeepSeek, passed to hosts only. */
  deepseekApiKey: string;
  deepseekBaseUrl: string | null;
  deepseekModel: string | null;
  /** Host lifecycle. */
  hostPortRange: [number, number];
  hostIdleMinutes: number;
  hostHeapMb: number;
  maxHosts: number;
  hostStartTimeoutMs: number;
  viewTtlSeconds: number;
  secureCookies: boolean;
  /** True behind a reverse proxy that sets X-Forwarded-For; false trusts only the socket. */
  trustProxy: boolean;
}

class ConfigError extends Error {}

function required(name: string): string {
  const value = process.env[name]?.trim();
  if (!value) throw new ConfigError(`${name} is required`);
  return value;
}

function optional(name: string): string | null {
  const value = process.env[name]?.trim();
  return value ? value : null;
}

function integer(name: string, fallback: number, min: number, max: number): number {
  const raw = optional(name);
  if (raw === null) return fallback;
  const value = Number(raw);
  if (!Number.isInteger(value) || value < min || value > max) {
    throw new ConfigError(`${name} must be an integer from ${min} to ${max}, got ${raw}`);
  }
  return value;
}

function url(name: string, value: string): string {
  try {
    const parsed = new URL(value);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") throw new Error();
    return value.replace(/\/+$/, "");
  } catch {
    throw new ConfigError(`${name} must be an http(s) URL, got ${value}`);
  }
}

function mount(name: string, value: string): string {
  if (!/^\/[A-Za-z0-9._~/-]*$/.test(value)) throw new ConfigError(`${name} must be a path like /chat, got ${value}`);
  return value === "/" ? "" : value.replace(/\/+$/, "");
}

function path(name: string, value: string, mustExist: boolean): string {
  const absolute = isAbsolute(value) ? value : resolve(process.cwd(), value);
  if (mustExist && !existsSync(absolute)) throw new ConfigError(`${name} points at ${absolute}, which does not exist`);
  return absolute;
}

/**
 * Read the configuration from the environment.
 * @param packageDir - the chat-deepseek directory, for the paths it ships.
 */
export function loadConfig(packageDir: string): GatewayConfig {
  const errors: string[] = [];
  const attempt = <T>(fn: () => T): T | undefined => {
    try {
      return fn();
    } catch (error) {
      if (error instanceof ConfigError) {
        errors.push(error.message);
        return undefined;
      }
      throw error;
    }
  };

  const authSecret = attempt(() => {
    const secret = required("CHAT_AUTH_SECRET");
    if (secret.length < 32) throw new ConfigError("CHAT_AUTH_SECRET must be at least 32 characters");
    return secret;
  });
  const portRange = attempt(() => {
    const raw = optional("CHAT_HOST_PORTS") ?? "41000-41999";
    const match = /^(\d+)-(\d+)$/.exec(raw);
    const low = Number(match?.[1]);
    const high = Number(match?.[2]);
    if (!match || low < 1024 || high > 65535 || low >= high) {
      throw new ConfigError(`CHAT_HOST_PORTS must be a range like 41000-41999, got ${raw}`);
    }
    return [low, high] as [number, number];
  });

  const config = {
    publicOrigin: attempt(() => url("CHAT_PUBLIC_ORIGIN", required("CHAT_PUBLIC_ORIGIN"))),
    basePath: attempt(() => mount("CHAT_BASE_PATH", optional("CHAT_BASE_PATH") ?? "/chat")),
    host: optional("CHAT_HOST") ?? "0.0.0.0",
    port: attempt(() => integer("CHAT_PORT", 3100, 1, 65535)),
    internalPort: attempt(() => integer("CHAT_INTERNAL_PORT", 3101, 1, 65535)),
    databaseUrl: attempt(() => required("CHAT_DATABASE_URL")),
    databaseSchema: attempt(() => {
      const schema = optional("CHAT_DATABASE_SCHEMA") ?? "chat";
      if (!/^[a-z_][a-z0-9_]{0,62}$/.test(schema)) throw new ConfigError(`CHAT_DATABASE_SCHEMA must be a lowercase identifier, got ${schema}`);
      return schema;
    }),
    authSecret,
    appApiUrl: attempt(() => url("CHAT_APP_API_URL", required("CHAT_APP_API_URL"))),
    appPublicPath: attempt(() => mount("CHAT_APP_PUBLIC_PATH", optional("CHAT_APP_PUBLIC_PATH") ?? "/app")),
    reportApiUrl: attempt(() => {
      const value = optional("CHAT_REPORT_API_URL");
      return value === null ? null : url("CHAT_REPORT_API_URL", value);
    }),
    reportPublicPath: attempt(() => mount("CHAT_REPORT_PUBLIC_PATH", optional("CHAT_REPORT_PUBLIC_PATH") ?? "/report")),
    ssoSigningKey: optional("SSO_SIGNING_KEY")?.replace(/\\n/g, "\n") ?? null,
    nodeBin: optional("CHAT_NODE_BIN") ?? "node",
    dshBin: attempt(() =>
      path("CHAT_DSH_BIN", optional("CHAT_DSH_BIN") ?? `${packageDir}/node_modules/@deepseek-ai/dsh/lib/bin.js`, true)
    ),
    businessPatch: attempt(() => path("CHAT_BUSINESS_PATCH", `${packageDir}/profile/business.patch.yml`, true)),
    pluginsDir: attempt(() => path("CHAT_PLUGINS_DIR", `${packageDir}/plugins`, true)),
    skillsDir: attempt(() => path("CHAT_SKILLS_DIR", optional("CHAT_SKILLS_DIR") ?? `${packageDir}/skills`, true)),
    agentsFile: attempt(() => path("CHAT_AGENTS_FILE", optional("CHAT_AGENTS_FILE") ?? `${packageDir}/AGENTS.md`, true)),
    dataDir: attempt(() => path("CHAT_DATA_DIR", optional("CHAT_DATA_DIR") ?? `${packageDir}/.data`, false)),
    deepseekApiKey: attempt(() => required("DEEPSEEK_API_KEY")),
    deepseekBaseUrl: attempt(() => {
      const value = optional("DEEPSEEK_BASE_URL");
      return value === null ? null : url("DEEPSEEK_BASE_URL", value);
    }),
    deepseekModel: optional("CHAT_DEEPSEEK_MODEL"),
    hostPortRange: portRange,
    hostIdleMinutes: attempt(() => integer("CHAT_HOST_IDLE_MINUTES", 30, 1, 24 * 60)),
    hostHeapMb: attempt(() => integer("CHAT_HOST_HEAP_MB", 256, 96, 8192)),
    maxHosts: attempt(() => integer("CHAT_MAX_HOSTS", 0, 0, 10000)),
    hostStartTimeoutMs: attempt(() => integer("CHAT_HOST_START_TIMEOUT_MS", 60000, 5000, 600000)),
    viewTtlSeconds: attempt(() => integer("CHAT_VIEW_TTL_SECONDS", 600, 30, 86400)),
    trustProxy: optional("CHAT_TRUST_PROXY") === "1",
    secureCookies: attempt(() => {
      const origin = optional("CHAT_PUBLIC_ORIGIN");
      return origin?.startsWith("https://") ?? false;
    }),
  };

  if (errors.length > 0) {
    throw new Error(`The chat gateway cannot start:\n  - ${errors.join("\n  - ")}`);
  }
  return config as GatewayConfig;
}

/chat-deepseek/gateway/crypto.ts:
/**
 * Every secret the gateway derives, seals or signs.
 *
 * - **Keys** come from `CHAT_AUTH_SECRET` by HKDF, one per purpose, so a key
 *   leaked from one use opens nothing else.
 * - **Record references** are what the model sees instead of a record id:
 *   AES-256-GCM over `{entity, id}` bound to the person's user id as associated
 *   data. The model cannot read the id out of one, cannot forge one, and a ref
 *   minted for one person does not open for another.
 * - **Stored credentials** — the person's application token and reporting
 *   session token — are sealed the same way before they touch the database.
 * - **Reporting assertions** are Ed25519-signed, sixty seconds long and single
 *   use; the reporting platform verifies them with the public half.
 */

import {
  createCipheriv,
  createDecipheriv,
  createPrivateKey,
  hkdfSync,
  randomBytes,
  randomUUID,
  sign,
  timingSafeEqual,
} from "node:crypto";

const IV_BYTES = 12;
const TAG_BYTES = 16;

export type KeyPurpose = "record-ref" | "stored-credential" | "view-id";

export function deriveKey(secret: string, purpose: KeyPurpose): Buffer {
  return Buffer.from(hkdfSync("sha256", Buffer.from(secret, "utf8"), Buffer.alloc(0), `appwithai-chat/${purpose}`, 32));
}

/** AES-256-GCM, `iv ‖ tag ‖ ciphertext`, base64url. */
export function seal(key: Buffer, plaintext: string, associated: string): string {
  const iv = randomBytes(IV_BYTES);
  const cipher = createCipheriv("aes-256-gcm", key, iv);
  cipher.setAAD(Buffer.from(associated, "utf8"));
  const body = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
  return Buffer.concat([iv, cipher.getAuthTag(), body]).toString("base64url");
}

/** The inverse of {@link seal}; `null` for anything that was not sealed with this key for this subject. */
export function open(key: Buffer, sealed: string, associated: string): string | null {
  let raw: Buffer;
  try {
    raw = Buffer.from(sealed, "base64url");
  } catch {
    return null;
  }
  if (raw.length <= IV_BYTES + TAG_BYTES) return null;
  try {
    const decipher = createDecipheriv("aes-256-gcm", key, raw.subarray(0, IV_BYTES));
    decipher.setAAD(Buffer.from(associated, "utf8"));
    decipher.setAuthTag(raw.subarray(IV_BYTES, IV_BYTES + TAG_BYTES));
    return Buffer.concat([decipher.update(raw.subarray(IV_BYTES + TAG_BYTES)), decipher.final()]).toString("utf8");
  } catch {
    return null;
  }
}

export interface RecordTarget {
  /** The bus table, e.g. `bus_account`. */
  table: string;
  id: string;
}

const REF_PREFIX = "rec_";

export function sealRecordRef(key: Buffer, userId: string, target: RecordTarget): string {
  return REF_PREFIX + seal(key, JSON.stringify([target.table, target.id]), `ref:${userId}`);
}

export function openRecordRef(key: Buffer, userId: string, ref: string): RecordTarget | null {
  if (typeof ref !== "string" || !ref.startsWith(REF_PREFIX)) return null;
  const plain = open(key, ref.slice(REF_PREFIX.length), `ref:${userId}`);
  if (plain === null) return null;
  try {
    const [table, id] = JSON.parse(plain) as unknown[];
    if (typeof table !== "string" || typeof id !== "string") return null;
    return { table, id };
  } catch {
    return null;
  }
}

export function randomToken(bytes = 32): string {
  return randomBytes(bytes).toString("base64url");
}

/** Constant-time string equality for secrets of any length. */
export function secretEquals(a: string, b: string): boolean {
  const left = Buffer.from(a, "utf8");
  const right = Buffer.from(b, "utf8");
  return left.length === right.length && timingSafeEqual(left, right);
}

export interface Assertion {
  iss: "appwithai-chat";
  aud: "report";
  sub: string;
  name: string;
  roles: string[];
  master: boolean;
  jti: string;
  iat: number;
  exp: number;
}

/**
 * A sixty-second, single-use statement that `sub` is signed in with these roles,
 * as `base64url(payload).base64url(signature)`.
 */
export function signAssertion(
  privateKeyPem: string,
  subject: { email: string; name: string; roles: string[]; master: boolean },
  now = Date.now()
): string {
  const iat = Math.floor(now / 1000);
  const payload: Assertion = {
    iss: "appwithai-chat",
    aud: "report",
    sub: subject.email.toLowerCase(),
    name: subject.name,
    roles: subject.roles,
    master: subject.master,
    jti: randomUUID(),
    iat,
    exp: iat + 60,
  };
  const encoded = Buffer.from(JSON.stringify(payload), "utf8").toString("base64url");
  const signature = sign(null, Buffer.from(encoded, "utf8"), createPrivateKey(privateKeyPem));
  return `${encoded}.${signature.toString("base64url")}`;
}

/chat-deepseek/gateway/db.ts:
/**
 * The gateway's own tables, in a database and a schema of their own (`chat` by
 * default).
 *
 * It may share a PostgreSQL *server* with the application it serves, never its
 * database. The gateway reads business data only through the application's
 * API, as the person, so there is no path from here to a `bus_` row that skips
 * the application's authorisation — and the reverse matters as much: the
 * reporting platform introspects every schema of the database it reports on,
 * so chat sessions kept in the application's database would become rows a
 * report could select.
 *
 * Better Auth's tables (`user`, `session`, `account`, `verification`) are
 * created by its own migrator; the two below are the gateway's.
 */

import { type Generated, Kysely, PostgresDialect, sql } from "kysely";
import pg from "pg";

export interface CredentialsTable {
  /** The Better Auth session this row belongs to; ends with it. */
  session_id: string;
  user_id: string;
  email: string;
  name: string;
  roles: string[];
  is_master: boolean;
  /** The application's JWT, sealed (`stored-credential` key, bound to the session id). */
  app_token: string;
  /** The reporting platform's session token, sealed the same way; null when not signed in there. */
  report_token: string | null;
  created_at: Generated<Date>;
  expires_at: Date;
}

export interface AppViewsTable {
  /** Opaque, unguessable; what a chat node holds. */
  id: string;
  user_id: string;
  kind: "business-application" | "enterprise-report";
  /** `{ path }` inside the application, or `{ reportId, params }` for a report. */
  target: unknown;
  operation: string;
  title: string;
  expires_at: Date;
  created_at: Generated<Date>;
}

export interface ChatDatabase {
  credentials: CredentialsTable;
  app_views: AppViewsTable;
}

/**
 * Create the gateway's database when the server does not have it yet.
 *
 * A container's init scripts run once, when its volume is first created, so a
 * chat added to an application that already has a database would never get
 * one that way. Creating it here, on the server named by the URL, covers both.
 * The role in the URL needs CREATEDB for this; where it lacks it, the database
 * must be created beforehand and this does nothing.
 */
export async function ensureDatabase(databaseUrl: string): Promise<void> {
  const probe = new pg.Client({ connectionString: databaseUrl });
  try {
    await probe.connect();
    return;
  } catch (error) {
    if ((error as { code?: string }).code !== "3D000") throw error;
  } finally {
    await probe.end().catch(() => {});
  }
  const url = new URL(databaseUrl);
  const name = decodeURIComponent(url.pathname.replace(/^\//, ""));
  if (!/^[A-Za-z_][A-Za-z0-9_]{0,62}$/.test(name)) {
    throw new Error(`CHAT_DATABASE_URL names a database (${name}) this gateway will not create; create it first.`);
  }
  url.pathname = "/postgres";
  const admin = new pg.Client({ connectionString: url.toString() });
  await admin.connect();
  try {
    await admin.query(`CREATE DATABASE "${name}"`);
    console.log(`chat gateway: created database ${name}`);
  } catch (error) {
    // Another gateway starting at the same moment created it first.
    if ((error as { code?: string }).code !== "42P04") throw error;
  } finally {
    await admin.end();
  }
}

export function createPool(databaseUrl: string, schema: string): pg.Pool {
  return new pg.Pool({
    connectionString: databaseUrl,
    max: 20,
    // Every connection resolves unqualified names in the chat schema first, so
    // Better Auth's tables land there and never beside the application's.
    options: `-c search_path=${schema},public`,
  });
}

export function createDb(pool: pg.Pool): Kysely<ChatDatabase> {
  return new Kysely<ChatDatabase>({ dialect: new PostgresDialect({ pool }) });
}

/** Create the schema and the gateway's own tables. Idempotent. */
export async function migrateGatewayTables(db: Kysely<ChatDatabase>, schema: string): Promise<void> {
  await sql`CREATE SCHEMA IF NOT EXISTS ${sql.id(schema)}`.execute(db);
  await sql`
    CREATE TABLE IF NOT EXISTS ${sql.id(schema, "credentials")} (
      session_id   TEXT PRIMARY KEY,
      user_id      TEXT NOT NULL,
      email        TEXT NOT NULL,
      name         TEXT NOT NULL,
      roles        TEXT[] NOT NULL DEFAULT '{}',
      is_master    BOOLEAN NOT NULL DEFAULT FALSE,
      app_token    TEXT NOT NULL,
      report_token TEXT,
      created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
      expires_at   TIMESTAMPTZ NOT NULL
    )`.execute(db);
  await sql`CREATE INDEX IF NOT EXISTS credentials_user_idx ON ${sql.id(schema, "credentials")} (user_id)`.execute(db);
  await sql`
    CREATE TABLE IF NOT EXISTS ${sql.id(schema, "app_views")} (
      id          TEXT PRIMARY KEY,
      user_id     TEXT NOT NULL,
      kind        TEXT NOT NULL CHECK (kind IN ('business-application', 'enterprise-report')),
      target      JSONB NOT NULL,
      operation   TEXT NOT NULL,
      title       TEXT NOT NULL,
      expires_at  TIMESTAMPTZ NOT NULL,
      created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
    )`.execute(db);
  await sql`CREATE INDEX IF NOT EXISTS app_views_expiry_idx ON ${sql.id(schema, "app_views")} (expires_at)`.execute(db);
}

/** Delete expired views and orphaned credentials. Run on an interval. */
export async function sweepExpired(db: Kysely<ChatDatabase>): Promise<void> {
  // A view is kept a day past expiry so a stale node can say "expired" (410)
  // rather than "not found" (404) — the difference tells the person to re-open.
  await db.deleteFrom("app_views").where("expires_at", "<", sql<Date>`now() - interval '1 day'`).execute();
  await db.deleteFrom("credentials").where("expires_at", "<", sql<Date>`now()`).execute();
}

/chat-deepseek/gateway/hosts.ts:
/**
 * One Harness host per signed-in person.
 *
 * A host is a `dsh` process on a loopback port with its own `DSH_HOME`, so one
 * person's sessions, logs and settings are another directory from the next
 * person's, and a host that misbehaves takes down one conversation. The gateway
 * is the only thing that talks to it: it starts the host, trades the launch
 * token for the host's authentication cookie (which never reaches a browser),
 * proxies the person's chat to it, and stops it when they have been idle.
 *
 * Memory is the term that scales (see README, "Capacity"), so three things bound
 * it: each host's V8 heap is capped (`CHAT_HOST_HEAP_MB`), idle hosts are reaped
 * (`CHAT_HOST_IDLE_MINUTES`), and at most `CHAT_MAX_HOSTS` run at once — the
 * next person waits in a queue with a stated position rather than the machine
 * swapping.
 */

import { spawn, type ChildProcess } from "node:child_process";
import { existsSync } from "node:fs";
import { copyFile, mkdir, readlink, rm, symlink, writeFile } from "node:fs/promises";
import { createServer } from "node:net";
import { totalmem } from "node:os";
import { join } from "node:path";
import { randomToken } from "./crypto";
import type { GatewayConfig } from "./config";

/**
 * The largest resident memory one business host was measured at, in MiB: a
 * lone host after a turn, before any page is shared with a second
 * (`bun run load`, 2026-10-04; README, "Memory"). Its own share fell to about
 * 72 MiB from 25 hosts on. `defaultMaxHosts` takes the larger of this and 90%
 * of the heap ceiling, so with the default 256 MiB heap the ceiling is set by
 * the heap — the most one host can grow to — not by this.
 */
export const MEASURED_HOST_RSS_MB = 154;

export interface RunningHost {
  userId: string;
  port: number;
  /** `name=value` of the host's authentication cookie. */
  cookie: string;
  /** Presented by this host's tools on the internal API. */
  secret: string;
  startedAt: number;
  lastUsedAt: number;
  /** Open WebSocket streams; a host with one is never idle. */
  streams: number;
  process: ChildProcess;
}

export class CapacityError extends Error {
  constructor(readonly position: number) {
    super(`The chat is at capacity; you are number ${position} in the queue.`);
    this.name = "CapacityError";
  }
}

const PROFILE = "chat";
const LAUNCH_LINE = /dsh web: (http:\/\/127\.0\.0\.1:(\d+)\/\?token=[A-Za-z0-9_-]+)/;

export function defaultMaxHosts(heapMb: number): number {
  // Three quarters of the machine for hosts, the rest for the gateway, the
  // applications and the database; the measured RSS, not the heap cap, is
  // what a host costs.
  const perHost = Math.max(MEASURED_HOST_RSS_MB, Math.round(heapMb * 0.9));
  return Math.max(1, Math.floor((totalmem() / 2 ** 20) * 0.75 / perHost));
}

async function portIsFree(port: number): Promise<boolean> {
  return new Promise((resolve) => {
    const server = createServer();
    server.once("error", () => resolve(false));
    server.listen(port, "127.0.0.1", () => server.close(() => resolve(true)));
  });
}

export class HostManager {
  private readonly hosts = new Map<string, RunningHost>();
  private readonly starting = new Map<string, Promise<RunningHost>>();
  private readonly bySecret = new Map<string, string>();
  private readonly queue: string[] = [];
  private readonly waiters = new Map<string, Array<() => void>>();
  private readonly maxHosts: number;
  private readonly reaper: ReturnType<typeof setInterval>;

  constructor(private readonly config: GatewayConfig) {
    this.maxHosts = config.maxHosts > 0 ? config.maxHosts : defaultMaxHosts(config.hostHeapMb);
    this.reaper = setInterval(() => void this.reapIdle(), 60_000);
    this.reaper.unref();
  }

  get capacity(): number {
    return this.maxHosts;
  }

  get running(): number {
    return this.hosts.size + this.starting.size;
  }

  /** The person whose host presented this secret, or null. */
  userForSecret(secret: string): string | null {
    return this.bySecret.get(secret) ?? null;
  }

  host(userId: string): RunningHost | null {
    return this.hosts.get(userId) ?? null;
  }

  /** Position in the queue (1-based), or 0 when not waiting. */
  queuePosition(userId: string): number {
    return this.queue.indexOf(userId) + 1;
  }

  touch(userId: string): void {
    const host = this.hosts.get(userId);
    if (host) host.lastUsedAt = Date.now();
  }

  streamOpened(userId: string): void {
    const host = this.hosts.get(userId);
    if (host) host.streams += 1;
  }

  streamClosed(userId: string): void {
    const host = this.hosts.get(userId);
    if (host) {
      host.streams = Math.max(0, host.streams - 1);
      host.lastUsedAt = Date.now();
    }
  }

  /**
   * The person's host, started if needed. Throws {@link CapacityError} when the
   * ceiling is reached; the person stays queued and the next call after a slot
   * frees starts their host.
   */
  async ensure(userId: string): Promise<RunningHost> {
    const existing = this.hosts.get(userId);
    if (existing && existing.process.exitCode === null) {
      existing.lastUsedAt = Date.now();
      return existing;
    }
    const pending = this.starting.get(userId);
    if (pending) return pending;

    if (this.running >= this.maxHosts) {
      if (!this.queue.includes(userId)) this.queue.push(userId);
      throw new CapacityError(this.queuePosition(userId));
    }
    const head = this.queue[0];
    if (head !== undefined && head !== userId) {
      // Someone queued first; a freed slot is theirs.
      if (!this.queue.includes(userId)) this.queue.push(userId);
      throw new CapacityError(this.queuePosition(userId));
    }
    if (head === userId) this.queue.shift();

    const start = this.start(userId).finally(() => this.starting.delete(userId));
    this.starting.set(userId, start);
    return start;
  }

  /** Stop the person's host, e.g. at sign-out. */
  async stop(userId: string): Promise<void> {
    const host = this.hosts.get(userId);
    if (!host) return;
    this.forget(host);
    await this.terminate(host.process);
  }

  async stopAll(): Promise<void> {
    clearInterval(this.reaper);
    await Promise.all([...this.hosts.keys()].map((userId) => this.stop(userId)));
  }

  private forget(host: RunningHost): void {
    if (this.hosts.get(host.userId) === host) this.hosts.delete(host.userId);
    this.bySecret.delete(host.secret);
  }

  private async terminate(child: ChildProcess): Promise<void> {
    if (child.exitCode !== null || child.signalCode !== null) return;
    child.kill("SIGTERM");
    await new Promise<void>((resolve) => {
      const timer = setTimeout(() => {
        child.kill("SIGKILL");
        resolve();
      }, 10_000);
      child.once("exit", () => {
        clearTimeout(timer);
        resolve();
      });
    });
  }

  private async reapIdle(): Promise<void> {
    const cutoff = Date.now() - this.config.hostIdleMinutes * 60_000;
    for (const host of [...this.hosts.values()]) {
      if (host.streams === 0 && host.lastUsedAt < cutoff) await this.stop(host.userId);
    }
  }

  private homeFor(userId: string): string {
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(userId)) throw new Error("unsafe user id for a host directory");
    return join(this.config.dataDir, "hosts", userId);
  }

  /**
   * Lay out the person's Harness home: the `chat` profile on the shipped Web
   * bundles, our plugin packages linked into its `node_modules` (Harness
   * resolves a plugin name against the profile, not the installation), and the
   * business instructions as the home-level `AGENTS.md`.
   */
  async prepareHome(userId: string): Promise<{ root: string; dshHome: string; documents: string }> {
    const root = this.homeFor(userId);
    const dshHome = join(root, "dsh");
    const profile = join(dshHome, "profiles", PROFILE);
    const documents = join(root, "documents");
    await mkdir(join(profile, "node_modules", "@appwithai"), { recursive: true });
    await mkdir(documents, { recursive: true });

    await writeFile(
      join(profile, "package.json"),
      `${JSON.stringify(
        {
          name: `dsh-profile-${PROFILE}`,
          private: true,
          dependencies: {},
          dsh: { profile: { bundles: ["@deepseek-ai/dsh-base", "@deepseek-ai/dsh-web-app"] } },
        },
        null,
        2
      )}\n`
    );
    await writeFile(join(profile, "cordis.yml"), "# The business chat's profile root; composed from bundles and patches.\n[]\n");
    // The person's own patch layer stays empty: the business patch is passed as
    // `--patch`, after it, and nothing they can reach writes here.
    await writeFile(join(profile, "cordis.patch.yml"), "[]\n");

    for (const plugin of ["business-tools", "business-nodes"]) {
      const source = join(this.config.pluginsDir, plugin);
      if (!existsSync(source)) continue;
      const link = join(profile, "node_modules", "@appwithai", `chat-${plugin}`);
      const current = await readlink(link).catch(() => null);
      if (current !== source) {
        await rm(link, { force: true, recursive: true });
        await symlink(source, link, "dir");
      }
    }
    await copyFile(this.config.agentsFile, join(dshHome, "AGENTS.md"));
    return { root, dshHome, documents };
  }

  private async allocatePort(): Promise<number> {
    const [low, high] = this.config.hostPortRange;
    const used = new Set([...this.hosts.values()].map((host) => host.port));
    const span = high - low + 1;
    const offset = Math.floor(Math.random() * span);
    for (let i = 0; i < span; i++) {
      const port = low + ((offset + i) % span);
      if (!used.has(port) && (await portIsFree(port))) return port;
    }
    throw new Error(`no free port in CHAT_HOST_PORTS ${low}-${high}`);
  }

  private async start(userId: string): Promise<RunningHost> {
    const { dshHome, documents } = await this.prepareHome(userId);
    const port = await this.allocatePort();
    const secret = randomToken();
    const env: Record<string, string> = {
      PATH: process.env.PATH ?? "/usr/local/bin:/usr/bin:/bin",
      HOME: documents,
      DSH_HOME: dshHome,
      DSH_TELEMETRY_DISABLED: "1",
      NODE_OPTIONS: `--max-old-space-size=${this.config.hostHeapMb}`,
      CHAT_GATEWAY_INTERNAL_URL: `http://127.0.0.1:${this.config.internalPort}`,
      CHAT_HOST_SECRET: secret,
      CHAT_SKILLS_DIR: this.config.skillsDir,
      CHAT_DOCUMENTS_DIR: documents,
      DEEPSEEK_API_KEY: this.config.deepseekApiKey,
    };
    if (this.config.deepseekBaseUrl) env.DEEPSEEK_BASE_URL = this.config.deepseekBaseUrl;
    if (this.config.deepseekModel) env.CHAT_DEEPSEEK_MODEL = this.config.deepseekModel;

    // Harness supports Node (>= 22.19), not Bun, whatever runs the gateway.
    const child = spawn(
      this.config.nodeBin,
      [this.config.dshBin, "--profile", PROFILE, "--patch", this.config.businessPatch, "--no-open", "--port", String(port)],
      { cwd: documents, env, stdio: ["ignore", "pipe", "pipe"] }
    );

    let output = "";
    const launchUrl = await new Promise<string>((resolve, reject) => {
      const timer = setTimeout(() => {
        child.kill("SIGKILL");
        reject(new Error(`the chat host did not start within ${this.config.hostStartTimeoutMs} ms:\n${output.slice(-2000)}`));
      }, this.config.hostStartTimeoutMs);
      const onData = (chunk: Buffer) => {
        output += chunk.toString("utf8");
        const match = LAUNCH_LINE.exec(output);
        if (match) {
          clearTimeout(timer);
          resolve(match[1]!);
        }
      };
      child.stdout?.on("data", onData);
      child.stderr?.on("data", (chunk: Buffer) => {
        output += chunk.toString("utf8");
      });
      child.once("exit", (code, signal) => {
        clearTimeout(timer);
        reject(new Error(`the chat host exited before it was ready (code ${code}, signal ${signal}):\n${output.slice(-2000)}`));
      });
    });
    // Keep draining the pipes so a chatty host never blocks on a full buffer.
    child.stdout?.resume();
    child.stderr?.resume();

    // The launch token is good for one exchange, on `GET /`, for a cookie bound
    // to this authority. The gateway makes the exchange and keeps the cookie.
    const exchange = await fetch(launchUrl, { redirect: "manual" });
    const setCookie = exchange.headers.get("set-cookie");
    const cookie = setCookie?.split(";")[0]?.trim();
    if (exchange.status !== 303 || !cookie) {
      child.kill("SIGKILL");
      throw new Error(`the chat host refused its own launch token (HTTP ${exchange.status})`);
    }

    const host: RunningHost = {
      userId,
      port,
      cookie,
      secret,
      startedAt: Date.now(),
      lastUsedAt: Date.now(),
      streams: 0,
      process: child,
    };
    this.hosts.set(userId, host);
    this.bySecret.set(secret, userId);
    child.once("exit", () => {
      this.forget(host);
      this.release();
    });
    return host;
  }

  /** A slot freed: wake whoever is at the head of the queue. */
  private release(): void {
    const head = this.queue[0];
    if (head === undefined) return;
    for (const wake of this.waiters.get(head) ?? []) wake();
    this.waiters.delete(head);
  }

  /** Resolve when it is the person's turn to try again (for a waiting page's long poll). */
  waitForTurn(userId: string, timeoutMs: number): Promise<void> {
    return new Promise((resolve) => {
      const timer = setTimeout(resolve, timeoutMs);
      const list = this.waiters.get(userId) ?? [];
      list.push(() => {
        clearTimeout(timer);
        resolve();
      });
      this.waiters.set(userId, list);
    });
  }
}

/chat-deepseek/gateway/pages.ts:
/**
 * The four pages the gateway renders itself. Everything else the person sees is
 * the Harness client or the applications' own screens.
 *
 * Self-contained (no external fonts, scripts or images), readable in light and
 * dark, and usable at phone width.
 */

const escape = (value: string) =>
  value.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);

const STYLE = `
:root{--bg:#f7f8fa;--card:#ffffff;--ink:#14161a;--muted:#5d6470;--line:#dfe3e8;--accent:#2f5bd3;--accent-ink:#ffffff;--danger:#b42318}
@media (prefers-color-scheme:dark){:root{--bg:#0f1115;--card:#171a20;--ink:#e8eaee;--muted:#9aa3af;--line:#2a2f38;--accent:#7aa2ff;--accent-ink:#0f1115;--danger:#ff8a80}}
*{box-sizing:border-box}html,body{margin:0;height:100%}
body{background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;display:grid;place-items:center;padding:16px}
main{width:100%;max-width:400px;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:28px}
h1{font-size:20px;margin:0 0 4px}p{margin:0 0 16px;color:var(--muted)}
label{display:block;font-weight:600;margin:14px 0 6px}
input{width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:8px;background:transparent;color:var(--ink);font:inherit}
input:focus{outline:2px solid var(--accent);outline-offset:1px}
button,a.button{display:inline-block;margin-top:20px;width:100%;padding:10px 14px;border:0;border-radius:8px;background:var(--accent);color:var(--accent-ink);font:inherit;font-weight:600;text-align:center;text-decoration:none;cursor:pointer}
button[disabled]{opacity:.6;cursor:progress}
.error{color:var(--danger);min-height:1.5em;margin:12px 0 0}
.note{font-size:13px;margin-top:18px}
`;

function shell(title: string, body: string, script = ""): string {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(title)}</title><style>${STYLE}</style></head><body><main>${body}</main>${script ? `<script>${script}</script>` : ""}</body></html>`;
}

export function signInPage(base: string): string {
  return shell(
    "Sign in — Business chat",
    `<h1>Business chat</h1>
<p>Sign in with your account in the application. The chat, the application and its reports open together.</p>
<form id="sign-in" novalidate>
  <label for="email">Email</label>
  <input id="email" name="email" type="email" autocomplete="username" required>
  <label for="password">Password</label>
  <input id="password" name="password" type="password" autocomplete="current-password" required>
  <button type="submit">Sign in</button>
  <p class="error" id="error" role="alert"></p>
</form>
<p class="note">The assistant acts only as you: it can read what you can read and open the application's screens for you, and it never changes a record itself.</p>`,
    `const base=${JSON.stringify(base)};
const form=document.getElementById("sign-in"),error=document.getElementById("error"),button=form.querySelector("button");
form.addEventListener("submit",async(event)=>{event.preventDefault();error.textContent="";button.disabled=true;
try{const response=await fetch(base+"/_/auth/sign-in/application",{method:"POST",headers:{"content-type":"application/json"},credentials:"same-origin",
body:JSON.stringify({email:form.email.value,password:form.password.value})});
if(response.ok){location.assign(base+"/");return}
const body=await response.json().catch(()=>({}));
error.textContent=response.status===429?"Too many attempts. Wait a minute and try again.":(body.message||"Sign-in failed.");}
catch{error.textContent="The chat could not be reached."}finally{button.disabled=false}});`
  );
}

export function waitingPage(base: string, position: number): string {
  return shell(
    "Waiting — Business chat",
    `<h1>The chat is busy</h1>
<p>Every seat is taken right now. You are <strong id="position">number ${position}</strong> in the queue; this page opens the chat as soon as a seat is free.</p>`,
    `const base=${JSON.stringify(base)};
(async function wait(){try{const r=await fetch(base+"/_/queue",{credentials:"same-origin"});const b=await r.json();
if(!b.position){location.reload();return}document.getElementById("position").textContent="number "+b.position;}catch{}setTimeout(wait,1000)})();`
  );
}

export function notFoundPage(base: string): string {
  return shell(
    "Not found — Business chat",
    `<h1>Nothing here</h1><p>This link does not belong to your session, or it never existed.</p><a class="button" href="${escape(base)}/">Open the chat</a>`
  );
}

export function expiredPage(base: string, title: string): string {
  return shell(
    "Expired — Business chat",
    `<h1>This view has expired</h1><p>${escape(title)} was opened a while ago. Use <strong>Re-open</strong> on the card in the conversation to open it again.</p><a class="button" href="${escape(base)}/">Back to the chat</a>`
  );
}

/chat-deepseek/gateway/proxy.ts:
/**
 * The person's Harness host, reached through the gateway.
 *
 * Everything under the chat's mount that is not the gateway's own (`/_/…`) is
 * the Harness Web client and its API, served by the person's own host. The
 * gateway rewrites three things on the way through and nothing else:
 *
 * - **the path** — the mount is taken off; the Harness page carries
 *   `<base href="./">`, so it is correct at any prefix;
 * - **`Host` and `Origin`** — set to the host's own loopback authority, which
 *   its browser-trust fence requires and its cookie is bound to;
 * - **the cookie** — the browser's cookies are dropped and the host's
 *   authentication cookie, which only the gateway holds, is sent instead.
 *
 * And it refuses Remote calls outside {@link REMOTE_ALLOWLIST}. The composition
 * already removed every Host API over the machine; this is the second wall, and
 * it is the one that closes `workspace/create`, which would otherwise let a
 * browser make any directory a session's working directory.
 */

import type { RunningHost } from "./hosts";

/**
 * Remote namespaces the business chat uses. Each either names the methods it
 * may not use (`deny`) or, where most of the namespace is dangerous, the only
 * ones it may (`allow`).
 */
export const REMOTE_ALLOWLIST: Record<string, { deny?: string[]; allow?: string[] }> = {
  session: {},
  commands: {},
  skills: {},
  userQuestions: {},
  sessionReferenceResolver: {},
  workspace: { deny: ["create"] },
  // The client reads its display preferences here (the transcript mode that
  // keeps the application's screens unfolded). Writes stay closed: `settings`
  // edits any plugin's live configuration, the DeepSeek provider's `baseURL`
  // among them — and a repointed base URL is the server's API key sent to an
  // address the person chose.
  settings: { allow: ["describe"] },
};

/** The stream every client opens for host events; not an RPC namespace. */
const EVENT_STREAM = "$events";

/** `null` when a Remote endpoint (`namespace/method`) may be used, else why not. */
export function refuseEndpoint(endpoint: string): string | null {
  if (endpoint === EVENT_STREAM) return null;
  const match = /^([A-Za-z]+)\/([A-Za-z]+)$/.exec(endpoint);
  if (!match) return `${endpoint} is not part of the business chat`;
  const [, namespace, name] = match;
  const rule = REMOTE_ALLOWLIST[namespace!];
  if (!rule) return `${namespace} is not part of the business chat`;
  if (rule.allow && !rule.allow.includes(name!)) return `${namespace}/${name} is not available in the business chat`;
  if (rule.deny?.includes(name!)) return `${namespace}/${name} is not available in the business chat`;
  return null;
}

/**
 * Check one browser-to-host frame on `/api/remote.mux`.
 *
 * The mux carries the same Remote calls as the unary routes — a stream is
 * opened by naming an `endpoint` — so the allowlist has to hold here too, or a
 * hand-written client opens on the socket what the HTTP route refuses. The
 * frame shapes are Harness's own (`parseRemoteStreamClientMessage`): text,
 * JSON, `open` naming an endpoint, then `item`, `cancel` and `end` on a stream
 * it opened.
 *
 * `opened` is this socket's set of allowed streams; an `open` that passes is
 * added to it.
 */
export function checkMuxFrame(
  message: string | Buffer | ArrayBuffer | Uint8Array,
  opened: Set<string>
): { forward: true } | { forward: false; reply?: string; close?: string } {
  if (typeof message !== "string") return { forward: false, close: "binary frames are not part of the protocol" };
  let frame: { type?: unknown; streamId?: unknown; endpoint?: unknown };
  try {
    frame = JSON.parse(message);
  } catch {
    return { forward: false, close: "malformed frame" };
  }
  const streamId = typeof frame.streamId === "string" && frame.streamId.length > 0 ? frame.streamId : null;
  if (!streamId) return { forward: false, close: "frame without a stream" };
  if (frame.type === "open") {
    const reason = typeof frame.endpoint === "string" ? refuseEndpoint(frame.endpoint) : "open without an endpoint";
    if (reason) {
      return {
        forward: false,
        reply: JSON.stringify({ type: "error", streamId, error: { code: "FORBIDDEN", message: reason, details: {} } }),
      };
    }
    opened.add(streamId);
    return { forward: true };
  }
  if (frame.type === "item" || frame.type === "cancel" || frame.type === "end") {
    if (!opened.has(streamId)) return { forward: false };
    if (frame.type !== "item") opened.delete(streamId);
    return { forward: true };
  }
  return { forward: false, close: "unknown frame type" };
}

const REMOTE_PATH = /^\/api\/([A-Za-z]+)\/([A-Za-z]+)$/;

/** `null` when the request may pass, else the reason it may not. */
export function refuseRemote(method: string, path: string): string | null {
  if (!path.startsWith("/api/")) return null;
  if (path === "/api/remote.mux") return null;
  const match = REMOTE_PATH.exec(path);
  if (!match) {
    // Non-RPC routes. The session-log download is the one the chat keeps;
    // `/api/file?path=` is refused because it reads any absolute path through
    // the host's filesystem provider, which no part of a business chat needs.
    return path === "/api/session.export" && (method === "GET" || method === "POST")
      ? null
      : `${path} is not part of the business chat`;
  }
  const [, namespace, name] = match;
  return refuseEndpoint(`${namespace}/${name}`);
}

/** Response and request headers that do not cross a proxy. */
const HOP_BY_HOP = new Set([
  "connection",
  "keep-alive",
  "proxy-authenticate",
  "proxy-authorization",
  "te",
  "trailer",
  "transfer-encoding",
  "upgrade",
  "host",
  "cookie",
  "origin",
  "referer",
  "content-length",
]);

export function hostAuthority(host: RunningHost): string {
  return `127.0.0.1:${host.port}`;
}

/** Forward one HTTP request to the person's host. */
export async function proxyHttp(request: Request, host: RunningHost, innerPath: string): Promise<Response> {
  const url = new URL(request.url);
  const target = `http://${hostAuthority(host)}${innerPath}${url.search}`;
  const headers = new Headers();
  for (const [name, value] of request.headers) {
    if (!HOP_BY_HOP.has(name.toLowerCase())) headers.set(name, value);
  }
  headers.set("host", hostAuthority(host));
  headers.set("cookie", host.cookie);
  if (request.headers.has("origin")) headers.set("origin", `http://${hostAuthority(host)}`);
  // A same-origin request as far as the host can tell, which it is: the browser
  // is talking to the gateway, and the gateway to its own loopback host.
  headers.set("sec-fetch-site", "same-origin");

  const upstream = await fetch(target, {
    method: request.method,
    headers,
    body: request.method === "GET" || request.method === "HEAD" ? undefined : request.body,
    redirect: "manual",
    // @ts-expect-error -- Bun/undici accept `duplex` for a streamed request body.
    duplex: "half",
  });

  const responseHeaders = new Headers();
  for (const [name, value] of upstream.headers) {
    const lower = name.toLowerCase();
    // The host's own cookie stays with the gateway. `fetch` has already decoded
    // a compressed body, so its encoding header no longer describes what we send.
    if (lower === "set-cookie" || lower === "content-encoding" || HOP_BY_HOP.has(lower)) continue;
    responseHeaders.set(name, value);
  }
  return new Response(upstream.body, { status: upstream.status, statusText: upstream.statusText, headers: responseHeaders });
}

