/**
 * The reporting platform, as the gateway speaks to it: with the person's own
 * reporting session, which the gateway obtains by presenting a signed assertion
 * (`POST /api/auth/assertion`) and keeps sealed server-side.
 *
 * The platform decides what the person may run — `decideQueryRun` checks every
 * stored query against their data-source permissions at run time — so the
 * gateway never sees SQL and never runs any.
 */

import { ApplicationError } from "./application";

type Json = Record<string, unknown>;

export interface ReportSummary {
  id: string;
  name: string;
  description: string;
  savedQueryId: string | null;
}

export interface ReportPage {
  rows: Json[];
  totalRows: number;
  pageIndex: number;
  pageSize: number;
}

export interface ReportSession {
  /** The platform's session cookie, `name=value`, exactly as it set it. */
  cookie: string;
  /** The `Set-Cookie` header, relayed to the browser so embedded pages are signed in. */
  setCookie: string;
}

export class ReportingClient {
  constructor(private readonly apiUrl: string) {}

  private async request(path: string, init: RequestInit & { cookie?: string } = {}): Promise<{ status: number; body: any; headers: Headers }> {
    const headers = new Headers(init.headers);
    headers.set("accept", "application/json");
    if (init.body !== undefined) headers.set("content-type", "application/json");
    if (init.cookie) headers.set("cookie", init.cookie);
    let response: Response;
    try {
      response = await fetch(`${this.apiUrl}${path}`, { ...init, headers, redirect: "manual" });
    } catch (error) {
      throw new ApplicationError(502, "REPORTING_UNREACHABLE", `The reporting platform could not be reached: ${(error as Error).message}`);
    }
    const text = await response.text();
    let body: any = null;
    if (text) {
      try {
        body = JSON.parse(text);
      } catch {
        body = { message: text.slice(0, 300) };
      }
    }
    return { status: response.status, body, headers: response.headers };
  }

  private fail(status: number, body: any, fallback: string): never {
    const message =
      (typeof body?.error?.message === "string" && body.error.message) ||
      (typeof body?.message === "string" && body.message) ||
      (typeof body?.error === "string" && body.error) ||
      fallback;
    const code = status === 401 ? "UNAUTHENTICATED" : status === 403 ? "FORBIDDEN" : status === 404 ? "NOT_FOUND" : "REPORTING_ERROR";
    throw new ApplicationError(status, code, message);
  }

  /** Exchange a signed assertion for a reporting session. */
  async signInWithAssertion(assertion: string): Promise<ReportSession> {
    const { status, body, headers } = await this.request("/auth/assertion", {
      method: "POST",
      body: JSON.stringify({ assertion }),
    });
    const setCookie = headers.get("set-cookie");
    if (status !== 200 || !setCookie) this.fail(status === 200 ? 502 : status, body, "The reporting platform did not accept the sign-in.");
    const cookie = setCookie.split(";")[0]?.trim();
    if (!cookie || !cookie.includes("=")) throw new ApplicationError(502, "REPORTING_ERROR", "The reporting platform set no session cookie.");
    return { cookie, setCookie };
  }

  async signOut(session: string): Promise<void> {
    await this.request("/auth/sign-out", { method: "POST", cookie: session, body: "{}" });
  }

  /** Saved reports, most recent first; the platform's list is not narrowed by permission. */
  async listReports(session: string, page: number, pageSize: number): Promise<{ items: ReportSummary[]; total: number }> {
    const query = new URLSearchParams({ page: String(page), pageSize: String(pageSize) });
    const { status, body } = await this.request(`/reports?${query}`, { cookie: session });
    if (status !== 200) this.fail(status, body, "The reporting platform did not list its reports.");
    const data = body?.data ?? {};
    return {
      items: ((data.items ?? []) as Json[]).map((item) => ({
        id: String(item.id),
        name: String(item.name ?? ""),
        description: String(item.description ?? ""),
        savedQueryId: typeof item.saved_query_id === "string" ? item.saved_query_id : null,
      })),
      total: Number(data.meta?.total ?? data.meta?.totalItems ?? 0),
    };
  }

  async report(session: string, id: string): Promise<ReportSummary> {
    const { status, body } = await this.request(`/reports/${encodeURIComponent(id)}`, { cookie: session });
    if (status !== 200) this.fail(status, body, "The reporting platform did not return that report.");
    const item = (body?.data ?? {}) as Json;
    return {
      id: String(item.id ?? id),
      name: String(item.name ?? ""),
      description: String(item.description ?? ""),
      savedQueryId: typeof item.saved_query_id === "string" ? item.saved_query_id : null,
    };
  }

  /** Run a saved report, one page; refused with 403 when the person may not read its tables. */
  async run(session: string, id: string, page: number, pageSize: number): Promise<ReportPage> {
    const query = new URLSearchParams({ page: String(page), pageSize: String(pageSize) });
    const { status, body } = await this.request(`/reports/${encodeURIComponent(id)}/data?${query}`, { cookie: session });
    if (status !== 200) this.fail(status, body, "The report could not be run.");
    const data = body?.data ?? {};
    return {
      rows: (data.rows ?? []) as Json[],
      totalRows: Number(data.totalRows ?? 0),
      pageIndex: Number(data.pageIndex ?? page),
      pageSize: Number(data.pageSize ?? pageSize),
    };
  }

  /** Whether a chart is drawn from the same saved query as the report. */
  async chartFor(session: string, savedQueryId: string): Promise<string | null> {
    const { status, body } = await this.request(`/charts?${new URLSearchParams({ page: "1", pageSize: "100" })}`, { cookie: session });
    if (status !== 200) return null;
    const items = ((body?.data?.items ?? []) as Json[]).filter((item) => item.saved_query_id === savedQueryId);
    return items.length > 0 ? String(items[0]!.id) : null;
  }

  /** The platform's own export, streamed back unchanged. */
  async export(session: string, id: string, format: string): Promise<Response> {
    return fetch(`${this.apiUrl}/reports/${encodeURIComponent(id)}/export`, {
      method: "POST",
      headers: { cookie: session, "content-type": "application/json" },
      body: JSON.stringify({ format }),
      redirect: "manual",
    });
  }
}

/chat-deepseek/gateway/server.ts:
#!/usr/bin/env bun
/**
 * The business chat's gateway.
 *
 * Two listeners:
 *
 * - **Public** (`CHAT_PORT`, behind the reverse proxy at `CHAT_BASE_PATH`):
 *   the sign-in page and Better Auth (`/_/auth/*`), sign-out, the embedded-view
 *   routes the chat's nodes load (`/_/views/*`), and — for everything else —
 *   the signed-in person's own Harness host, proxied.
 * - **Internal** (`CHAT_INTERNAL_PORT`, loopback only): the tool API the
 *   person's host calls, authenticated by the secret the gateway gave it.
 *
 * Nothing on the public listener reaches a host without a chat session, and no
 * host is reachable except through this process.
 */

import { dirname, resolve } from "node:path";
import type { ServerWebSocket } from "bun";
import { ApplicationClient, ApplicationError } from "./application";
import { CLIENT_IP_HEADER, createAuth } from "./auth";
import { loadConfig } from "./config";
import { secretEquals } from "./crypto";
import { createDb, createPool, ensureDatabase, migrateGatewayTables, sweepExpired } from "./db";
import { CapacityError, HostManager, type RunningHost } from "./hosts";
import { checkMuxFrame, hostAuthority, proxyHttp, refuseRemote } from "./proxy";
import { ReportingClient } from "./reporting";
import { notFoundPage, signInPage, waitingPage } from "./pages";
import { BusinessTools, ToolRefusal } from "./tools";
import { ViewService } from "./views";

const packageDir = resolve(dirname(new URL(import.meta.url).pathname), "..");
const config = loadConfig(packageDir);
await ensureDatabase(config.databaseUrl);
const pool = createPool(config.databaseUrl, config.databaseSchema);
const db = createDb(pool);
await migrateGatewayTables(db, config.databaseSchema);

const application = new ApplicationClient(config.appApiUrl);
const reporting = config.reportApiUrl ? new ReportingClient(config.reportApiUrl) : null;
const gatewayAuth = createAuth({ config, pool, db, application, reporting });
await gatewayAuth.migrate();
const hosts = new HostManager(config);
const tools = new BusinessTools(config, db, application, reporting);
const views = new ViewService(config, db, application, reporting);

const sweeper = setInterval(() => void sweepExpired(db).catch((error) => console.error("sweep failed", error)), 10 * 60_000);
sweeper.unref();

const base = config.basePath;
const json = (status: number, body: unknown, headers: HeadersInit = {}) =>
  Response.json(body, { status, headers: { "cache-control": "no-store", ...headers } });
const html = (status: number, body: string, headers: HeadersInit = {}) =>
  new Response(body, {
    status,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store",
      "content-security-policy": "default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; frame-ancestors 'self'",
      ...headers,
    },
  });

interface SocketData {
  host: RunningHost;
  userId: string;
  protocols: string | null;
  upstream?: WebSocket;
  pending: Array<string | ArrayBufferLike | Uint8Array>;
  /** Streams this socket opened through the allowlist (`checkMuxFrame`). */
  streams: Set<string>;
}

/** The address a request came from: the socket, or the first hop a trusted proxy recorded. */
function clientIp(request: Request, server: Bun.Server<SocketData>): string {
  if (config.trustProxy) {
    const forwarded = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim();
    if (forwarded) return forwarded;
  }
  return server.requestIP(request)?.address ?? "unknown";
}

async function publicFetch(incoming: Request, server: Bun.Server<SocketData>): Promise<Response | undefined> {
  const headers = new Headers(incoming.headers);
  headers.set(CLIENT_IP_HEADER, clientIp(incoming, server));
  const request = new Request(incoming, { headers });
  const url = new URL(request.url);
  if (base && url.pathname !== base && !url.pathname.startsWith(`${base}/`)) return html(404, notFoundPage(base));
  const path = url.pathname.slice(base.length) || "/";

  // ── the gateway's own routes ──────────────────────────────────────────────
  if (path.startsWith("/_/auth/")) return gatewayAuth.auth.handler(request);

  if (path === "/_/sign-in") return html(200, signInPage(base));

  if (path === "/_/sign-out" && request.method === "POST") {
    const credentials = await gatewayAuth.credentialsFor(request);
    const cleared = await gatewayAuth.signOutEverywhere(request);
    if (credentials) await hosts.stop(credentials.userId);
    const headers = new Headers({ location: `${base}/_/sign-in`, "cache-control": "no-store" });
    for (const cookie of cleared) headers.append("set-cookie", cookie);
    return new Response(null, { status: 303, headers });
  }

  if (path === "/_/health") return json(200, { status: "ok", hosts: hosts.running, capacity: hosts.capacity });

  const credentials = await gatewayAuth.credentialsFor(request);
  if (!credentials) {
    if (path.startsWith("/api/") || path.startsWith("/_/")) return json(401, { code: "UNAUTHENTICATED", message: "Sign in to the chat first." });
    return Response.redirect(`${config.publicOrigin}${base}/_/sign-in`, 303);
  }

  if (path.startsWith("/_/views/")) return views.handle(request, path.slice("/_/views/".length), credentials);

  if (path === "/_/queue") {
    await hosts.waitForTurn(credentials.userId, 25_000);
    return json(200, { position: hosts.queuePosition(credentials.userId) });
  }

  // ── the person's Harness host ─────────────────────────────────────────────
  const refusal = refuseRemote(request.method, path);
  if (refusal) return json(403, { code: "NOT_AVAILABLE", message: refusal });

  let host: RunningHost;
  try {
    host = await hosts.ensure(credentials.userId);
  } catch (error) {
    if (error instanceof CapacityError) {
      return path.startsWith("/api/")
        ? json(503, { code: "AT_CAPACITY", position: error.position }, { "retry-after": "10" })
        : html(503, waitingPage(base, error.position), { "retry-after": "10" });
    }
    console.error("host start failed", error);
    return json(502, { code: "HOST_UNAVAILABLE", message: "The chat could not start for you. Try again in a moment." });
  }
  hosts.touch(credentials.userId);

  if (path === "/api/remote.mux" && request.headers.get("upgrade")?.toLowerCase() === "websocket") {
    // Bun upgrades only the request object it handed in.
    const upgraded = server.upgrade(incoming, {
      data: { host, userId: credentials.userId, protocols: request.headers.get("sec-websocket-protocol"), pending: [], streams: new Set() },
    });
    return upgraded ? undefined : json(400, { code: "UPGRADE_FAILED", message: "WebSocket upgrade failed." });
  }
  return proxyHttp(request, host, path);
}

const publicServer = Bun.serve<SocketData>({
  hostname: config.host,
  port: config.port,
  idleTimeout: 120,
  fetch: publicFetch,
  websocket: {
    open(socket: ServerWebSocket<SocketData>) {
      const { host } = socket.data;
      hosts.streamOpened(socket.data.userId);
      const upstream = new WebSocket(`ws://${hostAuthority(host)}/api/remote.mux`, {
        headers: { cookie: host.cookie, origin: `http://${hostAuthority(host)}`, host: hostAuthority(host) },
        ...(socket.data.protocols ? { protocols: socket.data.protocols.split(",").map((p) => p.trim()) } : {}),
      } as unknown as string[]);
      upstream.binaryType = "arraybuffer";
      socket.data.upstream = upstream;
      upstream.onopen = () => {
        for (const message of socket.data.pending.splice(0)) upstream.send(message);
      };
      upstream.onmessage = (event) => socket.send(event.data as string | ArrayBuffer);
      upstream.onclose = (event) => socket.close(event.code === 1005 ? 1000 : event.code, event.reason);
      upstream.onerror = () => socket.close(1011, "chat host stream failed");
    },
    message(socket, message) {
      const upstream = socket.data.upstream;
      hosts.touch(socket.data.userId);
      const verdict = checkMuxFrame(message, socket.data.streams);
      if (!verdict.forward) {
        if (verdict.reply) socket.send(verdict.reply);
        if (verdict.close) socket.close(1008, verdict.close);
        return;
      }
      if (upstream && upstream.readyState === WebSocket.OPEN) upstream.send(message);
      else socket.data.pending.push(message);
    },
    close(socket) {
      hosts.streamClosed(socket.data.userId);
      socket.data.upstream?.close();
    },
  },
});

// ── the internal tool API ───────────────────────────────────────────────────
const internalServer = Bun.serve({
  hostname: "127.0.0.1",
  port: config.internalPort,
  async fetch(request) {
    const url = new URL(request.url);
    const match = /^\/internal\/tools\/([a-z_]+)$/.exec(url.pathname);
    if (request.method !== "POST" || !match) return json(404, { code: "NOT_FOUND", message: "No such internal route." });
    const presented = request.headers.get("x-chat-host-secret") ?? "";
    const userId = presented ? hosts.userForSecret(presented) : null;
    const host = userId ? hosts.host(userId) : null;
    if (!userId || !host || !secretEquals(presented, host.secret)) {
      return json(401, { code: "UNKNOWN_HOST", message: "This host was not started by the gateway." });
    }
    hosts.touch(userId);
    const who = await gatewayAuth.latestCredentialsForUser(userId);
    if (!who) return json(401, { code: "SESSION_ENDED", message: "The person is no longer signed in to the chat." });
    let args: Record<string, unknown>;
    try {
      args = (await request.json()) as Record<string, unknown>;
    } catch {
      return json(400, { code: "INVALID_JSON", message: "The tool arguments were not JSON." });
    }
    try {
      return json(200, await tools.handle(match[1]!, args, who));
    } catch (error) {
      if (error instanceof ToolRefusal) return json(error.status, { code: error.code, message: error.message });
      if (error instanceof ApplicationError) return json(error.status, { code: error.code, message: error.message });
      console.error(`tool ${match[1]} failed`, error);
      return json(500, { code: "TOOL_FAILED", message: "The tool failed unexpectedly." });
    }
  },
});

console.log(
  `chat gateway: ${config.publicOrigin}${base}/ (listening on ${publicServer.hostname}:${publicServer.port}; ` +
    `tools on 127.0.0.1:${internalServer.port}; up to ${hosts.capacity} hosts)`
);

const shutdown = async () => {
  publicServer.stop();
  internalServer.stop();
  await hosts.stopAll();
  await pool.end();
  process.exit(0);
};
process.on("SIGTERM", () => void shutdown());
process.on("SIGINT", () => void shutdown());

/chat-deepseek/gateway/tools.ts:
/**
 * The eight business tools, on the gateway side.
 *
 * A host's tool call arrives on the internal listener with that host's secret;
 * the secret names the person, and their newest live credentials are what the
 * call acts with. Every read goes to the application or the reporting platform
 * *as that person*. What comes back to the model is shaped here, and three
 * things never appear in it: a record id (records are named by sealed refs), a
 * URL, and a credential.
 */

import { ApplicationClient, ApplicationError, type EntityEntry, type EntityMeta, type TransactionStatus } from "./application";
import type { SessionCredentials } from "./auth";
import type { GatewayConfig } from "./config";
import { deriveKey, openRecordRef, randomToken, sealRecordRef, type RecordTarget } from "./crypto";
import type { ChatDatabase } from "./db";
import type { ReportingClient } from "./reporting";
import type { Kysely } from "kysely";

type Json = Record<string, unknown>;

export class ToolRefusal extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string
  ) {
    super(message);
    this.name = "ToolRefusal";
  }
}

export interface ViewDescriptor {
  type: "business-application";
  applicationViewId: string;
  title: string;
  operation: "view" | "create" | "update" | "transition";
  entity: string;
  expiresAt: string;
}

/** Columns the model never needs: identity, bookkeeping, and raw references. */
const HIDDEN_COLUMNS = new Set(["id", "version", "created_by", "updated_by", "deleted_at", "is_deleted"]);
const ENTITY_CACHE_MS = 60_000;

function humanise(value: string): string {
  const spaced = value.replace(/[_-]+/g, " ").trim();
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
}

export class BusinessTools {
  private readonly refKey: Buffer;
  private readonly entityCache = new Map<string, { at: number; entities: EntityEntry[] }>();
  private readonly metaCache = new Map<string, { at: number; meta: EntityMeta }>();

  constructor(
    private readonly config: GatewayConfig,
    private readonly db: Kysely<ChatDatabase>,
    private readonly application: ApplicationClient,
    private readonly reporting: ReportingClient | null
  ) {
    this.refKey = deriveKey(config.authSecret, "record-ref");
  }

  async handle(operation: string, args: Json, who: SessionCredentials): Promise<unknown> {
    try {
      switch (operation) {
        case "search_records":
          return await this.searchRecords(args, who);
        case "get_record_summary":
          return await this.recordSummary(args, who);
        case "open_record":
          return await this.openRecord(args, who, "view");
        case "open_update_form":
          return await this.openRecord(args, who, "update");
        case "request_approval":
          return await this.openRecord(args, who, "transition");
        case "open_create_form":
          return await this.openCreateForm(args, who);
        case "search_reports":
          return await this.searchReports(args, who);
        case "run_approved_report":
          return await this.runReport(args, who);
        default:
          throw new ToolRefusal(404, "UNKNOWN_TOOL", `There is no business tool called ${operation}.`);
      }
    } catch (error) {
      if (error instanceof ApplicationError) {
        if (error.status === 401) {
          throw new ToolRefusal(401, "SESSION_ENDED", "The person's application session has ended; they need to sign in to the chat again.");
        }
        throw new ToolRefusal(error.status, error.code, error.message);
      }
      throw error;
    }
  }

  // ── entities ────────────────────────────────────────────────────────────────

  private async entities(who: SessionCredentials): Promise<EntityEntry[]> {
    const cached = this.entityCache.get(who.sessionId);
    if (cached && Date.now() - cached.at < ENTITY_CACHE_MS) return cached.entities;
    const { entities } = await this.application.dashboard(who.appToken);
    this.entityCache.set(who.sessionId, { at: Date.now(), entities });
    return entities;
  }

  private async meta(who: SessionCredentials, table: string): Promise<EntityMeta> {
    const key = `${who.sessionId}:${table}`;
    const cached = this.metaCache.get(key);
    if (cached && Date.now() - cached.at < ENTITY_CACHE_MS) return cached.meta;
    const meta = await this.application.meta(who.appToken, table);
    this.metaCache.set(key, { at: Date.now(), meta });
    return meta;
  }

  /** Find an entity by its window name, its table or its bare name, case and spacing aside. */
  private async resolveEntity(who: SessionCredentials, name: unknown): Promise<EntityEntry> {
    if (typeof name !== "string" || !name.trim()) throw new ToolRefusal(400, "ENTITY_REQUIRED", "Name the entity to search.");
    const wanted = name.trim().toLowerCase().replace(/[\s_-]+/g, "");
    const entities = await this.entities(who);
    const match = entities.find((entity) =>
      [entity.windowName, entity.table, entity.table.replace(/^bus_/, "")].some(
        (candidate) => candidate.toLowerCase().replace(/[\s_-]+/g, "") === wanted
      )
    );
    if (!match) {
      throw new ToolRefusal(
        404,
        "ENTITY_NOT_AVAILABLE",
        `"${name}" is not an entity this person can see. They can see: ${entities.map((e) => e.windowName).join(", ") || "none"}.`
      );
    }
    return match;
  }

  private target(who: SessionCredentials, ref: unknown): RecordTarget {
    const target = typeof ref === "string" ? openRecordRef(this.refKey, who.userId, ref) : null;
    if (!target) {
      throw new ToolRefusal(400, "INVALID_REF", "That is not a record reference issued to this person. Search for the record first.");
    }
    return target;
  }

  private label(meta: EntityMeta, row: Json, fallback: string): string {
    const parts = meta.columns
      .filter((column) => column.is_identifier)
      .map((column) => row[column.column_name])
      .filter((value) => value !== null && value !== undefined && value !== "")
      .map(String);
    return parts.length > 0 ? parts.join(" · ") : fallback;
  }

  /** The row as the model may see it: values by column label, no ids, no raw references. */
  private fields(meta: EntityMeta, row: Json): Json {
    const out: Json = {};
    for (const column of meta.columns) {
      const name = column.column_name;
      if (column.is_key || HIDDEN_COLUMNS.has(name) || name.endsWith("_id")) continue;
      if (!(name in row)) continue;
      out[column.name || name] = row[name] ?? null;
    }
    return out;
  }

  private status(meta: EntityMeta, row: Json, reported: TransactionStatus | null): TransactionStatus | null {
    if (reported) return reported;
    if (!meta.lifecycle) return null;
    const value = row[meta.lifecycle.statusField];
    if (typeof value !== "string") return null;
    return {
      field: meta.lifecycle.statusField,
      value,
      label: humanise(value),
      isFinal: meta.lifecycle.finals.includes(value),
    };
  }

  // ── reads ───────────────────────────────────────────────────────────────────

  private async searchRecords(args: Json, who: SessionCredentials) {
    const entity = await this.resolveEntity(who, args.entity);
    const meta = await this.meta(who, entity.table);
    const page = Number.isInteger(args.page) && (args.page as number) > 0 ? (args.page as number) : 1;
    const pageSize = Number.isInteger(args.pageSize) ? Math.min(50, Math.max(1, args.pageSize as number)) : 20;
    const filters = args.filters && typeof args.filters === "object" ? (args.filters as Json) : undefined;
    const { rows, total } = await this.application.search(who.appToken, entity.table, {
      text: typeof args.text === "string" ? args.text : undefined,
      filters,
      page,
      pageSize,
    });
    return {
      entity: entity.table.replace(/^bus_/, ""),
      label: entity.windowName,
      total,
      page,
      rows: rows.map((row) => ({
        ref: sealRecordRef(this.refKey, who.userId, { table: entity.table, id: String(row.id) }),
        label: this.label(meta, row, entity.windowName),
        fields: this.fields(meta, row),
        status: this.status(meta, row, null),
      })),
    };
  }

  private async recordSummary(args: Json, who: SessionCredentials) {
    const target = this.target(who, args.ref);
    const entities = await this.entities(who);
    const entity = entities.find((e) => e.table === target.table);
    if (!entity) throw new ToolRefusal(403, "FORBIDDEN", "This person can no longer see records of that kind.");
    const meta = await this.meta(who, target.table);
    const { row, status: reported } = await this.application.read(who.appToken, target.table, target.id);
    const status = this.status(meta, row, reported);
    const transitions =
      status && !status.isFinal
        ? (await this.application.transitions(who.appToken, target.table, status.value)).map((edge) => ({
            to: edge.to,
            label: edge.label === edge.to ? humanise(edge.to) : edge.label,
          }))
        : [];
    return {
      ref: String(args.ref),
      entity: entity.windowName,
      label: this.label(meta, row, entity.windowName),
      fields: this.fields(meta, row),
      status,
      transitions,
    };
  }

  // ── opens ───────────────────────────────────────────────────────────────────

  private async mintView(
    who: SessionCredentials,
    kind: "business-application" | "enterprise-report",
    target: Json,
    operation: string,
    title: string
  ): Promise<{ id: string; expiresAt: Date }> {
    const id = `v_${randomToken(18)}`;
    const expiresAt = new Date(Date.now() + this.config.viewTtlSeconds * 1000);
    await this.db
      .insertInto("app_views")
      .values({ id, user_id: who.userId, kind, target: JSON.stringify(target), operation, title, expires_at: expiresAt })
      .execute();
    return { id, expiresAt };
  }

  private async openRecord(args: Json, who: SessionCredentials, operation: "view" | "update" | "transition"): Promise<ViewDescriptor> {
    const target = this.target(who, args.ref);
    const entity = (await this.entities(who)).find((e) => e.table === target.table);
    if (!entity) throw new ToolRefusal(403, "FORBIDDEN", "This person can no longer see records of that kind.");
    if (!entity.route) {
      throw new ToolRefusal(409, "NO_SCREEN", `${entity.windowName} records are opened from their parent record.`);
    }
    const meta = await this.meta(who, target.table);
    // Read it now: an id the person cannot read must not become a view.
    const { row, status: reported } = await this.application.read(who.appToken, target.table, target.id);
    const status = this.status(meta, row, reported);
    const label = this.label(meta, row, entity.windowName);

    const query = new URLSearchParams({ embed: "1" });
    if (operation === "update") {
      if (status?.isFinal) {
        throw new ToolRefusal(409, "RECORD_FINAL", `${label} is ${status.label}, a final state: the transaction is complete and cannot be changed.`);
      }
      query.set("edit", "1");
    }
    if (operation === "transition") {
      const to = typeof args.transition === "string" ? args.transition : "";
      if (!status) throw new ToolRefusal(409, "NO_WORKFLOW", `${entity.windowName} records have no workflow.`);
      if (status.isFinal) {
        throw new ToolRefusal(409, "RECORD_FINAL", `${label} is ${status.label}, a final state: it has no further moves.`);
      }
      const moves = await this.application.transitions(who.appToken, target.table, status.value);
      if (!moves.some((move) => move.to === to)) {
        throw new ToolRefusal(
          400,
          "NO_SUCH_MOVE",
          `${label} cannot move from ${status.label} to "${to}". The moves from here are: ${moves.map((m) => m.to).join(", ") || "none"}.`
        );
      }
      query.set("transition", to);
    }
    const title = `${entity.windowName}: ${label}`;
    const view = await this.mintView(
      who,
      "business-application",
      { path: `${entity.route}/${encodeURIComponent(target.id)}?${query}` },
      operation,
      title
    );
    return {
      type: "business-application",
      applicationViewId: view.id,
      title,
      operation,
      entity: entity.windowName,
      expiresAt: view.expiresAt.toISOString(),
    };
  }

  private async openCreateForm(args: Json, who: SessionCredentials): Promise<ViewDescriptor> {
    const entity = await this.resolveEntity(who, args.entity);
    if (!entity.route) {
      throw new ToolRefusal(409, "NO_SCREEN", `${entity.windowName} records are created from their parent record.`);
    }
    const title = `New ${entity.windowName}`;
    const view = await this.mintView(who, "business-application", { path: `${entity.route}/new?embed=1` }, "create", title);
    return {
      type: "business-application",
      applicationViewId: view.id,
      title,
      operation: "create",
      entity: entity.windowName,
      expiresAt: view.expiresAt.toISOString(),
    };
  }

  // ── reports ─────────────────────────────────────────────────────────────────

  private reportSession(who: SessionCredentials): { reporting: ReportingClient; session: string } {
    if (!this.reporting) throw new ToolRefusal(503, "REPORTING_NOT_CONFIGURED", "This application has no reporting platform.");
    if (!who.reportSession) {
      throw new ToolRefusal(503, "REPORTING_UNAVAILABLE", "The reporting platform did not sign this person in; reports are unavailable for this session.");
    }
    return { reporting: this.reporting, session: who.reportSession };
  }

  private async searchReports(args: Json, who: SessionCredentials) {
    const { reporting, session } = this.reportSession(who);
    const words = typeof args.text === "string" ? args.text.toLowerCase().split(/\s+/).filter(Boolean) : [];
    const candidates = [];
    // The platform's list is not narrowed by permission, so narrow by text
    // first and then keep only what this person can actually run.
    for (let page = 0; page < 20 && candidates.length < 60; page++) {
      const { items, total } = await reporting.listReports(session, page, 100);
      for (const item of items) {
        const haystack = `${item.name} ${item.description}`.toLowerCase();
        if (words.every((word) => haystack.includes(word))) candidates.push(item);
      }
      if ((page + 1) * 100 >= total || items.length === 0) break;
    }
    const runnable = [];
    for (const report of candidates.slice(0, 20)) {
      try {
        await reporting.run(session, report.id, 0, 1);
        runnable.push({ reportId: report.id, title: report.name, description: report.description });
      } catch (error) {
        if (!(error instanceof ApplicationError) || error.status !== 403) throw error;
      }
    }
    return { reports: runnable };
  }

  private async runReport(args: Json, who: SessionCredentials) {
    const { reporting, session } = this.reportSession(who);
    const reportId = typeof args.reportId === "string" ? args.reportId : "";
    if (!reportId) throw new ToolRefusal(400, "REPORT_REQUIRED", "Name the report to run, by the id search_reports gave.");
    const report = await reporting.report(session, reportId);
    const first = await reporting.run(session, reportId, 0, 20);
    const columns = Object.keys(first.rows[0] ?? {});
    const chartId = report.savedQueryId ? await reporting.chartFor(session, report.savedQueryId) : null;
    const view = await this.mintView(
      who,
      "enterprise-report",
      { reportId, chartId, params: args.params && typeof args.params === "object" ? args.params : {} },
      "report",
      report.name
    );
    return {
      type: "enterprise-report" as const,
      reportViewId: view.id,
      title: report.name,
      columns,
      rowCount: first.totalRows,
      preview: first.rows,
      hasChart: chartId !== null,
      expiresAt: view.expiresAt.toISOString(),
    };
  }
}

