/**
 * The gateway's security properties, against a running gateway and the
 * application it serves — nothing is stubbed.
 *
 *   CHAT_TEST_GATEWAY=http://localhost:3100/chat \
 *   CHAT_TEST_INTERNAL=http://127.0.0.1:3101 \
 *   CHAT_TEST_DATABASE_URL=postgres://…/crm_development \
 *   CHAT_TEST_PASSWORD=admin \
 *   bun test tests/security
 *
 * Two people sign in: the administrator and a second account; the second may
 * not open the first's views. Every other suite drives the chat as one
 * person, so ownership is checked nowhere else.
 */

import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import pg from "pg";

const GATEWAY = process.env.CHAT_TEST_GATEWAY ?? "http://localhost:3100/chat";
const INTERNAL = process.env.CHAT_TEST_INTERNAL ?? "http://127.0.0.1:3101";
const DATABASE = process.env.CHAT_TEST_DATABASE_URL ?? "postgres://postgres:qapass@localhost:5432/crm_development";
const SCHEMA = process.env.CHAT_TEST_SCHEMA ?? "chat";
const PASSWORD = process.env.CHAT_TEST_PASSWORD ?? "admin";
const FIRST = process.env.CHAT_TEST_FIRST ?? "admin@admin.com";
const SECOND = process.env.CHAT_TEST_SECOND ?? "sales.rep@crm.example.com";

const pool = new pg.Pool({ connectionString: DATABASE });

/** Cookies as a browser would hold them for the chat's path. */
async function signIn(email: string, password = PASSWORD): Promise<{ status: number; cookie: string }> {
  const response = await fetch(`${GATEWAY}/_/auth/sign-in/application`, {
    method: "POST",
    headers: { "content-type": "application/json", origin: new URL(GATEWAY).origin },
    body: JSON.stringify({ email, password }),
  });
  const cookie = response.headers
    .getSetCookie()
    .map((header) => header.split(";")[0])
    .filter((pair) => pair?.startsWith("chat."))
    .join("; ");
  return { status: response.status, cookie };
}

async function userId(email: string): Promise<string> {
  const { rows } = await pool.query(`SELECT id FROM ${SCHEMA}."user" WHERE email = $1`, [email]);
  if (!rows[0]) throw new Error(`no chat user for ${email}`);
  return rows[0].id as string;
}

async function mintView(owner: string, expiresInSeconds: number): Promise<string> {
  const id = `v_test${crypto.randomUUID().replace(/-/g, "")}`;
  await pool.query(
    `INSERT INTO ${SCHEMA}.app_views (id, user_id, kind, target, operation, title, expires_at)
     VALUES ($1, $2, 'business-application', $3, 'create', 'Test view', now() + make_interval(secs => $4))`,
    [id, owner, JSON.stringify({ path: "/account/new?embed=1" }), expiresInSeconds]
  );
  return id;
}

let first = "";
let second = "";

beforeAll(async () => {
  const a = await signIn(FIRST);
  const b = await signIn(SECOND);
  expect(a.status).toBe(200);
  expect(b.status).toBe(200);
  first = a.cookie;
  second = b.cookie;
});

afterAll(async () => {
  await pool.query(`DELETE FROM ${SCHEMA}.app_views WHERE id LIKE 'v_test%'`);
  await pool.end();
});

describe("without a chat session", () => {
  it("the chat sends you to sign in", async () => {
    const response = await fetch(`${GATEWAY}/`, { redirect: "manual" });
    expect(response.status).toBe(303);
    expect(response.headers.get("location")).toEndWith("/_/sign-in");
  });

  it("no Harness API is reachable", async () => {
    const response = await fetch(`${GATEWAY}/api/session/list`, { method: "POST", body: "{}" });
    expect(response.status).toBe(401);
  });

  it("no view opens", async () => {
    const response = await fetch(`${GATEWAY}/_/views/v_abcdefghijklmnop/open`, { redirect: "manual" });
    expect(response.status).toBe(401);
  });

  it("a wrong password is refused, in words", async () => {
    const response = await fetch(`${GATEWAY}/_/auth/sign-in/application`, {
      method: "POST",
      headers: { "content-type": "application/json", origin: new URL(GATEWAY).origin },
      body: JSON.stringify({ email: FIRST, password: "not-the-password" }),
    });
    expect(response.status).toBe(401);
    const body = (await response.json()) as { message?: string };
    expect(body.message).toContain("not accepted");
  });
});

describe("signed in, the machine stays out of reach", () => {
  const signedIn = (path: string, init: RequestInit = {}) =>
    fetch(`${GATEWAY}${path}`, { ...init, headers: { cookie: first, "content-type": "application/json", ...(init.headers ?? {}) } });

  it("the route that reads any file on the host is refused", async () => {
    const response = await signedIn("/api/file?path=/etc/passwd");
    expect(response.status).toBe(403);
    expect(await response.text()).not.toContain("root:");
  });

  it("a directory cannot be made a workspace", async () => {
    const response = await signedIn("/api/workspace/create", {
      method: "POST",
      body: JSON.stringify({ type: "client-request", rpcId: "x", method: "workspace/create", payload: { args: { request: { path: "/etc" } } } }),
    });
    expect(response.status).toBe(403);
  });

  it("namespaces the chat does not use are refused", async () => {
    for (const path of ["/api/terminal/open", "/api/directoryPicker/list", "/api/pluginManager/install"]) {
      expect((await signedIn(path, { method: "POST", body: "{}" })).status).toBe(403);
    }
  });
});

describe("the WebSocket mux holds the same allowlist as the HTTP routes", () => {
  /** Open one stream over `/api/remote.mux` as the first person and return the first frame back. */
  async function openStream(endpoint: string): Promise<{ type?: string; error?: { code?: string } }> {
    const url = `${GATEWAY.replace(/^http/, "ws")}/api/remote.mux`;
    const socket = new WebSocket(url, { headers: { cookie: first, origin: new URL(GATEWAY).origin } } as unknown as string[]);
    try {
      await new Promise<void>((resolve, reject) => {
        socket.onopen = () => resolve();
        socket.onerror = () => reject(new Error("socket failed"));
      });
      const streamId = crypto.randomUUID();
      const answer = new Promise<string>((resolve) => {
        socket.onmessage = (event) => {
          const frame = JSON.parse(String(event.data));
          if (frame.streamId === streamId) resolve(String(event.data));
        };
      });
      socket.send(JSON.stringify({ type: "open", streamId, endpoint, payload: { args: {} } }));
      return JSON.parse(await Promise.race([answer, Bun.sleep(10_000).then(() => "{}")]));
    } finally {
      socket.close();
    }
  }

  it("refuses to open a stream on an endpoint the chat does not use", async () => {
    for (const endpoint of ["terminal/open", "workspace/create", "settings/mutate"]) {
      const frame = await openStream(endpoint);
      expect(frame.type, endpoint).toBe("error");
      expect(frame.error?.code, endpoint).toBe("FORBIDDEN");
    }
  });

  it("opens the streams the chat does use", async () => {
    const frame = await openStream("workspace/follow");
    expect(frame.type).toBe("item");
  });
});

describe("settings can be read and never written", () => {
  const rpc = (method: string) =>
    fetch(`${GATEWAY}/api/${method}`, {
      method: "POST",
      headers: { cookie: first, "content-type": "application/json" },
      body: JSON.stringify({ type: "client-request", rpcId: "s", method, payload: { args: {} } }),
    });

  it("answers a read", async () => {
    expect((await rpc("settings/describe")).status).toBe(200);
  });

  it("refuses every write: one could repoint the model endpoint the server's key is sent to", async () => {
    for (const method of ["settings/mutate", "settings/update", "settings/replace"]) {
      expect((await rpc(method)).status, method).toBe(403);
    }
  });
});

describe("the internal tool API", () => {
  it("refuses a call without a host secret", async () => {
    const response = await fetch(`${INTERNAL}/internal/tools/search_records`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ entity: "Account" }),
    });
    expect(response.status).toBe(401);
  });

  it("refuses a forged host secret", async () => {
    const response = await fetch(`${INTERNAL}/internal/tools/search_records`, {
      method: "POST",
      headers: { "content-type": "application/json", "x-chat-host-secret": "forged-secret-value" },
      body: JSON.stringify({ entity: "Account" }),
    });
    expect(response.status).toBe(401);
  });
});

describe("view ids belong to one person", () => {
  it("open for their owner", async () => {
    const id = await mintView(await userId(FIRST), 600);
    const response = await fetch(`${GATEWAY}/_/views/${id}/open`, { headers: { cookie: first }, redirect: "manual" });
    expect(response.status).toBe(303);
    expect(response.headers.get("location")).toContain("/account/new?embed=1");
  });

  it("are not found for anyone else", async () => {
    const id = await mintView(await userId(FIRST), 600);
    const response = await fetch(`${GATEWAY}/_/views/${id}/open`, { headers: { cookie: second }, redirect: "manual" });
    expect(response.status).toBe(404);
  });

  it("say so when they have expired", async () => {
    const id = await mintView(await userId(FIRST), -1);
    const response = await fetch(`${GATEWAY}/_/views/${id}/open`, { headers: { cookie: first }, redirect: "manual" });
    expect(response.status).toBe(410);
  });
});

describe("sign-out", () => {
  it("ends the chat session", async () => {
    const { cookie } = await signIn(SECOND);
    const out = await fetch(`${GATEWAY}/_/sign-out`, { method: "POST", headers: { cookie, origin: new URL(GATEWAY).origin }, redirect: "manual" });
    expect(out.status).toBe(303);
    const after = await fetch(`${GATEWAY}/api/session/list`, { method: "POST", headers: { cookie }, body: "{}" });
    expect(after.status).toBe(401);
  });
});

describe("sign-in is rate limited", () => {
  it("refuses a burst of attempts from one address", async () => {
    const statuses: number[] = [];
    for (let i = 0; i < 8; i++) statuses.push((await signIn(FIRST, "wrong-password")).status);
    expect(statuses).toContain(429);
  });
});

/chat-deepseek/tests/security/reporting-:
/**
 * The reporting platform's half of the single sign-on, against a running
 * platform backend and its database — the assertions are minted by the
 * gateway's own `signAssertion`, so a disagreement between the two halves
 * fails here rather than at somebody's first sign-in.
 *
 *   CHAT_TEST_REPORT_API=http://localhost:5150/api \
 *   CHAT_TEST_REPORT_DATABASE_URL=postgres://…/report_config \
 *   SSO_SIGNING_KEY="$(cat sso.key)" \
 *   bun test tests/security/reporting-assertion.test.ts
 *
 * The platform must have been seeded with the application's reporting pack:
 * role sync is checked against the roles that pack created.
 */

import { generateKeyPairSync, randomUUID, sign } from "node:crypto";
import { afterAll, describe, expect, it } from "bun:test";
import pg from "pg";
import { signAssertion } from "../../gateway/crypto";

const API = process.env.CHAT_TEST_REPORT_API ?? "http://localhost:5150/api";
const DATABASE = process.env.CHAT_TEST_REPORT_DATABASE_URL ?? "postgres://postgres:qapass@localhost:5432/report_chat_e2e";
const SIGNING_KEY = process.env.SSO_SIGNING_KEY ?? "";

const pool = new pg.Pool({ connectionString: DATABASE });
const run = `${Date.now().toString(36)}`;
const person = (who: string) => `${who}.${run}@crm.example.com`;

async function present(assertion: string): Promise<{ status: number; cookie: string | null; body: Record<string, unknown> }> {
  const response = await fetch(`${API}/auth/assertion`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ assertion }),
  });
  return {
    status: response.status,
    cookie: response.headers.get("set-cookie")?.split(";")[0] ?? null,
    body: (await response.json().catch(() => ({}))) as Record<string, unknown>,
  };
}

async function rolesOf(email: string): Promise<{ system: string[]; data: string[] }> {
  const system = await pool.query(
    `SELECT r.name FROM users u JOIN user_roles ur ON ur.user_id = u.id JOIN roles r ON r.id = ur.role_id
      WHERE u.email = $1 ORDER BY r.name`,
    [email]
  );
  const data = await pool.query(
    `SELECT DISTINCT d.name FROM users u JOIN ds_user_roles du ON du.user_id = u.id JOIN ds_roles d ON d.id = du.ds_role_id
      WHERE u.email = $1 ORDER BY d.name`,
    [email]
  );
  return { system: system.rows.map((r) => r.name), data: data.rows.map((r) => r.name) };
}

afterAll(async () => {
  await pool.query(
    `DELETE FROM users WHERE email LIKE $1`,
    [`%.${run}@crm.example.com`]
  );
  await pool.end();
});

describe("a valid assertion", () => {
  it("is required to be configured", () => {
    expect(SIGNING_KEY).toContain("PRIVATE KEY");
  });

  it("opens a session and creates the person, with the roles it names", async () => {
    const email = person("sales.rep");
    const answer = await present(signAssertion(SIGNING_KEY, { email, name: "Sales Rep", roles: ["Sales Rep"], master: false }));
    expect(answer.status).toBe(200);
    expect(answer.cookie).toMatch(/^ers\.session_token=/);
    expect((answer.body.user as { email: string }).email).toBe(email);

    const session = await fetch(`${API}/auth/get-session`, { headers: { cookie: answer.cookie ?? "" } });
    expect(session.status).toBe(200);
    expect(((await session.json()) as { user?: { email: string } }).user?.email).toBe(email);

    const roles = await rolesOf(email);
    expect(roles.system).toEqual(["Sales Rep"]);
    expect(roles.data).toEqual(["Sales Rep"]);
  });

  it("re-syncs roles on the next sign-in: one removed in the application is removed here", async () => {
    const email = person("moving");
    expect((await present(signAssertion(SIGNING_KEY, { email, name: "Moving", roles: ["sales_rep", "support_agent"], master: false }))).status).toBe(200);
    expect((await rolesOf(email)).system).toEqual(["Sales Rep", "Support Agent"]);
    expect((await present(signAssertion(SIGNING_KEY, { email, name: "Moving", roles: ["support_agent"], master: false }))).status).toBe(200);
    expect(await rolesOf(email)).toEqual({ system: ["Support Agent"], data: ["Support Agent"] });
  });

  it("maps the application's master role to this platform's administrator", async () => {
    const email = person("owner");
    expect((await present(signAssertion(SIGNING_KEY, { email, name: "Owner", roles: ["Administrator"], master: true }))).status).toBe(200);
    expect((await rolesOf(email)).system).toContain("Administrator");
  });

  it("gives a role the pack never created nothing to read", async () => {
    const email = person("stranger");
    expect((await present(signAssertion(SIGNING_KEY, { email, name: "Stranger", roles: ["Night Porter"], master: false }))).status).toBe(200);
    expect(await rolesOf(email)).toEqual({ system: [], data: [] });
  });

  it("creates an account with no password: an assertion is the only way in", async () => {
    const email = person("passwordless");
    expect((await present(signAssertion(SIGNING_KEY, { email, name: "P", roles: [], master: false }))).status).toBe(200);
    const credential = await pool.query(
      `SELECT a.provider_id, a.password FROM auth_accounts a JOIN users u ON u.id = a.user_id WHERE u.email = $1`,
      [email]
    );
    expect(credential.rows).toEqual([{ provider_id: "appwithai-chat", password: null }]);
  });
});

describe("an assertion is refused", () => {
  it("the second time it is presented", async () => {
    const assertion = signAssertion(SIGNING_KEY, { email: person("replay"), name: "R", roles: [], master: false });
    expect((await present(assertion)).status).toBe(200);
    const second = await present(assertion);
    expect(second.status).toBe(401);
    expect(second.cookie).toBeNull();
  });

  it("when another key signed it", async () => {
    const { privateKey } = generateKeyPairSync("ed25519");
    const forged = signAssertion(privateKey.export({ type: "pkcs8", format: "pem" }).toString(), {
      email: person("forged"),
      name: "F",
      roles: [],
      master: true,
    });
    expect((await present(forged)).status).toBe(401);
  });

  it("when its payload was edited after signing", async () => {
    const token = signAssertion(SIGNING_KEY, { email: person("edited"), name: "E", roles: ["Sales Rep"], master: false });
    const [encoded, signature] = token.split(".");
    const payload = JSON.parse(Buffer.from(encoded ?? "", "base64url").toString("utf8"));
    payload.master = true;
    const edited = `${Buffer.from(JSON.stringify(payload)).toString("base64url")}.${signature}`;
    expect((await present(edited)).status).toBe(401);
  });

  it("when it has expired, or was minted for another audience", async () => {
    const past = Date.now() - 10 * 60_000;
    expect((await present(signAssertion(SIGNING_KEY, { email: person("late"), name: "L", roles: [], master: false }, past))).status).toBe(401);

    const now = Math.floor(Date.now() / 1000);
    const payload = { iss: "appwithai-chat", aud: "app", sub: person("aud"), name: "A", roles: [], master: false, jti: randomUUID(), iat: now, exp: now + 60 };
    const encoded = Buffer.from(JSON.stringify(payload)).toString("base64url");
    const signature = sign(null, Buffer.from(encoded), SIGNING_KEY).toString("base64url");
    expect((await present(`${encoded}.${signature}`)).status).toBe(401);
  });

  it("for a deactivated account, whoever vouches for it", async () => {
    const email = person("deactivated");
    expect((await present(signAssertion(SIGNING_KEY, { email, name: "D", roles: [], master: false }))).status).toBe(200);
    await pool.query("UPDATE users SET is_active = FALSE WHERE email = $1", [email]);
    expect((await present(signAssertion(SIGNING_KEY, { email, name: "D", roles: [], master: false }))).status).toBe(401);
  });
});

/chat-deepseek/tests/support/messages-re:
/**
 * A Messages-protocol endpoint that records what the Harness sends the model.
 *
 * It stands where `DEEPSEEK_BASE_URL` points during a test, and exists for two
 * questions only a real request can answer:
 *
 * - **Which tools does the agent actually receive?** The composition gate reads
 *   the `tools` array of the request the host built — not the configuration that
 *   was supposed to produce it.
 * - **What does a host cost in memory while it works?** The load test needs
 *   hosts that run real turns, real tool calls through the gateway and real
 *   session writes; only the model's words are scripted, because 200 people's
 *   conversations cannot be bought from a provider to measure a process.
 *
 * Every reply is a protocol-correct streamed Messages response. A script may
 * ask for one `tool_use` per turn before the closing text, so a turn exercises
 * the tool path end to end.
 */

export interface RecordedRequest {
  path: string;
  model: string | undefined;
  toolNames: string[];
  system: string;
  messageCount: number;
  /** Text of every `tool_result` block in the last message: what the tools answered. */
  toolResults: string[];
  /** What the person last wrote: the latest user message that is not a tool result. */
  userText: string;
  /** Every tool result since that message, in order: this turn's steps so far. */
  turnResults: string[];
  receivedAt: number;
}

export interface RecorderScript {
  /**
   * The tool call to make on this model step, or `null` to close the turn with
   * text. Asked on every step: `turnResults` says how far the turn has got, so
   * a script can search first and then open what the search found — and must
   * return `null` once it has what it wanted, or the turn never ends.
   */
  toolCall?: (request: RecordedRequest) => { name: string; input: Record<string, unknown> } | null;
  /** The closing text of a turn. */
  text?: (request: RecordedRequest) => string;
}

export interface MessagesRecorder {
  url: string;
  requests: RecordedRequest[];
  stop(): void;
}

type Json = Record<string, unknown>;

function sse(events: Array<[string, Json]>): string {
  return events.map(([event, data]) => `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`).join("");
}

function systemText(system: unknown): string {
  if (typeof system === "string") return system;
  if (Array.isArray(system)) {
    return system
      .map((block) => (block && typeof block === "object" && "text" in block ? String(block.text) : ""))
      .join("\n");
  }
  return "";
}

function resultTexts(message: Json | undefined): string[] {
  if (!message || !Array.isArray(message.content)) return [];
  return (message.content as Json[])
    .filter((block) => block?.type === "tool_result")
    .map((block) => {
      const content = block.content;
      if (typeof content === "string") return content;
      if (Array.isArray(content)) return (content as Json[]).map((part) => String(part.text ?? "")).join("");
      return "";
    });
}

/** The person's latest words, and every tool result after them. */
function currentTurn(messages: unknown): { userText: string; turnResults: string[] } {
  if (!Array.isArray(messages)) return { userText: "", turnResults: [] };
  const turnResults: string[] = [];
  for (let index = messages.length - 1; index >= 0; index--) {
    const message = messages[index] as Json;
    if (message?.role !== "user") continue;
    const results = resultTexts(message);
    if (results.length > 0) {
      turnResults.unshift(...results);
      continue;
    }
    const content = message.content;
    const userText =
      typeof content === "string"
        ? content
        : Array.isArray(content)
          ? (content as Json[]).map((block) => (block?.type === "text" ? String(block.text ?? "") : "")).join("\n")
          : "";
    return { userText, turnResults };
  }
  return { userText: "", turnResults };
}

function lastToolResults(messages: unknown): string[] {
  if (!Array.isArray(messages) || messages.length === 0) return [];
  const last = messages[messages.length - 1] as Json;
  if (!Array.isArray(last?.content)) return [];
  return (last.content as Json[])
    .filter((block) => block?.type === "tool_result")
    .map((block) => {
      const content = block.content;
      if (typeof content === "string") return content;
      if (Array.isArray(content)) return (content as Json[]).map((part) => String(part.text ?? "")).join("");
      return "";
    });
}

export function startMessagesRecorder(port = 0, script: RecorderScript = {}): MessagesRecorder {
  const requests: RecordedRequest[] = [];
  let sequence = 0;

  const server = Bun.serve({
    port,
    hostname: "127.0.0.1",
    async fetch(request) {
      const url = new URL(request.url);
      if (request.method !== "POST" || !url.pathname.endsWith("/messages")) {
        return Response.json({ type: "error", error: { type: "not_found_error", message: url.pathname } }, { status: 404 });
      }
      const body = (await request.json()) as Json;
      const recorded: RecordedRequest = {
        path: url.pathname,
        model: typeof body.model === "string" ? body.model : undefined,
        toolNames: Array.isArray(body.tools)
          ? (body.tools as Json[]).map((tool) => String(tool.name)).sort()
          : [],
        system: systemText(body.system),
        messageCount: Array.isArray(body.messages) ? body.messages.length : 0,
        toolResults: lastToolResults(body.messages),
        ...currentTurn(body.messages),
        receivedAt: Date.now(),
      };
      requests.push(recorded);

      const id = `msg_recorded_${++sequence}`;
      const call = script.toolCall?.(recorded) ?? null;
      const content: Json[] = call
        ? [{ type: "tool_use", id: `toolu_recorded_${sequence}`, name: call.name, input: call.input }]
        : [{ type: "text", text: script.text?.(recorded) ?? "Recorded." }];
      const stopReason = call ? "tool_use" : "end_turn";
      const usage = { input_tokens: 1, output_tokens: 1 };

      if (body.stream !== true) {
        return Response.json({
          id,
          type: "message",
          role: "assistant",
          model: recorded.model ?? "recorded",
          content,
          stop_reason: stopReason,
          stop_sequence: null,
          usage,
        });
      }

      const events: Array<[string, Json]> = [
        [
          "message_start",
          {
            type: "message_start",
            message: {
              id,
              type: "message",
              role: "assistant",
              model: recorded.model ?? "recorded",
              content: [],
              stop_reason: null,
              stop_sequence: null,
              usage,
            },
          },
        ],
      ];
      content.forEach((block, index) => {
        if (block.type === "tool_use") {
          events.push([
            "content_block_start",
            { type: "content_block_start", index, content_block: { ...block, input: {} } },
          ]);
          events.push([
            "content_block_delta",
            {
              type: "content_block_delta",
              index,
              delta: { type: "input_json_delta", partial_json: JSON.stringify(block.input) },
            },
          ]);
        } else {
          events.push([
            "content_block_start",
            { type: "content_block_start", index, content_block: { type: "text", text: "" } },
          ]);
          events.push([
            "content_block_delta",
            { type: "content_block_delta", index, delta: { type: "text_delta", text: block.text } },
          ]);
        }
        events.push(["content_block_stop", { type: "content_block_stop", index }]);
      });
      events.push([
        "message_delta",
        { type: "message_delta", delta: { stop_reason: stopReason, stop_sequence: null }, usage },
      ]);
      events.push(["message_stop", { type: "message_stop" }]);

      return new Response(sse(events), {
        headers: { "content-type": "text/event-stream", "cache-control": "no-cache" },
      });
    },
  });

  return {
    url: `http://127.0.0.1:${server.port}`,
    requests,
    stop: () => server.stop(true),
  };
}

