schema:
  name: CEDM Entity Schema
  version: 0.4.0

help:
  required: [summary, businessMeaning, usage, relationshipContext]
  properties:
    summary: {type: string, minLength: 20}
    businessMeaning: {type: string, minLength: 30}
    usage: {type: string, minLength: 30}
    relationshipContext: {type: string, minLength: 30}
    lifecycle: {type: string}
    example: {type: string}
    valueSemantics: {type: object}
    valueLabels: {type: object, description: One short label per enumerated value}
    requiredMeaning: {type: string}
    optionalMeaning: {type: string}

entity:
  required: [name, namespace, identity, attributes, help]
  properties:
    name: {type: string, pattern: '^[A-Z][A-Za-z0-9]*$'}
    namespace: {type: string}
    kind: {type: string}
    description: {type: string}
    help:
      required: [summary, businessMeaning, usage, relationshipContext]
      properties:
        summary: {type: string}
        businessMeaning: {type: string}
        usage: {type: string}
        relationshipContext: {type: string}
        lifecycle: {type: string}
        example: {type: string}
    ui:
      description: How the entity is presented. Every slot has a derivation rule in specification/dictionary-mapping.yaml; only icon is required.
      required: [icon]
      properties:
        icon: {type: string, description: A lucide 0.312 icon id (tools/lucide-icons.txt)}
        label: {type: string, description: Window title; derived from the name when absent}
        group: {type: string, description: One of the field groups in dictionary-mapping.yaml}
        recordLabel: {type: array, description: Attributes that identify one record; derived when absent}
        highVolume: {type: boolean}
    extends: {type: string}
    identity:
      required: [key, type]
      properties:
        key: {type: string}
        type: {type: string}
        generated: {type: boolean}
        immutable: {type: boolean}
    attributes:
      type: array
      itemRequired: [name, type, required, help]
      itemProperties:
        help:
          required: [summary, usage, relationshipContext]
          properties:
            summary: {type: string}
            usage: {type: string}
            relationshipContext: {type: string}
            valueSemantics: {type: object}
            requiredMeaning: {type: string}
            optionalMeaning: {type: string}
    relationships:
      type: array
      itemRequired: [name, target, cardinality, help]
      itemProperties:
        help:
          required: [summary, usage, cardinalityMeaning, context]
          properties:
            summary: {type: string}
            usage: {type: string}
            cardinalityMeaning: {type: string}
            context: {type: string}
    invariants:
      type: array
      itemRequired: [id, rule]
    lifecycle: {type: object}
    audit: {type: object}

relationship:
  cardinalities: ['0..1', '1', '0..*', '1..*']
